def _configure_stdio_utf8():
    """Best-effort UTF-8 console output on Windows source runs."""
    for name in ("stdout", "stderr"):
        stream = getattr(sys, name, None)
        if hasattr(stream, "reconfigure"):
            try:
                stream.reconfigure(encoding="utf-8", errors="replace")
            except Exception:
                pass


_configure_stdio_utf8()


_YK_INSTANCE_LOCK_HANDLE = None


def _yk_instance_lock_file(port):
    safe_port = int(port) if str(port).isdigit() else 5443
    lock_dir = Path(tempfile.gettempdir()) / "YazKlinik" / "locks"
    lock_dir.mkdir(parents=True, exist_ok=True)
    return lock_dir / f"web_{safe_port}.lock"


def _yk_release_instance_lock():
    global _YK_INSTANCE_LOCK_HANDLE
    handle = _YK_INSTANCE_LOCK_HANDLE
    _YK_INSTANCE_LOCK_HANDLE = None
    if not handle:
        return
    try:
        handle.seek(0)
        if os.name == "nt":
            import msvcrt
            msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
        else:
            import fcntl
            fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
    except Exception:
        pass
    try:
        handle.close()
    except Exception:
        pass


def _yk_acquire_instance_lock(port):
    """Guard against accidental second server instance on same port."""
    global _YK_INSTANCE_LOCK_HANDLE
    lock_file = _yk_instance_lock_file(port)
    try:
        lock_file.parent.mkdir(parents=True, exist_ok=True)
        handle = open(lock_file, "a+", encoding="utf-8")
    except Exception as ex:
        return False, f"Kilit dosyasi acilamadi: {lock_file} ({ex})"
    try:
        handle.seek(0)
        if os.name == "nt":
            import msvcrt
            msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        handle.truncate()
        handle.write(
            f"pid={os.getpid()}\nstarted={datetime.now().isoformat(sep=' ', timespec='seconds')}\n")
        handle.flush()
        _YK_INSTANCE_LOCK_HANDLE = handle
        atexit.register(_yk_release_instance_lock)
        return True, str(lock_file)
    except Exception:
        try:
            handle.close()
        except Exception:
            pass
        return False, (
            f"YazKlinik zaten calisiyor gibi gorunuyor "
            f"(kilit: {lock_file})."
        )


