def _console_print(*args, **kwargs):
    """Keep legacy mojibake startup messages readable in terminal builds."""
    import builtins as _builtins
    fixed_args = tuple(
        _early_fix_mojibake_text(arg) if isinstance(arg, str) else arg
        for arg in args
    )
    return _builtins.print(*fixed_args, **kwargs)


print = _console_print

