def _web_ensure_patient_demographics_schema_v1000(con):
    con.execute("""
        CREATE TABLE IF NOT EXISTS patient_demographics (
            patient_key TEXT PRIMARY KEY,
            updated_at TEXT
        )
    """)
    try:
        cols = {str(row[1]) for row in con.execute(
            "PRAGMA table_info(patient_demographics)").fetchall()}
    except Exception:
        cols = set()
    for col, ddl in (
        ("blood_type", "ALTER TABLE patient_demographics ADD COLUMN blood_type TEXT"),
        ("rh_factor", "ALTER TABLE patient_demographics ADD COLUMN rh_factor TEXT"),
        ("partner_rh", "ALTER TABLE patient_demographics ADD COLUMN partner_rh TEXT"),
        ("gravida", "ALTER TABLE patient_demographics ADD COLUMN gravida INTEGER"),
        ("para", "ALTER TABLE patient_demographics ADD COLUMN para INTEGER"),
        ("abortus", "ALTER TABLE patient_demographics ADD COLUMN abortus INTEGER"),
        ("living", "ALTER TABLE patient_demographics ADD COLUMN living INTEGER"),
        ("lmp_override", "ALTER TABLE patient_demographics ADD COLUMN lmp_override TEXT"),
        ("chronic_conditions", "ALTER TABLE patient_demographics ADD COLUMN chronic_conditions TEXT"),
        ("medications", "ALTER TABLE patient_demographics ADD COLUMN medications TEXT"),
        ("allergies", "ALTER TABLE patient_demographics ADD COLUMN allergies TEXT"),
        ("data_json", "ALTER TABLE patient_demographics ADD COLUMN data_json TEXT"),
        ("tc_no", "ALTER TABLE patient_demographics ADD COLUMN tc_no TEXT"),
        ("phone", "ALTER TABLE patient_demographics ADD COLUMN phone TEXT"),
        ("age", "ALTER TABLE patient_demographics ADD COLUMN age INTEGER"),
        ("age_source", "ALTER TABLE patient_demographics ADD COLUMN age_source TEXT"),
        ("age_confirmed_at",
         "ALTER TABLE patient_demographics ADD COLUMN age_confirmed_at TEXT"),
        ("birth_date", "ALTER TABLE patient_demographics ADD COLUMN birth_date TEXT"),
        ("weight", "ALTER TABLE patient_demographics ADD COLUMN weight REAL"),
        ("height", "ALTER TABLE patient_demographics ADD COLUMN height REAL"),
        ("bmi", "ALTER TABLE patient_demographics ADD COLUMN bmi REAL"),
        ("pre_pregnancy_weight",
         "ALTER TABLE patient_demographics ADD COLUMN pre_pregnancy_weight REAL"),
        ("canonical_name",
         "ALTER TABLE patient_demographics ADD COLUMN canonical_name TEXT"),
        ("dicom_patient_id",
         "ALTER TABLE patient_demographics ADD COLUMN dicom_patient_id TEXT"),
        ("dicom_patient_name",
         "ALTER TABLE patient_demographics ADD COLUMN dicom_patient_name TEXT"),
        ("dicom_accession_prefix",
         "ALTER TABLE patient_demographics ADD COLUMN dicom_accession_prefix TEXT"),
        ("dicom_station_aet",
         "ALTER TABLE patient_demographics ADD COLUMN dicom_station_aet TEXT"),
        ("dicom_patient_sex",
         "ALTER TABLE patient_demographics ADD COLUMN dicom_patient_sex TEXT"),
    ):
        if col in cols:
            continue
        try:
            con.execute(ddl)
            cols.add(col)
        except Exception:
            pass
    return cols


def _web_patient_profile_metric_float_v1000(value, low=None, high=None):
    if value in (None, ""):
        return None
    try:
        number = float(str(value).replace(",", "."))
        if low is not None and number < low:
            return None
        if high is not None and number > high:
            return None
        return round(number, 2)
    except Exception:
        return None


def _web_patient_profile_metric_int_v1000(value, low=None, high=None):
    number = _web_patient_profile_metric_float_v1000(value, low=low, high=high)
    if number is None:
        return None
    return int(round(number))


def _web_patient_profile_age_v1000(value):
    age = _web_patient_profile_metric_int_v1000(value, low=0, high=120)
    if age is None or age <= 1:
        return None
    return age


def load_patient_demographics(patient_key: str) -> dict:
    if patient_key:
        try:
            with db_conn() as con:
                _web_ensure_patient_demographics_schema_v1000(con)
                con.commit()
        except Exception:
            pass
    data = _v68_load_patient_demographics(patient_key) or {}
    if not patient_key:
        return data
    try:
        with db_conn() as con:
            _ensure_visit_clinical_schema(con)
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            _web_ensure_patient_demographics_schema_v1000(con)
            row = con.execute(
                "SELECT tc_no, phone, age, age_source, age_confirmed_at, "
                "birth_date, weight, height, bmi, "
                "pre_pregnancy_weight, lmp_override, "
                "blood_type, rh_factor, partner_rh, gravida, para, "
                "abortus, living, chronic_conditions, medications, allergies, "
                "canonical_name, dicom_patient_id, dicom_patient_name, "
                "dicom_accession_prefix, dicom_station_aet, dicom_patient_sex "
                "FROM patient_demographics WHERE patient_key=?",
                (patient_key,)).fetchone()
            if row:
                for key in ("tc_no", "phone", "age", "age_source",
                            "age_confirmed_at", "birth_date", "weight", "height",
                            "bmi", "pre_pregnancy_weight", "lmp_override",
                            "blood_type", "rh_factor", "partner_rh",
                            "gravida", "para", "abortus", "living",
                            "chronic_conditions", "medications", "allergies",
                            "canonical_name", "dicom_patient_id",
                            "dicom_patient_name", "dicom_accession_prefix",
                            "dicom_station_aet", "dicom_patient_sex"):
                    value = row.get(key)
                    if value not in (None, ""):
                        data[key] = value
    except Exception:
        pass
    age = _web_patient_profile_age_v1000(data.get("age"))
    if age is None:
        data.pop("age", None)
    else:
        data["age"] = age
    return data


def save_patient_demographics(patient_key: str, data: dict) -> None:
    if not patient_key:
        return
    data = dict(data or {})
    with db_conn() as con:
        _web_ensure_patient_demographics_schema_v1000(con)
        con.commit()
    _v68_save_patient_demographics(patient_key, data)
    age = _web_patient_profile_age_v1000(data.get("age"))
    weight = _web_patient_profile_metric_float_v1000(
        data.get("weight"), low=20, high=250)
    height = _web_patient_profile_metric_float_v1000(
        data.get("height"), low=90, high=230)
    bmi = _web_patient_profile_metric_float_v1000(
        data.get("bmi"), low=10, high=80)
    if bmi is None and weight is not None and height is not None:
        try:
            h_m = float(height) / 100.0
            if h_m > 0:
                bmi = round(float(weight) / (h_m * h_m), 1)
        except Exception:
            bmi = None
    pre_weight = _web_patient_profile_metric_float_v1000(
        data.get("pre_pregnancy_weight"), low=20, high=250)
    text_fields = {
        "tc_no": str(data.get("tc_no") or "").strip(),
        "phone": str(data.get("phone") or "").strip(),
        "age_source": (
            str(data.get("age_source") or "manual").strip()
            if age is not None else ""),
        "age_confirmed_at": (
            str(data.get("age_confirmed_at") or
                datetime.now().isoformat(sep=" ", timespec="seconds")).strip()
            if age is not None else ""),
        "birth_date": str(data.get("birth_date") or "").strip(),
        "lmp_override": str(data.get("lmp_override") or "").strip(),
        "blood_type": str(data.get("blood_type") or "").strip(),
        "rh_factor": str(data.get("rh_factor") or "").strip(),
        "partner_rh": str(data.get("partner_rh") or "").strip(),
        "chronic_conditions": str(data.get("chronic_conditions") or "").strip(),
        "medications": str(data.get("medications") or "").strip(),
        "allergies": str(data.get("allergies") or "").strip(),
        "canonical_name": str(data.get("canonical_name") or "").strip(),
        "dicom_patient_id": str(data.get("dicom_patient_id") or "").strip(),
        "dicom_patient_name": str(data.get("dicom_patient_name") or "").strip(),
        "dicom_accession_prefix": str(data.get("dicom_accession_prefix") or "").strip(),
        "dicom_station_aet": str(data.get("dicom_station_aet") or "").strip(),
        "dicom_patient_sex": str(data.get("dicom_patient_sex") or "").strip(),
    }
    int_fields = {}
    for key in ("gravida", "para", "abortus", "living"):
        try:
            if data.get(key) not in (None, ""):
                int_fields[key] = int(data.get(key))
        except Exception:
            pass
    if (age is None and weight is None and height is None and
            bmi is None and
            pre_weight is None and not any(text_fields.values()) and
            not int_fields):
        return
    try:
        now = datetime.now().isoformat(sep=" ", timespec="seconds")
        with db_conn() as con:
            _web_ensure_patient_demographics_schema_v1000(con)
            con.execute(
                "INSERT OR IGNORE INTO patient_demographics(patient_key, updated_at) "
                "VALUES(?, ?)",
                (patient_key, now))
            updates = []
            params = []
            numeric_values = {
                "age": age,
                "weight": weight,
                "height": height,
                "bmi": bmi,
                "pre_pregnancy_weight": pre_weight,
            }
            for col, val in numeric_values.items():
                if val is not None:
                    updates.append(f"{col}=?")
                    params.append(val)
            for col, val in text_fields.items():
                if val:
                    updates.append(f"{col}=?")
                    params.append(val)
            for col, val in int_fields.items():
                updates.append(f"{col}=?")
                params.append(val)
            if updates:
                updates.append("updated_at=?")
                params.append(now)
                params.append(patient_key)
                con.execute(
                    "UPDATE patient_demographics SET "
                    + ", ".join(updates)
                    + " WHERE patient_key=?",
                    params)
            if age is not None:
                try:
                    _ensure_patient_data_conflict_schema(con)
                    con.execute(
                        "UPDATE patient_data_conflicts SET status='manual_applied', "
                        "resolved_at=?, resolved_by=?, note=? "
                        "WHERE patient_key=? AND field_key='age' "
                        "AND status='pending'",
                        (now, "manual", "Manual/ana yas kaydi guncellendi",
                         patient_key))
                except Exception:
                    pass
            con.commit()
        if any(k in data for k in (
                "lmp_override", "lmp", "sat", "lmp_date",
                "last_menstrual_period", "gravida", "para",
                "abortus", "living")):
            try:
                invalidator = globals().get("cache_invalidate")
                if invalidator:
                    invalidator("delivery_countdown")
                    invalidator("smart_notifications")
                    invalidator("perinatology")
            except Exception:
                pass
    except Exception:
        pass

