def _yk_external_https_redirect_enabled():
    value = os.environ.get("YAZKLINIK_FORCE_HTTPS_EXTERNAL", "1")
    return str(value).strip().lower() not in {
        "0", "false", "hayir", "hayır", "no", "off"}


def _yk_request_hostname():
    host = str(
        request.headers.get("X-Forwarded-Host")
        or request.headers.get("Host")
        or "").strip()
    if "," in host:
        host = host.split(",", 1)[0].strip()
    if not host:
        return ""
    if host.startswith("["):
        end = host.find("]")
        if end > 0:
            return host[1:end].strip().lower()
    if host.count(":") == 1:
        host = host.rsplit(":", 1)[0]
    return host.strip("[]").lower()


def _yk_is_local_hostname(hostname):
    host = str(hostname or "").strip().lower()
    if host in {"localhost", "127.0.0.1", "::1", "0.0.0.0"}:
        return True
    return host.startswith("127.")


def _yk_normalize_base_url(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    if not raw.startswith(("http://", "https://")):
        raw = "https://" + raw.lstrip("/")
    try:
        parts = urlsplit(raw)
        if not parts.scheme or not parts.netloc:
            return ""
        return f"{parts.scheme}://{parts.netloc}".rstrip("/")
    except Exception:
        return ""


def _yk_public_base_url():
    if has_request_context():
        hostname = _yk_request_hostname()
        if hostname and not _yk_is_local_hostname(hostname):
            host = hostname
            if ":" in host and not host.startswith("["):
                host = f"[{host}]"
            return f"https://{host}:{_yk_https_port()}"
    configured = _yk_normalize_base_url(
        os.environ.get("YAZKLINIK_PUBLIC_BASE_URL")
        or os.environ.get("YAZKLINIK_EXTERNAL_BASE_URL")
        or "")
    if configured:
        return configured
    if has_request_context():
        try:
            return str(request.url_root or "").rstrip("/")
        except Exception:
            pass
    host = str(
        os.environ.get("YAZKLINIK_HTTPS_PUBLIC_HOST")
        or os.environ.get("YAZKLINIK_PUBLIC_HOST")
        or "127.0.0.1").strip()
    if ":" in host and not host.startswith("["):
        host = f"[{host}]"
    return f"https://{host}:{_yk_https_port()}"


def _yk_url_netloc_parts(netloc):
    text = str(netloc or "").strip()
    if not text:
        return "", ""
    if text.startswith("[") and "]" in text:
        host = text[1:text.find("]")]
        rest = text[text.find("]") + 1:]
        port = rest[1:] if rest.startswith(":") else ""
        return host.lower(), port
    if text.count(":") == 1:
        host, port = text.rsplit(":", 1)
        return host.lower(), port
    return text.lower(), ""


def _yk_netloc_is_internal_service(netloc):
    host, port = _yk_url_netloc_parts(netloc)
    if not host:
        return False
    try:
        web_port = str(int(os.environ.get("YAZKLINIK_WEB_PORT") or 5052))
    except Exception:
        web_port = "5052"
    try:
        https_port = str(int(_yk_https_port()))
    except Exception:
        https_port = "5443"
    internal_ports = {web_port, https_port, "5000", "5051", "5068", "8042"}
    if port not in internal_ports:
        return False
    if _yk_is_local_hostname(host):
        return True
    try:
        import ipaddress
        ip = ipaddress.ip_address(host)
        return bool(ip.is_private or ip.is_loopback or str(ip).startswith("100."))
    except Exception:
        pass
    configured = _yk_normalize_base_url(os.environ.get("YAZKLINIK_PUBLIC_BASE_URL", ""))
    if configured:
        cfg_host, _cfg_port = _yk_url_netloc_parts(urlsplit(configured).netloc)
        if host == cfg_host and port == web_port:
            return True
    return False


def _yk_public_url(path="/"):
    raw = str(path or "/").strip()
    if raw.startswith(("http://", "https://")):
        try:
            parts = urlsplit(raw)
            if parts.netloc and not _yk_netloc_is_internal_service(parts.netloc):
                return raw
            raw = parts.path or "/"
            if parts.query:
                raw += "?" + parts.query
        except Exception:
            raw = "/"
    if raw.startswith("//"):
        raw = "/"
    if not raw.startswith("/"):
        raw = "/" + raw.lstrip("/")
    return _yk_public_base_url().rstrip("/") + raw


def _yk_https_redirect_host():
    configured = str(os.environ.get("YAZKLINIK_HTTPS_PUBLIC_HOST") or "").strip()
    if configured:
        return configured
    public_base = _yk_public_base_url()
    try:
        netloc = urlsplit(public_base).netloc
        if netloc:
            return netloc
    except Exception:
        pass
    hostname = _yk_request_hostname()
    if not hostname:
        return ""
    if ":" in hostname and not hostname.startswith("["):
        hostname = f"[{hostname}]"
    return f"{hostname}:{_yk_https_port()}"


@app.before_request
def _yk_force_external_https_for_browser():
    if not _yk_external_https_redirect_enabled():
        return
    if not _yk_https_enabled():
        return
    if request.is_secure:
        return
    if str(request.headers.get("X-Forwarded-Proto", "")).lower() == "https":
        return
    hostname = _yk_request_hostname()
    if not hostname or _yk_is_local_hostname(hostname):
        return
    target_host = _yk_https_redirect_host()
    if not target_host:
        return
    path = request.path or "/"
    if request.query_string:
        path += "?" + request.query_string.decode("latin-1", "ignore")
    code = 302 if request.method in {"GET", "HEAD"} else 307
    return redirect(_yk_public_url(path), code=code)


@app.after_request
def _yk_rewrite_internal_redirect_locations(response):
    try:
        if not _yk_external_https_redirect_enabled():
            return response
        hostname = _yk_request_hostname()
        if not hostname or _yk_is_local_hostname(hostname):
            return response
        loc = response.headers.get("Location")
        if not loc or not str(loc).startswith(("http://", "https://")):
            return response
        parts = urlsplit(str(loc))
        if parts.netloc and _yk_netloc_is_internal_service(parts.netloc):
            response.headers["Location"] = _yk_public_url(loc)
    except Exception:
        pass
    return response


@app.context_processor
def _yk_public_url_context():
    try:
        return {"yk_public_base_url": _yk_public_base_url()}
    except Exception:
        return {"yk_public_base_url": ""}


@app.before_request
def _database_ready_guard():
    """Repair a malformed SQLite file before route code touches it."""
    global _DB_READY_GUARD_LAST
    path = request.path or ""
    if path.startswith(("/static/", "/favicon", "/brand-logo")):
        return
    if path.startswith("/yz-mod/"):
        return
    if path in (
        "/api/terminal/ping",
        "/api/ozellik-senkron",
        "/yk-test-pdf",
        "/api/yz/durum",
        "/api/ui/experience-mode",
    ):
        return
    prewarm_program_cache = str(os.environ.get(
        "YAZKLINIK_PROGRAM_RAM_CACHE_PREWARM_ON_REQUEST", "0")
    ).strip().lower() in {"1", "true", "yes", "evet", "on"}
    if prewarm_program_cache:
        try:
            _program_ram_cache_prewarm_once()
        except Exception:
            pass
    now_ts = datetime.now().timestamp()
    if now_ts - float(_DB_READY_GUARD_LAST or 0.0) < _DB_READY_GUARD_INTERVAL:
        return
    try:
        info = ensure_database_ready(recreate=True)
        _DB_READY_GUARD_LAST = now_ts
        if str(info.get("status")) == "recovered":
            flash(
                "Veritabani bozulmasi otomatik onarildi. "
                "Bozuk dosya auto_backups/malformed_db altina alindi.",
                "warning")
    except Exception as ex:
        # D128 SUPER PERF FIX (2026-05-10): Bu before_request handler bazi
        # waitress thread'lerinde DB lock'tan dolayi 500 donduruyor; halbuki
        # ensure_db() server start'ta zaten yapildi ve DB sagliklidir.
        # Burada sessizce gec ki request handle edilebilsin.
        if is_sqlite_malformed_error(ex):
            try:
                info = recover_malformed_database(
                    f"web before_request: {ex}", recreate=True)
                _DB_READY_GUARD_LAST = now_ts
                flash(
                    "Veritabani bozulmasi otomatik onarildi. "
                    "Hasta listesini tekrar acin.", "warning")
                return
            except Exception:
                pass
        # Soft fail: log ve devam et, route handler kendi DB hatasini gosterir
        try:
            print(f"[before_request DB warn] {ex}")
        except Exception:
            pass
        _DB_READY_GUARD_LAST = now_ts
        return


def app_resource_path(*parts) -> Path:
    """Resolve bundled assets in source runs and PyInstaller builds."""
    bundle_dir = getattr(sys, "_MEIPASS", None)
    if bundle_dir:
        return Path(bundle_dir).joinpath(*parts)
    return Path(__file__).resolve().parent.joinpath(*parts)

