def _b301_is_tls_verify_error(ex):
    try:
        import ssl as _ssl
        cur = ex
        for _ in range(6):
            if isinstance(cur, _ssl.SSLCertVerificationError):
                return True
            cur = getattr(cur, "__cause__", None) or getattr(cur, "reason", None)
            if cur is None:
                break
    except Exception:
        pass
    text = (str(ex) + " " + repr(ex)).upper()
    return "CERTIFICATE_VERIFY_FAILED" in text or "SSLCERTVERIFICATIONERROR" in text


def _b301_urlopen_cloud(req, timeout=60, provider="cloud"):
    """Open cloud API URL; retry once for Windows TLS interception errors.

    Some Windows antivirus/proxy chains expose a CA that Python/OpenSSL rejects
    even though the browser accepts it. We keep normal TLS first, then retry
    only for certificate verification failures unless strict TLS is requested.
    """
    import urllib.request as _urllib_req
    import urllib.error as _urllib_err
    try:
        return _urllib_req.urlopen(req, timeout=timeout)
    except Exception as ex:
        strict = str(os.environ.get("YAZKLINIK_STRICT_CLOUD_TLS") or "").lower()
        if strict in {"1", "true", "yes", "on"} or not _b301_is_tls_verify_error(ex):
            raise
        try:
            import ssl as _ssl
            ctx = _ssl._create_unverified_context()
            return _urllib_req.urlopen(req, timeout=timeout, context=ctx)
        except _urllib_err.HTTPError:
            raise
        except Exception:
            raise ex


def _b301_cloud_config(provider):
    """Provider'a gore config dict don. provider in {claude, deepseek, gemini}."""
    provider = str(provider or "").strip().lower()
    if provider not in _B301_CLOUD_DEFAULTS:
        return {}
    defaults = _B301_CLOUD_DEFAULTS[provider]
    api_key = (
        os.environ.get(f"YAZKLINIK_{provider.upper()}_API_KEY")
        or _ai_setting_value(f"sysparam_{provider}_api_key", "")
    ).strip()
    model = (
        os.environ.get(f"YAZKLINIK_{provider.upper()}_MODEL")
        or _ai_setting_value(f"sysparam_{provider}_model", defaults["model"])
        or defaults["model"]
    ).strip()
    base_url = (
        os.environ.get(f"YAZKLINIK_{provider.upper()}_BASE_URL")
        or _ai_setting_value(f"sysparam_{provider}_base_url", defaults["base_url"])
        or defaults["base_url"]
    ).strip()
    timeout_raw = (
        os.environ.get(f"YAZKLINIK_{provider.upper()}_TIMEOUT")
        or _ai_setting_value(f"sysparam_{provider}_timeout", "60")
        or "60"
    )
    try:
        timeout = max(10, min(int(float(str(timeout_raw).replace(",", "."))), 300))
    except Exception:
        timeout = 60
    return {
        "provider": provider,
        "label": defaults["label"],
        "api_key": api_key,
        "model": model,
        "base_url": base_url,
        "timeout": timeout,
    }


def _b301_cloud_available(provider):
    """API key tanimli mi?"""
    p = str(provider or "").strip().lower()
    # D250: OpenAI _B301_CLOUD_DEFAULTS'ta yok, ayri _openai_config var.
    # Bu fonksiyon openai icin de calismali ki UI dogru status yansitsin.
    if p == "openai":
        try:
            return bool((_openai_config() or {}).get("api_key"))
        except Exception:
            return False
    cfg = _b301_cloud_config(provider)
    return bool(cfg.get("api_key"))


def _b301_cloud_configured_status():
    """Cheap cloud provider status for header badges.

    This intentionally checks only saved/env API keys, not remote network
    reachability, so the global YZ badge stays fast while still counting
    configured cloud providers such as DeepSeek.
    """
    status = {
        "openai": False,
        "claude": False,
        "deepseek": False,
        "gemini": False,
    }
    try:
        status["openai"] = bool((_openai_config() or {}).get("api_key"))
    except Exception:
        status["openai"] = False
    for provider in ("claude", "deepseek", "gemini"):
        try:
            status[provider] = bool(_b301_cloud_available(provider))
        except Exception:
            status[provider] = False
    return status


def _b301_selected_cloud_providers():
    """Cloud providers explicitly selected for text/task work."""
    cloud_set = {"openai", "claude", "deepseek", "gemini"}
    selected = set()
    try:
        provider = _ai_provider_value()
        if provider in cloud_set:
            selected.add(provider)
    except Exception:
        pass
    try:
        task_defs = globals().get("_OLLAMA_TASK_DEFINITIONS") or []
        for task, _label, _icon in task_defs:
            raw = _ollama_setting_value(_ollama_task_setting_key(task), "")
            value = str(raw or "").strip().lower().replace(":", "_").replace("-", "_")
            if value.startswith("cloud_"):
                provider = value.split("cloud_", 1)[1].strip("_")
                if provider in cloud_set:
                    selected.add(provider)
            elif value in cloud_set:
                selected.add(value)
        raw_vision = _ollama_setting_value("sysparam_ollama_vision_model", "")
        value = str(raw_vision or "").strip().lower().replace(":", "_").replace("-", "_")
        if value.startswith("cloud_"):
            provider = value.split("cloud_", 1)[1].strip("_")
            if provider in cloud_set:
                selected.add(provider)
    except Exception:
        pass
    order = ("claude", "openai", "deepseek", "gemini")
    return [p for p in order if p in selected]


def _b301_cloud_badge_status(base_status=None):
    """Cloud providers that should contribute to the compact YZ badge."""
    status = dict(base_status or _b301_cloud_configured_status())
    selected = _b301_selected_cloud_providers()
    if selected:
        return {p: bool(status.get(p)) and p in selected for p in status}
    configured = [p for p in ("claude", "openai", "deepseek", "gemini")
                  if status.get(p)]
    if len(configured) == 1:
        only = configured[0]
        return {p: p == only for p in status}
    return {p: False for p in status}


def _b301_call_anthropic_claude(prompt, model=None, temperature=None,
                                max_tokens=None, timeout=None,
                                use_cache=True, system=None):
    """B301: Anthropic Claude Messages API."""
    import urllib.request as _urllib_req
    import urllib.error as _urllib_err
    import json as _json
    import hashlib as _hash
    import time as _t

    prompt = (prompt or "").strip()
    if not prompt:
        return (False, "Bos YZ istemi", 0)
    cfg = _b301_cloud_config("claude")
    api_key = cfg.get("api_key")
    if not api_key:
        return (False, "Anthropic Claude API anahtari tanimli degil.", 0)
    model = str(model or cfg.get("model") or "claude-sonnet-4-6").strip()
    base_url = str(cfg.get("base_url") or "https://api.anthropic.com/v1/messages")
    if timeout is None:
        timeout = cfg.get("timeout") or 60
    try:
        timeout = max(10, min(int(timeout), 300))
    except Exception:
        timeout = 60

    cache_key = None
    if use_cache:
        try:
            sysstr = str(system or "")
            cache_key = _hash.md5(
                f"claude:{model}:{sysstr}:{prompt}".encode("utf-8")).hexdigest()
            now = _t.time()
            with _AI_CACHE_LOCK:
                if cache_key in _AI_CACHE:
                    ts, cached = _AI_CACHE[cache_key]
                    if now - ts < _AI_CACHE_TTL:
                        return (True, cached, 0)
        except Exception:
            cache_key = None

    payload_obj = {
        "model": model,
        "max_tokens": max(128, min(int(max_tokens or 1024), 4096)),
        "messages": [{"role": "user", "content": prompt}],
    }
    if system:
        payload_obj["system"] = str(system)
    if temperature is not None:
        try:
            payload_obj["temperature"] = float(temperature)
        except Exception:
            pass

    start = _t.time()
    try:
        payload = _json.dumps(payload_obj).encode("utf-8")
        req = _urllib_req.Request(
            base_url,
            data=payload,
            headers={
                "Content-Type": "application/json",
                "x-api-key": api_key,
                "anthropic-version": "2023-06-01",
            })
        with _urllib_req.urlopen(req, timeout=timeout) as resp:
            data = _json.loads(resp.read().decode("utf-8"))
        # Response: {"content": [{"type":"text","text":"..."}], ...}
        parts = []
        for block in (data.get("content") or []):
            if isinstance(block, dict) and block.get("type") == "text":
                t = block.get("text") or ""
                if t:
                    parts.append(str(t))
        answer = "\n".join(parts).strip()
        duration_ms = int((_t.time() - start) * 1000)
        if not answer:
            answer = _json.dumps(data, ensure_ascii=False)[:4000]
        if cache_key and answer:
            try:
                with _AI_CACHE_LOCK:
                    if len(_AI_CACHE) > _AI_CACHE_MAX:
                        keys = sorted(_AI_CACHE.keys(),
                                      key=lambda k: _AI_CACHE[k][0])
                        for k in keys[:20]:
                            _AI_CACHE.pop(k, None)
                    _AI_CACHE[cache_key] = (_t.time(), answer)
            except Exception:
                pass
        return (True, answer, duration_ms)
    except _urllib_err.HTTPError as ex:
        try:
            detail = ex.read().decode("utf-8", errors="ignore")
        except Exception:
            detail = str(ex)
        return (False, f"Claude HTTP hata {ex.code}: {detail[:800]}",
                int((_t.time() - start) * 1000))
    except Exception as ex:
        return (False, f"Claude baglanti hatasi: {ex}",
                int((_t.time() - start) * 1000))


def _b301_call_deepseek(prompt, model=None, temperature=None,
                       max_tokens=None, timeout=None,
                       use_cache=True, system=None):
    """B301: DeepSeek Chat Completions (OpenAI-compatible)."""
    import urllib.request as _urllib_req
    import urllib.error as _urllib_err
    import json as _json
    import hashlib as _hash
    import time as _t

    prompt = (prompt or "").strip()
    if not prompt:
        return (False, "Bos YZ istemi", 0)
    cfg = _b301_cloud_config("deepseek")
    api_key = cfg.get("api_key")
    if not api_key:
        return (False, "DeepSeek API anahtari tanimli degil.", 0)
    model = str(model or cfg.get("model") or "deepseek-chat").strip()
    base_url = str(cfg.get("base_url") or "https://api.deepseek.com/chat/completions").strip()
    base_url = base_url.rstrip("/")
    if not base_url.endswith("/chat/completions"):
        base_url = base_url + "/chat/completions"
    if timeout is None:
        timeout = cfg.get("timeout") or 60
    try:
        timeout = max(10, min(int(timeout), 300))
    except Exception:
        timeout = 60

    cache_key = None
    if use_cache:
        try:
            sysstr = str(system or "")
            cache_key = _hash.md5(
                f"deepseek:{model}:{sysstr}:{prompt}".encode("utf-8")).hexdigest()
            now = _t.time()
            with _AI_CACHE_LOCK:
                if cache_key in _AI_CACHE:
                    ts, cached = _AI_CACHE[cache_key]
                    if now - ts < _AI_CACHE_TTL:
                        return (True, cached, 0)
        except Exception:
            cache_key = None

    messages = []
    if system:
        messages.append({"role": "system", "content": str(system)})
    messages.append({"role": "user", "content": prompt})
    payload_obj = {
        "model": model,
        "messages": messages,
        "max_tokens": max(128, min(int(max_tokens or 1024), 4096)),
    }
    if temperature is not None:
        try:
            payload_obj["temperature"] = float(temperature)
        except Exception:
            pass

    start = _t.time()
    try:
        payload = _json.dumps(payload_obj).encode("utf-8")
        req = _urllib_req.Request(
            base_url,
            data=payload,
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {api_key}",
            })
        with _b301_urlopen_cloud(req, timeout=timeout, provider="deepseek") as resp:
            data = _json.loads(resp.read().decode("utf-8"))
        # Response: {"choices": [{"message": {"content": "..."}}]}
        answer = ""
        for ch in (data.get("choices") or []):
            msg = (ch or {}).get("message") or {}
            text = msg.get("content") or ""
            if text:
                answer = str(text).strip()
                break
        duration_ms = int((_t.time() - start) * 1000)
        if not answer:
            answer = _json.dumps(data, ensure_ascii=False)[:4000]
        if cache_key and answer:
            try:
                with _AI_CACHE_LOCK:
                    if len(_AI_CACHE) > _AI_CACHE_MAX:
                        keys = sorted(_AI_CACHE.keys(),
                                      key=lambda k: _AI_CACHE[k][0])
                        for k in keys[:20]:
                            _AI_CACHE.pop(k, None)
                    _AI_CACHE[cache_key] = (_t.time(), answer)
            except Exception:
                pass
        return (True, answer, duration_ms)
    except _urllib_err.HTTPError as ex:
        try:
            detail = ex.read().decode("utf-8", errors="ignore")
        except Exception:
            detail = str(ex)
        return (False, f"DeepSeek HTTP hata {ex.code}: {detail[:800]}",
                int((_t.time() - start) * 1000))
    except Exception as ex:
        return (False, f"DeepSeek baglanti hatasi: {ex}",
                int((_t.time() - start) * 1000))


def _b301_call_gemini(prompt, model=None, temperature=None,
                     max_tokens=None, timeout=None,
                     use_cache=True, system=None):
    """B301: Google Gemini generateContent."""
    import urllib.request as _urllib_req
    import urllib.error as _urllib_err
    import json as _json
    import hashlib as _hash
    import time as _t

    prompt = (prompt or "").strip()
    if not prompt:
        return (False, "Bos YZ istemi", 0)
    cfg = _b301_cloud_config("gemini")
    api_key = cfg.get("api_key")
    if not api_key:
        return (False, "Gemini API anahtari tanimli degil.", 0)
    model = str(model or cfg.get("model") or "gemini-2.5-flash").strip()
    base_root = str(cfg.get("base_url") or "https://generativelanguage.googleapis.com/v1beta/models")
    base_root = base_root.rstrip("/")
    full_url = f"{base_root}/{model}:generateContent"
    if timeout is None:
        timeout = cfg.get("timeout") or 60
    try:
        timeout = max(10, min(int(timeout), 300))
    except Exception:
        timeout = 60

    cache_key = None
    if use_cache:
        try:
            sysstr = str(system or "")
            cache_key = _hash.md5(
                f"gemini:{model}:{sysstr}:{prompt}".encode("utf-8")).hexdigest()
            now = _t.time()
            with _AI_CACHE_LOCK:
                if cache_key in _AI_CACHE:
                    ts, cached = _AI_CACHE[cache_key]
                    if now - ts < _AI_CACHE_TTL:
                        return (True, cached, 0)
        except Exception:
            cache_key = None

    contents = [{"role": "user", "parts": [{"text": prompt}]}]
    payload_obj = {
        "contents": contents,
        "generationConfig": {
            "maxOutputTokens": max(128, min(int(max_tokens or 1024), 8192)),
        },
    }
    if system:
        payload_obj["system_instruction"] = {
            "parts": [{"text": str(system)}],
        }
    if temperature is not None:
        try:
            payload_obj["generationConfig"]["temperature"] = float(temperature)
        except Exception:
            pass

    start = _t.time()
    try:
        payload = _json.dumps(payload_obj).encode("utf-8")
        req = _urllib_req.Request(
            full_url,
            data=payload,
            headers={
                "Content-Type": "application/json",
                "x-goog-api-key": api_key,
            })
        with _urllib_req.urlopen(req, timeout=timeout) as resp:
            data = _json.loads(resp.read().decode("utf-8"))
        # Response: {"candidates":[{"content":{"parts":[{"text":"..."}]}}]}
        parts = []
        for cand in (data.get("candidates") or []):
            content_obj = (cand or {}).get("content") or {}
            for p in (content_obj.get("parts") or []):
                t = (p or {}).get("text") or ""
                if t:
                    parts.append(str(t))
        answer = "\n".join(parts).strip()
        duration_ms = int((_t.time() - start) * 1000)
        if not answer:
            answer = _json.dumps(data, ensure_ascii=False)[:4000]
        if cache_key and answer:
            try:
                with _AI_CACHE_LOCK:
                    if len(_AI_CACHE) > _AI_CACHE_MAX:
                        keys = sorted(_AI_CACHE.keys(),
                                      key=lambda k: _AI_CACHE[k][0])
                        for k in keys[:20]:
                            _AI_CACHE.pop(k, None)
                    _AI_CACHE[cache_key] = (_t.time(), answer)
            except Exception:
                pass
        return (True, answer, duration_ms)
    except _urllib_err.HTTPError as ex:
        try:
            detail = ex.read().decode("utf-8", errors="ignore")
        except Exception:
            detail = str(ex)
        return (False, f"Gemini HTTP hata {ex.code}: {detail[:800]}",
                int((_t.time() - start) * 1000))
    except Exception as ex:
        return (False, f"Gemini baglanti hatasi: {ex}",
                int((_t.time() - start) * 1000))


def _b301_call_cloud_ai(provider, prompt, **kwargs):
    """B301: Saglayiciya gore yonlendir. Donus: (ok, answer, duration_ms)."""
    p = str(provider or "").strip().lower()
    if p == "claude":
        return _b301_call_anthropic_claude(prompt, **kwargs)
    if p == "openai" or p == "chatgpt":
        return call_online_chatgpt(prompt, **kwargs)
    if p == "deepseek":
        return _b301_call_deepseek(prompt, **kwargs)
    if p == "gemini":
        return _b301_call_gemini(prompt, **kwargs)
    return (False, f"Bilinmeyen bulut saglayici: {p}", 0)


def _b301_pick_auto_cloud_provider():
    """B301: 'auto' modunda hangi bulut saglayicisi varsa onu sec.
    Sira: claude > openai > deepseek > gemini (kalite oncelikli)."""
    for kind, provider in _ai_strategy_available_order(prefer_cloud=True):
        if kind == "cloud":
            return str(provider or "")
    return ""


def _b301_active_text_provider():
    """B301: Akilli Dialog/cagrilarin gidecegi aktif provider'i don.
    Donus: 'ollama' veya 'claude'/'openai'/'deepseek'/'gemini' veya '' (yok).
    """
    return _ai_strategy_pick_active_provider(images=False, prefer_cloud=False)


def _normalize_ollama_task(task):
    raw = _fold_search_text(str(task or ""))
    if not raw:
        return ""
    if any(k in raw for k in ("vision", "goruntu", "gorsel", "dicom", "usg",
                              "anomali", "image", "video")):
        return "vision"
    if any(k in raw for k in ("telefon", "telesekreter", "phone", "pbx",
                              "diyalog", "chat", "sohbet")):
        return "phone"
    if any(k in raw for k in ("recete", "ilac", "doz", "gebelik guvenligi",
                              "prescription")):
        return "prescription"
    if any(k in raw for k in ("lab", "tahlil", "usg", "obstetrik", "gebelik",
                              "preeklampsi", "clinical", "klinik", "karar")):
        return "clinical"
    if any(k in raw for k in ("ozet", "rapor", "summary", "not", "dokuman")):
        return "summary"
    if any(k in raw for k in ("sistem", "terminal", "diagnostic", "performans",
                              "komuta", "takip", "health")):
        return "fast"
    return "general"


def _ollama_task_from_context(task=None, system=None, images=None):
    if images:
        return "vision"
    explicit = _normalize_ollama_task(task)
    if explicit:
        return explicit
    ctx = str(system or "")
    try:
        ctx += " " + str(request.path or "")
    except Exception:
        pass
    inferred = _normalize_ollama_task(ctx)
    return inferred or "general"


def _ollama_task_setting_key(task):
    task = _ollama_task_from_context(task)
    return f"sysparam_ollama_task_{task}_model"


def _ollama_manual_model_for_task(task):
    task = _ollama_task_from_context(task)
    task_model = _ollama_setting_value(_ollama_task_setting_key(task), "auto")
    if not _is_auto_model_value(task_model):
        return _normalize_ollama_model_name(task_model)
    mode = str(_AI_CONFIG.get("model_mode") or "auto").strip()
    if _is_manual_model_mode(mode):
        model = _normalize_ollama_model_name(_AI_CONFIG.get("model"))
        if model and not _is_auto_model_value(model):
            return model
    return ""


def _ollama_resolve_model_name(model_name, models):
    wanted = _normalize_ollama_model_name(model_name)
    if not wanted:
        return ""
    by_lower = {}
    for m in (models or []):
        raw = str(m or "").strip()
        if not raw:
            continue
        by_lower[raw.lower()] = raw
        by_lower[_normalize_ollama_model_name(raw).lower()] = raw
    return by_lower.get(wanted.lower(), wanted)


def _ollama_model_should_disable_think(model_name) -> bool:
    """Legacy compatibility hook.

    Older builds forced ``think:false`` for DeepSeek R1 70B variants. The user
    now wants reasoning enabled again, so this always returns False.
    """
    return False


def _ollama_model_should_enable_think(model_name) -> bool:
    """Enable Ollama reasoning stream for DeepSeek R1 70B / 70B2 variants."""
    ml = _normalize_ollama_model_name(model_name).lower()
    folded = re.sub(r"[\s_\-]+", "", ml)
    if "deepseek" not in folded or "r1" not in folded:
        return False
    return bool(re.search(r"(?:^|[:/])70b2?(?:$|[^0-9])", folded))


def _apply_ollama_think_policy(payload_obj, model_name):
    if isinstance(payload_obj, dict) and _ollama_model_should_enable_think(model_name):
        payload_obj["think"] = True
    return payload_obj


def _ollama_text_model_priority_score(model_name: str, task="general") -> float:
    task = _ollama_task_from_context(task)
    ml = str(model_name or "").lower()
    if not ml:
        return -9999.0
    if any(k in ml for k in ("embed", "embedding", "nomic-embed")):
        return -9000.0
    score = 0.0
    size = _ollama_model_size_hint(ml)
    if _is_ollama_vision_model(ml):
        score -= 300
    if any(k in ml for k in ("qwen", "llama", "gpt-oss", "mistral", "gemma",
                             "phi", "meditron")):
        score += 50
    if any(k in ml for k in ("turk", "tr", "qwen")):
        score += 18
    if "coder" in ml or "code" in ml:
        score -= 45

    if task == "phone":
        if "llama3.1:8b" in ml or "llama3.1:latest" in ml:
            score += 150
        if "gpt-oss:20b" in ml or "mixtral:8x7b" in ml:
            score += 120
        if "qwen" in ml:
            score += 80
        if any(k in ml for k in ("llama3.1", "llama3", "mistral", "phi")):
            score += 80
        if 4 <= size <= 12:
            score += 100
        elif 12 < size <= 24:
            score += 35
        elif size > 32:
            score -= 180
        score -= max(size - 12, 0) * 4
    elif task in ("clinical", "prescription"):
        if "gpt-oss:20b" in ml:
            score += 180
        if "qwen2.5:32b" in ml or "mixtral:8x7b" in ml:
            score += 150
        if any(k in ml for k in ("gpt-oss", "qwen", "meditron", "clinical",
                                 "med")):
            score += 95
        if "70b" in ml or "72b" in ml or "120b" in ml:
            score -= 120
        if "32b" in ml or "30b" in ml:
            score += 45
        if task == "prescription" and any(k in ml for k in ("gpt-oss", "qwen")):
            score += 35
        score += min(size, 32.0) * 1.2
        score -= max(size - 32, 0) * 4
    elif task in ("summary", "fast"):
        if "llama3.1:8b" in ml or "llama3.1:latest" in ml:
            score += 150
        if "gpt-oss:20b" in ml:
            score += 115
        if any(k in ml for k in ("qwen", "llama3.1", "llama3", "mistral",
                                 "phi")):
            score += 90
        if 3 <= size <= 12:
            score += 95
        elif 12 < size <= 24:
            score += 25
        elif size > 32:
            score -= 150
        score -= max(size - 12, 0) * 3.5
    else:
        if "gpt-oss:20b" in ml:
            score += 150
        if "llama3.1:8b" in ml or "llama3.1:latest" in ml:
            score += 130
        if "qwen2.5:32b" in ml:
            score += 95
        if any(k in ml for k in ("gpt-oss", "qwen", "llama3.1", "llama3")):
            score += 95
        if 7 <= size <= 24:
            score += 60
        elif 24 < size <= 32:
            score += 35
        elif size > 32:
            score -= 120
        score += min(size, 24.0)
        score -= max(size - 32, 0) * 3

    if "latest" in ml and size == 0:
        score -= 12
    try:
        gpu_profile = _gpu_auto_profile()
        if gpu_profile.get("enabled") and gpu_profile.get("tier") == "rtx_6gb":
            if 3 <= size <= 9:
                score += 140
            elif 9 < size <= 14:
                score += 35
            elif 14 < size <= 24:
                score -= 110
            elif size > 24:
                score -= 260
            if any(k in ml for k in ("llama3.1:8b", "llama3:8b", "qwen2.5:7b",
                                     "qwen2.5:8b", "mistral:7b", "gemma")):
                score += 70
    except Exception:
        pass
    return score


def _best_ollama_text_model(task="general", models=None) -> str:
    models = list(models if models is not None else _ollama_models())
    models = [str(m).strip() for m in models if str(m).strip()]
    if not models:
        return ""
    return sorted(
        models,
        key=lambda m: (_ollama_text_model_priority_score(m, task),
                       str(m).lower()),
        reverse=True,
    )[0]


def _vision_model_priority_score(model_name: str) -> float:
    """Score installed vision models for anomaly/media scans."""
    ml = str(model_name or "").lower()
    score = 0.0
    if "llama3.2-vision" in ml:
        score += 1050
    elif "qwen3-vl" in ml or "qwen3vl" in ml:
        score += 980
    elif "qwen2.5-vl" in ml or "qwen2.5vl" in ml:
        score += 930
    elif "qwen2-vl" in ml or "qwen-vl" in ml:
        score += 850
    elif "llama3.2-vision" in ml:
        score += 900
    elif "pixtral" in ml:
        score += 740
    elif "internvl" in ml:
        score += 720
    elif "llava" in ml:
        score += 660
    elif "minicpm" in ml:
        score += 630
    elif "gemma3" in ml:
        score += 610
    elif "bakllava" in ml:
        score += 520
    elif "moondream" in ml:
        score += 330
    elif _is_ollama_vision_model(ml):
        score += 430
    size = _ollama_model_size_hint(ml)
    score += min(size, 30.0) * 2.0
    score -= max(size - 30.0, 0) * 2.5
    if any(k in ml for k in ("medical", "clinical", "med-vl", "llava-med")):
        score += 70
    if any(k in ml for k in ("1b", "2b", "3b")):
        score -= 80
    if "latest" in ml and _ollama_model_size_hint(ml) == 0:
        score -= 15
    try:
        gpu_profile = _gpu_auto_profile()
        if gpu_profile.get("enabled") and gpu_profile.get("tier") == "rtx_6gb":
            if 4 <= size <= 8:
                score += 160
            elif 8 < size <= 12:
                score += 35
            elif size > 12:
                score -= 220
            if any(k in ml for k in ("moondream", "llava:7b", "minicpm")):
                score += 90
    except Exception:
        pass
    return score


def _best_ollama_vision_model(force: bool = False) -> str:
    models = _ollama_models(force=force)
    vision_models = [m for m in models if _is_ollama_vision_model(m)]
    if not vision_models:
        return ""
    return sorted(
        vision_models,
        key=lambda m: (_vision_model_priority_score(m), str(m).lower()),
        reverse=True,
    )[0]


def _select_ollama_vision_model(preferred=None, force: bool = False):
    """Return model metadata for image/DICOM/video anomaly scans."""
    _refresh_ai_config()
    configured = (
        str(preferred).strip()
        if preferred is not None else
        str(_AI_CONFIG.get("vision_model") or "").strip()
    )
    models = _ollama_models(force=force)
    by_lower = {m.lower(): m for m in models}
    auto_model = _best_ollama_vision_model(force=False)

    if not _is_vision_auto_value(configured):
        manual = by_lower.get(configured.lower())
        if manual and _is_ollama_vision_model(manual):
            return {
                "model": manual,
                "source": "manual",
                "configured": configured,
                "auto_model": auto_model,
                "note": "Kullanici tarafindan secilen vision model.",
            }
        if not models and _is_ollama_vision_model(configured):
            return {
                "model": configured,
                "source": "manual-offline",
                "configured": configured,
                "auto_model": "",
                "note": "Ollama model listesi okunamadi; kayitli vision model deneniyor.",
            }

    if auto_model:
        return {
            "model": auto_model,
            "source": "auto",
            "configured": configured or "auto",
            "auto_model": auto_model,
            "note": "Kurulu vision modeller arasindan otomatik en iyi secim.",
        }

    return {
        "model": "",
        "source": "none",
        "configured": configured or "auto",
        "auto_model": "",
        "note": "Kurulu vision model bulunamadi.",
    }


def _select_ollama_model(preferred=None, vision: bool = False,
                         task=None, system=None):
    """Pick a model for the active workflow; user force wins."""
    _refresh_ai_config()
    if vision:
        return _select_ollama_vision_model(preferred=preferred).get("model", "")
    task_name = _ollama_task_from_context(task=task, system=system)
    models = _ollama_models()
    preferred = _normalize_ollama_model_name(preferred)
    if preferred and not _is_auto_model_value(preferred):
        return _ollama_resolve_model_name(preferred, models)

    manual_model = _ollama_manual_model_for_task(task_name)
    if manual_model:
        return _ollama_resolve_model_name(manual_model, models)

    configured_default = _normalize_ollama_model_name(
        _AI_CONFIG.get("model") or DEFAULT_OLLAMA_MODEL)
    if configured_default and not _is_auto_model_value(configured_default):
        resolved_default = _ollama_resolve_model_name(configured_default, models)
        installed_lower = {str(m).strip().lower() for m in models if str(m).strip()}
        if (not models or resolved_default.lower() in installed_lower
                or configured_default.lower() in installed_lower):
            return resolved_default

    if not models:
        fallback = _normalize_ollama_model_name(_AI_CONFIG.get("model"))
        if _is_auto_model_value(fallback):
            fallback = DEFAULT_OLLAMA_MODEL
        return fallback

    auto_model = _best_ollama_text_model(task_name, models=models)
    if auto_model:
        return auto_model

    preferred = _normalize_ollama_model_name(_AI_CONFIG.get("model"))
    by_lower = {m.lower(): m for m in models}
    if preferred and not _is_auto_model_value(preferred) and preferred.lower() in by_lower:
        if not vision or _is_ollama_vision_model(preferred):
            return by_lower[preferred.lower()]

    preferred_order = (
        DEFAULT_OLLAMA_MODEL, BALANCED_OLLAMA_MODEL, "llama3.1:latest",
        "mixtral:8x7b", CLINICAL_OLLAMA_MODEL, "llama3:8b",
        "qwen3:32b", "gemma3:27b", "mistral", DEEP_OLLAMA_MODEL,
    )
    for wanted in preferred_order:
        if wanted.lower() in by_lower:
            return by_lower[wanted.lower()]
    return models[0]


def _ollama_extract_final_answer(data):
    """Return only the user-visible final answer from an Ollama payload."""
    import re as _re

    if not isinstance(data, dict):
        return ""

    candidates = []
    for key in ("response", "answer", "content", "text", "output"):
        val = data.get(key)
        if val:
            candidates.append(val)

    message = data.get("message")
    if isinstance(message, dict):
        val = message.get("content")
        if val:
            candidates.append(val)

    for val in candidates:
        text = str(val or "").strip()
        if not text:
            continue
        # Some reasoning models may leak a <think> block into response.
        text = _re.sub(r"(?is)<think>.*?</think>", "", text).strip()
        text = _re.sub(r"(?is)^\s*thinking\s*:\s*.*?final\s*:\s*", "",
                       text).strip()
        if text:
            return text
    return ""


def _ollama_error_is_final_only(text):
    """Detect when the model produced reasoning but no final answer."""
    low = str(text or "").lower()
    return (
        "final cevap" in low and "dusunme" in low
    ) or (
        "thinking" in low and "final" in low
    )


def _ollama_retry_prompt_without_thinking(full_prompt):
    return (
        "Onceki denemede model sadece dusunme/reasoning cikisi uretip "
        "hekime gosterilecek final cevabi bos birakti.\n\n"
        "KURAL: Dusunme surecini, reasoning notlarini, <think> bloklarini "
        "ve ara muhakemeyi yazma. Sadece nihai kullanici cevabini ver.\n"
        "Cevap Turkce, net, baslikli ve klinik olarak temkinli olsun.\n\n"
        "[ASIL ISTEM]\n"
        f"{full_prompt}"
    )


def _ollama_runtime_defaults(task="general", model_name="", has_images=False):
    task_name = _ollama_task_from_context(task=task, images=has_images)
    # D300 RTX 5090 akici muhabbet: num_predict cok kisa, ilk cumle hizli bitsin
    # (browser sentence-split TTS ile her cumle ayri akar). Tek cumle ~50 token.
    # (kisa cevap = hizli token uretimi). Reçete/clinical icin daha az kesildi.
    profiles = {
        "fast": {"temperature": 0.20, "num_predict": 140, "num_ctx": 1536, "timeout": 20},
        "phone": {"temperature": 0.22, "num_predict": 160, "num_ctx": 2048, "timeout": 25},
        "summary": {"temperature": 0.22, "num_predict": 600, "num_ctx": 3072, "timeout": 45},
        "clinical": {"temperature": 0.20, "num_predict": 800, "num_ctx": 3072, "timeout": 60},
        "prescription": {"temperature": 0.16, "num_predict": 700, "num_ctx": 3072, "timeout": 60},
        "vision": {"temperature": 0.16, "num_predict": 600, "num_ctx": 3072, "timeout": 90},
        "general": {"temperature": 0.22, "num_predict": 600, "num_ctx": 3072, "timeout": 50},
    }
    cfg = dict(profiles.get(task_name) or profiles["general"])
    if has_images:
        cfg.update(profiles["vision"])
    size = _ollama_model_size_hint(model_name)
    if size >= 60:
        cfg["timeout"] = max(cfg["timeout"], 140)
        cfg["num_predict"] = min(cfg["num_predict"], 1200)
        cfg["num_ctx"] = min(cfg["num_ctx"], 4096)
    elif 24 < size < 60:
        cfg["timeout"] = max(cfg["timeout"], 90)
        cfg["num_predict"] = min(cfg["num_predict"], 1100)
    try:
        gpu_opts = _gpu_ollama_options(
            model_name=model_name, has_images=has_images, task=task_name)
        if gpu_opts:
            if "num_ctx" in gpu_opts:
                cfg["num_ctx"] = min(int(cfg.get("num_ctx") or 2048),
                                     int(gpu_opts["num_ctx"]))
            for opt_key in ("num_batch", "num_gpu", "num_thread"):
                if opt_key in gpu_opts:
                    cfg[opt_key] = gpu_opts[opt_key]
    except Exception:
        pass
    return cfg


def _anomaly_safe_fallback_report(ctx_str, rule_warnings, ga_w=None,
                                  edd_str="", media_note=""):
    """Safe clinical fallback when the LLM cannot provide a final report."""
    danger = [w for w in (rule_warnings or []) if w.get("level") == "danger"]
    warning = [w for w in (rule_warnings or []) if w.get("level") != "danger"]
    lines = [
        "## Genel Degerlendirme",
        "YZ modeli final raporu bos dondurdugu icin sistem guvenli kural "
        "tabanli on rapora gecti. Bu cikti kesin tani degildir; hekim "
        "muayenesi, orijinal USG/DICOM ve klinik verilerle onaylanmalidir.",
        "",
        "## Risk Ozeti",
    ]
    if ga_w:
        lines.append(f"- Gebelik haftasi: {ga_w} hf"
                     + (f", EDD: {edd_str}" if edd_str else ""))
    if danger or warning:
        lines.append(f"- Kritik uyari: {len(danger)}")
        lines.append(f"- Takip uyarisi: {len(warning)}")
    else:
        lines.append(
            "- Otomatik kural tabanli kontrolde kritik alarm saptanmadi.")

    if danger or warning:
        lines.extend(["", "## Anormal Bulgular / Uyarilar"])
        for item in danger + warning:
            title = str(item.get("title") or "Uyari").strip()
            detail = str(item.get("detail") or "").strip()
            action = str(item.get("action") or "").strip()
            lines.append(f"- {title}: {detail}"
                         + (f" Eylem: {action}" if action else ""))

    if "Goruntu eklenemedi" in str(media_note or ""):
        lines.extend([
            "",
            "## Goruntu Notu",
            "- Hasta medyasi/DICOM/PDF baglami final rapora tam "
            "aktarilamamis olabilir. Gerekirse goruntuyu veya DICOM "
            "calismasini tekrar baglayin.",
        ])

    if ctx_str:
        compact_ctx = " ".join(str(ctx_str).split())
        if compact_ctx:
            lines.extend([
                "",
                "## Kullanilan Klinik Baglam",
                compact_ctx[:1200],
            ])

    lines.extend([
        "",
        "## Oneri",
        "- USG olcumleri yoksa ilk USG olcumunu ekleyin.",
        "- Supheli bulgu varsa perinatolojiye sevk veya detayli USG "
        "degerlendirmesi planlayin.",
        "- YZ analizini tekrar calistirmeden once gerekirse YZ ayarlarindan "
        "daha stabil bir model secin.",
    ])
    return "\n".join(lines)


def _ensure_ai_anomaly_screening_schema(con):
    """Persist local fetal image/anomaly pre-screening runs."""
    con.execute("""
        CREATE TABLE IF NOT EXISTS ai_anomaly_screenings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_key TEXT NOT NULL,
            source_count INTEGER DEFAULT 0,
            source_names TEXT,
            model_used TEXT,
            model_source TEXT,
            answer TEXT,
            risk_flags TEXT,
            quality_flags TEXT,
            created_at TEXT NOT NULL,
            created_by TEXT
        )
    """)
    con.execute("""
        CREATE INDEX IF NOT EXISTS idx_ai_anomaly_screenings_patient
        ON ai_anomaly_screenings(patient_key, created_at DESC)
    """)


def _fetal_anomaly_risk_tags(text):
    """Extract conservative risk/quality flags from local model output."""
    hay = str(text or "").lower()
    groups = [
        ("perinatoloji/sevk", (
            "perinatoloji", "sevk", "detayli usg", "fetal ekokardiyografi",
            "acil", "yuksek risk")),
        ("kalp/toraks", (
            "kalp", "kardiyak", "ventrikul", "septum", "ekokardiyografi",
            "toraks", "hidrops")),
        ("santral sinir sistemi", (
            "ventrikulomegali", "beyin", "posterior fossa", "spina",
            "noral tup", "omurga", "kafa")),
        ("yuz/profil", (
            "yarik", "dudak", "damak", "profil", "nazal", "ense",
            "nt")),
        ("batin/bobrek", (
            "bobrek", "hidronefroz", "mesane", "barsak", "karin",
            "abdominal", "omfalosel", "gastro")),
        ("ekstremite", (
            "ekstremite", "kol", "bacak", "el", "ayak", "femur",
            "humerus", "kisalma")),
        ("buyume/sivi/plasenta", (
            "iugr", "sga", "efw", "afi", "oligohidramnios",
            "polihidramnios", "plasenta", "doppler")),
        ("supheli bulgu", (
            "anomali", "suphe", "patoloji", "normal degil", "izleniyor",
            "asimetri", "genisleme", "artmis", "azalmis")),
    ]
    tags = []
    for label, words in groups:
        if any(word in hay for word in words):
            tags.append(label)
    return tags[:12]


def _fetal_anomaly_quality_tags(text):
    hay = str(text or "").lower()
    tags = []
    for label, words in [
        ("goruntu yetersiz", ("yetersiz", "net degil", "gorulemiyor", "artefakt")),
        ("tek kare siniri", ("tek kare", "sinirli", "tam degerlendirme")),
        ("orijinal gerekli", ("orijinal", "dicom", "cihaz", "usg kaydi")),
        ("ek kesit gerekli", ("ek kesit", "tekrar", "farkli plan", "yeniden")),
    ]:
        if any(word in hay for word in words):
            tags.append(label)
    return tags[:8]


