def _save_ai_anomaly_screening(patient_key, source_count, source_names,
                               model_used, model_source, answer,
                               risk_flags=None, quality_flags=None):
    import json as _json
    try:
        with db_conn() as con:
            _ensure_ai_anomaly_screening_schema(con)
            con.execute(
                "INSERT INTO ai_anomaly_screenings "
                "(patient_key, source_count, source_names, model_used, "
                "model_source, answer, risk_flags, quality_flags, created_at, created_by) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    patient_key,
                    int(source_count or 0),
                    _json.dumps(list(source_names or [])[:40], ensure_ascii=False),
                    str(model_used or ""),
                    str(model_source or ""),
                    str(answer or ""),
                    _json.dumps(list(risk_flags or []), ensure_ascii=False),
                    _json.dumps(list(quality_flags or []), ensure_ascii=False),
                    datetime.now().isoformat(timespec="seconds"),
                    str(session.get("user") or ""),
                ),
            )
            con.commit()
            return True
    except Exception:
        return False


def _recent_ai_anomaly_screenings_html(patient_key, limit=5):
    import json as _json
    try:
        with db_conn() as con:
            _ensure_ai_anomaly_screening_schema(con)
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            rows = con.execute(
                "SELECT * FROM ai_anomaly_screenings WHERE patient_key=? "
                "ORDER BY created_at DESC LIMIT ?",
                (patient_key, int(limit or 5)),
            ).fetchall()
    except Exception:
        rows = []
    if not rows:
        return (
            '<div class="alert alert-light border">'
            'Henuz kayitli lokal anomali on tarama raporu yok.</div>')
    cards = []
    for row in rows:
        try:
            risks = _json.loads(row.get("risk_flags") or "[]")
        except Exception:
            risks = []
        try:
            quality = _json.loads(row.get("quality_flags") or "[]")
        except Exception:
            quality = []
        excerpt = " ".join(str(row.get("answer") or "").split())[:900]
        badges = "".join(
            f'<span class="badge bg-danger me-1">{sh(x)}</span>'
            for x in list(risks or [])[:6])
        qbadges = "".join(
            f'<span class="badge bg-secondary me-1">{sh(x)}</span>'
            for x in list(quality or [])[:4])
        cards.append(f"""
        <details class="card mb-2">
          <summary class="card-header" style="cursor:pointer;">
            <b>{sh(row.get('created_at') or '')}</b>
            <span class="text-muted ms-2">{sh(row.get('model_used') or '')}</span>
            <span class="badge bg-primary ms-2">{int(row.get('source_count') or 0)} gorsel</span>
          </summary>
          <div class="card-body">
            <div class="mb-2">{badges or '<span class="badge bg-success">risk bayragi yok</span>'}</div>
            <div class="mb-2">{qbadges}</div>
            <div class="small" style="white-space:pre-wrap;">{safe_html(excerpt)}</div>
          </div>
        </details>
        """)
    return "".join(cards)


def call_ollama(prompt, model=None, temperature=None,
                  max_tokens=None, timeout=None, use_cache=True,
                  system=None, images=None):
    """ğŸ¤– Ortak Ollama Ã§aÄŸrÄ± fonksiyonu.

 TÃ¼m YZ route'larÄ± bunu kullanmalÄ±. Cache, hata yÃ¶netimi,
 fallback mekanizmasÄ± dahil.

 Args:
 prompt: YZ'ye gÃ¶nderilecek ana metin
 model: Model adi (default: gpt-oss:20b)
 temperature: 0.0-1.0 (default: 0.3)
 max_tokens: Max cevap uzunluÄŸu (default: 2048)
 timeout: Saniye (default: 180)
 use_cache: AynÄ± prompt tekrarsa cache'ten dÃ¶ner
 system: Sistem prompt'u (varsa baÅŸa eklenir)

 Returns:
 (success: bool, response_or_error: str, duration_ms: int)
 """
    import urllib.request as _urllib_req
    import urllib.error as _urllib_err
    import json as _json
    import hashlib as _hash
    import time as _t

    prompt = (prompt or "").strip()
    images = [img for img in (images or []) if img]
    task_name = _ollama_task_from_context(system=system, images=bool(images))
    if not prompt:
        return (False, "âŒ BoÅŸ YZ istemi", 0)

    chosen_provider = _ai_provider_value()
    if not images and chosen_provider != "ollama":
        tried_cloud = []
        cloud_model = model if chosen_provider in {
            "openai", "claude", "deepseek", "gemini"
        } else None
        ok, answer, duration_ms, used_provider = _b301_try_cloud_by_strategy(
            prompt,
            tried_log=tried_cloud,
            model=cloud_model,
            temperature=temperature,
            max_tokens=max_tokens,
            timeout=timeout,
            use_cache=use_cache,
            system=system,
            images=images)
        if ok and answer:
            return (True, answer, duration_ms)
        # Strict online/cloud secildiyse sessiz Ollama fallback yapma.
        if _ai_provider_is_strict_online(chosen_provider):
            tried_text = ", ".join(tried_cloud) or "bulut saglayici offline"
            detail = (f"Secili online YZ cevap veremedi ({tried_text}). "
                      "Ayarlar > Yapay Zeka'dan key/model kontrol edin.")
            return (False, detail, duration_ms or 0)

    _refresh_ai_config()
    # Terminal PC'ler server YZ'yi kullanir. DB'de eski/yanlis Ollama URL
    # kaldiysa status kontrolu calisan server-localhost adresine dondurur.
    if not _ollama_status().get("online"):
        _ollama_status(force=True)
    if model is None:
        model = _select_ollama_model(
            vision=bool(images), task=task_name, system=system)
    elif images and not _is_ollama_vision_model(model):
        vision_model = _select_ollama_model(vision=True)
        if vision_model:
            model = vision_model
    if images and not model:
        return (False,
                "Ollama vision model bulunamadi. Oneri: qwen3-vl:30b "
                "veya llama3.2-vision:11b kurup YZ Sihirbazi'ndan "
                "Goruntu/USG modeli olarak aktif edin.",
                0)
    if _is_auto_model_value(model):
        model = _select_ollama_model(
            vision=bool(images), task=task_name, system=system)
    model = _normalize_ollama_model_name(model or _AI_CONFIG["model"])
    runtime_defaults = _ollama_runtime_defaults(
        task_name, model_name=model, has_images=bool(images))
    if temperature is None:
        temperature = runtime_defaults.get(
            "temperature", _AI_CONFIG["default_options"]["temperature"])
    if max_tokens is None:
        max_tokens = runtime_defaults.get(
            "num_predict", _AI_CONFIG["default_options"]["num_predict"])
    if timeout is None:
        timeout = runtime_defaults.get("timeout", _AI_CONFIG["default_timeout"])
    try:
        timeout = max(10, min(int(timeout), 600))
    except Exception:
        timeout = _AI_CONFIG["default_timeout"]
    try:
        max_tokens = max(128, min(int(max_tokens), 4096))
    except Exception:
        max_tokens = _AI_CONFIG["default_options"]["num_predict"]

    full_prompt = prompt
    if system:
        full_prompt = f"[SÄ°STEM]\n{system}\n\n{prompt}"

    # Cache kontrol
    cache_key = None
    if images:
        use_cache = False
    if use_cache:
        try:
            cache_key = _hash.md5(
                f"{model}:{full_prompt}".encode()).hexdigest()
            now = _t.time()
            with _AI_CACHE_LOCK:
                if cache_key in _AI_CACHE:
                    ts, cached = _AI_CACHE[cache_key]
                    if now - ts < _AI_CACHE_TTL:
                        return (True, cached, 0)
        except Exception:
            cache_key = None

    start = _t.time()
    try:
        payload_obj = {
            "model": model,
            "prompt": full_prompt,
            "stream": False,
            "keep_alive": _AI_CONFIG.get("keep_alive", "10m"),
            "options": {
                "temperature": temperature,
                "num_predict": max_tokens,
                "num_ctx": runtime_defaults.get(
                    "num_ctx", _AI_CONFIG["default_options"]["num_ctx"]),
            },
        }
        for opt_key in ("num_batch", "num_gpu", "num_thread"):
            if opt_key in runtime_defaults:
                payload_obj["options"][opt_key] = runtime_defaults[opt_key]
        _apply_ollama_think_policy(payload_obj, model)
        if images:
            payload_obj["images"] = images
        payload = _json.dumps(payload_obj).encode("utf-8")

        req = _urllib_req.Request(
            _AI_CONFIG["url"],
            data=payload,
            headers={"Content-Type": "application/json"})

        with _urllib_req.urlopen(req, timeout=timeout) as resp:
            data = _json.loads(resp.read().decode("utf-8"))
            answer = _ollama_extract_final_answer(data)

        if not answer and data.get("thinking"):
            try:
                retry_obj = dict(payload_obj)
                retry_obj["prompt"] = _ollama_retry_prompt_without_thinking(
                    full_prompt)
                retry_options = dict(payload_obj.get("options") or {})
                retry_options["temperature"] = min(
                    float(temperature or 0.2), 0.2)
                retry_options["num_predict"] = min(max(int(max_tokens), 900), 1536)
                retry_obj["options"] = retry_options
                retry_payload = _json.dumps(retry_obj).encode("utf-8")
                retry_req = _urllib_req.Request(
                    _AI_CONFIG["url"],
                    data=retry_payload,
                    headers={"Content-Type": "application/json"})
                with _urllib_req.urlopen(retry_req, timeout=timeout) as resp:
                    retry_data = _json.loads(resp.read().decode("utf-8"))
                    answer = _ollama_extract_final_answer(retry_data)
            except Exception:
                answer = ""

        duration_ms = int((_t.time() - start) * 1000)
        if not answer:
            reason = data.get("done_reason") or ""
            if reason == "length":
                return (False,
                        "Ollama final cevabi tamamlayamadi. Token siniri "
                        "kisa kaldi; daha uzun cevap limitiyle tekrar deneyin.",
                        duration_ms)
            if data.get("thinking"):
                return (False,
                        "Ollama final cevap yerine sadece dusunme cikisi "
                        "dondurdu. Modeli veya cevap limitini kontrol edin.",
                        duration_ms)

        # Cache'e koy
        if cache_key and answer:
            try:
                with _AI_CACHE_LOCK:
                    if len(_AI_CACHE) > _AI_CACHE_MAX:
                        keys = sorted(_AI_CACHE.keys(),
                                        key=lambda k: _AI_CACHE[k][0])
                        for k in keys[:20]:
                            _AI_CACHE.pop(k, None)
                    _AI_CACHE[cache_key] = (_t.time(), answer)
            except Exception:
                pass

        return (True, answer, duration_ms)

    except _urllib_err.URLError as ex:
        return (False,
                 ("âŒ Ollama baÄŸlantÄ±sÄ± kurulamadÄ±. "
                  "Server PC'de Ollama Ã§alÄ±ÅŸÄ±yor mu? "
                  f"Detay: {ex}"),
                 int((_t.time() - start) * 1000))
    except Exception as ex:
        return (False, f"âŒ YZ hatasÄ±: {ex}",
                 int((_t.time() - start) * 1000))


def ollama_available():
    """YZ servis ÅŸu anda Ã§alÄ±ÅŸÄ±yor mu? (hÄ±zlÄ± check)"""
    try:
        return bool(_ai_strategy_pick_active_provider(images=False))
    except Exception:
        return bool(openai_available() or _ollama_status().get("online"))


