def _doctor_display_name():
    """Current doctor name for AI prompts and UI greetings."""
    try:
        name = (get_clinic_doctor_name() or "").strip()
    except Exception:
        name = ""
    if not name or name.lower() == "doktor":
        name = "Dr.Hakan YAZ"
    return name


def _doctor_ai_system(role="clinical"):
    doctor_name = _doctor_display_name()
    return (
        "Sen YazKlinik icinde calisan klinik is ve karar destek "
        "asistanisin. Turkce, net, sakin ve ise yarar cevap ver. "
        "Kullanici emir verdiginde once yapilabilir eylemi uygula ya da "
        "guvenli aksiyon hazirla; sadece sohbet ederek gecistirme. "
        f"Kullanicinin adi {doctor_name}; ona gerekiyorsa '{doctor_name}' "
        "veya 'doktorum' diye hitap et. "
        "Tibbi konularda kesin tani koyma; klinik karar hekime aittir. "
        f"Rol baglami: {role}."
    )


def _patient_context_for_ai(patient_key, include_labs=True, include_usg=True):
    """Build compact patient context for local LLM calls."""
    lines = [f"Hasta anahtari: {patient_key}"]
    try:
        demo = load_patient_demographics(patient_key) or {}
        if demo.get("age"):
            lines.append(f"Yas: {demo.get('age')}")
        if demo.get("weight"):
            lines.append(f"Kilo: {demo.get('weight')} kg")
        if demo.get("height"):
            lines.append(f"Boy: {demo.get('height')} cm")
        if demo.get("blood_type"):
            lines.append(f"Kan grubu: {demo.get('blood_type')}")
        if demo.get("gravida") is not None:
            lines.append(
                "GPAL: "
                f"G{demo.get('gravida') or 0} "
                f"P{demo.get('para') or 0} "
                f"A{demo.get('abortus') or 0} "
                f"L{demo.get('living') or 0}"
            )
        if demo.get("lmp_override"):
            parts = str(demo["lmp_override"]).split(".")
            if len(parts) == 3:
                lmp_dt = datetime(int(parts[2]), int(parts[1]), int(parts[0]))
                ga_days = (datetime.now() - lmp_dt).days
                if 0 <= ga_days <= 320:
                    lines.append(f"Gebelik haftasi: {ga_days // 7}+{ga_days % 7}")
        for key, label in (
            ("chronic_conditions", "Kronik hastalik"),
            ("medications", "Ilaclar"),
            ("allergies", "Alerjiler"),
        ):
            if demo.get(key):
                lines.append(f"{label}: {demo.get(key)}")
    except Exception:
        pass

    try:
        flags = get_patient_flags(patient_key) or {}
        active = [
            PATIENT_FLAG_LABELS.get(k, k)
            for k, v in flags.items()
            if isinstance(v, dict) and v.get("value") == "1"
        ]
        if active:
            lines.append("Aktif riskler: " + ", ".join(active))
    except Exception:
        pass

    if include_usg:
        try:
            with db_conn() as con:
                con.row_factory = lambda cur, row: {
                    d[0]: row[i] for i, d in enumerate(cur.description)}
                rows = con.execute(
                    "SELECT * FROM usg_measurements WHERE patient_key=? "
                    "ORDER BY usg_date DESC LIMIT 5",
                    (patient_key,)).fetchall()
            if rows:
                lines.append("[Son USG olcumleri]")
                for u in rows:
                    parts = []
                    for key, label in (
                        ("usg_date", "Tarih"), ("ga_weeks", "GA"),
                        ("crl", "CRL"), ("nt", "NT"), ("bpd", "BPD"),
                        ("hc", "HC"), ("ac", "AC"), ("fl", "FL"),
                        ("efw", "EFW"), ("afi", "AFI"),
                        ("placenta", "Plasenta"),
                        ("fetal_position", "Pozisyon"),
                    ):
                        val = u.get(key)
                        if val not in (None, ""):
                            parts.append(f"{label}: {val}")
                    if u.get("notes"):
                        parts.append(f"Not: {u.get('notes')}")
                    if parts:
                        lines.append("- " + "; ".join(parts))
        except Exception:
            pass

    if include_labs:
        try:
            labs = list_lab_results(patient_key)[:3]
            if labs:
                lines.append("[Son tahliller]")
                for lab in labs:
                    values = lab.get("values") or {}
                    sample = []
                    for tn, tv in list(values.items())[:16]:
                        if isinstance(tv, dict):
                            sample.append(
                                f"{tn}: {tv.get('value')} {tv.get('unit', '')}".strip())
                        else:
                            sample.append(f"{tn}: {tv}")
                    if sample:
                        lines.append("- " + "; ".join(sample))
        except Exception:
            pass

    return "\n".join(lines)


def _patient_latest_clinical_snapshot(patient_key):
    """Collect the newest visit, USG and vital data for AI workflows."""
    snap = {"latest_visit": None, "latest_usg": None,
            "latest_vitals": None, "latest_labs": []}
    try:
        with db_conn() as con:
            _ensure_visit_clinical_schema(con)
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            try:
                snap["latest_visit"] = con.execute(
                    "SELECT * FROM visits WHERE patient_folder_key=? "
                    "ORDER BY COALESCE(visit_date, '') DESC, "
                    "COALESCE(folder_mtime, 0) DESC, visit_key DESC LIMIT 1",
                    (patient_key,)).fetchone()
            except Exception:
                pass
            try:
                snap["latest_usg"] = con.execute(
                    "SELECT * FROM usg_measurements WHERE patient_key=? "
                    "ORDER BY COALESCE(usg_date, '') DESC, id DESC LIMIT 1",
                    (patient_key,)).fetchone()
            except Exception:
                pass
            try:
                snap["latest_vitals"] = con.execute(
                    "SELECT * FROM exam_vitals WHERE patient_key=? "
                    "ORDER BY COALESCE(measured_at, '') DESC, id DESC LIMIT 1",
                    (patient_key,)).fetchone()
            except Exception:
                pass
    except Exception:
        pass
    try:
        snap["latest_labs"] = list_lab_results(patient_key)[:5]
    except Exception:
        snap["latest_labs"] = []
    return snap


def _snapshot_lines_for_diet(snapshot):
    lines = []
    visit = snapshot.get("latest_visit") or {}
    usg = snapshot.get("latest_usg") or {}
    vitals = snapshot.get("latest_vitals") or {}
    if visit:
        lines.append(
            "Son gelis: "
            f"{visit.get('visit_date') or ''} / {visit.get('visit_key') or ''}".strip())
    if usg:
        parts = []
        if usg.get("usg_date"):
            parts.append(f"USG tarihi: {usg.get('usg_date')}")
        if usg.get("ga_weeks") is not None:
            parts.append(f"Gebelik haftasi: {usg.get('ga_weeks')}+{usg.get('ga_days') or 0}")
        if usg.get("efw"):
            parts.append(f"Bebek tahmini kilo: {usg.get('efw')} g")
        if usg.get("afi"):
            parts.append(f"AFI: {usg.get('afi')}")
        if parts:
            lines.append("Son USG: " + ", ".join(parts))
    if vitals:
        parts = []
        if vitals.get("measured_at"):
            parts.append(f"Olcum: {str(vitals.get('measured_at'))[:16]}")
        if vitals.get("weight"):
            parts.append(f"Anne kilo: {vitals.get('weight')} kg")
        if vitals.get("bp_sys") or vitals.get("bp_dia"):
            parts.append(f"Tansiyon: {vitals.get('bp_sys')}/{vitals.get('bp_dia')}")
        if vitals.get("complaint"):
            parts.append(f"Sikayet: {vitals.get('complaint')}")
        if parts:
            lines.append("Son vital: " + ", ".join(parts))
    return lines


