def _diet_fold_v1000(value):
    text = _repair_mojibake_text(str(value or ""))
    replacements = (
        ("\u0131", "i"), ("\u0130", "I"),
        ("\u015f", "s"), ("\u015e", "S"),
        ("\u011f", "g"), ("\u011e", "G"),
        ("\u00fc", "u"), ("\u00dc", "U"),
        ("\u00f6", "o"), ("\u00d6", "O"),
        ("\u00e7", "c"), ("\u00c7", "C"),
        ("\u00c4\u00b1", "i"), ("\u00c4\u00b0", "I"),
        ("\u00c5\u0178", "s"), ("\u00c5\u009e", "S"),
        ("\u00c4\u0178", "g"), ("\u00c4\u009e", "G"),
        ("\u00c3\u00bc", "u"), ("\u00c3\u009c", "U"),
        ("\u00c3\u00b6", "o"), ("\u00c3\u0096", "O"),
        ("\u00c3\u00a7", "c"), ("\u00c3\u0087", "C"),
    )
    for src, dst in replacements:
        text = text.replace(src, dst)
    text = unicodedata.normalize("NFKD", text)
    return text.encode("ascii", "ignore").decode("ascii").lower()


def _diet_has_any_v1000(value, tokens):
    folded = _diet_fold_v1000(value)
    return any(str(token).lower() in folded for token in tokens)


def _diet_strip_leading_ack_v1000(text):
    """D13: Diyet AI cevabinin basindaki 'Elbette ... hazirliyorum' gibi
    gereksiz acilis satirini temizle."""
    raw = str(text or "")
    if not raw:
        return ""
    lines = raw.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    while True:
        idx = None
        for i, line in enumerate(lines):
            if line.strip():
                idx = i
                break
        if idx is None:
            break
        first_fold = _diet_fold_v1000(lines[idx].strip())
        if first_fold.startswith("elbette"):
            del lines[idx]
            continue
        break
    return "\n".join(lines).strip()


_DIET_TR_MOJIBAKE_REPLACEMENTS_V1000 = (
    ("\u00c3\u00bc", "\u00fc"), ("\u00c3\u009c", "\u00dc"),
    ("\u00c3\u00b6", "\u00f6"), ("\u00c3\u0096", "\u00d6"),
    ("\u00c3\u00a7", "\u00e7"), ("\u00c3\u0087", "\u00c7"),
    ("\u00c4\u00b1", "\u0131"), ("\u00c4\u00b0", "\u0130"),
    ("\u00c5\u0178", "\u015f"), ("\u00c5\u009e", "\u015e"),
    ("\u00c4\u0178", "\u011f"), ("\u00c4\u009e", "\u011e"),
    ("\u00c2\u00a0", " "), ("\u00c2\u00b7", " "),
    ("\u00c2", ""),
)


def _diet_light_mojibake_clean_v1000(value, collapse=True):
    """Patient-facing diet text cleaner for AI markdown and saved HTML."""
    text = str(value or "")
    if not text:
        return ""
    try:
        text = fix_mojibake_text(text)
    except Exception:
        try:
            text = _repair_mojibake_text(text)
        except Exception:
            pass
    for _ in range(2):
        before = text
        for bad, good in _DIET_TR_MOJIBAKE_REPLACEMENTS_V1000:
            text = text.replace(bad, good)
        if text == before:
            break
    # Drop mojibake emoji clusters such as "ğŸŒ‡" / "ðŸ..." before titles.
    text = re.sub(
        "(?:[\u011f\u011e\u00f0\u00d0]\u0178|"
        "\u00c3\u00b0\u00c5\u00b8|"
        "\u00c3\u0192\u00c2\u00b0\u00c3\u2026\u00c2\u00b8)[^\\s<]*",
        " ",
        text,
    )
    text = text.replace("\u00a0", " ")
    if collapse:
        text = re.sub(r"\s+", " ", text).strip()
    return text


def _diet_display_text_v1000(value):
    """Diet output is patient-facing; repair mojibake before HTML/PDF render."""
    text = _diet_light_mojibake_clean_v1000(value)
    if not text:
        return ""
    text = text.replace("**", "")
    # Broken emoji fragments such as "ğŸŒ..." are worse than no icon.
    text = re.sub(r"(^|\s)[ğĞ]Ÿ[^\s:|,;)]*", " ", text)
    text = re.sub(r"(^|\s)â[^\s:|,;)]{1,8}", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def _diet_display_block_text_v1000(value):
    raw = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    return "\n".join(_diet_display_text_v1000(line) for line in raw.split("\n")).strip()


