def _diet_sanitize_saved_html_v1000(html_text):
    text = _diet_light_mojibake_clean_v1000(html_text, collapse=False)
    if not text:
        return ""
    import html as _html

    def _replace_day_icon(match):
        return f"{match.group(1)}G\u00fcn{match.group(3)}"

    text = re.sub(
        r'(<span\b[^>]*class=["\'][^"\']*yk-ai-day-emoji[^"\']*["\'][^>]*>)(.*?)(</span>)',
        _replace_day_icon,
        text,
        flags=re.I | re.S,
    )

    def _replace_day_h5(match):
        inner = match.group(2)
        plain = re.sub(r"<[^>]+>", " ", inner)
        title = _diet_day_title_v1000(_html.unescape(plain))
        if not title:
            return match.group(0)
        return f"{match.group(1)}{safe_html(title)}{match.group(3)}"

    text = re.sub(
        r"(<h5\b[^>]*>)(.*?)(</h5>)",
        _replace_day_h5,
        text,
        flags=re.I | re.S,
    )

    def _replace_plan_h4(match):
        inner = match.group(2)
        plain = _diet_display_text_v1000(_html.unescape(re.sub(r"<[^>]+>", " ", inner)))
        fold = _diet_fold_v1000(plain)
        if "gunluk" in fold and "plan" in fold:
            return f"{match.group(1)}7 G\u00fcnl\u00fck Plan{match.group(3)}"
        return f"{match.group(1)}{safe_html(plain) if plain else inner}{match.group(3)}"

    text = re.sub(
        r"(<h4\b[^>]*>)(.*?)(</h4>)",
        _replace_plan_h4,
        text,
        flags=re.I | re.S,
    )
    if "yk-diet-readability-d104" not in text:
        if "</head>" in text:
            text = text.replace("</head>", _DIET_SAVED_HTML_READABILITY_CSS_V1000 + "\n</head>", 1)
        elif "</style>" in text:
            text = text.replace("</style>", "</style>\n" + _DIET_SAVED_HTML_READABILITY_CSS_V1000, 1)
        else:
            text = _DIET_SAVED_HTML_READABILITY_CSS_V1000 + text
    return text


def _diet_metric_float_v1000(value, low=None, high=None):
    if value in (None, ""):
        return None
    try:
        text = str(value).replace(",", ".")
        match = re.search(r"-?\d+(?:\.\d+)?", text)
        if not match:
            return None
        number = float(match.group(0))
        if low is not None and number < low:
            return None
        if high is not None and number > high:
            return None
        return number
    except Exception:
        return None


def _diet_metric_int_v1000(value, low=None, high=None):
    number = _diet_metric_float_v1000(value, low=low, high=high)
    if number is None:
        return None
    return int(round(number))


def _diet_metric_date_age_v1000(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%d-%m-%Y"):
        try:
            born = datetime.strptime(raw[:10], fmt).date()
            today = datetime.now().date()
            age = today.year - born.year - (
                (today.month, today.day) < (born.month, born.day))
            return age if 1 < age <= 120 else None
        except Exception:
            pass
    return None


def _diet_find_deep_value_v1000(obj, keys):
    folded_keys = {_diet_fold_v1000(k) for k in keys}
    if isinstance(obj, dict):
        for key, value in obj.items():
            if _diet_fold_v1000(key) in folded_keys and value not in (None, ""):
                return value
        for value in obj.values():
            found = _diet_find_deep_value_v1000(value, keys)
            if found not in (None, ""):
                return found
    elif isinstance(obj, list):
        for value in obj:
            found = _diet_find_deep_value_v1000(value, keys)
            if found not in (None, ""):
                return found
    return None


def _diet_table_cols_v1000(con, table):
    try:
        return {str(row[1]) for row in con.execute(
            f"PRAGMA table_info({table})").fetchall()}
    except Exception:
        return set()


def _diet_ensure_metric_schema_v1000(con):
    try:
        con.execute("""
            CREATE TABLE IF NOT EXISTS patient_demographics (
                patient_key TEXT PRIMARY KEY,
                updated_at TEXT
            )
        """)
    except Exception:
        pass
    cols = _diet_table_cols_v1000(con, "patient_demographics")
    for col, ddl in (
        ("age", "ALTER TABLE patient_demographics ADD COLUMN age INTEGER"),
        ("birth_date", "ALTER TABLE patient_demographics ADD COLUMN birth_date TEXT"),
        ("weight", "ALTER TABLE patient_demographics ADD COLUMN weight REAL"),
        ("height", "ALTER TABLE patient_demographics ADD COLUMN height REAL"),
        ("bmi", "ALTER TABLE patient_demographics ADD COLUMN bmi REAL"),
        ("pre_pregnancy_weight",
         "ALTER TABLE patient_demographics ADD COLUMN pre_pregnancy_weight REAL"),
    ):
        if col in cols:
            continue
        try:
            con.execute(ddl)
            cols.add(col)
        except Exception:
            pass
    return cols


def _diet_patient_db_metrics_v1000(patient_key):
    metrics = {
        "age": None, "weight": None, "height": None,
        "bmi": None, "pre_weight": None, "sources": {},
    }

    def set_metric(name, value, source, kind="float", low=None, high=None):
        if metrics.get(name) is not None:
            return
        if name == "age":
            parsed = _web_patient_profile_age_v1000(value)
        else:
            parsed = (
                _diet_metric_int_v1000(value, low=low, high=high)
                if kind == "int"
                else _diet_metric_float_v1000(value, low=low, high=high))
        if parsed is None:
            return
        metrics[name] = parsed
        metrics["sources"][name] = source

    age_keys = ("age", "yas", "yaÅŸ", "patient_age", "hasta_yasi", "hasta_yasi")
    birth_keys = ("birth_date", "birthdate", "date_of_birth", "dogum_tarihi", "dob")
    weight_keys = (
        "weight", "weight_kg", "kilo", "current_weight", "mevcut_kilo",
        "anne_kilo", "mother_weight", "kg")
    height_keys = ("height", "height_cm", "boy", "boy_cm", "cm")
    bmi_keys = ("bmi", "vki", "body_mass_index")
    pre_weight_keys = (
        "pre_pregnancy_weight", "pre_weight", "prepregnancy_weight",
        "gebelik_oncesi_kilo", "gebelik_oncesi_weight")

    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            _diet_ensure_metric_schema_v1000(con)

            try:
                row = con.execute(
                    "SELECT age, notes FROM patient_type WHERE patient_key=?",
                    (patient_key,)).fetchone()
                if row:
                    set_metric("age", row.get("age"), "patient_type.age",
                               kind="int", low=0, high=120)
                    notes = row.get("notes") or ""
                    set_metric("age", _diet_find_number_v1000(
                        notes, (r"(?:yas|yaÅŸ|age)\s*[:=]?\s*(\d{1,3})",)),
                        "patient_type.notes", kind="int", low=0, high=120)
                    set_metric("weight", _diet_find_number_v1000(
                        notes, (r"(?:kilo|weight)\s*[:=]?\s*(\d{2,3}(?:[.,]\d+)?)",)),
                        "patient_type.notes", low=20, high=250)
                    set_metric("height", _diet_find_number_v1000(
                        notes, (r"(?:boy|height)\s*[:=]?\s*(\d{2,3}(?:[.,]\d+)?)",)),
                        "patient_type.notes", low=90, high=230)
                    set_metric("bmi", _diet_find_number_v1000(
                        notes, (r"(?:bmi|vki)\s*[:=]?\s*(\d{2}(?:[.,]\d+)?)",)),
                        "patient_type.notes", low=10, high=80)
            except Exception:
                pass

            try:
                cols = _diet_table_cols_v1000(con, "patient_demographics")
                row = con.execute(
                    "SELECT * FROM patient_demographics WHERE patient_key=?",
                    (patient_key,)).fetchone()
                if row:
                    canonical_age = _web_patient_profile_age_v1000(
                        row.get("age"))
                    if canonical_age is not None:
                        metrics["age"] = canonical_age
                        metrics["sources"]["age"] = "patient_demographics.age"
                    if metrics.get("age") is None:
                        age_from_birth = _diet_metric_date_age_v1000(
                            row.get("birth_date"))
                        set_metric("age", age_from_birth,
                                   "patient_demographics.birth_date",
                                   kind="int", low=0, high=120)
                    set_metric("weight", row.get("weight"),
                               "patient_demographics.weight", low=20, high=250)
                    set_metric("height", row.get("height"),
                               "patient_demographics.height", low=90, high=230)
                    set_metric("bmi", row.get("bmi"),
                               "patient_demographics.bmi", low=10, high=80)
                    set_metric("pre_weight", row.get("pre_pregnancy_weight"),
                               "patient_demographics.pre_pregnancy_weight",
                               low=20, high=250)
                    if "data_json" in cols and row.get("data_json"):
                        try:
                            import json as _json
                            data = _json.loads(row.get("data_json") or "{}")
                        except Exception:
                            data = {}
                        set_metric("age", _diet_find_deep_value_v1000(data, age_keys),
                                   "patient_demographics.data_json.age",
                                   kind="int", low=0, high=120)
                        if metrics.get("age") is None:
                            set_metric("age", _diet_metric_date_age_v1000(
                                _diet_find_deep_value_v1000(data, birth_keys)),
                                "patient_demographics.data_json.birth_date",
                                kind="int", low=0, high=120)
                        set_metric("weight", _diet_find_deep_value_v1000(data, weight_keys),
                                   "patient_demographics.data_json.weight",
                                   low=20, high=250)
                        set_metric("height", _diet_find_deep_value_v1000(data, height_keys),
                                   "patient_demographics.data_json.height",
                                   low=90, high=230)
                        set_metric("bmi", _diet_find_deep_value_v1000(data, bmi_keys),
                                   "patient_demographics.data_json.bmi",
                                   low=10, high=80)
                        set_metric("pre_weight", _diet_find_deep_value_v1000(
                            data, pre_weight_keys),
                            "patient_demographics.data_json.pre_weight",
                            low=20, high=250)
            except Exception:
                pass

            try:
                row = con.execute(
                    "SELECT weight FROM exam_vitals WHERE patient_key=? "
                    "AND weight IS NOT NULL "
                    "ORDER BY COALESCE(measured_at, '') DESC, id DESC LIMIT 1",
                    (patient_key,)).fetchone()
                if row:
                    set_metric("weight", row.get("weight"),
                               "exam_vitals.latest.weight", low=20, high=250)
            except Exception:
                pass

            for table in ("obstetric_form", "gynec_form"):
                try:
                    if "data_json" not in _diet_table_cols_v1000(con, table):
                        continue
                    row = con.execute(
                        f"SELECT data_json FROM {table} WHERE patient_key=?",
                        (patient_key,)).fetchone()
                    if not row or not row.get("data_json"):
                        continue
                    import json as _json
                    data = _json.loads(row.get("data_json") or "{}")
                    set_metric("age", _diet_find_deep_value_v1000(data, age_keys),
                               f"{table}.data_json.age",
                               kind="int", low=0, high=120)
                    if metrics.get("age") is None:
                        set_metric("age", _diet_metric_date_age_v1000(
                            _diet_find_deep_value_v1000(data, birth_keys)),
                            f"{table}.data_json.birth_date",
                            kind="int", low=0, high=120)
                    set_metric("weight", _diet_find_deep_value_v1000(data, weight_keys),
                               f"{table}.data_json.weight", low=20, high=250)
                    set_metric("height", _diet_find_deep_value_v1000(data, height_keys),
                               f"{table}.data_json.height", low=90, high=230)
                    set_metric("bmi", _diet_find_deep_value_v1000(data, bmi_keys),
                               f"{table}.data_json.bmi", low=10, high=80)
                    set_metric("pre_weight", _diet_find_deep_value_v1000(
                        data, pre_weight_keys),
                        f"{table}.data_json.pre_weight", low=20, high=250)
                except Exception:
                    continue
            con.commit()
    except Exception:
        pass
    return metrics


def _diet_save_patient_db_metrics_v1000(patient_key, age=None, weight=None,
                                        height=None, bmi=None,
                                        pre_weight=None, overwrite=True):
    if not patient_key:
        return
    age = _web_patient_profile_age_v1000(age)
    weight = _diet_metric_float_v1000(weight, low=20, high=250)
    height = _diet_metric_float_v1000(height, low=90, high=230)
    bmi = _diet_metric_float_v1000(bmi, low=10, high=80)
    if bmi is None and weight is not None and height is not None:
        try:
            h_m = float(height) / 100.0
            if h_m > 0:
                bmi = round(float(weight) / (h_m * h_m), 1)
        except Exception:
            bmi = None
    pre_weight = _diet_metric_float_v1000(pre_weight, low=20, high=250)
    if (age is None and weight is None and height is None and
            bmi is None and pre_weight is None):
        return
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    try:
        with db_conn() as con:
            _diet_ensure_metric_schema_v1000(con)
            if overwrite:
                age_expr = "COALESCE(excluded.age, patient_demographics.age)"
                weight_expr = "COALESCE(excluded.weight, patient_demographics.weight)"
                height_expr = "COALESCE(excluded.height, patient_demographics.height)"
                bmi_expr = "COALESCE(excluded.bmi, patient_demographics.bmi)"
                pre_expr = (
                    "COALESCE(excluded.pre_pregnancy_weight, "
                    "patient_demographics.pre_pregnancy_weight)")
            else:
                age_expr = "COALESCE(patient_demographics.age, excluded.age)"
                weight_expr = "COALESCE(patient_demographics.weight, excluded.weight)"
                height_expr = "COALESCE(patient_demographics.height, excluded.height)"
                bmi_expr = "COALESCE(patient_demographics.bmi, excluded.bmi)"
                pre_expr = (
                    "COALESCE(patient_demographics.pre_pregnancy_weight, "
                    "excluded.pre_pregnancy_weight)")
            con.execute(
                "INSERT INTO patient_demographics("
                "patient_key, age, weight, height, bmi, "
                "pre_pregnancy_weight, updated_at"
                ") VALUES(?,?,?,?,?,?,?) "
                "ON CONFLICT(patient_key) DO UPDATE SET "
                f"age={age_expr}, "
                f"weight={weight_expr}, "
                f"height={height_expr}, "
                f"bmi={bmi_expr}, "
                f"pre_pregnancy_weight={pre_expr}, "
                "updated_at=excluded.updated_at",
                (patient_key, age, weight, height, bmi, pre_weight, now))
            con.commit()
    except Exception:
        pass


def _web_sync_patient_profile_v1000(patient_key, age=None, weight=None,
                                    height=None, bmi=None, pre_weight=None,
                                    lmp_text=None):
    if not patient_key:
        return
    age = _web_patient_profile_age_v1000(age)
    weight = _web_patient_profile_metric_float_v1000(weight, low=20, high=250)
    height = _web_patient_profile_metric_float_v1000(height, low=90, high=230)
    bmi = _web_patient_profile_metric_float_v1000(bmi, low=10, high=80)
    pre_weight = _web_patient_profile_metric_float_v1000(
        pre_weight, low=20, high=250)
    lmp_day = _preg_plan_parse_date_v1000(lmp_text) if lmp_text else None
    if (age is None and weight is None and height is None and bmi is None and
            pre_weight is None and not lmp_day):
        return
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    try:
        with db_conn() as con:
            _web_ensure_patient_demographics_schema_v1000(con)
            lmp_value = _preg_plan_format_date_v1000(lmp_day) if lmp_day else None
            con.execute(
                "INSERT INTO patient_demographics("
                "patient_key, age, weight, height, bmi, pre_pregnancy_weight, "
                "lmp_override, updated_at"
                ") VALUES (?, ?, ?, ?, ?, ?, ?, ?) "
                "ON CONFLICT(patient_key) DO UPDATE SET "
                "age=COALESCE(patient_demographics.age, excluded.age), "
                "weight=COALESCE(patient_demographics.weight, excluded.weight), "
                "height=COALESCE(patient_demographics.height, excluded.height), "
                "bmi=COALESCE(patient_demographics.bmi, excluded.bmi), "
                "pre_pregnancy_weight=COALESCE("
                "patient_demographics.pre_pregnancy_weight, "
                "excluded.pre_pregnancy_weight), "
                "lmp_override=COALESCE("
                "NULLIF(patient_demographics.lmp_override, ''), "
                "excluded.lmp_override), "
                "updated_at=excluded.updated_at",
                (patient_key, age, weight, height, bmi, pre_weight, lmp_value, now))
            con.commit()
    except Exception:
        pass


def _diet_prefill_patient_metrics_from_pdfs_v1000(patient_key, db_metrics=None):
    """Fill empty diet metrics once from cached/latest patient PDFs."""
    q_patient = str(patient_key or "").strip()
    if not q_patient:
        return False
    metrics = dict(db_metrics or {})

    def _missing(name):
        return metrics.get(name) in (None, "")

    needed = {
        "age": _missing("age"),
        "weight": _missing("weight"),
        "height": _missing("height"),
        "bmi": _missing("bmi"),
        "pre_weight": _missing("pre_weight"),
    }
    if not any(needed.values()):
        return False

    result = {}
    try:
        # Synchronous on first need; cached on later opens. This makes the
        # diet form usable immediately after the patient PDF lands.
        result = _patient_file_auto_apply_pdf_demographics(
            q_patient, force=False, max_pdfs=12) or {}
    except Exception:
        result = {}

    payload = result.get("payload") if isinstance(result, dict) else None
    if not isinstance(payload, dict):
        try:
            meta = _patient_file_load_data_json(q_patient) or {}
            payload = meta.get("pdf_patient_extract") or {}
        except Exception:
            payload = {}
    pdf_demo = (payload or {}).get("demographics") or {}
    if not isinstance(pdf_demo, dict):
        pdf_demo = {}

    age = pdf_demo.get("age") if needed["age"] else None
    weight = pdf_demo.get("weight") if needed["weight"] else None
    height = pdf_demo.get("height") if needed["height"] else None
    bmi = pdf_demo.get("bmi") if needed["bmi"] else None
    pre_weight = (
        pdf_demo.get("pre_pregnancy_weight") if needed["pre_weight"] else None)

    try:
        if age is None and needed["age"] and pdf_demo.get("birth_date"):
            age = _diet_metric_date_age_v1000(pdf_demo.get("birth_date"))
    except Exception:
        pass

    if any(v not in (None, "") for v in (age, weight, height, bmi, pre_weight)):
        _diet_save_patient_db_metrics_v1000(
            q_patient,
            age=age,
            weight=weight,
            height=height,
            bmi=bmi,
            pre_weight=pre_weight,
            overwrite=False,
        )
        return True
    return bool(isinstance(result, dict) and result.get("applied"))


def _diet_latest_labs_v1000(patient_key):
    relevant = {}
    rows = []
    try:
        rows = list_lab_results(patient_key)[:8]
    except Exception:
        rows = []
    lab_map = {
        "Hb": ("hemoglobin", "hgb", "hb"),
        "Glukoz": ("glukoz", "glucose", "seker", "sugar"),
        "OGTT": ("ogtt", "tolerans"),
        "HbA1c": ("hba1c", "a1c"),
        "Insulin": ("insulin", "insulin"),
        "TSH": ("tsh",),
        "Vit D": ("25 oh", "vitamin d", "d vitamini"),
        "Ferritin": ("ferritin",),
        "B12": ("b12", "kobalamin"),
        "Kolesterol": ("kolesterol", "ldl", "hdl"),
        "Trigliserit": ("trigliserit", "triglyceride"),
    }
    for lab in rows:
        values = lab.get("values") or {}
        for test_name, test_value in values.items():
            folded = _diet_fold_v1000(test_name)
            for label, tokens in lab_map.items():
                if label in relevant:
                    continue
                if any(token in folded for token in tokens):
                    relevant[label] = (
                        f"{test_value.get('value', '')} "
                        f"{test_value.get('unit', '')}").strip()
                    break
    return relevant


def _diet_number_from_match_v1000(value):
    try:
        text = str(value or "").replace(",", ".")
        text = re.sub(r"[^0-9.\-]", "", text)
        return float(text) if text else None
    except Exception:
        return None


def _diet_find_number_v1000(text, patterns):
    for pattern in patterns:
        try:
            match = re.search(pattern, text, re.IGNORECASE)
        except Exception:
            match = None
        if not match:
            continue
        value = _diet_number_from_match_v1000(match.group(1))
        if value is not None:
            return value
    return None


def _diet_parse_date_text_v1000(text):
    match = re.search(r"\b(\d{2})[./-](\d{2})[./-](\d{4})\b", text)
    if match:
        return f"{match.group(1)}.{match.group(2)}.{match.group(3)}"
    match = re.search(r"\b(\d{4})[./-](\d{2})[./-](\d{2})\b", text)
    if match:
        return f"{match.group(3)}.{match.group(2)}.{match.group(1)}"
    return ""


def _diet_parse_efw_gram_candidate_v1000(value, require_unit=False):
    raw = _diet_fold_v1000(value)
    unit_match = re.search(
        r"\b(\d{2,5}(?:[.,]\d+)?)\s*(?:g|gr|gram|grams)\b", raw)
    if unit_match:
        parsed = _diet_number_from_match_v1000(unit_match.group(1))
    elif require_unit:
        return None
    else:
        match = re.search(r"\b(\d{2,5}(?:[.,]\d+)?)\b", raw)
        parsed = _diet_number_from_match_v1000(match.group(1)) if match else None
    if parsed is None:
        return None
    if 40 <= parsed <= 6500:
        return int(round(parsed))
    return None


def _diet_extract_efw_value_from_table_v1000(raw_text):
    """Voluson table: EFW (Hadlock/AC-BPD-FL) -> Value column -> grams."""
    lines = [
        _diet_fold_v1000(line).strip()
        for line in str(raw_text or "").splitlines()
        if _diet_fold_v1000(line).strip()
    ]

    def tableish(block):
        joined = " ".join(block)
        has_formula = (
            "hadlock" in joined or
            re.search(r"\bac\s*/?\s*bpd\s*/?\s*fl\b", joined) or
            all(re.search(rf"\b{token}\b", joined) for token in ("ac", "bpd", "fl")))
        return "efw" in joined and "value" in joined and has_formula

    for idx, line in enumerate(lines):
        if not re.search(r"\befw\b", line):
            continue
        block = lines[idx:min(len(lines), idx + 16)]
        if not tableish(block):
            continue
        for offset, block_line in enumerate(block):
            if "value" not in block_line:
                continue
            same_line = re.search(
                r"\bvalue\b\D{0,24}(\d{2,5}(?:[.,]\d+)?)\s*(?:g|gr|gram|grams)?\b",
                block_line)
            if same_line:
                value = _diet_parse_efw_gram_candidate_v1000(
                    same_line.group(1), require_unit=False)
                if value is not None:
                    return value
            for candidate_line in block[offset + 1:offset + 7]:
                if re.search(r"\b(?:bpd|hc|ac|fl|crl|nt|afi)\b", candidate_line):
                    continue
                value = _diet_parse_efw_gram_candidate_v1000(candidate_line)
                if value is not None:
                    return value

    flat = re.sub(r"\s+", " ", _diet_fold_v1000(raw_text))
    patterns = (
        r"\befw(?:\s*\([^)]*\))?.{0,140}?\b(?:ac\s*/?\s*bpd\s*/?\s*fl|ac.{0,20}bpd.{0,20}fl|bpd.{0,20}ac.{0,20}fl|hadlock).{0,80}?\bvalue\b\D{0,40}(\d{2,5}(?:[.,]\d+)?)\s*(?:g|gr|gram|grams)?\b",
        r"\befw(?:\s*\([^)]*\))?.{0,120}?\bvalue\b\D{0,40}(\d{2,5}(?:[.,]\d+)?)\s*(?:g|gr|gram|grams)?\b",
    )
    for pattern in patterns:
        match = re.search(pattern, flat, re.IGNORECASE)
        if not match:
            continue
        value = _diet_parse_efw_gram_candidate_v1000(
            match.group(1), require_unit=False)
        if value is not None:
            return value
    return None


def _diet_parse_fetal_pdf_text_v1000(raw_text):
    folded = _diet_fold_v1000(raw_text)
    text = re.sub(r"\s+", " ", folded)
    info = {}

    ga_patterns = (
        r"\b(?:ga|aog|gebelik\s*hafta\w*|gebelik\s*yas\w*|gestasyonel\s*yas\w*|gestational\s*age)\s*[:=]?\s*(\d{1,2})\s*(?:w|hf|hafta)?\s*[+ ]\s*(\d{1,2})\s*(?:d|gun)?",
        r"\b(\d{1,2})\s*w\s*(\d{1,2})\s*d\b",
        r"\b(\d{1,2})\s*hafta\s*(\d{1,2})\s*gun\b",
    )
    for pattern in ga_patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            try:
                ga_w = int(match.group(1))
                ga_d = int(match.group(2))
                if 3 <= ga_w <= 43 and 0 <= ga_d <= 6:
                    info["ga_w"] = ga_w
                    info["ga_d"] = ga_d
                    break
            except Exception:
                pass

    measurements = {
        "efw_g": (
            r"\befw\s*[:=]?\s*(\d{2,5})\s*(?:g|gr)?\b",
            r"estimated\s*fetal\s*weight\s*[:=]?\s*(\d{2,5})",
            r"tahmini\s*(?:fetal\s*)?(?:agirlik|agirligi)\s*[:=]?\s*(\d{2,5})",
        ),
        "bpd_mm": (r"\bbpd\s*[:=]?\s*(\d{1,3}(?:[.,]\d+)?)",),
        "hc_mm": (r"\bhc\s*[:=]?\s*(\d{1,3}(?:[.,]\d+)?)",),
        "ac_mm": (r"\bac\s*[:=]?\s*(\d{1,3}(?:[.,]\d+)?)",),
        "fl_mm": (r"\bfl\s*[:=]?\s*(\d{1,3}(?:[.,]\d+)?)",),
        "crl_mm": (r"\bcrl\s*[:=]?\s*(\d{1,3}(?:[.,]\d+)?)",),
        "nt_mm": (
            r"\bnt\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
            r"nuchal\s*translucency\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
        ),
        "afi_cm": (
            r"\bafi\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
            r"amniotic\s*fluid\s*index\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
            r"amniyon\s*sivi\s*indeksi\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
        ),
        "ua_pi": (
            r"\bua\s*pi\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
            r"umbilical\s*artery\s*pi\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
            r"umbilikal\s*arter\s*pi\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
        ),
        "ua_ri": (
            r"\bua\s*ri\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
            r"umbilikal\s*arter\s*ri\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
        ),
        "ua_sd": (
            r"\bua\s*s[/ ]d\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
            r"\bs[/ ]d\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
        ),
        "mca_pi": (
            r"\bmca\s*pi\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
            r"middle\s*cerebral\s*(?:artery\s*)?pi\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)",
        ),
        "mca_psv": (
            r"\bmca\s*psv\s*[:=]?\s*(\d{1,3}(?:[.,]\d+)?)",
            r"\bmca\s*peak\s*[:=]?\s*(\d{1,3}(?:[.,]\d+)?)",
        ),
        "nipt_fetal_fraction": (
            r"fetal\s*fraction\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)\s*%?",
            r"fetal\s*fraksiyon\s*[:=]?\s*(\d{1,2}(?:[.,]\d+)?)\s*%?",
        ),
    }
    for key, patterns in measurements.items():
        value = _diet_find_number_v1000(text, patterns)
        if value is not None:
            info[key] = int(value) if key == "efw_g" else value
    efw_table_value = _diet_extract_efw_value_from_table_v1000(raw_text)
    if efw_table_value is not None:
        info["efw_g"] = efw_table_value
        info["efw_source"] = "efw_value_table"

    for label, keywords in (
        ("anterior", ("plasenta anterior", "anterior placenta")),
        ("posterior", ("plasenta posterior", "posterior placenta")),
        ("fundal", ("plasenta fundal", "fundal placenta")),
        ("previa", ("plasenta previa", "placenta previa")),
        ("low-lying", ("low lying placenta", "low-lying placenta", "alcak plasenta")),
    ):
        if any(keyword in text for keyword in keywords):
            info["placenta"] = label
            break

    for label, keywords in (
        ("cephalic", ("sefalik", "cephalic", "vertex", "bas asagi")),
        ("breech", ("breech", "makat")),
        ("transverse", ("transverse", "transvers", "enine")),
        ("oblique", ("oblique", "oblik")),
    ):
        if any(keyword in text for keyword in keywords):
            info["fetal_position"] = label
            break

    if any(k in text for k in ("ikiz", "twin", "gemelli", "dichorionic", "monochorionic")):
        info["fetus_count"] = "cogul/ikiz supheli"
    elif any(k in text for k in ("single live fetus", "tek fetus", "tek gebelik")):
        info["fetus_count"] = "tek fetus"

    edd_match = re.search(
        r"(?:edd|tahmini\s*dogum|expected\s*date)\s*[:=]?\s*"
        r"(\d{2}[./-]\d{2}[./-]\d{4}|\d{4}[./-]\d{2}[./-]\d{2})",
        text,
        re.IGNORECASE)
    if edd_match:
        info["edd_from_pdf"] = _diet_parse_date_text_v1000(edd_match.group(1))

    lmp_match = re.search(
        r"(?:\blmp\b|\bsat\b|son\s*adet|last\s*menstrual\s*period|last\s*period)"
        r"\s*[:=]?\s*(\d{2}[./-]\d{2}[./-]\d{4}|\d{4}[./-]\d{2}[./-]\d{2})",
        text,
        re.IGNORECASE)
    if lmp_match:
        info["lmp_from_pdf"] = _diet_parse_date_text_v1000(lmp_match.group(1))

    warnings = []
    for label, keywords in (
        ("IUGR/FGR", ("iugr", "fgr", "growth restriction", "gelisme geriligi")),
        ("LGA/makrozomi", ("lga", "macrosomia", "makrozomi")),
        ("Oligohidramnios", ("oligohidramnios", "oligohydramnios")),
        ("Polihidramnios", ("polihidramnios", "polyhydramnios")),
        ("Doppler anomali", ("absent end diastolic", "reversed flow", "brain sparing")),
    ):
        if any(keyword in text for keyword in keywords):
            warnings.append(label)
    if warnings:
        info["fetal_warnings"] = warnings

    fetal_tokens = (
        "fetus", "fetal", "gebelik", "gestasyon", "ultrason", "usg",
        "efw", "bpd", "afi", "plasenta", "nipt", "umbilikal", "mca",
        "lmp", "sat", "son adet")
    structured = any(k in info for k in (
        "ga_w", "efw_g", "bpd_mm", "hc_mm", "ac_mm", "fl_mm", "crl_mm",
        "nt_mm", "afi_cm", "placenta", "fetal_position", "ua_pi",
        "mca_pi", "nipt_fetal_fraction", "fetus_count", "fetal_warnings",
        "lmp_from_pdf", "edd_from_pdf"))
    info["found"] = bool(structured and any(token in text for token in fetal_tokens))
    return info


def _diet_recent_pdf_candidates_v1000(patient_key):
    cache_key = f"diet_recent_pdf_candidates_v1000_{patient_key}"
    try:
        cached = cache_get(cache_key)
        if cached is not None:
            return list(cached)
    except Exception:
        pass
    seen = set()
    patient_root = _patient_root_for_nas(patient_key)
    candidates = []
    visit_dates = {}
    try:
        with db_conn() as con:
            _ensure_file_archive_schema(con)
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            rows = con.execute(
                "SELECT file_name, full_path, visit_key, mtime FROM files "
                "WHERE patient_folder_key=? AND file_kind='pdf' "
                "AND COALESCE(archived_at, '') = '' "
                "ORDER BY mtime DESC, file_name LIMIT 30",
                (patient_key,)).fetchall()
            try:
                for visit_row in con.execute(
                    "SELECT visit_key, visit_date FROM visits "
                    "WHERE patient_folder_key=?",
                    (patient_key,)).fetchall():
                    visit_dates[str(visit_row.get("visit_key") or "")] = (
                        str(visit_row.get("visit_date") or ""))
            except Exception:
                pass
        for row in rows:
            visit_key = str(row.get("visit_key") or "")
            path = Path(row.get("full_path") or (
                patient_root / visit_key /
                str(row.get("file_name") or "")))
            candidates.append({
                "path": path,
                "mtime": row.get("mtime") or 0,
                "root": patient_root,
                "visit_key": visit_key,
                "visit_date": visit_dates.get(visit_key, ""),
            })
    except Exception:
        pass
    try:
        candidates.extend(
            e for e in _scan_patient_nas_media(
                patient_key, max_candidates=160, timeout=3.0)
            if e.get("kind") == "pdf")
    except Exception:
        pass

    def _sort_key(item):
        try:
            return float(item.get("mtime") or Path(item.get("path")).stat().st_mtime)
        except Exception:
            return 0.0

    out = []
    for item in sorted(candidates, key=_sort_key, reverse=True):
        try:
            path = Path(item.get("path"))
            key = _media_path_key(path)
            if key in seen or not path.exists() or not path.is_file():
                continue
            seen.add(key)
            visit_key = str(item.get("visit_key") or "")
            visit_date = str(item.get("visit_date") or "")
            if not visit_key:
                try:
                    rel = path.resolve().relative_to(patient_root.resolve())
                    if len(rel.parts) >= 2:
                        visit_key = str(rel.parts[0] or "")
                        visit_date = visit_dates.get(visit_key, visit_date)
                except Exception:
                    pass
            out.append({
                "path": path,
                "root": item.get("root") or patient_root,
                "mtime": _sort_key(item),
                "visit_key": visit_key,
                "visit_date": visit_date,
            })
        except Exception:
            continue
    return out


def _diet_collect_pdf_fetal_info_v1000(patient_key, max_pdfs=8, max_chars=16000):
    items = []
    search_parts = []
    total_chars = 0
    for item in _diet_recent_pdf_candidates_v1000(patient_key)[:max_pdfs]:
        path = Path(item.get("path"))
        text = _extract_text_from_pdf_file(path)
        if not text:
            continue
        if total_chars < max_chars:
            remaining = max_chars - total_chars
            search_parts.append(text[:remaining])
            total_chars += len(text[:remaining])
        parsed = _diet_parse_fetal_pdf_text_v1000(text)
        if not parsed.get("found"):
            continue
        parsed["source"] = _patient_media_label(
            path, item.get("root") or _patient_root_for_nas(patient_key),
            "PDF")
        parsed["source_name"] = path.name
        parsed["mtime"] = item.get("mtime") or 0
        items.append(parsed)
        if len(items) >= max_pdfs:
            break

    latest = items[0] if items else {}
    return {
        "items": items,
        "latest": latest,
        "search_text": "\n".join(search_parts)[:max_chars],
    }


def _diet_fetal_context_lines_v1000(pdf_fetal):
    latest = (pdf_fetal or {}).get("latest") or {}
    if not latest:
        return []
    lines = []
    if latest.get("source_name"):
        lines.append(f"PDF fetal kaynak: {latest.get('source_name')}")
    if latest.get("ga_w") is not None:
        lines.append(
            f"PDF fetal GA: {latest.get('ga_w')}+{latest.get('ga_d') or 0}")
    if latest.get("lmp_from_pdf"):
        lines.append(f"PDF LMP/SAT: {latest.get('lmp_from_pdf')}")
    if latest.get("edd_from_pdf"):
        lines.append(f"PDF EDD: {latest.get('edd_from_pdf')}")
    measurement_parts = []
    for key, label, unit in (
        ("efw_g", "EFW", "g"),
        ("bpd_mm", "BPD", "mm"),
        ("hc_mm", "HC", "mm"),
        ("ac_mm", "AC", "mm"),
        ("fl_mm", "FL", "mm"),
        ("crl_mm", "CRL", "mm"),
        ("nt_mm", "NT", "mm"),
        ("afi_cm", "AFI", "cm"),
    ):
        if latest.get(key) is not None:
            measurement_parts.append(f"{label}: {latest.get(key)} {unit}")
    if measurement_parts:
        lines.append("PDF fetal olcum: " + ", ".join(measurement_parts))
    anatomy_parts = []
    for key, label in (
        ("fetus_count", "Fetus"),
        ("placenta", "Plasenta"),
        ("fetal_position", "Pozisyon"),
    ):
        if latest.get(key):
            anatomy_parts.append(f"{label}: {latest.get(key)}")
    if anatomy_parts:
        lines.append("PDF fetal durum: " + ", ".join(anatomy_parts))
    doppler_parts = []
    for key, label in (
        ("ua_pi", "UA PI"), ("ua_ri", "UA RI"), ("ua_sd", "UA S/D"),
        ("mca_pi", "MCA PI"), ("mca_psv", "MCA PSV"),
        ("nipt_fetal_fraction", "NIPT fetal fraksiyon"),
    ):
        if latest.get(key) is not None:
            doppler_parts.append(f"{label}: {latest.get(key)}")
    if doppler_parts:
        lines.append("PDF Doppler/NIPT: " + ", ".join(doppler_parts))
    if latest.get("fetal_warnings"):
        lines.append(
            "PDF fetal uyarilar: " + ", ".join(latest.get("fetal_warnings")))
    return lines


def _diet_patient_visible_fetal_lines_v1000(pdf_fetal):
    hidden_prefixes = ("PDF fetal kaynak:", "PDF fetal durum:")
    return [
        line for line in _diet_fetal_context_lines_v1000(pdf_fetal)
        if not any(str(line).startswith(prefix) for prefix in hidden_prefixes)
    ]


def _diet_patient_group_label_v1000(profile):
    if profile.get("is_pregnant") and profile.get("is_infertile"):
        return "Gebe + infertilite/IVF oykusu"
    if profile.get("is_pregnant"):
        return "Gebe takip hastasi"
    if profile.get("is_infertile"):
        return "Infertilite hastasi"
    return "Genel hasta"


def _diet_profile_v1000(patient_key):
    try:
        demo = load_patient_demographics(patient_key) or {}
    except Exception:
        demo = {}
    patient_type_key = ""
    try:
        with db_conn() as con:
            row = con.execute(
                "SELECT ptype FROM patient_type WHERE patient_key=? LIMIT 1",
                (patient_key,),
            ).fetchone()
        patient_type_key = _normalize_patient_type_key(
            _row_value(row, "ptype") if row else "")
    except Exception:
        patient_type_key = ""
    snapshot = _patient_latest_clinical_snapshot(patient_key)
    latest_usg = snapshot.get("latest_usg") or {}
    latest_vitals = snapshot.get("latest_vitals") or {}
    db_metrics = _diet_patient_db_metrics_v1000(patient_key)
    try:
        if _diet_prefill_patient_metrics_from_pdfs_v1000(
                patient_key, db_metrics):
            demo = load_patient_demographics(patient_key) or {}
            db_metrics = _diet_patient_db_metrics_v1000(patient_key)
    except Exception:
        pass
    try:
        pdf_fetal = _diet_collect_pdf_fetal_info_v1000(patient_key)
    except Exception:
        pdf_fetal = {"items": [], "latest": {}, "search_text": ""}
    latest_pdf_fetal = pdf_fetal.get("latest") or {}

    weight = db_metrics.get("weight") or demo.get("weight") or latest_vitals.get("weight")
    height = db_metrics.get("height") or demo.get("height")
    pre_weight = db_metrics.get("pre_weight") or demo.get("pre_pregnancy_weight")
    ga_w = None
    ga_d = 0
    trimester = None
    edd_str = ""
    try:
        from datetime import timedelta
        lmp_str = str(demo.get("lmp_override") or "").strip()
        if lmp_str:
            parts = lmp_str.split(".")
            if len(parts) == 3:
                lmp_dt = datetime(int(parts[2]), int(parts[1]), int(parts[0]))
                ga_w = (datetime.now() - lmp_dt).days // 7
                ga_d = (datetime.now() - lmp_dt).days % 7
                edd_str = (lmp_dt + timedelta(days=280)).strftime("%d.%m.%Y")
    except Exception:
        pass
    if ga_w is None and latest_usg.get("ga_weeks") is not None:
        try:
            ga_w = int(latest_usg.get("ga_weeks"))
            ga_d = int(latest_usg.get("ga_days") or 0)
            edd_str = f"USG GA {ga_w}+{ga_d}"
        except Exception:
            pass
    if ga_w is None and latest_pdf_fetal.get("ga_w") is not None:
        try:
            ga_w = int(latest_pdf_fetal.get("ga_w"))
            ga_d = int(latest_pdf_fetal.get("ga_d") or 0)
            edd_str = latest_pdf_fetal.get("edd_from_pdf") or f"PDF GA {ga_w}+{ga_d}"
        except Exception:
            pass
    if ga_w is not None:
        trimester = 1 if ga_w < 14 else 2 if ga_w < 28 else 3

    bmi = None
    bmi_cat = ""
    try:
        stored_bmi = _diet_metric_float_v1000(
            db_metrics.get("bmi") or demo.get("bmi"), low=10, high=80)
        if stored_bmi is not None:
            bmi = stored_bmi
        elif weight and height:
            h_m = float(height) / 100.0
            bmi = float(weight) / (h_m * h_m)
        if bmi is not None:
            if bmi < 18.5:
                bmi_cat = "Dusuk kilo"
            elif bmi < 25:
                bmi_cat = "Normal"
            elif bmi < 30:
                bmi_cat = "Fazla kilo"
            else:
                bmi_cat = "Obezite"
    except Exception:
        bmi = None

    active_flags = []
    try:
        flags = get_patient_flags(patient_key)
        active_flags = [
            PATIENT_FLAG_LABELS.get(k, k)
            for k, v in flags.items()
            if v.get("value") == "1"
        ]
    except Exception:
        pass

    labs = _diet_latest_labs_v1000(patient_key)
    text_blob = " ".join([
        str(patient_key),
        str(demo),
        str(patient_type_key),
        " ".join(active_flags),
        " ".join(f"{k} {v}" for k, v in labs.items()),
        " ".join(_snapshot_lines_for_diet(snapshot)),
        " ".join(_diet_fetal_context_lines_v1000(pdf_fetal)),
        str(pdf_fetal.get("search_text") or ""),
    ])
    pdf_says_pregnant = bool(latest_pdf_fetal.get("found"))
    is_pregnant = (
        (ga_w is not None and 0 <= int(ga_w) <= 43) or
        pdf_says_pregnant)
    is_infertile = _diet_has_any_v1000(
        text_blob,
        ("infertil", "ivf", "tup bebek", "iui", "ovulasyon",
         "yumurta rezerv", "amh", "embriyo", "transfer"))
    if patient_type_key == "obstetric":
        is_pregnant = True
        is_infertile = False
    elif patient_type_key == "gynecologic" and not is_pregnant:
        is_infertile = True
    has_diabetes = _diet_has_any_v1000(
        text_blob,
        ("diabet", "diabetes", "gestasyonel diabet", "gestasyonel diyabet",
         "ogtt", "hba1c", "glukoz", "glucose", "insulin", "metformin"))
    has_prediabetes = _diet_has_any_v1000(
        text_blob,
        ("prediabet", "prediyabet", "sinirda seker", "insulin direnci",
         "bozulmus aclik", "bozulmus glukoz"))

    # YaÃƒâ€¦Ã…Â¸ kaynaÃƒâ€Ã…Â¸Ãƒâ€Ã‚Â±: hasta dosyasÃƒâ€Ã‚Â± > PDF rapor > demografi > "-"
    age_value = db_metrics.get("age") or _web_patient_profile_age_v1000(demo.get("age"))
    age_source = ""
    if not age_value:
        try:
            pdf_age = _clinical_pdf_age_v1000(patient_key) or {}
            if pdf_age.get("age"):
                age_value = pdf_age.get("age")
                age_source = pdf_age.get("source") or ""
        except Exception:
            pass
    if not age_value:
        try:
            with db_conn() as con:
                row = con.execute(
                    "SELECT age FROM patient_type WHERE patient_key=?",
                    (patient_key,)).fetchone()
                if row and row[0]:
                    age_value = _web_patient_profile_age_v1000(row[0])
                    if age_value:
                        age_source = "patient_type.age"
        except Exception:
            pass
    if not age_value:
        # Son fallback: demographics'teki birth_date'ten hesapla
        try:
            bd = demo.get("birth_date") or demo.get("dogum_tarihi")
            if bd:
                age_value = _diet_metric_date_age_v1000(bd)
                if age_value:
                    age_source = "patient_demographics.birth_date"
        except Exception:
            pass
    if age_value:
        # Bulundugunda DB'ye persist - sonraki acilislarda anlik gelir
        try:
            _diet_save_patient_db_metrics_v1000(patient_key, age=age_value)
        except Exception:
            pass
    profile = {
        "patient_key": patient_key,
        "demo": demo,
        "db_metrics": db_metrics,
        "age": age_value or "-",
        "age_source": age_source,
        "weight": weight,
        "height": height,
        "pre_weight": pre_weight,
        "chronic": demo.get("chronic_conditions") or "",
        "medications": demo.get("medications") or "",
        "allergies": demo.get("allergies") or "",
        "snapshot": snapshot,
        "latest_usg": latest_usg,
        "latest_vitals": latest_vitals,
        "pdf_fetal": pdf_fetal,
        "labs": labs,
        "active_flags": active_flags,
        "ga_w": ga_w,
        "ga_d": ga_d,
        "trimester": trimester,
        "edd_str": edd_str,
        "bmi": bmi,
        "bmi_cat": bmi_cat,
        "patient_type_key": patient_type_key,
        "is_pregnant": is_pregnant,
        "is_infertile": is_infertile,
        "has_diabetes": has_diabetes,
        "has_prediabetes": has_prediabetes,
    }
    _web_sync_patient_profile_v1000(
        patient_key,
        age=profile.get("age"),
        weight=profile.get("weight"),
        height=profile.get("height"),
        bmi=profile.get("bmi"),
        pre_weight=profile.get("pre_weight"),
        lmp_text=demo.get("lmp_override") or latest_pdf_fetal.get("lmp_from_pdf"),
    )
    return profile


def _diet_apply_form_v1000(profile, form):
    changed_age = None
    changed_weight = None
    changed_height = None
    changed_bmi = None
    changed_pre_weight = None
    def _set_bmi_value(value):
        bmi = _diet_metric_float_v1000(value, low=10, high=80)
        if bmi is None:
            return None
        profile["bmi"] = bmi
        profile["bmi_cat"] = (
            "Dusuk kilo" if bmi < 18.5 else
            "Normal" if bmi < 25 else
            "Fazla kilo" if bmi < 30 else "Obezite")
        return bmi

    try:
        if form.get("extra_age"):
            age_value = _web_patient_profile_age_v1000(form.get("extra_age"))
            if age_value is not None:
                profile["age"] = age_value
                changed_age = age_value
                profile.setdefault("db_metrics", {}).setdefault("sources", {})["age"] = "diyet_form.extra_age"
        if form.get("extra_weight"):
            profile["weight"] = float(str(form.get("extra_weight")).replace(",", "."))
            changed_weight = profile["weight"]
            profile.setdefault("db_metrics", {}).setdefault("sources", {})["weight"] = "diyet_form.extra_weight"
        if form.get("extra_height"):
            profile["height"] = float(str(form.get("extra_height")).replace(",", "."))
            changed_height = profile["height"]
            profile.setdefault("db_metrics", {}).setdefault("sources", {})["height"] = "diyet_form.extra_height"
        if form.get("extra_pre_weight"):
            pre_weight_value = _diet_metric_float_v1000(
                form.get("extra_pre_weight"), low=20, high=250)
            if pre_weight_value is not None:
                profile["pre_weight"] = pre_weight_value
                changed_pre_weight = pre_weight_value
                profile.setdefault("db_metrics", {}).setdefault("sources", {})["pre_weight"] = "diyet_form.extra_pre_weight"
        if profile.get("weight") and profile.get("height"):
            h_m = float(profile["height"]) / 100.0
            derived_bmi = _set_bmi_value(float(profile["weight"]) / (h_m * h_m))
            if derived_bmi is not None and (
                    changed_weight is not None or changed_height is not None):
                changed_bmi = derived_bmi
        if form.get("extra_bmi"):
            manual_bmi = _set_bmi_value(form.get("extra_bmi"))
            if manual_bmi is not None:
                changed_bmi = manual_bmi
                profile.setdefault("db_metrics", {}).setdefault("sources", {})["bmi"] = "diyet_form.extra_bmi"
        if (changed_age is not None or changed_weight is not None or
                changed_height is not None or changed_bmi is not None or
                changed_pre_weight is not None):
            _diet_save_patient_db_metrics_v1000(
                profile.get("patient_key"),
                age=changed_age,
                weight=changed_weight, height=changed_height,
                bmi=changed_bmi, pre_weight=changed_pre_weight)
    except Exception:
        pass
    group = (form.get("patient_group") or "auto").strip()
    if group == "pregnant":
        profile["is_pregnant"] = True
        if profile.get("ga_w") is None:
            profile["ga_w"] = 12
            profile["trimester"] = 1
    elif group == "infertile":
        profile["is_infertile"] = True
    elif group == "general":
        profile["is_pregnant"] = False
        profile["is_infertile"] = False
    return profile


def _diet_context_lines_v1000(profile, form=None):
    form = form or {}
    lines = [
        f"Hasta grubu: {_diet_patient_group_label_v1000(profile)}",
        f"Yas: {profile.get('age') or '-'}",
    ]
    if profile.get("weight"):
        lines.append(f"Kilo: {profile.get('weight')} kg")
    if profile.get("height"):
        lines.append(f"Boy: {profile.get('height')} cm")
    if profile.get("bmi"):
        lines.append(f"BMI: {profile.get('bmi'):.1f} ({profile.get('bmi_cat')})")
    if profile.get("pre_weight"):
        lines.append(f"Gebelik oncesi kilo: {profile.get('pre_weight')} kg")
    sources = (profile.get("db_metrics") or {}).get("sources") or {}
    if sources:
        source_labels = []
        for key, label in (
                ("age", "Yas"), ("weight", "Kilo"),
                ("height", "Boy"), ("pre_weight", "Gebelik oncesi kilo")):
            if sources.get(key):
                source_labels.append(f"{label}: {sources.get(key)}")
        if source_labels:
            lines.append("DB olcum kaynaklari: " + "; ".join(source_labels))
    if profile.get("ga_w") is not None:
        lines.append(
            f"Gebelik haftasi: {profile.get('ga_w')}+{profile.get('ga_d') or 0} "
            f"({profile.get('trimester')}. trimester)")
    if profile.get("edd_str"):
        lines.append(f"Tahmini dogum/GA: {profile.get('edd_str')}")
    if profile.get("chronic"):
        lines.append(f"Kronik hastaliklar: {profile.get('chronic')}")
    if profile.get("medications"):
        lines.append(f"Ilaclar: {profile.get('medications')}")
    if profile.get("allergies"):
        lines.append(f"Alerji: {profile.get('allergies')}")
    if profile.get("active_flags"):
        lines.append("Riskler: " + ", ".join(profile.get("active_flags")))
    if profile.get("labs"):
        lines.append(
            "Tahliller: "
            + ", ".join(f"{k}={v}" for k, v in profile.get("labs").items()))
    lines.extend(_snapshot_lines_for_diet(profile.get("snapshot") or {}))
    lines.extend(_diet_patient_visible_fetal_lines_v1000(profile.get("pdf_fetal") or {}))
    if form.get("extra_complaint"):
        lines.append(f"Sikayet: {form.get('extra_complaint')}")
    if form.get("extra_pref"):
        lines.append(f"Tercih: {form.get('extra_pref')}")
    if form.get("excluded_foods"):
        lines.append(f"Cikarilacak gidalar: {form.get('excluded_foods')}")
    return lines


