def _preg_plan_parse_date_v1000(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    raw = raw.replace("\\", "/")
    compact = raw[:10]
    for fmt in (
            "%d.%m.%Y", "%d/%m/%Y", "%d-%m-%Y",
            "%Y-%m-%d", "%Y/%m/%d", "%Y.%m.%d"):
        try:
            return datetime.strptime(compact, fmt).date()
        except Exception:
            pass
    match = re.search(
        r"(\d{2})[./-](\d{2})[./-](\d{4})|(\d{4})[./-](\d{2})[./-](\d{2})",
        raw)
    if not match:
        return None
    try:
        if match.group(1):
            return datetime(
                int(match.group(3)), int(match.group(2)),
                int(match.group(1))).date()
        return datetime(
            int(match.group(4)), int(match.group(5)),
            int(match.group(6))).date()
    except Exception:
        return None


def _preg_plan_format_date_v1000(day):
    if not day:
        return ""
    try:
        return day.strftime("%d.%m.%Y")
    except Exception:
        return str(day)


def _preg_plan_week_label_v1000(days):
    try:
        total = max(0, int(days))
        w, d = divmod(total, 7)
        return f"{w}+{d}" if d else f"{w}. hafta"
    except Exception:
        return "-"


def _preg_plan_patient_identity_v1000(patient_key):
    try:
        name = _pdf_editor_patient_name(patient_key)
    except Exception:
        name = str(patient_key)
    try:
        demo = load_patient_demographics(patient_key) or {}
    except Exception:
        demo = {}
    age = _web_patient_profile_age_v1000(demo.get("age"))
    if not age:
        try:
            metrics = _diet_patient_db_metrics_v1000(patient_key) or {}
            age = metrics.get("age") or age
        except Exception:
            pass
    if not age:
        try:
            with db_conn() as con:
                row = con.execute(
                    "SELECT age FROM patient_type WHERE patient_key=?",
                    (patient_key,)).fetchone()
                if row and row[0]:
                    age = _web_patient_profile_age_v1000(row[0])
        except Exception:
            pass
    if not age:
        try:
            age = (_clinical_pdf_age_v1000(patient_key) or {}).get("age") or age
        except Exception:
            pass
    if not age:
        # Son fallback: demographics'teki birth_date'ten hesapla
        try:
            bd = demo.get("birth_date") or demo.get("dogum_tarihi")
            if bd:
                age = _diet_metric_date_age_v1000(bd)
        except Exception:
            pass
    if age:
        # Bulundugunda DB'ye persist
        try:
            _diet_save_patient_db_metrics_v1000(patient_key, age=age)
        except Exception:
            pass
    return {"name": name or str(patient_key), "age": age or "", "demo": demo}


def _preg_plan_trimester_v1000(ga_days):
    if ga_days is None:
        return "Belirsiz"
    if ga_days < 14 * 7:
        return "1. trimester"
    if ga_days < 28 * 7:
        return "2. trimester"
    return "3. trimester"


def _preg_plan_valid_ga_days_v1000(ga_days):
    try:
        days = int(ga_days)
        return 14 <= days <= 315
    except Exception:
        return False


def _patient_ga_quick_card(patient_key):
    """D128 SUPER: Hasta listesi kart icin hizli gebelik haftasi.

    Sirayla: (1) DB demografi SAT/LMP -> bugune gore hesapla
             (2) Latest USG snapshot ga_weeks + USG tarihi -> bugune ilerlet.
    PDF taramaz (yavas). Donus: (ga_label, source_short)
    Ornek: ('20+4', 'SAT') / ('14+1', 'USG') / ('', '').
    """
    cache_key_v = f"ga_quick_card_{patient_key}"
    try:
        cached = cache_get(cache_key_v) if "cache_get" in globals() else None
    except Exception:
        cached = None
    if cached is not None:
        return cached
    today = datetime.now().date()
    out = ("", "")
    # 1) DB demografi SAT/LMP - lmp_override sutunu + data_json JSON ici
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            try:
                _web_ensure_patient_demographics_schema_v1000(con)
            except Exception:
                pass
            try:
                row = con.execute(
                    "SELECT lmp_override, data_json FROM patient_demographics "
                    "WHERE patient_key=? LIMIT 1",
                    (patient_key,)).fetchone()
            except Exception:
                row = None
            candidates = []
            if row:
                if row.get("lmp_override"):
                    candidates.append(row["lmp_override"])
                dj = row.get("data_json")
                if dj:
                    try:
                        import json as _json
                        j = _json.loads(dj) if isinstance(dj, str) else dj
                        if isinstance(j, dict):
                            for kk in ("lmp_override", "lmp", "sat",
                                       "lmp_date", "last_menstrual_period",
                                       "son_adet"):
                                v = j.get(kk)
                                if v:
                                    candidates.append(v)
                    except Exception:
                        pass
            for val in candidates:
                day = _preg_plan_parse_date_v1000(val)
                if not day:
                    continue
                ga_days = (today - day).days
                if 14 <= ga_days <= 315:
                    gw, gd = divmod(ga_days, 7)
                    out = (f"{gw}+{gd}" if gd else str(gw), "SAT")
                    break
    except Exception:
        pass
    # 2) Latest USG snapshot
    if not out[0]:
        try:
            snap = _patient_latest_clinical_snapshot(patient_key) or {}
            usg = snap.get("latest_usg") or {}
            gw_raw = usg.get("ga_weeks")
            gd_raw = usg.get("ga_days") or 0
            if gw_raw is not None:
                usg_date = _preg_plan_parse_date_v1000(usg.get("usg_date"))
                if usg_date:
                    delta = (today - usg_date).days
                    ga_days = int(gw_raw) * 7 + int(gd_raw or 0) + delta
                else:
                    ga_days = int(gw_raw) * 7 + int(gd_raw or 0)
                if 14 <= ga_days <= 315:
                    gw2, gd2 = divmod(ga_days, 7)
                    out = (f"{gw2}+{gd2}" if gd2 else str(gw2), "USG")
        except Exception:
            pass
    # 3) PDF fallback: kucuk scan (3 PDF, 8K char), gec ama cache TTL uzun
    if not out[0]:
        try:
            pdf_info = _diet_collect_pdf_fetal_info_v1000(
                patient_key, max_pdfs=3, max_chars=8000)
            latest_pdf = (pdf_info or {}).get("latest") or {}
            lmp_pdf = _preg_plan_parse_date_v1000(latest_pdf.get("lmp_from_pdf"))
            if lmp_pdf:
                ga_days = (today - lmp_pdf).days
                if 14 <= ga_days <= 315:
                    gw3, gd3 = divmod(ga_days, 7)
                    out = (f"{gw3}+{gd3}" if gd3 else str(gw3), "PDF")
            elif latest_pdf.get("edd_from_pdf"):
                edd_pdf = _preg_plan_parse_date_v1000(
                    latest_pdf.get("edd_from_pdf"))
                if edd_pdf:
                    ga_days = 280 - (edd_pdf - today).days
                    if 14 <= ga_days <= 315:
                        gw4, gd4 = divmod(ga_days, 7)
                        out = (f"{gw4}+{gd4}" if gd4 else str(gw4), "PDF")
        except Exception:
            pass
    try:
        if "cache_set" in globals():
            cache_set(cache_key_v, out, ttl_key="ga_quick_card")
    except Exception:
        pass
    return out


