def _preg_plan_usg_date_text_v1000(patient_key, latest_usg=None, latest_pdf=None):
    """Prefer the actual USG/PDF production date for the pregnancy plan."""
    latest_usg = latest_usg or {}
    latest_pdf = latest_pdf or {}
    for key in ("usg_date", "study_date", "exam_date", "visit_date", "date", "created_at"):
        day = _preg_plan_parse_date_v1000(latest_usg.get(key))
        if day:
            return _preg_plan_format_date_v1000(day)
    try:
        mtime = latest_pdf.get("mtime")
        if mtime:
            return _preg_plan_format_date_v1000(
                datetime.fromtimestamp(float(mtime)).date())
    except Exception:
        pass
    try:
        candidates = _diet_recent_pdf_candidates_v1000(patient_key)
    except Exception:
        candidates = []
    for item in candidates[:3]:
        try:
            mtime = item.get("mtime") or Path(item.get("path")).stat().st_mtime
            if mtime:
                return _preg_plan_format_date_v1000(
                    datetime.fromtimestamp(float(mtime)).date())
        except Exception:
            continue
    return ""


def _preg_plan_resolve_dating_v1000(patient_key):
    today = datetime.now().date()
    identity = _preg_plan_patient_identity_v1000(patient_key)
    demo = identity.get("demo") or {}
    try:
        snapshot = _patient_latest_clinical_snapshot(patient_key)
    except Exception:
        snapshot = {}
    latest_usg = (snapshot or {}).get("latest_usg") or {}
    try:
        pdf_fetal = _diet_collect_pdf_fetal_info_v1000(
            patient_key, max_pdfs=10, max_chars=22000)
    except Exception:
        pdf_fetal = {"items": [], "latest": {}, "search_text": ""}
    latest_pdf = pdf_fetal.get("latest") or {}
    usg_date_text = _preg_plan_usg_date_text_v1000(
        patient_key, latest_usg, latest_pdf)
    for value in (
            demo.get("lmp_override"), demo.get("lmp"), demo.get("sat"),
            demo.get("lmp_date"), demo.get("last_menstrual_period")):
        day = _preg_plan_parse_date_v1000(value)
        if not day:
            continue
        ga_days = (today - day).days
        if not _preg_plan_valid_ga_days_v1000(ga_days):
            continue
        ga_w, ga_d = divmod(ga_days, 7)
        edd = day + timedelta(days=280)
        return {
            "ga_days": ga_days,
            "ga_w": ga_w,
            "ga_d": ga_d,
            "ga_label": f"{ga_w}+{ga_d}",
            "trimester": _preg_plan_trimester_v1000(ga_days),
            "lmp_day": day,
            "lmp_text": _preg_plan_format_date_v1000(day),
            "edd_day": edd,
            "edd_text": _preg_plan_format_date_v1000(edd),
            "source": "SAT (hasta kaydi)",
            "source_detail": "Merkezi hasta profilindeki SAT/LMP",
            "base_date_text": "",
            "usg_date_text": usg_date_text,
            "pdf_fetal": pdf_fetal,
            "latest_pdf": latest_pdf,
        }

    def from_lmp(day, source, detail):
        if not day:
            return None
        ga_days = (today - day).days
        if not _preg_plan_valid_ga_days_v1000(ga_days):
            return None
        ga_w, ga_d = divmod(ga_days, 7)
        edd = day + timedelta(days=280)
        return {
            "ga_days": ga_days,
            "ga_w": ga_w,
            "ga_d": ga_d,
            "ga_label": f"{ga_w}+{ga_d}",
            "trimester": _preg_plan_trimester_v1000(ga_days),
            "lmp_day": day,
            "lmp_text": _preg_plan_format_date_v1000(day),
            "edd_day": edd,
            "edd_text": _preg_plan_format_date_v1000(edd),
            "source": source,
            "source_detail": detail,
            "base_date_text": "",
            "usg_date_text": usg_date_text,
            "pdf_fetal": pdf_fetal,
            "latest_pdf": latest_pdf,
        }

    lmp_candidates = [
        (demo.get("lmp_override"), "SAT (hasta kaydi)", "Hasta kartindaki SAT/LMP"),
        (demo.get("lmp"), "SAT (hasta kaydi)", "Hasta kartindaki LMP"),
        (demo.get("sat"), "SAT (hasta kaydi)", "Hasta kartindaki SAT"),
        (demo.get("lmp_date"), "SAT (hasta kaydi)", "Hasta kartindaki LMP tarihi"),
        (demo.get("last_menstrual_period"), "SAT (hasta kaydi)", "Hasta kartindaki LMP"),
        (latest_pdf.get("lmp_from_pdf"), "PDF LMP/SAT", "PDF evrakindan okunan LMP/SAT"),
    ]
    for value, source, detail in lmp_candidates:
        result = from_lmp(_preg_plan_parse_date_v1000(value), source, detail)
        if result:
            return result

    def from_ga(ga_w, ga_d, base_day, source, detail, edd_text=""):
        try:
            record_days = int(ga_w) * 7 + int(ga_d or 0)
        except Exception:
            return None
        ga_days = record_days
        base_text = ""
        if base_day:
            delta = (today - base_day).days
            ga_days = record_days + delta
            base_text = _preg_plan_format_date_v1000(base_day)
        if not _preg_plan_valid_ga_days_v1000(ga_days):
            return None
        ga_w2, ga_d2 = divmod(ga_days, 7)
        edd_day = _preg_plan_parse_date_v1000(edd_text)
        if not edd_day:
            edd_day = today + timedelta(days=(280 - ga_days))
        return {
            "ga_days": ga_days,
            "ga_w": ga_w2,
            "ga_d": ga_d2,
            "ga_label": f"{ga_w2}+{ga_d2}",
            "trimester": _preg_plan_trimester_v1000(ga_days),
            "lmp_day": None,
            "lmp_text": "",
            "edd_day": edd_day,
            "edd_text": _preg_plan_format_date_v1000(edd_day),
            "source": source,
            "source_detail": detail,
            "base_date_text": base_text,
            "usg_date_text": usg_date_text or base_text,
            "pdf_fetal": pdf_fetal,
            "latest_pdf": latest_pdf,
        }

    if latest_usg.get("ga_weeks") is not None:
        result = from_ga(
            latest_usg.get("ga_weeks"),
            latest_usg.get("ga_days") or 0,
            _preg_plan_parse_date_v1000(latest_usg.get("usg_date")),
            "USG kaydi",
            "SAT yoksa son USG kaydindaki hafta bugune ilerletildi")
        if result:
            return result

    pdf_edd = _preg_plan_parse_date_v1000(latest_pdf.get("edd_from_pdf"))
    if pdf_edd:
        ga_days = 280 - (pdf_edd - today).days
        if _preg_plan_valid_ga_days_v1000(ga_days):
            ga_w, ga_d = divmod(ga_days, 7)
            return {
                "ga_days": ga_days,
                "ga_w": ga_w,
                "ga_d": ga_d,
                "ga_label": f"{ga_w}+{ga_d}",
                "trimester": _preg_plan_trimester_v1000(ga_days),
                "lmp_day": pdf_edd - timedelta(days=280),
                "lmp_text": _preg_plan_format_date_v1000(
                    pdf_edd - timedelta(days=280)),
                "edd_day": pdf_edd,
                "edd_text": _preg_plan_format_date_v1000(pdf_edd),
                "source": "PDF EDD",
                "source_detail": "PDF evrakindaki tahmini dogum tarihinden hesaplandi",
                "base_date_text": "",
                "usg_date_text": usg_date_text,
                "pdf_fetal": pdf_fetal,
                "latest_pdf": latest_pdf,
            }

    if latest_pdf.get("ga_w") is not None:
        base_day = None
        try:
            if latest_pdf.get("mtime"):
                base_day = datetime.fromtimestamp(
                    float(latest_pdf.get("mtime"))).date()
        except Exception:
            base_day = None
        result = from_ga(
            latest_pdf.get("ga_w"),
            latest_pdf.get("ga_d") or 0,
            base_day,
            "PDF/USG GA",
            "PDF icindeki USG gebelik haftasi tarih bazli ilerletildi",
            latest_pdf.get("edd_from_pdf") or "")
        if result:
            return result

    return {
        "ga_days": None,
        "ga_w": None,
        "ga_d": None,
        "ga_label": "Bulunamadi",
        "trimester": "Belirsiz",
        "lmp_day": None,
        "lmp_text": "",
        "edd_day": None,
        "edd_text": "",
        "source": "Bulunamadi",
        "source_detail": "Hasta karti, PDF LMP/SAT ve USG kaydinda tarihlenebilir veri bulunamadi",
        "base_date_text": "",
        "usg_date_text": usg_date_text,
        "pdf_fetal": pdf_fetal,
        "latest_pdf": latest_pdf,
    }


def _clinical_date_to_html_v1000(value):
    day = _preg_plan_parse_date_v1000(value)
    return day.strftime("%Y-%m-%d") if day else ""


def _clinical_profile_bmi_v1000(weight, height):
    try:
        if not weight or not height:
            return None, ""
        h_m = float(height) / 100.0
        if h_m <= 0:
            return None, ""
        bmi = float(weight) / (h_m * h_m)
        if bmi < 18.5:
            label = "Dusuk kilo"
        elif bmi < 25:
            label = "Normal"
        elif bmi < 30:
            label = "Fazla kilo"
        else:
            label = "Obezite"
        return round(bmi, 1), label
    except Exception:
        return None, ""


def _clinical_save_pdf_age_candidate_v1000(patient_key, age, source_ref):
    """Route PDF-derived age through the canonical conflict gate."""
    age = _web_patient_profile_age_v1000(age)
    if age is None:
        return {"age": None, "source": ""}
    current_age = None
    try:
        current_age = _web_patient_profile_age_v1000(
            (load_patient_demographics(patient_key) or {}).get("age"))
    except Exception:
        current_age = None
    try:
        decision = _patient_data_suggest_value(
            patient_key, "age", age,
            source="pdf_yas_tespiti",
            source_ref=source_ref or "PDF",
            confidence=0.8,
            auto_apply_empty=True)
    except Exception:
        decision = {"status": "error"}
    if decision.get("status") == "queued":
        return {
            "age": current_age,
            "source": "Ana kayit yasi; PDF yas farki onay bekliyor",
            "conflict": decision,
            "pdf_age": age,
        }
    return {
        "age": age if current_age in (None, age) else current_age,
        "source": source_ref or "PDF",
        "decision": decision,
    }


def _clinical_pdf_age_v1000(patient_key):
    """Hasta dosyasindaki PDF'lerden yas tespiti.
    Once USG raporlarini, sonra hasta klasorundeki tum PDF'leri tarar
    (e-Nabiz, lab, kimlik, e-Devlet vb.). Yas + dogum tarihi cikarilir.
    Bulundugunda patient_demographics'e persist edilir, sonraki acilis-
    larda DB'den anlik gelir."""
    # 1) Once USG/Voluson raporlari (hizli, yapisal)
    try:
        records, _warnings = _vp_collect_patient_pdf_measurements(
            patient_key, limit=16)
    except Exception:
        records = []
    for row in reversed(records):
        age = _web_patient_profile_age_v1000(row.get("patient_age"))
        if age is not None:
            return _clinical_save_pdf_age_candidate_v1000(
                patient_key, age,
                f"USG PDF: {row.get('pdf_name') or 'rapor'}")

    # 2) Hasta klasorundeki tum PDF'leri tara (e-Nabiz, lab, kimlik, vb.)
    try:
        from pathlib import Path as _Path
        proot = _patient_root_for_nas(patient_key)
        items = []
        if proot and _Path(str(proot)).exists():
            for p in sorted(_Path(str(proot)).rglob("*.pdf")):
                try:
                    if not p.is_file():
                        continue
                    txt = ""
                    if HAS_FITZ:
                        try:
                            doc = fitz.open(str(p))
                            parts = []
                            for page in doc:
                                try:
                                    parts.append(page.get_text("text") or "")
                                except Exception:
                                    parts.append("")
                            doc.close()
                            txt = "\n".join(parts)
                        except Exception:
                            txt = ""
                    items.append({
                        "name": p.name,
                        "path": str(p),
                        "mtime": p.stat().st_mtime,
                        "text": txt,
                    })
                    if len(items) >= 12:
                        break
                except Exception:
                    continue
        if items:
            payload = _yk_extract_patient_pdf_payload(items) or {}
            demo = (payload.get("demographics") or {})
            age = _web_patient_profile_age_v1000(demo.get("age"))
            if age is None and demo.get("birth_date"):
                # birth_date string'inden yas hesapla
                try:
                    age = _diet_metric_date_age_v1000(demo.get("birth_date"))
                except Exception:
                    age = None
            if age is not None:
                src = "Genel PDF tarama"
                pdfs = payload.get("pdfs") or []
                if pdfs:
                    try:
                        src = f"PDF: {pdfs[0].get('name') or 'rapor'}"
                    except Exception:
                        pass
                return _clinical_save_pdf_age_candidate_v1000(
                    patient_key, age, src)
    except Exception:
        pass
    return {"age": None, "source": ""}


def _clinical_patient_profile_v1000(patient_key, allow_pdf_scan=False):
    try:
        _patient_file_auto_apply_pdf_demographics_deferred(patient_key, max_pdfs=8)
    except Exception:
        pass
    try:
        demo = load_patient_demographics(patient_key) or {}
    except Exception:
        demo = {}
    try:
        db_metrics = _diet_patient_db_metrics_v1000(patient_key) or {}
    except Exception:
        db_metrics = {"sources": {}}
    try:
        dating = _preg_plan_resolve_dating_v1000(patient_key) or {}
    except Exception:
        dating = {}
    metric_sources = db_metrics.get("sources") or {}

    age = db_metrics.get("age")
    age_source = metric_sources.get("age") or ""
    if age is None:
        try:
            meta = _patient_file_load_data_json(patient_key) or {}
            pdf_extract = meta.get("pdf_patient_extract")
            if isinstance(pdf_extract, dict):
                pdf_demo = pdf_extract.get("demographics") or {}
                age = _web_patient_profile_age_v1000(pdf_demo.get("age"))
                if age is None and pdf_demo.get("birth_date"):
                    age = _diet_metric_date_age_v1000(pdf_demo.get("birth_date"))
                if age is not None:
                    age_source = "PDF onbellek"
        except Exception:
            pass
    if age is None and allow_pdf_scan:
        pdf_age = _clinical_pdf_age_v1000(patient_key)
        age = pdf_age.get("age")
        age_source = pdf_age.get("source") or ""

    weight = db_metrics.get("weight")
    height = db_metrics.get("height")
    pre_weight = db_metrics.get("pre_weight")
    bmi = _web_patient_profile_metric_float_v1000(
        db_metrics.get("bmi"), low=10, high=80)
    if bmi is not None:
        bmi_label = (
            "Dusuk kilo" if bmi < 18.5 else
            "Normal" if bmi < 25 else
            "Fazla kilo" if bmi < 30 else "Obezite")
    else:
        bmi, bmi_label = _clinical_profile_bmi_v1000(weight, height)

    manual_lmp = demo.get("lmp_override") or demo.get("lmp")
    lmp_text = manual_lmp or dating.get("lmp_text") or ""
    lmp_source = "Doktor kaydi" if manual_lmp else (dating.get("source") or "")
    edd_text = dating.get("edd_text") or ""
    ga_label = dating.get("ga_label") or ""

    profile = {
        "demo": demo,
        "db_metrics": db_metrics,
        "dating": dating,
        "age": age,
        "age_source": age_source,
        "weight": weight,
        "height": height,
        "pre_weight": pre_weight,
        "bmi": bmi,
        "bmi_label": bmi_label,
        "lmp_text": lmp_text,
        "lmp_html": _clinical_date_to_html_v1000(lmp_text),
        "lmp_source": lmp_source,
        "edd_text": edd_text,
        "ga_label": ga_label,
        "ga_days": dating.get("ga_days"),
        "trimester": dating.get("trimester") or "",
        "pdf_fetal": dating.get("pdf_fetal") or {},
    }
    _web_sync_patient_profile_v1000(
        patient_key,
        age=age,
        weight=weight,
        height=height,
        bmi=bmi,
        pre_weight=pre_weight,
        lmp_text=lmp_text if not manual_lmp else None,
    )
    return profile


def _patient_obstetric_context_active(patient_key):
    """Return True when this patient is explicitly or safely inferred obstetric."""
    if not patient_key:
        return False
    try:
        with db_conn() as con:
            row = con.execute(
                "SELECT ptype FROM patient_type WHERE patient_key=?",
                (patient_key,),
            ).fetchone()
        if row:
            try:
                ptype = row["ptype"]
            except Exception:
                ptype = row[0]
            ptype = _normalize_patient_type_key(ptype)
            if ptype:
                return ptype == "obstetric"
    except Exception:
        pass

    try:
        demo = load_patient_demographics(patient_key) or {}
    except Exception:
        demo = {}
    for key in (
            "lmp_override", "lmp", "sat", "lmp_date",
            "last_menstrual_period"):
        try:
            day = _preg_plan_parse_date_v1000(demo.get(key))
            if day and _preg_plan_valid_ga_days_v1000(
                    (datetime.now().date() - day).days):
                return True
        except Exception:
            pass

    try:
        dating = _preg_plan_resolve_dating_v1000(patient_key) or {}
        if _preg_plan_valid_ga_days_v1000(dating.get("ga_days")):
            return True
    except Exception:
        pass

    try:
        with db_conn() as con:
            row = con.execute("""
                SELECT 1 FROM usg_measurements
                WHERE patient_key=?
                  AND (
                    ga_weeks IS NOT NULL OR ga_days IS NOT NULL OR
                    bpd IS NOT NULL OR hc IS NOT NULL OR ac IS NOT NULL OR
                    fl IS NOT NULL OR crl IS NOT NULL OR nt IS NOT NULL OR
                    efw IS NOT NULL OR afi IS NOT NULL
                  )
                LIMIT 1
            """, (patient_key,)).fetchone()
        if row:
            return True
    except Exception:
        pass

    for table in ("deliveries", "birth_plans"):
        try:
            with db_conn() as con:
                row = con.execute(
                    f"SELECT 1 FROM {table} WHERE patient_key=? LIMIT 1",
                    (patient_key,),
                ).fetchone()
            if row:
                return True
        except Exception:
            pass
    return False


def _normalize_patient_type_key(ptype):
    value = str(ptype or "").strip().lower()
    folded = _fold_search_text(value)
    aliases = {
        "gynecology": "gynecologic",
        "gynaecology": "gynecologic",
        "jinekoloji": "gynecologic",
        "infertility": "gynecologic",
        "infertilite": "gynecologic",
        "infertil": "gynecologic",
        "obstetrik": "obstetric",
        "obstetri": "obstetric",
        "gebelik": "obstetric",
        "medical_aesthetic": "medical_aesthetic",
        "medical aesthetic": "medical_aesthetic",
        "medikal estetik": "medical_aesthetic",
        "gynecologic_aesthetic": "gynecologic_aesthetic",
        "gynecologic aesthetic": "gynecologic_aesthetic",
        "gynecological aesthetic": "gynecologic_aesthetic",
        "genital_aesthetic": "gynecologic_aesthetic",
        "genital aesthetic": "gynecologic_aesthetic",
        "jinekolojik estetik": "gynecologic_aesthetic",
        "jinekolojik_estetik": "gynecologic_aesthetic",
    }
    normalized = aliases.get(value) or aliases.get(folded) or value
    if normalized in (
            "gynecologic", "obstetric",
            "medical_aesthetic", "gynecologic_aesthetic"):
        return normalized
    if "estetik" in folded or "aesthetic" in normalized:
        if any(token in folded for token in ("jinek", "genital", "gyn")):
            return "gynecologic_aesthetic"
        return "medical_aesthetic"
    if normalized.startswith("obstetr") or "gebelik" in normalized:
        return "obstetric"
    if normalized.startswith(
            ("jinekolog", "gynecolog", "gynaecolog", "infertil")):
        return "gynecologic"
    return normalized


def _patient_card_primary_type(patient_key, ptype=None, has_obstetric_hint=None):
    normalized_type = _normalize_patient_type_key(ptype)
    # D40: Hasta kartinda once explicit tip kazanir.
    # PDF/manual'dan gelen gynecology -> jinekoloji; obstetric -> obstetrik.
    if normalized_type in ("obstetric", "gynecologic"):
        return normalized_type
    if has_obstetric_hint is not None:
        return "obstetric" if bool(has_obstetric_hint) else "gynecologic"
    if _patient_obstetric_context_active(patient_key):
        return "obstetric"
    return "gynecologic"


def _patient_type_meta_row(patient_key):
    if not patient_key:
        return {}
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            row = con.execute(
                "SELECT ptype, is_manual, notes, updated_at "
                "FROM patient_type WHERE patient_key=?",
                (patient_key,),
            ).fetchone()
        return dict(row) if row else {}
    except Exception:
        return {}


def _patient_card_type_control_html(patient_key, current_type=None,
                                    is_manual=False, updated_at=""):
    current = _patient_card_primary_type(patient_key, current_type)
    if current not in ("obstetric", "gynecologic"):
        current = "gynecologic"
    q_patient = quote(str(patient_key), safe="")
    detail_url = f"/hasta/{q_patient}"
    action_url = f"/hasta/{q_patient}/kart-tipi"
    overview_url = f"/api/web/patient/{q_patient}/overview?sync=1"
    safe_id = re.sub(r"[^A-Za-z0-9_-]+", "_", str(patient_key or ""))[:48]
    safe_id = safe_id or "patient"
    status_label = "Manuel" if is_manual else "Otomatik"
    status_class = "bg-success" if is_manual else "bg-secondary"
    current_label = "Obstetrik" if current == "obstetric" else "Jinekoloji"
    updated_line = ""
    if updated_at:
        updated_line = (
            f'<span class="text-muted ms-2">Son kayit: {sh(updated_at)}</span>'
        )
    obst_checked = "checked" if current == "obstetric" else ""
    gyn_checked = "checked" if current == "gynecologic" else ""
    return f"""
    <div class="card mb-3 yk-patient-card-type-control">
      <div class="card-header d-flex justify-content-between align-items-center flex-wrap gap-2">
        <span><i class="bi bi-layout-sidebar-inset"></i> Hasta Kart Tipi</span>
        <span class="d-flex align-items-center gap-2">
          <span class="badge bg-primary">{current_label}</span>
          <span class="badge {status_class}">{status_label}</span>
        </span>
      </div>
      <div class="card-body">
        <form method="POST" action="{safe_attr(action_url)}"
              class="row g-2 align-items-center yk-card-type-form"
              data-yk-card-type-form="1"
              data-overview-url="{safe_attr(overview_url)}"
              data-current-type="{safe_attr(current)}">
          <input type="hidden" name="next" value="{safe_attr(detail_url)}">
          <div class="col-lg-8">
            <div class="btn-group w-100 yk-card-type-switch" role="group" aria-label="Hasta kart tipi">
              <input type="radio" class="btn-check" name="ptype"
                     id="ykCardTypeObstetric_{safe_id}" value="obstetric"
                     data-yk-card-type-radio="1" {obst_checked}>
              <label class="btn btn-outline-primary" for="ykCardTypeObstetric_{safe_id}">
                <i class="bi bi-heart-pulse"></i> Obstetrik
              </label>
              <input type="radio" class="btn-check" name="ptype"
                     id="ykCardTypeGynecologic_{safe_id}" value="gynecologic"
                     data-yk-card-type-radio="1" {gyn_checked}>
              <label class="btn btn-outline-info" for="ykCardTypeGynecologic_{safe_id}">
                <i class="bi bi-gender-female"></i> Jinekoloji
              </label>
            </div>
            <div class="form-text yk-card-type-status" data-yk-card-type-status="1">
              Bu secim manuel kaydedilir; PDF/otomatik siniflama yerine hasta kartinda bu tip kullanilir.
              {updated_line}
            </div>
          </div>
          <div class="col-lg-4">
            <button class="btn btn-dark w-100" type="submit">
              <i class="bi bi-check2-circle"></i> Kart tipini uygula
            </button>
          </div>
        </form>
      </div>
    </div>
    """


def _preg_plan_milestones_v1000(ga_days, include_past=False):
    today = datetime.now().date()
    specs = [
        (0, 14 * 7, "Ilk izlem ve risk degerlendirme", [
            "Anne oykusu, risk formu, tansiyon, kilo/BMI ve idrar kontrolu",
            "Kan grubu/Rh, tam kan, idrar, enfeksiyon ve TSH gibi temel testler",
            "Erken USG ile gebelik yeri, canlilik, cogul gebelik ve haftanin netlestirilmesi",
            "Bulanti, beslenme, sigara/alkol, is ve egzersiz danismanligi",
        ]),
        (11 * 7 + 2, 14 * 7 + 1, "11+2 - 14+1 hafta tarama penceresi", [
            "Hafta tayini, ense kalinligi ve erken yapisal degerlendirme",
            "Ikili tarama veya NIPT seceneklerinin hekimle konusulmasi",
            "Cogul gebelik ve plasenta bilgilerinin kayda alinmasi",
        ]),
        (16 * 7, 18 * 7, "16-18 hafta ara kontrol", [
            "Onceki test sonuclarinin kapanmasi ve risklerin yeniden siniflanmasi",
            "Tansiyon, kilo, idrar ve sikayet odakli muayene",
            "Demir/D vitamini/folat destegi yalniz hekim planina gore duzenlenir",
        ]),
        (18 * 7, 24 * 7, "18-24 hafta ayrintili fetal degerlendirme", [
            "Ayrintili ultrason/anomali taramasi ve plasenta yerinin kontrolu",
            "Fetal olcumler, amniyon, serviks ve riskli bulgu varsa sevk/ikinci gorus",
            "Anneye fetal hareketlerin baslamasi ve normal degisimler anlatilir",
        ]),
        (24 * 7, 28 * 7, "24-28 hafta seker ve ara test penceresi", [
            "Gestasyonel diyabet riski; kurum protokolu ve hekim kararina gore OGTT",
            "Tam kan, ferritin/eksiklik, idrar ve enfeksiyon ihtiyaci degerlendirilir",
            "Tansiyon-proteinuri takibi ve preeklampsi belirtileri anlatilir",
        ]),
        (28 * 7, 32 * 7, "28-32 hafta ucuncu izlem", [
            "Fetal buyume, su, plasenta ve gelisim ritmi yeniden kontrol edilir",
            "Rh negatif ise antikor/anti-D planlamasi hekimce netlestirilir",
            "Bebek hareketleri, erken dogum belirtileri ve acil basvuru egitimi",
        ]),
        (34 * 7, 36 * 7, "34-36 hafta doguma hazirlik", [
            "Bebek gelis pozisyonu, dogum sekli ihtimali ve hastane plani",
            "Anestezi, sezaryen/vajinal dogum olasiliklari ve yenidogan hazirligi",
            "Canta, refakat, kan grubu ve ulasim planinin netlestirilmesi",
        ]),
        (36 * 7, 38 * 7, "36-38 hafta dorduncu izlem", [
            "Prezentasyon, serviks/kontraksiyon sikayeti ve dogum bulgulari",
            "NST/AFI veya ek USG gereksinimi klinik duruma gore kararlastirilir",
            "GBS veya ek taramalar kurum protokolu varsa hekimce uygulanir",
        ]),
        (38 * 7, 40 * 7, "38-40 hafta yakin takip", [
            "Haftalik veya hekimin belirledigi siklikta tansiyon, idrar, NST/AFI",
            "Fetal hareket azalmasi, su gelmesi, kanama veya duzenli agri acildir",
            "Dogum tarihi, dogum sekli ve basvuru esigi yeniden yazili verilir",
        ]),
        (40 * 7, 41 * 7, "40-41 hafta gun asimi plani", [
            "Gun asimi icin NST/AFI ve klinik degerlendirme siklastirilir",
            "Induksiyon veya bekleme secenegi hastanin riskine gore hekimce planlanir",
            "Acil bulgular ve hastane basvuru yolu tekrar anlatilir",
        ]),
    ]
    rows = []
    for start, end, title, actions in specs:
        if ga_days is not None and not include_past and end < int(ga_days) - 7:
            continue
        week_label = _preg_plan_week_label_v1000(start)
        if end != start:
            week_label = (
                f"{_preg_plan_week_label_v1000(start)} - "
                f"{_preg_plan_week_label_v1000(end)}")
        date_label = "-"
        state = "Planla"
        if ga_days is not None:
            start_day = today + timedelta(days=start - int(ga_days))
            end_day = today + timedelta(days=end - int(ga_days))
            if start_day == end_day:
                date_label = _preg_plan_format_date_v1000(start_day)
            else:
                date_label = (
                    f"{_preg_plan_format_date_v1000(start_day)} - "
                    f"{_preg_plan_format_date_v1000(end_day)}")
            if start <= int(ga_days) <= end:
                state = "Bu hafta"
            elif int(ga_days) > end:
                state = "Eksikse tamamla"
            else:
                state = "Planla"
        rows.append({
            "week": week_label,
            "date": date_label,
            "state": state,
            "title": title,
            "actions": actions,
        })
    return rows if include_past else rows[:12]


