def _preg_plan_current_focus_v1000(ga_days):
    if ga_days is None:
        return [
            "SAT/LMP veya USG haftasi netlestirilmeden tarihli plan kesinlestirilmez.",
            "Hasta kartina SAT girilmeli; yoksa en guvenilir USG raporu secilmelidir.",
            "Gebelik haftasi netlesince tarihli gebelik planina aktarilir.",
        ]
    if ga_days < 14 * 7:
        return [
            "Ilk izlem ve risk degerlendirmesi tamamlanmali.",
            "Erken USG ve temel kan/idrar tetkikleri planlanmali.",
            "Bulanti, beslenme, ilac guvenligi ve tehlike isaretleri anlatilmali.",
        ]
    if ga_days < 24 * 7:
        return [
            "11-14 tarama sonucu ve 18-24 ayrintili USG penceresi takip edilmeli.",
            "Plasenta ve fetal olcumler USG raporuna gore kayda alinmali.",
            "Anneye hareketlerin zamanla duzenli hissedilecegi anlatilmali.",
        ]
    if ga_days < 28 * 7:
        return [
            "24-28 hafta seker taramasi/OGTT ihtiyaci hekimce netlestirilmeli.",
            "Tansiyon, proteinuri, tam kan ve demir durumu kontrol edilmeli.",
            "Bebek hareketleri ve acil basvuru kosullari yazili verilmeli.",
        ]
    if ga_days < 36 * 7:
        return [
            "Fetal buyume ve anne tansiyon/idrar izlemi sikilastirilmali.",
            "Dogum tercihleri, hastane plani ve yenidogan hazirligi konusulmali.",
            "Rh, asi ve ek testler kurum protokolune gore kapatilmali.",
        ]
    return [
        "Dogum bulgulari, basvuru esigi ve ulasim plani netlestirilmeli.",
        "NST/AFI/USG takibi klinik duruma gore planlanmali.",
        "Gun asimi ve dogum sekli karari hekim-hasta gorusmesiyle yazilmali.",
    ]


