_PERF_CACHE = {}
_PERF_BUILD_LOCK = threading.Lock()
_PERF_BUILDING_KEYS = set()
_PERF_CACHE_TTL = {
    # D250 PREMIUM: TTL'ler 2-3x uzatildi - tek doktor + dusuk yazma frekansi
    "smart_notifications": 1200,  # 20 dk (D250: 600->1200)
    "delivery_countdown": 2400,   # 40 dk (D250: 1200->2400)
    "perinatology_dashboard": 720,   # 12 dk (D250: 360->720)
    "dashboard_stats": 300,       # 5 dk (D250: 120->300)
    "monthly_report": 7200,       # 2 saat (D250: 3600->7200)
    "web_patient_listing": 600,   # 10 dk (D250: 240->600)
    "web_patient_overview": 420,  # 7 dk (D250: 180->420)
    "web_patient_visits": 360,    # 6 dk (D250: 150->360)
    "web_visit_media": 420,       # 7 dk (D250: 180->420)
    "web_visit_summary": 600,     # 10 dk (D250: 240->600)
    "terminal_patient_listing": 240,  # 4 dk (D250: 90->240)
    "terminal_patient_detail": 180,   # 3 dk (D250: 70->180)
    # D128 SUPER cache TTLs (D250 ile guncel):
    "ga_quick_card": 3600,           # 1 saat - hasta listesi GA chip (D250: 1800->3600)
    "tedavi_hasta_search": 300,      # 5 dk - autocomplete (D250: 120->300)
    "tedavi_hasta_detay": 2400,      # 40 dk - PDF tarayan detay (D250: 1200->2400)
}


def cache_get(key):
    """Cache'ten oku - TTL aÅŸÄ±lmÄ±ÅŸsa None dÃ¶ner."""
    import time as _t
    entry = _PERF_CACHE.get(key)
    if not entry:
        return None
    ts, value, ttl = entry
    if _t.time() - ts > ttl:
        _PERF_CACHE.pop(key, None)
        return None
    return value


def cache_get_with_state(key):
    """Cache oku; expired ise de stale degeri silmeden bildir."""
    import time as _t
    entry = _PERF_CACHE.get(key)
    if not entry:
        return None, False, False
    ts, value, ttl = entry
    fresh = (_t.time() - ts) <= ttl
    return value, True, fresh


def cache_set(key, value, ttl_key=None, ttl_seconds=None):
    """Cache'e yaz."""
    import time as _t
    ttl = (ttl_seconds if ttl_seconds is not None
           else _PERF_CACHE_TTL.get(ttl_key or "", 300))
    _PERF_CACHE[key] = (_t.time(), value, ttl)


def _perf_singleflight_async(key, worker):
    """Ayni pahali isi ayni anda bir kez arka planda calistir."""
    with _PERF_BUILD_LOCK:
        if key in _PERF_BUILDING_KEYS:
            return False
        _PERF_BUILDING_KEYS.add(key)

    def _runner():
        try:
            try:
                with app.app_context():
                    worker()
            except RuntimeError:
                worker()
        except Exception as ex:
            try:
                print(f"perf async build {key}: {ex}")
            except Exception:
                pass
        finally:
            with _PERF_BUILD_LOCK:
                _PERF_BUILDING_KEYS.discard(key)

    threading.Thread(target=_runner, name=f"YKPerfBuild-{str(key)[:48]}", daemon=True).start()
    return True


def cache_invalidate(prefix=None):
    """Cache'i temizle - prefix verilirse sadece o."""
    if prefix is None:
        _PERF_CACHE.clear()
        return
    to_delete = [k for k in _PERF_CACHE.keys()
                 if k.startswith(prefix)]
    for k in to_delete:
        _PERF_CACHE.pop(k, None)


def _pending_data_conflict_count_cached():
    """Pending conflict count'u kisa TTL ile oku; her render'da DB sorgusunu azalt."""
    cache_key = "web_pending_data_conflicts"
    cached = cache_get(cache_key)
    if cached is not None:
        try:
            return max(0, int(cached))
        except Exception:
            return 0
    count = 0
    try:
        with db_conn() as con:
            row = con.execute(
                "SELECT COUNT(*) FROM patient_data_conflicts WHERE status='pending'"
            ).fetchone()
            count = int(row[0] or 0) if row else 0
    except Exception:
        count = 0
    cache_set(cache_key, count, ttl_seconds=120)
    return count


def _patient_folder_person_name(raw_name):
    """Convert NAS/Voluson folder suffix Surname_Name to Name Surname."""
    text = str(raw_name or "").replace("_", " ").strip()
    text = re.sub(r"\s+", " ", text)
    if not text:
        return ""
    parts = [p for p in text.split(" ") if p]
    if len(parts) >= 2:
        surname = parts[0]
        given = " ".join(parts[1:])
        if given and surname:
            return f"{given} {surname}".strip()
    return text


def _person_name_to_family_given(name_text):
    """Human name -> DICOM PatientName format: SOYAD^AD."""
    text = str(name_text or "").strip()
    if not text:
        return ""
    if "^" in text:
        left, right = (text.split("^", 1) + [""])[:2]
        left = re.sub(r"\s+", " ", left.replace("_", " ").strip())
        right = re.sub(r"\s+", " ", right.replace("_", " ").strip())
        if left and right:
            return f"{left}^{right}"
        if left:
            return left
    text = re.sub(r"\s+", " ", text.replace("_", " ").replace("^", " ")).strip()
    parts = [p for p in text.split(" ") if p]
    if not parts:
        return ""
    if len(parts) == 1:
        return parts[0]
    family = parts[-1]
    given = " ".join(parts[:-1])
    return f"{family}^{given}".strip("^")


def _date_display_from_iso(iso_date):
    text = str(iso_date or "").strip()
    match = re.match(r"^(?P<yyyy>\d{4})-(?P<mm>\d{2})-(?P<dd>\d{2})$", text)
    if not match:
        return ""
    return f"{match.group('dd')}.{match.group('mm')}.{match.group('yyyy')}"


def _date_iso_from_text(value):
    """Extract a visit date from folder/file text without trusting mtime."""
    text = str(value or "")
    if not text:
        return ""
    patterns = (
        r"(?<!\d)(?P<yyyy>20\d{2})[-_.]?(?P<mm>\d{2})[-_.]?(?P<dd>\d{2})(?!\d)",
        r"(?<!\d)(?P<yy>\d{2})[-_.](?P<mm>\d{2})[-_.](?P<dd>\d{2})(?:[-_.]\d+)?(?!\d)",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, text):
            try:
                year = int(match.groupdict().get("yyyy") or 0)
                if not year:
                    yy = int(match.group("yy"))
                    year = 2000 + yy if yy < 70 else 1900 + yy
                month = int(match.group("mm"))
                day = int(match.group("dd"))
                datetime(year, month, day)
                return f"{year:04d}-{month:02d}-{day:02d}"
            except Exception:
                continue
    return ""


def _patient_key_name_parts(value):
    """Split technical folder keys like F137230-26-02-26-1_Surname_Name."""
    text = str(value or "").strip()
    if not text:
        return "", "", ""
    text = re.split(r"[\\/]+", text)[-1].strip()
    text = re.sub(r"\s+", " ", text)
    pattern = (
        r"^(?P<prefix>[A-Za-z]?\d{3,}(?:-\d{2}){3}(?:-\d+)?)"
        r"[\s_]+(?P<name>.+)$")
    match = re.match(pattern, text)
    if not match:
        return text, "", ""
    prefix = match.group("prefix")
    clean_name = _patient_folder_person_name(match.group("name"))
    date_text = _date_display_from_iso(_date_iso_from_text(prefix))
    return clean_name or text, prefix, date_text


_VOLUSON_FOLDER_KEY_PATTERN = re.compile(
    r"^[A-Za-z]?\d{3,}(?:-\d{2}){3}(?:-\d+)?(?:[_\s].+)?$"
)


def _patient_name_tokens_for_folder_key(name_text):
    text = str(name_text or "")
    text = fix_mojibake_text(text)
    text = re.sub(r'[<>:"/\\|?*\x00-\x1F]+', " ", text)
    replacements = (
        ("\u0130", "I"), ("\u0131", "i"),
        ("\u015e", "S"), ("\u015f", "s"),
        ("\u011e", "G"), ("\u011f", "g"),
        ("\u00dc", "U"), ("\u00fc", "u"),
        ("\u00d6", "O"), ("\u00f6", "o"),
        ("\u00c7", "C"), ("\u00e7", "c"),
        ("\u00c4\u00b0", "I"), ("\u00c4\u00b1", "i"),
        ("\u00c5\u017d", "S"), ("\u00c5\u009e", "S"),
        ("\u00c5\u0178", "s"), ("\u00c5\u009f", "s"),
        ("\u00c4\u017d", "G"), ("\u00c4\u009e", "G"),
        ("\u00c4\u0178", "g"), ("\u00c4\u009f", "g"),
        ("\u00c3\u0152", "U"), ("\u00c3\u009c", "U"),
        ("\u00c3\u00bc", "u"),
        ("\u00c3\u2013", "O"), ("\u00c3\u0096", "O"),
        ("\u00c3\u00b6", "o"),
        ("\u00c3\u2021", "C"), ("\u00c3\u0087", "C"),
        ("\u00c3\u00a7", "c"),
    )
    for src, dest in replacements:
        text = text.replace(src, dest)
    text = unicodedata.normalize("NFKD", text)
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    text = re.sub(r"[^A-Za-z0-9 ]+", " ", text)
    tokens = [tok for tok in re.split(r"\s+", text.strip()) if tok]
    return [tok.title() for tok in tokens]


def _voluson_folder_name_suffix(name_text):
    tokens = _patient_name_tokens_for_folder_key(name_text)
    if not tokens:
        return "Hasta"
    if len(tokens) == 1:
        return tokens[0]
    surname = tokens[-1]
    given = "_".join(tokens[:-1])
    return f"{surname}_{given}".strip("_")


def _is_voluson_folder_key_like(value):
    return bool(_VOLUSON_FOLDER_KEY_PATTERN.match(str(value or "").strip()))


def _get_voluson_patient_prefix():
    candidates = [
        os.environ.get("YAZKLINIK_VOLUSON_AUTO_PREFIX", "").strip(),
        _db_get_setting("voluson_auto_prefix", "").strip(),
        _db_get_setting("sysparam_voluson_auto_prefix", "").strip(),
    ]
    try:
        from yazklinik_common import load_settings as _load_settings
        cfg = ((_load_settings() or {}).get("integrations", {})
               .get("usg_nas", {}).get("config", {}))
        candidates.append(str(cfg.get("accepted_prefix") or "").strip())
    except Exception:
        pass
    for cand in candidates:
        cleaned = re.sub(r"[^A-Za-z0-9]+", "", cand).upper()
        if cleaned:
            return cleaned
    return "F137230"


def _next_voluson_daily_sequence(base_prefix, patient_root):
    highest = 0
    pattern = re.compile(rf"^{re.escape(base_prefix)}-(\d+)(?:_|$)", re.IGNORECASE)
    like_text = f"{base_prefix}-%"
    try:
        with db_conn() as con:
            rows = con.execute(
                "SELECT folder_key FROM patients WHERE folder_key LIKE ?",
                (like_text,)).fetchall()
        for row in rows or []:
            key = ""
            try:
                key = str(row["folder_key"] or "")
            except Exception:
                try:
                    key = str(row[0] or "")
                except Exception:
                    key = ""
            match = pattern.match(key)
            if match:
                highest = max(highest, int(match.group(1)))
    except Exception:
        pass
    root = Path(patient_root)
    try:
        if root.exists():
            for child in root.iterdir():
                if not child.is_dir():
                    continue
                match = pattern.match(child.name)
                if match:
                    highest = max(highest, int(match.group(1)))
    except Exception:
        pass
    return highest + 1


def _build_voluson_patient_key(name_text, patient_root=None):
    root = Path(patient_root or get_patient_storage_root()).expanduser()
    now = datetime.now()
    base = f"{_get_voluson_patient_prefix()}-{now:%y-%m-%d}"
    suffix = _voluson_folder_name_suffix(name_text)
    seq = _next_voluson_daily_sequence(base, root)
    for _ in range(2000):
        key = f"{base}-{seq}_{suffix}" if suffix else f"{base}-{seq}"
        if not _patient_key_exists(key, patient_root=root):
            return key
        seq += 1
    stamp = now.strftime("%Y%m%d%H%M%S")
    return f"{base}-{seq}_{suffix}_{stamp}" if suffix else f"{base}-{seq}_{stamp}"


def _patient_key_exists(patient_key, patient_root=None):
    key = str(patient_key or "").strip()
    if not key:
        return False
    try:
        with db_conn() as con:
            row = con.execute(
                "SELECT 1 FROM patients WHERE folder_key=? LIMIT 1",
                (key,)).fetchone()
        if row:
            return True
    except Exception:
        pass
    root = Path(patient_root or get_patient_storage_root()).expanduser()
    try:
        return (root / key).exists()
    except Exception:
        return False


def _new_visit_key_voluson(patient_path: Path):
    marker = datetime.now().replace(microsecond=0)
    for _ in range(240):
        candidate = marker.strftime("%Y%m%d_%H%M%S")
        if not (patient_path / candidate).exists():
            return candidate
        marker = marker + timedelta(seconds=1)
    return datetime.now().strftime("%Y%m%d_%H%M%S")


def _ensure_patient_folder_identity(patient_key, display_name="", note_text="",
                                    create_first_visit=True):
    storage_root = get_patient_storage_root()
    storage_root.mkdir(parents=True, exist_ok=True)
    patient_path = storage_root / str(patient_key)
    patient_path.mkdir(parents=True, exist_ok=True)
    _ensure_patient_index_row(patient_key, patient_path, display_name or patient_key)
    if create_first_visit:
        _ensure_initial_manual_visit(patient_key, patient_path, note_text)
    return patient_path


