def _patient_name_looks_like_filename_only(name):
    """D250 2026-05-12: F137230-26-05-07-3__ gibi ad/soyad icermeyen
    salt dosya-adi olusumlarini hasta listesinden gizlemek icin kullanilir.

    Kural: temizlenmis adda en az 2'serli alfabetik bir 'ad' ve 'soyad'
    bulunmuyorsa veya tum string letter+digit+- karisimi yapay bir id ise
    dosya-adi say."""
    s = str(name or "").strip()
    if not s:
        return True
    # F137230-26-05-07-3__ / F12345_26-05-07 / 2024-12-30__123 gibi
    if re.fullmatch(
        r"[A-Za-zÇĞİÖŞÜçğıöşü]{0,4}\d{2,}(?:[-_.]+\d+)*[-_.]*\d*_*",
        s,
    ):
        return True
    # Bosluk yok + en az 3 rakam + harf< rakam (yapay id)
    digit_count = sum(1 for c in s if c.isdigit())
    alpha_count = sum(1 for c in s if c.isalpha())
    if " " not in s and digit_count >= 3 and digit_count >= alpha_count:
        return True
    # Hicbir alfabetik blok (>=2) yok - ornek "F1-2-3"
    if not re.search(r"[A-Za-zÇĞİÖŞÜçğıöşü]{2,}", s):
        return True
    return False


def _patient_folder_date_label(patient_key):
    return _date_display_from_iso(_patient_key_visit_date_iso(patient_key))


def _patient_key_visit_date_iso(patient_key):
    _clean_name, prefix, _date_text = _patient_key_name_parts(patient_key)
    return _date_iso_from_text(prefix or patient_key)


def _patient_visit_date_iso(patient_key, visit_key="", visit_date=""):
    raw_date = str(visit_date or "").strip()
    if raw_date:
        direct = _date_iso_from_text(raw_date[:10])
        if direct:
            return direct
        if re.match(r"^\d{4}-\d{2}-\d{2}", raw_date):
            return raw_date[:10]
    return (
        _date_iso_from_text(visit_key)
        or _patient_key_visit_date_iso(patient_key)
        or raw_date
    )


def _normalize_visit_type(value, fallback="muayene"):
    text = str(value or "").strip().lower()
    fallback = str(fallback or "muayene").strip().lower()
    if "kontrol" in text or text in {"control", "followup", "follow-up"}:
        return "kontrol"
    if "muayene" in text or "examination" in text or "exam" in text:
        return "muayene"
    if "kontrol" in fallback:
        return "kontrol"
    return "muayene"


def _visit_type_label(value):
    return "Kontrol" if _normalize_visit_type(value) == "kontrol" else "Muayene"


def _visit_type_badge_html(value):
    kind = _normalize_visit_type(value)
    if kind == "kontrol":
        return '<span class="badge bg-warning text-dark"><i class="bi bi-check2-square"></i> Kontrol</span>'
    return '<span class="badge bg-primary"><i class="bi bi-clipboard2-pulse"></i> Muayene</span>'


def _visit_clinical_preview(row, note_text=""):
    for key in ("examination", "control_note", "notes"):
        value = str((row or {}).get(key) or "").strip()
        if value:
            return value
    return str(note_text or "").strip()


def _patient_media_visit_date_iso(patient_key, media_path, patient_root=None):
    try:
        path = Path(media_path)
        parts = []
        if patient_root:
            try:
                parts = list(path.resolve().relative_to(Path(patient_root).resolve()).parts)
            except Exception:
                parts = list(path.parts)
        else:
            parts = list(path.parts)
        directory_parts = parts[:-1] if path.suffix else parts
        for part in reversed(directory_parts):
            found = _date_iso_from_text(part)
            if found:
                return found
        if path.suffix:
            found = _date_iso_from_text(path.name)
            if found:
                return found
    except Exception:
        pass
    return _patient_key_visit_date_iso(patient_key)


def _patient_display_label(patient_key, display_name=None, include_date=False):
    folder_name, folder_prefix, _folder_date = _patient_key_name_parts(patient_key)
    explicit = _clean_patient_display_name(display_name or "")
    if explicit and _fold_search_text(explicit) != _fold_search_text(patient_key):
        name = explicit
    else:
        name = folder_name if folder_prefix else _clean_patient_display_name(
            display_name or patient_key)
    if include_date:
        date_text = _patient_folder_date_label(patient_key)
        if date_text and date_text not in name:
            return f"{name} ({date_text})"
    return name


def _is_hidden_demo_patient_record(*values):
    for value in values:
        if value and is_hidden_vendor_demo_patient(value):
            return True
    return _is_non_patient_system_record(*values)


def _is_non_patient_system_record(*values):
    system_names = {
        "$recycle.bin", "$recycle", "recycle", "recycler", "recycled",
        "recycle bin", "recyclebin", "@recycle", "#recycle", ".recycle",
        "trash", ".trash", "trashes", ".trashes", "lost+found",
    }
    for value in values:
        if not value:
            continue
        try:
            parts = re.split(r"[\\/]+", str(value))
        except Exception:
            parts = [str(value)]
        for part in parts:
            name = str(part or "").strip().lower()
            if not name:
                continue
            compact = re.sub(r"[^a-z0-9]+", "", name)
            if name in system_names or compact in system_names:
                return True
            if "recycle" in compact or compact in {"trash", "trashes", "cop"}:
                return True
    return False


