def _build_visit_summary_html(patient_key, visit_key):
    cache_key = f"web_visit_summary_{patient_key}_{visit_key}"
    cached = cache_get(cache_key)
    if cached is not None:
        return fix_mojibake_text(cached)

    pdf_path = ""
    with db_conn() as con:
        _ensure_file_archive_schema(con)
        row = con.execute(
            "SELECT latest_pdf_path FROM visits "
            "WHERE patient_folder_key=? AND visit_key=?",
            (patient_key, visit_key),
        ).fetchone()
        if row and row[0]:
            pdf_path = str(row[0])
        if not pdf_path:
            row = con.execute(
                "SELECT file_name FROM files "
                "WHERE patient_folder_key=? AND visit_key=? AND file_kind='pdf' "
                "AND COALESCE(archived_at, '') = '' "
                "ORDER BY file_name LIMIT 1",
                (patient_key, visit_key),
            ).fetchone()
            if row and row[0]:
                pdf_path = str(_patient_root_for_nas(patient_key) / visit_key / row[0])

    if not pdf_path:
        html = (
            '<div class="card mb-3"><div class="card-header bg-light">'
            'ğŸ“‹ GeliÅŸ Ã–zeti</div><div class="card-body text-muted">'
            'Bu geliÅŸte Ã¶zetlenecek PDF bulunamadÄ±.</div></div>'
        )
        html = fix_mojibake_text(html)
        cache_set(cache_key, html, ttl_key="web_visit_summary")
        return html

    try:
        pdf = Path(pdf_path)
        data = parse_pdf_summary_data(pdf)
        plain = build_pdf_summary_plain(pdf)
        badges = []
        if data.get("is_twin"):
            badges.append('<span class="badge bg-danger me-1">Ä°kiz Gebelik</span>')
        if data.get("ga_days"):
            ga_days = int(data.get("ga_days") or 0)
            badges.append(
                f'<span class="badge bg-primary me-1">GA {ga_days // 7}+{ga_days % 7}</span>'
            )
        if data.get("edd"):
            badges.append(
                f'<span class="badge bg-secondary me-1">EDD {sh(data.get("edd"))}</span>'
            )
        html = f"""
 <div class="card mb-3">
 <div class="card-header bg-light d-flex justify-content-between align-items-center flex-wrap gap-2">
 <span>ğŸ“‹ GeliÅŸ Ã–zeti</span>
 <span>{''.join(badges)}</span>
          </div>
          <div class="card-body">
            <div style="white-space:pre-wrap;line-height:1.55;">{safe_html(plain)}</div>
          </div>
        </div>
        """
    except Exception as ex:
        html = (
            '<div class="alert alert-warning mb-3">'
            f'PDF Ã¶zeti alÄ±namadÄ±: {sh(ex)}'
            '</div>'
        )

    html = fix_mojibake_text(html)
    cache_set(cache_key, html, ttl_key="web_visit_summary")
    return html


_VP_METRICS = (
    ("BPD", "BPD", "mm", "Hadlock"),
    ("HC", "HC", "mm", "Hadlock"),
    ("AC", "AC", "mm", "Hadlock"),
    ("FL", "FL", "mm", "Hadlock"),
    ("CRL", "CRL", "mm", "Robinson"),
    ("NT", "NT", "mm", "FMF"),
    ("EFW", "EFW", "g", "Hadlock AC/BPD/FL"),
)


def _vp_float(value):
    if isinstance(value, (list, tuple)):
        for item in value:
            found = _vp_float(item)
            if found is not None:
                return found
        return None
    if value in (None, ""):
        return None
    text = fix_mojibake_text(str(value)).replace(",", ".")
    match = re.search(r"[-+]?\d+(?:\.\d+)?", text)
    if not match:
        return None
    try:
        return float(match.group(0))
    except Exception:
        return None


def _vp_metric_value(raw):
    if isinstance(raw, (list, tuple)):
        return _vp_float(raw[0] if raw else "")
    return _vp_float(raw)


def _vp_metric_ga(raw):
    if isinstance(raw, (list, tuple)) and len(raw) > 1:
        return _vp_ga_days_from_value(raw[1])
    return None


def _vp_ga_days_from_value(value):
    if value in (None, ""):
        return None
    if isinstance(value, (int, float)) and float(value) > 0:
        return int(float(value))
    text = fix_mojibake_text(str(value)).strip().lower()
    if not text or text in {"-", "none", "null"}:
        return None
    patterns = (
        r"(\d{1,2})\s*w\s*\+?\s*(\d{1,2})?\s*d?",
        r"(\d{1,2})\s*hafta\s*(\d{1,2})?",
        r"(\d{1,2})\s*\+\s*(\d{1,2})",
    )
    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            weeks = int(match.group(1))
            days = int(match.group(2) or 0)
            return weeks * 7 + days
    return None


def _vp_ga_label(ga_days):
    if ga_days is None:
        return "-"
    try:
        days = int(ga_days)
        return f"{days // 7}+{days % 7}"
    except Exception:
        return "-"


def _vp_fold_key(value):
    return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())


def _vp_get_any(data, names, default=""):
    if not isinstance(data, dict):
        return default
    for name in names:
        if name in data:
            return data.get(name)
    targets = {_vp_fold_key(name) for name in names}
    for key, value in data.items():
        if _vp_fold_key(key) in targets:
            return value
    return default


def _vp_metric_raw(data, metric):
    names = {
        "BPD": ("BPD", "Biparietal Diameter"),
        "HC": ("HC", "Head Circumference"),
        "AC": ("AC", "Abdominal Circumference"),
        "FL": ("FL", "Femur Length"),
        "CRL": ("CRL", "Crown Rump Length"),
        "NT": ("NT", "Nuchal Translucency"),
        "EFW": ("EFW", "Estimated Fetal Weight", "Hadlock EFW"),
        "AFI": ("AFI", "Amniotic Fluid Index"),
    }.get(metric, (metric,))
    return _vp_get_any(data, names, "")


def _vp_percentile(metric, value, ga_days):
    if value is None or ga_days is None or metric not in {"BPD", "HC", "AC", "FL", "EFW"}:
        return ""
    try:
        label = percentile_label(float(value), int(round(float(ga_days) / 7.0)), metric)
        label = fix_mojibake_text(label or "").strip()
        low = label.lower()
        if low.startswith("<p10"):
            return "<p10 - p10 alti"
        if low.startswith(">p90"):
            return ">p90 - p90 ustu"
        return label
    except Exception:
        return ""


def _vp_percentile_tone(label):
    text = str(label or "").lower()
    if not text:
        return "muted", "Referans yok"
    if text.startswith("<p10"):
        return "low", "p10 alti dikkat"
    if text.startswith(">p90"):
        return "high", "p90 ustu dikkat"
    return "ok", "Haftaya uyumlu"


def _vp_fmt(value, suffix="", digits=1):
    if value in (None, ""):
        return "-"
    try:
        number = float(value)
        if abs(number - int(number)) < 0.05:
            return f"{int(number)}{suffix}"
        return f"{number:.{digits}f}{suffix}"
    except Exception:
        return f"{sh(value)}{suffix}"


def _vp_date_sort_key(value):
    text = str(value or "")
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%Y%m%d"):
        try:
            return datetime.strptime(text[:10], fmt)
        except Exception:
            pass
    match = re.search(r"(\d{4})[-_.](\d{2})[-_.](\d{2})", text)
    if match:
        try:
            return datetime(int(match.group(1)), int(match.group(2)), int(match.group(3)))
        except Exception:
            pass
    return datetime(1900, 1, 1)


def _vp_patient_identity(patient_key):
    try:
        header = _get_patient_header_data(patient_key)
        return {
            "name": header.get("display_name") or patient_key,
            "protocol_no": header.get("protocol_no") or "",
        }
    except Exception:
        return {"name": str(patient_key), "protocol_no": ""}


def _vp_visit_pdf_candidates(patient_key, limit=140):
    candidates = []
    seen = set()

    def add_candidate(path, visit_key="", visit_date="", source=""):
        if not path:
            return
        try:
            pdf = Path(path)
            key = str(pdf).lower()
            if key in seen:
                return
            seen.add(key)
            candidates.append({
                "path": pdf,
                "visit_key": visit_key or "",
                "visit_date": visit_date or "",
                "source": source or pdf.name,
            })
        except Exception:
            return

    try:
        with db_conn() as con:
            _ensure_file_archive_schema(con)
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            visits = con.execute(
                "SELECT visit_key, visit_date, latest_pdf_path FROM visits "
                "WHERE patient_folder_key=? AND COALESCE(archived_at, '') = '' "
                "ORDER BY COALESCE(visit_date,''), visit_key",
                (patient_key,),
            ).fetchall()
            files = con.execute(
                "SELECT visit_key, file_name, full_path, mtime FROM files "
                "WHERE patient_folder_key=? AND file_kind='pdf' "
                "AND COALESCE(archived_at, '') = '' "
                "ORDER BY COALESCE(mtime,0)",
                (patient_key,),
            ).fetchall()
    except Exception:
        visits, files = [], []

    visit_dates = {str(v.get("visit_key") or ""): str(v.get("visit_date") or "") for v in visits}
    for row in visits:
        add_candidate(
            row.get("latest_pdf_path"),
            str(row.get("visit_key") or ""),
            str(row.get("visit_date") or ""),
            "latest_pdf_path",
        )
    for row in files:
        visit_key = str(row.get("visit_key") or "")
        full_path = row.get("full_path")
        if not full_path:
            full_path = (
                _patient_root_for_nas(patient_key)
                / visit_key
                / str(row.get("file_name") or ""))
        add_candidate(
            full_path,
            visit_key,
            visit_dates.get(visit_key, ""),
            str(row.get("file_name") or ""),
        )

    if not candidates:
        try:
            for item in _scan_patient_nas_media(patient_key, max_candidates=limit, timeout=3.0):
                if item.get("kind") == "pdf":
                    add_candidate(item.get("path"), "", "", item.get("name") or "")
        except Exception:
            pass

    existing = []
    for item in candidates:
        try:
            if item["path"].exists() and item["path"].is_file():
                existing.append(item)
        except Exception:
            continue
    return existing[:limit]


def _vp_fetus_payloads(data):
    if not isinstance(data, dict):
        return [("", {})]
    nested = []
    for key, value in data.items():
        if isinstance(value, dict) and (
                "GA(AUA)" in value or "GA(LMP)" in value or "EFW" in value):
            nested.append((str(key), value))
    if not nested:
        return [("", data)]
    payloads = []
    labels = ("Fetus A", "Fetus B", "Fetus C")
    for idx, (_key, value) in enumerate(nested):
        payloads.append((labels[idx] if idx < len(labels) else f"Fetus {idx + 1}", value))
    return payloads


def _vp_record_from_pdf(patient_key, item, data, fetus_label, fetus_data):
    ga_days = (
        _vp_ga_days_from_value(_vp_get_any(fetus_data, ("ga_days", "GA(AUA)", "GA(LMP)")))
        or _vp_ga_days_from_value(data.get("ga_days") if isinstance(data, dict) else "")
        or _vp_ga_days_from_value(_vp_get_any(fetus_data, ("GA(AUA)", "GA(LMP)")))
    )
    measures = {}
    for metric, _label, _unit, _method in _VP_METRICS:
        raw = _vp_metric_raw(fetus_data, metric)
        value = _vp_metric_value(raw)
        measures[metric] = {
            "raw": raw,
            "value": value,
            "ga_days": _vp_metric_ga(raw) or ga_days,
            "percentile": _vp_percentile(metric, value, _vp_metric_ga(raw) or ga_days),
        }

    if measures["EFW"]["value"] is None:
        try:
            calc = hadlock_efw(
                measures["BPD"]["value"],
                measures["HC"]["value"],
                measures["AC"]["value"],
                measures["FL"]["value"],
            )
            if calc:
                measures["EFW"]["value"] = round(float(calc))
                measures["EFW"]["raw"] = f"{int(round(float(calc)))} g"
                measures["EFW"]["percentile"] = _vp_percentile("EFW", calc, ga_days)
                measures["EFW"]["calculated"] = True
        except Exception:
            pass

    pdf = item.get("path")
    visit_date = str(item.get("visit_date") or "")
    if not visit_date:
        try:
            visit_date = datetime.fromtimestamp(pdf.stat().st_mtime).strftime("%Y-%m-%d")
        except Exception:
            visit_date = ""
    q_patient = quote(str(patient_key), safe="")
    q_visit = quote(str(item.get("visit_key") or ""), safe="")
    pdf_url = ""
    if item.get("visit_key"):
        pdf_url = f"/hasta/{q_patient}/gelis/{q_visit}/dosya/{quote(pdf.name, safe='')}"
    return {
        "patient_name": _vp_get_any(data, ("Hasta", "patient_name", "Name"), ""),
        "patient_age": _vp_get_any(data, ("Age", "Hasta Yasi", "patient_age"), ""),
        "fetus_label": fetus_label,
        "visit_key": str(item.get("visit_key") or ""),
        "visit_date": visit_date,
        "pdf_name": pdf.name if pdf else "",
        "pdf_path": str(pdf or ""),
        "pdf_url": pdf_url,
        "ga_days": ga_days,
        "ga_label": _vp_ga_label(ga_days),
        "edd": _vp_get_any(data, ("edd", "EDD"), ""),
        "is_twin": bool(data.get("is_twin")) if isinstance(data, dict) else False,
        "measures": measures,
        "summary": "",
    }


def _vp_collect_patient_pdf_measurements(patient_key, limit=80):
    records = []
    warnings = []
    for item in _vp_visit_pdf_candidates(patient_key, limit=limit):
        pdf = item.get("path")
        try:
            data = parse_pdf_summary_data(pdf)
            try:
                plain = build_pdf_summary_plain(pdf)
            except Exception:
                plain = ""
            for fetus_label, fetus_data in _vp_fetus_payloads(data):
                record = _vp_record_from_pdf(patient_key, item, data, fetus_label, fetus_data)
                record["summary"] = fix_mojibake_text(str(plain or ""))[:1800]
                records.append(record)
        except Exception as ex:
            warnings.append(f"{pdf.name if pdf else 'PDF'}: {ex}")

    records.sort(key=lambda row: (
        row.get("ga_days") if row.get("ga_days") is not None else 9999,
        _vp_date_sort_key(row.get("visit_date")),
        row.get("pdf_name") or "",
        row.get("fetus_label") or "",
    ))
    return records, warnings


def _vp_latest_previous(records):
    if not records:
        return {}, {}
    latest = records[-1]
    for row in reversed(records[:-1]):
        if row.get("fetus_label") == latest.get("fetus_label"):
            return latest, row
    return latest, records[-2] if len(records) > 1 else {}


def _vp_measure_value(record, metric):
    try:
        return ((record or {}).get("measures") or {}).get(metric, {}).get("value")
    except Exception:
        return None


def _vp_measure_percentile(record, metric):
    try:
        return ((record or {}).get("measures") or {}).get(metric, {}).get("percentile") or ""
    except Exception:
        return ""


def _vp_last_visit_age_days(visits):
    for row in visits or []:
        day = _preg_plan_parse_date_v1000(row.get("visit_date"))
        if day:
            return (datetime.now().date() - day).days
    return None


def _vp_visit_intelligence(patient_key, records, limit=32):
    by_visit = {}
    for record in records or []:
        visit_key = str(record.get("visit_key") or "")
        if not visit_key:
            continue
        by_visit.setdefault(visit_key, []).append(record)
    visits = []
    notes_map = {}
    try:
        payload = _get_patient_visits_listing(patient_key, limit=limit) or {}
        visits = list(payload.get("visits") or [])
        notes_map = payload.get("notes_map") or {}
    except Exception:
        visits = []
        notes_map = {}

    timeline = []
    used = set()
    for visit in visits:
        visit_key = str(visit.get("visit_key") or "")
        used.add(visit_key)
        linked = by_visit.get(visit_key) or []
        best = linked[-1] if linked else {}
        timeline.append({
            "visit_key": visit_key,
            "visit_date": visit.get("visit_date") or "",
            "file_count": int(visit.get("file_count") or 0),
            "pdf_count": int(visit.get("pdf_count") or 0),
            "image_count": int(visit.get("image_count") or 0),
            "video_count": int(visit.get("video_count") or 0),
            "note": notes_map.get(visit_key, ""),
            "ga_label": best.get("ga_label") or "",
            "efw": _vp_measure_value(best, "EFW"),
            "efw_percentile": _vp_measure_percentile(best, "EFW"),
            "source_pdf": best.get("pdf_name") or "",
            "has_pdf_measurement": bool(linked),
        })

    for record in records or []:
        visit_key = str(record.get("visit_key") or "")
        if visit_key and visit_key in used:
            continue
        timeline.append({
            "visit_key": visit_key,
            "visit_date": record.get("visit_date") or "",
            "file_count": 0,
            "pdf_count": 1,
            "image_count": 0,
            "video_count": 0,
            "note": "",
            "ga_label": record.get("ga_label") or "",
            "efw": _vp_measure_value(record, "EFW"),
            "efw_percentile": _vp_measure_percentile(record, "EFW"),
            "source_pdf": record.get("pdf_name") or "",
            "has_pdf_measurement": True,
        })
    timeline.sort(key=lambda row: _vp_date_sort_key(row.get("visit_date")), reverse=True)
    return timeline[:limit]


def _vp_efw_velocity_status(latest, previous):
    current = _vp_measure_value(latest, "EFW")
    old = _vp_measure_value(previous, "EFW")
    if current is None or old is None:
        return {}
    if latest.get("ga_days") is None or previous.get("ga_days") is None:
        return {}
    day_delta = int(latest.get("ga_days") or 0) - int(previous.get("ga_days") or 0)
    if day_delta <= 0:
        return {}
    weekly = (float(current) - float(old)) / day_delta * 7.0
    exp_prev = _growth_interp_v1000(float(previous["ga_days"]) / 7.0, 1)
    exp_now = _growth_interp_v1000(float(latest["ga_days"]) / 7.0, 1)
    expected = None
    ratio = None
    if exp_prev and exp_now:
        expected = (float(exp_now) - float(exp_prev)) / day_delta * 7.0
        ratio = weekly / expected if expected else None
    tone = "muted"
    label = "Hiz kiyaslamasi sinirli"
    if ratio is not None:
        if ratio < 0.75:
            tone = "low"
            label = "Haftalik EFW artisi yavas"
        elif ratio > 1.25:
            tone = "high"
            label = "Haftalik EFW artisi hizli"
        else:
            tone = "ok"
            label = "Haftalik EFW artisi uyumlu"
    return {
        "weekly_gain": weekly,
        "expected_weekly_gain": expected,
        "ratio": ratio,
        "tone": tone,
        "label": label,
        "summary": (
            f"Son iki olcum arasinda haftalik artis {_vp_fmt(weekly, ' g')}; "
            f"beklenen {_vp_fmt(expected, ' g') if expected else '-'}."
        ),
    }


def _vp_data_quality(identity, profile, records, warnings, timeline):
    checks = [
        ("Kimlik", bool(identity.get("name"))),
        ("Yas", bool(profile.get("age"))),
        ("Kilo", bool(profile.get("weight"))),
        ("Boy", bool(profile.get("height"))),
        ("SAT/LMP", bool(profile.get("lmp_text"))),
        ("EDD", bool(profile.get("edd_text"))),
        ("Gebelik haftasi", profile.get("ga_days") is not None),
        ("PDF olcum", bool(records)),
        ("EFW", any(_vp_measure_value(r, "EFW") is not None for r in records or [])),
        ("BPD/HC/AC/FL", any(
            all(_vp_measure_value(r, m) is not None for m in ("BPD", "HC", "AC", "FL"))
            for r in records or [])),
        ("Gelis notu", any((r.get("note") or "").strip() for r in timeline or [])),
        ("Okunamayan PDF yok", not warnings),
    ]
    done = sum(1 for _label, ok in checks if ok)
    score = int(round(done / max(1, len(checks)) * 100))
    missing = [label for label, ok in checks if not ok]
    if score >= 85:
        tone = "ok"
        label = "ViewPoint kalitesinde dosya"
    elif score >= 60:
        tone = "high"
        label = "Klinik veri tamamlanmali"
    else:
        tone = "low"
        label = "Eksik veri takibi gerekli"
    return {
        "score": score,
        "tone": tone,
        "label": label,
        "checks": checks,
        "missing": missing,
    }


def _vp_risk_radar(patient_key, profile, latest, previous, records, warnings, timeline):
    cards = []
    latest_efw_pct = _vp_measure_percentile(latest, "EFW")
    latest_tone, latest_status = _vp_percentile_tone(latest_efw_pct)
    if latest_tone in {"low", "high"}:
        cards.append({
            "tone": latest_tone,
            "title": "EFW persentil uyarisi",
            "text": f"Son EFW {latest_efw_pct}; {latest_status}. Klinik korelasyon ve gerekirse yakin takip.",
        })
    velocity = _vp_efw_velocity_status(latest, previous)
    if velocity.get("tone") in {"low", "high"}:
        cards.append({
            "tone": velocity["tone"],
            "title": velocity.get("label") or "EFW hiz uyarisi",
            "text": velocity.get("summary") or "",
        })
    if warnings:
        cards.append({
            "tone": "high",
            "title": "Okunamayan PDF var",
            "text": f"{len(warnings)} rapor tam okunamadi; rapor/PDF atÃ¶lyesinde kontrol edin.",
        })
    if not records:
        cards.append({
            "tone": "low",
            "title": "PDF biometri yok",
            "text": "Hasta klasorundeki USG/PDF raporlari indekslenirse grafik ve kiyas otomatik dolar.",
        })
    if profile.get("ga_days") is None:
        cards.append({
            "tone": "high",
            "title": "Tarihleme eksik",
            "text": "SAT/LMP, EDD veya USG haftasi bulunamadi; hasta dosyasinda duzeltilebilir.",
        })
    last_age = _vp_last_visit_age_days(timeline)
    if last_age is not None and last_age > 35:
        cards.append({
            "tone": "high",
            "title": "Kontrol araligi uzamis",
            "text": f"Son gelis yaklasik {last_age} gun once. Takip sikligi klinik duruma gore gozden gecsin.",
        })
    try:
        flags = get_patient_flags(patient_key) or {}
        danger_labels = [
            PATIENT_FLAG_LABELS.get(name, name)
            for name, data in flags.items()
            if data.get("value") == "1" and PATIENT_FLAG_LEVELS.get(name) == "danger"
        ]
        if danger_labels:
            cards.append({
                "tone": "low",
                "title": "Hasta bayraklari",
                "text": ", ".join(danger_labels[:4]),
            })
    except Exception:
        pass
    if not cards:
        cards.append({
            "tone": "ok",
            "title": "Klinik radar sakin",
            "text": "Mevcut veride otomatik oncelikli alarm yok; rutin hekim degerlendirmesi surer.",
        })
    return cards[:8], velocity


def _vp_next_best_actions(patient_key, profile, risks, quality):
    q_patient = quote(str(patient_key), safe="")
    actions = []
    ga_days = profile.get("ga_days")
    if ga_days is not None:
        for item in _preg_plan_milestones_v1000(ga_days, include_past=False)[:3]:
            actions.append({
                "title": item.get("title") or "Gebelik kontrolu",
                "detail": f"{item.get('week')} / {item.get('date')} - {item.get('state')}",
                "url": f"/hasta/{q_patient}/gebelik-takip-plani",
                "icon": "bi-calendar2-heart",
            })
    if quality.get("missing"):
        actions.append({
            "title": "Eksik klinik veriyi tamamla",
            "detail": ", ".join(quality.get("missing", [])[:4]),
            "url": f"/hasta/{q_patient}/hasta-dosyasi",
            "icon": "bi-ui-checks-grid",
        })
    if any(r.get("tone") in {"low", "high"} for r in risks):
        actions.append({
            "title": "Riskli bulgulari gozden gecir",
            "detail": "Persentil, EFW hizi ve hasta bayraklari tek ekranda kontrol edilsin.",
            "url": f"/hasta/{q_patient}/gebelik-gelisim-takibi",
            "icon": "bi-graph-up-arrow",
        })
    actions.extend([
        {
            "title": "Rapor atolyesinde PDF duzenle",
            "detail": "Var olan rapor uzerine kase, resim, sayfa ve hasta ozeti ekle.",
            "url": f"/hasta/{q_patient}/pdf-atolyesi",
            "icon": "bi-file-earmark-pdf",
        },
        {
            "title": "NAS/DICOM dosyalarini kontrol et",
            "detail": "Ayni hasta icinde DICOM, goruntu, video ve PDF arsivini ac.",
            "url": f"/hasta/{q_patient}/dosya-gezgini",
            "icon": "bi-hdd-network",
        },
    ])
    return actions[:7]


def _vp_command_payload(patient_key, identity, profile, records, warnings):
    latest, previous = _vp_latest_previous(records)
    timeline = _vp_visit_intelligence(patient_key, records)
    quality = _vp_data_quality(identity, profile, records, warnings, timeline)
    risks, velocity = _vp_risk_radar(
        patient_key, profile, latest, previous, records, warnings, timeline)
    actions = _vp_next_best_actions(patient_key, profile, risks, quality)
    return {
        "identity": identity,
        "profile": {
            "age": profile.get("age"),
            "weight": profile.get("weight"),
            "height": profile.get("height"),
            "bmi": profile.get("bmi"),
            "ga_label": profile.get("ga_label"),
            "ga_days": profile.get("ga_days"),
            "trimester": profile.get("trimester"),
            "lmp_text": profile.get("lmp_text"),
            "edd_text": profile.get("edd_text"),
            "dating_source": (profile.get("dating") or {}).get("source"),
        },
        "quality": quality,
        "risks": risks,
        "velocity": velocity,
        "next_actions": actions,
        "timeline": timeline,
        "record_count": len(records or []),
    }


