def _build_visit_media_html_rich(patient_key, visit_key):
    """Premium media grid for AJAX-loaded visit media."""
    cache_key = f"web_visit_media_{patient_key}_{visit_key}_rich"
    cached = cache_get(cache_key)
    if cached is not None:
        return fix_mojibake_text(cached)

    with db_conn() as con:
        _ensure_file_archive_schema(con)
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        files = con.execute(
            "SELECT file_name, file_kind, size_bytes, full_path, mtime FROM files "
            "WHERE patient_folder_key=? AND visit_key=? "
            "AND COALESCE(archived_at, '') = '' "
            "ORDER BY file_kind, file_name",
            (patient_key, visit_key),
        ).fetchall()
