def _get_terminal_patient_detail_cached(patient_key):
    cache_key = f"terminal_patient_{patient_key}"
    cached = cache_get(cache_key)
    if cached is not None:
        return cached

    detail = {"patient_key": patient_key}
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        row = con.execute(
            "SELECT * FROM patients WHERE folder_key=? "
            "AND COALESCE(archived_at, '') = ''",
            (patient_key,),
        ).fetchone()
        if row:
            detail.update(dict(row))

        try:
            pt = con.execute(
                "SELECT * FROM patient_type WHERE patient_key=?",
                (patient_key,),
            ).fetchone()
            if pt:
                detail["type_info"] = dict(pt)
        except Exception:
            pass

        try:
            detail["demographics"] = load_patient_demographics(patient_key) or {}
        except Exception:
            detail["demographics"] = {}

        try:
            visits = con.execute(
                "SELECT * FROM visits WHERE patient_folder_key=? "
                "AND COALESCE(archived_at, '') = '' "
                "ORDER BY visit_date DESC LIMIT 30",
                (patient_key,),
            ).fetchall()
            detail["visits"] = [dict(v) for v in visits]
        except Exception:
            detail["visits"] = []

        try:
            detail["flags"] = get_patient_flags(patient_key) or {}
        except Exception:
            detail["flags"] = {}

    cache_set(cache_key, detail, ttl_key="terminal_patient_detail")
    return detail


def _patient_whatsapp_primary_actions_html(patient_key, visit_key="", btn_size="lg",
                                           include_files_button=True):
    q_patient = quote(str(patient_key), safe="")
    size_class = f" btn-{btn_size}" if btn_size else ""
    hidden_visit = ""
    visit_folder_button = ""
    files_form = ""
    files_label = "Son gelis dosyalarini gonder"
    zip_label = "WhatsApp ZIP gonder"
    if str(visit_key or "").strip():
        q_visit = quote(str(visit_key), safe="")
        files_label = "Acik gelis dosyalarini gonder"
        zip_label = "Acik gelis ZIP gonder"
        hidden_visit = (
            f'<input type="hidden" name="visit_key" '
            f'value="{safe_attr(visit_key)}">'
        )
        folder_path = ""
        try:
            _visit, folder = _find_visit_for_whatsapp(patient_key, visit_key)
            if folder:
                folder_path = str(Path(folder))
        except Exception:
            folder_path = ""
        native_folder_url = (
            "yazklinik-open-folder://open?" + urlencode({"path": folder_path})
            if folder_path else "")
        visit_folder_button = f"""
      <button type="button"
              class="btn btn-outline-dark{size_class}"
              data-native-url="{safe_attr(native_folder_url)}"
              data-api-url="/api/hasta/{q_patient}/gelis/{q_visit}/klasor-ac"
              onclick="return ykOpenVisitFolderA118(event,this)">
        <i class="bi bi-folder2-open"></i> Gelis klasorunu ac
      </button>
        """
    if include_files_button:
        files_form = f"""
      <form method="POST" action="/hasta/{q_patient}/whatsapp/son-gelis"
            class="d-inline">
        {hidden_visit}
        <button type="submit" name="mode" value="files"
                class="btn btn-success{size_class}">
          <i class="bi bi-images"></i> {files_label}
        </button>
      </form>
        """
    return f"""
      <script>
        window.ykOpenVisitFolderA118 = window.ykOpenVisitFolderA118 || function(ev, btn) {{
          if (ev) {{ ev.preventDefault(); ev.stopPropagation(); }}
          btn = btn || (ev && ev.currentTarget);
          if (!btn) return false;
          var nativeUrl = btn.getAttribute('data-native-url') || '';
          var apiUrl = btn.getAttribute('data-api-url') || '';
          var isWebShell = false;
          var isLocal = false;
          try {{
            isWebShell = document.documentElement.hasAttribute('data-yazklinik-webshell') ||
              (document.body && document.body.classList.contains('yk-webshell-embedded'));
            var h = (window.location.hostname || '').toLowerCase();
            isLocal = !h || h === 'localhost' || h === '127.0.0.1' || h === '::1';
          }} catch(e) {{}}
          if (nativeUrl) {{
            var nativeSent = false;
            var bridgeTried = false;
            try {{
              if (window.ykNativeOpenUrl) {{
                bridgeTried = true;
                nativeSent = !!window.ykNativeOpenUrl(nativeUrl);
              }}
            }} catch(e) {{}}
            if (!nativeSent) {{
              try {{
                window.location.href = nativeUrl;
                nativeSent = true;
              }} catch(e) {{}}
            }}
            if ((isWebShell || !isLocal) && bridgeTried && nativeSent) return false;
          }}
          if (apiUrl) {{
            window.setTimeout(function() {{
              fetch(apiUrl, {{method:'POST', headers:{{'Accept':'application/json'}}}})
                .then(function(r) {{ return r.json().then(function(d) {{ d.httpOk = r.ok; return d; }}); }})
                .then(function(d) {{
                  if (!d.ok) alert(d.message || 'Gelis klasoru acilamadi.');
                }})
                .catch(function(err) {{ alert('Gelis klasoru acilamadi: ' + err); }});
            }}, nativeUrl ? 250 : 0);
          }}
          return false;
        }};
      </script>
      <a href="/hasta/{q_patient}/whatsapp"
         class="btn btn-success{size_class}">
        <i class="bi bi-whatsapp"></i> WhatsApp
      </a>
      {visit_folder_button}
      {files_form}
      <form method="POST" action="/hasta/{q_patient}/whatsapp/son-gelis"
            class="d-inline">
        {hidden_visit}
        <button type="submit" name="mode" value="zip"
                class="btn btn-outline-success{size_class}">
          <i class="bi bi-file-zip"></i> {zip_label}
        </button>
      </form>
    """


def _patient_detail_action_link_html(href, icon, label, tone="", target=""):
    target_attr = ' target="_blank"' if target == "_blank" else ""
    return (
        f'<a href="{safe_attr(href)}" class="yk-action-chip {safe_attr(tone)}"'
        f'{target_attr}>'
        f'<i class="bi {safe_attr(icon)}"></i><span>{label}</span>'
        f'</a>'
    )


def _patient_detail_action_post_html(action, mode, icon, label, tone=""):
    return (
        f'<form method="POST" action="{safe_attr(action)}" class="yk-action-form">'
        f'<button type="submit" name="mode" value="{safe_attr(mode)}" '
        f'class="yk-action-chip {safe_attr(tone)}">'
        f'<i class="bi {safe_attr(icon)}"></i><span>{label}</span>'
        f'</button></form>'
    )


