def _system_memory_snapshot():
    total = 0
    available = 0
    try:
        import psutil
        vm = psutil.virtual_memory()
        total = int(vm.total or 0)
        available = int(vm.available or 0)
    except Exception:
        if os.name == "nt":
            try:
                import ctypes

                class MEMORYSTATUSEX(ctypes.Structure):
                    _fields_ = [
                        ("dwLength", ctypes.c_ulong),
                        ("dwMemoryLoad", ctypes.c_ulong),
                        ("ullTotalPhys", ctypes.c_ulonglong),
                        ("ullAvailPhys", ctypes.c_ulonglong),
                        ("ullTotalPageFile", ctypes.c_ulonglong),
                        ("ullAvailPageFile", ctypes.c_ulonglong),
                        ("ullTotalVirtual", ctypes.c_ulonglong),
                        ("ullAvailVirtual", ctypes.c_ulonglong),
                        ("sullAvailExtendedVirtual", ctypes.c_ulonglong),
                    ]

                stat = MEMORYSTATUSEX()
                stat.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
                if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(stat)):
                    total = int(stat.ullTotalPhys or 0)
                    available = int(stat.ullAvailPhys or 0)
            except Exception:
                pass
        if not total:
            try:
                page = os.sysconf("SC_PAGE_SIZE")
                phys = os.sysconf("SC_PHYS_PAGES")
                avail = os.sysconf("SC_AVPHYS_PAGES")
                total = int(page * phys)
                available = int(page * avail)
            except Exception:
                pass
    return {
        "total_bytes": total,
        "available_bytes": available,
        "total_gb": _fmt_gb(total),
        "available_gb": _fmt_gb(available),
    }


def _system_cpu_snapshot():
    logical = int(os.cpu_count() or 1)
    physical = 0
    name = ""
    max_clock_mhz = 0
    try:
        import psutil
        physical = int(psutil.cpu_count(logical=False) or 0)
        if not logical:
            logical = int(psutil.cpu_count(logical=True) or 1)
    except Exception:
        pass
    if os.name == "nt":
        try:
            flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            ps = (
                "Get-CimInstance Win32_Processor | "
                "Select-Object -First 1 Name,NumberOfCores,"
                "NumberOfLogicalProcessors,MaxClockSpeed | ConvertTo-Json -Compress"
            )
            proc = subprocess.run(
                ["powershell", "-NoProfile", "-Command", ps],
                capture_output=True,
                text=True,
                timeout=2.5,
                creationflags=flags,
            )
            if proc.returncode == 0 and proc.stdout.strip():
                row = json.loads(proc.stdout.strip())
                if isinstance(row, list) and row:
                    row = row[0]
                if isinstance(row, dict):
                    name = str(row.get("Name") or "").strip()
                    physical = _gpu_parse_int(row.get("NumberOfCores"), physical)
                    logical = _gpu_parse_int(row.get("NumberOfLogicalProcessors"), logical)
                    max_clock_mhz = _gpu_parse_int(row.get("MaxClockSpeed"), 0)
        except Exception:
            pass
    return {
        "name": name or platform.processor() or "CPU",
        "physical_cores": int(physical or 0),
        "logical_processors": int(logical or 1),
        "max_clock_mhz": int(max_clock_mhz or 0),
    }


def _media_ram_cache_float(raw, default, minimum, maximum):
    try:
        value = float(str(raw).replace(",", "."))
    except Exception:
        value = float(default)
    return max(float(minimum), min(float(maximum), value))


def _ram_auto_profile(memory=None):
    """Return safe RAM/cache defaults from the installed server RAM size."""
    memory = memory or _system_memory_snapshot()
    total_gb = float((memory or {}).get("total_gb") or 0)
    if total_gb >= 120:
        media_gb, reserve_gb = 72, 24
        max_file_mb, program_mb = 6144, 1536
        thumb_items, thumb_mb = 4096, 1024
    elif total_gb >= 60:
        media_gb, reserve_gb = 32, 16
        max_file_mb, program_mb = 4096, 1024
        thumb_items, thumb_mb = 3072, 768
    elif total_gb >= 32:
        media_gb, reserve_gb = 14, 10
        max_file_mb, program_mb = 2048, 512
        thumb_items, thumb_mb = 1536, 384
    elif total_gb >= 16:
        media_gb, reserve_gb = 6, 6
        max_file_mb, program_mb = 1024, 256
        thumb_items, thumb_mb = 768, 192
    else:
        media_gb, reserve_gb = 2, 4
        max_file_mb, program_mb = 512, 128
        thumb_items, thumb_mb = 384, 96
    # Never let defaults try to reserve more cache than the machine can carry.
    if total_gb:
        media_gb = int(max(1, min(media_gb, max(1, total_gb - reserve_gb - 2))))
    return {
        "total_gb": round(total_gb, 2),
        "media_ram_cache_gb": media_gb,
        "media_ram_cache_max_file_mb": max_file_mb,
        "ram_reserve_gb": reserve_gb,
        "program_ram_cache_mb": program_mb,
        "thumb_cache_items": thumb_items,
        "thumb_cache_mb": thumb_mb,
        "media_ram_cache_enabled": True,
        "media_ram_cache_video_enabled": True,
        "media_ram_cache_prewarm_enabled": total_gb >= 60,
        "ram_auto_use_available_enabled": True,
        "program_ram_cache_enabled": True,
    }


def _hardware_auto_profile(force=False):
    cached = getattr(_hardware_auto_profile, "_cache", None)
    now = time.monotonic()
    if cached and not force and now - cached[0] < 5.0:
        return dict(cached[1])
    memory = _system_memory_snapshot()
    cpu = _system_cpu_snapshot()
    ram_profile = _ram_auto_profile(memory)
    gpu = {}
    try:
        gpu = _gpu_auto_profile(force=bool(force))
    except Exception:
        gpu = {}
    logical = max(1, int(cpu.get("logical_processors") or os.cpu_count() or 1))
    physical = max(1, int(cpu.get("physical_cores") or max(1, logical // 2)))
    total_gb = float(memory.get("total_gb") or 0)
    if total_gb >= 60 and logical >= 16:
        waitress_threads = min(32, max(20, logical + 4))
        ocr_workers = min(6, max(3, physical // 2))
        pdf_workers = min(6, max(3, physical // 2))
        ollama_threads = min(12, max(8, physical))
        tier = "workstation_64gb"
    elif total_gb >= 32 and logical >= 8:
        waitress_threads = min(24, max(12, logical + 2))
        ocr_workers = min(4, max(2, physical // 2))
        pdf_workers = min(4, max(2, physical // 2))
        ollama_threads = min(10, max(6, physical))
        tier = "workstation_32gb"
    elif total_gb >= 16:
        waitress_threads = min(16, max(8, logical))
        ocr_workers = 2
        pdf_workers = 2
        ollama_threads = min(8, max(4, physical))
        tier = "standard_16gb"
    else:
        waitress_threads = min(8, max(4, logical))
        ocr_workers = 1
        pdf_workers = 1
        ollama_threads = min(4, max(2, physical))
        tier = "safe_low_ram"
    if str(gpu.get("tier") or "") == "rtx_6gb":
        # 6 GB VRAM'da paralel yerel YZ yerine tek akisi hizli tutmak daha saglam.
        ollama_parallel = 1
    else:
        ollama_parallel = 2 if total_gb >= 60 and logical >= 16 else 1
    profile = {
        "enabled": _gpu_truthy(os.environ.get("YAZKLINIK_HARDWARE_AUTO", "1"), True),
        "tier": tier,
        "cpu": cpu,
        "memory": memory,
        "gpu": gpu,
        "waitress_threads": int(waitress_threads),
        "ollama_num_thread": int(ollama_threads),
        "ollama_num_parallel": int(ollama_parallel),
        "ocr_max_workers": int(ocr_workers),
        "pdf_max_workers": int(pdf_workers),
        "ram_cache": ram_profile,
    }
    _hardware_auto_profile._cache = (now, dict(profile))
    return profile


def _resolve_waitress_threads(raw=None):
    raw = os.environ.get("YAZKLINIK_WAITRESS_THREADS", raw if raw is not None else "auto")
    text = str(raw if raw is not None else "").strip().lower()
    if text in {"", "auto", "default", "donanim", "hardware"}:
        try:
            return int(_hardware_auto_profile().get("waitress_threads") or 16)
        except Exception:
            return min(24, max(8, int(os.cpu_count() or 8)))
    try:
        return max(4, min(64, int(float(text.replace(",", ".")))))
    except Exception:
        return min(24, max(8, int(os.cpu_count() or 8)))


def _media_ram_cache_config(force=False):
    """GB-limited in-process multimedia cache for fast patient work."""
    now = time.monotonic()
    cached = getattr(_media_ram_cache_config, "_cache", None)
    if cached and not force and now - cached[0] < 2.0:
        return dict(cached[1])

    memory = _system_memory_snapshot()
    profile = _ram_auto_profile(memory)
    env_gb = os.environ.get("YAZKLINIK_MEDIA_RAM_CACHE_GB", "").strip()
    raw_gb = (
        env_gb or
        _db_get_setting(
            "sysparam_media_ram_cache_gb",
            str(profile["media_ram_cache_gb"]))
    )
    raw_file_mb = (
        os.environ.get("YAZKLINIK_MEDIA_RAM_CACHE_MAX_FILE_MB", "").strip()
        or _db_get_setting(
            "sysparam_media_ram_cache_max_file_mb",
            str(profile["media_ram_cache_max_file_mb"]))
    )
    configured_gb = _media_ram_cache_float(
        raw_gb, profile["media_ram_cache_gb"], 0, 180)
    ram_auto_enabled = _setting_to_bool(
        _db_get_setting(
            "sysparam_ram_auto_use_available_enabled",
            "1" if profile["ram_auto_use_available_enabled"] else "0"),
        default=True)
    raw_reserve_gb = (
        os.environ.get("YAZKLINIK_RAM_RESERVE_GB", "").strip()
        or _db_get_setting("sysparam_ram_reserve_gb", str(profile["ram_reserve_gb"]))
    )
    reserve_gb = _media_ram_cache_float(
        raw_reserve_gb, profile["ram_reserve_gb"], 2, 128)
    current_cache_gb = _fmt_gb(_MEDIA_RAM_CACHE_BYTES + _PROGRAM_RAM_CACHE_BYTES)
    if ram_auto_enabled and float(memory.get("available_gb") or 0) > 0:
        usable_gb = max(
            0.0,
            float(memory.get("available_gb") or 0) + float(current_cache_gb) - reserve_gb)
        max_gb = min(configured_gb, usable_gb)
    else:
        max_gb = configured_gb
    max_bytes = int(max_gb * 1024 * 1024 * 1024)
    max_file_mb = _media_ram_cache_float(
        raw_file_mb, profile["media_ram_cache_max_file_mb"],
        1, max(1, configured_gb * 1024))
    cfg = {
        "enabled": _setting_to_bool(
            _db_get_setting("sysparam_media_ram_cache_enabled", "1"),
            default=True),
        "video_enabled": _setting_to_bool(
            _db_get_setting(
                "sysparam_media_ram_cache_video_enabled",
                "1" if profile["media_ram_cache_video_enabled"] else "0"),
            default=profile["media_ram_cache_video_enabled"]),
        "prewarm_enabled": _setting_to_bool(
            _db_get_setting(
                "sysparam_media_ram_cache_prewarm_enabled",
                "1" if profile["media_ram_cache_prewarm_enabled"] else "0"),
            default=profile["media_ram_cache_prewarm_enabled"]),
        "ram_auto_enabled": ram_auto_enabled,
        "ram_reserve_gb": round(reserve_gb, 2),
        "configured_gb": round(configured_gb, 2),
        "max_gb": round(max_gb, 2),
        "max_bytes": max_bytes,
        "max_file_mb": round(max_file_mb, 1),
        "max_file_bytes": int(max_file_mb * 1024 * 1024),
        "program_cache_enabled": _setting_to_bool(
            _db_get_setting(
                "sysparam_program_ram_cache_enabled",
                "1" if profile["program_ram_cache_enabled"] else "0"),
            default=profile["program_ram_cache_enabled"]),
        "program_cache_mb": round(_media_ram_cache_float(
            os.environ.get("YAZKLINIK_PROGRAM_RAM_CACHE_MB", "").strip()
            or _db_get_setting(
                "sysparam_program_ram_cache_mb",
                str(profile["program_ram_cache_mb"])),
            profile["program_ram_cache_mb"], 16, 4096), 1),
        "memory": memory,
        "auto_profile": profile,
    }
    if cfg["max_bytes"] <= 0:
        cfg["enabled"] = False
    _media_ram_cache_config._cache = (now, dict(cfg))
    return cfg


def _media_ram_cache_allowed(path, kind, size, cfg):
    if not cfg.get("enabled"):
        return False, "disabled"
    path = Path(path)
    ext = path.suffix.lower()
    kind = kind or _file_kind_for_path(path)
    allowed_exts = (
        IMAGE_EXTS_WEB | VIDEO_EXTS_WEB | AUDIO_EXTS_WEB |
        PDF_EXTS_WEB | DICOM_EXTS_WEB
    )
    if ext not in allowed_exts:
        return False, "not_media"
    if kind == "video" and not cfg.get("video_enabled"):
        return False, "video_disabled"
    if int(size or 0) <= 0:
        return False, "empty"
    if int(size) > int(cfg.get("max_file_bytes") or 0):
        return False, "too_large_file"
    if int(size) > int(cfg.get("max_bytes") or 0):
        return False, "too_large_cache"
    return True, "ok"


def _media_ram_cache_apply_limits(cfg=None):
    global _MEDIA_RAM_CACHE_BYTES, _MEDIA_RAM_CACHE_EVICTIONS
    cfg = cfg or _media_ram_cache_config()
    max_bytes = int(cfg.get("max_bytes") or 0)
    with _MEDIA_RAM_CACHE_LOCK:
        if not cfg.get("enabled") or max_bytes <= 0:
            _MEDIA_RAM_CACHE.clear()
            _MEDIA_RAM_CACHE_BYTES = 0
            return
        while _MEDIA_RAM_CACHE and _MEDIA_RAM_CACHE_BYTES > max_bytes:
            _, entry = _MEDIA_RAM_CACHE.popitem(last=False)
            _MEDIA_RAM_CACHE_BYTES -= int(entry.get("size") or 0)
            _MEDIA_RAM_CACHE_EVICTIONS += 1


def _media_ram_cache_get_bytes(path, kind=None):
    """Return file bytes from RAM, loading the whole media file if allowed."""
    global _MEDIA_RAM_CACHE_BYTES
    global _MEDIA_RAM_CACHE_HITS, _MEDIA_RAM_CACHE_MISSES
    global _MEDIA_RAM_CACHE_STORES, _MEDIA_RAM_CACHE_EVICTIONS

    cfg = _media_ram_cache_config()
    try:
        path = Path(path).resolve()
        stat = path.stat()
        size = int(stat.st_size or 0)
        mtime_ns = int(getattr(stat, "st_mtime_ns", int(stat.st_mtime * 1e9)))
    except Exception:
        _MEDIA_RAM_CACHE_MISSES += 1
        return None, "missing", cfg

    allowed, reason = _media_ram_cache_allowed(path, kind, size, cfg)
    if not allowed:
        _MEDIA_RAM_CACHE_MISSES += 1
        return None, reason, cfg

    cache_key = (str(path).lower(), size, mtime_ns)
    with _MEDIA_RAM_CACHE_LOCK:
        entry = _MEDIA_RAM_CACHE.get(cache_key)
        if entry is not None:
            _MEDIA_RAM_CACHE.move_to_end(cache_key)
            _MEDIA_RAM_CACHE_HITS += 1
            return entry.get("data"), "hit", cfg

    try:
        data = path.read_bytes()
    except Exception:
        _MEDIA_RAM_CACHE_MISSES += 1
        return None, "read_error", cfg

    with _MEDIA_RAM_CACHE_LOCK:
        for key in list(_MEDIA_RAM_CACHE.keys()):
            if key[0] == cache_key[0] and key != cache_key:
                old = _MEDIA_RAM_CACHE.pop(key)
                _MEDIA_RAM_CACHE_BYTES -= int(old.get("size") or 0)

        while (_MEDIA_RAM_CACHE and
               _MEDIA_RAM_CACHE_BYTES + size > int(cfg.get("max_bytes") or 0)):
            _, old = _MEDIA_RAM_CACHE.popitem(last=False)
            _MEDIA_RAM_CACHE_BYTES -= int(old.get("size") or 0)
            _MEDIA_RAM_CACHE_EVICTIONS += 1

        if size <= int(cfg.get("max_bytes") or 0):
            _MEDIA_RAM_CACHE[cache_key] = {
                "data": data,
                "size": size,
                "path": str(path),
                "kind": kind or _file_kind_for_path(path),
                "mtime_ns": mtime_ns,
                "stored_at": time.time(),
            }
            _MEDIA_RAM_CACHE_BYTES += size
            _MEDIA_RAM_CACHE_STORES += 1
            return data, "stored", cfg

    _MEDIA_RAM_CACHE_MISSES += 1
    return None, "too_large_cache", cfg


def _media_ram_cache_read_or_disk(path, kind=None):
    data, _, _ = _media_ram_cache_get_bytes(path, kind=kind)
    if data is not None:
        return data
    return Path(path).read_bytes()


def _program_ram_cache_allowed(path, size, cfg):
    if not cfg.get("program_cache_enabled"):
        return False, "disabled"
    if int(size or 0) <= 0:
        return False, "empty"
    max_bytes = int(float(cfg.get("program_cache_mb") or 0) * 1024 * 1024)
    if int(size) > max_bytes:
        return False, "too_large"
    try:
        root = Path(__file__).resolve().parent
        real = Path(path).resolve()
        if root not in real.parents and real != root:
            return False, "outside_app"
    except Exception:
        return False, "path_error"
    allowed_exts = {
        ".py", ".txt", ".md", ".html", ".css", ".js", ".json",
        ".png", ".jpg", ".jpeg", ".webp", ".ico", ".svg",
        ".woff", ".woff2", ".ttf",
    }
    if Path(path).suffix.lower() not in allowed_exts:
        return False, "not_program_asset"
    available_gb = float((cfg.get("memory") or {}).get("available_gb") or 0)
    reserve_gb = float(cfg.get("ram_reserve_gb") or 0)
    if cfg.get("ram_auto_enabled") and available_gb and available_gb < reserve_gb:
        return False, "ram_reserved"
    return True, "ok"


def _program_ram_cache_apply_limits(cfg=None):
    global _PROGRAM_RAM_CACHE_BYTES, _PROGRAM_RAM_CACHE_EVICTIONS
    cfg = cfg or _media_ram_cache_config()
    max_bytes = int(float(cfg.get("program_cache_mb") or 0) * 1024 * 1024)
    with _PROGRAM_RAM_CACHE_LOCK:
        if not cfg.get("program_cache_enabled") or max_bytes <= 0:
            _PROGRAM_RAM_CACHE.clear()
            _PROGRAM_RAM_CACHE_BYTES = 0
            return
        while _PROGRAM_RAM_CACHE and _PROGRAM_RAM_CACHE_BYTES > max_bytes:
            _, entry = _PROGRAM_RAM_CACHE.popitem(last=False)
            _PROGRAM_RAM_CACHE_BYTES -= int(entry.get("size") or 0)
            _PROGRAM_RAM_CACHE_EVICTIONS += 1


def _program_ram_cache_get_bytes(path):
    global _PROGRAM_RAM_CACHE_BYTES
    global _PROGRAM_RAM_CACHE_HITS, _PROGRAM_RAM_CACHE_MISSES
    global _PROGRAM_RAM_CACHE_STORES, _PROGRAM_RAM_CACHE_EVICTIONS
    cfg = _media_ram_cache_config()
    try:
        path = Path(path).resolve()
        stat = path.stat()
        size = int(stat.st_size or 0)
        mtime_ns = int(getattr(stat, "st_mtime_ns", int(stat.st_mtime * 1e9)))
    except Exception:
        _PROGRAM_RAM_CACHE_MISSES += 1
        return None, "missing", cfg
    allowed, reason = _program_ram_cache_allowed(path, size, cfg)
    if not allowed:
        _PROGRAM_RAM_CACHE_MISSES += 1
        return None, reason, cfg
    cache_key = (str(path).lower(), size, mtime_ns)
    with _PROGRAM_RAM_CACHE_LOCK:
        entry = _PROGRAM_RAM_CACHE.get(cache_key)
        if entry is not None:
            _PROGRAM_RAM_CACHE.move_to_end(cache_key)
            _PROGRAM_RAM_CACHE_HITS += 1
            return entry.get("data"), "hit", cfg
    try:
        data = path.read_bytes()
    except Exception:
        _PROGRAM_RAM_CACHE_MISSES += 1
        return None, "read_error", cfg
    with _PROGRAM_RAM_CACHE_LOCK:
        for key in list(_PROGRAM_RAM_CACHE.keys()):
            if key[0] == cache_key[0] and key != cache_key:
                old = _PROGRAM_RAM_CACHE.pop(key)
                _PROGRAM_RAM_CACHE_BYTES -= int(old.get("size") or 0)
        max_bytes = int(float(cfg.get("program_cache_mb") or 0) * 1024 * 1024)
        while (_PROGRAM_RAM_CACHE and
               _PROGRAM_RAM_CACHE_BYTES + size > max_bytes):
            _, old = _PROGRAM_RAM_CACHE.popitem(last=False)
            _PROGRAM_RAM_CACHE_BYTES -= int(old.get("size") or 0)
            _PROGRAM_RAM_CACHE_EVICTIONS += 1
        if size <= max_bytes:
            _PROGRAM_RAM_CACHE[cache_key] = {
                "data": data,
                "size": size,
                "path": str(path),
                "kind": "program",
                "mtime_ns": mtime_ns,
                "stored_at": time.time(),
            }
            _PROGRAM_RAM_CACHE_BYTES += size
            _PROGRAM_RAM_CACHE_STORES += 1
            return data, "stored", cfg
    _PROGRAM_RAM_CACHE_MISSES += 1
    return None, "too_large_cache", cfg


def _program_ram_cache_status():
    cfg = _media_ram_cache_config()
    _program_ram_cache_apply_limits(cfg)
    with _PROGRAM_RAM_CACHE_LOCK:
        sample = []
        for entry in list(_PROGRAM_RAM_CACHE.values())[-8:]:
            sample.append({
                "path": entry.get("path"),
                "mb": round(float(entry.get("size") or 0) / (1024 ** 2), 2),
            })
        return {
            "enabled": bool(cfg.get("program_cache_enabled")),
            "limit_mb": cfg.get("program_cache_mb"),
            "used_mb": round(float(_PROGRAM_RAM_CACHE_BYTES or 0) / (1024 ** 2), 2),
            "used_bytes": _PROGRAM_RAM_CACHE_BYTES,
            "items": len(_PROGRAM_RAM_CACHE),
            "hits": _PROGRAM_RAM_CACHE_HITS,
            "misses": _PROGRAM_RAM_CACHE_MISSES,
            "stores": _PROGRAM_RAM_CACHE_STORES,
            "evictions": _PROGRAM_RAM_CACHE_EVICTIONS,
            "recent": sample,
        }


def _program_ram_cache_prewarm_once(force=False):
    global _PROGRAM_RAM_CACHE_PREWARMED
    if _PROGRAM_RAM_CACHE_PREWARMED and not force:
        return _program_ram_cache_status()
    cfg = _media_ram_cache_config(force=force)
    if not cfg.get("program_cache_enabled"):
        _PROGRAM_RAM_CACHE_PREWARMED = True
        return _program_ram_cache_status()
    root = Path(__file__).resolve().parent
    candidates = [
        root / "yazklinik_web.py",
        root / "yazklinik_v68.py",
        root / "yazklinik_common.py",
        root / "yazklinik_desktop_v1000.py",
        root / "yazklinik_terminal_safe.py",
        root / "assets" / "yazklinik_app.ico",
        root / "assets" / "amblem_renkli.png",
    ]
    for folder in (root / "assets", root / "static"):
        try:
            if folder.exists():
                for child in folder.rglob("*"):
                    if child.is_file():
                        candidates.append(child)
        except Exception:
            pass
    seen = set()
    for path in candidates[:256]:
        try:
            key = str(Path(path).resolve()).lower()
        except Exception:
            key = str(path).lower()
        if key in seen:
            continue
        seen.add(key)
        _program_ram_cache_get_bytes(path)
    _PROGRAM_RAM_CACHE_PREWARMED = True
    return _program_ram_cache_status()


def _send_program_ram_asset(path, mimetype=None):
    import mimetypes
    path = Path(path)
    data, cache_status, _ = _program_ram_cache_get_bytes(path)
    mime = mimetype or mimetypes.guess_type(str(path))[0] or "application/octet-stream"
    if data is not None:
        response = send_file(
            BytesIO(data),
            mimetype=mime,
            download_name=path.name,
            conditional=True,
            max_age=86400,
        )
    else:
        response = send_file(
            str(path),
            mimetype=mime,
            download_name=path.name,
            conditional=True,
            max_age=86400,
        )
    try:
        response.headers["Cache-Control"] = "public, max-age=604800, immutable"
        response.headers["X-YazKlinik-Program-RAM-Cache"] = cache_status
    except Exception:
        pass
    return response


def _fmt_gb(value_bytes):
    try:
        return round(float(value_bytes or 0) / (1024 ** 3), 3)
    except Exception:
        return 0.0


def _media_ram_cache_status():
    cfg = _media_ram_cache_config()
    _media_ram_cache_apply_limits(cfg)
    with _MEDIA_RAM_CACHE_LOCK:
        sample = []
        for entry in list(_MEDIA_RAM_CACHE.values())[-8:]:
            sample.append({
                "path": entry.get("path"),
                "kind": entry.get("kind"),
                "mb": round(float(entry.get("size") or 0) / (1024 ** 2), 1),
            })
        return {
            "enabled": bool(cfg.get("enabled")),
            "video_enabled": bool(cfg.get("video_enabled")),
            "prewarm_enabled": bool(cfg.get("prewarm_enabled")),
            "ram_auto_enabled": bool(cfg.get("ram_auto_enabled")),
            "ram_reserve_gb": cfg.get("ram_reserve_gb"),
            "configured_gb": cfg.get("configured_gb"),
            "limit_gb": cfg.get("max_gb"),
            "max_file_mb": cfg.get("max_file_mb"),
            "system_total_gb": (cfg.get("memory") or {}).get("total_gb"),
            "system_available_gb": (cfg.get("memory") or {}).get("available_gb"),
            "used_gb": _fmt_gb(_MEDIA_RAM_CACHE_BYTES),
            "used_bytes": _MEDIA_RAM_CACHE_BYTES,
            "items": len(_MEDIA_RAM_CACHE),
            "hits": _MEDIA_RAM_CACHE_HITS,
            "misses": _MEDIA_RAM_CACHE_MISSES,
            "stores": _MEDIA_RAM_CACHE_STORES,
            "evictions": _MEDIA_RAM_CACHE_EVICTIONS,
            "recent": sample,
        }


def _media_ram_cache_clear():
    global _MEDIA_RAM_CACHE_BYTES
    with _MEDIA_RAM_CACHE_LOCK:
        count = len(_MEDIA_RAM_CACHE)
        bytes_used = _MEDIA_RAM_CACHE_BYTES
        _MEDIA_RAM_CACHE.clear()
        _MEDIA_RAM_CACHE_BYTES = 0
    return {"cleared_items": count, "cleared_gb": _fmt_gb(bytes_used)}


def _program_ram_cache_clear():
    global _PROGRAM_RAM_CACHE_BYTES, _PROGRAM_RAM_CACHE_PREWARMED
    with _PROGRAM_RAM_CACHE_LOCK:
        count = len(_PROGRAM_RAM_CACHE)
        bytes_used = _PROGRAM_RAM_CACHE_BYTES
        _PROGRAM_RAM_CACHE.clear()
        _PROGRAM_RAM_CACHE_BYTES = 0
        _PROGRAM_RAM_CACHE_PREWARMED = False
    return {
        "cleared_items": count,
        "cleared_mb": round(float(bytes_used or 0) / (1024 ** 2), 2),
    }


def _media_ram_cache_schedule_prewarm(cache_id, entries, max_items=80):
    cfg = _media_ram_cache_config()
    if not cfg.get("enabled") or not cfg.get("prewarm_enabled"):
        return
    cache_id = str(cache_id or "")
    if not cache_id:
        return
    with _MEDIA_RAM_CACHE_LOCK:
        if cache_id in _MEDIA_RAM_CACHE_PREWARMING:
            return
        _MEDIA_RAM_CACHE_PREWARMING.add(cache_id)

    def worker():
        try:
            ordered = sorted(
                list(entries or []),
                key=lambda item: (
                    0 if item.get("kind") == "image" else
                    1 if item.get("kind") == "dicom" else
                    2 if item.get("kind") == "pdf" else
                    3 if item.get("kind") == "video" else 4,
                    -float(item.get("mtime") or 0),
                ),
            )
            warmed = 0
            for item in ordered:
                if warmed >= int(max_items or 80):
                    break
                path = item.get("path")
                if not path:
                    continue
                if item.get("kind") == "video":
                    continue
                _media_ram_cache_get_bytes(path, kind=item.get("kind"))
                warmed += 1
        finally:
            with _MEDIA_RAM_CACHE_LOCK:
                _MEDIA_RAM_CACHE_PREWARMING.discard(cache_id)

    threading.Thread(target=worker, daemon=True).start()


def _safe_upload_filename(filename, fallback="dosya"):
    """Return a filesystem-safe basename while keeping Turkish text intact."""
    name = Path(filename or fallback).name.strip() or fallback
    name = re.sub(r'[<>:"/\\|?*\x00-\x1F]', "_", name)
    name = re.sub(r"\s+", " ", name).strip(" .")
    return name[:150] or fallback


def _validate_template_blob_upload(file_name: str,
                                   file_ext: str,
                                   blob: bytes,
                                   label: str) -> None:
    size = len(blob or b"")
    ext = (file_ext or "").lower().lstrip(".")
    if ext not in TEMPLATE_BLOB_ALLOWED_EXTS:
        allowed = ", ".join(sorted(TEMPLATE_BLOB_ALLOWED_EXTS))
        raise ValueError(
            f"{label} icin {ext or 'uzantisiz'} dosya DB'ye gomulemez. "
            f"Izin verilenler: {allowed}.")
    if size > TEMPLATE_BLOB_MAX_BYTES:
        raise ValueError(
            f"{label} dosyasi {_fmt_bytes(size)}. DB sismemesi icin "
            f"sablon dosyalari en fazla {TEMPLATE_BLOB_MAX_MB} MB olabilir. "
            "Buyuk PDF/video/resimleri multimedya arsivine kisayol olarak ekleyin.")


def _unique_child_path(folder: Path, filename: str) -> Path:
    folder.mkdir(parents=True, exist_ok=True)
    safe_name = _safe_upload_filename(filename)
    candidate = folder / safe_name
    if not candidate.exists():
        return candidate
    stem = candidate.stem or "dosya"
    suffix = candidate.suffix
    for idx in range(1, 1000):
        alt = folder / f"{stem}_{idx:03d}{suffix}"
        if not alt.exists():
            return alt
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    return folder / f"{stem}_{stamp}{suffix}"


def _file_kind_for_path(path_or_name):
    ext = Path(str(path_or_name)).suffix.lower()
    if ext in PDF_EXTS_WEB:
        return "pdf"
    if ext in IMAGE_EXTS_WEB:
        return "image"
    if ext in VIDEO_EXTS_WEB:
        return "video"
    if ext in AUDIO_EXTS_WEB:
        return "audio"
    if ext in DICOM_EXTS_WEB:
        return "dicom"
    return "other"


def _web_media_mimetype(path, kind=None):
    import mimetypes
    ext = Path(str(path)).suffix.lower()
    explicit = {
        ".pdf": "application/pdf",
        ".mp4": "video/mp4",
        ".m4v": "video/mp4",
        ".mov": "video/quicktime",
        ".webm": "video/webm",
        ".avi": "video/x-msvideo",
        ".wmv": "video/x-ms-wmv",
        ".mkv": "video/x-matroska",
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg",
        ".png": "image/png",
        ".gif": "image/gif",
        ".webp": "image/webp",
        ".tif": "image/tiff",
        ".tiff": "image/tiff",
        ".dcm": "application/dicom",
        ".dicom": "application/dicom",
        ".ima": "application/dicom",
    }
    if ext in explicit:
        return explicit[ext]
    guessed = mimetypes.guess_type(str(path))[0]
    if guessed:
        return guessed
    if kind == "video":
        return "application/octet-stream"
    if kind == "pdf":
        return "application/pdf"
    if kind == "dicom":
        return "application/dicom"
    return "application/octet-stream"


_WEB_MEDIA_THUMB_CACHE = OrderedDict()
_WEB_MEDIA_THUMB_CACHE_LOCK = threading.RLock()
_WEB_MEDIA_THUMB_CACHE_BYTES = 0
_WEB_MEDIA_THUMB_CACHE_MAX_ITEMS = 512
_WEB_MEDIA_THUMB_CACHE_MAX_BYTES = 96 * 1024 * 1024


def _web_media_thumb_cache_limits():
    try:
        profile = _ram_auto_profile()
        return (
            int(profile.get("thumb_cache_items") or _WEB_MEDIA_THUMB_CACHE_MAX_ITEMS),
            int(float(profile.get("thumb_cache_mb") or 96) * 1024 * 1024),
        )
    except Exception:
        return _WEB_MEDIA_THUMB_CACHE_MAX_ITEMS, _WEB_MEDIA_THUMB_CACHE_MAX_BYTES


def _web_media_thumb_side(raw):
    try:
        side = int(float(str(raw or "").replace(",", ".")))
    except Exception:
        side = 420
    return max(96, min(side, 900))


def _web_media_thumb_response(path, kind=None):
    global _WEB_MEDIA_THUMB_CACHE_BYTES
    path = Path(path)
    kind = kind or _file_kind_for_path(path)
    if kind != "image":
        return None
    side = _web_media_thumb_side(
        request.args.get("side") or request.args.get("w") or "420")
    try:
        stat = path.stat()
        cache_key = (
            str(path.resolve()).lower(),
            int(stat.st_size or 0),
            int(getattr(stat, "st_mtime_ns", int(stat.st_mtime * 1_000_000_000))),
            side,
        )
    except Exception:
        return None

    with _WEB_MEDIA_THUMB_CACHE_LOCK:
        entry = _WEB_MEDIA_THUMB_CACHE.get(cache_key)
        if entry is not None:
            _WEB_MEDIA_THUMB_CACHE.move_to_end(cache_key)
            payload = entry["payload"]
            response = send_file(
                BytesIO(payload),
                mimetype="image/jpeg",
                download_name=f"{path.stem}.thumb.jpg",
                conditional=True,
                max_age=604800,
            )
            response.headers["Cache-Control"] = "public, max-age=604800, immutable"
            response.headers["X-YazKlinik-Thumb"] = "ram-hit"
            return response

    try:
        from PIL import Image, ImageOps
        source = Path(path)
        with Image.open(source) as img:
            img = ImageOps.exif_transpose(img)
            if img.mode not in ("RGB", "L"):
                img = img.convert("RGB")
            elif img.mode == "L":
                img = img.convert("RGB")
            try:
                resample = Image.Resampling.LANCZOS
            except Exception:
                resample = Image.LANCZOS
            img.thumbnail((side, side), resample)
            out = BytesIO()
            img.save(out, format="JPEG", quality=78, optimize=True, progressive=True)
            payload = out.getvalue()
    except Exception:
        return None

    with _WEB_MEDIA_THUMB_CACHE_LOCK:
        for key in list(_WEB_MEDIA_THUMB_CACHE.keys()):
            if key[0] == cache_key[0] and key != cache_key:
                old = _WEB_MEDIA_THUMB_CACHE.pop(key)
                _WEB_MEDIA_THUMB_CACHE_BYTES -= int(old.get("size") or 0)
        _WEB_MEDIA_THUMB_CACHE[cache_key] = {
            "payload": payload,
            "size": len(payload),
            "path": str(path),
        }
        _WEB_MEDIA_THUMB_CACHE_BYTES += len(payload)
        max_items, max_bytes = _web_media_thumb_cache_limits()
        while (
            len(_WEB_MEDIA_THUMB_CACHE) > max_items or
            _WEB_MEDIA_THUMB_CACHE_BYTES > max_bytes
        ):
            _, old = _WEB_MEDIA_THUMB_CACHE.popitem(last=False)
            _WEB_MEDIA_THUMB_CACHE_BYTES -= int(old.get("size") or 0)

    response = send_file(
        BytesIO(payload),
        mimetype="image/jpeg",
        download_name=f"{path.stem}.thumb.jpg",
        conditional=True,
        max_age=604800,
    )
    response.headers["Cache-Control"] = "public, max-age=604800, immutable"
    response.headers["X-YazKlinik-Thumb"] = "generated"
    return response


def _send_web_media_file(path, kind=None, download=False):
    path = Path(path)
    kind = kind or _file_kind_for_path(path)
    if (
        not download and
        kind == "image" and
        str(request.args.get("thumb") or "").lower() in ("1", "true", "yes")
    ):
        thumb_response = _web_media_thumb_response(path, kind=kind)
        if thumb_response is not None:
            return thumb_response
    cache_status = "disk"
    cached_blob = None
    range_request = bool(request.headers.get("Range"))
    # D94: Full image/video media should stream from disk/NAS. Thumbnails still
    # use the small RAM cache above; reading a multi-MB USG/JPG into RAM before
    # every Safari preview can stall both the browser and waitress worker.
    if (
        request.method != "HEAD" and
        kind not in ("video", "image") and
        not range_request
    ):
        cached_blob, cache_status, _ = _media_ram_cache_get_bytes(
            path, kind=kind)
    elif kind == "video":
        cache_status = "stream"
    elif kind == "image":
        cache_status = "stream-image"
    if cached_blob is not None:
        response = send_file(
            BytesIO(cached_blob),
            mimetype=_web_media_mimetype(path, kind),
            as_attachment=bool(download),
            download_name=path.name,
            conditional=True,
            max_age=86400 if kind in ("image", "video", "dicom") else 3600,
        )
    else:
        response = send_file(
            str(path),
            mimetype=_web_media_mimetype(path, kind),
            as_attachment=bool(download),
            download_name=path.name,
            conditional=True,
            max_age=86400 if kind in ("image", "video", "dicom") else 3600,
        )
    try:
        response.headers.setdefault("Accept-Ranges", "bytes")
        response.headers.setdefault("X-Content-Type-Options", "nosniff")
        response.headers["X-YazKlinik-RAM-Cache"] = cache_status
        if kind in ("image", "video", "dicom") and not download:
            response.headers["Cache-Control"] = "public, max-age=604800, immutable"
        if kind == "pdf" and not download:
            safe_name = path.name.replace('"', "")
            response.headers["Content-Disposition"] = (
                f'inline; filename="{safe_name}"')
    except Exception:
        pass
    return response


def _ensure_patient_index_schema(con):
    """Keep older web-only databases compatible with NAS path indexing."""
    con.execute("""
        CREATE TABLE IF NOT EXISTS patients (
            folder_key TEXT PRIMARY KEY,
            full_path TEXT,
            display_name TEXT,
            folder_mtime REAL,
            first_seen_at TEXT,
            last_synced_at TEXT,
            created_at TEXT,
            updated_at TEXT
        )
    """)
    try:
        cols = {str(row[1]) for row in con.execute(
            "PRAGMA table_info(patients)").fetchall()}
    except Exception:
        cols = set()
    for col, ddl in (
        ("full_path", "ALTER TABLE patients ADD COLUMN full_path TEXT"),
        ("display_name", "ALTER TABLE patients ADD COLUMN display_name TEXT"),
        ("folder_mtime", "ALTER TABLE patients ADD COLUMN folder_mtime REAL"),
        ("first_seen_at", "ALTER TABLE patients ADD COLUMN first_seen_at TEXT"),
        ("last_synced_at", "ALTER TABLE patients ADD COLUMN last_synced_at TEXT"),
        ("created_at", "ALTER TABLE patients ADD COLUMN created_at TEXT"),
        ("updated_at", "ALTER TABLE patients ADD COLUMN updated_at TEXT"),
        ("archived_at", "ALTER TABLE patients ADD COLUMN archived_at TEXT"),
        ("archived_by", "ALTER TABLE patients ADD COLUMN archived_by TEXT"),
        ("archive_reason", "ALTER TABLE patients ADD COLUMN archive_reason TEXT"),
    ):
        if col in cols:
            continue
        try:
            con.execute(ddl)
            cols.add(col)
        except Exception:
            pass
    return cols


def _ensure_patient_index_row(patient_key, patient_path=None, display_name=None):
    """Make manual patients immediately visible without waiting for NAS sync."""
    patient_path = (
        Path(patient_path) if patient_path
        else get_patient_storage_root() / patient_key
    )
    manual_name = ""
    display_fold = _fold_search_text(display_name or "")
    if not display_fold or display_fold == _fold_search_text(patient_key):
        try:
            manual_name = str(
                (load_patient_demographics(patient_key) or {}).get("canonical_name")
                or "").strip()
        except Exception:
            manual_name = ""
    preferred_display = manual_name or display_name or patient_key
    display_name = _patient_display_label(patient_key, preferred_display)
    if _is_hidden_demo_patient_record(patient_key, display_name, patient_path):
        return
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    try:
        mtime = patient_path.stat().st_mtime if patient_path.exists() else datetime.now().timestamp()
    except Exception:
        mtime = datetime.now().timestamp()
    try:
        with db_conn() as con:
            _ensure_patient_index_schema(con)
            con.execute(
                "INSERT INTO patients(folder_key, full_path, display_name, "
                "folder_mtime, first_seen_at, last_synced_at) "
                "VALUES(?,?,?,?,?,?) "
                "ON CONFLICT(folder_key) DO UPDATE SET "
                "full_path=excluded.full_path, "
                "display_name=excluded.display_name, "
                "folder_mtime=excluded.folder_mtime, "
                "last_synced_at=excluded.last_synced_at",
                (patient_key, str(patient_path), display_name, mtime, now, now))
            _ensure_patient_protocol(patient_key, con)
            con.commit()
    except Exception:
        # Older/fallback DB schema used by some web-only installs.
        try:
            with db_conn() as con:
                con.execute(
                    "INSERT OR IGNORE INTO patients(folder_key, display_name, "
                    "created_at, updated_at) VALUES(?,?,?,?)",
                    (patient_key, display_name, now, now))
                con.execute(
                    "UPDATE patients SET display_name=?, updated_at=? "
                    "WHERE folder_key=?",
                    (display_name, now, patient_key))
                _ensure_patient_protocol(patient_key, con)
                con.commit()
        except Exception as ex:
            print(f"patient index row: {ex}")


def _path_compare_text(path_value):
    try:
        return str(Path(str(path_value)).expanduser().resolve()).casefold()
    except Exception:
        try:
            return os.path.normcase(os.path.abspath(
                os.path.expanduser(str(path_value)))).casefold()
        except Exception:
            return str(path_value or "").casefold()


def _path_under_any_root(path_value, roots):
    path_text = _path_compare_text(path_value)
    if not path_text:
        return False
    for root in roots:
        root_text = _path_compare_text(root)
        if not root_text:
            continue
        if path_text == root_text:
            return True
        sep = "\\" if "\\" in root_text else "/"
        if path_text.startswith(root_text.rstrip("\\/") + sep):
            return True
    return False


def _nas_merge_prefixes(accepted_prefix="F137230"):
    pieces = [accepted_prefix, os.environ.get(
        "YAZKLINIK_VOLUSON_MERGE_PREFIXES", "F137230,E15545")]
    prefixes = []
    for raw in pieces:
        for part in re.split(r"[,;\s]+", str(raw or "")):
            cleaned = re.sub(r"[^A-Za-z0-9]+", "", part).upper()
            if cleaned and cleaned not in prefixes:
                prefixes.append(cleaned)
    return tuple(prefixes or ("F137230", "E15545"))


def _nas_patient_prefix_for_dir(path, accepted_prefix="F137230"):
    name = Path(path).name.strip().upper()
    for prefix in sorted(_nas_merge_prefixes(accepted_prefix), key=len, reverse=True):
        if prefix and name.startswith(prefix):
            return prefix
    return ""


def _nas_prefix_rank(prefix, accepted_prefix="F137230"):
    primary = re.sub(r"[^A-Za-z0-9]+", "", str(
        accepted_prefix or "F137230")).upper() or "F137230"
    prefix = str(prefix or "").upper()
    if prefix == primary:
        return 0
    return 1 if prefix else 2


def _nas_patient_dir_date(path):
    path = Path(path)
    candidates = [path.name]
    try:
        candidates.extend(part for part in reversed(path.parts[-4:-1]))
    except Exception:
        pass
    for value in candidates:
        found = _date_iso_from_text(value)
        if found:
            try:
                return datetime.strptime(found, "%Y-%m-%d").date()
            except Exception:
                pass
    try:
        return datetime.fromtimestamp(path.stat().st_mtime).date()
    except Exception:
        return None


def _nas_patient_dates_close(path_a, path_b, max_days=280):
    date_a = _nas_patient_dir_date(path_a)
    date_b = _nas_patient_dir_date(path_b)
    if not date_a or not date_b:
        return True
    try:
        return abs((date_a - date_b).days) <= int(max_days or 280)
    except Exception:
        return True


def _nas_patient_content_signature(path, max_files=240, timeout=1.2):
    import time as _time
    root = Path(path)
    cache = getattr(_nas_patient_content_signature, "_cache", {})
    try:
        cache_key = (_path_compare_text(root), int(root.stat().st_mtime))
    except Exception:
        cache_key = (_path_compare_text(root), 0)
    cached = cache.get(cache_key)
    if cached is not None:
        return set(cached)

    skip_dirs = {
        "$recycle.bin", "system volume information", "__pycache__",
        ".git", ".svn", "node_modules", "cache", "thumbs", "tmp", "temp",
    }
    allowed_exts = set()
    try:
        allowed_exts = set(_nas_sync_allowed_file_exts())
    except Exception:
        allowed_exts = IMAGE_EXTS_WEB | VIDEO_EXTS_WEB | DICOM_EXTS_WEB | PDF_EXTS_WEB
    deadline = _time.monotonic() + float(timeout or 1.2)
    stack = [root]
    signature = set()
    scanned = 0
    max_seen = max(500, int(max_files or 240) * 12)
    while stack and len(signature) < int(max_files or 240) and scanned < max_seen:
        if _time.monotonic() > deadline:
            break
        current = stack.pop()
        try:
            with os.scandir(current) as entries:
                for entry in entries:
                    scanned += 1
                    if scanned >= max_seen or _time.monotonic() > deadline:
                        break
                    name = entry.name
                    lower = name.lower()
                    try:
                        if entry.is_dir(follow_symlinks=False):
                            if lower not in skip_dirs:
                                stack.append(Path(entry.path))
                            continue
                        if not entry.is_file(follow_symlinks=False):
                            continue
                        ext = Path(name).suffix.lower()
                        if allowed_exts and ext and ext not in allowed_exts:
                            continue
                        st = entry.stat()
                        signature.add((
                            _fold_search_text(name),
                            int(st.st_size or 0),
                            ext,
                        ))
                    except Exception:
                        continue
        except Exception:
            continue
    cache[cache_key] = frozenset(signature)
    if len(cache) > 512:
        for key in list(cache.keys())[:80]:
            cache.pop(key, None)
    setattr(_nas_patient_content_signature, "_cache", cache)
    return set(signature)


def _nas_patient_content_looks_same(path_a, path_b):
    sig_a = _nas_patient_content_signature(path_a)
    sig_b = _nas_patient_content_signature(path_b)
    if not sig_a or not sig_b:
        return False
    overlap = len(sig_a.intersection(sig_b))
    smaller = max(1, min(len(sig_a), len(sig_b)))
    return overlap >= 3 or (overlap >= 1 and (overlap / smaller) >= 0.55)


def _nas_find_merge_group(groups_by_display, display_key, patient_dir):
    for group in groups_by_display.get(display_key, []):
        try:
            if not _nas_patient_dates_close(patient_dir, group.get("path")):
                continue
            if not _nas_patient_content_looks_same(patient_dir, group.get("path")):
                continue
            return group
        except Exception:
            continue
    return None


def _ensure_patient_alias_row(canonical_key, alias_key, alias_path,
                              display_name="", source_prefix="",
                              merge_reason=""):
    canonical_key = str(canonical_key or "").strip()
    alias_key = str(alias_key or "").strip()
    if not canonical_key or not alias_key or canonical_key == alias_key:
        return False
    alias_path = Path(alias_path).expanduser()
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    try:
        mtime = alias_path.stat().st_mtime if alias_path.exists() else datetime.now().timestamp()
    except Exception:
        mtime = datetime.now().timestamp()
    try:
        with db_conn() as con:
            _ensure_patient_alias_schema(con)
            con.execute(
                "INSERT INTO patient_folder_aliases("
                "alias_key, canonical_key, full_path, display_name, "
                "folder_mtime, source_prefix, merge_reason, first_seen_at, "
                "last_synced_at) VALUES(?,?,?,?,?,?,?,?,?) "
                "ON CONFLICT(alias_key) DO UPDATE SET "
                "canonical_key=excluded.canonical_key, "
                "full_path=excluded.full_path, "
                "display_name=excluded.display_name, "
                "folder_mtime=excluded.folder_mtime, "
                "source_prefix=excluded.source_prefix, "
                "merge_reason=excluded.merge_reason, "
                "last_synced_at=excluded.last_synced_at",
                (alias_key, canonical_key, str(alias_path), display_name,
                 mtime, source_prefix, merge_reason, now, now),
            )
            cols = _ensure_patient_index_schema(con)
            if {"archived_at", "archived_by", "archive_reason"}.issubset(cols):
                assignments = [
                    "full_path=''",
                    "archived_at=COALESCE(NULLIF(archived_at,''), ?)",
                    "archived_by=COALESCE(NULLIF(archived_by,''), ?)",
                    "archive_reason=?",
                ]
                values = [
                    now,
                    "nas-merge",
                    f"NAS alias merged into {canonical_key}: {merge_reason}"[:500],
                ]
                if "updated_at" in cols:
                    assignments.append("updated_at=?")
                    values.append(now)
                values.extend([alias_key, canonical_key])
                con.execute(
                    f"UPDATE patients SET {', '.join(assignments)} "
                    "WHERE folder_key=? AND folder_key<>?",
                    values,
                )
            con.commit()
        _invalidate_patient_web_cache(canonical_key)
        _invalidate_patient_web_cache(alias_key)
        return True
    except Exception as ex:
        print(f"patient alias row: {ex}")
        return False


def _nas_mapping_skip_dir(path):
    name = Path(path).name.strip().lower()
    return (
        not name
        or is_hidden_vendor_demo_patient(path)
        or _is_non_patient_system_record(path)
        or name.startswith(".")
        or name in {
            "$recycle.bin", "system volume information", "__pycache__",
            "_yazklinik_db", "thumbs", "cache", "temp", "tmp",
            "usg", "tahlil", "lab", "labs", "dicom", "pdf", "rapor",
            "raporlar", "reports", "image", "images", "video", "videos",
            "media", "medya", "backup", "backups", "yedek", "yedekler",
        }
    )


def _nas_patient_display_from_dir(path, accepted_prefix="F137230"):
    path = Path(path)
    raw_name = path.name.strip()
    original_raw_name = raw_name
    prefix = _nas_patient_prefix_for_dir(path, accepted_prefix)
    extracted = ""
    if prefix and raw_name.upper().startswith(prefix.upper()):
        try:
            from yazklinik_nas_watcher import extract_patient_name_from_filename
            extracted = extract_patient_name_from_filename(raw_name) or ""
        except Exception:
            extracted = ""
        raw_name = re.sub(
            r"^" + re.escape(prefix) + r"[\s_\-]*",
            "",
            raw_name,
            flags=re.IGNORECASE,
        ).strip() or raw_name
    folder_name, folder_prefix, _date_text = _patient_key_name_parts(
        original_raw_name)
    fallback_name = folder_name if folder_prefix else raw_name
    cleaned = _patient_display_label(
        original_raw_name, extracted or fallback_name or original_raw_name)
    return cleaned or path.name


def _nas_dir_looks_like_patient(path, accepted_prefix="F137230"):
    path = Path(path)
    if _nas_mapping_skip_dir(path):
        return False
    name = path.name.strip()
    prefix = _nas_patient_prefix_for_dir(path, accepted_prefix)
    if prefix and name.upper().startswith(prefix):
        return True
    words = _fold_search_text(_nas_patient_display_from_dir(path, accepted_prefix)).split()
    return len([w for w in words if len(w) >= 2]) >= 2


def _iter_nas_patient_candidate_dirs(root, accepted_prefix="F137230",
                                     direct_only=False, max_dirs=10000):
    root = Path(root).expanduser()
    if not root.exists() or not root.is_dir():
        return
    yielded = 0
    if direct_only:
        try:
            children = sorted(
                list(root.iterdir()),
                key=lambda p: (
                    _nas_prefix_rank(
                        _nas_patient_prefix_for_dir(p, accepted_prefix),
                        accepted_prefix,
                    ),
                    p.name.lower(),
                ),
            )
        except Exception:
            children = []
        for child in children:
            if yielded >= max_dirs:
                return
            try:
                if child.is_dir() and not _nas_mapping_skip_dir(child):
                    yielded += 1
                    yield child
            except Exception:
                continue
        return

    stack = [(root, 0)]
    while stack and yielded < max_dirs:
        current, depth = stack.pop()
        try:
            children = sorted(
                list(current.iterdir()),
                key=lambda p: (
                    _nas_prefix_rank(
                        _nas_patient_prefix_for_dir(p, accepted_prefix),
                        accepted_prefix,
                    ),
                    p.name.lower(),
                ),
            )
        except Exception:
            continue
        for child in children:
            if yielded >= max_dirs:
                return
            try:
                if not child.is_dir():
                    continue
                if _nas_mapping_skip_dir(child):
                    continue
                if _nas_dir_looks_like_patient(child, accepted_prefix):
                    yielded += 1
                    yield child
                    continue
                if depth < 1:
                    stack.append((child, depth + 1))
            except Exception:
                continue


def _reset_patient_folder_mappings_for_roots(roots):
    roots = [Path(r).expanduser() for r in roots if str(r or "").strip()]
    if not roots:
        return 0
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    reset_count = 0
    try:
        with db_conn() as con:
            cols = _ensure_patient_index_schema(con)
            _ensure_patient_alias_schema(con)
            if "full_path" not in cols:
                return 0
            try:
                alias_rows = con.execute(
                    "SELECT alias_key, full_path FROM patient_folder_aliases "
                    "WHERE COALESCE(full_path, '') <> ''").fetchall()
            except Exception:
                alias_rows = []
            for row in alias_rows:
                try:
                    alias_key = row["alias_key"]
                    full_path = row["full_path"]
                except Exception:
                    alias_key = row[0]
                    full_path = row[1]
                if _path_under_any_root(full_path, roots):
                    con.execute(
                        "DELETE FROM patient_folder_aliases WHERE alias_key=?",
                        (alias_key,),
                    )
            try:
                rows = con.execute(
                    "SELECT folder_key, full_path FROM patients "
                    "WHERE COALESCE(full_path, '') <> ''").fetchall()
            except Exception:
                rows = []
            for row in rows:
                try:
                    folder_key = row["folder_key"]
                    full_path = row["full_path"]
                except Exception:
                    folder_key = row[0]
                    full_path = row[1]
                if not _path_under_any_root(full_path, roots):
                    continue
                assignments = ["full_path=?"]
                values = [""]
                if "folder_mtime" in cols:
                    assignments.append("folder_mtime=?")
                    values.append(0.0)
                if "last_synced_at" in cols:
                    assignments.append("last_synced_at=?")
                    values.append(now)
                if "updated_at" in cols:
                    assignments.append("updated_at=?")
                    values.append(now)
                values.append(folder_key)
                con.execute(
                    f"UPDATE patients SET {', '.join(assignments)} "
                    "WHERE folder_key=?",
                    values,
                )
                reset_count += 1
            con.commit()
    except Exception as ex:
        print(f"reset patient folder mappings: {ex}")
    return reset_count


def rebuild_nas_patient_folder_mapping(watch_folder=None, data_root=None,
                                       accepted_prefix="F137230",
                                       clear_existing=True,
                                       max_dirs=10000):
    """Re-index NAS/Data patient folders without deleting patient data."""
    watch_root = Path(watch_folder or get_nas_root()).expanduser()
    data_root_path = Path(data_root or default_patient_data_root(
        watch_root)).expanduser()
    accepted_prefix = (accepted_prefix or "F137230").strip() or "F137230"
    result = {
        "ok": False,
        "watch_folder": str(watch_root),
        "data_root": str(data_root_path),
        "accepted_prefix": accepted_prefix,
        "merge_prefixes": list(_nas_merge_prefixes(accepted_prefix)),
        "reset_mappings": 0,
        "mapped_patients": 0,
        "merged_aliases": 0,
        "scanned_dirs": 0,
        "skipped": 0,
        "errors": [],
    }
    if not watch_root.exists() or not watch_root.is_dir():
        result["error"] = f"NAS klasoru yok: {watch_root}"
        return result

    try:
        data_root_path.mkdir(parents=True, exist_ok=True)
    except Exception as ex:
        result["errors"].append(f"Data klasoru olusturulamadi: {ex}")

    roots_for_reset = [watch_root]
    try:
        if data_root_path.exists():
            roots_for_reset.append(data_root_path)
    except Exception:
        pass
    if clear_existing:
        result["reset_mappings"] = _reset_patient_folder_mappings_for_roots(
            roots_for_reset)

    mapped_display_names = set()
    merge_groups_by_display = {}
    seen_paths = set()

    def _map_dir(patient_dir, source):
        try:
            key = patient_dir.name.strip()
            if not key:
                result["skipped"] += 1
                return
            path_key = _path_compare_text(patient_dir)
            if path_key in seen_paths:
                result["skipped"] += 1
                return
            display_name = _nas_patient_display_from_dir(
                patient_dir, accepted_prefix)
            display_key = _fold_search_text(display_name)
            prefix = _nas_patient_prefix_for_dir(patient_dir, accepted_prefix)
            if prefix and display_key:
                group = _nas_find_merge_group(
                    merge_groups_by_display, display_key, patient_dir)
                if group:
                    if _ensure_patient_alias_row(
                            group["key"], key, patient_dir,
                            display_name=display_name,
                            source_prefix=prefix,
                            merge_reason=(
                                "same-name/same-content/within-9-months")):
                        result["merged_aliases"] += 1
                    group.setdefault("aliases", []).append({
                        "key": key,
                        "path": patient_dir,
                        "prefix": prefix,
                    })
                    mapped_display_names.add(display_key)
                    seen_paths.add(path_key)
                    _invalidate_patient_web_cache(group["key"])
                    return
            if source == "watch" and display_key in mapped_display_names:
                result["skipped"] += 1
                seen_paths.add(path_key)
                return
            _ensure_patient_index_row(key, patient_dir, display_name)
            mapped_display_names.add(display_key)
            seen_paths.add(path_key)
            result["mapped_patients"] += 1
            if prefix and display_key:
                merge_groups_by_display.setdefault(display_key, []).append({
                    "key": key,
                    "path": patient_dir,
                    "prefix": prefix,
                    "display_name": display_name,
                    "aliases": [],
                })
            _invalidate_patient_web_cache(key)
        except Exception as ex:
            if len(result["errors"]) < 12:
                result["errors"].append(f"{patient_dir}: {ex}")

    # Data is the preferred, durable patient file root. Index it first.
    if data_root_path.exists() and data_root_path.is_dir():
        for pdir in _iter_nas_patient_candidate_dirs(
                data_root_path, accepted_prefix,
                direct_only=True, max_dirs=max_dirs):
            result["scanned_dirs"] += 1
            _map_dir(pdir, "data")

    remaining = max(0, int(max_dirs) - result["scanned_dirs"])
    for pdir in _iter_nas_patient_candidate_dirs(
            watch_root, accepted_prefix, direct_only=False,
            max_dirs=remaining or max_dirs):
        result["scanned_dirs"] += 1
        _map_dir(pdir, "watch")

    try:
        setattr(_scan_patient_nas_media, "_cache", {})
    except Exception:
        pass
    _invalidate_patient_web_cache()
    result["ok"] = True
    return result


_NAS_DRIVE_SYNC_LOCK = threading.Lock()


def _nas_sync_table_cols(con, table_name):
    try:
        return {str(row[1]) for row in con.execute(
            f"PRAGMA table_info({table_name})").fetchall()}
    except Exception:
        return set()


def _nas_sync_add_missing_cols(con, table_name, col_defs):
    cols = _nas_sync_table_cols(con, table_name)
    for col_name, ddl in col_defs:
        if col_name in cols:
            continue
        try:
            con.execute(ddl)
            cols.add(col_name)
        except Exception:
            pass
    return cols


