def _nas_sync_allowed_file_exts():
    return (_media_shortcut_allowed_exts() | {
        ".doc", ".docx", ".xls", ".xlsx", ".csv", ".txt", ".rtf",
        ".zip", ".7z", ".rar",
    })


def _nas_sync_skip_scan_dir(path):
    name = Path(path).name.strip().lower()
    return (
        not name
        or _is_non_patient_system_record(path)
        or name.startswith(".")
        or name in {
            "$recycle.bin", "system volume information", "__pycache__",
            ".git", ".svn", "node_modules", "_yazklinik_db", "cache",
            "temp", "tmp", "backup", "backups", "yedek", "yedekler",
        }
    )


def _nas_sync_safe_visit_key(visit_dir, patient_dir):
    try:
        rel = str(Path(visit_dir).relative_to(Path(patient_dir)))
    except Exception:
        rel = Path(visit_dir).name
    rel = rel.replace("\\", "__").replace("/", "__").strip(" .")
    return rel[:180] if rel and rel != "." else "_KOK_DOSYALAR"


def _nas_sync_parse_visit_date(path):
    text = Path(path).name
    patterns = (
        r"(?P<y>20\d{2}|19\d{2})[-_. ]?(?P<m>0?[1-9]|1[0-2])[-_. ]?(?P<d>0?[1-9]|[12]\d|3[01])",
        r"(?P<d>0?[1-9]|[12]\d|3[01])[-_. ](?P<m>0?[1-9]|1[0-2])[-_. ](?P<y>20\d{2}|19\d{2})",
    )
    for pattern in patterns:
        match = re.search(pattern, text)
        if not match:
            continue
        try:
            dt = datetime(
                int(match.group("y")),
                int(match.group("m")),
                int(match.group("d")),
            )
            return dt.strftime("%Y-%m-%d")
        except Exception:
            continue
    try:
        return datetime.fromtimestamp(Path(path).stat().st_mtime).strftime(
            "%Y-%m-%d")
    except Exception:
        return datetime.now().strftime("%Y-%m-%d")


def _nas_sync_has_direct_files(folder):
    allowed = _nas_sync_allowed_file_exts()
    try:
        for child in Path(folder).iterdir():
            try:
                if child.is_file() and child.suffix.lower() in allowed:
                    return True
            except Exception:
                continue
    except Exception:
        pass
    return False


def _nas_sync_visit_candidates(patient_dir, max_visits_per_patient=500):
    patient_dir = Path(patient_dir)
    yielded = 0
    if _nas_sync_has_direct_files(patient_dir):
        yielded += 1
        yield "_KOK_DOSYALAR", patient_dir, False
    try:
        children = sorted(patient_dir.iterdir(), key=lambda p: p.name.lower())
    except Exception:
        children = []
    for child in children:
        if yielded >= max(1, int(max_visits_per_patient or 500)):
            return
        try:
            if not child.is_dir() or _nas_sync_skip_scan_dir(child):
                continue
        except Exception:
            continue
        yielded += 1
        yield _nas_sync_safe_visit_key(child, patient_dir), child, True


def _nas_sync_iter_files(folder, recursive=True, max_files=2000):
    allowed = _nas_sync_allowed_file_exts()
    limit = max(1, int(max_files or 2000))
    yielded = 0
    stack = [Path(folder)]
    while stack and yielded < limit:
        current = stack.pop()
        try:
            children = list(current.iterdir())
        except Exception:
            continue
        for child in sorted(children, key=lambda p: p.name.lower()):
            if yielded >= limit:
                return
            try:
                if child.is_dir():
                    if recursive and not _nas_sync_skip_scan_dir(child):
                        stack.append(child)
                    continue
                if not child.is_file():
                    continue
                name = child.name.strip()
                if not name or name.startswith(".") or name.startswith("~$"):
                    continue
                if child.suffix.lower() not in allowed:
                    continue
                yielded += 1
                yield child
            except Exception:
                continue


def _nas_sync_db_file_name(path, visit_dir, used_names):
    path = Path(path)
    candidate = path.name.strip() or "dosya"
    if candidate in used_names:
        try:
            rel = str(path.relative_to(Path(visit_dir)))
        except Exception:
            rel = path.name
        candidate = rel.replace("\\", "__").replace("/", "__").strip(" .")
    if not candidate:
        candidate = path.name or "dosya"
    base = candidate[:180]
    candidate = base
    idx = 2
    while candidate in used_names:
        stem = Path(base).stem or "dosya"
        suffix = Path(base).suffix
        candidate = f"{stem}_{idx}{suffix}"[:180]
        idx += 1
    used_names.add(candidate)
    return candidate


def _nas_sync_file_records(visit_dir, recursive=True, max_files_per_visit=2000):
    records = []
    used_names = set()
    counts = {
        "file_count": 0,
        "image_count": 0,
        "video_count": 0,
        "pdf_count": 0,
        "latest_pdf_path": None,
    }
    latest_pdf = (-1.0, None)
    for path in _nas_sync_iter_files(
            visit_dir, recursive=recursive, max_files=max_files_per_visit):
        kind = _file_kind_for_path(path)
        try:
            stat = path.stat()
            size = stat.st_size
            mtime = stat.st_mtime
        except Exception:
            size = None
            mtime = None
        if kind == "image":
            counts["image_count"] += 1
        elif kind == "video":
            counts["video_count"] += 1
        elif kind == "pdf":
            counts["pdf_count"] += 1
            if float(mtime or 0) >= latest_pdf[0]:
                latest_pdf = (float(mtime or 0), str(path))
        counts["file_count"] += 1
        records.append({
            "file_name": _nas_sync_db_file_name(path, visit_dir, used_names),
            "full_path": str(path),
            "file_kind": kind,
            "size_bytes": size,
            "mtime": mtime,
        })
    counts["latest_pdf_path"] = latest_pdf[1]
    return records, counts


def _nas_sync_coalesce_file_records(records):
    """Merge file rows coming from multiple aliased NAS roots."""
    merged = []
    used_names = set()
    seen_fingerprints = set()
    for rec in records or []:
        name = str(rec.get("file_name") or "").strip() or "dosya"
        fingerprint = (
            name.casefold(),
            str(rec.get("file_kind") or ""),
            int(rec.get("size_bytes") or 0),
        )
        if fingerprint in seen_fingerprints:
            continue
        seen_fingerprints.add(fingerprint)
        candidate = name[:180]
        if candidate in used_names:
            stem = Path(candidate).stem or "dosya"
            suffix = Path(candidate).suffix
            idx = 2
            while candidate in used_names:
                candidate = f"{stem}_{idx}{suffix}"[:180]
                idx += 1
        used_names.add(candidate)
        row = dict(rec)
        row["file_name"] = candidate
        merged.append(row)
    return merged


def _nas_sync_counts_from_file_records(records):
    counts = {
        "file_count": 0,
        "image_count": 0,
        "video_count": 0,
        "pdf_count": 0,
        "latest_pdf_path": None,
    }
    latest_pdf = (-1.0, None)
    for rec in records or []:
        kind = str(rec.get("file_kind") or "")
        if kind == "image":
            counts["image_count"] += 1
        elif kind == "video":
            counts["video_count"] += 1
        elif kind == "pdf":
            counts["pdf_count"] += 1
            if float(rec.get("mtime") or 0) >= latest_pdf[0]:
                latest_pdf = (float(rec.get("mtime") or 0),
                              rec.get("full_path"))
        counts["file_count"] += 1
    counts["latest_pdf_path"] = latest_pdf[1]
    return counts


def _nas_sync_visit_rowid(con, patient_key, visit_key):
    row = con.execute(
        "SELECT rowid FROM visits WHERE patient_folder_key=? "
        "AND visit_key=? LIMIT 1",
        (patient_key, visit_key),
    ).fetchone()
    return row[0] if row else None


def _nas_sync_upsert_visit(con, patient_key, visit_key, visit_dir,
                           counts, now, counters):
    try:
        folder_mtime = Path(visit_dir).stat().st_mtime
    except Exception:
        folder_mtime = datetime.now().timestamp()
    values = {
        "patient_folder_key": patient_key,
        "visit_key": visit_key,
        "visit_date": _nas_sync_parse_visit_date(visit_dir),
        "visit_type": _normalize_visit_type(visit_key),
        "full_path": str(visit_dir),
        "folder_mtime": folder_mtime,
        "file_count": int(counts.get("file_count") or 0),
        "image_count": int(counts.get("image_count") or 0),
        "video_count": int(counts.get("video_count") or 0),
        "pdf_count": int(counts.get("pdf_count") or 0),
        "latest_pdf_path": counts.get("latest_pdf_path"),
        "last_synced_at": now,
    }
    rowid = _nas_sync_visit_rowid(con, patient_key, visit_key)
    if rowid:
        assignments = ", ".join(f"{col}=?" for col in values.keys())
        con.execute(
            f"UPDATE visits SET {assignments} WHERE rowid=?",
            tuple(values.values()) + (rowid,),
        )
        counters["visits_updated"] += 1
    else:
        values["first_seen_at"] = now
        values["created_at"] = now
        cols = list(values.keys())
        placeholders = ",".join("?" for _ in cols)
        con.execute(
            f"INSERT INTO visits({','.join(cols)}) VALUES({placeholders})",
            tuple(values[c] for c in cols),
        )
        counters["visits_added"] += 1


def _nas_sync_upsert_files(con, patient_key, visit_key, records, now, counters):
    current_names = {r["file_name"] for r in records}
    existing_rows = con.execute(
        "SELECT rowid, file_name, full_path, file_kind, size_bytes, mtime "
        "FROM files WHERE patient_folder_key=? AND visit_key=?",
        (patient_key, visit_key),
    ).fetchall()
    existing = {}
    for row in existing_rows:
        try:
            existing[str(row[1])] = row
        except Exception:
            continue

    for rec in records:
        row = existing.get(rec["file_name"])
        if row:
            changed = (
                str(row[2] or "") != str(rec.get("full_path") or "")
                or str(row[3] or "") != str(rec.get("file_kind") or "")
                or row[4] != rec.get("size_bytes")
                or row[5] != rec.get("mtime")
            )
            con.execute(
                "UPDATE files SET full_path=?, file_kind=?, size_bytes=?, "
                "mtime=?, last_synced_at=? WHERE rowid=?",
                (rec.get("full_path"), rec.get("file_kind"),
                 rec.get("size_bytes"), rec.get("mtime"), now, row[0]),
            )
            if changed:
                counters["files_updated"] += 1
        else:
            con.execute(
                "INSERT INTO files(patient_folder_key, visit_key, file_name, "
                "full_path, file_kind, size_bytes, mtime, first_seen_at, "
                "last_synced_at) VALUES(?,?,?,?,?,?,?,?,?)",
                (patient_key, visit_key, rec.get("file_name"),
                 rec.get("full_path"), rec.get("file_kind"),
                 rec.get("size_bytes"), rec.get("mtime"), now, now),
            )
            counters["files_added"] += 1

    stale = [row[0] for row in existing_rows if str(row[1]) not in current_names]
    for rowid in stale:
        con.execute("DELETE FROM files WHERE rowid=?", (rowid,))
        counters["files_removed"] += 1
    counters["files_seen"] += len(records)


def _nas_sync_log_result(result):
    try:
        import json as _json
        with db_conn() as con:
            _ensure_nas_drive_sync_schema(con)
            con.execute(
                "INSERT INTO sync_log(sync_type, source_path, data_root, "
                "status, started_at, finished_at, duration_sec, "
                "mapped_patients, visits_synced, files_synced, errors_json) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                ("web_nas_drive", result.get("watch_folder"),
                 result.get("data_root"), "ok" if result.get("ok") else "error",
                 result.get("started_at"), result.get("finished_at"),
                 result.get("duration_sec"), result.get("mapped_patients", 0),
                 (result.get("visits_added", 0) +
                  result.get("visits_updated", 0)),
                 (result.get("files_added", 0) +
                  result.get("files_updated", 0)),
                 _json.dumps(result.get("errors") or [], ensure_ascii=False)),
            )
            con.commit()
    except Exception as ex:
        print(f"nas sync log: {ex}")


def run_nas_drive_sync(watch_folder=None, data_root=None,
                       accepted_prefix=None, clear_existing=True,
                       max_dirs=10000, max_patients=50000,
                       max_visits_per_patient=500,
                       max_files_per_visit=2000):
    if not _NAS_DRIVE_SYNC_LOCK.acquire(blocking=False):
        return {
            "ok": False,
            "busy": True,
            "error": "NAS senkronizasyonu zaten calisiyor",
        }
    import time as _time
    started = datetime.now()
    t0 = _time.time()
    accepted_prefix = (
        accepted_prefix or os.environ.get("YAZKLINIK_VOLUSON_AUTO_PREFIX")
        or "F137230").strip() or "F137230"
    watch_root = Path(watch_folder or get_nas_root()).expanduser()
    data_root_path = Path(data_root or get_data_root_dir() or
                          default_patient_data_root(watch_root)).expanduser()
    result = {
        "ok": False,
        "started_at": started.isoformat(sep=" ", timespec="seconds"),
        "watch_folder": str(watch_root),
        "data_root": str(data_root_path),
        "accepted_prefix": accepted_prefix,
        "mapped_patients": 0,
        "merged_aliases": 0,
        "patients_scanned": 0,
        "patients_missing_path": 0,
        "visits_added": 0,
        "visits_updated": 0,
        "files_seen": 0,
        "files_added": 0,
        "files_updated": 0,
        "files_removed": 0,
        "errors": [],
    }
    try:
        watch_exists = watch_root.exists() and watch_root.is_dir()
        data_exists = data_root_path.exists() and data_root_path.is_dir()
        if not watch_exists and not data_exists:
            result["error"] = (
                f"NAS/Data klasoru yok: {watch_root} / {data_root_path}")
            return result

        mapping_watch = watch_root if watch_exists else data_root_path
        mapping_data = data_root_path if data_exists else mapping_watch
        mapping = rebuild_nas_patient_folder_mapping(
            watch_folder=str(mapping_watch),
            data_root=str(mapping_data),
            accepted_prefix=accepted_prefix,
            clear_existing=clear_existing,
            max_dirs=max_dirs,
        )
        result["mapped_patients"] = int(mapping.get("mapped_patients") or 0)
        result["merged_aliases"] = int(mapping.get("merged_aliases") or 0)
        result["reset_mappings"] = int(mapping.get("reset_mappings") or 0)
        result["scanned_dirs"] = int(mapping.get("scanned_dirs") or 0)
        if mapping.get("errors"):
            result["errors"].extend(str(x) for x in mapping.get("errors")[:12])
        if not mapping.get("ok"):
            result["error"] = mapping.get("error") or "NAS hasta esleme hatasi"
            return result

        now = datetime.now().isoformat(sep=" ", timespec="seconds")
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            _ensure_nas_drive_sync_schema(con)
            rows = con.execute(
                "SELECT folder_key, display_name, full_path FROM patients "
                "WHERE COALESCE(full_path, '') <> '' "
                "ORDER BY COALESCE(display_name, folder_key), folder_key "
                "LIMIT ?",
                (max(1, min(int(max_patients or 50000), 50000)),),
            ).fetchall()
            counters = {
                "visits_added": 0,
                "visits_updated": 0,
                "files_seen": 0,
                "files_added": 0,
                "files_updated": 0,
                "files_removed": 0,
            }
            for row in rows:
                patient_key = str(row.get("folder_key") or "").strip()
                patient_path_text = str(row.get("full_path") or "").strip()
                if _is_hidden_demo_patient_record(
                        patient_key, row.get("display_name"), patient_path_text):
                    continue
                if not patient_key:
                    continue
                patient_roots = _patient_roots_for_nas(patient_key)
                if not patient_roots:
                    result["patients_missing_path"] += 1
                    continue
                result["patients_scanned"] += 1
                visit_batches = {}
                for patient_dir in patient_roots:
                    try:
                        patient_dir = Path(patient_dir).expanduser()
                        if not patient_dir.exists() or not patient_dir.is_dir():
                            continue
                    except Exception:
                        continue
                    for visit_key, visit_dir, recursive in _nas_sync_visit_candidates(
                            patient_dir, max_visits_per_patient):
                        try:
                            records, _counts = _nas_sync_file_records(
                                visit_dir, recursive=recursive,
                                max_files_per_visit=max_files_per_visit)
                            batch = visit_batches.setdefault(visit_key, {
                                "dirs": [],
                                "records": [],
                            })
                            batch["dirs"].append(visit_dir)
                            batch["records"].extend(records)
                        except Exception as ex:
                            if len(result["errors"]) < 20:
                                result["errors"].append(
                                    f"{patient_key}/{visit_key}: {ex}")
                if not visit_batches:
                    continue
                for visit_key, batch in visit_batches.items():
                    try:
                        existing_visit = _nas_sync_visit_rowid(
                            con, patient_key, visit_key)
                        records = _nas_sync_coalesce_file_records(
                            batch.get("records"))
                        counts = _nas_sync_counts_from_file_records(records)
                        if not records and not existing_visit:
                            continue
                        visit_dir = (batch.get("dirs") or [
                            _patient_root_for_nas(patient_key) / str(visit_key)
                        ])[0]
                        _nas_sync_upsert_files(
                            con, patient_key, visit_key, records, now,
                            counters)
                        _nas_sync_upsert_visit(
                            con, patient_key, visit_key, visit_dir, counts,
                            now, counters)
                    except Exception as ex:
                        if len(result["errors"]) < 20:
                            result["errors"].append(
                                f"{patient_key}/{visit_key}: {ex}")
            con.commit()
        result.update(counters)
        result["ok"] = True
        try:
            setattr(_scan_patient_nas_media, "_cache", {})
        except Exception:
            pass
        _invalidate_patient_web_cache()
        return result
    except Exception as ex:
        result["error"] = str(ex)
        return result
    finally:
        result["finished_at"] = datetime.now().isoformat(
            sep=" ", timespec="seconds")
        result["duration_sec"] = round(_time.time() - t0, 2)
        _nas_sync_log_result(result)
        _NAS_DRIVE_SYNC_LOCK.release()


def _save_visit_note(patient_key, visit_key, note):
    note = (note or "").strip()
    if not note:
        return
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    try:
        with db_conn() as con:
            con.execute(
                "INSERT INTO visit_notes(patient_key, visit_key, note, updated_at) "
                "VALUES(?,?,?,?) "
                "ON CONFLICT(patient_key, visit_key) DO UPDATE SET "
                "note=excluded.note, updated_at=excluded.updated_at",
                (patient_key, visit_key, note, now))
            con.commit()
    except Exception as ex:
        print(f"visit note save: {ex}")


def _record_visit_files(patient_key, visit_key, visit_dir: Path, saved_files):
    """Persist uploaded manual visit files so the web media viewer sees them now."""
    counts = {"file_count": len(saved_files), "image_count": 0,
              "video_count": 0, "pdf_count": 0, "latest_pdf_path": None,
              "pdf_archived_count": 0, "report_type": ""}
    detected_types = []
    for item in saved_files:
        kind = item.get("kind")
        if kind == "image":
            counts["image_count"] += 1
        elif kind == "video":
            counts["video_count"] += 1
        elif kind == "pdf":
            counts["pdf_count"] += 1
            if not counts["latest_pdf_path"]:
                counts["latest_pdf_path"] = str(item.get("path"))
            report_type = str(item.get("report_type") or "").strip().lower()
            if report_type not in ("obstetric", "gynecologic"):
                report_type = _detect_report_type_from_pdf_file(item.get("path"))
                item["report_type"] = report_type
            if report_type:
                detected_types.append(report_type)
    if not saved_files:
        return counts
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    try:
        with db_conn() as con:
            for item in saved_files:
                p = Path(item["path"])
                try:
                    stat = p.stat()
                    size = stat.st_size
                    mtime = stat.st_mtime
                except Exception:
                    size = None
                    mtime = None
                con.execute(
                    "INSERT INTO files(patient_folder_key, visit_key, file_name, "
                    "full_path, file_kind, size_bytes, mtime, first_seen_at, "
                    "last_synced_at) VALUES(?,?,?,?,?,?,?,?,?) "
                    "ON CONFLICT(patient_folder_key, visit_key, file_name) "
                    "DO UPDATE SET full_path=excluded.full_path, "
                    "file_kind=excluded.file_kind, size_bytes=excluded.size_bytes, "
                    "mtime=excluded.mtime, last_synced_at=excluded.last_synced_at",
                    (patient_key, visit_key, p.name, str(p), item["kind"],
                     size, mtime, now, now))
                if item.get("kind") == "pdf":
                    archived = _archive_patient_pdf_file(
                        patient_key=patient_key,
                        visit_key=visit_key,
                        file_path=p,
                        source="manual-visit-upload",
                        report_type=item.get("report_type") or "",
                        con=con)
                    if archived:
                        counts["pdf_archived_count"] += 1
                        if not item.get("report_type"):
                            item["report_type"] = archived.get("report_type") or ""
                            if item.get("report_type"):
                                detected_types.append(item.get("report_type"))
            con.commit()
    except Exception as ex:
        print(f"visit file rows: {ex}")
    decided_type = ""
    if "obstetric" in detected_types:
        decided_type = "obstetric"
    elif "gynecologic" in detected_types:
        decided_type = "gynecologic"
    if decided_type:
        counts["report_type"] = decided_type
        _set_patient_type_from_report(patient_key, decided_type, source="manual-visit-upload")
    return counts


def _save_uploaded_visit_files(patient_key, visit_key, visit_dir: Path, uploads):
    saved = []
    for uf in uploads:
        if not uf or not uf.filename:
            continue
        dest = _unique_child_path(visit_dir, uf.filename)
        try:
            uf.save(str(dest))
            saved.append({
                "path": dest,
                "kind": _file_kind_for_path(dest),
            })
        except Exception as ex:
            flash(f"Dosya yuklenemedi ({uf.filename}): {ex}", "warning")
    return _record_visit_files(patient_key, visit_key, visit_dir, saved)


def _upsert_visit_record(patient_key, visit_key, visit_dir: Path,
                         visit_date=None, counts=None, visit_type=None,
                         examination=None, control_note=None):
    counts = counts or {}
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    try:
        folder_mtime = visit_dir.stat().st_mtime if visit_dir.exists() else datetime.now().timestamp()
    except Exception:
        folder_mtime = datetime.now().timestamp()
    visit_type = _normalize_visit_type(visit_type, fallback=visit_key)
    examination = str(examination or "").strip()
    control_note = str(control_note or "").strip()
    try:
        with db_conn() as con:
            _ensure_visit_clinical_schema(con)
            con.execute(
                "INSERT INTO visits(patient_folder_key, visit_key, full_path, "
                "visit_date, folder_mtime, file_count, image_count, video_count, "
                "pdf_count, latest_pdf_path, first_seen_at, last_synced_at, "
                "visit_type, examination, control_note) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) "
                "ON CONFLICT(patient_folder_key, visit_key) DO UPDATE SET "
                "full_path=excluded.full_path, visit_date=excluded.visit_date, "
                "folder_mtime=excluded.folder_mtime, file_count=excluded.file_count, "
                "image_count=excluded.image_count, video_count=excluded.video_count, "
                "pdf_count=excluded.pdf_count, latest_pdf_path=excluded.latest_pdf_path, "
                "last_synced_at=excluded.last_synced_at, "
                "visit_type=COALESCE(NULLIF(excluded.visit_type,''), visits.visit_type), "
                "examination=COALESCE(NULLIF(excluded.examination,''), visits.examination), "
                "control_note=COALESCE(NULLIF(excluded.control_note,''), visits.control_note)",
                (patient_key, visit_key, str(visit_dir),
                 visit_date or datetime.now().strftime("%Y-%m-%d"),
                 folder_mtime,
                 counts.get("file_count", 0) or 0,
                 counts.get("image_count", 0) or 0,
                 counts.get("video_count", 0) or 0,
                 counts.get("pdf_count", 0) or 0,
                 counts.get("latest_pdf_path"),
                 now, now, visit_type, examination, control_note))
            con.commit()
    except Exception as ex:
        print(f"visit DB: {ex}")


def _ensure_initial_manual_visit(patient_key, patient_path: Path, note=None):
    """Create the first manual visit so manual patients track like NAS patients."""
    try:
        with db_conn() as con:
            row = con.execute(
                "SELECT 1 FROM visits WHERE patient_folder_key=? LIMIT 1",
                (patient_key,)).fetchone()
            if row:
                return None
    except Exception:
        pass
    base = _new_visit_key_voluson(patient_path)
    visit_dir = patient_path / base
    visit_dir.mkdir(parents=True, exist_ok=True)
    visit_key = visit_dir.name
    _upsert_visit_record(
        patient_key, visit_key, visit_dir,
        visit_date=datetime.now().strftime("%Y-%m-%d"))
    initial_note = "Manuel hasta kaydi olusturuldu."
    if note:
        initial_note += "\n" + note.strip()
    _save_visit_note(patient_key, visit_key, initial_note)
    return visit_key


