def _lab_upload_dir(patient_key, test_date=None):
    stamp = (test_date or datetime.now().strftime("%Y-%m-%d"))[:10]
    stamp = re.sub(r"[^0-9-]", "", stamp) or datetime.now().strftime("%Y-%m-%d")
    return _patient_root_for_nas(patient_key) / "_tahliller" / stamp


def _extract_date_from_lab_text(text, fallback=None):
    text = text or ""
    for pat in (
        r"(\d{4})[./-](\d{1,2})[./-](\d{1,2})",
        r"(\d{1,2})[./-](\d{1,2})[./-](\d{4})",
    ):
        m = re.search(pat, text)
        if not m:
            continue
        a, b, c = m.groups()
        try:
            if len(a) == 4:
                return f"{int(a):04d}-{int(b):02d}-{int(c):02d}"
            return f"{int(c):04d}-{int(b):02d}-{int(a):02d}"
        except Exception:
            pass
    return fallback or datetime.now().strftime("%Y-%m-%d")


def _extract_lab_values_from_text_web(text):
    try:
        from yazklinik_v68 import _extract_lab_values_from_text as _extract
        return _extract(text or "") or {}
    except Exception:
        pass
    out = {}
    for line in (text or "").splitlines():
        line = line.strip()
        if len(line) < 4:
            continue
        m = re.match(
            r"^([A-Za-z0-9 /()._%+-]{2,40})\s+(-?\d+(?:[.,]\d+)?)\s*([A-Za-z/%0-9.]+)?",
            line)
        if not m:
            continue
        name, value, unit = m.groups()
        out[name.strip()] = {
            "value": value.replace(",", "."),
            "unit": unit or "",
            "ref": "",
        }
    return out


_YK_LAB_NOISE_MARKERS = (
    "Ã", "Â", "�", "ƒ", "â", "€", "™", "œ", "ž", "Æ", "¢", "š",
)


def _yk_lab_fold(value):
    text = _repair_mojibake_text(str(value or ""))
    text = text.translate(str.maketrans({
        "Ý": "I", "ý": "i", "Þ": "S", "þ": "s", "Ð": "G", "ð": "g",
        "İ": "I", "ı": "i", "Ş": "S", "ş": "s", "Ğ": "G", "ğ": "g",
        "Ü": "U", "ü": "u", "Ö": "O", "ö": "o", "Ç": "C", "ç": "c",
    }))
    text = unicodedata.normalize("NFKD", text)
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    text = re.sub(r"\s+", " ", text).strip().casefold()
    return text


def _yk_lab_has_noise(value):
    text = str(value or "")
    if any(marker in text for marker in _YK_LAB_NOISE_MARKERS):
        return True
    if len(text) > 120:
        return True
    if re.search(r"[^\w\s%#/+().,\-:;*<>]", text, re.UNICODE):
        noisy = sum(1 for ch in text if ord(ch) > 255)
        if noisy >= 4:
            return True
    return False


def _yk_lab_is_date_token(value):
    return bool(re.fullmatch(
        r"\d{1,2}[./-]\d{1,2}[./-]\d{4}(?:\s+\d{1,2}:\d{2})?|"
        r"\d{4}[./-]\d{1,2}[./-]\d{1,2}",
        str(value or "").strip()))


def _yk_lab_parse_number(value):
    raw = str(value or "").strip()
    if not raw or _yk_lab_is_date_token(raw):
        return None
    raw = raw.replace("\u2212", "-")
    m = re.fullmatch(r"[<>]?\s*(-?\d{1,6}(?:[.,]\d{1,4})?)", raw)
    if not m:
        return None
    try:
        return float(m.group(1).replace(",", "."))
    except Exception:
        return None


def _yk_lab_canonical_name(label):
    raw = str(label or "").strip()
    if not raw or raw == "-" or _yk_lab_has_noise(raw):
        return ""
    folded = _yk_lab_fold(raw)
    compact = re.sub(r"[^a-z0-9#%]+", "", folded)
    if not compact or compact in {
        "tarih", "tahlil", "sonuc", "sonucbirimi", "referansdegeri",
        "rapor", "islemadi", "tamkansayimihemogram", "hemogram",
    }:
        return ""

    # Specific names first; otherwise "Hb A1c" can be mistaken for hemoglobin.
    contains_rules = (
        ("HbA1c", ("hba1c", "glikehemoglobin", "glikolizehemoglobin", "a1c")),
        ("WBC", ("wbc", "lokosit", "leukosit", "lökosit")),
        ("RBC", ("rbc", "eritrosit")),
        ("Hemoglobin", ("hgb", "hemoglobin")),
        ("Hematokrit", ("hct", "hematokrit")),
        ("MCV", ("mcv",)),
        ("MCHC", ("mchc",)),
        ("MCH", ("mch",)),
        ("RDW-SD", ("rdwsd",)),
        ("RDW-CV", ("rdwcv",)),
        ("PLT", ("plt", "trombosit")),
        ("PDW", ("pdw",)),
        ("MPV", ("mpv",)),
        ("PCT", ("pct",)),
        ("NRBC%", ("nrbc%", "nrbcpercent", "nrbc")),
        ("NEUT%", ("neut%", "neutrofil%", "notrofil%")),
        ("NEUT#", ("neut#", "neutrofil#", "notrofil#")),
        ("LYMPH%", ("lymph%", "lenfosit%")),
        ("LYMPH#", ("lymph#", "lenfosit#")),
        ("MONO%", ("mono%", "monosit%")),
        ("MONO#", ("mono#", "monosit#")),
        ("EO%", ("eo%", "eozinofil%")),
        ("EO#", ("eo#", "eozinofil#")),
        ("BASO%", ("baso%", "bazofil%")),
        ("BASO#", ("baso#", "bazofil#")),
        ("Glukoz", ("glukoz", "glucose", "aclikkansekeri")),
        ("Demir", ("demirserum", "serumdemir", "demir")),
        ("Ferritin", ("ferritin",)),
        ("Vitamin B12", ("vitaminb12", "b12")),
        ("Folat", ("folat", "folicacid")),
        ("25-OH Vitamin D", ("25ohvitamind", "vitamind", "dvitamini")),
        ("TSH", ("tsh",)),
        ("Serbest T4", ("serbestt4", "freet4", "st4", "ft4")),
        ("Serbest T3", ("serbestt3", "freet3", "st3", "ft3")),
        ("Anti-TPO", ("antitpo",)),
        ("LDL", ("ldl",)),
        ("HDL", ("hdl",)),
        ("Trigliserid", ("trigliserid", "triglyceride")),
        ("Total Kolesterol", ("kolesterol", "cholesterol")),
        ("ALT", ("alaninaminotransferaz", "alt", "sgpt")),
        ("AST", ("aspartattransaminaz", "ast", "sgot")),
        ("GGT", ("ggt", "gamaglutamil")),
        ("ALP", ("alkalenfosfataz", "alp")),
        ("Kreatinin", ("kreatinin", "creatinine")),
        ("Ure", ("ure", "urea")),
        ("BUN", ("bun",)),
        ("Sodyum", ("sodyum", "sodium")),
        ("Potasyum", ("potasyum", "potassium")),
        ("Kalsiyum", ("kalsiyum", "calcium")),
        ("Magnezyum", ("magnezyum", "magnesium")),
        ("Total Bilirubin", ("bilirubintotal", "totalbilirubin")),
        ("Direkt Bilirubin", ("bilirubindirekt", "direktbilirubin")),
        ("Albumin", ("albumin",)),
        ("CRP", ("crp",)),
        ("Sedimentasyon", ("sedimentasyon", "sedim")),
        ("Beta-hCG", ("betahcg", "hcg")),
        ("Progesteron", ("progesteron",)),
        ("Estradiol", ("estradiol", "e2")),
        ("FSH", ("fsh",)),
        ("LH", ("lh",)),
        ("AMH", ("amh",)),
        ("Prolaktin", ("prolaktin", "prolactin")),
    )
    for canonical, needles in contains_rules:
        if any(n in compact for n in needles):
            return canonical
    return ""


def _yk_lab_unit_or_ref(tokens, start):
    unit = ""
    ref = ""
    if start < len(tokens):
        cand = str(tokens[start] or "").strip()
        if cand and cand != "-" and not _yk_lab_is_date_token(cand):
            folded = _yk_lab_fold(cand)
            if not _yk_lab_canonical_name(cand):
                if re.search(r"\d\s*[-–]\s*\d|^[<>]=?\s*\d", cand):
                    ref = cand
                elif len(cand) <= 24 and folded not in {"rapor", "sonuc", "referans degeri"}:
                    unit = cand
    if start + 1 < len(tokens):
        cand = str(tokens[start + 1] or "").strip()
        if cand and cand != "-" and not _yk_lab_is_date_token(cand):
            if re.search(r"\d\s*[-–]\s*\d|^[<>]=?\s*\d", cand):
                ref = cand
    return unit, ref


def _yk_lab_ref_range(ref):
    nums = re.findall(
        r"[<>]?\s*(-?\d{1,6}(?:[.,]\d{1,4})?)",
        str(ref or ""))
    if len(nums) < 2:
        return None
    try:
        a = float(nums[0].replace(",", "."))
        b = float(nums[1].replace(",", "."))
        return (min(a, b), max(a, b))
    except Exception:
        return None


def _yk_lab_range_distance(number, low, high):
    if low <= number <= high:
        return 0.0
    return min(abs(number - low), abs(number - high))


def _yk_lab_repair_ocr_number(value, ref):
    raw = str(value or "").strip()
    if re.search(r"[.,<>-]", raw):
        return raw
    if not re.fullmatch(r"\d{3,5}", raw):
        return raw
    ref_range = _yk_lab_ref_range(ref)
    if not ref_range:
        return raw
    low, high = ref_range
    try:
        base = float(raw)
    except Exception:
        return raw
    raw_distance = _yk_lab_range_distance(base, low, high)
    candidates = []
    for div in (10.0, 100.0, 1000.0):
        cand = base / div
        if cand <= 0:
            continue
        candidates.append((cand, _yk_lab_range_distance(cand, low, high)))
    if not candidates:
        return raw
    best, best_distance = min(candidates, key=lambda item: item[1])
    if best_distance < raw_distance and (
            best_distance == 0 or raw_distance > max(high - low, 1.0)):
        return f"{best:.4f}".rstrip("0").rstrip(".")
    return raw


def _yk_lab_clean_unit(unit):
    text = str(unit or "").strip()
    if not text:
        return ""
    text = text.replace("µ", "u").replace("μ", "u")
    text = re.sub(
        r"10\s*[*^]\s*3\s*/\s*[?9u]?L",
        "10^3/uL", text, flags=re.IGNORECASE)
    text = re.sub(
        r"10\s*[*^]\s*6\s*/\s*[?9u]?L",
        "10^6/uL", text, flags=re.IGNORECASE)
    return text


def _yk_lab_put_value(values, label, value, unit="", ref="", raw_line=""):
    canonical = _yk_lab_canonical_name(label)
    if not canonical:
        return
    value = _yk_lab_repair_ocr_number(value, ref)
    number = _yk_lab_parse_number(value)
    if number is None:
        return
    unit = _yk_lab_clean_unit(unit)
    if unit and re.fullmatch(r"\.\d{4}", str(unit).strip()):
        return
    if canonical in values:
        return
    values[canonical] = {
        "value": number,
        "unit": str(unit or "").strip(),
        "ref": str(ref or "").strip(),
        "raw_line": str(raw_line or label).strip()[:300],
    }


def _yk_extract_lab_values_clean(raw_text):
    raw_text = _repair_mojibake_text(raw_text or "")
    values = {}
    if not raw_text.strip():
        return values

    # e-Nabiz copy/paste often arrives as a tabular text export.
    for line in raw_text.splitlines():
        parts = [p.strip() for p in line.split("\t") if p.strip()]
        if len(parts) < 4:
            continue
        date_index = 0 if _yk_lab_is_date_token(parts[0]) else -1
        if date_index < 0 and len(parts) > 1 and _yk_lab_is_date_token(parts[1]):
            date_index = 1
        if date_index < 0 or date_index + 2 >= len(parts):
            continue
        label = parts[date_index + 1]
        value = parts[date_index + 2]
        unit = parts[date_index + 3] if date_index + 3 < len(parts) else ""
        ref = parts[date_index + 4] if date_index + 4 < len(parts) else ""
        _yk_lab_put_value(values, label, value, unit, ref, line)

    # OCR from e-Nabiz screenshots usually arrives as one visual table row:
    # "7.08.2025 WBC 6.33 10*3/?L 3.91 - 10.9".
    for line in raw_text.splitlines():
        row = re.sub(r"[|]+", " ", str(line or ""))
        row = re.sub(r"\s+", " ", row).strip()
        if not row:
            continue
        row = re.sub(
            r"^(?:\d{1,2}[./-]\d{1,2}[./-]\d{4}|"
            r"\d{4}[./-]\d{1,2}[./-]\d{1,2}|-)\s+",
            "", row)
        parts = row.split()
        if len(parts) < 2:
            continue
        for value_idx in range(1, min(len(parts), 10)):
            if _yk_lab_parse_number(parts[value_idx]) is None:
                continue
            label = " ".join(parts[:value_idx]).strip(":- ")
            if not _yk_lab_canonical_name(label):
                continue
            rest = " ".join(parts[value_idx + 1:])
            ref = ""
            unit = ""
            ref_match = re.search(
                r"([<>]?\s*\d{1,6}(?:[.,]\d{1,4})?\s*"
                r"(?:-|–|—|ile|to)\s*"
                r"[<>]?\s*\d{1,6}(?:[.,]\d{1,4})?|"
                r"[<>]=?\s*\d{1,6}(?:[.,]\d{1,4})?)",
                rest)
            if ref_match:
                unit = rest[:ref_match.start()].strip()
                ref = ref_match.group(1).strip()
            else:
                unit = rest.strip()
            _yk_lab_put_value(
                values, label, parts[value_idx], unit, ref, line)
            break

    # PDF text extraction can be vertical: date, test, value, unit, ref.
    tokens = [ln.strip() for ln in raw_text.splitlines() if ln.strip()]
    skip_folded = {
        "tarih", "tahlil", "sonuc", "sonuc birimi", "referans degeri",
        "rapor", "islem adi", "adi soyadi", "ad soyad",
    }
    i = 0
    while i < len(tokens):
        label_idx = i
        if _yk_lab_is_date_token(tokens[i]):
            label_idx = i + 1
        elif tokens[i] == "-":
            label_idx = i + 1
        if label_idx >= len(tokens):
            i += 1
            continue
        label = tokens[label_idx]
        if _yk_lab_fold(label) in skip_folded or not _yk_lab_canonical_name(label):
            i += 1
            continue
        value_idx = None
        for j in range(label_idx + 1, min(label_idx + 5, len(tokens))):
            if _yk_lab_parse_number(tokens[j]) is not None:
                value_idx = j
                break
            if _yk_lab_canonical_name(tokens[j]) or _yk_lab_is_date_token(tokens[j]):
                break
        if value_idx is None:
            i += 1
            continue
        unit, ref = _yk_lab_unit_or_ref(tokens, value_idx + 1)
        raw_line = " | ".join(tokens[label_idx:min(value_idx + 4, len(tokens))])
        _yk_lab_put_value(values, label, tokens[value_idx], unit, ref, raw_line)
        i = value_idx + 1
    return values


def _yk_sanitize_lab_values(values, raw_text=""):
    cleaned = {}
    if isinstance(values, str):
        try:
            values = json.loads(values or "{}")
        except Exception:
            values = {}
    for label, payload in (values or {}).items():
        canonical = _yk_lab_canonical_name(label)
        if not canonical or not isinstance(payload, dict):
            continue
        value = payload.get("value")
        unit = payload.get("unit") or ""
        ref = payload.get("ref") or ""
        raw_line = payload.get("raw_line") or label
        if _yk_lab_parse_number(value) is None:
            continue
        if str(unit).strip().startswith(".20"):
            continue
        _yk_lab_put_value(cleaned, canonical, value, unit, ref, raw_line)
    parsed = _yk_extract_lab_values_clean(raw_text)
    if len(parsed) >= max(1, len(cleaned) // 2):
        return parsed
    return cleaned


def _list_lab_results_clean(patient_key, autorepair=True):
    import json as _json
    if not patient_key:
        return []
    updates = []
    out = []
    try:
        with db_conn() as con:
            con.row_factory = sqlite3.Row
            rows = con.execute(
                "SELECT id, patient_key, pdf_path, source, test_date, "
                "uploaded_at, extracted_json, raw_text, notes FROM lab_results "
                "WHERE patient_key=? ORDER BY "
                "COALESCE(test_date, uploaded_at) DESC, id DESC",
                (patient_key,)).fetchall()
    except Exception:
        return list_lab_results(patient_key)
    for r in rows:
        old_text = r["extracted_json"] or "{}"
        try:
            old_values = _json.loads(old_text)
        except Exception:
            old_values = {}
        values = _yk_sanitize_lab_values(old_values, r["raw_text"] or "")
        try:
            new_text = _json.dumps(values, ensure_ascii=False, sort_keys=True)
            old_norm = _json.dumps(old_values, ensure_ascii=False, sort_keys=True)
            if autorepair and values and new_text != old_norm:
                updates.append((new_text, int(r["id"])))
        except Exception:
            pass
        out.append({
            "id": r["id"],
            "pdf_path": r["pdf_path"],
            "source": r["source"],
            "test_date": r["test_date"],
            "uploaded_at": r["uploaded_at"],
            "values": values,
            "notes": r["notes"] or "",
        })
    if updates:
        try:
            with db_conn() as con:
                con.executemany(
                    "UPDATE lab_results SET extracted_json=? WHERE id=?",
                    updates)
                con.commit()
        except Exception as ex:
            print(f"lab autorepair skipped: {ex}")
    return out


def _yk_clipboard_fold_text(value):
    text = _repair_mojibake_text(str(value or ""))
    text = unicodedata.normalize("NFKD", text)
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    return text.casefold()


def _yk_clipboard_date_ddmmyyyy(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    m = re.search(
        r"(\d{1,2})[./-](\d{1,2})[./-](\d{4})|"
        r"(\d{4})[./-](\d{1,2})[./-](\d{1,2})",
        raw)
    if not m:
        return ""
    try:
        if m.group(1):
            day, month, year = int(m.group(1)), int(m.group(2)), int(m.group(3))
        else:
            year, month, day = int(m.group(4)), int(m.group(5)), int(m.group(6))
        dt = datetime(year, month, day)
        if 1900 <= dt.year <= 2100:
            return dt.strftime("%d.%m.%Y")
    except Exception:
        pass
    return ""


def _yk_valid_tc_no(value):
    digits = re.sub(r"\D+", "", str(value or ""))
    if len(digits) != 11 or digits[0] == "0":
        return False
    try:
        nums = [int(ch) for ch in digits]
        odd = sum(nums[0:9:2])
        even = sum(nums[1:8:2])
        return ((odd * 7 - even) % 10 == nums[9]
                and sum(nums[:10]) % 10 == nums[10])
    except Exception:
        return False


def _yk_clipboard_find_numbers_near(text, label_patterns, unit="", high=None):
    folded = _yk_clipboard_fold_text(text)
    out = {}
    for key, patterns in label_patterns.items():
        for label in patterns:
            label_fold = re.escape(_yk_clipboard_fold_text(label))
            rx_list = (
                rf"(?:^|[^a-z0-9]){label_fold}(?![a-z0-9])\s*[:=\-]?\s*"
                rf"(-?\d{{1,5}}(?:[.,]\d+)?)",
                rf"(?:^|[^a-z0-9]){label_fold}(?![a-z0-9])\D{{0,24}}"
                rf"(-?\d{{1,5}}(?:[.,]\d+)?)",
            )
            for rx in rx_list:
                m = re.search(rx, folded, re.IGNORECASE)
                if not m:
                    continue
                val = m.group(1).replace(",", ".")
                try:
                    fval = float(val)
                    if high is not None and fval > high:
                        continue
                except Exception:
                    pass
                out[key] = {"value": val, "unit": unit, "ref": ""}
                break
            if key in out:
                break
    return out


def _yk_clipboard_parse_text_web(raw_text, default_source="web_paste"):
    """Parse BulutKlinik/e-Nabiz copied or OCR text without legacy modules."""
    text = _repair_mojibake_text(raw_text or "")
    folded = _yk_clipboard_fold_text(text)
    source_hint = default_source or "web_paste"
    if any(w in folded for w in ("bulutklinik", "bulut klinik")):
        source_hint = "BulutKlinik"
    elif any(w in folded for w in (
            "e-nabiz", "e nabiz", "enabiz", "saglik bakanligi",
            "saglik.gov.tr")):
        source_hint = "e-Nabiz"

    tc_numbers = []
    for raw_tc in re.findall(r"(?<!\d)([1-9]\d{10})(?!\d)", text):
        if raw_tc not in tc_numbers and _yk_valid_tc_no(raw_tc):
            tc_numbers.append(raw_tc)

    phones = []
    for raw_phone in re.findall(
            r"(?:\+?90\s*)?(?:0\s*)?5\d[\d\s().-]{7,16}\d", text):
        digits = re.sub(r"\D+", "", raw_phone)
        if digits.startswith("90") and len(digits) >= 12:
            digits = "0" + digits[-10:]
        elif digits.startswith("5") and len(digits) == 10:
            digits = "0" + digits
        elif len(digits) > 11:
            digits = digits[-11:]
        if len(digits) == 11 and digits.startswith("05") and digits not in phones:
            phones.append(digits)

    dob = ""
    for rx in (
            r"(?:dogum\s*tarihi|doğum\s*tarihi|birth\s*date|date\s*of\s*birth|dob)"
            r"\D{0,24}(\d{1,2}[./-]\d{1,2}[./-]\d{4}|\d{4}[./-]\d{1,2}[./-]\d{1,2})",
            r"(?:dt|d\.t\.)\D{0,12}(\d{1,2}[./-]\d{1,2}[./-]\d{4})",
    ):
        m = re.search(rx, folded, re.IGNORECASE)
        if m:
            dob = _yk_clipboard_date_ddmmyyyy(m.group(1))
            if dob:
                break

    age = None
    for rx in (
            r"(?:hasta\s*yasi|hasta\s*yas|yas|yaş|age)\D{0,14}(\d{1,3})(?!\s*[+]\s*\d)",
            r"\b(\d{1,3})\s*(?:yasinda|yaşında|yas|yaş)\b",
    ):
        m = re.search(rx, folded, re.IGNORECASE)
        if m:
            try:
                candidate = int(m.group(1))
                if 1 < candidate <= 120:
                    age = candidate
                    break
            except Exception:
                pass

    names = []
    name_patterns = (
        r"(?:ad\s*soyad|adi\s*soyadi|adı\s*soyadı|hasta\s*adi\s*soyadi|hasta\s*adı\s*soyadı)"
        r"\s*[:=\-]?\s*([A-Za-zÇĞİÖŞÜçğıöşü'.\- ]{5,80})",
        r"(?:hasta\s*adi|hasta\s*adı|ad[ıi])\s*[:=\-]?\s*"
        r"([A-Za-zÇĞİÖŞÜçğıöşü'.\- ]{5,80})",
    )
    for rx in name_patterns:
        for m in re.finditer(rx, text, re.IGNORECASE):
            name = re.sub(r"\s+", " ", m.group(1)).strip(" -:;|")
            name = re.split(r"\s{2,}| T\.?C\.?| Dogum| Doğum| Telefon| GSM", name)[0].strip()
            if 5 <= len(name) <= 80 and name not in names:
                names.append(name)
            if len(names) >= 4:
                break
        if names:
            break

    lab_values = _extract_lab_values_from_text_web(text) or {}
    usg_labels = {
        "BPD": ("bpd", "biparietal", "biparyetal"),
        "HC": ("hc", "head circumference", "bas cevresi", "baş çevresi"),
        "AC": ("ac", "abdominal circumference", "karin cevresi", "karın çevresi"),
        "FL": ("fl", "femur"),
        "CRL": ("crl", "crown rump"),
        "NT": ("nt", "ense saydamligi", "ense saydamlığı"),
        "EFW": ("efw", "tahmini agirlik", "tahmini ağırlık"),
        "AFI": ("afi", "amniyon"),
        "UA PI": ("ua pi", "umbilikal arter pi", "umbilical artery pi"),
        "UA RI": ("ua ri", "umbilikal arter ri"),
        "UA S/D": ("ua s/d", "s/d"),
        "MCA PI": ("mca pi", "orta serebral arter pi"),
        "MCA PSV": ("mca psv",),
        "FHR": ("fhr", "fetal kalp", "kalp atimi", "kalp atımı"),
        "Serviks": ("serviks", "servikal uzunluk", "cervical length"),
    }
    usg_values = _yk_clipboard_find_numbers_near(
        text, usg_labels, unit="", high=10000)

    score = 0
    score += 18 if tc_numbers else 0
    score += 12 if phones else 0
    score += 10 if names else 0
    score += 10 if (age or dob) else 0
    score += min(35, len(lab_values) * 4)
    score += min(30, len(usg_values) * 5)
    confidence = max(0, min(95, score))
    return {
        "source_hint": source_hint,
        "tc_numbers": tc_numbers,
        "phones": phones,
        "names": names,
        "age": age,
        "dob": dob,
        "lab_values": lab_values,
        "usg_values": usg_values,
        "confidence": confidence,
    }


def _yk_clipboard_has_meaningful_data(parsed):
    parsed = parsed or {}
    return bool(
        parsed.get("tc_numbers")
        or parsed.get("phones")
        or parsed.get("names")
        or parsed.get("age")
        or parsed.get("dob")
        or parsed.get("lab_values")
        or parsed.get("usg_values"))


def _yk_clipboard_preview_html(parsed):
    parsed = parsed or {}
    if not _yk_clipboard_has_meaningful_data(parsed):
        return ""
    rows = []
    if parsed.get("source_hint"):
        rows.append(("Kaynak", parsed.get("source_hint")))
    if parsed.get("tc_numbers"):
        rows.append(("TC Kimlik", ", ".join(parsed.get("tc_numbers") or [])))
    if parsed.get("phones"):
        rows.append(("Telefon", ", ".join(parsed.get("phones") or [])))
    if parsed.get("names"):
        rows.append(("Isim adaylari", ", ".join((parsed.get("names") or [])[:4])))
    if parsed.get("age"):
        rows.append(("Yas", str(parsed.get("age"))))
    if parsed.get("dob"):
        rows.append(("Dogum tarihi", parsed.get("dob")))
    labs = parsed.get("lab_values") or {}
    if labs:
        lab_rows = "<br>".join(
            f"{safe_html(k)}: <b>{safe_html((v or {}).get('value'))}</b>"
            for k, v in list(labs.items())[:12])
        rows.append((f"Tahlil ({len(labs)})", lab_rows))
    usgs = parsed.get("usg_values") or {}
    if usgs:
        usg_rows = "<br>".join(
            f"{safe_html(k)}: <b>{safe_html((v or {}).get('value'))}</b>"
            for k, v in list(usgs.items())[:12])
        rows.append((f"USG ({len(usgs)})", usg_rows))
    body = "".join(
        f"<tr><th style='width:180px'>{safe_html(k)}</th><td>{v}</td></tr>"
        for k, v in rows)
    return f"""
    <div class="alert alert-info">
      <div class="d-flex justify-content-between align-items-center flex-wrap gap-2">
        <h5 class="mb-1">Akilli aktarimda bulunan veriler</h5>
        <span class="badge bg-primary">Guven %{int(parsed.get('confidence') or 0)}</span>
      </div>
      <table class="table table-sm mb-0 mt-2">{body}</table>
    </div>
    """


def _yk_apply_clipboard_payload_to_patient(patient_key, parsed, raw_text,
                                           source="web_paste",
                                           source_ref="Pano / dis sistem"):
    parsed = parsed or {}
    raw_text = _repair_mojibake_text(raw_text or "")
    actions = []
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    source_hint = parsed.get("source_hint") or source

    try:
        phones = parsed.get("phones") or []
        if phones:
            decision = _patient_data_suggest_value(
                patient_key, "phone", phones[0],
                source=source, source_ref=source_ref,
                confidence=0.72, auto_apply_empty=True)
            label = "onaya alindi" if decision.get("status") == "queued" else phones[0]
            actions.append(f"Telefon: {label}")
    except Exception:
        pass

    try:
        demo = {}
        if parsed.get("age"):
            demo["age"] = str(parsed.get("age"))
        if parsed.get("dob"):
            demo["birth_date"] = parsed.get("dob")
        tcs = parsed.get("tc_numbers") or []
        if tcs:
            demo["tc_no"] = tcs[0]
        if parsed.get("names"):
            demo["canonical_name"] = parsed.get("names")[0]
        if demo:
            decisions = _patient_data_suggest_demographics(
                patient_key, demo,
                source=source, source_ref=source_ref,
                confidence=0.72, auto_apply_empty=True)
            queued = sum(1 for d in decisions if d.get("status") == "queued")
            actions.append(
                f"Demografi: {len(demo)} alan"
                + (f" ({queued} onay bekliyor)" if queued else ""))
    except Exception:
        pass

    labs = parsed.get("lab_values") or {}
    if labs:
        try:
            parsed_lab = {
                "values": labs,
                "raw_text": raw_text,
                "test_date": _extract_date_from_lab_text(raw_text),
            }
            lab_id = _save_lab_result_resilient(
                patient_key, "", parsed_lab,
                source=f"{source}:{source_hint}",
                notes=f"{source_ref} aktarimi")
            actions.append(f"Tahlil: {len(labs)} parametre" + (f" (#{lab_id})" if lab_id else ""))
        except Exception as ex:
            actions.append(f"Tahlil hatasi: {ex}")

    usgs = parsed.get("usg_values") or {}
    if usgs:
        try:
            usg_text = "\n".join(
                f" - {k}: {(v or {}).get('value')} {(v or {}).get('unit') or ''}".rstrip()
                for k, v in usgs.items())
            with db_conn() as con:
                con.execute(
                    "INSERT INTO visits(patient_folder_key, visit_date, notes, "
                    "examination, source, created_at) VALUES(?,?,?,?,?,?)",
                    (patient_key, datetime.now().strftime("%Y-%m-%d %H:%M"),
                     f"USG bulgulari ({source_hint} ekran aktarimi):\n{usg_text}",
                     usg_text, f"{source}:usg", now))
                con.commit()
            actions.append(f"USG: {len(usgs)} olcum")
        except Exception:
            pass

    if raw_text and len(raw_text.strip()) > 40:
        try:
            with db_conn() as con:
                con.execute(
                    "INSERT INTO visits(patient_folder_key, visit_date, notes, "
                    "source, created_at) VALUES(?,?,?,?,?)",
                    (patient_key, datetime.now().strftime("%Y-%m-%d %H:%M"),
                     f"Ekran/metin aktarimi ({source_hint})\n\n{raw_text[:4000]}",
                     f"{source}:raw", now))
                con.commit()
            actions.append("Ham metin notu eklendi")
        except Exception:
            pass

    return actions


def _yk_image_bytes_to_ollama_b64(image_data, max_side=2200):
    try:
        from PIL import Image
        img = Image.open(BytesIO(image_data))
        img = img.convert("RGB")
        img.thumbnail((max_side, max_side))
        buf = BytesIO()
        img.save(buf, format="JPEG", quality=92, optimize=True)
        return base64.b64encode(buf.getvalue()).decode("ascii")
    except Exception:
        try:
            return base64.b64encode(image_data or b"").decode("ascii")
        except Exception:
            return ""


def _yk_prepare_screen_capture_image_bytes(image_data, max_side=4200,
                                           target_max_bytes=18 * 1024 * 1024):
    """Normalize screenshots for OCR without destroying table text quality."""
    meta = {
        "input_bytes": len(image_data or b""),
        "output_bytes": len(image_data or b""),
        "compressed": False,
    }
    if not image_data:
        return b"", meta

    try:
        from PIL import Image, ImageOps
        with Image.open(BytesIO(image_data)) as img:
            img = ImageOps.exif_transpose(img)
            original_size = img.size

            if img.mode in ("RGBA", "LA") or (
                    img.mode == "P" and "transparency" in img.info):
                bg = Image.new("RGB", img.size, "white")
                rgba = img.convert("RGBA")
                bg.paste(rgba, mask=rgba.getchannel("A"))
                img = bg
            else:
                img = img.convert("RGB")

            largest = max(img.size or (0, 0))
            resample = getattr(getattr(Image, "Resampling", Image),
                               "LANCZOS")
            if largest > max_side:
                img.thumbnail((max_side, max_side), resample)
            elif img.size[0] and img.size[0] < 2200:
                scale = min(max_side / max(img.size), 2200 / img.size[0])
                if scale > 1.05:
                    img = img.resize(
                        (int(img.size[0] * scale), int(img.size[1] * scale)),
                        resample)

            out = BytesIO()
            img.save(out, format="PNG", optimize=True)
            last_payload = out.getvalue()
            output_format = "PNG"
            if len(last_payload) > target_max_bytes:
                for quality in (96, 92, 88, 84):
                    out.seek(0)
                    out.truncate(0)
                    img.save(out, format="JPEG", quality=quality,
                             optimize=True, progressive=False)
                    last_payload = out.getvalue()
                    output_format = "JPEG"
                    if len(last_payload) <= target_max_bytes:
                        break

            if not last_payload:
                return image_data, meta

            meta.update({
                "output_bytes": len(last_payload),
                "compressed": (
                    len(last_payload) < len(image_data)
                    or img.size != original_size),
                "format": output_format,
                "width": img.size[0],
                "height": img.size[1],
            })
            return last_payload, meta
    except Exception as ex:
        meta["error"] = str(ex)
        return image_data, meta


def _yk_screen_capture_ocr_score(text):
    text = str(text or "").strip()
    if not text:
        return 0
    folded = _yk_lab_fold(text)
    lab_terms = (
        "tarih", "tahlil", "sonuc", "referans", "wbc", "rbc",
        "rdw", "plt", "hgb", "hct", "mcv", "mch", "lymph",
        "glukoz", "kolesterol", "ferritin", "crp", "tsh",
    )
    lab_hits = sum(1 for term in lab_terms if term in folded)
    number_hits = len(re.findall(r"\b\d{1,6}(?:[.,]\d{1,4})?\b", text))
    date_hits = len(re.findall(r"\b\d{1,2}[./-]\d{1,2}[./-]\d{4}\b", text))
    noisy_hits = sum(text.count(marker) for marker in _YK_LAB_NOISE_MARKERS)
    return (
        len(text)
        + lab_hits * 180
        + min(number_hits, 120) * 10
        + date_hits * 60
        - noisy_hits * 220)


def _yk_screen_capture_ocr_variants(image_data):
    from PIL import Image, ImageOps, ImageEnhance, ImageFilter

    with Image.open(BytesIO(image_data)) as img:
        img = ImageOps.exif_transpose(img)
        if img.mode in ("RGBA", "LA") or (
                img.mode == "P" and "transparency" in img.info):
            bg = Image.new("RGB", img.size, "white")
            rgba = img.convert("RGBA")
            bg.paste(rgba, mask=rgba.getchannel("A"))
            img = bg
        else:
            img = img.convert("RGB")

        resample = getattr(getattr(Image, "Resampling", Image), "LANCZOS")
        width, height = img.size
        if width and width < 3000:
            scale = min(2.6, 3000 / width)
            img = img.resize(
                (int(width * scale), int(height * scale)), resample)

        gray = ImageOps.grayscale(img)
        gray = ImageOps.autocontrast(gray)
        sharp = ImageEnhance.Contrast(gray).enhance(1.55)
        sharp = ImageEnhance.Sharpness(sharp).enhance(2.0)
        unsharp = sharp.filter(ImageFilter.UnsharpMask(
            radius=1.2, percent=160, threshold=3))
        threshold = sharp.point(lambda p: 255 if p > 178 else 0)

        return [
            ("gray", gray),
            ("sharp", sharp),
            ("unsharp", unsharp),
            ("threshold", threshold),
        ]


def _yk_ocr_text_from_image_bytes(image_data):
    if not image_data:
        return "", "Goruntu bos."
    try:
        try:
            pytesseract = _pdf_atelier_configure_tesseract()
        except Exception:
            import pytesseract
        try:
            if os.name == "nt":
                for candidate in (
                        r"C:\Program Files\Tesseract-OCR\tesseract.exe",
                        r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe"):
                    if Path(candidate).exists():
                        pytesseract.pytesseract.tesseract_cmd = candidate
                        break
        except Exception:
            pass
        configs = (
            ("tur+eng", "--oem 1 --psm 6 -c preserve_interword_spaces=1"),
            ("tur+eng", "--oem 1 --psm 4 -c preserve_interword_spaces=1"),
            ("tur+eng", "--oem 1 --psm 11 -c preserve_interword_spaces=1"),
            ("eng", "--oem 1 --psm 6 -c preserve_interword_spaces=1"),
        )
        best_text = ""
        best_score = 0
        last_error = ""
        for variant_name, img in _yk_screen_capture_ocr_variants(image_data):
            del variant_name
            for lang, cfg in configs:
                try:
                    text = (pytesseract.image_to_string(
                        img, lang=lang, config=cfg) or "").strip()
                    score = _yk_screen_capture_ocr_score(text)
                    if score > best_score:
                        best_score = score
                        best_text = text
                except Exception as ex:
                    last_error = str(ex)
        if best_text:
            return best_text, ""
        return "", last_error or "OCR metin bulamadi."
    except Exception as ex:
        return "", str(ex)


def _extract_text_from_pdf_file(path):
    if not HAS_FITZ:
        return ""
    try:
        doc = fitz.open(str(path))
        parts = []
        for page in doc:
            parts.append(page.get_text("text") or "")
        doc.close()
        return "\n".join(parts).strip()
    except Exception:
        return ""


def _fold_text_for_report_type(text):
    folded = unicodedata.normalize("NFKD", str(text or ""))
    folded = "".join(ch for ch in folded if not unicodedata.combining(ch))
    folded = folded.casefold()
    folded = re.sub(r"\s+", " ", folded)
    return folded.strip()


def _detect_report_type_from_text(text):
    folded = _fold_text_for_report_type(text)
    if not folded:
        return ""
    lab_markers = (
        "laboratuvar", "laboratory", "tahlil", "tetkik",
        "sonuc birimi", "referans degeri", "referans araligi",
        "e-nabiz", "enabiz", "hemogram", "tam kan sayimi",
        "glukoz", "kolesterol", "ferritin", "crp",
    )
    if any(tok in folded for tok in lab_markers):
        return "lab"
    if any(tok in folded for tok in (
            "obstetrics report",
            "obstetric report",
            "obstetrik rapor",
            "obstetric ultrasound",
    )):
        return "obstetric"
    if any(tok in folded for tok in (
            "gynecology report",
            "gynaecology report",
            "gynecologic report",
            "jinekoloji rapor",
            "jinekoloji rapor",
    )):
        return "gynecologic"
    return ""


def _detect_report_type_from_pdf_file(path):
    try:
        pdf_text = _extract_text_from_pdf_file(path)
    except Exception:
        pdf_text = ""
    return _detect_report_type_from_text(pdf_text)


def _set_patient_type_from_report(patient_key, report_type, source="pdf-auto"):
    ptype = str(report_type or "").strip().lower()
    if ptype not in ("obstetric", "gynecologic"):
        return False
    key = str(patient_key or "").strip()
    if not key:
        return False
    try:
        with db_conn() as con:
            row = con.execute(
                "SELECT ptype FROM patient_type WHERE patient_key=? LIMIT 1",
                (key,)).fetchone()
        current = str((row[0] if row else "") or "").strip().lower()
    except Exception:
        current = ""
    if current in ("medical_aesthetic", "gynecologic_aesthetic"):
        return False
    if current == ptype:
        return False
    try:
        note = f"PDF rapor tipinden otomatik atandi ({source})."
        set_patient_type(key, ptype, is_manual=False, notes=note)
        return True
    except Exception as ex:
        print(f"patient type auto set: {ex}")
        return False


def _ensure_patient_pdf_archive_schema(con=None):
    def _run(open_con):
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS patient_pdf_archive (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                patient_key TEXT NOT NULL,
                visit_key TEXT,
                rel_path TEXT,
                file_name TEXT NOT NULL,
                source TEXT,
                source_path TEXT,
                report_type TEXT,
                mime_type TEXT DEFAULT 'application/pdf',
                file_size INTEGER DEFAULT 0,
                sha256 TEXT NOT NULL,
                text_head TEXT,
                file_blob BLOB NOT NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                archived_by TEXT
            )
        """)
        for ddl in (
            "ALTER TABLE patient_pdf_archive ADD COLUMN deleted_at TEXT",
            "ALTER TABLE patient_pdf_archive ADD COLUMN deleted_by TEXT",
            "ALTER TABLE patient_pdf_archive ADD COLUMN delete_reason TEXT",
            "CREATE UNIQUE INDEX IF NOT EXISTS idx_pdf_archive_patient_sha "
            "ON patient_pdf_archive(patient_key, sha256)",
            "CREATE INDEX IF NOT EXISTS idx_pdf_archive_patient_visit "
            "ON patient_pdf_archive(patient_key, visit_key, updated_at DESC)",
            "CREATE INDEX IF NOT EXISTS idx_pdf_archive_patient_rel "
            "ON patient_pdf_archive(patient_key, rel_path)",
        ):
            try:
                open_con.execute(ddl)
            except Exception:
                pass

    if con is not None:
        _run(con)
        return
    with db_conn() as open_con:
        _run(open_con)
        open_con.commit()


def _archive_patient_pdf_blob(patient_key, file_name, file_blob,
                              visit_key="", rel_path="", source="",
                              source_path="", report_type="",
                              mime_type="application/pdf",
                              text_head="", archived_by="",
                              con=None):
    key = str(patient_key or "").strip()
    if not key:
        return {}
    blob = bytes(file_blob or b"")
    if not blob:
        return {}
    if len(blob) > PDF_ARCHIVE_MAX_BYTES:
        return {}
    safe_name = _safe_upload_filename(file_name or "rapor.pdf")
    import hashlib as _hashlib
    sha256 = _hashlib.sha256(blob).hexdigest()
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    normalized_type = str(report_type or "").strip().lower()
    if normalized_type in ("laboratuvar", "laboratory", "tahlil", "tetkik"):
        normalized_type = "lab"
    if normalized_type not in ("obstetric", "gynecologic", "lab"):
        normalized_type = ""
    text_head = str(text_head or "")[:20000]
    creator = str(archived_by or (session.get("user", "?")
                                  if has_request_context() else "system"))

    def _run(open_con):
        _ensure_patient_pdf_archive_schema(open_con)
        open_con.execute(
            "INSERT INTO patient_pdf_archive("
            "patient_key, visit_key, rel_path, file_name, source, source_path, "
            "report_type, mime_type, file_size, sha256, text_head, file_blob, "
            "created_at, updated_at, archived_by"
            ") VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) "
            "ON CONFLICT(patient_key, sha256) DO UPDATE SET "
            "visit_key=COALESCE(NULLIF(excluded.visit_key,''), patient_pdf_archive.visit_key), "
            "rel_path=COALESCE(NULLIF(excluded.rel_path,''), patient_pdf_archive.rel_path), "
            "file_name=COALESCE(NULLIF(excluded.file_name,''), patient_pdf_archive.file_name), "
            "source=COALESCE(NULLIF(excluded.source,''), patient_pdf_archive.source), "
            "source_path=COALESCE(NULLIF(excluded.source_path,''), patient_pdf_archive.source_path), "
            "report_type=COALESCE(NULLIF(excluded.report_type,''), patient_pdf_archive.report_type), "
            "mime_type=COALESCE(NULLIF(excluded.mime_type,''), patient_pdf_archive.mime_type), "
            "file_size=CASE WHEN excluded.file_size > 0 THEN excluded.file_size ELSE patient_pdf_archive.file_size END, "
            "text_head=COALESCE(NULLIF(excluded.text_head,''), patient_pdf_archive.text_head), "
            "file_blob=CASE WHEN LENGTH(excluded.file_blob) > 0 THEN excluded.file_blob ELSE patient_pdf_archive.file_blob END, "
            "updated_at=excluded.updated_at, "
            "archived_by=COALESCE(NULLIF(excluded.archived_by,''), patient_pdf_archive.archived_by)",
            (key, str(visit_key or "").strip(), str(rel_path or "").strip(),
             safe_name, str(source or "").strip(),
             str(source_path or "").strip(), normalized_type,
             str(mime_type or "application/pdf").strip() or "application/pdf",
             int(len(blob)), sha256, text_head, sqlite3.Binary(blob),
             now, now, creator))
        row = open_con.execute(
            "SELECT id FROM patient_pdf_archive "
            "WHERE patient_key=? AND sha256=? LIMIT 1",
            (key, sha256)).fetchone()
        return int(row[0] if row else 0)

    try:
        if con is not None:
            row_id = _run(con)
        else:
            with db_conn() as open_con:
                row_id = _run(open_con)
                open_con.commit()
    except Exception as ex:
        print(f"pdf archive save: {ex}")
        return {}
    return {
        "id": row_id,
        "sha256": sha256,
        "size": len(blob),
        "report_type": normalized_type,
    }


def _archive_patient_pdf_file(patient_key, visit_key, file_path, source="",
                              report_type="", text_hint="", con=None):
    path = Path(file_path or "")
    if not path or not path.exists() or not path.is_file():
        return {}
    if _file_kind_for_path(path) != "pdf":
        return {}
    try:
        if path.stat().st_size > PDF_ARCHIVE_MAX_BYTES:
            return {}
    except Exception:
        pass
    try:
        blob = path.read_bytes()
    except Exception:
        return {}
    if not blob:
        return {}
    text_for_report = str(text_hint or "")
    if not text_for_report:
        text_for_report = _extract_text_from_pdf_file(path)
    detected = str(report_type or "").strip().lower() or _detect_report_type_from_text(text_for_report)
    try:
        patient_root = _patient_root_for_nas(patient_key)
        rel_path = path.resolve().relative_to(patient_root.resolve()).as_posix()
    except Exception:
        rel_path = (f"{visit_key}/{path.name}" if visit_key else path.name)
    return _archive_patient_pdf_blob(
        patient_key=patient_key,
        visit_key=visit_key or "",
        rel_path=rel_path,
        file_name=path.name,
        file_blob=blob,
        source=source or "patient-pdf",
        source_path=str(path),
        report_type=detected,
        mime_type="application/pdf",
        text_head=text_for_report,
        con=con,
    )


def _load_archived_pdf_record(patient_key, visit_key="", file_name="", rel_path=""):
    key = str(patient_key or "").strip()
    if not key:
        return None
    safe_name = _safe_media_route_part(file_name)
    safe_rel = _safe_media_route_part(rel_path)
    try:
        _ensure_patient_pdf_archive_schema()
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            if safe_rel:
                row = con.execute(
                    "SELECT * FROM patient_pdf_archive "
                    "WHERE patient_key=? AND rel_path=? "
                    "AND COALESCE(deleted_at, '') = '' "
                    "ORDER BY updated_at DESC, id DESC LIMIT 1",
                    (key, safe_rel)).fetchone()
                if row:
                    return row
            if safe_name and visit_key:
                row = con.execute(
                    "SELECT * FROM patient_pdf_archive "
                    "WHERE patient_key=? AND visit_key=? AND file_name=? "
                    "AND COALESCE(deleted_at, '') = '' "
                    "ORDER BY updated_at DESC, id DESC LIMIT 1",
                    (key, str(visit_key), safe_name)).fetchone()
                if row:
                    return row
            if safe_name:
                row = con.execute(
                    "SELECT * FROM patient_pdf_archive "
                    "WHERE patient_key=? AND file_name=? "
                    "AND COALESCE(deleted_at, '') = '' "
                    "ORDER BY updated_at DESC, id DESC LIMIT 1",
                    (key, safe_name)).fetchone()
                if row:
                    return row
    except Exception:
        return None
    return None


def _send_archived_pdf_blob(row, download=False):
    if not row:
        abort(404)
    blob = row.get("file_blob") or b""
    if not blob:
        abort(404)
    file_name = _safe_upload_filename(row.get("file_name") or "rapor.pdf")
    mime = str(row.get("mime_type") or "application/pdf").strip() or "application/pdf"
    response = send_file(
        BytesIO(blob),
        mimetype=mime,
        as_attachment=bool(download),
        download_name=file_name,
        conditional=True,
        max_age=3600,
    )
    try:
        response.headers.setdefault("Accept-Ranges", "bytes")
        response.headers.setdefault("X-Content-Type-Options", "nosniff")
        response.headers["X-YazKlinik-PDF-Archive"] = "db-fallback"
        if not download:
            safe_name = file_name.replace('"', "")
            response.headers["Content-Disposition"] = (
                f'inline; filename="{safe_name}"')
    except Exception:
        pass
    return response


def _ensure_file_archive_schema(con=None):
    def _run(open_con):
        for col, ddl in (
            ("archived_at", "ALTER TABLE files ADD COLUMN archived_at TEXT"),
            ("archived_by", "ALTER TABLE files ADD COLUMN archived_by TEXT"),
            ("archive_reason", "ALTER TABLE files ADD COLUMN archive_reason TEXT"),
        ):
            try:
                cols = {str(r[1]) for r in open_con.execute(
                    "PRAGMA table_info(files)").fetchall()}
                if col not in cols:
                    open_con.execute(ddl)
            except Exception:
                pass
        try:
            open_con.execute(
                "CREATE INDEX IF NOT EXISTS idx_files_active_visit "
                "ON files(patient_folder_key, visit_key, archived_at)")
        except Exception:
            pass

    if con is not None:
        _run(con)
        return
    with db_conn() as open_con:
        _run(open_con)
        open_con.commit()


