def _recount_visit_files(con, patient_key, visit_key):
    _ensure_file_archive_schema(con)
    rows = con.execute(
        "SELECT file_kind, full_path, mtime FROM files "
        "WHERE patient_folder_key=? AND visit_key=? "
        "AND COALESCE(archived_at, '') = ''",
        (patient_key, visit_key)).fetchall()
    records = []
    for row in rows or []:
        try:
            records.append({
                "file_kind": row["file_kind"],
                "full_path": row["full_path"],
                "mtime": row["mtime"],
            })
        except Exception:
            records.append({
                "file_kind": row[0],
                "full_path": row[1],
                "mtime": row[2],
            })
    counts = _nas_sync_counts_from_file_records(records)
    con.execute(
        "UPDATE visits SET file_count=?, image_count=?, video_count=?, "
        "pdf_count=?, latest_pdf_path=? "
        "WHERE patient_folder_key=? AND visit_key=?",
        (int(counts.get("file_count") or 0),
         int(counts.get("image_count") or 0),
         int(counts.get("video_count") or 0),
         int(counts.get("pdf_count") or 0),
         counts.get("latest_pdf_path"),
         patient_key, visit_key))


