# Her 24 saatte bir DB'nin yedeÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ini alÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±r. Son 30 gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼nÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼ tutar,
# eskileri otomatik siler. Server kapanmadÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± sÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼rece ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§alÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±r.

_backup_thread = None
_backup_thread_started = False
_backup_dir_resolved = None  # C18: cache - bir kez cozuldukten sonra tekrar arama
_backup_fallback_warned = False  # C18: tek seferlik uyari


def _get_backup_dir():
    """C18: Yedek klasoru graceful fallback ile. Doktor 'E:\\ surucusu yok'
    sikayet etti - eski kod E:\\USG\\Backup hardcoded fallback kullaniyordu,
    surucu yoksa konsolu [WinError 3] dolduruyordu. Yeni davranis:
    1) get_backup_root() (kullanici ayari) dene; mkdir basariliysa kullan
    2) %LOCALAPPDATA%\\YazKlinik\\Backups
    3) <project_dir>\\auto_backups (kesin yazilabilir, paket ile gelir)
    4) Path.home() / 'YazKlinik' / 'Backups'
    Ilk yazilabilir olani DONDURULUR ve cache edilir; sonraki cagrilarda
    tekrar arama yapilmaz, errors spamlanmaz.
    """
    global _backup_dir_resolved, _backup_fallback_warned
    if _backup_dir_resolved is not None:
        return _backup_dir_resolved

    candidates = []

    # 1) Kullanici ayarladigi yer
    try:
        cfg = get_backup_root()
        if cfg:
            candidates.append((Path(cfg), "settings"))
    except Exception:
        pass

    # 2) %LOCALAPPDATA%\YazKlinik\Backups
    try:
        local_app = os.environ.get("LOCALAPPDATA", "").strip()
        if local_app:
            candidates.append(
                (Path(local_app) / "YazKlinik" / "Backups", "LOCALAPPDATA"))
    except Exception:
        pass

    # 3) Proje klasoru / auto_backups (kesin yazilabilir)
    try:
        project_dir = Path(__file__).resolve().parent
        candidates.append((project_dir / "auto_backups", "project-dir"))
    except Exception:
        pass

    # 4) Home / YazKlinik / Backups
    try:
        candidates.append(
            (Path.home() / "YazKlinik" / "Backups", "home-dir"))
    except Exception:
        pass

    chosen = None
    chosen_source = ""
    failed_candidates = []
    for cand_path, source in candidates:
        try:
            cand_path.mkdir(parents=True, exist_ok=True)
            # Yazma testi - mkdir basarili olsa bile sonra yazma
            # iznimiz olmayabilir.
            test_file = cand_path / ".yk_write_test"
            try:
                test_file.write_text("ok", encoding="utf-8")
                test_file.unlink()
            except Exception:
                failed_candidates.append((cand_path, source, "write_denied"))
                continue
            chosen = cand_path
            chosen_source = source
            break
        except Exception as ex:
            failed_candidates.append((cand_path, source, str(ex)[:50]))

    if chosen is None:
        # Hicbir yer yazilabilir degil - cwd'a son care
        chosen = Path.cwd()
        chosen_source = "cwd-fallback"

    # Tek seferlik uyari - kullanici ayari basarisiz olursa
    if not _backup_fallback_warned and failed_candidates:
        primary_failed = failed_candidates[0]
        if primary_failed[1] == "settings":
            print(
                f"i Otomatik yedek: ayarlardaki yol erisilemiyor "
                f"({primary_failed[0]}); fallback {chosen_source} = {chosen}"
            )
            _backup_fallback_warned = True

    _backup_dir_resolved = chosen
    return chosen


def _do_auto_backup():
    """Tek bir otomatik yedek al."""
    try:
        backup_dir = _get_backup_dir()
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        dest = backup_dir / f"auto_yedek_{timestamp}.sqlite3"
        result = backup_database(dest)
        size_mb = result.get("size_bytes", 0) / 1024 / 1024
        print(f"âœ“ Otomatik yedek alindi: {dest.name} "
              f"({size_mb:.1f} MB, "
              f"{result.get('patient_count', 0)} hasta)")
        # Eski yedekleri temizle (30 gunden eski)
        from datetime import timedelta
        cutoff = datetime.now() - timedelta(days=30)
        deleted = 0
        for old in backup_dir.glob("auto_yedek_*.sqlite3"):
            try:
                if datetime.fromtimestamp(
                        old.stat().st_mtime) < cutoff:
                    old.unlink()
                    deleted += 1
            except Exception:
                pass
        if deleted:
            print(f"âœ“ {deleted} eski yedek temizlendi (>30 gun)")
        return True
    except Exception as ex:
        # C18: Hata mesaji daha temiz - WinError 3 spamlamasin
        msg = str(ex)
        if "WinError 3" in msg or "belirtilen yolu bulamiyor" in msg.lower():
            print(
                "i Otomatik yedek: hedef klasor erisilemiyor - "
                "Ayarlar sayfasindan yedek yolunu kontrol et."
            )
        else:
            print(f"i Otomatik yedek atlandi: {msg[:120]}")
        return False


def _yk_env_float(name, default):
    try:
        value = str(os.environ.get(name, "")).strip()
        if not value:
            return float(default)
        return float(value)
    except Exception:
        return float(default)


def _yk_latest_auto_backup_age_seconds(backup_dir):
    try:
        files = list(Path(backup_dir).glob("auto_yedek_*.sqlite3"))
        if not files:
            return None
        latest = max(files, key=lambda p: p.stat().st_mtime)
        return max(0.0, time.time() - float(latest.stat().st_mtime))
    except Exception:
        return None


def _backup_scheduler_loop():
    """Her 24 saatte bir yedek alan arka plan loop'u."""
    import time as _t
    # Ilk yedek kontrolu hasta ekranini yormasin. Son yedek yeniyse de
    # her restart sonrasi tekrar DB kopyalamayalim.
    initial_delay = _yk_env_float(
        "YAZKLINIK_AUTO_BACKUP_INITIAL_DELAY_SEC", 900)
    interval = _yk_env_float("YAZKLINIK_AUTO_BACKUP_INTERVAL_SEC", 24 * 60 * 60)
    min_age = _yk_env_float("YAZKLINIK_AUTO_BACKUP_MIN_AGE_SEC", 20 * 60 * 60)
    _t.sleep(max(30.0, initial_delay))
    while True:
        try:
            backup_dir = _get_backup_dir()
            age = _yk_latest_auto_backup_age_seconds(backup_dir)
            if age is not None and age < min_age:
                hours = age / 3600.0
                print(f"i Otomatik yedek atlandi: son yedek {hours:.1f} saat once alindi.")
            else:
                _do_auto_backup()
        except Exception as ex:
            print(f"ÃƒÂ¢Ã…Â¡ Backup loop: {ex}")
        # 24 saat bekle
        _t.sleep(max(60.0, interval))


def _start_backup_thread():
    """Backup thread'i bir kere baÅŸlat."""
    global _backup_thread, _backup_thread_started
    if _backup_thread_started:
        return
    try:
        import threading
        _backup_thread = threading.Thread(
            target=_backup_scheduler_loop,
            daemon=True, name="AutoBackup")
        _backup_thread.start()
        _backup_thread_started = True
        print("Otomatik yedekleme aktif (24 saatte bir)")
    except Exception as ex:
        print(f"ÃƒÂ¢Ã…Â¡ Backup thread: {ex}")


# Thread'i baÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸lat
_start_backup_thread()


