def can(permission: str) -> bool:
    """KullanÄ±cÄ± bu izne sahip mi?"""
    role = session.get("role", "")
    perms = PERMISSIONS.get(role, set())
    return "all" in perms or permission in perms


def _safe_next_url(value=None, fallback=None, forbid_current=True):
    """Return an internal relative redirect target, never a looping URL."""
    fallback = fallback or url_for("home")
    text = str(value or "").strip()
    if not text or len(text) > 2048:
        return fallback
    try:
        parts = urlsplit(text)
        if parts.scheme or parts.netloc:
            host = (parts.hostname or "").lower()
            current_host = (request.host or "").split(":", 1)[0].lower()
            allowed_hosts = {"localhost", "127.0.0.1", "::1"}
            if current_host:
                allowed_hosts.add(current_host)
            if host and host not in allowed_hosts:
                return fallback
            text = parts.path or fallback
            if parts.query:
                text += f"?{parts.query}"
            if parts.fragment:
                text += f"#{parts.fragment}"
            parts = urlsplit(text)
        if not text.startswith("/") or text.startswith("//"):
            return fallback
        path = parts.path or "/"
        bad_paths = {
            url_for("login"),
            url_for("logout"),
            "/login",
            "/logout",
        }
        if path in bad_paths:
            return fallback
        if forbid_current and path == request.path:
            return fallback
        return text
    except Exception:
        return fallback


def login_required(f):
    """Sayfa decorator: giriÅŸsiz eriÅŸim engellenir."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        if not session.get("user"):
            return redirect(url_for("login",
                                      next=_safe_next_url(
                                          request.url,
                                          fallback=url_for("home"),
                                          forbid_current=False)))
        return f(*args, **kwargs)
    return wrapper


# =====================================================================
# Entegrasyon kasasi (BulutKlinik / e-Nabiz / kredansiyel duzenleme)
# Hassas API anahtarlarini ve hasta PDF'ini koruyan ek admin sifresi
# kapisi. Doktor zaten loginli, ama bu sayfalar ek bir password
# challenge ister (30 dk gecerli session flag).
# =====================================================================

INTEGRATION_UNLOCK_TTL_SEC = 30 * 60


def _integration_unlock_state():
    try:
        ts = float(session.get("integrations_unlocked_at") or 0)
    except Exception:
        ts = 0.0
    if ts <= 0:
        return {"unlocked": False, "expires_in": 0}
    elapsed = time.time() - ts
    if elapsed > INTEGRATION_UNLOCK_TTL_SEC:
        return {"unlocked": False, "expires_in": 0}
    return {"unlocked": True,
            "expires_in": int(INTEGRATION_UNLOCK_TTL_SEC - elapsed)}


def _integration_unlock_form_html(next_url=""):
    """Sifre prompt'u: doktor giris sifresini sorar, dogru ise
    integrations_unlocked_at = now seti yapar (30 dk gecerli)."""
    nxt = sh(next_url or request.path)
    return f"""
    <div class="container py-5" style="max-width:520px">
      <div class="card shadow-sm">
        <div class="card-body p-4">
          <h3 class="mb-2">
            <i class="bi bi-shield-lock"></i> Entegrasyon Kasasi
          </h3>
          <p class="text-muted small mb-3">
            BulutKlinik / e-Nabiz sayfalari hasta verisini ve API anahtari
            duzenlemeyi icerir. Devam etmek icin <b>kullanici sifrenizi</b>
            tekrar girin (30 dk gecerli).
          </p>
          <form method="POST" action="/entegrasyonlar/unlock">
            <input type="hidden" name="next" value="{nxt}">
            <div class="mb-3">
              <label class="form-label">Kullanici</label>
              <input type="text" class="form-control" readonly
                     value="{sh(session.get('user') or 'doktor')}">
            </div>
            <div class="mb-3">
              <label class="form-label">Sifre</label>
              <input type="password" name="password" class="form-control"
                     autocomplete="current-password" required autofocus>
            </div>
            <button type="submit" class="btn btn-primary w-100">
              <i class="bi bi-unlock-fill"></i> Kasayi Ac
            </button>
          </form>
          <p class="text-muted small mt-3 mb-0">
            Cikis yaptiginda otomatik kilitlenir.
            Bu sayfa <code>web_audit_log</code>'a kaydedilir (KVKK denetim izi).
          </p>
        </div>
      </div>
    </div>
    """


def integration_unlock_required(f):
    """Login + integration-unlock zorunlu decorator.
    Varsayilan: kasa KAPALI (login yeterli) - kullanici 'sorunsuz entegre'
    icin kasayi devre disi tuttu. Etkinlestirmek icin DB'de
    sysparam_integrations_kasa=1 yap."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        if not session.get("user"):
            return redirect(url_for("login",
                                      next=_safe_next_url(
                                          request.url,
                                          fallback=url_for("home"),
                                          forbid_current=False)))
        # Kasa flag'i DB'de '1' ise devreye gir (varsayilan kapali)
        try:
            kasa_on = str(_db_get_setting(
                "sysparam_integrations_kasa", "0") or "0").strip().lower()
            kasa_on = kasa_on in {"1", "true", "yes", "on"}
        except Exception:
            kasa_on = False
        if kasa_on:
            state = _integration_unlock_state()
            if not state["unlocked"]:
                return render(
                    _integration_unlock_form_html(request.full_path),
                    title="Entegrasyon Kasasi")
        return f(*args, **kwargs)
    return wrapper


@app.route("/entegrasyonlar/unlock", methods=["POST"])
@login_required
def integration_unlock_post():
    password = (request.form.get("password") or "").strip()
    next_url = _safe_next_url(request.form.get("next") or "/bulutklinik",
                              fallback="/bulutklinik",
                              forbid_current=False)
    user = USERS.get(session.get("user") or "")
    if not user or user.get("password") != password:
        try:
            _log_audit("integrations:unlock_fail",
                       entity_type="session",
                       details=f"user={session.get('user')}")
        except Exception:
            pass
        flash("Sifre dogrulanamadi. Tekrar deneyin.", "danger")
        return redirect(next_url or "/bulutklinik")
    session["integrations_unlocked_at"] = time.time()
    try:
        _log_audit("integrations:unlock_ok",
                   entity_type="session",
                   details=f"ttl={INTEGRATION_UNLOCK_TTL_SEC}s")
    except Exception:
        pass
    flash("Entegrasyon kasasi acildi (30 dk).", "success")
    return redirect(next_url or "/bulutklinik")


