def _ollama_recommended_model_for_task(task, models=None):
    task = _ollama_task_from_context(task)
    installed = [str(m).strip() for m in (models or _ollama_models()) if str(m).strip()]
    by_lower = {m.lower(): m for m in installed}
    for wanted in _OLLAMA_RECOMMENDED_TASK_PREFS.get(task, []):
        normalized = _normalize_ollama_model_name(wanted)
        if normalized.lower() in by_lower:
            return by_lower[normalized.lower()]
    if task == "vision":
        vision_models = [m for m in installed if _is_ollama_vision_model(m)]
        if vision_models:
            return sorted(
                vision_models,
                key=lambda m: (_vision_model_priority_score(m), str(m).lower()),
                reverse=True,
            )[0]
        return _OLLAMA_RECOMMENDED_TASK_PREFS[task][0]
    return _best_ollama_text_model(task, models=installed) or DEFAULT_OLLAMA_MODEL


def _ollama_task_recommendation_rows(force=False):
    models = _ollama_models(force=force)
    rows = []
    for task, label, icon in _OLLAMA_TASK_DEFINITIONS:
        model = _ollama_recommended_model_for_task(task, models=models)
        setting = (
            "sysparam_ollama_vision_model"
            if task == "vision" else _ollama_task_setting_key(task)
        )
        rows.append({
            "task": task,
            "label": label,
            "icon": icon,
            "model": model,
            "setting": setting,
            "installed": model in models,
        })
    return rows


def _apply_ollama_task_recommendations(force=False):
    applied = []
    for row in _ollama_task_recommendation_rows(force=True):
        current = _db_get_setting(row["setting"], "")
        if force or not current or _is_auto_model_value(current):
            _db_set_setting(row["setting"], row["model"] or "auto")
            applied.append(row)
    if not _db_get_setting("sysparam_ollama_model_mode", ""):
        _db_set_setting("sysparam_ollama_model_mode", "auto")
    _refresh_ai_config()
    return applied


OLLAMA_SPEED_PROFILE_VERSION = "D300_RTX5090_OPTIMAL_20260515"


def _apply_ollama_speed_profile(force=False):
    current_profile = _db_get_setting("sysparam_ollama_speed_profile_version", "")
    should_apply = force or current_profile != OLLAMA_SPEED_PROFILE_VERSION
    if not should_apply:
        return []
    _db_set_setting("sysparam_ollama_model", DEFAULT_OLLAMA_MODEL)
    _db_set_setting("sysparam_ollama_model_mode", "auto")
    _db_set_setting("sysparam_ollama_keep_alive", "30m")
    _db_set_setting("sysparam_ollama_timeout", "75")
    _db_set_setting("sysparam_whisper_prefer_local", "1")
    if not _db_get_setting("sysparam_whisper_local_model", ""):
        _db_set_setting("sysparam_whisper_local_model", "base")
    applied = _apply_ollama_task_recommendations(force=True)
    _db_set_setting("sysparam_ollama_speed_profile_version",
                    OLLAMA_SPEED_PROFILE_VERSION)
    _refresh_ai_config()
    return applied


