DEFAULT_BULUTKLINIK_PORTAL_URL = "https://app.bulutklinik.com/App/My/favorites.gg"
DEFAULT_ENABIZ_DOCTOR_PORTAL_URL = "https://mbys2.saglik.gov.tr/"


def _portal_host_allowed(host, allowed_hosts):
    host = str(host or "").strip().lower()
    if not host:
        return False
    for allowed in allowed_hosts:
        allowed = str(allowed or "").strip().lower()
        if host == allowed or host.endswith("." + allowed):
            return True
    return False


def _normalize_portal_url(value, default_url, allowed_hosts):
    raw = str(value or "").strip()
    if not raw:
        raw = str(default_url or "").strip()
    if raw and not re.match(r"^https?://", raw, flags=re.I):
        raw = "https://" + raw.lstrip("/")
    try:
        parsed = urlsplit(raw)
        if parsed.scheme.lower() not in {"http", "https"}:
            return str(default_url or "").strip()
        if not _portal_host_allowed(parsed.hostname, allowed_hosts):
            return str(default_url or "").strip()
        return raw
    except Exception:
        return str(default_url or "").strip()


def _mask_portal_url(value):
    text = str(value or "")
    if not text:
        return ""
    text = re.sub(r"(?i)(token=)[^&#]+", r"\1***", text)
    text = re.sub(r"(?i)(access_token=)[^&#]+", r"\1***", text)
    text = re.sub(r"(?i)(code=)[^&#]+", r"\1***", text)
    return text


def _integration_portal_url(kind):
    kind = str(kind or "").strip().lower()
    if kind == "bulutklinik":
        key = "sysparam_bulutklinik_portal_url"
        env = "YAZKLINIK_BULUTKLINIK_PORTAL_URL"
        default = DEFAULT_BULUTKLINIK_PORTAL_URL
        hosts = ("bulutklinik.com",)
    elif kind == "enabiz":
        key = "sysparam_enabiz_doctor_portal_url"
        env = "YAZKLINIK_ENABIZ_DOCTOR_PORTAL_URL"
        default = DEFAULT_ENABIZ_DOCTOR_PORTAL_URL
        hosts = ("enabiz.gov.tr", "mbys2.saglik.gov.tr", "saglik.gov.tr")
    else:
        return ""
    saved = _db_get_setting(key, "").strip()
    raw = saved or os.environ.get(env) or default
    if kind == "enabiz":
        legacy = "https://enabiz.gov.tr/DoktorErisim/home/KisiDogrula"
        try:
            raw_host = (urlsplit(str(raw or "")).hostname or "").lower()
        except Exception:
            raw_host = ""
        if (str(raw or "").strip().rstrip("/") == legacy.rstrip("/")
                or raw_host == "enabiz.gov.tr"):
            raw = default
    return _normalize_portal_url(raw, default, hosts)


def _save_integration_portal_url(kind, value):
    kind = str(kind or "").strip().lower()
    if kind == "bulutklinik":
        key = "sysparam_bulutklinik_portal_url"
        default = DEFAULT_BULUTKLINIK_PORTAL_URL
        hosts = ("bulutklinik.com",)
    elif kind == "enabiz":
        key = "sysparam_enabiz_doctor_portal_url"
        default = DEFAULT_ENABIZ_DOCTOR_PORTAL_URL
        hosts = ("enabiz.gov.tr", "mbys2.saglik.gov.tr", "saglik.gov.tr")
    else:
        raise ValueError("Bilinmeyen portal")
    url = _normalize_portal_url(value, default, hosts)
    if not url or url == default and str(value or "").strip() and str(value).strip() != default:
        raise ValueError("Portal URL alan adi beklenen sistemle uyusmuyor.")
    _db_set_setting(key, url)
    return url


