def _merge_patients_dry_run(source_key, target_key):
    """Hangi tablolardan kac satir tasinacak - sayim, gercek tasima yok."""
    summary = {"source": source_key, "target": target_key, "tables": {}, "total": 0}
    if source_key == target_key:
        return summary
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: row[0]
            for tname, col in _MERGE_FK_TABLES:
                try:
                    n = con.execute(
                        f"SELECT COUNT(*) FROM {tname} WHERE {col}=?",
                        (source_key,)).fetchone()
                    if n and int(n) > 0:
                        summary["tables"][tname] = int(n)
                        summary["total"] += int(n)
                except Exception:
                    continue
            # Source patient kaydi var mi
            try:
                src_exists = con.execute(
                    "SELECT 1 FROM patients WHERE folder_key=? LIMIT 1",
                    (source_key,)).fetchone()
                summary["source_exists"] = bool(src_exists)
            except Exception:
                summary["source_exists"] = False
            try:
                tgt_exists = con.execute(
                    "SELECT 1 FROM patients WHERE folder_key=? LIMIT 1",
                    (target_key,)).fetchone()
                summary["target_exists"] = bool(tgt_exists)
            except Exception:
                summary["target_exists"] = False
            # Source protokol no
            try:
                spn = con.execute(
                    "SELECT protocol_no FROM patient_protocols WHERE patient_key=?",
                    (source_key,)).fetchone()
                summary["source_protocol_no"] = str(spn) if spn else ""
            except Exception:
                summary["source_protocol_no"] = ""
            try:
                tpn = con.execute(
                    "SELECT protocol_no FROM patient_protocols WHERE patient_key=?",
                    (target_key,)).fetchone()
                summary["target_protocol_no"] = str(tpn) if tpn else ""
            except Exception:
                summary["target_protocol_no"] = ""
    except Exception as ex:
        summary["error"] = str(ex)
    return summary


def _merge_patients_execute(source_key, target_key, *, reason=""):
    """Source -> target tum FK guncelle, source patient'i arsivle.

    Returns: {"ok": bool, "moved": {table: rows}, "error": str?}.
    Single transaction; hata olursa rollback yapar.
    Klasor (filesystem) tasiyici DEGIL - sadece DB."""
    if not source_key or not target_key:
        return {"ok": False, "error": "source/target key bos olamaz"}
    if source_key == target_key:
        return {"ok": False, "error": "source ve target ayni hasta"}
    moved = {}
    try:
        with db_conn() as con:
            # Validate
            sr = con.execute(
                "SELECT folder_key FROM patients WHERE folder_key=?",
                (source_key,)).fetchone()
            tr = con.execute(
                "SELECT folder_key FROM patients WHERE folder_key=?",
                (target_key,)).fetchone()
            if not sr:
                return {"ok": False, "error": f"source bulunamadi: {source_key}"}
            if not tr:
                return {"ok": False, "error": f"target bulunamadi: {target_key}"}

            # 1) Bulk UPDATE all FK tables
            for tname, col in _MERGE_FK_TABLES:
                try:
                    cur = con.execute(
                        f"UPDATE {tname} SET {col}=? WHERE {col}=?",
                        (target_key, source_key))
                    if cur.rowcount > 0:
                        moved[tname] = cur.rowcount
                except Exception:
                    continue

            # 2) patient_protocols: source row varsa archive et (sil yerine)
            try:
                src_proto = con.execute(
                    "SELECT protocol_no FROM patient_protocols WHERE patient_key=?",
                    (source_key,)).fetchone()
                if src_proto:
                    src_proto_no = src_proto[0]
                    # patient_protocols PK = patient_key, target zaten kaydi var.
                    # Source protokolunu silelim ki conflict olmasin.
                    con.execute(
                        "DELETE FROM patient_protocols WHERE patient_key=?",
                        (source_key,))
                    moved["patient_protocols_deleted"] = 1
                    # Notu visit_notes veya patient_relations tablosuna ekle
                    # (alias kayit) - basitce target'in patient_protocols satirinin
                    # bir notu bos ise oraya yaz
                    try:
                        con.execute("""
                          INSERT INTO patient_relations
                            (patient_key, related_patient_key, relation, notes, created_at)
                          VALUES (?, ?, 'merged_from', ?, datetime('now'))
                        """, (target_key, source_key,
                              f"Eski protokol no: {src_proto_no}"))
                    except Exception:
                        pass
            except Exception:
                pass

            # 3) patient_demographics: source row varsa target'a merge
            try:
                src_demo = con.execute(
                    "SELECT data_json, lmp_override FROM patient_demographics "
                    "WHERE patient_key=?", (source_key,)).fetchone()
                tgt_demo = con.execute(
                    "SELECT data_json, lmp_override FROM patient_demographics "
                    "WHERE patient_key=?", (target_key,)).fetchone()
                if src_demo:
                    if not tgt_demo:
                        # Target'ta demo yok - source'u rename
                        con.execute(
                            "UPDATE patient_demographics SET patient_key=? "
                            "WHERE patient_key=?",
                            (target_key, source_key))
                        moved["patient_demographics"] = 1
                    else:
                        # Hem source hem target var - source data'yi notuna
                        # ekle, source row'unu sil
                        merged_note = (
                            f"Birlesim: {source_key} kaynaktan; "
                            f"lmp_override={src_demo[1] or '-'}")
                        try:
                            cur_dj = tgt_demo[0] or "{}"
                            con.execute(
                                "UPDATE patient_demographics SET "
                                "data_json = ? "
                                "WHERE patient_key=?",
                                (cur_dj + " | " + merged_note, target_key))
                        except Exception:
                            pass
                        con.execute(
                            "DELETE FROM patient_demographics WHERE patient_key=?",
                            (source_key,))
                        moved["patient_demographics_merged"] = 1
            except Exception:
                pass

            # 4) Source patient kaydini arsivle (silmiyoruz - geri al imkani)
            try:
                con.execute(
                    "UPDATE patients SET archived_at=datetime('now'), "
                    "display_name = COALESCE(display_name,'') || ' [BIRLESIRILDI -> "
                    + str(target_key) + "]' "
                    "WHERE folder_key=?",
                    (source_key,))
                moved["patients_archived"] = 1
            except Exception:
                pass

            # 5) Audit log
            try:
                user = str(session.get("username") or "system") if "session" in globals() else "system"
                con.execute("""
                  INSERT INTO web_audit_log
                    (patient_key, user, action, details, created_at)
                  VALUES (?, ?, 'merge_patient', ?, datetime('now'))
                """, (target_key, user,
                      f"source={source_key} reason={reason or 'manuel'}"))
            except Exception:
                pass

            con.commit()
        # Cache temizle - hasta listesi yenilensin
        try:
            for k in list(_PERF_CACHE.keys()):
                if "patient" in str(k).lower() or "ga_quick" in str(k).lower():
                    _PERF_CACHE.pop(k, None)
        except Exception:
            pass
        return {"ok": True, "moved": moved, "source": source_key, "target": target_key}
    except Exception as ex:
        return {"ok": False, "error": str(ex), "moved": moved}


@app.route("/api/hasta-birlestir-onizleme", methods=["POST"])
@login_required
def api_hasta_birlestir_onizleme():
    """Birlesim onizlemesi: kac satir hangi tablodan tasinacak."""
    if str(session.get("role") or "") != "doktor":
        return jsonify({"ok": False, "error": "Sadece doktor"}), 403
    body = request.get_json(silent=True) or {}
    src = str(body.get("source_key") or request.form.get("source_key") or "").strip()
    tgt = str(body.get("target_key") or request.form.get("target_key") or "").strip()
    if not src or not tgt:
        return jsonify({"ok": False, "error": "source_key ve target_key gerekli"})
    summary = _merge_patients_dry_run(src, tgt)
    return jsonify({"ok": True, **summary})


@app.route("/api/hasta-birlestir", methods=["POST"])
@login_required
def api_hasta_birlestir():
    """Iki hastayi tek hastada birlestir: source -> target."""
    if str(session.get("role") or "") != "doktor":
        return jsonify({"ok": False, "error": "Sadece doktor"}), 403
    body = request.get_json(silent=True) or {}
    src = str(body.get("source_key") or request.form.get("source_key") or "").strip()
    tgt = str(body.get("target_key") or request.form.get("target_key") or "").strip()
    reason = str(body.get("reason") or request.form.get("reason") or "").strip()
    if not src or not tgt:
        return jsonify({"ok": False, "error": "source_key ve target_key gerekli"})
    if src == tgt:
        return jsonify({"ok": False, "error": "Ayni hasta secildi"})
    result = _merge_patients_execute(src, tgt, reason=reason)
    if not result.get("ok"):
        return jsonify(result), 400
    return jsonify(result)


