@login_required
def ui_visit_pdf_sil(patient_key, visit_key, file_name):
    if str(session.get("role") or "") != "doktor":
        flash("Sadece doktor PDF silebilir.", "danger")
        return redirect(url_for("visit_files", patient_key=patient_key, visit_key=visit_key))
    safe_name = _safe_media_route_part(file_name)
    if not safe_name or "/" in safe_name or _file_kind_for_path(safe_name) != "pdf":
        flash("PDF bulunamadi.", "danger")
        return redirect(url_for("visit_files", patient_key=patient_key, visit_key=visit_key))

    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    user = session.get("user", "?")
    reason = str(request.form.get("reason") or "PDF listeden kaldirildi").strip()[:500]
    file_path = None
    rel_path = ""
    try:
        try:
            file_path, _kind = _resolve_visit_media_path(patient_key, visit_key, safe_name)
        except Exception:
            file_path = _visit_folder_from_db(patient_key, visit_key) / safe_name
        try:
            rel_path = Path(file_path).resolve().relative_to(
                _patient_root_for_nas(patient_key).resolve()).as_posix()
        except Exception:
            rel_path = f"{visit_key}/{safe_name}"
        try:
            if file_path and Path(file_path).exists():
                _archive_patient_pdf_file(
                    patient_key, visit_key, file_path,
                    source="pdf-delete-before-hide", con=None)
        except Exception:
            pass

        with db_conn() as con:
            _ensure_file_archive_schema(con)
            _ensure_patient_pdf_archive_schema(con)
            row = con.execute(
                "SELECT rowid FROM files WHERE patient_folder_key=? "
                "AND visit_key=? AND file_name=? LIMIT 1",
                (patient_key, visit_key, safe_name)).fetchone()
            if row:
                con.execute(
                    "UPDATE files SET archived_at=?, archived_by=?, "
                    "archive_reason=?, last_synced_at=? "
                    "WHERE patient_folder_key=? AND visit_key=? AND file_name=?",
                    (now, user, reason, now, patient_key, visit_key, safe_name))
            else:
                full_path = str(file_path or "")
                try:
                    stat = Path(full_path).stat()
                    size_bytes = int(stat.st_size or 0)
                    mtime = float(stat.st_mtime or 0)
                except Exception:
                    size_bytes = 0
                    mtime = 0
                con.execute(
                    "INSERT INTO files(patient_folder_key, visit_key, file_name, "
                    "full_path, file_kind, size_bytes, mtime, first_seen_at, "
                    "last_synced_at, archived_at, archived_by, archive_reason) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                    (patient_key, visit_key, safe_name, full_path, "pdf",
                     size_bytes, mtime, now, now, now, user, reason))
            con.execute(
                "UPDATE patient_pdf_archive SET deleted_at=?, deleted_by=?, "
                "delete_reason=? WHERE patient_key=? "
                "AND COALESCE(deleted_at, '') = '' "
                "AND (file_name=? OR rel_path=? OR (visit_key=? AND file_name=?))",
                (now, user, reason, patient_key,
                 safe_name, rel_path, visit_key, safe_name))
            _recount_visit_files(con, patient_key, visit_key)
            con.commit()
        try:
            _log_audit("visit_pdf_archive", entity_type="file",
                       entity_id=safe_name, patient_key=patient_key,
                       details=f"visit={visit_key}")
        except Exception:
            pass
        try:
            _invalidate_patient_web_cache(patient_key, visit_key)
        except Exception:
            pass
        flash("PDF listeden kaldirildi. Dosya silinmedi; arsiv kopyasi korundu.", "success")
    except Exception as ex:
        flash(f"PDF silinemedi: {ex}", "danger")

    fallback = url_for("visit_files", patient_key=patient_key, visit_key=visit_key)
    next_url = _safe_next_url(
        request.form.get("next") or request.referrer or fallback,
        fallback=fallback,
        forbid_current=False)
    return redirect(next_url or fallback)


