def permission_required(perm):
    """Rol bazlÄ± yetki kontrolÃ¼."""
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            if not session.get("user"):
                return redirect(url_for("login",
                                          next=_safe_next_url(
                                              request.url,
                                              fallback=url_for("home"),
                                              forbid_current=False)))
            if not can(perm):
                flash(
                    f"âŒ Bu iÅŸlem iÃ§in yetkiniz yok. "
                    f"Mevcut rol: {session.get('role')}",
                    "danger")
                return redirect(url_for("home"))
            return f(*args, **kwargs)
        return wrapper
    return decorator


def get_nas_root() -> Path:
    env_root = (os.environ.get("YAZKLINIK_NAS_ROOT")
                or os.environ.get("YAZKLINIK_ROOT_FOLDER") or "").strip()
    if env_root:
        return Path(env_root).expanduser()
    for key in ("path_nas_root", "nas/path"):
        try:
            path = _db_get_setting(key, "")
            if path:
                return Path(path)
        except Exception:
            pass
    try:
        s = QSettings("YazKlinik", "yazklinik")
        path = s.value("nas/path", "")
        if path:
            return Path(path)
    except Exception:
        pass
    if sys.platform == "darwin":
        return Path("/Volumes/nas/Hastalar")
    return Path(r"\\Sam\usg\Hastalar")


_SETTINGS_VALUE_CACHE = {}
_SETTINGS_VALUE_CACHE_LOCK = threading.Lock()
_SETTINGS_VALUE_CACHE_TTL = 12.0


def _setting_cache_get_raw(key: str):
    now = time.time()
    with _SETTINGS_VALUE_CACHE_LOCK:
        item = _SETTINGS_VALUE_CACHE.get(key)
        if not item:
            return False, None
        ts, value = item
        if now - float(ts or 0.0) >= _SETTINGS_VALUE_CACHE_TTL:
            _SETTINGS_VALUE_CACHE.pop(key, None)
            return False, None
        return True, value


def _setting_cache_put_raw(key: str, value):
    with _SETTINGS_VALUE_CACHE_LOCK:
        _SETTINGS_VALUE_CACHE[key] = (time.time(), value)


def _setting_cache_invalidate(key: str = ""):
    with _SETTINGS_VALUE_CACHE_LOCK:
        if key:
            _SETTINGS_VALUE_CACHE.pop(key, None)
        else:
            _SETTINGS_VALUE_CACHE.clear()


def _db_get_setting(key: str, default: str = "") -> str:
    hit, cached_value = _setting_cache_get_raw(key)
    if hit:
        return str(cached_value) if cached_value not in (None, "") else default
    try:
        with db_conn() as con:
            con.execute(
                "CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)")
            row = con.execute(
                "SELECT value FROM settings WHERE key=?", (key,)).fetchone()
            value = str(row[0]).strip() if row and row[0] not in (None, "") else ""
            _setting_cache_put_raw(key, value)
            return value or default
    except Exception:
        return default


def _db_set_setting(key: str, value: str) -> None:
    with db_conn() as con:
        con.execute(
            "CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)")
        con.execute(
            "INSERT OR REPLACE INTO settings(key, value) VALUES(?, ?)",
            (key, value))
        con.commit()
    _setting_cache_put_raw(key, str(value or "").strip())


def _print_setting(key: str, default: str = "") -> str:
    return str(_db_get_setting(key, default) or default)


def _normalize_print_settings(raw=None):
    raw = raw or {}
    paper_values = {"A4", "A5", "A3", "LETTER", "PHOTO_6X8"}
    paper = str(raw.get("paper") or _print_setting("print.paper", "A4")).upper()
    if paper not in paper_values:
        paper = "A4"
    try:
        margin = int(float(raw.get("margin_mm")
                           or _print_setting("print.margin_mm", "10") or 10))
    except Exception:
        margin = 10
    margin = max(0, min(30, margin))
    orientation = str(raw.get("orientation")
                      or _print_setting("print.orientation", "portrait")).lower()
    if orientation not in {"portrait", "landscape"}:
        orientation = "portrait"
    scale_mode = str(raw.get("scale_mode")
                     or _print_setting("print.scale_mode", "fit")).lower()
    if scale_mode not in {"fit", "fill", "actual"}:
        scale_mode = "fit"
    color_mode = str(raw.get("color_mode")
                     or _print_setting("print.color_mode", "color")).lower()
    if color_mode not in {"color", "grayscale"}:
        color_mode = "color"
    try:
        copies = int(float(raw.get("copies")
                           or _print_setting("print.copies", "1") or 1))
    except Exception:
        copies = 1
    copies = max(1, min(9, copies))
    show_dialog = "1" if str(raw.get("show_dialog")
                             or _print_setting("print.show_dialog", "1")) == "1" else "0"
    printer_name = str(raw.get("printer_name")
                       or _print_setting("print.printer_name", "") or "").strip()
    return {
        "paper": paper,
        "margin_mm": str(margin),
        "orientation": orientation,
        "scale_mode": scale_mode,
        "color_mode": color_mode,
        "copies": str(copies),
        "show_dialog": show_dialog,
        "printer_name": printer_name,
    }


# B305: _available_printers() bazi sistemlerde 5-30 sn surebilir (Win32 print
# enumeration + PowerShell fallback). Sayfa her acilista bunu cagirinca
# YazÄ±cÄ± AyarlarÄ± sayfasi DONUYOR. Cache: 5 dk taze sonuc + force refresh
# parametresi.
_B305_PRINTERS_CACHE = {"ts": 0.0, "data": None}
_B305_PRINTERS_TTL = 300  # 5 dakika


def _available_printers(force=False):
    import time as _t
    now = _t.time()
    cached = _B305_PRINTERS_CACHE.get("data")
    if (not force) and cached is not None and (now - float(_B305_PRINTERS_CACHE.get("ts", 0))) < _B305_PRINTERS_TTL:
        return cached
    result = _b305_compute_available_printers()
    _B305_PRINTERS_CACHE["ts"] = now
    _B305_PRINTERS_CACHE["data"] = result
    return result


def _b305_compute_available_printers():
    result = {"printers": [], "default": "", "error": ""}
    if os.name != "nt":
        return result
    try:
        import win32print  # type: ignore
        flags = win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS
        default = ""
        try:
            default = win32print.GetDefaultPrinter()
        except Exception:
            default = ""
        rows = []
        for item in win32print.EnumPrinters(flags):
            name = str(item[2] if len(item) > 2 else "").strip()
            if name:
                rows.append({
                    "name": name,
                    "driver": str(item[1] if len(item) > 1 else ""),
                    "port": str(item[3] if len(item) > 3 else ""),
                    "default": name == default,
                })
        result["printers"] = rows
        result["default"] = default
        return result
    except Exception as ex:
        result["error"] = str(ex)
    try:
        ps = (
            "$ErrorActionPreference='Stop';"
            "Get-Printer | Select-Object Name,DriverName,PortName,"
            "@{n='Default';e={$_.Name -eq (Get-CimInstance Win32_Printer "
            "-Filter \"Default=True\" | Select-Object -First 1 -ExpandProperty Name)}} "
            "| ConvertTo-Json -Compress"
        )
        proc = subprocess.run(
            ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass",
             "-Command", ps],
            capture_output=True, text=True, timeout=5)
        if proc.returncode != 0:
            raise RuntimeError((proc.stderr or proc.stdout or "").strip())
        data = json.loads(proc.stdout or "[]")
        if isinstance(data, dict):
            data = [data]
        rows = []
        default = ""
        for item in data if isinstance(data, list) else []:
            name = str(item.get("Name") or "").strip()
            if not name:
                continue
            is_default = bool(item.get("Default"))
            if is_default:
                default = name
            rows.append({
                "name": name,
                "driver": str(item.get("DriverName") or ""),
                "port": str(item.get("PortName") or ""),
                "default": is_default,
            })
        result["printers"] = rows
        result["default"] = default
        if rows:
            result["error"] = ""
    except Exception as ex:
        if not result["error"]:
            result["error"] = str(ex)
    return result


# B306: B305 pre-warm thread'i kaldirildi - server start'inda CPU yuku
# yaratiyordu (doktor 'menu gecisleri yavasladi' sikayet etti). 5dk cache
# zaten ilk sayfa acilista doldurulur.


def _preferred_photo_printer_name():
    saved = _print_setting("print.photo_printer_name", "").strip()
    if saved:
        return saved
    printers = _available_printers().get("printers", [])
    for printer in printers:
        name = str(printer.get("name") or "").strip()
        folded = _fold_search_text(name)
        if "hiti" in folded and ("525" in folded or "p525" in folded or "525l" in folded):
            return name
    for printer in printers:
        name = str(printer.get("name") or "").strip()
        if "hiti" in _fold_search_text(name):
            return name
    return ""


def _open_hiti_525l_printer_panel():
    if os.name != "nt":
        return False, "HiTi 525L paneli sadece Windows uzerinde acilir.", ""
    printer_name = _preferred_photo_printer_name()
    if not printer_name:
        return False, "HiTi 525L Windows yazici listesinde bulunamadi.", ""
    commands = [
        ["rundll32", "printui.dll,PrintUIEntry", "/e", "/n", printer_name],
        ["rundll32", "printui.dll,PrintUIEntry", "/p", "/n", printer_name],
        ["control", "printers"],
    ]
    last_error = ""
    for cmd in commands:
        try:
            subprocess.Popen(cmd, shell=False)
            return True, f"{printer_name} paneli acildi. 6x8 foto baski secimini onaylayin.", printer_name
        except Exception as ex:
            last_error = str(ex)
    return False, last_error or "HiTi 525L paneli acilamadi.", printer_name


def _open_windows_printer_settings():
    if os.name != "nt":
        return False, "Bu islem sadece Windows server uzerinde acilir."
    commands = [
        ["cmd", "/c", "start", "", "ms-settings:printers"],
        ["control", "printers"],
        ["rundll32", "printui.dll,PrintUIEntry", "/s"],
    ]
    last_error = ""
    for cmd in commands:
        try:
            subprocess.Popen(cmd, shell=False)
            return True, "Windows yazici ayarlari acildi."
        except Exception as ex:
            last_error = str(ex)
    return False, last_error or "Windows yazici ayarlari acilamadi."


def _yk_media_src_parts(src: str):
    parsed = urlsplit(str(src or "").strip())
    path = parsed.path or str(src or "")
    return [unquote(p) for p in path.strip("/").split("/") if p]


def _yk_patient_key_from_media_src(src: str) -> str:
    parts = _yk_media_src_parts(src)
    if len(parts) >= 2 and parts[0] == "hasta":
        return parts[1]
    return ""


def _yk_temp_photo_print_path(filename: str = "media.jpg") -> Path:
    stem = re.sub(r"[^A-Za-z0-9_.-]+", "_", Path(filename or "media").stem)[:70]
    if not stem:
        stem = "media"
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    return Path(tempfile.gettempdir()) / f"YazKlinik_PrintPhoto_{stamp}_{stem}.jpg"


def _yk_save_print_jpeg_from_bytes(raw: bytes, filename: str = "media.jpg") -> Path:
    if not raw:
        raise ValueError("Resim verisi bos.")
    out_path = _yk_temp_photo_print_path(filename)
    try:
        from PIL import Image
        img = Image.open(BytesIO(raw))
        if img.mode in ("RGBA", "LA"):
            bg = Image.new("RGB", img.size, "white")
            alpha = img.getchannel("A") if "A" in img.getbands() else None
            bg.paste(img.convert("RGBA"), mask=alpha)
            img = bg
        elif img.mode != "RGB":
            img = img.convert("RGB")
        img.save(out_path, "JPEG", quality=96, subsampling=0)
    except Exception:
        out_path.write_bytes(raw)
    return out_path


def _yk_jpeg_file_for_photo_print(path: Path) -> Path:
    path = Path(path)
    if path.suffix.lower() in {".jpg", ".jpeg"}:
        return path
    try:
        from PIL import Image
        out_path = _yk_temp_photo_print_path(path.name)
        img = Image.open(path)
        if img.mode in ("RGBA", "LA"):
            bg = Image.new("RGB", img.size, "white")
            alpha = img.getchannel("A") if "A" in img.getbands() else None
            bg.paste(img.convert("RGBA"), mask=alpha)
            img = bg
        elif img.mode != "RGB":
            img = img.convert("RGB")
        img.save(out_path, "JPEG", quality=96, subsampling=0)
        return out_path
    except Exception:
        return path


def _yk_resolve_media_source_path_for_print(src: str):
    parts = _yk_media_src_parts(src)
    if len(parts) >= 4 and parts[0] == "hasta":
        patient_key = parts[1]
        route = parts[2]
        if route == "gelis" and len(parts) >= 6 and parts[4] == "dosya":
            return _resolve_visit_media_path(patient_key, parts[3], "/".join(parts[5:]))
        if route == "gelis" and len(parts) >= 6 and parts[4] == "dicom-preview":
            file_path, kind = _resolve_visit_media_path(patient_key, parts[3], "/".join(parts[5:]))
            return file_path, "dicom" if kind == "dicom" else kind
        if route in {"medya-dosya", "dicom-dosya"}:
            file_path = _resolve_patient_relative_media_path(patient_key, "/".join(parts[3:]))
            return file_path, _file_kind_for_path(file_path)
        if route == "nas-dosya":
            _root, file_path, _rel = _resolve_patient_explorer_path(
                patient_key, "/".join(parts[3:]), require_file=True)
            return file_path, _patient_explorer_file_kind(file_path)
        if route == "usg-img" and len(parts) >= 4:
            filename = _safe_media_route_part(parts[3])
            if not filename or "/" in filename:
                raise ValueError("Gecersiz USG resim yolu.")
            file_path = Path(get_data_root_dir()) / patient_key / "usg_goruntuler" / filename
            if not file_path.exists() or not file_path.is_file():
                raise FileNotFoundError(str(file_path))
            return file_path, "image"
        if route == "takip-medya-dosya" and len(parts) >= 4:
            media_id = int(parts[3])
            with db_conn() as con:
                con.row_factory = lambda cur, row: {
                    d[0]: row[i] for i, d in enumerate(cur.description)}
                row = con.execute(
                    "SELECT * FROM patient_media_archive WHERE id=? AND patient_key=?",
                    (media_id, patient_key)).fetchone()
            if not row:
                raise ValueError("Medya arsiv kaydi bulunamadi.")
            roots = []
            if row.get("storage_root"):
                roots.append(Path(str(row.get("storage_root"))))
            roots.extend([_patient_media_root(patient_key), get_nas_root() / patient_key])
            for root in roots:
                candidate = (
                    Path(str(row.get("abs_path") or ""))
                    if row.get("abs_path") else root / str(row.get("rel_path") or "")
                )
                try:
                    candidate.resolve().relative_to(root.resolve())
                except Exception:
                    continue
                if candidate.exists() and candidate.is_file():
                    return candidate, _file_kind_for_path(candidate)
            raise FileNotFoundError("Arsiv resmi diskte bulunamadi.")
    raise ValueError("Bu medya kaynagi JPEG/foto baski icin cozumlenemedi.")


def _yk_materialize_photo_print_file(src: str) -> Path:
    try:
        file_path, kind = _yk_resolve_media_source_path_for_print(src)
        if kind == "image":
            return _yk_jpeg_file_for_photo_print(Path(file_path))
        if kind == "dicom":
            raw, filename, _media_kind = _hd_read_dicom_preview_bytes(file_path)
            return _yk_save_print_jpeg_from_bytes(raw, filename)
    except Exception:
        pass

    parts = _yk_media_src_parts(src)
    if len(parts) >= 3 and parts[0] == "dicom" and parts[1] == "preview":
        raw, filename, _media_kind = _hd_read_orthanc_preview_bytes(parts[2])
        return _yk_save_print_jpeg_from_bytes(raw, filename)

    patient_key = _yk_patient_key_from_media_src(src)
    if patient_key:
        raw, filename, media_kind = _hd_source_bytes_from_url(patient_key, src)
        if media_kind not in {"image", "dicom"}:
            raise ValueError("Kaynak resim degil.")
        return _yk_save_print_jpeg_from_bytes(raw, filename)

    raise ValueError("JPEG/foto baski icin kaynak resim bulunamadi.")


def _yk_photo_print_file_hint(src: str) -> str:
    try:
        file_path, kind = _yk_resolve_media_source_path_for_print(src)
        if kind == "image":
            return str(Path(file_path).resolve())
    except Exception:
        return ""
    return ""


def _yk_absolute_internal_src(src: str) -> str:
    if not src:
        return ""
    if src.startswith(("http://", "https://")):
        return src
    return request.host_url.rstrip("/") + src


@app.route("/yk-media-jpeg")
@login_required
def yk_media_jpeg_file():
    src = str(request.args.get("src", "") or "").strip()
    title = str(request.args.get("title", "YazKlinik Medya") or "YazKlinik Medya")
    if (not src or not src.startswith("/") or src.startswith("//")
            or "\n" in src or "\r" in src):
        abort(400)
    if not (src.startswith("/hasta/") or src.startswith("/yk-")
            or src.startswith("/dicom/preview/")):
        abort(400)
    try:
        image_path = _yk_materialize_photo_print_file(src)
    except Exception:
        abort(404)
    safe_name = re.sub(r"[^A-Za-z0-9_.-]+", "_", title).strip("._")[:90]
    if not safe_name:
        safe_name = Path(image_path).stem or "YazKlinik_Medya"
    if not safe_name.lower().endswith((".jpg", ".jpeg")):
        safe_name += ".jpg"
    return send_file(
        image_path,
        mimetype="image/jpeg",
        download_name=safe_name,
        conditional=True,
    )


def _normalize_desktop_runtime_mode(value: str) -> str:
    mode = (value or "").strip().lower()
    if mode in {"hybrid", "mirror", "shell"}:
        return mode
    return "hybrid"


def _desktop_runtime_mode_paths():
    paths = [Path(__file__).resolve().parent / "desktop_mode.txt"]
    local_app = os.environ.get("LOCALAPPDATA")
    if local_app:
        paths.append(Path(local_app) / "YazKlinik" / "desktop_mode.txt")
    return paths


def _write_desktop_runtime_mode(mode: str) -> str:
    mode = _normalize_desktop_runtime_mode(mode)
    for path in _desktop_runtime_mode_paths():
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(mode, encoding="ascii")
        except Exception:
            pass
    return mode


def _read_desktop_runtime_mode() -> str:
    stored = _db_get_setting("sysparam_desktop_runtime_mode", "")
    if stored:
        return _normalize_desktop_runtime_mode(stored)
    for path in _desktop_runtime_mode_paths():
        try:
            if path.exists():
                text = path.read_text(encoding="ascii", errors="ignore")
                return _normalize_desktop_runtime_mode(text)
        except Exception:
            pass
    return "hybrid"


def _setting_to_bool(value, default=True) -> bool:
    if value is None:
        return bool(default)
    text = str(value).strip().lower()
    if not text:
        return bool(default)
    if text in {"1", "true", "yes", "on", "evet", "acik", "aÃ§ik", "aÃ§Ä±k"}:
        return True
    if text in {"0", "false", "no", "off", "hayir", "hayÄ±r", "kapali", "kapalÄ±"}:
        return False
    return bool(default)


