@app.route("/api/terminal/performance", methods=["GET", "POST"])
def api_terminal_performance():
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401
    ram_profile = _ram_auto_profile()
    gpu_profile = _gpu_auto_profile()
    if request.method == "POST":
        data = request.get_json(silent=True) or {}
        if "media_ram_cache_gb" in data:
            gb = _media_ram_cache_float(
                data.get("media_ram_cache_gb"),
                ram_profile["media_ram_cache_gb"], 0, 180)
            _db_set_setting("sysparam_media_ram_cache_gb", str(gb))
        if "ram_auto_use_available_enabled" in data:
            _db_set_setting(
                "sysparam_ram_auto_use_available_enabled",
                "1" if data.get("ram_auto_use_available_enabled") else "0")
        if "ram_reserve_gb" in data:
            reserve = _media_ram_cache_float(
                data.get("ram_reserve_gb"),
                ram_profile["ram_reserve_gb"], 2, 128)
            _db_set_setting("sysparam_ram_reserve_gb", str(reserve))
        if "program_ram_cache_enabled" in data:
            _db_set_setting(
                "sysparam_program_ram_cache_enabled",
                "1" if data.get("program_ram_cache_enabled") else "0")
        if "program_ram_cache_mb" in data:
            mb = _media_ram_cache_float(
                data.get("program_ram_cache_mb"),
                ram_profile["program_ram_cache_mb"], 16, 4096)
            _db_set_setting("sysparam_program_ram_cache_mb", str(mb))
        if "desktop_runtime_mode" in data:
            mode = _write_desktop_runtime_mode(data.get("desktop_runtime_mode"))
            _db_set_setting("sysparam_desktop_runtime_mode", mode)
        if "gpu_auto_enabled" in data:
            _db_set_setting(
                "sysparam_gpu_auto_enabled",
                "1" if data.get("gpu_auto_enabled") else "0")
            gpu_profile = _gpu_auto_profile(force=True)
        _media_ram_cache_apply_limits(_media_ram_cache_config(force=True))
        _program_ram_cache_apply_limits(_media_ram_cache_config(force=True))
        _program_ram_cache_prewarm_once(force=True)
    return jsonify({
        "ok": True,
        "cache": _media_ram_cache_status(),
        "program_cache": _program_ram_cache_status(),
        "memory": _system_memory_snapshot(),
        "gpu": gpu_profile,
        "whisper": _whisper_runtime_profile(),
        "desktop_runtime_mode": _read_desktop_runtime_mode(),
    })


