@app.route("/yk-vp-clinical.css")
def _yk_vp_clinical_css_asset():
    from flask import Response
    r = Response(_yk_vp_clinical_css(), mimetype="text/css; charset=utf-8")
    r.headers["Cache-Control"] = "public, max-age=604800, immutable"
    return r


_login_attempts = {}


def _get_client_ip():
    """Client IP'si (proxy arkasÄ±nda X-Forwarded-For de destekle)."""
    try:
        return (request.headers.get('X-Forwarded-For',
                                      request.remote_addr)
                or 'unknown')
    except Exception:
        return 'unknown'


@app.route("/giris", methods=["GET", "POST"])
def login():
    ip = _get_client_ip()
    # Bu IP'den kaÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ baÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸arÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±sÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±z deneme var?
    failed = _login_attempts.get(ip, 0)

    if request.method == "POST":
        # Brute-force koruma
        if failed >= 10:
            flash("âš  Ã‡ok fazla hatalÄ± deneme. 5 dakika bekleyin.",
                   "danger")
            return redirect(url_for("login"))

        username = request.form.get("username", "").strip().lower()
        password = request.form.get("password", "")
        remember = request.form.get("remember") == "on"
        user = USERS.get(username)
        if user and user["password"] == password:
            session.permanent = remember  # 8 saat mÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±, 30 dk mÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±
            session["user"] = username
            session["role"] = user["role"]
            session["display_name"] = (
                _doctor_display_name() if user["role"] == "doktor"
                else user["name"]
            )
            session["login_ip"] = ip
            session["login_time"] = datetime.now().isoformat(
                timespec="seconds")
            # BaÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸arÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±lÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± login ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â counter sÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±fÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±rla
            _login_attempts.pop(ip, None)
