@app.route("/istatistikler")
@login_required
def statistics():
    """Klinik istatistikleri - hasta sayÄ±larÄ±, doÄŸum tÃ¼rleri vb."""
    stats = {}
    try:
        with db_conn() as con:
            # Toplam hasta
            stats["total_patients"] = con.execute(
                "SELECT COUNT(*) FROM patients").fetchone()[0]

            # Obstetrik / Jinekolojik
            rows = con.execute(
                "SELECT ptype, COUNT(*) FROM patient_type "
                "GROUP BY ptype").fetchall()
            stats["by_type"] = dict(rows)

            # Toplam geliÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ sayÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±sÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±
            stats["total_visits"] = con.execute(
                "SELECT COUNT(*) FROM visits").fetchone()[0]

            # Toplam doÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸um
            stats["total_deliveries"] = con.execute(
                "SELECT COUNT(*) FROM deliveries").fetchone()[0]

            # DoÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸um tipi daÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±lÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±mÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±
            rows = con.execute(
                "SELECT delivery_type, COUNT(*) FROM deliveries "
                "GROUP BY delivery_type").fetchall()
            stats["delivery_types"] = dict(rows)

            # Son 30 gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n yeni kayÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±t
            from datetime import timedelta
            date_30 = (datetime.now() - timedelta(days=30)).strftime(
                "%Y-%m-%d")
            stats["new_30d"] = con.execute(
                "SELECT COUNT(*) FROM patients "
                "WHERE first_seen_at>=?", (date_30,)).fetchone()[0]

            # Son 30 gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n geliÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸
            stats["visits_30d"] = con.execute(
                "SELECT COUNT(*) FROM visits "
                "WHERE visit_date>=?", (date_30,)).fetchone()[0]

            # Bayrak daÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±lÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±mÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±
            rows = con.execute(
                "SELECT flag_name, COUNT(DISTINCT patient_key) "
                "FROM patient_flags WHERE value='1' "
                "GROUP BY flag_name "
                "ORDER BY 2 DESC LIMIT 10").fetchall()
            stats["top_flags"] = rows

            # Toplam tahlil sayÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±sÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±
            stats["total_labs"] = con.execute(
                "SELECT COUNT(*) FROM lab_results").fetchone()[0]
    except Exception as ex:
        flash(f"Ä°statistik hatasÄ±: {ex}", "danger")
