def _alex_runtime_enabled():
    try:
        return _db_get_setting("alex_runtime_enabled", "1") == "1"
    except Exception:
        return True


def _alex_runtime_set(enabled):
    try:
        _db_set_setting("alex_runtime_enabled", "1" if enabled else "0")
    except Exception:
        pass


def _alex_runtime_blocks_caller(caller=""):
    if _alex_runtime_enabled():
        return False
    name = str(caller or "").strip().lower()
    if not name:
        return False
    # Manual "Konus / Gorusmeyi baslat" turns must remain usable even when
    # background Alex is disabled. The runtime switch is only for continuous
    # wake-word/background loops.
    blocked_tokens = (
        "browser-live",
        "alex-wake",
        "alex-background",
        "always-on",
    )
    return any(token in name for token in blocked_tokens)


@app.route("/api/alex-runtime/<action>", methods=["GET", "POST"])
def api_alex_runtime(action):
    enabled = str(action or "").lower() in ("start", "on", "baslat", "ac", "1")
    disabled = str(action or "").lower() in ("stop", "off", "kapat", "0")
    if not enabled and not disabled:
        return jsonify({
            "ok": False,
            "error": "Geçersiz Alex komutu",
            "enabled": _alex_runtime_enabled(),
        }), 400
    _alex_runtime_set(enabled)
    return jsonify({
        "ok": True,
        "enabled": enabled,
        "message": "Alex ses modu açık" if enabled else "Alex ses modu kapalı",
    })


@app.route("/alex-baslat")
@app.route("/alex-kapat")
def alex_desktop_shortcut():
    action = "start" if request.path.endswith("baslat") else "stop"
    _alex_runtime_set(action == "start")
    title = "Alex başlatılıyor" if action == "start" else "Alex kapatılıyor"
    message = (
        "Alex tek dinleme modunda açılıyor."
        if action == "start"
        else "Alex arka plan dinleme ve ses döngüsü kapatılıyor."
    )
    return render_template_string(
        """<!doctype html>
<html lang="tr">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{ title }}</title>
  <style>
    body { font-family: system-ui, -apple-system, Segoe UI, sans-serif; margin: 0; background: #f8fafc; color: #0f172a; }
    main { min-height: 100vh; display: grid; place-items: center; padding: 24px; }
    section { max-width: 460px; width: 100%; background: #fff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 22px; box-shadow: 0 18px 45px rgba(15, 23, 42, .08); }
    h1 { font-size: 22px; margin: 0 0 8px; }
    p { margin: 0; color: #475569; line-height: 1.45; }
  </style>
</head>
<body>
<main><section><h1>{{ title }}</h1><p>{{ message }}</p></section></main>
<script>
(function(){
  var action = {{ action|tojson }};
  var cmdKey = 'ykVoiceAlexCommandD200';
  var storeKey = 'ykVoiceAlexAlwaysOnD200';
  try { localStorage.setItem(storeKey, '0'); } catch(e) {}
  try {
    localStorage.setItem(cmdKey, JSON.stringify({
      action: action,
      at: Date.now(),
      id: 'shortcut-' + Date.now()
    }));
  } catch(e) {}
  window.setTimeout(function(){
    window.location.replace('/dashboard?alex=' + encodeURIComponent(action));
  }, 650);
})();
</script>
</body>
</html>""",
        action=action,
        title=title,
        message=message,
    )


