@app.route("/yeni-hasta", methods=["GET", "POST"])
@permission_required("register_patient")
def new_patient():
    if request.method == "POST":
        f = request.form
        name_raw = f.get("name", "").strip()
        ptype = f.get("type", "obstetric")
        if not name_raw:
            flash("Hasta adÄ± zorunludur.", "danger")
            return redirect(url_for("new_patient"))

        clean_name = re.sub(r'[<>:"/\\|?*\x00-\x1F]', ' ', name_raw)
        clean_name = re.sub(r'\s+', ' ', clean_name).strip()
        if not clean_name:
            flash("GeÃ§erli bir isim girin.", "danger")
            return redirect(url_for("new_patient"))

        root = get_patient_storage_root()
        try:
            root.mkdir(parents=True, exist_ok=True)
        except Exception as ex:
            flash(f"Hasta veri kok klasoru olusturulamadi: {ex}", "danger")
            return redirect(url_for("new_patient"))

        patient_key = _build_voluson_patient_key(clean_name, patient_root=root)
        target = root / patient_key
        try:
            target.mkdir(parents=True, exist_ok=False)
        except Exception as ex:
            flash(f"Hasta klasoru olusturulamadi: {ex}", "danger")
            return redirect(url_for("new_patient"))

        age_val = None
        try:
            age = f.get("age", "").strip()
            if age:
                age_val = int(age)
                if age_val < 14 or age_val > 80:
                    flash(f"ÃƒÂ¢Ã…Â¡ YaÅŸ 14-80 arasÄ± olmalÄ± (girilen: {age_val}). "
                           "YaÅŸ kaydedilmedi.", "warning")
                    age_val = None
        except ValueError:
            flash("âš  YaÅŸ sayÄ± olmalÄ± - kaydedilmedi.", "warning")

        phone = f.get("phone", "").strip()
        notes = f.get("notes", "").strip()

        try:
            set_patient_type(patient_key, ptype, is_manual=True,
                              age=age_val, phone=phone or None,
                              notes=notes or None)
            if phone:
                normalized = normalize_phone(phone)
                if normalized != get_default_whatsapp_number():
                    save_phone_db(patient_key, normalized)

            demo = {}
            tc_no = re.sub(r"\D+", "", f.get("tc_no", "").strip())
            if tc_no:
                demo["tc_no"] = tc_no[:11]
            phone_value = f.get("phone", "").strip()
            if phone_value:
                demo["phone"] = phone_value
                try:
                    normalized_phone = normalize_phone(phone_value)
                    if normalized_phone:
                        save_phone_db(patient_key, normalized_phone)
                except Exception:
                    pass
            birth = f.get("birth_date", "").strip()
            if birth:
                try:
                    yy, mm, dd = birth.split("-")
                    demo["birth_date"] = (
                        f"{int(dd):02d}.{int(mm):02d}.{yy}")
                except Exception:
                    pass
            bt = f.get("blood_type", "")
            if bt and bt != "-":
                demo["blood_type"] = bt
            rh = f.get("rh", "")
            if rh:
                demo["rh_factor"] = ("positive"
                                       if rh == "positive"
                                       else "negative")
            lmp = f.get("lmp", "").strip()
            if lmp:
                try:
                    yy, mm, dd = lmp.split("-")
                    demo["lmp_override"] = (
                        f"{int(dd):02d}.{int(mm):02d}.{yy}")
                except Exception:
                    pass
            for k in ("gravida", "para", "abortus", "living"):
                v = f.get(k, "").strip()
                if v:
                    try:
                        demo[k] = int(v)
                    except ValueError:
                        pass
            if age_val is not None:
                demo["age"] = age_val
            demo["canonical_name"] = name_raw
            prefixed_name, folder_prefix, _folder_date = _patient_key_name_parts(patient_key)
            mwl_name = _person_name_to_family_given(name_raw or prefixed_name or patient_key)
            if mwl_name:
                demo["dicom_patient_name"] = mwl_name
            if folder_prefix:
                demo["dicom_patient_id"] = folder_prefix
            else:
                fallback_id = re.sub(r"[^A-Za-z0-9_.-]+", "", patient_key)[:32]
                if fallback_id:
                    demo["dicom_patient_id"] = fallback_id
            demo["dicom_accession_prefix"] = demo.get("dicom_patient_id") or ""
            demo["dicom_station_aet"] = VOLUSON_AET
            for k_form, k_db in (
                    ("weight", "weight"),
                    ("height", "height"),
                    ("pre_pregnancy_weight", "pre_pregnancy_weight")):
                v = f.get(k_form, "").strip()
                if v:
                    demo[k_db] = v
            for k in ("chronic", "meds", "allergies"):
                v = f.get(k, "").strip()
                if v:
                    demo[{"chronic": "chronic_conditions",
                           "meds": "medications",
                           "allergies": "allergies"}[k]] = v
            if demo:
                save_patient_demographics(patient_key, demo)
            _ensure_patient_index_row(patient_key, target, name_raw)
            _ensure_initial_manual_visit(patient_key, target, notes)
        except Exception as ex:
            flash(f"Kayit hatasÄ±: {ex}", "danger")
            return redirect(url_for("new_patient"))

        _invalidate_patient_web_cache()
        flash(f"âœ… '{name_raw}' kaydedildi!", "success")
        _log_audit("patient_create", entity_type="patient",
                    patient_key=patient_key,
                    details=f"name={name_raw}")
        return redirect(url_for("patient_detail",
                                  patient_key=patient_key))

    today_str = datetime.now().strftime("%Y-%m-%d")
    default_phone = get_default_whatsapp_number()
    default_type = request.args.get("type", "obstetric").strip()
    if default_type not in PATIENT_TYPE_LABELS:
        default_type = "obstetric"
    checked_ob = "checked" if default_type == "obstetric" else ""
    checked_gyn = "checked" if default_type == "gynecologic" else ""
    checked_med_aes = "checked" if default_type == "medical_aesthetic" else ""
    checked_gyn_aes = "checked" if default_type == "gynecologic_aesthetic" else ""
    content = f"""
    <a href="/" class="btn btn-secondary mb-3">&larr; Hasta listesi</a>
    <h2 class="mb-4"><i class="bi bi-person-plus"></i> Yeni Hasta Kayit</h2>
    <style>
      .yk-patient-type-grid {{
        row-gap: 12px;
      }}
      .yk-patient-type-option {{
        display: flex;
        align-items: center;
        gap: 12px;
        min-height: 56px;
        padding: 13px 16px;
        border: 1px solid #D9E6F2;
        border-radius: 14px;
        background: linear-gradient(135deg, #FFFFFF, #F5FAFE);
        box-shadow: 0 10px 24px rgba(15, 44, 72, .06);
        cursor: pointer;
        transition: border-color .16s ease, box-shadow .16s ease, background .16s ease;
      }}
      .yk-patient-type-option:hover {{
        border-color: #8CC7EA;
        box-shadow: 0 14px 30px rgba(15, 44, 72, .10);
      }}
      .yk-patient-type-option.is-selected {{
        border-color: #0EA5A4;
        background: linear-gradient(135deg, #ECFEFF, #FFFFFF);
        box-shadow: 0 0 0 3px rgba(14, 165, 164, .14),
                    0 18px 34px rgba(15, 44, 72, .12);
      }}
      .yk-patient-type-radio {{
        width: 24px;
        height: 24px;
        min-width: 24px;
        margin: 0;
        appearance: none;
        -webkit-appearance: none;
        border: 2px solid #A9BDD0;
        border-radius: 999px;
        background: #FFFFFF;
        box-shadow: inset 0 0 0 5px #FFFFFF;
        cursor: pointer;
      }}
      .yk-patient-type-radio:checked {{
        border-color: #0EA5A4;
        background: #0EA5A4;
        box-shadow: inset 0 0 0 5px #FFFFFF,
                    0 0 0 3px rgba(14, 165, 164, .18);
      }}
      .yk-patient-type-label {{
        flex: 1;
        margin: 0;
        color: #17304A;
        font-weight: 800;
        cursor: pointer;
      }}
    </style>
    <form method="POST">
      <div class="form-section">
        <h5>1. Hasta Tipi</h5>
        <div class="row g-3 yk-patient-type-grid" data-yk-patient-type-list>
          <div class="col-md-6">
            <div class="form-check yk-patient-type-option" data-yk-patient-type-option>
              <input class="form-check-input yk-patient-type-radio" type="radio" name="type"
                     id="type-ob" value="obstetric" {checked_ob}
                     onchange="ykSyncPatientTypePick(this)">
              <label class="form-check-label yk-patient-type-label" for="type-ob">
                <i class="bi bi-person-heart"></i> Obstetrik (Gebelik Takibi)</label>
            </div>
          </div>
          <div class="col-md-6">
            <div class="form-check yk-patient-type-option" data-yk-patient-type-option>
              <input class="form-check-input yk-patient-type-radio" type="radio" name="type"
                     id="type-gyn" value="gynecologic" {checked_gyn}
                     onchange="ykSyncPatientTypePick(this)">
              <label class="form-check-label yk-patient-type-label" for="type-gyn">
                <i class="bi bi-flower1"></i> Jinekolojik</label>
            </div>
          </div>
          <div class="col-md-6">
            <div class="form-check yk-patient-type-option" data-yk-patient-type-option>
              <input class="form-check-input yk-patient-type-radio" type="radio" name="type"
                     id="type-med-aes" value="medical_aesthetic" {checked_med_aes}
                     onchange="ykSyncPatientTypePick(this)">
              <label class="form-check-label yk-patient-type-label" for="type-med-aes">
                Medikal Estetik</label>
            </div>
          </div>
          <div class="col-md-6">
            <div class="form-check yk-patient-type-option" data-yk-patient-type-option>
              <input class="form-check-input yk-patient-type-radio" type="radio" name="type"
                     id="type-gyn-aes" value="gynecologic_aesthetic" {checked_gyn_aes}
                     onchange="ykSyncPatientTypePick(this)">
              <label class="form-check-label yk-patient-type-label" for="type-gyn-aes">
                Jinekolojik Estetik</label>
            </div>
          </div>
        </div>
      </div>
      <div class="form-section">
        <h5>2. Kimlik</h5>
        <div class="row g-3">
          <div class="col-md-8">
            <label class="form-label">Ad Soyad *</label>
            <input type="text" name="name" class="form-control form-control-lg"
                   required autofocus placeholder="Ayse Yilmaz">
          </div>
          <div class="col-md-4">
            <label class="form-label">Yas</label>
            <input type="number" name="age" class="form-control form-control-lg"
                   min="14" max="80">
          </div>
          <div class="col-md-4">
            <label class="form-label">Kilo (kg)</label>
            <input type="number" name="weight" step="0.1"
                   class="form-control" min="20" max="250">
          </div>
          <div class="col-md-4">
            <label class="form-label">Boy (cm)</label>
            <input type="number" name="height" step="0.1"
                   class="form-control" min="90" max="230">
          </div>
          <div class="col-md-4">
            <label class="form-label">Gebelik oncesi kilo (kg)</label>
            <input type="number" name="pre_pregnancy_weight" step="0.1"
                   class="form-control" min="20" max="250">
          </div>
          <div class="col-md-12">
            <label class="form-label">Telefon</label>
            <input type="tel" name="phone" class="form-control"
                   placeholder="{default_phone} (varsayilan)">
          </div>
        </div>
      </div>
      <div class="form-section">
        <h5>3. Kan Grubu</h5>
        <div class="row g-3">
          <div class="col-md-6">
            <label class="form-label">Kan Grubu</label>
            <select name="blood_type" class="form-select">
              <option value="">-</option>
              <option>0</option><option>A</option>
              <option>B</option><option>AB</option>
            </select>
          </div>
          <div class="col-md-6">
            <label class="form-label">Rh</label>
            <select name="rh" class="form-select">
              <option value="">-</option>
              <option value="positive">Pozitif (+)</option>
              <option value="negative">Negatif (-)</option>
            </select>
          </div>
        </div>
      </div>
      <div class="form-section" id="ob-section">
        <h5>4. Gebelik Bilgileri</h5>
        <div class="row g-3">
          <div class="col-md-6">
            <label class="form-label">LMP (Son Adet)</label>
            <input type="date" name="lmp" class="form-control"
                   max="{today_str}">
          </div>
          <div class="col-md-6">
            <label class="form-label">GPAL</label>
            <div class="row g-1">
              <div class="col"><input type="number" name="gravida"
                class="form-control" min="0" max="20" placeholder="G"></div>
              <div class="col"><input type="number" name="para"
                class="form-control" min="0" max="20" placeholder="P"></div>
              <div class="col"><input type="number" name="abortus"
                class="form-control" min="0" max="20" placeholder="A"></div>
              <div class="col"><input type="number" name="living"
                class="form-control" min="0" max="20" placeholder="L"></div>
            </div>
          </div>
        </div>
      </div>
      <div class="form-section">
        <h5>5. Tibbi Ozgecmis</h5>
        <div class="row g-3">
          <div class="col-md-12">
            <label class="form-label">Kronik Hastaliklar</label>
            <input type="text" name="chronic" class="form-control"
                   placeholder="DM, HT, Tiroid">
          </div>
          <div class="col-md-12">
            <label class="form-label">Ilaclar</label>
            <input type="text" name="meds" class="form-control"
                   placeholder="Levothyroxine 50mcg">
          </div>
          <div class="col-md-12">
            <label class="form-label">Alerjiler</label>
            <input type="text" name="allergies" class="form-control">
          </div>
        </div>
      </div>
      <div class="form-section">
        <h5>6. Notlar</h5>
        <textarea name="notes" class="form-control" rows="3"></textarea>
      </div>
      <div class="d-flex justify-content-between mb-5">
        <a href="/" class="btn btn-secondary btn-lg">Iptal</a>
        <button type="submit" class="btn btn-success btn-lg">Kaydet</button>
      </div>
    </form>
    <script>
      const obRadio = document.getElementById('type-ob');
      const obSec = document.getElementById('ob-section');
      function ykSyncPatientTypePick(radio) {{
        document.querySelectorAll('input[name="type"]').forEach(function(item) {{
          var option = item.closest('[data-yk-patient-type-option]');
          if (option) option.classList.toggle('is-selected', !!item.checked);
          item.setAttribute('aria-checked', item.checked ? 'true' : 'false');
        }});
        tg();
        return true;
      }}
      function ykSetPatientType(radio) {{
        if (!radio) return false;
        document.querySelectorAll('input[name="type"]').forEach(function(item) {{
          item.checked = (item === radio);
        }});
        ykSyncPatientTypePick(radio);
        try {{
          radio.dispatchEvent(new Event('change', {{ bubbles: true }}));
        }} catch (e) {{}}
        return false;
      }}
      function tg() {{
        obSec.style.opacity = obRadio.checked ? '1' : '0.4';
        obSec.style.pointerEvents = obRadio.checked ? 'auto' : 'none';
      }}
      var ykPatientTypeLastHandledAt = 0;
      function ykStopPatientTypeEvent(ev) {{
        if (!ev) return false;
        ev.preventDefault();
        ev.stopPropagation();
        if (ev.stopImmediatePropagation) ev.stopImmediatePropagation();
        return false;
      }}
      function ykHandlePatientTypeEvent(ev) {{
        var target = ev.target;
        if (!target || !target.closest) return;
        var option = target.closest('[data-yk-patient-type-option]');
        if (!option) return;
        var radio = option.querySelector('input[name="type"]');
        if (!radio) return;
        var now = Date.now();
        if ((ev.type === 'mousedown' || ev.type === 'click') &&
            (now - ykPatientTypeLastHandledAt) < 650) {{
          return ykStopPatientTypeEvent(ev);
        }}
        ykPatientTypeLastHandledAt = now;
        ykSetPatientType(radio);
        return ykStopPatientTypeEvent(ev);
      }}
      window.addEventListener('pointerdown', ykHandlePatientTypeEvent, true);
      window.addEventListener('mousedown', ykHandlePatientTypeEvent, true);
      window.addEventListener('click', ykHandlePatientTypeEvent, true);
      window.addEventListener('keydown', function(ev) {{
        if (ev.key !== ' ' && ev.key !== 'Enter') return;
        var target = ev.target;
        if (!target || !target.closest) return;
        var option = target.closest('[data-yk-patient-type-option]');
        if (!option) return;
        var radio = option.querySelector('input[name="type"]');
        if (!radio) return;
        ykSetPatientType(radio);
        return ykStopPatientTypeEvent(ev);
      }}, true);
      document.querySelectorAll('input[name="type"]').forEach(r => {{
        r.addEventListener('change', tg);
        ykSyncPatientTypePick(r);
      }});
      tg();
    </script>
    """
