@app.route("/hasta/<patient_key>/telefon", methods=["POST"])
@permission_required("edit_phone")
def update_phone(patient_key):
    new_phone = request.form.get("phone", "").strip()
    try:
        if new_phone:
            normalized = normalize_phone(new_phone)
            if normalized != get_default_whatsapp_number():
                save_phone_db(patient_key, normalized)
                _invalidate_patient_web_cache(patient_key)
                flash(f"âœ“ Telefon kaydedildi: {normalized}", "success")
            else:
                flash("VarsayÄ±lan numara - kayÄ±t yapÄ±lmadÄ±.", "info")
        else:
            with db_conn() as con:
                con.execute(
                    "DELETE FROM patient_phones WHERE patient_key=?",
                    (patient_key,))
                con.commit()
            _invalidate_patient_web_cache(patient_key)
            flash("Ã–zel numara silindi.", "warning")
    except Exception as ex:
        flash(f"Hata: {ex}", "danger")
    return redirect(url_for("patient_detail",
                              patient_key=patient_key))


