def _patient_file_pdf_snapshot(patient_key, max_pdfs=12, max_chars=120000):
    items = []
    warnings = []
    try:
        candidates = _diet_recent_pdf_candidates_v1000(patient_key)[:max_pdfs]
    except Exception as ex:
        candidates = []
        warnings.append(f"PDF listesi okunamadi: {ex}")
    for item in candidates:
        try:
            path = Path(item.get("path"))
            text = _extract_text_from_pdf_file(path)
            if not text:
                warnings.append(f"{path.name}: metin okunamadi/OCR gerekebilir")
                continue
            items.append({
                "name": path.name,
                "path": str(path),
                "mtime": item.get("mtime") or 0,
                "visit_key": item.get("visit_key") or "",
                "visit_date": item.get("visit_date") or "",
                "text": text[:max_chars],
            })
        except Exception as ex:
            warnings.append(f"{Path(item.get('path', 'PDF')).name}: {ex}")
    payload = _yk_extract_patient_pdf_payload(items)
    if warnings:
        payload["warnings"] = list(payload.get("warnings") or []) + warnings
    payload["read_pdf_count"] = len(items)
    payload["candidate_pdf_count"] = len(candidates)
    return payload


def _patient_file_pdf_form_demo(existing_demo, pdf_payload):
    demo = dict(existing_demo or {})
    pdf_demo = (pdf_payload or {}).get("demographics") or {}
    for key, value in pdf_demo.items():
        if value in (None, ""):
            continue
        if demo.get(key) in (None, ""):
            demo[key] = value
    return demo


def _patient_file_html_date(value):
    try:
        return _clinical_date_to_html_v1000(value)
    except Exception:
        return ""


def _patient_file_iso_date(value):
    text = str(value or "").strip()
    if not text:
        return ""
    if re.match(r"^\d{4}-\d{2}-\d{2}$", text[:10]):
        return text[:10]
    try:
        day = _preg_plan_parse_date_v1000(text)
        if day:
            return day.isoformat()
    except Exception:
        pass
    return ""


def _patient_file_mtime_date(value):
    try:
        mtime = float(value or 0)
        if mtime > 0:
            return datetime.fromtimestamp(mtime).strftime("%Y-%m-%d")
    except Exception:
        pass
    return ""


def _patient_file_load_data_json(patient_key):
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            _web_ensure_patient_demographics_schema_v1000(con)
            row = con.execute(
                "SELECT data_json FROM patient_demographics WHERE patient_key=?",
                (patient_key,)).fetchone()
        data = json.loads((row or {}).get("data_json") or "{}")
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _patient_file_update_data_json(patient_key, updater):
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            _web_ensure_patient_demographics_schema_v1000(con)
            row = con.execute(
                "SELECT data_json FROM patient_demographics WHERE patient_key=?",
                (patient_key,)).fetchone()
            try:
                data = json.loads((row or {}).get("data_json") or "{}")
                if not isinstance(data, dict):
                    data = {}
            except Exception:
                data = {}
            updated = updater(data, now)
            if isinstance(updated, dict):
                data = updated
            con.execute(
                "INSERT OR IGNORE INTO patient_demographics("
                "patient_key, updated_at, data_json) VALUES(?,?,?)",
                (patient_key, now, json.dumps(data, ensure_ascii=False)))
            con.execute(
                "UPDATE patient_demographics SET data_json=?, updated_at=? "
                "WHERE patient_key=?",
                (json.dumps(data, ensure_ascii=False), now, patient_key))
            con.commit()
        return True
    except Exception:
        return False


def _patient_file_mark_manual_fields(patient_key, fields):
    clean = []
    for raw in fields or []:
        field = _patient_data_canonical_key(raw)
        if field and field not in clean:
            clean.append(field)
    if not clean:
        return False

    def _update(data, now):
        manual = data.get("manual_fields")
        if isinstance(manual, list):
            manual = {str(k): {"updated_at": now} for k in manual}
        if not isinstance(manual, dict):
            manual = {}
        for field in clean:
            manual[field] = {
                "source": "manual_form",
                "updated_at": now,
            }
        data["manual_fields"] = manual
        return data

    return _patient_file_update_data_json(patient_key, _update)


def _patient_file_merge_pdf_demo(patient_key, pdf_payload, overwrite=False):
    """Apply newest PDF demographics without trampling manual patient data."""
    pdf_entries = list((pdf_payload or {}).get("pdfs") or [])
    if not pdf_entries and (pdf_payload or {}).get("demographics"):
        pdf_entries = [{
            "name": "PDF",
            "mtime": 0,
            "path": "",
            "demographics": (pdf_payload or {}).get("demographics") or {},
        }]

    def _sort_key(entry):
        try:
            return float(entry.get("mtime") or 0)
        except Exception:
            return 0.0

    pdf_entries = sorted(pdf_entries, key=_sort_key, reverse=True)
    meta = _patient_file_load_data_json(patient_key)
    manual_raw = meta.get("manual_fields")
    if isinstance(manual_raw, dict):
        manual_fields = set(manual_raw.keys())
    elif isinstance(manual_raw, list):
        manual_fields = set(str(x) for x in manual_raw)
    else:
        manual_fields = set()
    pdf_sources = meta.get("pdf_auto_field_sources")
    if not isinstance(pdf_sources, dict):
        pdf_sources = {}
    old_applied = meta.get("pdf_patient_extract_applied")
    if not isinstance(old_applied, dict):
        old_applied = {}

    try:
        current_demo = load_patient_demographics(patient_key) or {}
    except Exception:
        current_demo = {}
    applied = {}
    skipped = {}
    seen = set()
    source_updates = {}
    for entry in pdf_entries:
        entry_demo = entry.get("demographics") or {}
        if not entry_demo:
            continue
        source_name = str(entry.get("name") or "PDF")
        source_ref = source_name
        if entry.get("visit_date"):
            source_ref += f" / {entry.get('visit_date')}"
        for raw_key, value in dict(entry_demo).items():
            field = _patient_data_canonical_key(raw_key)
            if not field or field in seen:
                continue
            seen.add(field)
            normalized = _patient_data_normalize(field, value)
            if not normalized:
                continue
            current_norm = _patient_data_normalize(
                field, current_demo.get(field))
            was_pdf_field = field in pdf_sources or field in old_applied
            if current_norm == normalized:
                continue
            if field in manual_fields and current_norm:
                skipped[field] = normalized
                try:
                    _patient_data_suggest_value(
                        patient_key, field, normalized,
                        source="pdf_latest_hasta_dosyasi",
                        source_ref=source_ref,
                        confidence=0.82,
                        auto_apply_empty=False)
                except Exception:
                    pass
                continue
            if (not current_norm) or was_pdf_field or overwrite:
                try:
                    _patient_data_apply_value(patient_key, field, normalized)
                    current_demo[field] = normalized
                    applied[field] = normalized
                    source_updates[field] = {
                        "source": source_name,
                        "path": str(entry.get("path") or ""),
                        "mtime": entry.get("mtime") or 0,
                        "visit_key": str(entry.get("visit_key") or ""),
                        "visit_date": str(entry.get("visit_date") or ""),
                    }
                except Exception:
                    skipped[field] = normalized
                continue
            skipped[field] = normalized
            try:
                _patient_data_suggest_value(
                    patient_key, field, normalized,
                    source="pdf_latest_hasta_dosyasi",
                    source_ref=source_ref,
                    confidence=0.82,
                    auto_apply_empty=False)
            except Exception:
                pass

    if source_updates:
        def _update(data, now):
            existing = data.get("pdf_auto_field_sources")
            if not isinstance(existing, dict):
                existing = {}
            for field, info in source_updates.items():
                item = dict(info or {})
                item["updated_at"] = now
                existing[field] = item
            data["pdf_auto_field_sources"] = existing
            return data

        _patient_file_update_data_json(patient_key, _update)
    return applied, skipped


def _patient_file_store_pdf_payload(patient_key, pdf_payload, applied=None):
    def _update(data, now):
        compact = dict(pdf_payload or {})
        if "pdfs" in compact:
            compact["pdfs"] = compact.get("pdfs", [])[:20]
        if "labs" in compact:
            compact["labs"] = compact.get("labs", [])[:80]
        data["pdf_patient_extract"] = compact
        data["pdf_patient_extract_applied"] = dict(applied or {})
        data["pdf_patient_extract_updated_at"] = now
        return data

    _patient_file_update_data_json(patient_key, _update)


_PATIENT_FILE_PDF_AUTO_PROFILE_VERSION = "2026-05-14-profile-demographics-metrics-v3"


def _patient_file_pdf_candidate_signature(patient_key, max_pdfs=12):
    try:
        candidates = _diet_recent_pdf_candidates_v1000(patient_key)[:max_pdfs]
    except Exception:
        candidates = []
    bits = []
    for item in candidates:
        raw_path = str(item.get("path") or "").strip()
        if not raw_path:
            continue
        try:
            path = Path(raw_path)
            stat = path.stat()
            mtime = int(stat.st_mtime)
            size = int(stat.st_size)
        except Exception:
            mtime = int(float(item.get("mtime") or 0))
            size = 0
        bits.append(f"{raw_path}|{mtime}|{size}")
    return "\n".join(bits), len(candidates)


def _patient_file_auto_apply_pdf_demographics(patient_key, force=False,
                                              max_pdfs=12):
    """Keep core patient profile fields fresh from PDFs without overwriting manual data."""
    q_patient = str(patient_key or "").strip()
    if not q_patient:
        return {"ok": False, "status": "no_patient"}
    try:
        meta = _patient_file_load_data_json(q_patient)
    except Exception:
        meta = {}
    if not force:
        try:
            checked_raw = str(meta.get("pdf_patient_extract_auto_checked_at") or "")
            checked_dt = datetime.fromisoformat(checked_raw.replace("Z", "+00:00"))
            if (meta.get("pdf_patient_extract_auto_version")
                    == _PATIENT_FILE_PDF_AUTO_PROFILE_VERSION and
                    (datetime.now() - checked_dt.replace(tzinfo=None)).total_seconds() < 900):
                return {"ok": True, "status": "recent", "applied": {}}
        except Exception:
            pass
    signature, candidate_count = _patient_file_pdf_candidate_signature(
        q_patient, max_pdfs=max_pdfs)
    if not candidate_count:
        return {"ok": True, "status": "no_pdf", "applied": {}}
    if (not force and
            meta.get("pdf_patient_extract_auto_version")
            == _PATIENT_FILE_PDF_AUTO_PROFILE_VERSION and
            meta.get("pdf_patient_extract_auto_signature") == signature):
        return {"ok": True, "status": "cached", "applied": {}}
    try:
        payload = _patient_file_pdf_snapshot(q_patient, max_pdfs=max_pdfs)
        applied, skipped = _patient_file_merge_pdf_demo(
            q_patient, payload, overwrite=False)
        _patient_file_store_pdf_payload(q_patient, payload, applied=applied)

        def _update(data, now):
            data["pdf_patient_extract_auto_version"] = (
                _PATIENT_FILE_PDF_AUTO_PROFILE_VERSION)
            data["pdf_patient_extract_auto_signature"] = signature
            data["pdf_patient_extract_auto_checked_at"] = now
            data["pdf_patient_extract_auto_applied"] = dict(applied or {})
            data["pdf_patient_extract_auto_skipped"] = dict(skipped or {})
            return data

        _patient_file_update_data_json(q_patient, _update)
        if applied:
            try:
                _invalidate_patient_web_cache(q_patient)
            except Exception:
                pass
        return {
            "ok": True,
            "status": "applied" if applied else "read",
            "applied": applied,
            "skipped": skipped,
            "payload": payload,
        }
    except Exception as ex:
        return {"ok": False, "status": "error", "error": str(ex)}


def _patient_file_auto_apply_pdf_demographics_deferred(patient_key, max_pdfs=12):
    q_patient = str(patient_key or "").strip()
    if not q_patient:
        return {"ok": False, "status": "no_patient"}
    try:
        meta = _patient_file_load_data_json(q_patient)
        checked_raw = str(meta.get("pdf_patient_extract_auto_checked_at") or "")
        checked_dt = datetime.fromisoformat(checked_raw.replace("Z", "+00:00"))
        if (meta.get("pdf_patient_extract_auto_version")
                == _PATIENT_FILE_PDF_AUTO_PROFILE_VERSION and
                (datetime.now() - checked_dt.replace(tzinfo=None)).total_seconds() < 900):
            return {"ok": True, "status": "recent"}
    except Exception:
        pass

    run_key = f"patient_pdf_auto_apply_{q_patient}_{int(max_pdfs or 0)}"

    def _worker():
        _patient_file_auto_apply_pdf_demographics(
            q_patient, force=False, max_pdfs=max_pdfs)

    try:
        scheduled = _perf_singleflight_async(run_key, _worker)
        return {"ok": True, "status": "scheduled" if scheduled else "running"}
    except Exception as ex:
        return {"ok": False, "status": "defer_error", "error": str(ex)}


