_PATIENT_FILE_DICOM_SYNC_LOCK = threading.Lock()
_PATIENT_FILE_DICOM_SYNC_RUNNING = {}


def _patient_file_dicom_snapshot(patient_key, limit=12):
    payload = {
        "ok": True,
        "patient_key": str(patient_key or ""),
        "studies": [],
        "measurements": [],
        "usg_rows": [],
        "private_reports": [],
        "stats": {
            "studies": 0,
            "measurements": 0,
            "usg_rows": 0,
            "private_reports": 0,
            "last_sync_at": "",
        },
        "job": {},
        "error": "",
    }
    q_patient = str(patient_key or "").strip()
    if not q_patient:
        return payload
    meta = _patient_file_load_data_json(q_patient)
    job = meta.get("dicom_patient_extract_job")
    if isinstance(job, dict):
        payload["job"] = job
    row_factory = lambda cur, row: {
        d[0]: row[i] for i, d in enumerate(cur.description)}
    limit = max(1, min(int(limit or 12), 80))
    try:
        with db_conn() as con:
            con.row_factory = row_factory
            _ensure_dicom_ai_tables(con)
            _ensure_usg_measurement_dicom_columns(con)
            payload["studies"] = con.execute("""
                SELECT orthanc_study_id, study_instance_uid, patient_name,
                       patient_id, study_date, study_time, accession_number,
                       matched_confidence, match_reason, last_synced_at
                FROM dicom_studies
                WHERE patient_key=?
                ORDER BY COALESCE(study_date,'') DESC,
                         COALESCE(last_synced_at,'') DESC
                LIMIT ?
            """, (q_patient, limit)).fetchall()
            payload["measurements"] = con.execute("""
                SELECT id, visit_key, source_type, source_id,
                       measurement_name, measurement_value, unit, confidence,
                       needs_doctor_review, doctor_approved, created_at
                FROM dicom_measurement_candidates
                WHERE patient_key=? AND COALESCE(source_type,'') LIKE 'dicom%'
                ORDER BY doctor_approved DESC,
                         COALESCE(created_at,'') DESC, id DESC
                LIMIT ?
            """, (q_patient, limit * 3)).fetchall()
            payload["usg_rows"] = con.execute("""
                SELECT usg_date, visit_key, ga_weeks, ga_days,
                       bpd, hc, ac, fl, crl, nt, efw, afi, fhr,
                       ua_pi, ua_ri, ua_sd, mca_pi, mca_ri, mca_psv,
                       uta_pi, uta_ri, dv_pi, cpr, source_type,
                       source_accession_number, source_study_id,
                       source_instance_id, notes, created_at
                FROM usg_measurements
                WHERE patient_key=? AND COALESCE(source_type,'') LIKE 'dicom%'
                ORDER BY COALESCE(usg_date,'') DESC,
                         COALESCE(created_at,'') DESC
                LIMIT ?
            """, (q_patient, limit)).fetchall()
            payload["private_reports"] = con.execute("""
                SELECT orthanc_instance_id, private_creator_list,
                       private_tag_count, text_probe_count,
                       decoded_measurement_count, has_4dview_payload,
                       updated_at
                FROM dicom_private_tag_reports
                WHERE patient_key=?
                ORDER BY COALESCE(updated_at,'') DESC
                LIMIT ?
            """, (q_patient, limit)).fetchall()
            counts = {}
            for key, sql in (
                ("studies",
                 "SELECT COUNT(*) AS n FROM dicom_studies WHERE patient_key=?"),
                ("measurements",
                 "SELECT COUNT(*) AS n FROM dicom_measurement_candidates "
                 "WHERE patient_key=? AND COALESCE(source_type,'') LIKE 'dicom%'"),
                ("usg_rows",
                 "SELECT COUNT(*) AS n FROM usg_measurements "
                 "WHERE patient_key=? AND COALESCE(source_type,'') LIKE 'dicom%'"),
                ("private_reports",
                 "SELECT COUNT(*) AS n FROM dicom_private_tag_reports "
                 "WHERE patient_key=?"),
            ):
                row = con.execute(sql, (q_patient,)).fetchone()
                counts[key] = int((row or {}).get("n") or 0)
            row = con.execute("""
                SELECT MAX(last_synced_at) AS last_sync_at
                FROM dicom_studies
                WHERE patient_key=?
            """, (q_patient,)).fetchone()
            counts["last_sync_at"] = str(
                (row or {}).get("last_sync_at") or "")
            payload["stats"] = counts
    except Exception as ex:
        payload["ok"] = False
        payload["error"] = f"{type(ex).__name__}: {ex}"
    return payload


def _patient_file_dicom_usg_bits(row):
    row = row or {}
    bits = []
    if row.get("ga_weeks") not in (None, "", "None"):
        bits.append(f"GA {row.get('ga_weeks')}+{row.get('ga_days') or 0}")
    for key, label, unit in (
            ("bpd", "BPD", "mm"),
            ("hc", "HC", "mm"),
            ("ac", "AC", "mm"),
            ("fl", "FL", "mm"),
            ("crl", "CRL", "mm"),
            ("nt", "NT", "mm"),
            ("efw", "EFW", "g"),
            ("afi", "AFI", "cm"),
            ("fhr", "FHR", "bpm"),
            ("ua_pi", "UA PI", ""),
            ("ua_ri", "UA RI", ""),
            ("ua_sd", "UA S/D", ""),
            ("mca_pi", "MCA PI", ""),
            ("mca_ri", "MCA RI", ""),
            ("mca_psv", "MCA PSV", ""),
            ("uta_pi", "UTA PI", ""),
            ("uta_ri", "UTA RI", ""),
            ("dv_pi", "DV PI", ""),
            ("cpr", "CPR", ""),
    ):
        value = row.get(key)
        if value in (None, "", "None"):
            continue
        bits.append(f"{label}: {value}{(' ' + unit) if unit else ''}")
    return " | ".join(bits)


def _patient_file_store_dicom_payload(patient_key, sync_result, snapshot):
    def _update(data, now):
        compact = {
            "updated_at": now,
            "sync": dict(sync_result or {}),
            "stats": dict((snapshot or {}).get("stats") or {}),
        }
        data["dicom_patient_extract"] = compact
        return data

    _patient_file_update_data_json(patient_key, _update)


def _patient_file_store_dicom_job_status(
        patient_key, status, message="", job_id="", sync_result=None):
    def _update(data, now):
        job = {
            "status": str(status or ""),
            "message": str(message or ""),
            "job_id": str(job_id or ""),
            "updated_at": now,
        }
        if isinstance(sync_result, dict):
            job["patient_after"] = dict(sync_result.get("patient_after") or {})
            job["patient_added"] = dict(sync_result.get("patient_added") or {})
            job["studies_seen"] = int(sync_result.get("studies_seen") or 0)
            job["instances_synced"] = int(sync_result.get("instances_synced") or 0)
            job["measurement_candidates"] = int(
                sync_result.get("measurement_candidates") or 0)
        data["dicom_patient_extract_job"] = job
        return data

    _patient_file_update_data_json(patient_key, _update)


def _patient_file_sync_dicom_measurements(
        patient_key, limit=120, instance_cap=900,
        private_scan_cap=120, private_download_cap=0):
    q_patient = str(patient_key or "").strip()
    if not q_patient:
        return {"ok": False, "error": "patient_key yok"}
    before = _patient_file_dicom_snapshot(q_patient, limit=1).get("stats") or {}
    result = _dicom_sync_from_orthanc(
        limit=limit, detail=True, instance_cap=instance_cap,
        private_scan_cap=private_scan_cap,
        private_download_cap=private_download_cap)
    after_payload = _patient_file_dicom_snapshot(q_patient, limit=16)
    after = after_payload.get("stats") or {}
    added = {
        key: max(0, int(after.get(key) or 0) - int(before.get(key) or 0))
        for key in ("studies", "measurements", "usg_rows", "private_reports")
    }
    result["patient_key"] = q_patient
    result["patient_before"] = before
    result["patient_after"] = after
    result["patient_added"] = added
    _patient_file_store_dicom_payload(q_patient, result, after_payload)
    return result


def _patient_file_dicom_sync_message(sync_result):
    if not isinstance(sync_result, dict):
        return "DICOM taramasi tamamlandi."
    after = sync_result.get("patient_after") or {}
    added = sync_result.get("patient_added") or {}
    if int(after.get("usg_rows") or 0):
        return (
            "DICOM tarandi: "
            f"{int(after.get('studies') or 0)} study, "
            f"{int(after.get('measurements') or 0)} olcum adayi, "
            f"{int(after.get('usg_rows') or 0)} USG satiri hasta dosyasinda. "
            "Yeni: "
            f"{int(added.get('studies') or 0)} study, "
            f"{int(added.get('measurements') or 0)} aday, "
            f"{int(added.get('usg_rows') or 0)} USG satiri.")
    if int(after.get("measurements") or 0):
        return (
            "DICOM olcum adaylari bulundu; DICOM / USG Zeka sayfasinda "
            "kontrol edip onaylayabilirsiniz.")
    return (
        "DICOM tarandi fakat bu hastaya baglanan olcum bulunamadi. "
        "Worklist/PatientID/Accession eslesmesini veya DICOM / USG Zeka "
        "sayfasindaki manuel study baglama akisini kontrol edin.")


def _patient_file_start_dicom_sync_job(patient_key, user_name=""):
    q_patient = str(patient_key or "").strip()
    if not q_patient:
        return {"ok": False, "error": "patient_key yok"}
    with _PATIENT_FILE_DICOM_SYNC_LOCK:
        current = _PATIENT_FILE_DICOM_SYNC_RUNNING.get(q_patient)
        if current and current.get("running"):
            return {
                "ok": True,
                "started": False,
                "running": True,
                "job_id": current.get("job_id") or "",
            }
        job_id = uuid.uuid4().hex[:12]
        _PATIENT_FILE_DICOM_SYNC_RUNNING[q_patient] = {
            "running": True,
            "job_id": job_id,
            "started_at": datetime.now().isoformat(
                sep=" ", timespec="seconds"),
        }

    _patient_file_store_dicom_job_status(
        q_patient, "running",
        "DICOM olcum aktarimi arka planda basladi. Sayfa serbest; birazdan yenileyin.",
        job_id=job_id)

    def _worker():
        try:
            result = _patient_file_sync_dicom_measurements(q_patient)
            status = "done"
            after = result.get("patient_after") or {}
            if not int(after.get("measurements") or 0) and not int(after.get("usg_rows") or 0):
                status = "empty"
            _patient_file_store_dicom_job_status(
                q_patient, status, _patient_file_dicom_sync_message(result),
                job_id=job_id, sync_result=result)
            try:
                _invalidate_patient_web_cache(q_patient)
            except Exception:
                pass
        except Exception as ex:
            _patient_file_store_dicom_job_status(
                q_patient, "error",
                f"DICOM aktarimi tamamlanamadi: {type(ex).__name__}: {ex}",
                job_id=job_id)
        finally:
            with _PATIENT_FILE_DICOM_SYNC_LOCK:
                current = _PATIENT_FILE_DICOM_SYNC_RUNNING.get(q_patient) or {}
                if current.get("job_id") == job_id:
                    _PATIENT_FILE_DICOM_SYNC_RUNNING.pop(q_patient, None)

    threading.Thread(
        target=_worker, name=f"dicom-patient-sync-{q_patient[:24]}",
        daemon=True).start()
    return {"ok": True, "started": True, "running": True, "job_id": job_id}


def _patient_file_dicom_panel_html(patient_key, dicom_payload, can_edit):
    dicom_payload = dicom_payload or {}
    stats = dicom_payload.get("stats") or {}
    measurements = dicom_payload.get("measurements") or []
    usg_rows = dicom_payload.get("usg_rows") or []
    studies = dicom_payload.get("studies") or []
