@login_required
def patient_followup_media(patient_key):
    """Manual follow-up media: aesthetic before/after and face tracking."""
    allowed_modules = {
        "medical_aesthetic",
        "genital_aesthetic",
        "gynecologic_aesthetic",
        "face_followup",
        "hd_studio",
    }
    allowed_phases = {"before", "after", "followup"}
    if request.method == "POST":
        f = request.form
        module = _normalize_media_module(f.get("module", "medical_aesthetic"))
        phase = _normalize_media_phase(f.get("phase", "before"))
        if phase not in allowed_phases:
            phase = "followup"
        title = f.get("title", "").strip()
        note = f.get("note", "").strip()
        captured_date = f.get("captured_at", "").strip()
        captured_at = (
            f"{captured_date} 12:00:00"
            if re.fullmatch(r"\d{4}-\d{2}-\d{2}", captured_date)
            else datetime.now().isoformat(sep=" ", timespec="seconds"))
        visit_key = f.get("visit_key", "").strip() or None
        shortcut_paths = f.get("shortcut_paths", "").strip()
        shortcut_recursive = f.get("shortcut_recursive") == "on"
        saved = 0
        had_input = bool(shortcut_paths)
        for uf in request.files.getlist("files"):
            if uf and uf.filename:
                had_input = True
            try:
                if _save_archive_upload(
                        patient_key, module, phase, uf,
                        title=title, note=note, visit_key=visit_key,
                        captured_at=captured_at):
                    saved += 1
            except Exception as ex:
                flash(f"Medya yuklenemedi: {ex}", "warning")
        if shortcut_paths:
            shortcut_result = _save_archive_shortcut_paths(
                patient_key, shortcut_paths, module, phase, title=title,
                note=note, visit_key=visit_key, captured_at=captured_at,
                recursive=shortcut_recursive)
            saved += shortcut_result["saved"]
