def _ensure_ai_phone_schema(con=None):
    def _run(open_con):
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS ai_phone_calls (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                caller TEXT,
                device_id INTEGER,
                transcript TEXT NOT NULL,
                ai_reply TEXT NOT NULL,
                status TEXT DEFAULT 'draft',
                created_at TEXT NOT NULL,
                handled_by TEXT
            )
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_ai_phone_calls_created
            ON ai_phone_calls(created_at DESC)
        """)
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS ai_phone_pending_appointments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                token TEXT UNIQUE NOT NULL,
                caller TEXT,
                patient_key TEXT NOT NULL,
                patient_name TEXT,
                appointment_date TEXT NOT NULL,
                appointment_time TEXT NOT NULL,
                purpose TEXT,
                note TEXT,
                status TEXT DEFAULT 'pending',
                created_at TEXT NOT NULL,
                expires_at TEXT
            )
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_ai_phone_pending_lookup
            ON ai_phone_pending_appointments(caller, status, created_at DESC)
        """)
        try:
            cols = set()
            for row in open_con.execute(
                    "PRAGMA table_info(ai_phone_calls)").fetchall():
                if isinstance(row, dict):
                    cols.add(str(row.get("name") or ""))
                else:
                    cols.add(str(row[1]))
            for col, ddl in (
                ("staff_status",
                 "ALTER TABLE ai_phone_calls "
                 "ADD COLUMN staff_status TEXT DEFAULT 'open'"),
                ("staff_note",
                 "ALTER TABLE ai_phone_calls ADD COLUMN staff_note TEXT"),
                ("handled_at",
                 "ALTER TABLE ai_phone_calls ADD COLUMN handled_at TEXT"),
                ("source_channel",
                 "ALTER TABLE ai_phone_calls "
                 "ADD COLUMN source_channel TEXT DEFAULT 'phone'"),
            ):
                if col not in cols:
                    open_con.execute(ddl)
        except Exception:
            pass
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_ai_phone_calls_staff
            ON ai_phone_calls(staff_status, created_at DESC)
        """)
    if con is not None:
        _run(con)
        return
    with db_conn() as open_con:
        _run(open_con)
        open_con.commit()


