def _ai_phone_handoff_keywords(settings=None):
    settings = settings or _ai_phone_settings()
    raw = str(settings.get("ai_phone_handoff_keywords") or "")
    keywords = []
    for part in re.split(r"[,;\n]+", raw):
        folded = _fold_search_text(part.strip())
        if folded and folded not in keywords:
            keywords.append(folded)
    return keywords


def _ai_phone_should_handoff(text, settings=None, status=""):
    folded = _fold_search_text(text)
    if not folded:
        return False
    if str(status or "").lower() in {"fallback", "needs_human", "manual_handoff"}:
        return True
    return any(keyword and keyword in folded
               for keyword in _ai_phone_handoff_keywords(settings))


def _ai_phone_handoff_reply(settings=None, caller="", transcript=""):
    settings = settings or _ai_phone_settings()
    reply = str(settings.get("ai_phone_live_assistant_text") or "").strip()
    if not reply:
        reply = str(settings.get("ai_phone_escalation_text") or "").strip()
    phone = str(settings.get("ai_phone_live_assistant_phone") or "").strip()
    if phone:
        reply = f"{reply} Asistan dahili/telefon: {phone}."
    return reply


def _ai_phone_tts_profile_key(profile=None):
    raw = str(profile or _ai_phone_settings().get("ai_phone_voice_profile")
              or "tr_lokal_piper").strip()
    folded = _fold_search_text(raw)
    mapped = AI_PHONE_TTS_LEGACY_PROFILE_MAP.get(raw) or AI_PHONE_TTS_LEGACY_PROFILE_MAP.get(folded)
    if mapped:
        return mapped
    if raw in AI_PHONE_TTS_VOICES:
        return raw
    for key in AI_PHONE_TTS_VOICES:
        if key.lower() == raw.lower():
            return key
    if "ahmet" in folded or "erkek" in folded:
        return "tr_premium_erkek"
    if "piper" in folded or "dfki" in folded or "aksansiz" in folded:
        return "tr_lokal_piper"
    if "emel" in folded or "kadin" in folded or "dogal" in folded:
        return "tr_premium_kadin"
    return "tr_lokal_piper"


def _ai_phone_tts_rate_percent(rate_value):
    try:
        rate = float(str(rate_value or "0.98").replace(",", "."))
    except Exception:
        rate = 0.98
    rate = max(0.72, min(1.25, rate))
    percent = int(round((rate - 1.0) * 100))
    return f"{percent:+d}%"


