def _ai_phone_tts_cache_get(key):
    with _AI_PHONE_TTS_LOCK:
        item = _AI_PHONE_TTS_CACHE.get(key)
        if item:
            _AI_PHONE_TTS_CACHE.move_to_end(key)
        return item


def _ai_phone_tts_cache_put(key, value):
    with _AI_PHONE_TTS_LOCK:
        _AI_PHONE_TTS_CACHE[key] = value
        _AI_PHONE_TTS_CACHE.move_to_end(key)
        while len(_AI_PHONE_TTS_CACHE) > 48:
            _AI_PHONE_TTS_CACHE.popitem(last=False)


