_ALEX_MEMORY_TABLE_READY = False


def _alex_db_path():
    """Alex tablolari icin direkt DB path (config.env'den)."""
    return (os.environ.get("YAZKLINIK_DB_PATH")
            or r"D:\YazKlinik_Final_D300\local_db\yazklinik_v68.sqlite3")


def _alex_db_conn():
    """Sqlite3 direkt connection - commit garantili (db_conn helper'i v68'den
    geliyor, muhtemelen farkli DB veya rollback nedeniyle sorunlu)."""
    import sqlite3 as _sql
    con = _sql.connect(_alex_db_path(), timeout=10)
    con.execute("PRAGMA journal_mode=WAL")
    con.execute("PRAGMA synchronous=NORMAL")
    return con


def _alex_exec(sql, params=(), commit=False, fetch=None):
    """Alex helper DB execute wrapper. commit=True INSERT/UPDATE/DELETE icin."""
    con = _alex_db_conn()
    try:
        cur = con.execute(sql, params or ())
        if fetch == 'all':
            return list(cur.fetchall())
        elif fetch == 'one':
            return cur.fetchone()
        if commit:
            con.commit()
        return cur.lastrowid
    finally:
        con.close()


def _alex_exec_script(statements_with_params):
    """Birden cok statement'i tek transaction'da calistir."""
    con = _alex_db_conn()
    try:
        for sql, params in statements_with_params:
            con.execute(sql, params or ())
        con.commit()
    finally:
        con.close()


def _alex_memory_init():
    """Alex konusma hafiza tablosu - bir kez yarat."""
    global _ALEX_MEMORY_TABLE_READY
    if _ALEX_MEMORY_TABLE_READY:
        return
    try:
        con = _alex_db_conn()
        try:
            con.execute("""
                CREATE TABLE IF NOT EXISTS alex_memory (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_key TEXT NOT NULL,
                    turn_ts INTEGER NOT NULL,
                    role TEXT NOT NULL,
                    content TEXT NOT NULL
                )
            """)
            con.execute("""
                CREATE INDEX IF NOT EXISTS idx_alex_memory_user_ts
                ON alex_memory(user_key, turn_ts DESC)
            """)
            con.commit()
        finally:
            con.close()
        _ALEX_MEMORY_TABLE_READY = True
        try:
            print(f"[ALEX-MEM] tablo init OK -> {_alex_db_path()}", flush=True)
        except Exception:
            pass
    except Exception as exc:
        try:
            print(f"[ALEX-MEM] INIT HATA: {exc}", flush=True)
        except Exception:
            pass


def _alex_memory_get(user_key, limit=20):
    """Son N turn'u doner (kronolojik: eski->yeni).

    Default limit=20 -> son 20 user + 20 Alex mesaji = 40 satir.
    Kullanici "kalici hafiza" istiyor; cok eski mesajlar prompt'a yuklenmiyor
    (LLM context limit) ama DB'de saklanmaya devam ediyor.
    """
    _alex_memory_init()
    try:
        con = _alex_db_conn()
        try:
            cur = con.execute(
                "SELECT role, content FROM alex_memory "
                "WHERE user_key = ? ORDER BY turn_ts DESC LIMIT ?",
                (str(user_key or "anon"), int(limit) * 2))
            rows = list(cur.fetchall())
        finally:
            con.close()
        return list(reversed(rows))
    except Exception:
        return []


def _alex_memory_append(user_key, role, content):
    """Yeni mesaji history'ye ekle. Debug log aktif."""
    _alex_memory_init()
    content = str(content or "").strip()
    if not content:
        try:
            print(f"[ALEX-MEM] SKIP: bos content (user={user_key} role={role})",
                  flush=True)
        except Exception:
            pass
        return
    if len(content) > 2000:
        content = content[:2000]
    try:
        con = _alex_db_conn()
        try:
            con.execute(
                "INSERT INTO alex_memory (user_key, turn_ts, role, content) "
                "VALUES (?, ?, ?, ?)",
                (str(user_key or "anon"), int(time.time() * 1000),
                 str(role), content))
            con.commit()
        finally:
            con.close()
        try:
            print(f"[ALEX-MEM] SAVED user={user_key} role={role} "
                  f"content={content[:60]!r}", flush=True)
        except Exception:
            pass
    except Exception as exc:
        try:
            print(f"[ALEX-MEM] HATA: {type(exc).__name__}: {exc}", flush=True)
        except Exception:
            pass


def _alex_memory_prune(user_key, keep=40):
    """Eski mesajlari sil, en son 40 mesaji (yaklasik 20 turn) koru."""
    try:
        with db_conn() as con:
            con.execute(
                "DELETE FROM alex_memory WHERE user_key = ? AND id NOT IN "
                "(SELECT id FROM alex_memory WHERE user_key = ? "
                "ORDER BY turn_ts DESC LIMIT ?)",
                (str(user_key or "anon"), str(user_key or "anon"), int(keep)))
    except Exception:
        pass


def _alex_memory_format_for_prompt(history_rows):
    """[(role, content), ...] -> prompt-friendly string."""
    if not history_rows:
        return ""
    lines = []
    for role, content in history_rows:
        speaker = "Kullanici" if role == "user" else "Alex"
        lines.append(f"{speaker}: {content}")
    return "\n".join(lines)


def _alex_memory_clear(user_key):
    """Kullanicinin tum Alex hafizasini sil."""
    try:
        _alex_exec("DELETE FROM alex_memory WHERE user_key = ?",
                   (str(user_key or "anon"),), commit=True)
    except Exception:
        pass


