def _alex_command_add(user_key, trigger_phrase, action_text,
                      action_type="llm", description=""):
    _alex_learning_init()
    try:
        trigger_phrase = str(trigger_phrase or "").strip().lower()
        action_text = str(action_text or "").strip()
        action_type = str(action_type or "llm").strip().lower()
        if action_type not in ("llm", "shell", "open_app", "file", "url"):
            action_type = "llm"
        if not trigger_phrase or not action_text:
            return False
        if len(trigger_phrase) > 200 or len(action_text) > 1500:
            return False
        _alex_exec(
            "INSERT INTO alex_commands "
            "(user_key, trigger_phrase, action_type, action_text, "
            "description, created_ts) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (str(user_key or "anon"), trigger_phrase, action_type,
             action_text, str(description or "")[:300],
             int(time.time() * 1000)), commit=True)
        return True
    except Exception:
        return False


def _alex_command_delete(cmd_id, user_key=None):
    _alex_learning_init()
    try:
        if user_key:
            _alex_exec("DELETE FROM alex_commands WHERE id = ? AND user_key = ?",
                       (int(cmd_id), str(user_key)), commit=True)
        else:
            _alex_exec("DELETE FROM alex_commands WHERE id = ?",
                       (int(cmd_id),), commit=True)
        return True
    except Exception:
        return False


def _alex_match_command(user_key, user_text):
    """Kullanicinin metni bir custom command trigger'i ile eslesir mi?

    Geri donus: (action_type, action_text, description) tuple veya None.
    Esleme: kullanici_text icinde trigger_phrase substring (case-insensitive).
    """
    _alex_learning_init()
    try:
        text_lower = str(user_text or "").lower().strip()
        if not text_lower:
            return None
        rows = _alex_exec(
            "SELECT id, trigger_phrase, action_type, action_text, description "
            "FROM alex_commands WHERE user_key = ?",
            (str(user_key or "anon"),), fetch='all') or []
        rows.sort(key=lambda r: len(r[1] or ""), reverse=True)
        for cmd_id, trigger, action_type, action, desc in rows:
            if trigger and trigger.lower() in text_lower:
                try:
                    _alex_exec(
                        "UPDATE alex_commands SET used_count = used_count + 1 "
                        "WHERE id = ?", (cmd_id,), commit=True)
                except Exception:
                    pass
                return (action_type or "llm", action, desc or "")
        return None
    except Exception:
        return None


def _alex_facts_format_for_prompt(facts):
    if not facts:
        return ""
    lines = []
    for f in facts:
        cat = f.get("category", "genel")
        text = f.get("fact", "")
        lines.append(f"- [{cat}] {text}")
    return "\n".join(lines)


