def _yaz_knowledge_init():
    try:
        con = _alex_db_conn()
        try:
            con.execute("""
                CREATE TABLE IF NOT EXISTS yaz_llm_knowledge_feed (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_key TEXT NOT NULL,
                    agent_id TEXT NOT NULL,
                    topic TEXT NOT NULL,
                    source TEXT NOT NULL,
                    source_quality TEXT DEFAULT '',
                    summary TEXT DEFAULT '',
                    details_json TEXT DEFAULT '[]',
                    result_count INTEGER DEFAULT 0,
                    learned_fact_id TEXT DEFAULT '',
                    status TEXT DEFAULT 'learned',
                    created_ts INTEGER NOT NULL
                )
            """)
            con.execute("""
                CREATE INDEX IF NOT EXISTS idx_yaz_knowledge_user
                ON yaz_llm_knowledge_feed(user_key, created_ts DESC)
            """)
            con.execute("""
                CREATE INDEX IF NOT EXISTS idx_yaz_knowledge_agent
                ON yaz_llm_knowledge_feed(agent_id, created_ts DESC)
            """)
            con.commit()
        finally:
            con.close()
    except Exception as exc:
        try:
            print(f"[YAZ-KNOW] init HATA: {exc}", flush=True)
        except Exception:
            pass


def _yaz_knowledge_save(user_key, agent_id, topic, source, source_quality,
                        summary, results, fact_id="", status="learned"):
    _yaz_knowledge_init()
    try:
        import json as _json
        con = _alex_db_conn()
        try:
            cur = con.execute(
                "INSERT INTO yaz_llm_knowledge_feed "
                "(user_key, agent_id, topic, source, source_quality, summary, "
                "details_json, result_count, learned_fact_id, status, created_ts) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (str(user_key or "anon"), str(agent_id or "manual"),
                 str(topic or ""), str(source or ""), str(source_quality or ""),
                 str(summary or ""), _json.dumps(results or [], ensure_ascii=False),
                 int(len(results or [])), str(fact_id or ""), str(status or "learned"),
                 int(time.time() * 1000)))
            con.commit()
            return int(cur.lastrowid or 0)
        finally:
            con.close()
    except Exception as exc:
        try:
            print(f"[YAZ-KNOW] save HATA: {exc}", flush=True)
        except Exception:
            pass
        return 0


def _yaz_knowledge_recent(user_key, limit=25):
    _yaz_knowledge_init()
    try:
        con = _alex_db_conn()
        try:
            cur = con.execute(
                "SELECT id, agent_id, topic, source, source_quality, summary, "
                "result_count, learned_fact_id, status, created_ts "
                "FROM yaz_llm_knowledge_feed WHERE user_key = ? "
                "ORDER BY created_ts DESC LIMIT ?",
                (str(user_key or "anon"), int(limit)))
            rows = list(cur.fetchall())
        finally:
            con.close()
        cols = ("id", "agent_id", "topic", "source", "source_quality",
                "summary", "result_count", "learned_fact_id", "status",
                "created_ts")
        return [dict(zip(cols, r)) for r in rows]
    except Exception:
        return []


def _yaz_knowledge_stats(user_key=None):
    _yaz_knowledge_init()
    out = {"total": 0, "strong": 0, "recent_24h": 0, "facts": 0,
           "last_ts": 0}
    try:
        day_ago = int((time.time() - 86400) * 1000)
        where = "WHERE user_key = ?" if user_key else ""
        args = (str(user_key),) if user_key else ()
        con = _alex_db_conn()
        try:
            row = con.execute(
                "SELECT COUNT(*), "
                "SUM(CASE WHEN source_quality='strong' THEN 1 ELSE 0 END), "
                "SUM(CASE WHEN created_ts >= ? THEN 1 ELSE 0 END), "
                "SUM(CASE WHEN COALESCE(learned_fact_id,'')<>'' THEN 1 ELSE 0 END), "
                "MAX(created_ts) FROM yaz_llm_knowledge_feed " + where,
                ((day_ago,) + args) if args else (day_ago,)).fetchone()
        finally:
            con.close()
        if row:
            out.update({
                "total": int(row[0] or 0),
                "strong": int(row[1] or 0),
                "recent_24h": int(row[2] or 0),
                "facts": int(row[3] or 0),
                "last_ts": int(row[4] or 0),
            })
    except Exception:
        pass
    return out


def _yaz_result_quality(results, source):
    if (source or "").lower() == "pubmed":
        return {"tier": "strong", "score": 100, "label": "PubMed"}
    scores = []
    labels = []
    for r in results or []:
        prof = _yaz_source_profile(r.get("url") or "", source=source)
        r["source_profile"] = prof
        scores.append(int(prof.get("score") or 0))
        if prof.get("label"):
            labels.append(str(prof.get("label")))
    if not scores:
        return {"tier": "unknown", "score": 0, "label": "Kaynak yok"}
    avg = sum(scores) / max(len(scores), 1)
    tier = "strong" if avg >= 80 else ("medium" if avg >= 55 else "unknown")
    return {"tier": tier, "score": int(avg),
            "label": ", ".join(sorted(set(labels))[:4])}


def _yaz_trusted_web_results(query, max_results=6):
    terms = str(query or "").strip()
    trusted_query = (
        terms + " (site:acog.org OR site:smfm.org OR site:rcog.org.uk "
        "OR site:nice.org.uk OR site:who.int OR site:cdc.gov OR site:nih.gov "
        "OR site:fda.gov OR site:ema.europa.eu OR site:saglik.gov.tr "
        "OR site:titck.gov.tr)"
    )
    raw = _alex_research_web(trusted_query, max_results=max_results + 8)
    filtered = []
    for item in raw:
        prof = _yaz_source_profile(item.get("url") or "", source="trusted_web")
        item["source_profile"] = prof
        if int(prof.get("score") or 0) >= 70:
            filtered.append(item)
    return filtered[:max_results]


def _yaz_run_info_agent(user_key, agent_id, topic_override="", promote=True,
                        max_results=5):
    agent = _yaz_info_agent_by_id(agent_id)
    if not agent:
        return {"ok": False, "error": "ajan bulunamadi"}
    topic = (str(topic_override or "").strip() or agent.get("topic") or "")
    source = str(agent.get("source") or "pubmed").lower()
    if source == "pubmed":
        results = _alex_research_pubmed(topic, max_results=max_results)
        synth_source = "pubmed"
    else:
        results = _yaz_trusted_web_results(topic, max_results=max_results)
        synth_source = "web"
    if not results:
        return {
            "ok": False,
            "agent": agent,
            "source": source,
            "query": topic,
            "error": "guvenilir kaynak sonucu bulunamadi",
            "results": [],
        }
    quality = _yaz_result_quality(results, "pubmed" if source == "pubmed"
                                  else "trusted_web")
    synth = _alex_research_synthesize(topic, results, source=synth_source)
    summary = str(synth.get("summary") or "").strip()
    if not synth.get("ok") or not summary:
        return {
            "ok": False,
            "agent": agent,
            "source": source,
            "query": topic,
            "error": summary or "LLM sentezi basarisiz",
            "results": results,
            "source_quality": quality,
        }
    try:
        _alex_research_save(
            user_key, "pubmed" if source == "pubmed" else "trusted_web",
            topic, summary, results, len(results))
    except Exception:
        pass
    fact_id = ""
    if promote:
        src_refs = []
        for i, r in enumerate(results[:5], 1):
            if source == "pubmed":
                src_refs.append(f"{i}) PMID {r.get('pmid','')}: {r.get('url','')}")
            else:
                prof = r.get("source_profile") or {}
                src_refs.append(f"{i}) {prof.get('label','web')}: {r.get('url','')}")
        fact_text = (
            f"[YAZ kaynakli bilgi / {agent.get('name')} / "
            f"{quality.get('tier')} kaynak] Konu: {topic}. "
            f"Ozet: {summary[:1400]} Kaynaklar: " + " | ".join(src_refs)
        )
        fact_id = _alex_fact_add(user_key, fact_text,
                                 category="kaynakli_bilgi") or ""
    feed_id = _yaz_knowledge_save(
        user_key, agent.get("id"), topic,
        "pubmed" if source == "pubmed" else "trusted_web",
        quality.get("tier"), summary, results, fact_id=fact_id,
        status="learned" if fact_id else "researched")
    return {
        "ok": True,
        "id": feed_id,
        "agent": agent,
        "source": source,
        "query": topic,
        "summary": summary,
        "detailed": synth.get("detailed") or "",
        "model": synth.get("model") or "",
        "results": results,
        "result_count": len(results),
        "source_quality": quality,
        "fact_id": fact_id,
    }


def _yaz_info_agents_payload(user_key):
    stats = _yaz_knowledge_stats(user_key)
    recent = _yaz_knowledge_recent(user_key, limit=20)
    agents = _yaz_info_agent_templates()
    return {
        "ok": True,
        "agents": agents,
        "stats": stats,
        "recent": recent,
        "trusted_sources": [
            {"domain": d, "label": label, "tier": tier, "score": score}
            for d, label, tier, score in _YAZ_TRUSTED_SOURCE_RULES
        ],
        "guardrail": (
            "YAZ bilgi ajanlari sadece kaynakli ozet uretir. Tani, tedavi, "
            "recete ve hasta karari hekim onayi olmadan otomatik uygulanmaz."
        ),
    }


def _alex_detect_url_intent(text):
    """Kullanici 'su linki oku' / 'bu URL'i ozetle' dedi mi? URL cikar."""
    if not text:
        return None
    import re as _re
    # Once dogrudan URL tara
    m = _re.search(r"https?://[^\s'\"<>]+", text)
    if m:
        url = m.group(0).rstrip(".,;:!?)")
        # 'oku', 'ozetle', 'incele' gibi trigger kelime gerekli (cunku salt
        # URL paylasmak istemeyebilir)
        triggers = [
            r"\boku(yup)?\b", r"\bozetle(r misin)?\b",
            r"\bincele(r misin)?\b", r"\baraştir\b", r"\barastir\b",
            r"\bbak\b", r"\baç\b", r"\bac\b",
        ]
        if any(_re.search(t, text, _re.IGNORECASE) for t in triggers):
            return url
        # Trigger yoksa da URL var ve cumle kisa ise (sadece URL) ozetle
        if len(text.strip()) < len(url) + 20:
            return url
    return None


def _alex_detect_promote_intent(text):
    """Kullanici 'bunu ogren' / 'kalici kaydet' dedi mi?"""
    if not text:
        return False
    import re as _re
    pat = _re.compile(
        r"\b(bunu\s+(?:ogren|öğren|aklında\s+tut|aklinda\s+tut|hatirla|hatırla)"
        r"|kalici\s+kaydet|kalıcı\s+kaydet|kalıcı\s+öğren|kalici\s+ogren"
        r"|ezberle|notuna\s+ekle|hafızana\s+kaydet|hafizana\s+kaydet"
        r"|bu\s+bilgiyi\s+sakla)\b",
        _re.IGNORECASE)
    return bool(pat.search(text))


def _alex_detect_reset_intent(text):
    """Kullanici 'yeni konu', 'unut', 'konuyu degistir' dedi mi?

    Sohbet hafizasini temizler - eski konular yeni soruda tekrar etmesin.
    Sadece konusma history; facts ve arastirma kalir.

    D300: Sadece 'yeni konu actim dun' gibi false positive olmasin diye
    cumlenin ANA NIYETI reset olmali - max 6 kelime + spesifik anahtar.
    """
    if not text:
        return False
    t = str(text).strip()
    if len(t.split()) > 6:
        return False
    import re as _re
    pat = _re.compile(
        r"\b(yeni\s+konu|baska\s+konu|konuyu\s+(degistir|değiştir|unut|kapat)"
        r"|sohbeti\s+(sifirla|sıfırla|unut|temizle)"
        r"|hafiza(sini|sını)?\s+(sifirla|sıfırla|temizle|unut)"
        r"|gecmisi\s+(unut|sil|temizle)|geçmişi\s+(unut|sil|temizle)"
        r"|temiz\s+(baslayalim|başlayalım)"
        r"|her\s+sey(?:i)?\s+unut|her\s+şey(?:i)?\s+unut)\b",
        _re.IGNORECASE)
    return bool(pat.search(t))


def _alex_is_meaningful_input(text):
    """Whisper halusinasyon + bos garland tespiti.

    Donus: (is_meaningful: bool, reason: str)
    False ise -> LLM cagrilmadan kibarca 'Tekrar eder misin' / sessizlik.
    Memory'e de SAVE etme - garbage history birikmesin.

    Tetikleyiciler (False sebepleri):
      - Bos / 2 karakterden kisa
      - Whisper sabit halusinasyon: "Altyazi M.K", "Thank you", subtitle vb
      - Tek interjeksiyon: "Mmh", "Ha?", "Alo?", "Eee"
      - Ayni kelime 3+ tekrar: "Pazartesi pazartesi pazartesi"
      - Yabanci garland karakter yogunlugu: "Şimli garzim yego"
    """
    if not text:
        return False, "bos"
    import re as _re
    t = str(text).strip()
    if len(t) < 3:
        return False, "cok kisa"
    tl = t.lower()
    # 1) Whisper bilinen halusinasyon paternleri
    HALU = ("altyazı m.k", "altyazi m.k", "altyazı:", "altyazi:",
            "altyazı m k", "altyazi m k", "altyazı ", "altyazi ",
            "subtitle", "thank you", "thanks for watching",
            "thanks for", "subscribe", "youtube", "captions by",
            " m.k.", " m. k.", "amara.org", "translated by")
    for p in HALU:
        if p in tl:
            return False, f"halusinasyon: {p}"
    # tek basina "altyazı m.k." gibi
    if tl.rstrip(".,!?") in ("altyazı m.k", "altyazi m.k", "altyazı",
                              "altyazi", "m.k", "m k"):
        return False, "halusinasyon: altyazi"
    # 2) Tek interjeksiyon (kelime parcasi)
    INTERJ = {"ha", "ah", "hm", "hmm", "mhm", "mmh", "mm", "ya",
              "ee", "eee", "eeee", "uh", "uhm", "uhh", "ohh", "oh",
              "alo", "alô", "of", "ahh", "um", "umm", "ummm",
              "hi", "hey", "ok", "okey", "ay", "ayy"}
    core = _re.sub(r"[.,!?;:\"'\s]+", " ", tl).strip()
    if core in INTERJ:
        return False, f"interjeksiyon: {core}"
    # 3) Ayni kelime 2+ tekrar (Whisper repeat loop) - daha sert: 2 yeter
    words = [w for w in _re.split(r"[\s.,!?;:\"']+", tl) if w]
    if len(words) >= 2:
        from collections import Counter as _C
        top_word, top_n = _C(words).most_common(1)[0]
        # 2 tekrar = sik / 3+ tekrar = kesin halusinasyon
        if (top_n >= 3 and top_n / len(words) >= 0.55) or \
           (top_n >= 2 and len(words) == top_n):  # "X, X" / "X X"
            return False, f"tekrar: '{top_word}' x{top_n}"
    # 4) Yabanci garland: TR olmayan + ASCII olmayan ozel karakter
    suspicious = "ÅÄÆØÞĐßΩΠλμπνρτυψ"
    if any(c in suspicious for c in t):
        return False, "yabanci garland"
    # 5) Tek kelime context'siz (Whisper sik halusinasyonu): SADECE komut
    #    kelimeleri gecer. Doktor gercekten soru soracaksa cumle kurar.
    SOLO_OK = {
        # Yanit
        "evet", "hayir", "hayır", "yok", "var", "tamam", "olur",
        "peki", "iyi", "tabii", "tabi",
        # Komut (Alex'i durdur/devam)
        "dur", "sus", "bekle", "devam", "tamamla", "iptal",
        "tekrar", "tekrarla", "sil", "kaydet", "kapat", "ac",
        # Tesekkur/kibar
        "tesekkur", "tesekkürler", "tesekkurler", "sagol", "sağol",
    }
    if len(words) == 1 and words[0] not in SOLO_OK:
        return False, f"tek kelime baglamsiz: '{words[0]}'"
    # 6) Whisper STT sabit tek-kelime halusinasyonlari (takvim, sayi, vb)
    #    Doktor cumlede gecerse OK; tek/iki kelime ise SUSPECT.
    WHISPER_LONE = {
        "pazartesi", "sali", "salı", "carsamba", "çarşamba",
        "persembe", "perşembe", "cuma", "cumartesi", "pazar",
        "ocak", "subat", "şubat", "mart", "nisan", "mayis",
        "mayıs", "haziran", "temmuz", "agustos", "ağustos",
        "eylul", "eylül", "ekim", "kasim", "kasım", "aralik",
        "aralık",
    }
    if len(words) <= 2 and any(w in WHISPER_LONE for w in words):
        return False, f"whisper takvim halusinasyon: {' '.join(words)}"
    return True, "ok"


def _alex_detect_stop_intent(text):
    """Kullanici 'sus', 'dur', 'tamam yeter' dedi mi? Sozlu kesme isareti.

    Alex konusurken kullanici sozlu kesme yapar. Voice-turn'da bu intent
    varsa cok kisa cevap ver ve ekstra konusma uretme.

    D300 FIX: Eskiden 'tamam sana sorum var' gibi cumlelerde 'tamam' false
    pozitif tetikliyordu - cevap 20 token'a kesilip diksiyon bozuluyordu.
    Artik SADECE cok kisa (max 4 kelime) metinde aktif.
    """
    if not text:
        return False
    t = str(text).strip().lower()
    # Cok kisa metin degilse kabul etme - normal cumlede "tamam" gecsen kesme
    words = t.split()
    if len(words) > 4:
        return False
    # Kisa direkt komutlar
    if t in ("dur", "sus", "yeter", "tamam yeter", "tamam tamam",
             "alex dur", "alex sus", "alex yeter", "alex bekle",
             "alex kes", "kes", "alex tamam", "sus alex", "dur alex",
             "tamam alex", "alex sus artik", "sus artik",
             "kes alex", "dur artik", "yeter artik"):
        return True
    # Regex pattern - sadece kisa metinde
    import re as _re
    pat = _re.compile(
        r"^\s*(alex\s+)?(sus|dur|kes|yeter|bekle)(\s+(alex|artik))?\s*[.!?]?\s*$",
        _re.IGNORECASE)
    return bool(pat.match(t))


