# D300 CANLI VERI: TCMB doviz kurlari + Google News RSS haberleri
# ============================================================================

def _alex_fetch_currency_rates(timeout=10):
    """TCMB resmi anlik kurlar (XML). Free, no key.

    Returns: dict {date, rates: {USD: {buy, sell, name}, EUR: {...}, ...}}
    """
    import urllib.request as _ureq
    import xml.etree.ElementTree as _ET
    url = "https://www.tcmb.gov.tr/kurlar/today.xml"
    try:
        with _ureq.urlopen(url, timeout=timeout) as resp:
            xml_data = resp.read().decode("utf-8", errors="replace")
        root = _ET.fromstring(xml_data)
    except Exception as exc:
        return {"ok": False, "error": f"TCMB erişilemedi: {exc}"}
    date = root.get("Date") or root.get("Tarih") or ""
    rates = {}
    for curr in root.findall("Currency"):
        code = curr.get("Kod") or curr.get("CurrencyCode") or ""
        if not code:
            continue
        try:
            unit = int((curr.findtext("Unit") or "1") or 1)
        except Exception:
            unit = 1
        try:
            forex_buy = (curr.findtext("ForexBuying") or "").strip()
            forex_sell = (curr.findtext("ForexSelling") or "").strip()
            banknote_buy = (curr.findtext("BanknoteBuying") or "").strip()
            banknote_sell = (curr.findtext("BanknoteSelling") or "").strip()
            name = (curr.findtext("Isim") or
                    curr.findtext("CurrencyName") or "").strip()
        except Exception:
            continue
        rates[code] = {
            "name": name,
            "unit": unit,
            "forex_buy": forex_buy,
            "forex_sell": forex_sell,
            "banknote_buy": banknote_buy,
            "banknote_sell": banknote_sell,
        }
    return {"ok": True, "date": date, "rates": rates}


def _alex_format_currency_for_prompt(want_codes=None):
    """TCMB kurlarini Alex prompt'una ozet olarak ver."""
    data = _alex_fetch_currency_rates()
    if not data.get("ok"):
        return f"[Doviz kurlari su an alinamadi: {data.get('error','')}]"
    rates = data.get("rates", {})
    want = (want_codes if want_codes
            else ["USD", "EUR", "GBP", "CHF", "JPY", "RUB"])
    lines = [f"TCMB resmi kurlar ({data.get('date','')})  - 1 birim icin TL:"]
    for code in want:
        r = rates.get(code) or rates.get(code.upper())
        if not r:
            continue
        unit = r.get("unit", 1)
        unit_str = f" ({unit} birim)" if unit != 1 else ""
        fb = r.get("forex_buy", "-")
        fs = r.get("forex_sell", "-")
        bn = r.get("banknote_sell", "-")
        lines.append(
            f"- {code}{unit_str} {r.get('name','')}: "
            f"alis {fb}, satis {fs}, efektif satis {bn}")
    return "\n".join(lines)


def _alex_fetch_news_rss(topic="", limit=8, timeout=10):
    """Google News RSS Turkce - free, no key.

    topic bos ise ana sayfa son haberleri; topic varsa konu araması.
    Returns: list of {title, link, published, source, snippet}
    """
    import urllib.request as _ureq
    import urllib.parse as _uparse
    import xml.etree.ElementTree as _ET
    import html as _html
    import re as _re
    topic = (topic or "").strip()
    if topic:
        url = (f"https://news.google.com/rss/search?q={_uparse.quote(topic)}"
               f"&hl=tr&gl=TR&ceid=TR:tr")
    else:
        url = "https://news.google.com/rss?hl=tr&gl=TR&ceid=TR:tr"
    req = _ureq.Request(url, headers={
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64) Alex/D300",
        "Accept": "application/rss+xml, application/xml, */*",
    })
    try:
        with _ureq.urlopen(req, timeout=timeout) as resp:
            data = resp.read().decode("utf-8", errors="replace")
        root = _ET.fromstring(data)
    except Exception as exc:
        return []
    items = []
    for item in root.iter("item"):
        if len(items) >= limit:
            break
        try:
            title = (item.findtext("title") or "").strip()
            link = (item.findtext("link") or "").strip()
            pub = (item.findtext("pubDate") or "").strip()
            src_el = item.find("source")
            source = (src_el.text or "").strip() if src_el is not None else ""
            desc = (item.findtext("description") or "").strip()
            snippet = _html.unescape(_re.sub(r"<[^>]+>", " ", desc))
            snippet = _re.sub(r"\s+", " ", snippet).strip()[:280]
            items.append({"title": title, "link": link,
                          "published": pub, "source": source,
                          "snippet": snippet})
        except Exception:
            continue
    return items


def _alex_format_news_for_prompt(topic="", limit=6):
    """Haberleri Alex prompt'una sirali ozet olarak ver."""
    items = _alex_fetch_news_rss(topic=topic, limit=limit)
    if not items:
        return f"[Haberler alinamadi (topic: {topic or 'gundem'})]"
    title = f"haberler '{topic}'" if topic else "Gundem son haberler"
    lines = [f"Google News - {title}:"]
    for i, it in enumerate(items, 1):
        src = f" ({it['source']})" if it.get("source") else ""
        lines.append(f"{i}. {it['title']}{src}")
        if it.get("snippet"):
            lines.append(f"   {it['snippet'][:200]}")
    return "\n".join(lines)


def _alex_detect_currency_intent(text):
    """Kullanici 'dolar kuru', 'euro ne kadar' dedi mi?

    Returns: list of currency codes veya None.
    """
    if not text:
        return None
    import re as _re
    t = str(text).lower()
    # Tetikleyici: "kur", "doviz", "ne kadar" + para birimi
    trigger = _re.search(
        r"\b(kur|kuru|doviz|döviz|ne\s+kadar|kac\s+tl|kaç\s+tl|fiyati|fiyatı)\b",
        t)
    # Para birimi sozluk
    currency_map = {
        "dolar": "USD", "usd": "USD", "amerikan\\s+dolari": "USD",
        "amerikan\\s+doları": "USD",
        "euro": "EUR", "eur": "EUR", "avro": "EUR",
        "pound": "GBP", "sterlin": "GBP", "gbp": "GBP",
        "frank": "CHF", "isvicre": "CHF", "chf": "CHF",
        "yen": "JPY", "jpy": "JPY",
        "ruble": "RUB", "rub": "RUB", "rus\\s+rublesi": "RUB",
        "altin": "XAU", "gram\\s+altin": "XAU",
    }
    found = []
    for pat, code in currency_map.items():
        if _re.search(rf"\b{pat}\b", t):
            if code not in found:
                found.append(code)
    if found:
        return found
    # "kur" / "doviz" + "ler" varsa hepsi
    if trigger and _re.search(r"\b(dovizler|dövizler|kurlar)\b", t):
        return ["USD", "EUR", "GBP", "CHF"]
    # Sadece "doviz kurlari" gibi -> USD+EUR yeter
    if trigger:
        return ["USD", "EUR"]
    return None


def _alex_detect_news_intent(text):
    """Kullanici 'haberler', 'gundem', 'son haberler' dedi mi?

    Returns: topic string or "" (genel gundem) veya None.
    """
    if not text:
        return None
    import re as _re
    t = str(text).strip()
    tl = t.lower()
    # Tetikleyiciler
    triggers = (r"\b(haberler|haberi|son\s+haberler|gundem|gündem|"
                r"bugun\s+ne\s+oldu|bugün\s+ne\s+oldu|son\s+dakika|"
                r"manset|manşet|gunun\s+haberi|günün\s+haberi)\b")
    if not _re.search(triggers, tl):
        return None
    # Konu cikar - trigger kelimeleri at, geri kalan topic
    cleaned = _re.sub(triggers, " ", tl)
    cleaned = _re.sub(
        r"\b(alex|lutfen|lütfen|bana|bugun|bugün|haberi|haberini|haberlerini|"
        r"ne\s+var|var\s+mi|var\s+mı|soyle|söyle|anlat|göster|goster|"
        r"hakkinda|hakkında|konusunda)\b",
        " ", cleaned)
    cleaned = _re.sub(r"\s+", " ", cleaned).strip(" ,.;:?!\"'")
    return cleaned  # bos ise '' = genel gundem


# ============================================================================
# D300 EGITIM: Conversation logging + feedback + LoRA dataset export
# ----------------------------------------------------------------------------
# Kullanici her Alex cevabini 👍/👎/✏️ ile etiketleyebilir veya ideal cevap
# yazabilir. Bu veriler LoRA fine-tuning datasetinde kullanilir.
# ============================================================================

_ALEX_TRAINING_READY = False


def _alex_training_init():
    """alex_training_data tablosunu olustur (idempotent)."""
    global _ALEX_TRAINING_READY
    if _ALEX_TRAINING_READY:
        return
    try:
        con = _alex_db_conn()
        try:
            con.execute("""
                CREATE TABLE IF NOT EXISTS alex_training_data (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_key TEXT NOT NULL,
                    user_text TEXT NOT NULL,
                    alex_response TEXT NOT NULL,
                    ideal_response TEXT,
                    rating INTEGER DEFAULT 0,
                    category TEXT DEFAULT 'chat',
                    model_used TEXT,
                    side_effects TEXT,
                    created_ts INTEGER NOT NULL,
                    rated_ts INTEGER,
                    used_in_training INTEGER DEFAULT 0
                )
            """)
            con.execute(
                "CREATE INDEX IF NOT EXISTS idx_alex_training_rating "
                "ON alex_training_data(rating, created_ts DESC)")
            con.execute(
                "CREATE INDEX IF NOT EXISTS idx_alex_training_user "
                "ON alex_training_data(user_key, created_ts DESC)")
            con.commit()
        finally:
            con.close()
        _ALEX_TRAINING_READY = True
    except Exception as exc:
        try: print(f"[ALEX-TRAIN] init HATA: {exc}", flush=True)
        except Exception: pass


def _alex_training_log(user_key, user_text, alex_response, model="",
                      category="chat", side_effects=None):
    """Her sohbet sonrasi training data tablosuna yaz (rating=0 = unrated).

    voice-turn-text finally bloku bunu cagirir.
    """
    _alex_training_init()
    if not user_text or not alex_response:
        return None
    try:
        import json as _json
        rid = _alex_exec(
            "INSERT INTO alex_training_data "
            "(user_key, user_text, alex_response, model_used, category, "
            "side_effects, created_ts) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (str(user_key or "anon"),
             str(user_text)[:2000], str(alex_response)[:4000],
             str(model or "")[:80], str(category or "chat")[:40],
             _json.dumps(side_effects or []),
             int(time.time() * 1000)),
            commit=True)
        return rid
    except Exception as exc:
        try: print(f"[ALEX-TRAIN] log HATA: {exc}", flush=True)
        except Exception: pass
        return None


def _alex_training_rate(training_id, rating, ideal_response="", user_key=None):
    """Bir kayda 👍 (+1) / 👎 (-1) / nötr (0) rating ver. Ideal cevap eklenirse
    kalici hata duzeltme.
    """
    _alex_training_init()
    try:
        rating = int(rating)
        if rating not in (-1, 0, 1):
            rating = 0
        sets = ["rating = ?", "rated_ts = ?"]
        params = [rating, int(time.time() * 1000)]
        if ideal_response:
            sets.append("ideal_response = ?")
            params.append(str(ideal_response)[:4000])
        sql = f"UPDATE alex_training_data SET {', '.join(sets)} WHERE id = ?"
        params.append(int(training_id))
        if user_key:
            sql += " AND user_key = ?"
            params.append(str(user_key))
        _alex_exec(sql, params, commit=True)
        return True
    except Exception:
        return False


def _alex_training_stats(user_key=None):
    """Dataset istatistikleri."""
    _alex_training_init()
    try:
        where = "WHERE user_key = ?" if user_key else ""
        params = (str(user_key),) if user_key else ()
        total = _alex_exec(
            f"SELECT COUNT(*) FROM alex_training_data {where}",
            params, fetch='one')[0]
        good = _alex_exec(
            f"SELECT COUNT(*) FROM alex_training_data {where + (' AND ' if where else 'WHERE ')}rating = 1",
            params, fetch='one')[0]
        bad = _alex_exec(
            f"SELECT COUNT(*) FROM alex_training_data {where + (' AND ' if where else 'WHERE ')}rating = -1",
            params, fetch='one')[0]
        corrected = _alex_exec(
            f"SELECT COUNT(*) FROM alex_training_data {where + (' AND ' if where else 'WHERE ')}ideal_response IS NOT NULL AND length(ideal_response) > 5",
            params, fetch='one')[0]
        return {"total": total, "good": good, "bad": bad,
                "corrected": corrected, "unrated": total - good - bad}
    except Exception as exc:
        return {"total": 0, "good": 0, "bad": 0, "corrected": 0, "unrated": 0,
                "error": str(exc)}


def _alex_training_recent(user_key=None, limit=50, only_rated=False):
    """Son N kaydi listele."""
    _alex_training_init()
    try:
        sql = (
            "SELECT id, user_text, alex_response, ideal_response, rating, "
            "model_used, category, created_ts FROM alex_training_data WHERE 1=1 ")
        params = []
        if user_key:
            sql += " AND user_key = ?"
            params.append(str(user_key))
        if only_rated:
            sql += " AND rating != 0"
        sql += " ORDER BY created_ts DESC LIMIT ?"
        params.append(int(limit))
        rows = _alex_exec(sql, params, fetch='all') or []
        return [{
            "id": r[0], "user_text": r[1], "alex_response": r[2],
            "ideal_response": r[3] or "", "rating": r[4],
            "model_used": r[5] or "", "category": r[6] or "",
            "created_ts": r[7],
        } for r in rows]
    except Exception:
        return []


def _alex_training_export_jsonl(out_path, only_good=True, include_corrected=True):
    """LoRA training dataset olarak JSONL export.

    Format: her satir {messages: [{role:'system',content:...},
                                  {role:'user',content:user_text},
                                  {role:'assistant',content:final_response}]}
    final_response: ideal_response varsa onu, yoksa alex_response.
    """
    _alex_training_init()
    import json as _json
    sql = ("SELECT user_text, alex_response, ideal_response, rating "
           "FROM alex_training_data WHERE 1=1 ")
    if only_good:
        if include_corrected:
            sql += ("AND (rating = 1 OR "
                    "(ideal_response IS NOT NULL AND length(ideal_response) > 5))")
        else:
            sql += "AND rating = 1"
    sql += " ORDER BY created_ts ASC"
    rows = _alex_exec(sql, fetch='all') or []
    if not rows:
        return 0, "Hic kayit yok"
    sys_prompt = (
        "Sen Alex'sin: Op. Dr. Hakan Yaz (kadin dogum uzmani) icin profesyonel "
        "Turkce sesli asistan. 1-3 cumlede, akici, dogal yanit ver.")
    try:
        with open(out_path, "w", encoding="utf-8") as f:
            n = 0
            for user_text, alex_resp, ideal_resp, rating in rows:
                final = (ideal_resp or "").strip() or (alex_resp or "").strip()
                if not (user_text and final):
                    continue
                ex = {"messages": [
                    {"role": "system", "content": sys_prompt},
                    {"role": "user", "content": str(user_text).strip()},
                    {"role": "assistant", "content": final},
                ]}
                f.write(_json.dumps(ex, ensure_ascii=False) + "\n")
                n += 1
        return n, ""
    except Exception as exc:
        return 0, str(exc)


# ============================================================================
# OLLAMA MODELFILE: kisilik + parametre customize, ollama create yaz
# ============================================================================

def _alex_ollama_modelfile(base_model="llama3.1:8b", system_prompt="",
                          temperature=0.4, num_ctx=4096,
                          custom_params=None):
    """Ollama Modelfile metni uret. `ollama create <ad> -f Modelfile` ile yuklenir."""
    if not system_prompt:
        system_prompt = (
            "Sen Alex'sin: Op. Dr. Hakan YAZ (Kadin Hastaliklari ve Dogum uzmani) "
            "icin calisan profesyonel Turkce sesli asistansin. "
            "1-3 cumlede, akici ve dogal yanit ver. Kisaltma kullanma "
            "(Op. Dr. yerine Operator Doktor, TSH yerine tiroid hormonu). "
            "Soyad/isim buyuk harf yazma. Madde/numara/parantez/yildiz "
            "kullanma. Uc nokta yerine tek nokta. Em dash yerine virgul.")
    lines = [
        f"FROM {base_model}",
        "",
        "# System prompt - Alex kisiligi",
        "SYSTEM " + repr(system_prompt).replace("'", '"'),
        "",
        "# Davranis parametreleri",
        f"PARAMETER temperature {temperature}",
        f"PARAMETER num_ctx {num_ctx}",
        "PARAMETER top_p 0.9",
        "PARAMETER repeat_penalty 1.1",
        "PARAMETER num_predict 250",
    ]
    if custom_params:
        for k, v in custom_params.items():
            lines.append(f"PARAMETER {k} {v}")
    return "\n".join(lines)


def _alex_ollama_create_custom_model(name, base_model="llama3.1:8b",
                                     system_prompt="",
                                     modelfile_dir=None):
    """Modelfile yaz + 'ollama create' calistir.

    Returns: (ok, message)
    """
    import subprocess as _sp
    import tempfile
    if not modelfile_dir:
        modelfile_dir = os.path.join(
            os.path.dirname(__file__) if "__file__" in globals() else ".",
            "ollama_modelfiles")
    try:
        os.makedirs(modelfile_dir, exist_ok=True)
    except Exception:
        modelfile_dir = tempfile.gettempdir()
    safe_name = re.sub(r"[^a-zA-Z0-9_-]", "_", str(name or "yaz"))
    mf_path = os.path.join(modelfile_dir, f"{safe_name}.Modelfile")
    content = _alex_ollama_modelfile(
        base_model=base_model, system_prompt=system_prompt)
    try:
        with open(mf_path, "w", encoding="utf-8") as f:
            f.write(content)
    except Exception as exc:
        return False, f"Modelfile yazilamadi: {exc}"
    try:
        result = _sp.run(
            ["ollama", "create", safe_name, "-f", mf_path],
            capture_output=True, text=True, timeout=120)
        if result.returncode != 0:
            return False, f"ollama create HATA: {result.stderr[:500]}"
        return True, (f"Model '{safe_name}' olusturuldu. "
                      f"Modelfile: {mf_path}")
    except FileNotFoundError:
        return False, "ollama CLI bulunamadi (PATH'te yok)"
    except Exception as exc:
        return False, str(exc)


