def _ai_phone_normalize_tts_text(text):
    """D300: XTTS-v2 Turkce kisaltma/ozel isimleri dogru telaffuz icin normalize.

    Op. Dr. Hakan YAZ -> Operator Doktor Hakan Yaz
    USG, TSH, NT, IVF -> harf harf okuma
    Cumle sonu/noktalama temizligi (XTTS lehce/kurtce gibi seslenmesin):
      ... -> .
      - -- ---  -> ,
      [K1] -> kaynak 1
      Sayilar + birim -> Turkce ("938g" -> "938 gram", "32w0d" -> "32 hafta 0 gun")
    """
    if not text:
        return ""
    import re as _re
    s = str(text)
    # === 0) CUMLE SONU TEMIZLIGI (XTTS bozulmasini onler) ===
    # Tirnak ve ozel char'lar -> sil/donus
    s = s.replace("“", '"').replace("”", '"')  # akilli tirnaklar
    s = s.replace("‘", "'").replace("’", "'")
    s = s.replace("—", ", ")  # em dash
    s = s.replace("–", "-")   # en dash
    s = s.replace("…", ".")   # ellipsis tek nokta
    # Coklu nokta/sorular -> tek
    s = _re.sub(r"\.{2,}", ".", s)
    s = _re.sub(r"\?{2,}", "?", s)
    s = _re.sub(r"!{2,}", "!", s)
    # Parantez/kose icindeki kaynak isaretleri Turkce
    s = _re.sub(r"\[?\(\s*[Kk]\s*([0-9]+)\s*\)\]?", r"kaynak \1", s)
    s = _re.sub(r"\(\s*[Kk]aynak\s+([0-9]+)\s*\)", r"kaynak \1", s)
    # Cift parantez/kose -> sil
    s = _re.sub(r"\[+", " ", s)
    s = _re.sub(r"\]+", " ", s)
    # Emoji / sembol (XTTS okuyamaz, garip ses cikarir)
    s = _re.sub(r"[*_`~|<>{}#@\\^]+", " ", s)
    # Alex bazen hitabi arka arkaya tekrar eder; TTS bunu dogal okumaz.
    s = _re.sub(
        r"\b(doktorum|hocam|doktor)\b(?:[\s,]+\1\b)+",
        r"\1",
        s,
        flags=_re.IGNORECASE)
    # Tek karakterlik orphan punctuation -> sil (sentence end'de hanging .)
    s = _re.sub(r"\s+[,;:]+\s*$", ".", s)
    # === 1) Unvan birlesimleri (Op. Dr. ozellikle - 'op' ayri okunmasin) ===
    title_pairs = [
        (r"\bOp\.\s*Dr\.\s*", "Operatör Doktor "),
        (r"\bUzm\.\s*Dr\.\s*", "Uzman Doktor "),
        (r"\bProf\.\s*Dr\.\s*", "Profesör Doktor "),
        (r"\bDoç\.\s*Dr\.\s*", "Doçent Doktor "),
        (r"\bYrd\.\s*Doç\.\s*Dr\.\s*", "Yardımcı Doçent Doktor "),
        (r"\bAsist\.\s*Dr\.\s*", "Asistan Doktor "),
    ]
    for pat, rep in title_pairs:
        s = _re.sub(pat, rep, s, flags=_re.IGNORECASE)
    # Tekil unvanlar
    single_titles = [
        (r"\bOp\.\s*", "Operatör "),
        (r"\bDr\.\s*", "Doktor "),
        (r"\bUzm\.\s*", "Uzman "),
        (r"\bProf\.\s*", "Profesör "),
        (r"\bDoç\.\s*", "Doçent "),
        (r"\bHst\.\s*", "Hasta "),
        (r"\bSn\.\s*", "Sayın "),
        (r"\bvb\.\s*", "ve benzeri "),
        (r"\bör\.\s*", "örnek "),
        (r"\bbkz\.\s*", "bakınız "),
    ]
    for pat, rep in single_titles:
        s = _re.sub(pat, rep, s, flags=_re.IGNORECASE)
    # === 2) Klinik kisaltmalari harf harf (USG -> U S G) ===
    letter_acronyms = {
        "USG": "U S G", "TSH": "T S H", "FSH": "F S H", "LH": "L H",
        "NT": "N T", "BPD": "B P D", "HC": "H C", "FL": "F L",
        "AC": "A C", "EFW": "E F W", "IVF": "İ V F",
        "MR": "M R", "CT": "C T", "PCR": "P C R", "HCG": "H C G",
        "DICOM": "Daykom", "PACS": "Paks", "EKG": "E K G",
        "HCM": "H C M", "ICSI": "İ C S İ",
        "TKİ": "T K İ", "HKD": "H K D",
        "GA": "G A", "FHR": "fetal kalp atimi", "PI": "P I", "RI": "R I",
        "PMID": "P M I D", "LMP": "L M P", "EDD": "E D D",
    }
    for ac, spelled in letter_acronyms.items():
        s = _re.sub(r"\b" + ac + r"\b", spelled, s)
    # === 3) Sayi + birim Turkce ("938g" -> "938 gram") ===
    unit_map = [
        (r"(\d+(?:[\.,]\d+)?)\s*g(?=\b|\s|$)", r"\1 gram"),
        (r"(\d+(?:[\.,]\d+)?)\s*kg\b", r"\1 kilogram"),
        (r"(\d+(?:[\.,]\d+)?)\s*mg\b", r"\1 miligram"),
        (r"(\d+(?:[\.,]\d+)?)\s*mm\b", r"\1 milimetre"),
        (r"(\d+(?:[\.,]\d+)?)\s*cm\b", r"\1 santimetre"),
        (r"(\d+(?:[\.,]\d+)?)\s*ml\b", r"\1 mililitre"),
        (r"(\d+(?:[\.,]\d+)?)\s*L\b", r"\1 litre"),
        (r"(\d+(?:[\.,]\d+)?)\s*bpm\b", r"\1 atım"),
        (r"(\d+(?:[\.,]\d+)?)\s*%", r"yüzde \1"),
        (r"(\d+(?:[\.,]\d+)?)\s*p\b", r"\1 persantil"),
    ]
    for pat, rep in unit_map:
        s = _re.sub(pat, rep, s, flags=_re.IGNORECASE)
    # GA formati: "32w0d" -> "32 hafta 0 gun"
    s = _re.sub(r"(\d+)\s*w\s*(\d+)\s*d\b",
                r"\1 hafta \2 gün", s, flags=_re.IGNORECASE)
    # === 4) Buyuk harf isimler title case ===
    def _title_case(m):
        return m.group(0).title()
    s = _re.sub(r"\b[A-ZĞÜŞİÖÇ]{2,}\b", _title_case, s)
    # === 5) Final whitespace cleanup ===
    s = _re.sub(r"\s+", " ", s).strip()
    # Trailing orphan punctuation
    s = _re.sub(r"[,;:\-]+\s*([.!?])\s*$", r"\1", s)
    s = s.rstrip(" ,;:-")
    # Eger hala noktalama ile bitmiyorsa nokta ekle (XTTS duzgun finalleyebilsin)
    if s and s[-1] not in ".!?":
        s += "."
    return s


def _ai_phone_should_tts_sentence(sentence):
    """Cumle TTS'e gondermeye degecek kadar anlamli mi?

    XTTS cok kisa fragment'lerde garip (lehce gibi) ses cikariyor.
    Filtreler:
      - Min 4 harf
      - En az 1 sesli harf (Turkce/Ingilizce)
      - Sadece noktalama/sayi ise atla
    """
    if not sentence:
        return False
    import re as _re
    s = sentence.strip()
    # Sadece noktalama / bosluk
    if not _re.search(r"[a-zA-ZğüşıöçĞÜŞİÖÇ]", s):
        return False
    # Cok kisa (3 karakter alti)
    alpha = _re.sub(r"[^a-zA-ZğüşıöçĞÜŞİÖÇ]", "", s)
    if len(alpha) < 3:
        return False
    # En az bir sesli harf (yoksa muhtemelen kisaltma fragment)
    if not _re.search(r"[aeıioöuüAEIİOÖUÜ]", s):
        return False
    return True


def _ai_phone_xtts_voice_from_profile(profile_key, voice_id=""):
    """profile/voice_id -> XTTS voice name (emel|ahmet)."""
    pk = str(profile_key or "").lower()
    vid = str(voice_id or "").lower()
    combined = f"{pk} {vid}"
    if "ahmet" in combined or "erkek" in combined or "male" in combined:
        return "ahmet"
    return "emel"


def _ai_phone_xtts_tts_bytes(text, voice="emel"):
    """D300 RTX 5090: lokal XTTS-v2 service'e (port 9002) FULL WAV istegi.

    Voice clone: emel veya ahmet. ~1200ms / 5-7s audio (RTF 0.22).
    Internet bagimsiz, kalite Edge TTS ile esdeger. Service yoksa None doner.
    Turkce kisaltma/ozel isim normalize edilir ("Op. Dr." -> "Operator Doktor").
    """
    import urllib.request
    import urllib.error
    import json as _json
    try:
        port = int(os.environ.get("YAZKLINIK_XTTS_SERVICE_PORT", "9002"))
    except Exception:
        port = 9002
    # D300: TTS oncesi text normalize - XTTS dogru telaffuz icin
    try:
        text = _ai_phone_normalize_tts_text(text)
    except Exception:
        pass
    url = f"http://127.0.0.1:{port}/tts"
    body = _json.dumps({"text": text, "voice": voice}).encode("utf-8")
    req = urllib.request.Request(
        url, data=body, headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.read()
    except urllib.error.URLError:
        return None
    except Exception:
        return None


def _ai_phone_xtts_stream_generator(text, voice="emel"):
    """D300 RTX 5090: XTTS streaming generator - browser ilk chunk gelir gelmez calar.

    XTTS service /tts/stream chunked WAV doner; biz onu pass-through ediyoruz.
    Conditioning latents cache'lendigi icin first chunk ~200-400ms (sub-saniye TTFB).
    """
    import urllib.request
    import urllib.error
    import json as _json
    try:
        port = int(os.environ.get("YAZKLINIK_XTTS_SERVICE_PORT", "9002"))
    except Exception:
        port = 9002
    try:
        text = _ai_phone_normalize_tts_text(text)
    except Exception:
        pass
    url = f"http://127.0.0.1:{port}/tts/stream"
    body = _json.dumps({"text": text, "voice": voice}).encode("utf-8")
    req = urllib.request.Request(
        url, data=body, headers={"Content-Type": "application/json"})
    try:
        resp = urllib.request.urlopen(req, timeout=60)
    except Exception:
        return None
    if getattr(resp, "status", 200) >= 400:
        try:
            resp.close()
        except Exception:
            pass
        return None

    def _gen():
        try:
            while True:
                chunk = resp.read(8192)
                if not chunk:
                    break
                yield chunk
        finally:
            try:
                resp.close()
            except Exception:
                pass

    return _gen()


def _ai_phone_edge_tts_stream_generator(text, voice="tr-TR-EmelNeural",
                                        rate_percent=0, pitch="+0Hz", volume="+0%"):
    """D300: edge-tts'in async stream()'ini sync generator'a cevir.

    Browser MediaSource API ile chunk chunk audio.play() yapar - tum response
    beklemeden ilk byte (~200ms) gelir gelmez ses calmaya baslar.
    Edge TTS toplam 1400ms surse bile algilanan latency ~300ms.
    """
    import asyncio
    import edge_tts
    import threading
    import queue

    if not text:
        return
    q = queue.Queue(maxsize=64)
    SENTINEL = object()

    def _format_rate(value):
        try:
            v = int(value or 0)
        except Exception:
            v = 0
        return f"{'+' if v >= 0 else ''}{v}%"

    rate_str = _format_rate(rate_percent)

    async def _producer():
        try:
            comm = edge_tts.Communicate(
                text, voice or "tr-TR-EmelNeural",
                rate=rate_str, pitch=pitch or "+0Hz", volume=volume or "+0%")
            async for chunk in comm.stream():
                if chunk.get("type") == "audio" and chunk.get("data"):
                    q.put(chunk["data"])
        except Exception as exc:
            try:
                print(f"[TTS-STREAM] HATA: {type(exc).__name__}: {exc}", flush=True)
            except Exception:
                pass
        finally:
            q.put(SENTINEL)

    def _run_loop():
        loop = asyncio.new_event_loop()
        try:
            loop.run_until_complete(_producer())
        finally:
            try:
                loop.close()
            except Exception:
                pass

    threading.Thread(target=_run_loop, daemon=True).start()
    while True:
        item = q.get()
        if item is SENTINEL:
            break
        yield item


def _ai_phone_piper_tts_bytes(text):
    """D300 RTX 5090: lokal Piper TTS service'e (port 9001) HTTP istek at.

    Edge TTS Microsoft Azure cloud'una gittigi icin ~1400ms latency yapiyor;
    Piper lokal ONNX runtime ile ~67ms / 4s audio = RTF 0.018 (20x hizli).

    Service yoksa veya hata olursa None doner, caller Edge TTS fallback'i kullanir.
    """
    import urllib.request
    import urllib.error
    import json as _json
    try:
        port = int(os.environ.get("YAZKLINIK_PIPER_SERVICE_PORT", "9001"))
    except Exception:
        port = 9001
    url = f"http://127.0.0.1:{port}/tts"
    body = _json.dumps({"text": text}).encode("utf-8")
    req = urllib.request.Request(
        url, data=body, headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=8) as resp:
            return resp.read()
    except urllib.error.URLError:
        return None
    except Exception:
        return None


def _ai_phone_edge_tts_bytes(text, voice, rate_percent, pitch="+0Hz", volume="+0%"):
    import asyncio
    import edge_tts

    async def _collect(ssl_mode="certifi"):
        connector = None
        edge_comm = None
        old_ssl_ctx = None
        if ssl_mode == "certifi":
            try:
                import ssl
                import certifi
                import aiohttp
                import edge_tts.communicate as edge_comm
                old_ssl_ctx = getattr(edge_comm, "_SSL_CTX", None)
                edge_comm._SSL_CTX = ssl.create_default_context(
                    cafile=certifi.where())
                connector = aiohttp.TCPConnector(
                    ssl=ssl.create_default_context(cafile=certifi.where()))
            except Exception:
                connector = None
        elif ssl_mode == "unverified":
            import ssl
            import aiohttp
            import edge_tts.communicate as edge_comm
            old_ssl_ctx = getattr(edge_comm, "_SSL_CTX", None)
            edge_comm._SSL_CTX = ssl._create_unverified_context()
            connector = aiohttp.TCPConnector(ssl=False)
        communicate = edge_tts.Communicate(
            text=text,
            voice=voice,
            rate=rate_percent,
            volume=volume or "+0%",
            pitch=pitch or "+0Hz",
            connector=connector)
        chunks = []
        try:
            async for chunk in communicate.stream():
                if chunk.get("type") == "audio" and chunk.get("data"):
                    chunks.append(chunk["data"])
        finally:
            if edge_comm is not None and old_ssl_ctx is not None:
                try:
                    edge_comm._SSL_CTX = old_ssl_ctx
                except Exception:
                    pass
            if connector is not None:
                try:
                    await connector.close()
                except Exception:
                    pass
        return b"".join(chunks)

    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)
        try:
            return loop.run_until_complete(_collect("certifi"))
        except Exception as ex:
            msg = str(ex)
            if (
                    "CERTIFICATE_VERIFY_FAILED" in msg or
                    "certificate verify failed" in msg.lower() or
                    "unable to get local issuer" in msg.lower()):
                return loop.run_until_complete(_collect("unverified"))
            raise
    finally:
        try:
            loop.close()
        except Exception:
            pass
        try:
            asyncio.set_event_loop(None)
        except Exception:
            pass


def _ai_phone_minutes(value):
    try:
        parts = str(value or "").strip().split(":")
        return int(parts[0]) * 60 + int(parts[1])
    except Exception:
        return -99999


def _ai_phone_parse_date(text):
    folded = _fold_search_text(text)
    today = datetime.now().date()
    if any(word in folded for word in ("bugun", "bugun icin", "bu gun")):
        return today.strftime("%Y-%m-%d")
    if "yarin" in folded:
        return (today + timedelta(days=1)).strftime("%Y-%m-%d")
    if "obur gun" in folded or "oburgun" in folded:
        return (today + timedelta(days=2)).strftime("%Y-%m-%d")

    iso = re.search(r"\b(20\d{2})[-/.](\d{1,2})[-/.](\d{1,2})\b", text)
    if iso:
        try:
            return datetime(int(iso.group(1)), int(iso.group(2)),
                            int(iso.group(3))).strftime("%Y-%m-%d")
        except Exception:
            pass

    dm = re.search(r"\b(\d{1,2})[./-](\d{1,2})(?:[./-](20\d{2}))?\b", text)
    if dm:
        year = int(dm.group(3) or today.year)
        try:
            parsed = datetime(year, int(dm.group(2)), int(dm.group(1))).date()
            if parsed < today and dm.group(3) is None:
                parsed = datetime(year + 1, int(dm.group(2)),
                                  int(dm.group(1))).date()
            return parsed.strftime("%Y-%m-%d")
        except Exception:
            pass

    weekdays = {
        "pazartesi": 0, "sali": 1, "carsamba": 2, "persembe": 3,
        "cuma": 4, "cumartesi": 5, "pazar": 6,
    }
    for name, idx in weekdays.items():
        if name in folded:
            days = (idx - today.weekday()) % 7
            if days == 0:
                days = 7
            return (today + timedelta(days=days)).strftime("%Y-%m-%d")
    return ""


def _ai_phone_parse_time(text):
    folded = _fold_search_text(text)
    match = re.search(r"\b(?:saat\s*)?([01]?\d|2[0-3])[:. ]([0-5]\d)\b",
                      folded)
    if match:
        return f"{int(match.group(1)):02d}:{int(match.group(2)):02d}"
    match = re.search(r"\bsaat\s*([01]?\d|2[0-3])\b", folded)
    if match:
        return f"{int(match.group(1)):02d}:00"
    if "ogleden sonra" in folded or "aksamustu" in folded:
        return "14:00"
    if "ogle" in folded:
        return "12:00"
    if "sabah" in folded:
        return "10:00"
    return ""


def _ai_phone_is_appointment_message(text):
    folded = _fold_search_text(text)
    return any(word in folded for word in (
        "randevu", "muayene", "kontrol", "gelmek istiyorum",
        "yer var", "musait", "bos saat", "sira almak"))


def _ai_phone_find_or_create_patient(caller, message=""):
    digits = "".join(ch for ch in str(caller or "") if ch.isdigit())
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        if digits:
            rows = con.execute(
                "SELECT patient_key, phone FROM phone_numbers").fetchall()
            for row in rows:
                saved = "".join(ch for ch in str(row.get("phone") or "")
                                if ch.isdigit())
                if saved and (saved.endswith(digits[-10:])
                              or digits.endswith(saved[-10:])):
                    patient = con.execute(
                        "SELECT folder_key, display_name FROM patients "
                        "WHERE folder_key=?",
                        (row.get("patient_key"),)).fetchone()
                    if patient:
                        return patient.get("folder_key"), (
                            patient.get("display_name")
                            or patient.get("folder_key"))

        name = ""
        name_match = re.search(
            r"(?:adim|adim soyadim|ben)\s+([A-Za-zCÄÃœÅÄ°Ã–Ã‡cÄŸÃ¼ÅŸiÃ¶Ã§ ]{3,40})",
            str(message or ""), re.IGNORECASE)
        if name_match:
            name = " ".join(name_match.group(1).split()).strip()
        if not name:
            name = f"Telefon Arayan {digits[-4:]}" if digits else "Telefon Arayan"
        base = "tel_" + (digits[-10:] if digits else uuid.uuid4().hex[:10])
        patient_key = base
        suffix = 1
        while con.execute("SELECT 1 FROM patients WHERE folder_key=?",
                          (patient_key,)).fetchone():
            existing = con.execute(
                "SELECT display_name FROM patients WHERE folder_key=?",
                (patient_key,)).fetchone()
            if existing:
                return patient_key, existing.get("display_name") or patient_key
            suffix += 1
            patient_key = f"{base}_{suffix}"
        try:
            patient_cols = set()
            patient_info = []
            for row in con.execute("PRAGMA table_info(patients)").fetchall():
                if isinstance(row, dict):
                    info = {
                        "name": str(row.get("name") or ""),
                        "type": str(row.get("type") or ""),
                        "notnull": int(row.get("notnull") or 0),
                        "dflt_value": row.get("dflt_value"),
                        "pk": int(row.get("pk") or 0),
                    }
                else:
                    info = {
                        "name": str(row[1]),
                        "type": str(row[2] or ""),
                        "notnull": int(row[3] or 0),
                        "dflt_value": row[4],
                        "pk": int(row[5] or 0),
                    }
                patient_cols.add(info["name"])
                patient_info.append(info)
        except Exception:
            patient_cols = {"folder_key", "display_name"}
            patient_info = []
        cols = ["folder_key", "display_name"]
        vals = [patient_key, name]
        if "full_path" in patient_cols:
            try:
                base_dir = Path(os.environ.get("YAZKLINIK_DATA_ROOT") or Path.cwd())
                full_path = str(base_dir / "Hastalar" / patient_key)
            except Exception:
                full_path = patient_key
            cols.append("full_path")
            vals.append(full_path)
        if "created_at" in patient_cols:
            cols.append("created_at")
            vals.append(now)
        if "updated_at" in patient_cols:
            cols.append("updated_at")
            vals.append(now)
        for info in patient_info:
            col = info.get("name") or ""
            if not col or col in cols:
                continue
            if not info.get("notnull") or info.get("dflt_value") is not None:
                continue
            ctype = (info.get("type") or "").upper()
            cols.append(col)
            if "INT" in ctype:
                vals.append(0)
            elif "REAL" in ctype or "FLOA" in ctype or "DOUB" in ctype:
                vals.append(time.time())
            else:
                vals.append(now)
        placeholders = ",".join("?" for _ in cols)
        con.execute(
            f"INSERT INTO patients({','.join(cols)}) VALUES({placeholders})",
            tuple(vals))
        if digits:
            con.execute(
                "INSERT OR REPLACE INTO phone_numbers(patient_key, phone, updated_at) "
                "VALUES(?,?,?)",
                (patient_key, caller, now))
        con.commit()
        return patient_key, name


def _ai_phone_available_slots(appt_date, preferred_time=""):
    _init_appointments_table()
    start_min = 9 * 60
    end_min = 17 * 60
    step = 30
    preferred = _ai_phone_minutes(preferred_time)
    with db_conn() as con:
        rows = con.execute(
            "SELECT appointment_time FROM appointments "
            "WHERE appointment_date=? AND status != 'cancelled'",
            (appt_date,)).fetchall()
    busy = [_ai_phone_minutes(r[0] if not isinstance(r, dict)
                              else r.get("appointment_time")) for r in rows]
    slots = []
    for minute in range(start_min, end_min + 1, step):
        if any(abs(minute - b) <= 15 for b in busy):
            continue
        slots.append(f"{minute // 60:02d}:{minute % 60:02d}")
    if preferred_time and preferred >= 0:
        slots.sort(key=lambda s: abs(_ai_phone_minutes(s) - preferred))
    return slots[:5]


def _ai_phone_create_pending_appointment(caller, message, appt_date, appt_time,
                                         purpose="Telefon randevusu"):
    _ensure_ai_phone_schema()
    patient_key, patient_name = _ai_phone_find_or_create_patient(
        caller, message=message)
    token = "YK-" + datetime.now().strftime("%m%d%H%M%S") + "-" + uuid.uuid4().hex[:4]
    now = datetime.now()
    expires = now + timedelta(minutes=30)
    note = f"YZ telesekreter onayi bekliyor. Arayan: {caller or '-'}"
    with db_conn() as con:
        con.execute(
            "INSERT INTO ai_phone_pending_appointments("
            "token, caller, patient_key, patient_name, appointment_date, "
            "appointment_time, purpose, note, status, created_at, expires_at"
            ") VALUES(?,?,?,?,?,?,?,?,?,?,?)",
            (token, caller or "", patient_key, patient_name, appt_date,
             appt_time, purpose, note, "pending",
             now.isoformat(sep=" ", timespec="seconds"),
             expires.isoformat(sep=" ", timespec="seconds")))
        con.commit()
    return {
        "token": token,
        "patient_key": patient_key,
        "patient_name": patient_name,
        "date": appt_date,
        "time": appt_time,
        "purpose": purpose,
    }


def _ai_phone_latest_pending(caller, message=""):
    _ensure_ai_phone_schema()
    token_match = re.search(r"\bYK-[A-Za-z0-9-]+\b", str(message or ""),
                            re.IGNORECASE)
    params = []
    where = "status='pending'"
    if token_match:
        where += " AND upper(token)=upper(?)"
        params.append(token_match.group(0))
    else:
        where += " AND caller=?"
        params.append(caller or "")
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        row = con.execute(
            "SELECT * FROM ai_phone_pending_appointments "
            f"WHERE {where} AND (expires_at IS NULL OR expires_at >= ?) "
            "ORDER BY created_at DESC LIMIT 1",
            tuple(params + [now])).fetchone()
    return row


def _ai_phone_confirm_pending_appointment(caller, message):
    folded = _fold_search_text(message)
    if not any(word in folded for word in (
        "evet", "onay", "tamam", "olur", "kabul", "kaydet")):
        return None
    pending = _ai_phone_latest_pending(caller, message)
    if not pending:
        return None
    _init_appointments_table()
    appt_date = pending.get("appointment_date")
    appt_time = pending.get("appointment_time")
    slots = _ai_phone_available_slots(appt_date, appt_time)
    if appt_time not in slots:
        return {
            "ok": False,
            "reply": (
                f"{appt_date} {appt_time} artik dolu gorunuyor. "
                f"Musait saatler: {', '.join(slots) if slots else 'bugun dolu'}. "
                "Lutfen yeni saati soyleyin.")
        }
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    with db_conn() as con:
        cur = con.execute(
            "INSERT INTO appointments("
            "patient_key, appointment_date, appointment_time, purpose, note, "
            "status, created_by, created_at) VALUES(?,?,?,?,?,?,?,?)",
            (pending.get("patient_key"), appt_date, appt_time,
             pending.get("purpose") or "Telefon randevusu",
             pending.get("note") or "YZ telesekreter ile alindi",
             "planned", "yz-telesekreter", now))
        appt_id = cur.lastrowid
        con.execute(
            "UPDATE ai_phone_pending_appointments SET status='booked' "
            "WHERE id=?",
            (pending.get("id"),))
        con.commit()
    try:
        _log_audit("ai_phone_appointment_create",
                   entity_type="appointment", entity_id=str(appt_id),
                   patient_key=pending.get("patient_key"),
                   details=f"{appt_date} {appt_time} telesekreter")
    except Exception:
        pass
    return {
        "ok": True,
        "appointment_id": appt_id,
        "reply": (
            f"Randevunuz kaydedildi: {appt_date} saat {appt_time}. "
            "Klinik ekibi gerekirse sizi arayacak.")
    }


def _ai_phone_handle_appointment_flow(message, history=None, caller=""):
    confirm = _ai_phone_confirm_pending_appointment(caller, message)
    if confirm:
        return confirm.get("reply"), (
            "appointment_booked" if confirm.get("ok") else "appointment_conflict")

    if not _ai_phone_is_appointment_message(message):
        return None, ""
    appt_date = _ai_phone_parse_date(message)
    appt_time = _ai_phone_parse_time(message)
    if not appt_date:
        return ((
            "Randevu icin hangi gun uygun? Bugun, yarin veya tarih olarak "
            "soyleyebilirsiniz. Ornek: yarin saat 10:30."),
            "appointment_need_date")
    if not appt_time:
        slots = _ai_phone_available_slots(appt_date)
        if slots:
            return ((
                f"{appt_date} icin musait saatler: {', '.join(slots[:4])}. "
                "Hangi saati ayirayim?"),
                "appointment_offer_slots")
        return ((
            f"{appt_date} icin bos saat bulamadim. Baska bir gun soyleyin, "
            "hemen bakayim."),
            "appointment_no_slot")

    slots = _ai_phone_available_slots(appt_date, appt_time)
    if appt_time not in slots:
        if slots:
            return ((
                f"{appt_date} saat {appt_time} dolu gorunuyor. En yakin "
                f"musait saatler: {', '.join(slots[:4])}. Hangi saati istersiniz?"),
                "appointment_conflict")
        return ((
            f"{appt_date} icin bos saat bulamadim. Baska bir gun soyleyin, "
            "kontrol edeyim."),
            "appointment_no_slot")

    pending = _ai_phone_create_pending_appointment(
        caller, message, appt_date, appt_time)
    return ((
        f"{pending['patient_name']} adina {appt_date} saat {appt_time} icin "
        f"randevu ayirabilirim. Onayliyorsaniz 'evet onayliyorum' deyin. "
        f"Onay kodu: {pending['token']}"),
        "appointment_pending")


