def _ai_phone_generate_dialog_reply(message, history=None, caller="", channel="web_test"):
    settings = _ai_phone_settings()
    text = str(message or "").strip()
    folded = _fold_search_text(text)
    emergency_words = [
        "kanama", "bayil", "nefes", "siddetli agri", "ates", "nobet",
        "bebek hareket etmiyor", "su geldi", "gogus agrisi", "intihar",
        "bayildim", "cok kotuyum", "dayanamayacak", "acil",
    ]
    if any(word in folded for word in emergency_words):
        return settings["ai_phone_emergency_text"], "emergency_rule"

    appt_reply, appt_status = _ai_phone_handle_appointment_flow(
        text, history=history, caller=caller)
    if appt_reply:
        return appt_reply, appt_status
    if _ai_phone_should_handoff(text, settings=settings):
        return _ai_phone_handoff_reply(settings, caller, text), "needs_human"

    clean_history = []
    for item in (history or [])[-10:]:
        role = str(item.get("role") or "").strip().lower()
        content = str(item.get("content") or "").strip()
        if role not in ("user", "assistant") or not content:
            continue
        clean_history.append(f"{'Hasta/Arayan' if role == 'user' else 'YZ'}: {content[:700]}")
    history_text = "\n".join(clean_history) or "Gecmis yok."
    prompt = (
        "Sen YazKlinik icin Turkce konusan, telefonda veya web testinde "
        "insanlarla sakin diyalog kuran YZ klinik karÅŸÄ±lama asistanisin. "
        "Tani koyma, tedavi baslatma, ilac dozu verme. Acil belirti varsa "
        "112/acil servis yonlendir. Randevu, sonuc, recete, adres, fiyat, "
        "doktor notu ve geri aranma taleplerini netlestir. "
        "Cevap dogal Turkce olsun; telefonda okunabilecek kadar kisa tut. "
        "Gerekirse bir sonraki soruyu sor.\n\n"
        f"Kanal: {channel}\n"
        f"Klinik karsilama metni: {settings['ai_phone_greeting']}\n"
        f"Klinik telefon: {settings['ai_phone_clinic_phone'] or '-'}\n"
        f"Arayan/test eden: {caller or '-'}\n"
        f"Gecmis:\n{history_text}\n\n"
        f"Son mesaj: {text}\n\n"
        "Cevap 1-4 cumle olsun. Klinik ekibe not gerekiyorsa bunu acik soyle."
    )
    try:
        ok, answer, _dur = call_ollama(
            prompt, model=_select_ollama_model(task="phone"),
            system=_doctor_ai_system("turkce telefon ve web diyalog asistani"),
            temperature=0.28, max_tokens=1000, timeout=120, use_cache=False)
        if ok and answer.strip():
            return answer.strip(), "ai_dialog"
        return settings["ai_phone_escalation_text"], "fallback"
    except Exception:
        return settings["ai_phone_escalation_text"], "fallback"


def _record_ai_phone_call(caller, transcript, ai_reply, status,
                          device_id=None, source_channel="phone"):
    _ensure_ai_phone_schema()
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    status_text = str(status or "").lower()
    if "emergency" in status_text:
        staff_status = "urgent"
    elif any(token in status_text for token in ("needs_human", "fallback", "manual_handoff")):
        staff_status = "callback"
    else:
        staff_status = "open"
    with db_conn() as con:
        con.execute(
            "INSERT INTO ai_phone_calls("
            "caller, device_id, transcript, ai_reply, status, created_at, "
            "handled_by, staff_status, source_channel"
            ") VALUES(?,?,?,?,?,?,?,?,?)",
            (caller or "", device_id, transcript, ai_reply, status, now,
             session.get("user", "api"), staff_status, source_channel or "phone"))
        con.commit()


def _chat_center_call_badge(status):
    status = str(status or "open").strip().lower()
    labels = {
        "open": ("bg-primary", "Acik"),
        "done": ("bg-success", "Tamamlandi"),
        "callback": ("bg-warning text-dark", "Geri aranacak"),
        "waiting": ("bg-info text-dark", "Beklemede"),
        "urgent": ("bg-danger", "Acil"),
    }
    css, label = labels.get(status, ("bg-secondary", status or "Durum"))
    return f'<span class="badge {css}">{sh(label)}</span>'


def _chat_center_ai_badge(status):
    status = str(status or "").strip().lower()
    if "emergency" in status:
        return '<span class="badge bg-danger">Acil uyarisi</span>'
    if "appointment_booked" in status:
        return '<span class="badge bg-success">Randevu kayitli</span>'
    if "appointment_pending" in status:
        return '<span class="badge bg-warning text-dark">Randevu onayi bekliyor</span>'
    if "appointment" in status:
        return '<span class="badge bg-info text-dark">Randevu akisi</span>'
    if "manual" in status:
        return '<span class="badge bg-secondary">Manuel not</span>'
    return f'<span class="badge bg-light text-dark">{sh(status or "YZ")}</span>'


def _chat_center_pending_badge(status):
    status = str(status or "pending").strip().lower()
    labels = {
        "pending": ("bg-warning text-dark", "Onay bekliyor"),
        "booked": ("bg-success", "Randevuya cevrildi"),
        "rejected": ("bg-danger", "Reddedildi"),
        "cancelled": ("bg-secondary", "Iptal"),
        "expired": ("bg-dark", "Suresi doldu"),
    }
    css, label = labels.get(status, ("bg-secondary", status or "Durum"))
    return f'<span class="badge {css}">{sh(label)}</span>'


def _chat_center_update_call(call_id, staff_status, note=""):
    _ensure_ai_phone_schema()
    allowed = {"open", "done", "callback", "waiting", "urgent"}
    staff_status = str(staff_status or "open").strip().lower()
    if staff_status not in allowed:
        staff_status = "open"
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    with db_conn() as con:
        con.execute(
            "UPDATE ai_phone_calls SET staff_status=?, staff_note=?, "
            "handled_by=?, handled_at=? WHERE id=?",
            (staff_status, note or "", session.get("user", "?"), now,
             int(call_id)))
        con.commit()


def _chat_center_set_pending_status(pending_id, status):
    _ensure_ai_phone_schema()
    status = str(status or "").strip().lower()
    if status not in {"pending", "booked", "rejected", "cancelled", "expired"}:
        status = "pending"
    with db_conn() as con:
        con.execute(
            "UPDATE ai_phone_pending_appointments SET status=? WHERE id=?",
            (status, int(pending_id)))
        con.commit()


def _chat_center_book_pending_appointment(pending_id, form=None, force=False):
    _ensure_ai_phone_schema()
    _init_appointments_table()
    form = form or {}

    def _field(name, default=""):
        try:
            value = form.get(name, default)
        except Exception:
            value = default
        return str(value if value is not None else default).strip()

    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        pending = con.execute(
            "SELECT * FROM ai_phone_pending_appointments WHERE id=?",
            (int(pending_id),)).fetchone()
    if not pending:
        return False, "Randevu talebi bulunamadi.", None

    patient_key = _field("patient_key", pending.get("patient_key") or "")
    appt_date = _field("appointment_date",
                       pending.get("appointment_date") or "")
    appt_time = _field("appointment_time",
                       pending.get("appointment_time") or "")
    purpose = _field("purpose", pending.get("purpose") or "Sohbet randevusu")
    note = _field("note", pending.get("note") or "")
    if not patient_key or not appt_date or not appt_time:
        return False, "Hasta, tarih ve saat zorunlu.", None

    slots = _ai_phone_available_slots(appt_date, appt_time)
    if not force and appt_time not in slots:
        slot_text = ", ".join(slots[:5]) if slots else "bos saat yok"
        return (
            False,
            f"{appt_date} {appt_time} dolu gorunuyor. Musait: {slot_text}.",
            None,
        )

    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    created_by = session.get("user", "sohbet-merkezi")
    source_note = (
        f"{note}\n\nSohbet merkezi onayi. Arayan: "
        f"{pending.get('caller') or '-'}; token: {pending.get('token') or '-'}"
    ).strip()
    with db_conn() as con:
        cur = con.execute(
            "INSERT INTO appointments("
            "patient_key, appointment_date, appointment_time, purpose, note, "
            "status, created_by, created_at) VALUES(?,?,?,?,?,?,?,?)",
            (patient_key, appt_date, appt_time, purpose, source_note,
             "planned", created_by, now))
        appt_id = cur.lastrowid
        con.execute(
            "UPDATE ai_phone_pending_appointments SET status='booked' "
            "WHERE id=?",
            (int(pending_id),))
        caller = str(pending.get("caller") or "")
        if caller:
            con.execute(
                "UPDATE ai_phone_calls SET staff_status='done', "
                "staff_note=?, handled_by=?, handled_at=? "
                "WHERE caller=? AND status LIKE 'appointment%' "
                "AND COALESCE(staff_status, 'open') != 'done'",
                (f"Randevuya cevrildi: #{appt_id}", created_by, now, caller))
        con.commit()
    try:
        _log_audit("chat_center_appointment_approve",
                   entity_type="appointment", entity_id=str(appt_id),
                   patient_key=patient_key,
                   details=f"{appt_date} {appt_time} sohbet merkezi")
    except Exception:
        pass
    return True, f"Randevu olusturuldu: #{appt_id}", appt_id


def _ai_phone_transcribe_via_openai(audio_bytes, filename="audio.webm",
                                    mime_type="audio/webm", language="tr"):
    """OpenAI Whisper API uzerinden bulutta ses->metin.
    Yerel asr ve HTTP servisi yoksa son fallback. OPENAI_API_KEY
    veya sysparam_openai_api_key set olmasi gerekiyor."""
    cfg = _openai_config() or {}
    api_key = (cfg.get("api_key") or "").strip()
    if not api_key:
        return None, "OPENAI_API_KEY tanimli degil"
    audio_bytes = bytes(audio_bytes or b"")
    if not audio_bytes:
        return None, "ses bos"
    # Audio API endpoint'i sabit (chat endpoint'inden farkli)
    url = "https://api.openai.com/v1/audio/transcriptions"
    boundary = "----YazKlinikOpenAIAudioBoundary"
    safe_name = str(filename or "audio.webm").replace('"', "")
    lang = (str(language or "tr").strip() or "tr")[:8]
    parts = []
    parts.append(
        f"--{boundary}\r\n"
        f'Content-Disposition: form-data; name="model"\r\n\r\n'
        f"whisper-1\r\n".encode("utf-8"))
    parts.append(
        f"--{boundary}\r\n"
        f'Content-Disposition: form-data; name="language"\r\n\r\n'
        f"{lang}\r\n".encode("utf-8"))
    parts.append(
        f"--{boundary}\r\n"
        f'Content-Disposition: form-data; name="response_format"\r\n\r\n'
        f"text\r\n".encode("utf-8"))
    parts.append(
        f"--{boundary}\r\n"
        f'Content-Disposition: form-data; name="file"; '
        f'filename="{safe_name}"\r\n'
        f"Content-Type: {mime_type or 'audio/webm'}\r\n\r\n".encode("utf-8"))
    parts.append(audio_bytes)
    parts.append(f"\r\n--{boundary}--\r\n".encode("utf-8"))
    body = b"".join(parts)
    import urllib.request as _urllib_req
    req = _urllib_req.Request(
        url, data=body, method="POST",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": f"multipart/form-data; boundary={boundary}",
        })
    try:
        with _urllib_req.urlopen(req, timeout=int(cfg.get("timeout") or 60)) as resp:
            text = resp.read().decode("utf-8", errors="ignore").strip()
            return (text or None), ""
    except Exception as ex:
        return None, f"OpenAI Whisper API hatasi: {ex}"


def _ai_phone_transcribe_audio_bytes(audio_bytes, filename="audio.webm",
                                     mime_type="audio/webm", language="tr"):
    import urllib.request as _urllib_req
    import urllib.parse as _urllib_parse
    audio_bytes = bytes(audio_bytes or b"")
    if not audio_bytes:
        raise ValueError("Ses verisi bos")

    # Windows/web kullanimi icin once yerel ASR denenir. localhost:9000
    # servisi kapaliysa kullaniciya ham urlopen hatasi gostermemek gerekir.
    prefer_local = str(_db_get_setting(
        "sysparam_whisper_prefer_local", "1") or "1").lower()
    prefer_local = prefer_local not in {"0", "false", "no", "off"}
    local_error = ""
    if prefer_local:
        local_text = _ai_phone_transcribe_audio_local(
            audio_bytes, filename=filename, mime_type=mime_type,
            language=language)
        local_error = str(getattr(
            _ai_phone_transcribe_audio_local, "last_error", "") or "")
        if local_text is not None:
            return local_text

    whisper_url = (
        _db_get_setting("sysparam_whisper_url", "")
        or "http://localhost:9000/asr")
    sep = "&" if "?" in whisper_url else "?"
    if "output=" not in whisper_url:
        whisper_url = f"{whisper_url}{sep}output=text"
    boundary = "----YazKlinikLiveVoiceBoundary"
    safe_name = str(filename or "audio.webm").replace('"', "")
    body = (
        f"--{boundary}\r\n"
        f'Content-Disposition: form-data; name="audio_file"; '
        f'filename="{safe_name}"\r\n'
        f"Content-Type: {mime_type or 'audio/webm'}\r\n\r\n"
    ).encode("utf-8")
    body += audio_bytes
    lang = str(language or "tr").strip() or "tr"
    body += (
        f"\r\n--{boundary}\r\n"
        f'Content-Disposition: form-data; name="task"\r\n\r\n'
        f"transcribe\r\n"
        f"--{boundary}\r\n"
        f'Content-Disposition: form-data; name="language"\r\n\r\n'
        f"{_urllib_parse.quote(lang, safe='')}\r\n"
        f"--{boundary}--\r\n"
    ).encode("utf-8")
    req = _urllib_req.Request(
        whisper_url,
        data=body,
        headers={"Content-Type": f"multipart/form-data; boundary={boundary}"})
    http_msg = ""
    try:
        with _urllib_req.urlopen(req, timeout=120) as resp:
            return resp.read().decode("utf-8", errors="ignore").strip()
    except Exception as http_ex:
        if not prefer_local:
            local_text = _ai_phone_transcribe_audio_local(
                audio_bytes, filename=filename, mime_type=mime_type,
                language=language)
            local_error = str(getattr(
                _ai_phone_transcribe_audio_local, "last_error", "") or "")
            if local_text is not None:
                return local_text
        http_msg = str(http_ex)
        if "10061" in http_msg or "actively refused" in http_msg.lower():
            http_msg = (
                "Whisper HTTP servisi kapali veya reddediyor "
                f"({whisper_url})")

    # Son fallback: OpenAI Whisper API (API key set ise)
    openai_text, openai_err = _ai_phone_transcribe_via_openai(
        audio_bytes, filename=filename, mime_type=mime_type, language=language)
    if openai_text:
        return openai_text

    detail = local_error or "yerel faster-whisper/openai-whisper modeli açılamadı"
    cloud_hint = ""
    if openai_err:
        if "OPENAI_API_KEY tanımlı değil" in openai_err or "OPENAI_API_KEY tanimli degil" in openai_err:
            cloud_hint = (" Çözüm: /tum-ayarlar > OpenAI API anahtarını "
                          "kaydedin (en hızlı çözüm) VEYA "
                          "pip install faster-whisper komutuyla yerel "
                          "modeli kurun.")
        else:
            cloud_hint = f" OpenAI fallback: {openai_err}"
    raise RuntimeError(
        "Ses metne çevrilemedi. Yerel ASR: "
        f"{detail}. HTTP: {http_msg or 'denenmedi'}.{cloud_hint}")


def _voice_focus_truthy(value):
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() not in {"", "0", "false", "no", "off", "hayir"}


def _voice_focus_fold(text):
    import re
    import unicodedata

    folded = unicodedata.normalize("NFKD", str(text or ""))
    folded = "".join(ch for ch in folded if not unicodedata.combining(ch))
    folded = folded.lower()
    folded = folded.translate(str.maketrans({
        "ı": "i", "İ": "i", "ğ": "g", "Ğ": "g", "ü": "u", "Ü": "u",
        "ş": "s", "Ş": "s", "ö": "o", "Ö": "o", "ç": "c", "Ç": "c",
    }))
    return re.sub(r"[^a-z0-9\s]+", " ", folded).strip()


def _voice_focus_clean_transcript(text, caller=""):
    import re

    clean = str(text or "").strip()
    if not clean:
        return ""
    clean = re.sub(
        r"\[(?:muzik|music|alkis|applause|gulusme|laughter|ses|noise)\]",
        " ", clean, flags=re.IGNORECASE).strip()
    folded = _voice_focus_fold(clean)
    if not folded:
        return ""
    caller_key = _voice_focus_fold(caller)
    background_hits = (
        "muzik", "sarki", "altyazi", "abone ol", "izlediginiz icin tesekkur",
        "reklam", "jenerik", "fon muzigi", "music", "subtitle")
    if caller_key in {"alex wake", "voice agent", "native mic", "webshell native"}:
        if any(hit in folded for hit in background_hits):
            has_wake = any(wake in folded for wake in ("alex", "aleks", "aleksa"))
            if not has_wake:
                return ""
    return clean


def _ai_phone_decode_audio_tolerant(audio_bytes, filename="audio.webm",
                                    mime_type="audio/webm",
                                    target_rate=16000):
    import io
    try:
        import av
        import numpy as np
        from av.audio.resampler import AudioResampler
    except Exception as ex:
        return None, f"PyAV/Numpy yuklenemedi: {ex}"

    raw = bytes(audio_bytes or b"")
    if not raw:
        return None, "bos ses verisi"

    decode_error = ""
    chunks = []
    container = None
    try:
        container = av.open(io.BytesIO(raw), mode="r", metadata_errors="ignore")
        streams = [s for s in (container.streams or []) if getattr(s, "type", "") == "audio"]
        if not streams:
            return None, "ses stream bulunamadi"
        stream = streams[0]
        try:
            stream.thread_type = "AUTO"
        except Exception:
            pass
        resampler = AudioResampler(format="s16", layout="mono", rate=int(target_rate or 16000))
        for packet in container.demux(stream):
            try:
                frames = packet.decode()
            except Exception as ex_pkt:
                if not decode_error:
                    decode_error = str(ex_pkt)
                continue
            for frame in frames or []:
                try:
                    out_frames = resampler.resample(frame) or []
                except Exception as ex_res:
                    if not decode_error:
                        decode_error = str(ex_res)
                    continue
                for out in out_frames:
                    try:
                        arr = out.to_ndarray()
                    except Exception as ex_arr:
                        if not decode_error:
                            decode_error = str(ex_arr)
                        continue
                    if arr is None:
                        continue
                    if getattr(arr, "ndim", 1) > 1:
                        arr = arr[0]
                    chunks.append(arr.astype(np.int16, copy=False))
        try:
            tail = resampler.resample(None) or []
            for out in tail:
                arr = out.to_ndarray()
                if arr is None:
                    continue
                if getattr(arr, "ndim", 1) > 1:
                    arr = arr[0]
                chunks.append(arr.astype(np.int16, copy=False))
        except Exception:
            pass
    except Exception as ex:
        return None, str(ex)
    finally:
        if container is not None:
            try:
                container.close()
            except Exception:
                pass

    if not chunks:
        if decode_error:
            return None, decode_error
        return None, "ses frame cozumlenemedi"
    try:
        pcm = np.concatenate(chunks)
    except Exception as ex:
        return None, f"ses birlestirme hatasi: {ex}"
    if getattr(pcm, "size", 0) <= 0:
        return None, "ses bos cikti"
    audio = pcm.astype(np.float32) / 32768.0
    audio = np.clip(audio, -1.0, 1.0)
    return audio, decode_error


_WHISPER_SVC_WARN_LAST = 0


def _ai_phone_transcribe_via_subprocess(audio_bytes, filename="audio.wav",
                                        language="tr"):
    """D300: Whisper microservice'ye HTTP istek at (port 9000).
    yazklinik_whisper_service.py ayri process'te calistigi icin
    werkzeug threading + faster-whisper CTranslate2 deadlock'undan kacinir.
    """
    global _WHISPER_SVC_WARN_LAST
    import urllib.request
    import urllib.error
    try:
        port = int(os.environ.get(
            "YAZKLINIK_WHISPER_SERVICE_PORT", "9000"))
    except Exception:
        port = 9000
    url = f"http://127.0.0.1:{port}/asr?output=text"
    boundary = "----yk_whisper_" + str(int(time.time() * 1000))
    suffix_name = filename or "audio.webm"
    parts = []
    parts.append(f"--{boundary}\r\n".encode())
    parts.append((
        f'Content-Disposition: form-data; name="language"\r\n\r\n'
        f"{language}\r\n").encode())
    parts.append(f"--{boundary}\r\n".encode())
    parts.append((
        f'Content-Disposition: form-data; name="audio_file"; '
        f'filename="{suffix_name}"\r\n'
        f"Content-Type: application/octet-stream\r\n\r\n").encode())
    parts.append(bytes(audio_bytes or b""))
    parts.append(f"\r\n--{boundary}--\r\n".encode())
    body = b"".join(parts)
    req = urllib.request.Request(
        url, data=body,
        headers={
            "Content-Type": f"multipart/form-data; boundary={boundary}"})
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            data = resp.read()
        return (data.decode("utf-8", errors="replace").strip() or "")
    except urllib.error.URLError:
        # Service kapali - dakikada bir uyari (log spam yapma)
        now = time.time()
        if now - _WHISPER_SVC_WARN_LAST > 60:
            _WHISPER_SVC_WARN_LAST = now
            try:
                print(
                    f"[WHISPER] Microservice (port {port}) yanit vermiyor. "
                    f"START_WHISPER_SERVICE.bat calisiyor mu? "
                    f"Lokal Whisper fallback'ine donuluyor (daha yavas).",
                    flush=True)
            except Exception:
                pass
        return None
    except Exception:
        return None


def _ai_phone_transcribe_audio_local(audio_bytes, filename="audio.wav",
                                     mime_type="audio/wav",
                                     language="tr"):
    import tempfile
    from pathlib import Path as _Path

    _ai_phone_transcribe_audio_local.last_error = ""
    # D300: once microservice (port 9000) dene - werkzeug+CTranslate2 deadlock'tan kacinir
    try:
        svc_text = _ai_phone_transcribe_via_subprocess(
            audio_bytes, filename=filename, language=language)
        if svc_text:
            return svc_text
    except Exception:
        pass
    suffix = _Path(str(filename or "audio.wav")).suffix or ".wav"
    temp_path = None
    try:
        with tempfile.NamedTemporaryFile(suffix=suffix, delete=False) as f:
            f.write(bytes(audio_bytes or b""))
            temp_path = f.name
        lang = str(language or "tr").strip() or "tr"
        whisper_profile = _whisper_runtime_profile()
        model_name = str(whisper_profile.get("model") or "base").strip() or "base"
        whisper_device = str(whisper_profile.get("device") or "cpu").strip() or "cpu"
        whisper_compute = str(
            whisper_profile.get("compute_type") or "int8").strip() or "int8"
        try:
            from faster_whisper import WhisperModel

            def _fw_candidates(name, device, compute):
                seen = set()
                items = [
                    (name, device, compute),
                    (name, "cpu", "int8"),
                    ("base", device, compute),
                    ("base", "cuda" if device == "cuda" else "cpu",
                     "float16" if device == "cuda" else "int8"),
                    ("base", "cpu", "int8"),
                    ("tiny", "cpu", "int8"),
                ]
                for item in items:
                    key = tuple(str(x or "").strip().lower() for x in item)
                    if not key[0] or key in seen:
                        continue
                    seen.add(key)
                    yield item

            with _AI_PHONE_ASR_MODEL_LOCK:
                cache = _AI_PHONE_ASR_MODEL_CACHE
                if (cache.get("engine") != "faster-whisper" or
                        cache.get("name") != model_name or
                        cache.get("device") != whisper_device or
                        cache.get("compute_type") != whisper_compute or
                        cache.get("model") is None):
                    load_errors = []
                    loaded = None
                    loaded_name = model_name
                    loaded_device = whisper_device
                    loaded_compute = whisper_compute
                    for cand_name, cand_device, cand_compute in _fw_candidates(
                            model_name, whisper_device, whisper_compute):
                        try:
                            loaded = WhisperModel(
                                cand_name,
                                device=cand_device,
                                compute_type=cand_compute)
                            loaded_name = cand_name
                            loaded_device = cand_device
                            loaded_compute = cand_compute
                            break
                        except Exception as load_ex:
                            load_errors.append(
                                f"{cand_name}/{cand_device}/{cand_compute}: {load_ex}")
                    if loaded is None:
                        raise RuntimeError("; ".join(load_errors[-3:]))
                    cache["model"] = loaded
                    cache["engine"] = "faster-whisper"
                    cache["name"] = loaded_name
                    cache["device"] = loaded_device
                    cache["compute_type"] = loaded_compute
                    model_name = loaded_name
                    whisper_device = loaded_device
                    whisper_compute = loaded_compute
                else:
                    model_name = str(cache.get("name") or model_name)
                    whisper_device = str(cache.get("device") or whisper_device)
                    whisper_compute = str(
                        cache.get("compute_type") or whisper_compute)
                model = cache["model"]
            fw_kwargs = {
                "language": lang,
                "beam_size": 1,
                "vad_filter": True,
                "condition_on_previous_text": False,
                "initial_prompt": (
                    "Turkce doktor komutu. Arka plan muzik ve ortam "
                    "seslerini yok say.")
            }
            try:
                segments, _info = model.transcribe(
                    temp_path, **fw_kwargs,
                    vad_parameters={
                        # D128 SUPER: 450->250ms (cumlede sessizlik biter
                        # bitmez kapat -> Alex daha cabuk cevaba gecer)
                        "min_silence_duration_ms": 250,
                        "speech_pad_ms": 120,
                    })
            except TypeError:
                segments, _info = model.transcribe(
                    temp_path, language=lang, beam_size=1, vad_filter=True)
            text = " ".join(
                (getattr(seg, "text", "") or "").strip()
                for seg in segments)
            return text.strip()
        except ImportError as ex:
            _ai_phone_transcribe_audio_local.last_error = (
                f"faster-whisper paketi yok: {ex}")
            pass
        except Exception as ex:
            _ai_phone_transcribe_audio_local.last_error = (
                f"faster-whisper calisamadi: {ex}")
            # BazÃƒâ€Ã‚Â± tarayici webm/mp4 dosyalari sonda kirik paket birakabiliyor.
            # PyAV ile toleransli decode edip float32 ses dalgasi olarak tekrar dene.
            try:
                audio_arr, decode_note = _ai_phone_decode_audio_tolerant(
                    audio_bytes, filename=filename, mime_type=mime_type, target_rate=16000)
                if audio_arr is not None:
                    with _AI_PHONE_ASR_MODEL_LOCK:
                        cache = _AI_PHONE_ASR_MODEL_CACHE
                        model = cache.get("model")
                    if model is not None:
                        try:
                            segments2, _info2 = model.transcribe(
                                audio_arr, **fw_kwargs,
                                vad_parameters={
                                    "min_silence_duration_ms": 450,
                                    "speech_pad_ms": 180,
                                })
                        except TypeError:
                            segments2, _info2 = model.transcribe(
                                audio_arr, language=lang, beam_size=1,
                                vad_filter=True)
                        text2 = " ".join(
                            (getattr(seg, "text", "") or "").strip()
                            for seg in segments2)
                        text2 = text2.strip()
                        if text2:
                            _ai_phone_transcribe_audio_local.last_error = ""
                            return text2
                    if decode_note:
                        _ai_phone_transcribe_audio_local.last_error += (
                            f" | decode notu: {decode_note}")
            except Exception as ex2:
                _ai_phone_transcribe_audio_local.last_error += (
                    f" | tolerant decode hatasi: {ex2}")

        try:
            import whisper
            with _AI_PHONE_ASR_MODEL_LOCK:
                cache = _AI_PHONE_ASR_MODEL_CACHE
                if (cache.get("engine") != "openai-whisper" or
                        cache.get("name") != model_name or
                        cache.get("model") is None):
                    cache["model"] = whisper.load_model(model_name)
                    cache["engine"] = "openai-whisper"
                    cache["name"] = model_name
                model = cache["model"]
            whisper_kwargs = {
                "language": lang,
                "initial_prompt": (
                    "Turkce doktor komutu. Arka plan muzik ve ortam "
                    "seslerini yok say."),
                "condition_on_previous_text": False,
                "no_speech_threshold": 0.62,
                "fp16": False,
            }
            try:
                result = model.transcribe(temp_path, **whisper_kwargs)
            except TypeError:
                result = model.transcribe(temp_path, language=lang)
            return (result.get("text") or "").strip()
        except ImportError as ex:
            if not getattr(_ai_phone_transcribe_audio_local, "last_error", ""):
                _ai_phone_transcribe_audio_local.last_error = (
                    f"openai-whisper paketi yok: {ex}")
            return None
        except Exception as ex:
            if not getattr(_ai_phone_transcribe_audio_local, "last_error", ""):
                _ai_phone_transcribe_audio_local.last_error = (
                    f"openai-whisper calisamadi: {ex}")
            return None
    except Exception as ex:
        _ai_phone_transcribe_audio_local.last_error = str(ex)
        return None
    finally:
        if temp_path:
            try:
                _Path(temp_path).unlink(missing_ok=True)
            except Exception:
                pass


def _ai_phone_native_mic_capabilities():
    info = {
        "available": False,
        "engine": "sounddevice",
        "devices": [],
        "default_input": None,
        "selected_input": None,
        "error": "",
        "hint": "",
    }
    try:
        import sounddevice as sd
    except Exception as ex:
        info["error"] = str(ex)
        info["hint"] = "sounddevice paketi kurulu degil"
        return info
    info["default_input"] = _ai_phone_audio_default_input_index(sd)
    try:
        selected = _ai_phone_select_native_input(sd)
        info["selected_input"] = selected
        devices = sd.query_devices()
        for idx, dev in enumerate(devices):
            try:
                inputs = int(dev.get("max_input_channels") or 0)
            except Exception:
                inputs = 0
            if inputs <= 0:
                continue
            info["devices"].append({
                "index": idx,
                "name": str(dev.get("name") or f"Input {idx}"),
                "channels": inputs,
                "samplerate": int(float(dev.get("default_samplerate") or 16000)),
                "score": _ai_phone_audio_input_score(
                    idx, dev, info.get("default_input")),
                "selected": bool(
                    selected and int(selected.get("index")) == int(idx)),
            })
        info["available"] = bool(selected or info["devices"])
        if not info["available"]:
            info["hint"] = "Windows tarafında aktif mikrofon girişi bulunamadı"
    except Exception as ex:
        info["error"] = str(ex)
        info["hint"] = "Mikrofon cihazlari okunamadi"
    return info


def _ai_phone_audio_name_key(value) -> str:
    text = str(value or "")
    try:
        text = unicodedata.normalize("NFKD", text)
        text = text.encode("ascii", "ignore").decode("ascii")
    except Exception:
        pass
    return re.sub(r"[^a-z0-9]+", " ", text.lower()).strip()


def _ai_phone_audio_default_input_index(sd):
    try:
        default_device = sd.default.device
        if hasattr(default_device, "input"):
            default_device = default_device.input
        elif isinstance(default_device, (list, tuple)) and default_device:
            default_device = default_device[0]
        idx = int(default_device)
        return idx if idx >= 0 else None
    except Exception:
        return None


def _ai_phone_audio_input_score(index, dev, default_index=None) -> int:
    name = _ai_phone_audio_name_key(dev.get("name") or "")
    try:
        channels = int(dev.get("max_input_channels") or 0)
    except Exception:
        channels = 0
    if channels <= 0:
        return -10000
    score = 0
    if default_index is not None and int(index) == int(default_index):
        score += 120
    if any(token in name for token in (
            "mikrofon", "microphone", "mic input", "mic in", "realtek hd audio mic")):
        score += 90
    elif re.search(r"(^| )mic( |$)", name):
        score += 70
    if any(token in name for token in ("array", "giris", "input")):
        score += 12
    if "realtek" in name:
        score += 5
    if any(token in name for token in (
            "stereo mix", "stereo kar", "hoparlor", "speaker", "output",
            "loopback", "monitor", "what u hear")):
        score -= 180
    return score


def _ai_phone_check_input(sd, index, rate) -> bool:
    try:
        sd.check_input_settings(
            device=int(index), channels=1,
            samplerate=int(rate or 16000), dtype="int16")
        return True
    except Exception:
        return False


def _ai_phone_select_native_input(sd):
    devices = list(sd.query_devices() or [])
    default_index = _ai_phone_audio_default_input_index(sd)
    env_pick = (
        os.environ.get("YAZKLINIK_WEBSHELL_MIC_DEVICE")
        or os.environ.get("YAZKLINIK_MIC_DEVICE")
        or ""
    ).strip()
    candidates = []
    for idx, dev in enumerate(devices):
        try:
            inputs = int(dev.get("max_input_channels") or 0)
        except Exception:
            inputs = 0
        if inputs <= 0:
            continue
        rate = int(float(dev.get("default_samplerate") or 16000))
        candidates.append({
            "index": idx,
            "name": str(dev.get("name") or f"Input {idx}"),
            "channels": inputs,
            "samplerate": rate,
            "score": _ai_phone_audio_input_score(idx, dev, default_index),
        })
    if env_pick:
        env_key = _ai_phone_audio_name_key(env_pick)
        for candidate in candidates:
            if (
                env_pick.isdigit() and int(candidate["index"]) == int(env_pick)
            ) or (env_key and env_key in _ai_phone_audio_name_key(candidate["name"])):
                if _ai_phone_check_input(sd, candidate["index"], candidate["samplerate"]):
                    candidate["selected_by"] = "env"
                    return candidate
    valid = [
        c for c in candidates
        if _ai_phone_check_input(sd, c["index"], c["samplerate"])
    ]
    if not valid:
        return None
    valid.sort(key=lambda c: (int(c.get("score") or 0), -int(c["index"])), reverse=True)
    selected = dict(valid[0])
    selected["selected_by"] = "default" if selected["index"] == default_index else "auto"
    return selected


def _ai_phone_focus_native_samples(samples):
    meta = {"enabled": True, "mode": "voice_focus_gate"}
    try:
        import numpy as np

        arr = np.asarray(samples, dtype=np.int16)
        if arr.size <= 0:
            meta["empty"] = True
            return arr, meta
        shaped = arr.reshape((-1, 1)) if arr.ndim == 1 else arr
        x = shaped.astype(np.float32)
        abs_before = np.abs(x)
        peak_before = float(abs_before.max()) if abs_before.size else 0.0
        rms_before = float(np.sqrt(np.mean(np.square(x)))) if x.size else 0.0
        meta.update({
            "peak_before": round(peak_before, 2),
            "rms_before": round(rms_before, 2),
        })
        if peak_before < 160:
            meta["too_quiet"] = True
            return shaped.astype(np.int16), meta

        x = x - float(np.mean(x))
        if x.shape[0] > 1:
            hp = np.empty_like(x)
            hp[0] = x[0]
            hp[1:] = x[1:] - (0.965 * x[:-1])
            x = (0.72 * x) + (0.28 * hp)

        absx = np.abs(x)
        floor = float(np.percentile(absx, 38)) if absx.size else 0.0
        threshold = max(220.0, floor * 2.2)
        quiet = absx < threshold
        x[quiet] *= 0.18
        peak_after = float(np.max(np.abs(x))) if x.size else 0.0
        if peak_after > 0 and peak_after < 12000:
            x *= min(3.0, 12000.0 / peak_after)
        x = np.clip(x, -32768, 32767).astype(np.int16)
        meta.update({
            "noise_floor": round(floor, 2),
            "gate_threshold": round(threshold, 2),
            "peak_after": int(np.max(np.abs(x))) if x.size else 0,
        })
        return x, meta
    except Exception as ex:
        meta["error"] = str(ex)
        return samples, meta


def _ai_phone_record_native_wav(seconds=7.0, samplerate=16000):
    import io
    import wave
    import numpy as np
    import sounddevice as sd

    seconds = max(2.0, min(float(seconds or 7.0), 12.0))
    samplerate = int(samplerate or 16000)
    record_rate = samplerate
    selected = _ai_phone_select_native_input(sd)
    if not selected:
        raise RuntimeError("Uygun mikrofon girişi bulunamadı")
    device = int(selected["index"])
    record_rate = int(selected.get("samplerate") or samplerate)
    frames = int(record_rate * seconds)
    audio = sd.rec(
        frames, samplerate=record_rate, channels=1, dtype="int16",
        device=device)
    sd.wait()
    arr = np.asarray(audio, dtype=np.int16)
    if arr.size <= 0:
        raise RuntimeError("Mikrofondan ses verisi alinamadi")
    arr, focus_meta = _ai_phone_focus_native_samples(arr)
    _ai_phone_record_native_wav.last_focus_meta = focus_meta
    buf = io.BytesIO()
    with wave.open(buf, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(record_rate)
        wf.writeframes(arr.tobytes())
    return buf.getvalue()


