    """Alex egitim sayfasi: kalici bilgiler + ozel komutlar (Windows aksiyon dahil)."""
    user_key = "alex_" + str(session.get("user") or "doktor")
    flash_msg = ""

    if request.method == "POST":
        action = (request.form.get("action") or "").strip()
        if action == "add_fact":
            fact = (request.form.get("fact") or "").strip()
            category = (request.form.get("category") or "genel").strip()
            if _alex_fact_add(user_key, fact, category):
                flash_msg = "Bilgi kaydedildi"
            else:
                flash_msg = "Bilgi eklenemedi"
        elif action == "delete_fact":
            fid = request.form.get("fact_id") or ""
            if _alex_fact_delete(fid, user_key=user_key):
                flash_msg = "Bilgi silindi"
        elif action == "add_command":
            trigger = (request.form.get("trigger_phrase") or "").strip()
            action_type = (request.form.get("action_type") or "llm").strip()
            action_text = (request.form.get("action_text") or "").strip()
            description = (request.form.get("description") or "").strip()
            if _alex_command_add(user_key, trigger, action_text,
                                 action_type=action_type, description=description):
                flash_msg = "Komut kaydedildi"
            else:
                flash_msg = "Komut eklenemedi"
        elif action == "delete_command":
            cid = request.form.get("command_id") or ""
            if _alex_command_delete(cid, user_key=user_key):
                flash_msg = "Komut silindi"
        elif action == "clear_memory":
            _alex_memory_clear(user_key)
            flash_msg = "Konusma gecmisi temizlendi"
