@app.route("/api/alex/research", methods=["POST"])
@login_required
def api_alex_research():
    """Alex'e online arastirma yaptir: PubMed veya web.

    POST JSON: {
        "query": "konu",
        "source": "pubmed" | "web" | "auto",
        "max_results": 5 (opsiyonel)
    }
    Response JSON: {ok, source, query, summary, detailed, results[], result_count, id}
    """
    try:
        data = request.get_json(force=True, silent=True) or {}
    except Exception:
        data = {}
    query = (data.get("query") or "").strip()
    source = (data.get("source") or "auto").strip().lower()
    max_results = int(data.get("max_results") or 5)
    if max_results < 1:
        max_results = 5
    if max_results > 15:
        max_results = 15
    if not query:
        return jsonify({"ok": False, "error": "query bos"}), 400
    # "auto": kullanici metninden tahmin
    if source == "auto":
        detected_src, detected_q = _alex_detect_research_intent(query)
        if detected_src:
            source = detected_src
            if detected_q:
                query = detected_q
        else:
            source = "pubmed"  # tibbi kullanim default
    if source not in ("pubmed", "web"):
        source = "pubmed"
    user_key = "alex_" + str(session.get("user") or "doktor")
    try:
        out = _alex_research_run(user_key, query, source=source,
                                 max_results=max_results, save=True)
    except Exception as exc:
        try:
            print(f"[ALEX-RES] run HATA: {exc}", flush=True)
        except Exception:
            pass
        return jsonify({"ok": False, "error": str(exc)}), 500
    return jsonify(out)


