@app.route("/voluson-import", methods=["GET"])
@login_required
def voluson_import_page():
    """Voluson PDF import sayfasi - manuel tarama + son import'lar."""
    try:
        import yazklinik_voluson as _vol
        _vol.init_db()
    except Exception:
        pass
    import sqlite3 as _sql
    db_p = (os.environ.get("YAZKLINIK_DB_PATH")
            or r"D:\YazKlinik_Final_D300\local_db\yazklinik_v68.sqlite3")
    con = _sql.connect(db_p)
    rows_html = ""
    total = 0
    matched = 0
    try:
        total = con.execute(
            "SELECT COUNT(*) FROM voluson_reports").fetchone()[0]
        matched = con.execute(
            "SELECT COUNT(*) FROM voluson_reports WHERE patient_key IS NOT NULL"
        ).fetchone()[0]
        cur = con.execute(
            "SELECT id, exam_date, patient_name, patient_key, ga_aua, efw_g, "
            "efw_percentile, clinical_flags, imported_ts "
            "FROM voluson_reports ORDER BY id DESC LIMIT 50")
        for r in cur.fetchall():
            (rid, exd, pn, pk, ga, efw, efp, flags_json, imp_ts) = r
            try:
                import json as _json
                flags = _json.loads(flags_json or "[]")
            except Exception:
                flags = []
            flags_html = (
                " ".join(f'<span class="badge bg-warning text-dark">{sh(f)}</span>'
                         for f in flags) if flags else "")
            match_badge = (f'<span class="badge bg-success">{sh(pk)}</span>'
                           if pk else '<span class="badge bg-secondary">eslesmemis</span>')
            rows_html += f"""
            <tr>
              <td>{rid}</td>
              <td class="small">{sh(exd or '')}</td>
              <td><b>{sh(pn or '')}</b></td>
              <td>{match_badge}</td>
              <td class="text-center">{sh(ga or '')}</td>
              <td class="text-center">{sh(str(efw) + 'g' if efw else '')}
                  {f'<small class="text-muted">({efp:.1f}p)</small>' if efp else ''}</td>
              <td>{flags_html}</td>
            </tr>"""
    except Exception as exc:
        rows_html = f'<tr><td colspan="7" class="text-danger">DB hata: {exc}</td></tr>'
    finally:
        con.close()
    if not rows_html:
        rows_html = ('<tr><td colspan="7" class="text-center text-muted py-3">'
                     'Henuz import yok</td></tr>')
    nas_root = (os.environ.get("YAZKLINIK_NAS_ROOT")
                or r"E:\USG\Hastalar")
    bk_panel = _bk_voluson_context_panel_html()

    page = f"""
    <!DOCTYPE html><html lang="tr"><head>
    <meta charset="UTF-8"><title>Voluson Import</title>
    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css">
    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.0/font/bootstrap-icons.css">
    </head><body class="container my-4">

    <h2><i class="bi bi-file-medical"></i> Voluson USG Raporu Import</h2>
    <p class="text-muted">NAS klasoru otomatik tarar + tum Voluson OB PDF'lerini hasta
    DB'sine isler. Hastalar otomatik eslesir (folder_key).</p>
    {bk_panel}

    <div class="row mb-3">
      <div class="col-md-4"><div class="card text-center bg-primary text-white">
        <div class="card-body py-2"><h3 class="mb-0">{total}</h3><small>Toplam import</small></div></div></div>
      <div class="col-md-4"><div class="card text-center bg-success text-white">
        <div class="card-body py-2"><h3 class="mb-0">{matched}</h3><small>Hasta eslesti</small></div></div></div>
      <div class="col-md-4"><div class="card text-center bg-warning">
        <div class="card-body py-2"><h3 class="mb-0">{total - matched}</h3><small>Eslesmemis</small></div></div></div>
    </div>

    <div class="card mb-4">
      <div class="card-header"><b>NAS Tarama</b></div>
      <div class="card-body">
        <div class="input-group">
          <span class="input-group-text">NAS root</span>
          <input id="ykVolRoot" type="text" class="form-control" value="{sh(nas_root)}">
          <button id="ykVolScan" class="btn btn-primary">
            <i class="bi bi-arrow-repeat"></i> Tara + Import
          </button>
        </div>
        <div class="form-check mt-2">
          <input type="checkbox" class="form-check-input" id="ykVolForce">
          <label class="form-check-label small" for="ykVolForce">
            Mevcut PDF'leri tekrar import et (force)
          </label>
        </div>
        <div id="ykVolStatus" class="mt-2 small text-muted"></div>
      </div>
    </div>

    <div class="card">
      <div class="card-header"><b>Son 50 Import</b></div>
      <div class="card-body p-0">
        <table class="table table-hover table-sm mb-0">
          <thead class="table-light">
            <tr><th>#</th><th>Tarih</th><th>Hasta</th><th>Eslesme</th>
                <th>GA</th><th>EFW</th><th>Klinik flags</th></tr>
          </thead>
          <tbody>{rows_html}</tbody>
        </table>
      </div>
    </div>

    <p class="text-muted small mt-3">
      <a href="/">← Ana sayfa</a> · <a href="/ses-ve-alex">Alex</a>
    </p>

    <script>
    document.getElementById('ykVolScan').addEventListener('click', async () => {{
      const root = document.getElementById('ykVolRoot').value.trim();
      const force = document.getElementById('ykVolForce').checked;
      const st = document.getElementById('ykVolStatus');
      st.innerHTML = '<i class="spinner-border spinner-border-sm"></i> Tarama basladi...';
      try {{
        const r = await fetch('/api/voluson/scan', {{
          method:'POST', credentials:'same-origin',
          headers:{{'Content-Type':'application/json'}},
          body: JSON.stringify({{root:root, force:force}})
        }});
        const d = await r.json();
        if (d.ok) {{
          st.innerHTML = '<span class="text-success">Tarandi: ' + d.scanned +
            ', Import: ' + d.imported + ', Atlandi: ' + d.skipped +
            ', Hata: ' + (d.errors || []).length + '</span>';
          setTimeout(() => location.reload(), 1500);
        }} else {{
          st.innerHTML = '<span class="text-danger">' + (d.error || 'hata') + '</span>';
        }}
      }} catch(e) {{
        st.innerHTML = '<span class="text-danger">' + e.message + '</span>';
      }}
    }});
    </script>
    </body></html>
    """
    return page


