@app.route("/api/alex/rag/upload-text", methods=["POST"])
@login_required
def api_alex_rag_upload_text():
    """Metin -> RAG index."""
    if str(session.get("role") or "") != "doktor":
        return jsonify({"ok": False, "error": "Sadece doktor"}), 403
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()
    text = (data.get("text") or "").strip()
    if not text or len(text) < 30:
        return jsonify({"ok": False, "error": "Metin cok kisa"}), 400
    try:
        import yazklinik_rag as _rag
        n_doc, n_chunk = _rag.index_text_document(
            title or "Manuel-Metin", text, kind="manual", source="ui-paste")
        return jsonify({"ok": True, "chunks": n_chunk,
                       "message": f"{n_chunk} chunk index'lendi"})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/alex/rag/upload-pdf", methods=["POST"])
@login_required
def api_alex_rag_upload_pdf():
    """PDF dosyasi -> parse + chunk + index."""
    if str(session.get("role") or "") != "doktor":
        return jsonify({"ok": False, "error": "Sadece doktor"}), 403
    f = request.files.get("pdf")
    if not f:
        return jsonify({"ok": False, "error": "PDF dosyasi yok"}), 400
    import tempfile
    title = (request.form.get("title") or
             os.path.basename(f.filename or "doc.pdf").rsplit(".", 1)[0])
    with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tf:
        f.save(tf.name)
        tmp_path = tf.name
    try:
        import yazklinik_rag as _rag
        ok, msg = _rag.index_pdf_file(tmp_path, title=title)
        if not ok:
            return jsonify({"ok": False, "error": msg}), 400
        return jsonify({"ok": True, "message": msg})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500
    finally:
        try: os.unlink(tmp_path)
        except Exception: pass


@app.route("/api/alex/rag/search", methods=["POST"])
@login_required
def api_alex_rag_search():
    data = request.get_json(silent=True) or {}
    q = (data.get("query") or "").strip()
    top_k = int(data.get("top_k") or 5)
    threshold = float(data.get("threshold") or 0.7)
    if not q:
        return jsonify({"ok": False, "error": "query bos"}), 400
    try:
        import yazklinik_rag as _rag
        results = _rag.search(q, top_k=top_k, threshold=threshold)
        return jsonify({"ok": True, "count": len(results), "results": results})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/alex-rag-merkezi", methods=["GET"])
@login_required
def alex_rag_merkezi_page():
    """RAG (semantic search) merkezi - durum + re-index + test search."""
    try:
        import yazklinik_rag as _rag
        col = _rag._get_collection()
        n = col.count()
        path = str(_rag.CHROMA_DIR)
        model = _rag.EMBED_MODEL
    except Exception as ex:
        n = 0; path = "(yuklenemedi)"; model = "?"; n_err = str(ex)
    content = f"""
    <style>
      .rag-tile {{background:#fff;border:1px solid #d8e7f3;border-radius:14px;
                  padding:18px;margin-bottom:16px;box-shadow:0 6px 18px rgba(15,55,80,.06);}}
      .rag-stat {{font-size:42px;font-weight:800;color:#0d6efd;}}
      .rag-result {{border:1px solid #e2e8f0;border-radius:8px;padding:10px;
                    margin-bottom:8px;background:#f8fafc;}}
      .rag-score {{display:inline-block;padding:2px 8px;border-radius:12px;
                   background:#e0f2fe;color:#0369a1;font-weight:700;font-size:12px;}}
      .rag-kind {{display:inline-block;padding:2px 8px;border-radius:12px;
                  background:#fef3c7;color:#92400e;font-weight:700;font-size:12px;}}
    </style>

    <div class="container my-4">
      <h2><i class="bi bi-search"></i> Alex RAG Merkezi (Semantic Search)</h2>
      <p class="text-muted">Hasta dosyalari, USG raporlari, arastirma ozetleri
      <b>vector DB</b>'ye indekslenir. Alex her sorguda en alakali 3-5 belgeyi
      otomatik prompt'a ekler.</p>

      <div class="row g-3 mb-3">
        <div class="col-md-4"><div class="rag-tile text-center">
          <div class="rag-stat">{n}</div>
          <small>Index'lenmis belge</small></div></div>
        <div class="col-md-8"><div class="rag-tile">
          <small class="text-muted">Model</small><br>
          <code>{sh(model)}</code><br>
          <small class="text-muted mt-2">Yol</small><br>
          <code style="font-size:11px;">{sh(path)}</code>
        </div></div>
      </div>

      <div class="rag-tile">
        <h4><i class="bi bi-arrow-clockwise"></i> Re-Index</h4>
        <p class="text-muted small">Yeni hasta, USG veya arastirma eklenince
        tekrar index'le. Tum DB taranir, yeni belgeler eklenir.</p>
        <button id="ragReindex" class="btn btn-primary">
          <i class="bi bi-cpu"></i> Tum DB'yi Re-Index
        </button>
        <div id="ragReindexStatus" class="mt-2 small"></div>
      </div>

      <div class="rag-tile">
        <h4><i class="bi bi-upload"></i> Manuel Bilgi Yukle</h4>
        <p class="text-muted small">Doktorun ozel notlari, kilavuzlar, PDF
        kitap/makaleler. Alex bunlari da arama kapsamina alir.</p>

        <div class="mb-3">
          <label class="form-label small"><b>Metin yapistir</b></label>
          <input id="ragUpTitle" type="text" class="form-control mb-2"
                 placeholder="Baslik (orn 'Preeklampsi protokol 2026')">
          <textarea id="ragUpText" class="form-control" rows="4"
                    placeholder="Metni buraya yapistir..."></textarea>
          <button id="ragUpTextBtn" class="btn btn-success mt-2">
            <i class="bi bi-file-text"></i> Metni Index'le
          </button>
        </div>

        <hr>

        <div>
          <label class="form-label small"><b>PDF Dosyasi</b></label>
          <div class="input-group">
            <input id="ragUpPdf" type="file" accept=".pdf" class="form-control">
            <button id="ragUpPdfBtn" class="btn btn-success">
              <i class="bi bi-file-pdf"></i> PDF'i Index'le
            </button>
          </div>
        </div>
        <div id="ragUpStatus" class="mt-2 small"></div>
      </div>

      <div class="rag-tile">
        <h4><i class="bi bi-search-heart"></i> Test Search</h4>
        <p class="text-muted small">Soru sor, vector DB'den en alakali
        belgeleri gor (Alex'in goruyor oldugu sey).</p>
        <div class="input-group mb-2">
          <input id="ragQuery" class="form-control" type="text"
                 placeholder='orn: "preeklampsi tedavisi" / "Kilic Seval son USG"'>
          <button id="ragSearchBtn" class="btn btn-info text-white">Ara</button>
        </div>
        <div id="ragResults"></div>
      </div>

      <p class="text-muted small mt-3">
        <a href="/ses-ve-alex">← Alex</a> ·
        <a href="/alex-egitim-merkezi">LLM Egitim</a> ·
        <a href="/alex-arastirma">Arastirma</a>
      </p>
    </div>

    <script>
    function esc(s){{return String(s||'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));}}

    document.getElementById('ragReindex').addEventListener('click', async () => {{
      const st = document.getElementById('ragReindexStatus');
      st.innerHTML = '<i class="spinner-border spinner-border-sm"></i> Re-index basladi (1-2 dk olabilir)...';
      try {{
        const r = await fetch('/api/alex/rag/reindex',
          {{method:'POST', credentials:'same-origin'}});
        const d = await r.json();
        if (d.ok) {{
          const s = d.stats;
          st.innerHTML = '<span class="text-success">Tamam: ' +
            'Toplam ' + s.total + ' belge (' +
            s.researches + ' arastirma, ' + s.voluson + ' USG, ' +
            s.facts + ' fact, ' + s.patients + ' hasta)</span>';
          setTimeout(() => location.reload(), 2000);
        }} else {{
          st.innerHTML = '<span class="text-danger">Hata: ' + esc(d.error||'') + '</span>';
        }}
      }} catch(e) {{ st.innerHTML = '<span class="text-danger">'+esc(e.message)+'</span>'; }}
    }});

    async function ragSearch() {{
      const q = document.getElementById('ragQuery').value.trim();
      if (!q) return;
      const out = document.getElementById('ragResults');
      out.innerHTML = '<i class="spinner-border spinner-border-sm"></i> Ariyor...';
      try {{
        const r = await fetch('/api/alex/rag/search', {{
          method:'POST', credentials:'same-origin',
          headers:{{'Content-Type':'application/json'}},
          body: JSON.stringify({{query:q, top_k:5, threshold:0.8}})
        }});
        const d = await r.json();
        if (!d.ok) {{ out.innerHTML = '<span class="text-danger">'+esc(d.error||'')+'</span>'; return; }}
        if (d.count === 0) {{ out.innerHTML = '<span class="text-muted">Alakali belge yok (threshold disinda)</span>'; return; }}
        let html = '<div class="mt-2"><b>'+d.count+' sonuc:</b></div>';
        for (const r of d.results) {{
          html += '<div class="rag-result">' +
            '<span class="rag-score">skor ' + r.score + '</span> ' +
            '<span class="rag-kind">' + esc(r.metadata.kind||'?') + '</span> ' +
            '<div class="mt-1 small">' + esc(r.text||'') + '</div>' +
            '</div>';
        }}
        out.innerHTML = html;
      }} catch(e) {{ out.innerHTML = '<span class="text-danger">'+esc(e.message)+'</span>'; }}
    }}
    document.getElementById('ragSearchBtn').addEventListener('click', ragSearch);
    document.getElementById('ragQuery').addEventListener('keydown', e => {{
      if (e.key === 'Enter') ragSearch();
    }});

    document.getElementById('ragUpTextBtn').addEventListener('click', async () => {{
      const title = document.getElementById('ragUpTitle').value.trim();
      const text = document.getElementById('ragUpText').value.trim();
      const st = document.getElementById('ragUpStatus');
      if (text.length < 30) {{ st.innerHTML = '<span class="text-danger">Metin cok kisa</span>'; return; }}
      st.innerHTML = '<i class="spinner-border spinner-border-sm"></i> Index basliyor...';
      try {{
        const r = await fetch('/api/alex/rag/upload-text', {{
          method:'POST', credentials:'same-origin',
          headers:{{'Content-Type':'application/json'}},
          body: JSON.stringify({{title:title, text:text}})
        }});
        const d = await r.json();
        if (d.ok) {{
          st.innerHTML = '<span class="text-success">✓ ' + esc(d.message) + '</span>';
          document.getElementById('ragUpText').value = '';
          setTimeout(() => location.reload(), 1500);
        }} else {{
          st.innerHTML = '<span class="text-danger">' + esc(d.error||'') + '</span>';
        }}
      }} catch(e) {{ st.innerHTML = '<span class="text-danger">'+esc(e.message)+'</span>'; }}
    }});

    document.getElementById('ragUpPdfBtn').addEventListener('click', async () => {{
      const file = document.getElementById('ragUpPdf').files[0];
      const st = document.getElementById('ragUpStatus');
      if (!file) {{ st.innerHTML = '<span class="text-danger">PDF sec</span>'; return; }}
      st.innerHTML = '<i class="spinner-border spinner-border-sm"></i> PDF parse + index basladi...';
      const fd = new FormData();
      fd.append('pdf', file);
      fd.append('title', file.name.replace(/\\.pdf$/i,''));
      try {{
        const r = await fetch('/api/alex/rag/upload-pdf',
          {{method:'POST', credentials:'same-origin', body:fd}});
        const d = await r.json();
        if (d.ok) {{
          st.innerHTML = '<span class="text-success">✓ ' + esc(d.message) + '</span>';
          document.getElementById('ragUpPdf').value = '';
          setTimeout(() => location.reload(), 1500);
        }} else {{
          st.innerHTML = '<span class="text-danger">' + esc(d.error||'') + '</span>';
        }}
      }} catch(e) {{ st.innerHTML = '<span class="text-danger">'+esc(e.message)+'</span>'; }}
    }});
    </script>
    """
    return render(content, title="Alex RAG Merkezi")


