@app.route("/api/alex/training/export", methods=["POST"])
@login_required
def api_alex_training_export():
    """JSONL formatinda LoRA dataset export."""
    if str(session.get("role") or "") != "doktor":
        return jsonify({"ok": False, "error": "Sadece doktor"}), 403
    out_dir = os.path.join(
        os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else ".",
        "alex_training_export")
    try:
        os.makedirs(out_dir, exist_ok=True)
    except Exception:
        pass
    import datetime as _dt
    out_path = os.path.join(
        out_dir,
        f"alex_train_{_dt.datetime.now().strftime('%Y%m%d_%H%M%S')}.jsonl")
    n, err = _alex_training_export_jsonl(out_path)
    if err:
        return jsonify({"ok": False, "error": err, "path": out_path}), 400
    return jsonify({"ok": True, "count": n, "path": out_path})


@app.route("/api/alex/modelfile/create", methods=["POST"])
@login_required
def api_alex_modelfile_create():
    """POST {name, base_model, system_prompt} -> ollama create."""
    if str(session.get("role") or "") != "doktor":
        return jsonify({"ok": False, "error": "Sadece doktor"}), 403
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "yaz").strip()
    base = (data.get("base_model") or "llama3.1:8b").strip()
    sys_p = (data.get("system_prompt") or "").strip()
    ok, msg = _alex_ollama_create_custom_model(
        name=name, base_model=base, system_prompt=sys_p)
    return jsonify({"ok": ok, "message": msg})


