@app.route("/api/mikrofon/tani", methods=["GET"])
@login_required
def api_mikrofon_tani():
    """Mobil + Mac Chrome icin mikrofon erisilebilirligi tanisi.
    Server-side: HTTPS portu, sertifika varligi, scheme, host listesi.
    Client gerek HTTPS gerek izin sorunlarini bildirir; bu endpoint
    sunucu tarafi onkosullari hizla netlestirir."""
    https_enabled = False
    https_port = "5443"
    https_hosts = []
    cert_info = {"path": "", "exists": False, "size_bytes": 0}
    try:
        https_enabled = _yk_https_enabled()
        https_port = _yk_https_port()
        https_hosts = _yk_https_hosts()
        cert_path, _ = _yk_https_cert_files()
        cert_info["path"] = str(cert_path)
        try:
            cert_info["exists"] = cert_path.exists()
            cert_info["size_bytes"] = (
                int(cert_path.stat().st_size) if cert_path.exists() else 0)
        except Exception:
            pass
    except Exception:
        pass

    host = (request.host or "").split(":")[0] or "127.0.0.1"
    scheme = (request.scheme or "http").lower()
    is_secure = (scheme == "https" or host in {"127.0.0.1", "localhost", "::1"})
    has_fitz = bool(globals().get("HAS_FITZ"))

    local_asr = {"available": False, "engine": "", "model": ""}
    try:
        import faster_whisper  # noqa: F401
        local_asr["available"] = True
        local_asr["engine"] = "faster-whisper"
    except Exception:
        try:
            import whisper  # noqa: F401
            local_asr["available"] = True
            local_asr["engine"] = "openai-whisper"
        except Exception:
            pass

    native = _ai_phone_native_mic_capabilities()
    https_url = (f"https://{host}:{https_port}{request.path or '/'}")

    checks = [
        {
            "key": "https_enabled",
            "label": "HTTPS dinleyicisi açık",
            "ok": bool(https_enabled),
            "detail": (f"Port {https_port}, sertifika "
                       f"{'var' if cert_info['exists'] else 'yok'}"),
            "fix": ("yazklinik_config.json içinde enable_https=1 yapın, "
                    "sonra sunucuyu yeniden başlatın."),
        },
        {
            "key": "secure_context",
            "label": "Tarayıcı secure-context (HTTPS / localhost)",
            "ok": bool(is_secure),
            "detail": f"Şu anda: {scheme}://{request.host}",
            "fix": ("Web mikrofonu için bu sayfayı " + https_url +
                    " adresinden açın. Mac Chrome sertifika uyarısı verirse "
                    "Gelişmiş -> devam et seçin."),
        },
        {
            "key": "cert_present",
            "label": "Self-signed sertifika dosyaları hazır",
            "ok": bool(cert_info["exists"]),
            "detail": cert_info["path"],
            "fix": ("certs/ klasörü oluşturulup self-signed sertifika "
                    "yeniden üretilecek (sunucu yeniden başlatıldığında)."),
        },
        {
            "key": "native_mic",
            "label": "Yerel (Windows/Mac) mikrofon köprüsü",
            "ok": bool(native.get("available")),
            "detail": (native.get("hint") or native.get("error")
                       or "Hazır"),
            "fix": ("Tarayıcı mikrofonu engellense bile native köprüsü "
                    "fallback sağlar; WAV kaydedip Whisper'a gönderir."),
        },
        {
            "key": "local_asr",
            "label": "Yerel ASR (faster-whisper / whisper) yüklü",
            "ok": bool(local_asr["available"]),
            "detail": (f"engine={local_asr['engine']}"
                       if local_asr["available"]
                       else "Yüklü değil; OpenAI/Whisper API'ye düşülebilir."),
            "fix": "pip install faster-whisper",
        },
    ]
    return jsonify({
        "ok": True,
        "scheme": scheme,
        "host": request.host,
        "https_enabled": https_enabled,
        "https_port": https_port,
        "https_hosts": https_hosts,
        "https_url": https_url,
        "cert": cert_info,
        "native_record": native,
        "local_asr": local_asr,
        "checks": checks,
        "summary": {
            "ok_count": sum(1 for c in checks if c["ok"]),
            "fail_count": sum(1 for c in checks if not c["ok"]),
        },
    })


