@app.route("/api/phone/live-native-record", methods=["POST"])
@login_required
def api_phone_live_native_record():
    data = request.get_json(silent=True) or {}
    if request.args.get("dry_run") or data.get("dry_run"):
        return jsonify({
            "ok": True,
            "dry_run": True,
            "native_record": _ai_phone_native_mic_capabilities(),
        })
    seconds = data.get("seconds", 7)
    language = (data.get("language") or "tr").strip() or "tr"
    caller = (data.get("caller") or session.get("user") or "web-test").strip()
    voice_focus = _voice_focus_truthy(data.get("voice_focus", True))
    want_reply = data.get("reply", True)
    want_reply = not (want_reply is False or str(want_reply).lower() in ("0", "false", "no"))
    history = data.get("history") or []
    if _alex_runtime_blocks_caller(caller):
        return jsonify({
            "ok": True,
            "text": "",
            "reply": "",
            "status": "alex_runtime_disabled",
            "language": language,
            "voice_focus": bool(voice_focus),
            "alex_runtime_disabled": True,
            "native_record": {"available": False, "hint": "Alex ses modu kapalı"},
        })
    caps = _ai_phone_native_mic_capabilities()
    if not caps.get("available"):
        msg = caps.get("hint") or caps.get("error") or "Windows mikrofonu hazır değil"
        return jsonify({
            "ok": False,
            "error": msg,
            "native_record": caps,
        }), 503
    if not _AI_PHONE_NATIVE_RECORD_LOCK.acquire(blocking=False):
        return jsonify({
            "ok": False,
            "error": "Başka bir ses kaydı devam ediyor; birkaç saniye sonra tekrar deneyin",
        }), 409
    try:
        wav_bytes = _ai_phone_record_native_wav(seconds=seconds)
        focus_meta = getattr(_ai_phone_record_native_wav, "last_focus_meta", {})
        text = _ai_phone_transcribe_audio_bytes(
            wav_bytes, filename="windows-mic.wav", mime_type="audio/wav",
            language=language).strip()
        if voice_focus:
            text = _voice_focus_clean_transcript(text, caller=caller)
        if not text:
            return jsonify({
                "ok": True,
                "text": "",
                "reply": "",
                "status": "no_speech",
                "voice_focus": bool(voice_focus),
                "voice_focus_meta": focus_meta,
                "native_record": caps,
            })
        reply = ""
        status = "transcribed"
        if want_reply:
            reply, status = _ai_phone_generate_dialog_reply(
                text, history=history, caller=caller, channel="native_mic")
            try:
                _record_ai_phone_call(
                    caller, f"user: {text}", reply, status,
                    source_channel="native_mic")
            except Exception:
                pass
        return jsonify({
            "ok": True,
            "text": text,
            "reply": reply,
            "status": status,
            "language": language,
            "voice_focus": bool(voice_focus),
            "voice_focus_meta": focus_meta,
            "native_record": caps,
        })
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500
    finally:
        try:
            _AI_PHONE_NATIVE_RECORD_LOCK.release()
        except Exception:
            pass


@app.route("/api/phone/native-record-wav", methods=["POST"])
@login_required
def api_phone_native_record_wav():
    import base64 as _b64
    data = request.get_json(silent=True) or {}
    if request.args.get("dry_run") or data.get("dry_run"):
        return jsonify({
            "ok": True,
            "dry_run": True,
            "native_record": _ai_phone_native_mic_capabilities(),
        })
    seconds = data.get("seconds", 7)
    caps = _ai_phone_native_mic_capabilities()
    if not caps.get("available"):
        msg = caps.get("hint") or caps.get("error") or "Windows mikrofonu hazir degil"
        return jsonify({
            "ok": False,
            "error": msg,
            "native_record": caps,
        }), 503
    if not _AI_PHONE_NATIVE_RECORD_LOCK.acquire(blocking=False):
        return jsonify({
            "ok": False,
            "error": "Başka bir ses kaydı devam ediyor; birkaç saniye sonra tekrar deneyin",
        }), 409
    try:
        wav_bytes = _ai_phone_record_native_wav(seconds=seconds)
        focus_meta = getattr(_ai_phone_record_native_wav, "last_focus_meta", {})
        return jsonify({
            "ok": True,
            "audio_b64": (
                "data:audio/wav;base64,"
                + _b64.b64encode(wav_bytes).decode("ascii")),
            "mime_type": "audio/wav",
            "seconds": seconds,
            "voice_focus": True,
            "voice_focus_meta": focus_meta,
            "native_record": caps,
        })
    except Exception as ex:
        return jsonify({
            "ok": False,
            "error": str(ex),
            "native_record": caps,
        }), 500
    finally:
        try:
            _AI_PHONE_NATIVE_RECORD_LOCK.release()
        except Exception:
            pass


@app.route("/yz-telefon-diyalog")
@login_required
def ai_phone_dialog_shortcut():
    return redirect(url_for("ai_phone_assistant_page"))


@app.route("/sohbet-merkezi", methods=["GET", "POST"])
@app.route("/randevu-onay", methods=["GET", "POST"])
@permission_required("view_chat_center")
def chat_center_page():
    """Telefon, web sohbet ve randevu talepleri icin tek merkez."""
    _ensure_ai_phone_schema()
    _init_appointments_table()

    if request.method == "POST":
        action = request.form.get("action", "").strip()
        next_url = url_for("chat_center_page",
                           filter=request.args.get("filter", "open"))
        if action in {
            "approve_pending", "reject_pending", "mark_call", "manual_note"
        } and not can("manage_chat_center"):
            flash("Bu islem icin sohbet merkezi yetkisi gerekli.", "danger")
            return redirect(next_url)

        if action == "approve_pending":
            pending_id = request.form.get("pending_id", "")
            ok, msg, appt_id = _chat_center_book_pending_appointment(
                pending_id, request.form,
                force=request.form.get("force_booking") == "1")
            flash(msg, "success" if ok else "warning")
            if ok and appt_id:
                return redirect(url_for("edit_appointment", appt_id=appt_id))
            return redirect(next_url)

        if action == "reject_pending":
            _chat_center_set_pending_status(
                request.form.get("pending_id", ""), "rejected")
            flash("Randevu talebi reddedildi.", "info")
            return redirect(next_url)

        if action == "mark_call":
            _chat_center_update_call(
                request.form.get("call_id", ""),
                request.form.get("staff_status", "open"),
                request.form.get("staff_note", ""))
            flash("Sohbet durumu kaydedildi.", "success")
            return redirect(next_url)

        if action == "manual_note":
            caller = request.form.get("caller", "").strip()
            message = request.form.get("message", "").strip()
            channel = request.form.get("channel", "manual").strip() or "manual"
            if not message:
                flash("Not/metin gerekli.", "warning")
                return redirect(next_url)
            if request.form.get("generate_reply") == "1":
                reply, status = _ai_phone_generate_dialog_reply(
                    message, caller=caller, channel=channel)
            else:
                reply, status = "Klinik ekibe manuel not birakildi.", "manual_note"
            _record_ai_phone_call(caller, message, reply, status,
                                  source_channel=channel)
            flash("Sohbet/not merkeze eklendi.", "success")
            return redirect(next_url)

    filt = request.args.get("filter", "open").strip().lower()
    if filt not in {"open", "callback", "appointments", "emergency", "done", "all"}:
        filt = "open"

    pending_where = "status='pending'"
    call_where = "COALESCE(staff_status, 'open') = 'open'"
    call_params = []
    if filt == "callback":
        call_where = "COALESCE(staff_status, 'open') = 'callback'"
        pending_where = "0"
    elif filt == "appointments":
        call_where = "status LIKE 'appointment%'"
        pending_where = "1=1"
    elif filt == "emergency":
        call_where = "status LIKE '%emergency%'"
        pending_where = "0"
    elif filt == "done":
        call_where = "COALESCE(staff_status, 'open') = 'done'"
        pending_where = "status IN ('booked', 'rejected', 'cancelled')"
    elif filt == "all":
        call_where = "1=1"
        pending_where = "1=1"

    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            def _count_value(sql, params=()):
                raw = con.execute(sql, tuple(params or ())).fetchone()
                if raw is None:
                    return 0
                if isinstance(raw, dict):
                    if "cnt" in raw:
                        try:
                            return int(raw.get("cnt") or 0)
                        except Exception:
                            return 0
                    try:
                        first_val = next(iter(raw.values()))
                        return int(first_val or 0)
                    except Exception:
                        return 0
                try:
                    return int(raw[0] or 0)
                except Exception:
                    return 0
            pending_rows = con.execute(
                "SELECT * FROM ai_phone_pending_appointments "
                f"WHERE {pending_where} "
                "ORDER BY CASE status WHEN 'pending' THEN 0 ELSE 1 END, "
                "created_at DESC LIMIT 80").fetchall()
            call_rows = con.execute(
                "SELECT * FROM ai_phone_calls "
                f"WHERE {call_where} "
                "ORDER BY created_at DESC LIMIT 80",
                tuple(call_params)).fetchall()
            stats = {
                "pending": _count_value(
                    "SELECT COUNT(*) AS cnt FROM ai_phone_pending_appointments "
                    "WHERE status='pending'"),
                "open": _count_value(
                    "SELECT COUNT(*) AS cnt FROM ai_phone_calls "
                    "WHERE COALESCE(staff_status, 'open')='open'"),
                "callback": _count_value(
                    "SELECT COUNT(*) AS cnt FROM ai_phone_calls "
                    "WHERE COALESCE(staff_status, 'open')='callback'"),
                "emergency": _count_value(
                    "SELECT COUNT(*) AS cnt FROM ai_phone_calls "
                    "WHERE status LIKE '%emergency%'"),
            }
    except Exception as ex:
        pending_rows, call_rows = [], []
