def _ensure_command_center_schema(con=None):
    def _run(open_con):
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS ai_command_runs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                token TEXT UNIQUE NOT NULL,
                user_message TEXT NOT NULL,
                action_key TEXT NOT NULL,
                action_label TEXT,
                action_args_json TEXT,
                risk_level TEXT DEFAULT 'safe',
                status TEXT DEFAULT 'draft',
                result_text TEXT,
                created_by TEXT,
                approved_by TEXT,
                created_at TEXT NOT NULL,
                executed_at TEXT
            )
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_ai_command_runs_created
            ON ai_command_runs(created_at DESC)
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_ai_command_runs_status
            ON ai_command_runs(status, created_at DESC)
        """)
    if con is not None:
        _run(con)
        return
    with db_conn() as open_con:
        _run(open_con)
        open_con.commit()


def _command_center_new_token():
    return "CMD-" + datetime.now().strftime("%m%d%H%M%S") + "-" + uuid.uuid4().hex[:6]


def _command_center_json(data):
    import json as _json
    try:
        return _json.dumps(data or {}, ensure_ascii=False)
    except Exception:
        return "{}"


def _command_center_load_json(text):
    import json as _json
    try:
        return _json.loads(text or "{}")
    except Exception:
        return {}


def _command_center_safe_host(value):
    host = str(value or "").strip()
    if not host or len(host) > 120:
        return ""
    if not re.match(r"^[A-Za-z0-9_.:-]+$", host):
        return ""
    return host


def _command_center_parse_host(text):
    text = str(text or "")
    patterns = (
        r"\b((?:\d{1,3}\.){3}\d{1,3})\b",
        r"\b(localhost)\b",
        r"\b([A-Za-z0-9][A-Za-z0-9.-]{1,100}\.[A-Za-z]{2,12})\b",
    )
    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            return _command_center_safe_host(match.group(1))
    return ""


def _command_center_parse_port(text, default_port=None):
    folded = _fold_search_text(text)
    match = re.search(r"\bport\s*(\d{2,5})\b", folded)
    if not match:
        match = re.search(r"\b(\d{4,5})\s*(?:port|portunu|portu)\b", folded)
    if not match:
        for common in ("5052", "5051", "5000", "11434", "8042"):
            if common in folded:
                return int(common)
    if match:
        try:
            port = int(match.group(1))
            if 1 <= port <= 65535:
                return port
        except Exception:
            pass
    return default_port


def _command_center_date_from_text(text):
    parsed = _ai_phone_parse_date(text)
    if parsed:
        return parsed
    return datetime.now().strftime("%Y-%m-%d")


