def _command_center_save(message, action, status="draft", result_text=""):
    _ensure_command_center_schema()
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    token = _command_center_new_token()
    with db_conn() as con:
        cur = con.execute(
            "INSERT INTO ai_command_runs("
            "token, user_message, action_key, action_label, action_args_json, "
            "risk_level, status, result_text, created_by, created_at"
            ") VALUES(?,?,?,?,?,?,?,?,?,?)",
            (token, message or "", action.get("key"), action.get("label"),
             _command_center_json(action.get("args")),
             action.get("risk", "safe"), status, result_text or "",
             session.get("user", "api"), now))
        con.commit()
        run_id = cur.lastrowid
    return run_id, token


def _command_center_update(run_id, status, result_text="", approved_by=None):
    _ensure_command_center_schema()
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    with db_conn() as con:
        con.execute(
            "UPDATE ai_command_runs SET status=?, result_text=?, "
            "approved_by=COALESCE(?, approved_by), executed_at=? WHERE id=?",
            (status, result_text or "", approved_by, now, int(run_id)))
        con.commit()


def _command_center_get(run_id):
    _ensure_command_center_schema()
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        return con.execute(
            "SELECT * FROM ai_command_runs WHERE id=?",
            (int(run_id),)).fetchone()


def _command_center_appointments_result(args):
    _init_appointments_table()
    appt_date = str((args or {}).get("date") or datetime.now().strftime("%Y-%m-%d"))
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        rows = con.execute(
            "SELECT a.*, p.display_name FROM appointments a "
            "LEFT JOIN patients p ON p.folder_key=a.patient_key "
            "WHERE a.appointment_date=? AND a.status != 'cancelled' "
            "ORDER BY a.appointment_time LIMIT 40",
            (appt_date,)).fetchall()
    if not rows:
        return True, f"{appt_date} icin randevu yok."
    lines = [f"{appt_date} randevulari:"]
    for row in rows:
        name = row.get("display_name") or row.get("patient_key") or "Hasta"
        purpose = row.get("purpose") or "-"
        status = row.get("status") or "planned"
        lines.append(
            f"- {row.get('appointment_time')}: {name} / {purpose} / {status}")
    return True, "\n".join(lines)


def _command_center_system_status_result(args):
    payload = _yk_system_status_payload(deep=bool((args or {}).get("deep")))
    checks = payload.get("checks") or []
    lines = [
        f"Sistem: {'OK' if payload.get('ok') else 'KONTROL'}",
        f"Surum: {payload.get('app_version')}",
    ]
    for check in checks:
        lines.append(
            f"- {check.get('label')}: {'OK' if check.get('ok') else 'KONTROL'}"
            f" / {check.get('detail') or '-'}")
    return True, "\n".join(lines)


def _command_center_ollama_result():
    status = _ollama_status(force=True)
    model = _select_ollama_model(task="general")
    phone_model = _select_ollama_model(task="phone")
    clinical_model = _select_ollama_model(task="clinical")
    models = status.get("models") or []
    lines = [
        f"Ollama: {'ONLINE' if status.get('online') else 'OFFLINE'}",
        f"URL: {status.get('url') or _AI_CONFIG.get('url', '')}",
        f"Model sayisi: {len(models)}",
        f"Genel model: {model or '-'}",
        f"Telefon modeli: {phone_model or '-'}",
        f"Klinik model: {clinical_model or '-'}",
    ]
    if models:
        lines.append("Yuklu modeller: " + ", ".join(str(m) for m in models[:12]))
    if status.get("hint"):
        lines.append("Not: " + str(status.get("hint")))
    return True, "\n".join(lines)


def _command_center_backup_result():
    backup_dir = _get_backup_dir()
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    target = backup_dir / f"komut_merkezi_yedek_{timestamp}.sqlite3"
    result = backup_database(target)
    size_mb = float(result.get("size_bytes") or target.stat().st_size) / 1048576
    return True, (
        f"Yedek alindi: {target}\n"
        f"Boyut: {size_mb:.2f} MB\n"
        f"Hasta sayisi: {result.get('patient_count', '-')}")


def _command_center_open_folder_result(args):
    folder_key = str((args or {}).get("folder") or "project")
    if folder_key == "backup":
        path = _get_backup_dir()
    elif folder_key == "source":
        path = Path(__file__).resolve().parent
    else:
        path = Path(__file__).resolve().parent.parent
    path = path.resolve()
    if os.name == "nt":
        try:
            os.startfile(str(path))  # noqa: S606 - whitelisted local folder only
            return True, f"Klasor acildi: {path}"
        except Exception as ex:
            return False, f"Klasor acilamadi: {path}\nHata: {ex}"
    return True, f"Klasor yolu: {path}"


def _command_center_ping_result(args):
    import subprocess as _subprocess
    host = _command_center_safe_host((args or {}).get("host")) or "127.0.0.1"
    cmd = ["ping", "-n", "2", host] if os.name == "nt" else ["ping", "-c", "2", host]
    try:
        proc = _subprocess.run(
            cmd, capture_output=True, text=True, timeout=10,
            creationflags=(getattr(_subprocess, "CREATE_NO_WINDOW", 0)
                           if os.name == "nt" else 0))
        out = ((proc.stdout or "") + "\n" + (proc.stderr or "")).strip()
        lines = "\n".join(out.splitlines()[-8:])
        return proc.returncode == 0, f"Komut: {' '.join(cmd)}\n{lines}"
    except Exception as ex:
        return False, f"Ping calisamadi: {ex}"


def _command_center_port_result(args):
    import socket as _socket
    host = _command_center_safe_host((args or {}).get("host")) or "127.0.0.1"
    try:
        port = int((args or {}).get("port") or 5052)
    except Exception:
        port = 5052
    if not (1 <= port <= 65535):
        return False, "Port araligi gecersiz."
    try:
        with _socket.create_connection((host, port), timeout=2):
            return True, f"{host}:{port} acik gorunuyor."
    except Exception as ex:
        return False, f"{host}:{port} kapali veya erisilemiyor: {ex}"


def _command_center_execute(action):
    key = action.get("key")
    args = action.get("args") or {}
    if action.get("doctor_only") and session.get("role") != "doktor":
        return False, "Bu komut sadece doktor yetkisiyle calisir."
    if key == "navigate":
        route = str((args or {}).get("route") or "").strip()
        label = str((args or {}).get("label") or action.get("label") or "Sayfa").strip()
        if route and _smart_dialog_is_allowed_route(route):
            return True, f"{label} hazir: {route}"
        return False, "Gecersiz sayfa yolu."
    if key == "safe_command_list":
        return True, _smart_dialog_safe_command_catalog_text()
    if key == "list_appointments":
        return _command_center_appointments_result(args)
    if key == "system_status":
        return _command_center_system_status_result(args)
    if key == "ollama_status":
        return _command_center_ollama_result()
    if key == "set_ollama_auto":
        _db_set_setting("sysparam_ollama_model_mode", "auto")
        _refresh_ai_config()
        return True, "Ollama model secimi otomatik gorev moduna alindi."
    if key == "voice_prescription_toggle":
        _voice_rx_set_enabled(bool(args.get("enabled")))
        return True, (
            "Sesli recete dikte modu acildi."
            if args.get("enabled") else
            "Sesli recete dikte modu kapatildi.")
    if key == "patient_tool":
        return _command_center_patient_tool_result(args)
    if key == "open_patient_folder":
        return _open_patient_folder_result(args)
    if key == "patient_pdf_print":
        return _command_center_pdf_print_result(args)
    if key == "append_patient_note":
        return _command_center_append_note_result(args)
    if key == "workflow_draft":
        return _command_center_workflow_result(args)
    if key == "daily_summary":
        summary = _daily_clinic_summary((args or {}).get("date"))
        return True, "\n".join(summary.get("lines") or [])
    if key == "backup_now":
        return _command_center_backup_result()
    if key == "open_folder":
        return _command_center_open_folder_result(args)
    if key == "ping_host":
        return _command_center_ping_result(args)
    if key == "check_port":
        return _command_center_port_result(args)
    if key == "server_restart_plan":
        return True, (
            "Guvenli yeniden baslatma plani:\n"
            "1. Once /api/terminal/ping ile canlilik kontrol edilir.\n"
            "2. Calisan kullanicilar varsa islem ertelenir.\n"
            "3. Windows launcher uzerinden server yeniden baslatilir.\n"
            "Bu web sureci kendini zorla kapatmaz.")
    if key == "system_command_request":
        return True, (
            "Sistem komutunu anladim ve not ettim. Klinik/YazKlinik komutlarini "
            "dogrudan uygulayabilirim; ham PowerShell/CMD veya geri donussuz "
            "Windows islemlerinde otomatik calistirma yerine ayrica acik onay "
            "ve manuel terminal akisi kullanilir.")
    return False, action.get("summary") or "Komut calistirilamadi."


def _command_center_run_message(message, force_confirmed=False):
    action = _command_center_parse(message)
    def _with_route_if_present(action_obj, result_text):
        if not isinstance(action_obj, dict):
            return action_obj
        direct_route = str(
            action_obj.get("route")
            or (action_obj.get("args") or {}).get("route")
            or "").strip()
        if direct_route:
            try:
                if _smart_dialog_is_allowed_route(direct_route):
                    enriched = dict(action_obj)
                    enriched["route"] = direct_route
                    if not enriched.get("label"):
                        enriched["label"] = (
                            (action_obj.get("args") or {}).get("label")
                            or enriched.get("summary")
                            or "Sayfayi ac")
                    return enriched
            except Exception:
                pass
        text = str(result_text or "")
        match = re.search(r"(/[A-Za-z0-9_./?=&%#-]+)", text)
        if not match:
            return action_obj
        route = match.group(1).rstrip(".,;)")
        try:
            if not _smart_dialog_is_allowed_route(route):
                return action_obj
        except Exception:
            return action_obj
        enriched = dict(action_obj)
        enriched["route"] = route
        if not enriched.get("label"):
            enriched["label"] = enriched.get("summary") or "Sayfayi ac"
        return enriched

    if action.get("doctor_only") and session.get("role") != "doktor":
        run_id, token = _command_center_save(
            message, action, status="denied",
            result_text="Bu komut sadece doktor yetkisiyle calisir.")
        return {
            "ok": False, "run_id": run_id, "token": token,
            "action": action, "status": "denied",
            "result": "Bu komut sadece doktor yetkisiyle calisir."
        }
    if action.get("needs_confirm") and not force_confirmed:
        run_id, token = _command_center_save(message, action, status="waiting_confirm")
        return {
            "ok": True, "run_id": run_id, "token": token,
            "action": action, "status": "waiting_confirm",
            "result": action.get("summary", "Onay bekliyor.")
        }
    ok, result = _command_center_execute(action)
    action = _with_route_if_present(action, result)
    run_id, token = _command_center_save(
        message, action, status=("executed" if ok else "error"),
        result_text=result)
    try:
        _log_audit("ai_command_execute",
                   entity_type="command", entity_id=str(run_id),
                   details=f"{action.get('key')} / {action.get('risk')}")
    except Exception:
        pass
    return {
        "ok": bool(ok), "run_id": run_id, "token": token,
        "action": action, "status": "executed" if ok else "error",
        "result": result
    }


def _command_center_history(limit=30):
    _ensure_command_center_schema()
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        return con.execute(
            "SELECT * FROM ai_command_runs ORDER BY created_at DESC LIMIT ?",
            (int(limit),)).fetchall()


