def _ensure_smart_dialog_schema(con=None):
    def _run(open_con):
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS ai_dialog_turns (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                dialog_id TEXT NOT NULL,
                role TEXT NOT NULL,
                text TEXT NOT NULL,
                meta_json TEXT,
                created_by TEXT,
                created_at TEXT NOT NULL
            )
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_ai_dialog_turns_dialog
            ON ai_dialog_turns(dialog_id, id DESC)
        """)
    if con is not None:
        _run(con)
        return
    with db_conn() as open_con:
        _run(open_con)
        open_con.commit()


def _smart_dialog_id(provided=None):
    raw = str(provided or "").strip()
    did = ""
    if raw and re.fullmatch(r"[A-Za-z0-9_-]{6,80}", raw):
        did = raw
        session["smart_dialog_id"] = did
    if not did:
        did = session.get("smart_dialog_id")
    if not did:
        did = "DIALOG-" + uuid.uuid4().hex[:12]
        session["smart_dialog_id"] = did
    return did


def _smart_dialog_save(role, text, meta=None, dialog_id=None):
    _ensure_smart_dialog_schema()
    dialog_id = dialog_id or _smart_dialog_id()
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    with db_conn() as con:
        con.execute(
            "INSERT INTO ai_dialog_turns(dialog_id, role, text, meta_json, "
            "created_by, created_at) VALUES(?,?,?,?,?,?)",
            (dialog_id, str(role or "assistant"), str(text or ""),
             _command_center_json(meta or {}), session.get("user", "web"), now))
        con.commit()


def _smart_dialog_history(dialog_id=None, limit=12):
    _ensure_smart_dialog_schema()
    dialog_id = dialog_id or _smart_dialog_id()
    try:
        limit = max(1, min(int(limit), 40))
    except Exception:
        limit = 12
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        rows = con.execute(
            "SELECT role, text, meta_json, created_at FROM ai_dialog_turns "
            "WHERE dialog_id=? ORDER BY id DESC LIMIT ?",
            (dialog_id, limit)).fetchall()
    return list(reversed(rows))


def _smart_dialog_client_history(raw_history, limit=10):
    if not isinstance(raw_history, list):
        return []
    items = []
    for item in raw_history[-int(limit or 10):]:
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "user").strip().lower()
        if role not in {"user", "assistant"}:
            role = "user"
        text = str(item.get("text") or "").strip()
        if not text:
            continue
        items.append({"role": role, "text": text[:900]})
    return items


def _smart_dialog_installed_models(force=False, models=None):
    if models is None:
        models = _ollama_models(force=force)
    return set(str(m).strip() for m in (models or [])
               if str(m).strip())


def _smart_dialog_resolve_model(profile_item, installed):
    wanted = str((profile_item or {}).get("model") or "").strip()
    fallbacks = list((profile_item or {}).get("fallbacks") or [])
    for model in [wanted] + fallbacks:
        if model in installed:
            return model, True
    return wanted, False


def _smart_dialog_model_profile_payload(force=False, models=None):
    installed = _smart_dialog_installed_models(force=force, models=models)
    items = []
    for item in SMART_DIALOG_MODEL_PROFILE:
        selected, present = _smart_dialog_resolve_model(item, installed)
        items.append({
            "key": item.get("key"),
            "label": item.get("label"),
            "wanted": item.get("model"),
            "selected": selected,
            "installed": bool(present),
            "setting": item.get("setting"),
            "why": item.get("why"),
            "fallbacks": item.get("fallbacks") or [],
        })
    return {
        "installed_models": sorted(installed),
        "items": items,
        "missing": [x["selected"] for x in items if not x.get("installed")],
    }


def _smart_dialog_apply_premium_profile():
    payload = _smart_dialog_model_profile_payload(force=True)
    applied = []
    missing = []
    for item in payload.get("items") or []:
        model = item.get("selected") or item.get("wanted")
        if item.get("installed") and model:
            _db_set_setting(item.get("setting"), model)
            applied.append({
                "label": item.get("label"),
                "setting": item.get("setting"),
                "model": model,
            })
        elif model:
            missing.append(model)
    _db_set_setting("sysparam_ollama_model_mode", "auto")
    _refresh_ai_config()
    return {"ok": True, "applied": applied, "missing": sorted(set(missing))}


def _smart_dialog_status_payload(deep=False):
    deep = bool(deep)
    ollama = _ollama_status(force=deep, fast=not deep)
    model_profile = _smart_dialog_model_profile_payload(
        force=deep, models=(ollama.get("models") or []))
    try:
        import importlib.util as _importlib_util
        local_image = {
            "opencv": bool(_importlib_util.find_spec("cv2")),
            "pillow": bool(_importlib_util.find_spec("PIL")),
            "numpy": bool(_importlib_util.find_spec("numpy")),
            "engine": "opencv+comfyui",
        }
    except Exception as ex:
        local_image = {
            "opencv": False,
            "pillow": False,
            "numpy": False,
            "engine": "unknown",
            "error": str(ex),
        }
    if deep:
        try:
            comfy = _comfyui_status(timeout=2, autostart=False)
        except Exception as ex:
            comfy = {"ok": False, "online": False, "error": str(ex)}
        try:
            orthanc = _orthanc_status_payload_cached(
                deep=False, ttl=30, force=True)
        except Exception as ex:
            orthanc = {"ok": False, "online": False, "error": str(ex)}
    else:
        comfy = {
            "ok": False,
            "online": False,
            "unknown": True,
            "fast": True,
            "url": _comfyui_base_url(),
            "hint": "Hizli acilis modunda ComfyUI canli yoklanmadi.",
        }
        orthanc = None
        try:
            now = time.time()
            for cached in list(_ORTHANC_STATUS_CACHE.values()):
                if now - float(cached.get("ts", 0.0)) < 240:
                    data = cached.get("data") or {}
                    if isinstance(data, dict):
                        orthanc = dict(data)
                        orthanc["fast_cached"] = True
                        break
        except Exception:
            orthanc = None
        if not orthanc:
            try:
                orthanc_url = _get_orthanc_config()[0]
            except Exception:
                orthanc_url = ""
            orthanc = {
                "ok": False,
                "online": False,
                "unknown": True,
                "fast": True,
                "url": orthanc_url,
                "services": [],
                "missing_services": [],
                "hint": "Hizli acilis modunda Orthanc canli yoklanmadi.",
            }
    suggestions = []
    if not ollama.get("online"):
        suggestions.append("Ollama servisini baslat; yerel akil motoru offline.")
    elif model_profile.get("missing"):
        suggestions.append("Eksik premium modelleri Model Kur bolumunden indir.")
    else:
        suggestions.append("Premium Ollama model seti hazir gorunuyor.")
    if orthanc.get("unknown"):
        suggestions.append("Orthanc durum kontrolu sayfayi yavaslatmamak icin istege bagli.")
    elif not orthanc.get("online"):
        suggestions.append("Orthanc kapali; DICOM/Voluson akisi icin servisi baslat.")
    elif orthanc.get("missing_services"):
        suggestions.append("Orthanc eklenti listesini kontrol et: DICOMweb/Worklists/Viewer eksik olabilir.")
    else:
        suggestions.append("Orthanc baglantisi program icinde kullanilabilir.")
    if comfy.get("unknown"):
        suggestions.append("ComfyUI durum kontrolu HD Studio icinde istege bagli calisir.")
    elif not comfy.get("online"):
        suggestions.append("ComfyUI kapali; HD Studio icin gerekirse programdan baslat.")
    else:
        suggestions.append("ComfyUI HD Studio isleme motoru hazir.")
    if local_image.get("opencv"):
        suggestions.append("Anlik OpenCV/Pillow HD Live isik ve netlik motoru hazir.")
    return {
        "ok": True,
        "ollama": ollama,
        "model_profile": model_profile,
        "orthanc": orthanc,
        "comfyui": comfy,
        "local_image": local_image,
        "suggestions": suggestions,
    }


