def _smart_dialog_is_safe_command_key(key):
    return str(key or "").strip() in _SMART_DIALOG_SAFE_COMMAND_KEYS


def _smart_dialog_is_allowed_patient_route(path):
    path = str(path or "").strip()
    if not path.startswith("/hasta/"):
        return False
    lowered = path.lower()
    if "%2f" in lowered or "%5c" in lowered or "\\" in path:
        return False
    parts = [p for p in path.split("/") if p]
    if len(parts) < 2 or parts[0] != "hasta":
        return False
    patient_key = parts[1]
    if (not patient_key or len(patient_key) > 220
            or not re.match(r"^[A-Za-z0-9._~%-]+$", patient_key)):
        return False
    suffix = "/".join(parts[2:])
    if not suffix:
        return True
    return bool(re.match(r"^[A-Za-z0-9._~%/?=&#+-]{0,260}$", suffix))


def _smart_dialog_is_allowed_route(route):
    route = str(route or "").strip()
    if not route or not route.startswith("/") or route.startswith("//"):
        return False
    if any(ch in route for ch in ("\n", "\r", "\t")):
        return False
    parsed = urlsplit(route)
    if parsed.scheme or parsed.netloc:
        return False
    path = str(parsed.path or route).strip() or "/"
    if ".." in path:
        return False
    if path == "/yk-print-media" and parsed.query:
        query_text = unquote(str(parsed.query or "")).lower()
        if "://" in query_text or "\\" in query_text or "\0" in query_text:
            return False
    return True


def _smart_dialog_safe_folder_roots():
    roots = [
        Path(__file__).resolve().parent,
        Path(__file__).resolve().parent.parent,
    ]
    try:
        roots.append(_get_backup_dir())
    except Exception:
        pass
    try:
        home = Path.home()
        roots.extend([
            home / "Desktop",
            home / "OneDrive" / "Desktop",
            home / "Documents",
        ])
    except Exception:
        pass
    resolved = []
    seen = set()
    for root in roots:
        try:
            r = Path(root).expanduser().resolve()
        except Exception:
            continue
        key = str(r).lower()
        if key not in seen:
            seen.add(key)
            resolved.append(r)
    return resolved


def _smart_dialog_is_safe_folder_path(path):
    raw = str(path or "").strip().strip('"').strip("'")
    if not raw or any(ch in raw for ch in ("\n", "\r", "\0")):
        return False
    try:
        target = Path(raw).expanduser()
        if not target.is_absolute():
            return False
        resolved = target.resolve()
    except Exception:
        return False
    return resolved.exists() and resolved.is_dir()


def _smart_dialog_is_safe_url(url):
    url = str(url or "").strip()
    if not url or any(ch in url for ch in ("\n", "\r", "\t")):
        return False
    parsed = urlsplit(url)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return False
    if parsed.username or parsed.password:
        return False
    host = (parsed.hostname or "").lower()
    if not host:
        return False
    return True


def _smart_dialog_normalize_action(action):
    if not isinstance(action, dict):
        return None
    normalized = {}
    raw_key = str(
        action.get("command_key")
        or action.get("key")
        or action.get("safe_command")
        or ""
    ).strip()
    if _smart_dialog_is_safe_command_key(raw_key):
        normalized["command_key"] = raw_key
        label = str(action.get("label") or "").strip()
        if label:
            normalized["label"] = label[:80]

    route = str(action.get("route") or "").strip()
    if route and _smart_dialog_is_allowed_route(route):
        normalized["route"] = route
        if "command_key" not in normalized:
            normalized["command_key"] = "navigate"
        label = str(action.get("label") or "").strip()
        if label:
            normalized["label"] = label[:80]

    command = str(action.get("command") or "").strip().lower()
    if command in _SMART_DIALOG_ALLOWED_COMMANDS:
        normalized["command"] = command
        if command == "open_app":
            app = str(action.get("app") or "").strip().lower().replace(" ", "_")
            if app and app in _SMART_DIALOG_WINDOWS_APP_WHITELIST:
                normalized["app"] = app
                normalized["command_key"] = "open_app"
            else:
                normalized.pop("command", None)
        elif command == "open_folder":
            path = str(action.get("path") or "").strip().strip('"').strip("'")
            if path and _smart_dialog_is_safe_folder_path(path):
                normalized["path"] = path
                normalized["command_key"] = "open_folder"
            else:
                normalized.pop("command", None)
        elif command == "open_url":
            url = str(action.get("url") or "").strip()
            if _smart_dialog_is_safe_url(url):
                normalized["url"] = url
                normalized["command_key"] = "open_url"
            else:
                normalized.pop("command", None)
        elif command == "list_apps":
            normalized["command_key"] = "list_apps"

    if normalized and set(normalized.keys()).issubset({"command_key", "label"}):
        if normalized.get("command_key") in {
                "open_app", "open_folder", "open_url", "list_apps"}:
            return None

    return normalized or None


def _smart_dialog_extract_action_from_answer(answer_text):
    text = str(answer_text or "").strip()
    if not text:
        return "", None
    action = None
    cleaned = text
    match = re.search(r"ACTION:\s*(\{[\s\S]*?\})", text, re.IGNORECASE)
    if match:
        raw_json = match.group(1)
        cleaned = (text[:match.start()] + text[match.end():]).strip()
        try:
            parsed = json.loads(raw_json)
            action = _smart_dialog_normalize_action(parsed)
        except Exception:
            action = None
    return (cleaned or text), action


