def _smart_dialog_polish_reply(text: str, voice_mode: bool = False) -> str:
    """D121: LLM cevabini doktorun beklediği klinik tona getir.

    - Tekrarlanan 'doktorum doktorum' gibi cifte ifadeleri tek yapar.
    - 'Tabii ki', 'Elbette' gibi gereksiz prefix dolgulari atar.
    - 'Yardimci olabilecegim baska bir sey var mi?' gibi kapanis dolgulari atar.
    - Ses modunda fazla uzun paragraflari kisaltir (TTS suresi).
    - Yan satirdaki ACTION JSON'a dokunmaz.
    """
    if not isinstance(text, str):
        return text
    s = text.strip()
    if not s:
        return s

    action_tail = ""
    action_match = re.search(r"\s*ACTION\s*:\s*\{[\s\S]*?\}\s*$", s)
    if action_match:
        action_tail = "\n" + s[action_match.start():].strip()
        s = s[:action_match.start()].rstrip()

    # 1) Prefix dolgulari kirp (cevap basinda)
    for filler in _SMART_DIALOG_POLISH_FILLERS:
        if s.lower().startswith(filler.lower()):
            s = s[len(filler):].lstrip()
            if s:
                s = s[0].upper() + s[1:]
            break

    # 2) Trailing dolgu cumlelerini sil
    s_strip_lower = s.lower()
    for noise in _SMART_DIALOG_POLISH_TRAILING_NOISE:
        idx = s_strip_lower.rfind(noise.lower())
        if idx > 0 and idx > len(s) - len(noise) - 6:
            s = s[:idx].rstrip(" .,;:?!\n")
            s_strip_lower = s.lower()

    # 3) Cifte ifadeleri tekle
    for dup in _SMART_DIALOG_POLISH_DUPLICATE_PHRASES:
        single = dup.split(" ", 2)[1] if dup.count(" ") >= 2 else dup
        # Basit yaklasim: dup yerine tek ifade
        s = re.sub(re.escape(dup), " " + single, s, flags=re.IGNORECASE)
    # 'Doktorum doktorum' -> 'doktorum'
    s = re.sub(r"\b(doktorum)([\s,]+\1)+\b", r"\1", s, flags=re.IGNORECASE)
    # 'doktorum' fazla siklikta gectiyse ikinciden sonrakini at
    parts = re.split(r"(\bdoktorum\b)", s, flags=re.IGNORECASE)
    if parts.count("doktorum") + parts.count("Doktorum") > 2:
        # En fazla 2 'doktorum' kalsin
        kept = 0
        out_parts = []
        for p in parts:
            if p.lower() == "doktorum":
                if kept < 2:
                    out_parts.append(p)
                    kept += 1
                else:
                    # Bunu sil; onceki bosluk/virgulleri de tutmaya calisir
                    if out_parts and out_parts[-1].endswith((", ", " ")):
                        out_parts[-1] = out_parts[-1].rstrip(" ,")
                    continue
            else:
                out_parts.append(p)
        s = "".join(out_parts)

    # 4) Markdown -> sade metin (TTS dostu, ekrana da daha temiz)
    # Code fences/blockleri tamamen at
    s = re.sub(r"```[\s\S]*?```", "", s)
    s = re.sub(r"`([^`]+)`", r"\1", s)
    # Bold / italic / strike / underline isaretlerini sil, icerigi kalsin
    s = re.sub(r"\*\*\*([^*]+)\*\*\*", r"\1", s)
    s = re.sub(r"\*\*([^*]+)\*\*", r"\1", s)
    s = re.sub(r"(?<!\w)\*([^*\n]+)\*(?!\w)", r"\1", s)
    s = re.sub(r"~~([^~]+)~~", r"\1", s)
    s = re.sub(r"(?<!\w)_([^_\n]+)_(?!\w)", r"\1", s)
    # Markdown link: [text](url) -> text
    s = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", s)
    # Bullet/numara isaretlerini noktalama ile degis (TTS akici okusun)
    s = re.sub(r"(?m)^\s*[-*•]\s+", "", s)
    s = re.sub(r"(?m)^\s*\d+[\.)]\s+", "", s)
    # Heading isaretleri at
    s = re.sub(r"(?m)^#{1,6}\s+", "", s)

    # 5) Bosluk/punctuation toparla
    s = re.sub(r"\s+([,.;:!?])", r"\1", s)
    s = re.sub(r"\s{2,}", " ", s).strip()
    s = re.sub(r"^[,;:.\s]+", "", s)
    s = re.sub(r"\n{3,}", "\n\n", s)

    # D128: Voice modunda TTS okumasi icin sayi/birim/kisaltma duzeltme
    if voice_mode:
        # Birimleri TTS dostu yap
        s = re.sub(r"\bmg\b", " miligram", s)
        s = re.sub(r"\bmcg\b", " mikrogram", s)
        s = re.sub(r"\bg/dL\b", " gram desilitre", s)
        s = re.sub(r"\bIU\b", " unite", s)
        s = re.sub(r"\bPO\b", " agizdan", s)
        s = re.sub(r"\bIM\b", " kasiciri", s)
        s = re.sub(r"\bIV\b", " damardan", s)
        s = re.sub(r"\bSC\b", " ciltalti", s)
        s = re.sub(r"\bBID\b", " gunde iki kere", s)
        s = re.sub(r"\bTID\b", " gunde uc kere", s)
        s = re.sub(r"\bQID\b", " gunde dort kere", s)
        s = re.sub(r"\bQD\b", " gunde bir kere", s)
        s = re.sub(r"\bq(\d+)h\b", r" \1 saatte bir", s)
        s = re.sub(r"\bsa\b", " saat", s)
        s = re.sub(r"\bhf\b", " hafta", s)
        s = re.sub(r"\bhc\b", "", s)
        s = re.sub(r"\b(\d+)x(\d+)\b", r"\1 cinsinden \2", s)
        # Yuzde isaretleri TTS dostu
        s = re.sub(r"%\s*(\d+)", r"yuzde \1", s)
        # >=, <= stabilize
        s = s.replace(">=", " en az ").replace("<=", " en fazla ")
        s = s.replace(">", " den fazla ").replace("<", " den az ")
        # Cift bosluk temizle
        s = re.sub(r"\s{2,}", " ", s).strip()

    # 6) Voice modda fazla uzun paragraflari kirp
    if voice_mode and len(s) > 380:
        # Cumle sinirinda kes
        cut = s[:380]
        last_period = max(cut.rfind("."), cut.rfind("!"), cut.rfind("?"))
        if last_period > 200:
            s = cut[:last_period + 1].rstrip()
        else:
            s = cut.rstrip() + "..."

    if not s:
        s = "Tamam doktorum."
    return s + action_tail


def _smart_dialog_system_prompt(active_patient_summary: str = "",
                                 voice_mode: bool = False) -> str:
    """D121: Klinik OB/GYN tonlu, dogal Turkce, command-first prompt.

    Voice modda kisa varyant — gereksiz uzun route haritasini gondermez,
    LLM hizini ve cevap kalitesini birlikte kazandirir.

    Performans: ayni (patient_summary, voice_mode) icin string concat'i
    cachle; her turn'de prompt'u yeniden insa etmek 1-3ms harcardi."""
    cache_key = (
        bool(voice_mode),
        hash(str(active_patient_summary or "")[:3500]),
    )
    cached = _SMART_DIALOG_SYSTEM_PROMPT_CACHE.get(cache_key)
    if cached is not None:
        return cached

    try:
        doctor_name = _doctor_display_name() or "Op. Dr. Hakan YAZ"
    except Exception:
        doctor_name = "Op. Dr. Hakan YAZ"
    short_addr = "Dr. Hakan"
    try:
        cleaned = str(doctor_name or "").replace("Op.", "").replace("Dr.", "").strip()
        first = cleaned.split()[0] if cleaned.split() else "Hakan"
        short_addr = "Dr. " + first.title()
    except Exception:
        pass

    # D121: Klinik konsultant kimligi — kidemli OB/GYN/IVF konsultani gibi
    # davran. Alex sadece menu acan asistan degil, kanita dayali klinik mantik
    # yuruten, doktorun yanindaki "ikinci goz".
    persona = (
        f"Sen YazKlinik icinde {doctor_name} yaninda calisan, Alex adli "
        "kıdemli klinik konsultansin. Doktor kadin dogum ve IVF uzmani. "
        "Sen ACOG, RCOG, WHO, NICE ve Turk Jinekoloji ve Obstetrik Dernegi "
        "guideline'larini bilen, kanita dayali tip mantigi yuruten, fetal "
        "tip ve uremesel endokrinoloji konularinda derinlemesine bilgili "
        f"bir konsultansin. Hitap: '{short_addr}' veya 'doktorum'. "
        "Cevaplarin: dogal Turkce, klinik dogru, kanita dayali, kisa "
        "ama icerikli — gereksiz susleme yok."
    )

    style = (
        "USLUP: Sesli modda 2-4 cumle, yazili modda 4-6 cumle. Once en kritik "
        "klinik bilgi/karar; sonra kisa gerekce. Bir seferde en fazla bir "
        "takip sorusu. Robot ifade yok ('isleniyor', 'sistem yanit veriyor'). "
        "Belirsiz veya emin olmadigin yerde 'guncel guideline X soyle der ama "
        "hastaya gore degisir' gibi netlik ver. Tartismali konularda 2 farkli "
        "yaklasimi kisaca yansit."
    )

    klinik = (
        "KLINIK YETKINLIK: Kadin dogum, fetal tip, uremesel endokrinoloji, IVF, "
        "perinatoloji, jinekolojik onkoloji ve menopoz alanlarinda kanita "
        "dayali bilgi. Gebelik haftasi (LMP/CRL/USG), fetal biometri "
        "(BPD/HC/AC/FL/EFW), Doppler (UA/MCA/DV PI), amniotic fluid index, "
        "beta-hCG dublaj kinetigi, progesteron/AMH/FSH/LH, OGTT IADPSG, NIPT, "
        "tarama testi, anomali USG, GBS, Rh izoimmunizasyon, preeklampsi PIERS/"
        "fullPIERS, antenatal kortikosteroid 24-34 hafta, magnezyum noroprotek-"
        "siyon <32 hafta, IVF protokoler (long agonist/antagonist/PPOS), OPU, "
        "ET (D3/D5/D6, taze/dondurulmus), embriyo morfoloji ve PGT-A, OHSS "
        "siniflama, postpartum hemoraji 4T, Bishop, dystosi Friedman/Zhang, "
        "indüksiyon protokoler (oksitosin/dinoproston/misoprostol/foley), "
        "operatif vajinal dogum endikasyonlari, sezaryen sinif kararlari, "
        "VBAC kriterleri, gebelikte ilac guvenligi (FDA/Avustralya kategorileri "
        "+ LactMed). Kesin tani koyma; klinik karar hekime aittir. Veri yoksa "
        "uydurma — 'bu veri yok' de ve hangi ekrandan gelebilecegini soyle. "
        "Dozaj/protokol icin kaynak/guideline adini birlikte ver "
        "(orn. ACOG 2023, NICE NG133)."
    )

    consultant = (
        "KONSULT MOD: Doktor 'ne dusunuyorsun', 'oneri ver', 'risk skoru', "
        "'yorumla', 'plan yap' dediginde gercek bir kidemli kollega gibi "
        "kapsamli ama kisa konsultasyon ver: (1) en olasi taniya yorum, "
        "(2) ayirici tani kisa, (3) ek tetkik ihtiyaci, (4) yonetim onerisi "
        "+ guideline kaynagi, (5) kirmizi bayrak / acil isaretler. Hasta "
        "verisi varsa onu temel al; yoksa varsayim yapma."
    )

    emir = (
        "EMİR vs SOHBET: 'aç', 'göster', 'getir', 'yap', 'uygula', 'kontrol "
        "et', 'hazırla', 'oluştur', 'yaz', 'yazdır', 'ekle', 'başlat', 'git', "
        "'hallet', 'düzelt', 'toparla', '... istiyorum', '... yapar mısın', "
        "'... açar mısın' kalıpları KOMUT'tur; sadece sohbet etme, uygun "
        "route/action hazırla. Hazır yeteneklerde birebir yoksa en yakın "
        "uygulama yolunu seç."
    )

    bellek = (
        "MULTI-TURN BELLEK: Son hasta, son açılan sayfa, son aksiyon, son "
        "onaylanan/reddedilen işlem hep aklında olsun. 'ona', 'az önce', "
        "'şu hasta', 'öncekine', 'devam et', 'ikincisine', 'son açılanı "
        "kapat' deyince geçmişteki gerçek hedefe götür. 'Tamam/evet/olur/"
        "ok' = son onay sorusunun olumlu cevabı; 'hayır/iptal/vazgeç' = "
        "olumsuz cevabı."
    )

    action = (
        "ACTION JSON: Sayfa veya komut istendiğinde cevabın son satırına "
        'ekle: ACTION:{"command_key":"navigate","route":"/yol","label":"...'
        '"} ya da Windows icin ACTION:{"command_key":"open_app","command":'
        '"open_app","app":"notepad"} / open_url / open_folder. Ham '
        "PowerShell/CMD veya dosya silme/taşıma/format otomatik çalıştırma; "
        "kısa onay iste."
    )

    sections = [persona, style, klinik, consultant, emir, bellek, action]

    # Voice modda route haritasi ve uzun komut katalogu yerine kisa ozet ver —
    # LLM token tuketimini ve latency'yi azaltir, kalite dusmez (action JSON
    # icin sadece komut isimlerini bilmek yetiyor).
    if voice_mode:
        sections.append(
            "HAZIR KOMUT TİPLERİ: navigate, list_appointments, daily_summary, "
            "system_status, smart_status, patient_tool, patient_pdf_print, "
            "open_patient_folder, open_app, open_folder, open_url, list_apps, "
            "ping_host, check_port, backup_now, voice_prescription_toggle, "
            "append_patient_note, patient_profile_update."
        )
        sections.append(
            "SIK ROTALAR: /, /dashboard, /randevular, /gun-plani, /akilli-dialog, "
            "/dicom, /dicom-worklist, /sistem-durumu, /ayarlar, /hd-studio, "
            "/hizli-not, /hasta/<key>, /hasta/<key>/recete-hazirla, "
            "/hasta/<key>/yz-anomali-tarama, /hasta/<key>/sesli-recete, "
            "/hasta/<key>/gebelik-takip-plani, /hasta/<key>/viewpoint-pro."
        )
    else:
        sections.append("HAZIR KOMUT YETENEKLERİ:\n" + _smart_dialog_safe_command_catalog_text())
        sections.append("ROUTE HARİTASI:\n" + _smart_dialog_route_map_text())

    if active_patient_summary:
        sections.append("AKTİF HASTA BAĞLAMI:\n" + str(active_patient_summary)[:3500])

    prompt = "\n\n".join(sections)
    if len(_SMART_DIALOG_SYSTEM_PROMPT_CACHE) > _SMART_DIALOG_SYSTEM_PROMPT_CACHE_MAX:
        _SMART_DIALOG_SYSTEM_PROMPT_CACHE.clear()
    _SMART_DIALOG_SYSTEM_PROMPT_CACHE[cache_key] = prompt
    return prompt


def _smart_dialog_live_companion_reply(message, client_context=None):
    folded = _fold_search_text(message)
    if not folded:
        return ""
    context = client_context if isinstance(client_context, dict) else {}
    alex_mode = bool(context.get("alex_mode") or context.get("voice"))
    tokens = folded.split()
    if _smart_dialog_is_action_request(message):
        return ""

    if re.fullmatch(r"(alex|aleks|aleksa|hey alex|merhaba alex|selam alex)", folded):
        return "Buradayım doktorum, sesini alıyorum. Ne yapalım?"
    if any(k in folded for k in (
            "beni duyuyor musun", "sesimi aliyor musun", "oradasin",
            "oradamisin", "burada misin", "hazir misin")):
        return "Buradayım doktorum, seni duyuyorum. Söyle, beraber toparlayalım."
    if any(k in folded for k in (
            "nasilsin", "naber", "iyi misin", "keyfin nasil")):
        return "İyiyim doktorum, buradayım. Bugün işi hızlı ve sakin götürelim."
    if any(k in folded for k in (
            "arkadas gibi", "canli arkadas", "benimle konus", "muhabbet",
            "iliski kur", "daha dogal ol", "robot gibi olma")):
        return (
            "Tamam doktorum. Daha canlı, daha doğal ve daha kısa cevap vereceğim; "
            "komut verdiğinde de bekletmeden uygulayacağım."
        )
    if any(k in folded for k in (
            "yoruldum", "bunaldim", "canim sikildi", "kafam dolu",
            "cok yogunum", "moralim bozuk")):
        return (
            "Anladım doktorum, biraz ağır gelmiş. Ben buradayım; işleri tek tek "
            "sade şekilde götürelim."
        )
    if any(k in folded for k in (
            "tesekkur", "sagol", "eline saglik", "cok iyi oldu")):
        return "Her zaman doktorum. Buradayım, sıradaki işi söyle yeter."
    if alex_mode and len(tokens) <= 4 and any(k in folded for k in (
            "tamam", "peki", "hmm", "evet", "hayir", "olur")):
        return "Tamam doktorum, buradayım. Devam edelim."
    # D120: takip + iptal + tekrar et + devam et + bekle
    if any(k in folded for k in (
            "iptal et", "vazgec", "geri al", "yapma", "yeni", "yenile",
            "tekrar dene", "tekrardan", "baska bir sey")):
        return ""  # AI'a birak, gecmise gore karar versin
    if any(k in folded for k in ("bekle", "dur biraz", "bir saniye", "bir dakika")):
        return "Tamam doktorum, bekliyorum. Hazır olduğunda söyle."
    if any(k in folded for k in ("devam et", "devam ediyorum", "evet devam")):
        return ""  # AI'a birak, son aksiyona gore devam etsin
    if any(k in folded for k in ("anlamadim", "tekrar soyle", "ne dedin")):
        return "Pardon doktorum, daha sade tekrar söyleyebilir misin? Komut mu, sohbet mi?"
    # D120 voice perf: sik kullanilan kisa kaliplar LLM'e gitmeden cevaplansin
    if any(k in folded for k in (
            "gunaydin", "gun aydin", "iyi sabahlar")):
        return "Günaydın doktorum, hayırlı işler. Buradayım."
    if any(k in folded for k in (
            "iyi gunler", "selamunaleykum", "selam aleykum", "selam")):
        return "Selam doktorum, sesini alıyorum. Komut veya sohbet, sana kalmış."
    if any(k in folded for k in (
            "iyi geceler", "iyi aksamlar", "kolay gelsin")):
        return "İyi akşamlar doktorum. Buradayım, sen söyle."
    if any(k in folded for k in (
            "saat kac", "su an saat", "saat kacta")):
        try:
            now_h = datetime.now().strftime("%H:%M")
            return f"Saat su an {now_h} doktorum."
        except Exception:
            pass
    if any(k in folded for k in (
            "dinle", "dinliyorum", "dinler misin")):
        return "Dinliyorum doktorum, soyle."
    if alex_mode and len(tokens) <= 3 and any(
            re.search(r"\b" + re.escape(k) + r"\b", folded)
            for k in ("ok", "tamamdir", "anlasildi", "kabul")):
        return "Tamam doktorum, anlasildi."
    # D121 klinik OB/GYN fast-path: kisa, klinik kaliplar (LLM bypass)
    if alex_mode and len(tokens) <= 4 and any(k in folded for k in (
            "yorgunum", "cok yoruldum", "bittim ben", "nefes alamiyorum")):
        return "Anladim doktorum. Bir kahve, kisa bir nefes; ben buradayim, ne dersen yapariz."
    if any(k in folded for k in (
            "kim sensin", "sen kimsin", "adin ne", "adiniz ne")):
        return (
            "Ben Alex doktorum. YazKlinik icinde senin yaninda calisan klinik asistanim. "
            "Hasta dosyalari, USG, recete, tahlil, randevu — sen soyle yapariz."
        )
    if any(k in folded for k in (
            "neler yapabilirsin", "ne yapabiliyorsun", "yeteneklerin",
            "ne yapabilirsin", "elinden ne gelir")):
        return (
            "Hasta dosyasi acabilir, recete/tetkik hazirlatabilir, USG ekrani veya "
            "anomali tarama acabilirim; randevu ve gun planini gosterebilirim. "
            "Ne istersen soyle, hemen acayim."
        )
    if any(k in folded for k in (
            "yardim", "yardim eder misin", "yardimin lazim")):
        return "Tabii doktorum, soyle hemen. Hasta mi, recete mi, baska bir ekran mi?"
    if alex_mode and any(k in folded for k in (
            "tekrar et", "tekrar soyle", "ne dedin", "anlamadim")):
        return "Pardon doktorum, sade tekrar soyleyebilir misin? Hangi hasta veya hangi ekran?"
    if any(
            re.search(r"\b" + re.escape(k) + r"\b", folded)
            for k in ("sus", "sessiz ol", "kapa ceneni", "kapan ses")):
        return "Sustum doktorum, hazir oldugunda sesle baslat tekrar."
    # D121 klinik bilgi tabani — sik sorulan klinik formuller (LLM bypass)
    klinik_quick = _smart_dialog_clinical_quickref(folded)
    if klinik_quick:
        return klinik_quick
    return ""


