def _smart_dialog_clinical_quickref(folded_query: str) -> str:
    """D121: Sik sorulan klinik formuller icin LLM'siz instant cevap.

    Pattern eslesmede tam-kelime/cok-kelime sinirlari korunur — boylece
    'aspirin preeklampsi' sorgusu hem aspirin hem preeklampsi key'lerine
    aday olur ama once daha SPESIFIK (uzun) eslesme kazanir."""
    if not folded_query:
        return ""

    # D128 Voice perf: Türkiye marka sorusu varsa direkt _TR_BRAND_DB lookup
    # ('Mirena Türkiye markası', 'doksisiklin marka adı', 'piyasa adi seftriakson')
    brand_triggers = (
        "marka", "markasi", "markanin", "piyasa", "ticari",
        "brand", "ticari ad", "ticari isim",
    )
    if any(t in folded_query for t in brand_triggers):
        # Sorgudan ilac adini cikar (en uzun token > 4 char)
        try:
            tokens = [t for t in folded_query.split() if len(t) >= 4 and t not in brand_triggers
                       and t not in ("ilac", "ilaci", "ilacin", "turkiyede",
                                      "turkiye", "adi", "ismi", "varmi", "var",
                                      "nedir", "ne", "olan", "olarak")]
            for tok in tokens:
                if tok in _TR_BRAND_DB:
                    brands = _TR_BRAND_DB[tok]
                    return (f"{tok.title()} Türkiye markalari: "
                            f"{', '.join(brands)}. Detay icin /ilac-piyasa.")
                # Substring kontrolu
                for key, brands in _TR_BRAND_DB.items():
                    if key in tok or tok in key:
                        return (f"{key.title()} Türkiye markalari: "
                                f"{', '.join(brands)}. Detay icin /ilac-piyasa.")
        except Exception:
            pass
        # Marka adindan jenerik bul
        try:
            for key, brands in _TR_BRAND_DB.items():
                for b in brands:
                    bnorm = b.lower().split()[0] if b else ""
                    if bnorm and len(bnorm) >= 4 and bnorm in folded_query:
                        return (f"{b} = jenerik ad: {key}. "
                                f"Diger markalar: {', '.join(brands)}.")
        except Exception:
            pass

    best_idx = -1
    best_specificity = -1
    for idx, (keys, _answer) in enumerate(_CLINICAL_QUICK_PATTERNS):
        for k in keys:
            # Multi-word key: substring match yeter (zaten spesifik)
            if " " in k:
                if k in folded_query:
                    spec = len(k) * 10  # cok-kelime kazanir
                    if spec > best_specificity:
                        best_specificity = spec
                        best_idx = idx
                    break
            else:
                # Tek kelime: tam kelime sinirinda esles
                if re.search(r"\b" + re.escape(k) + r"\b", folded_query):
                    spec = len(k)
                    if spec > best_specificity:
                        best_specificity = spec
                        best_idx = idx
                    break
    if best_idx >= 0:
        return _CLINICAL_QUICK_PATTERNS[best_idx][1]
    return ""


_SMART_DIALOG_REFERENT_TRIGGERS = (
    "ona", "ona da", "ona bir", "onun", "onunki", "onunla",
    "az once", "az evvel", "az evel", "demin",
    "su hasta", "bu hasta", "su hastay", "bu hastay",
    "oncekine", "oncekinin", "onceki hasta",
    "ayni hasta", "ayni hastaya",
    "bahsettigim", "bahsettigim hasta",
    "son hasta", "son acilan",
)


def _smart_dialog_referent_hint(message: str, history, action_result) -> str:
    """D121: Mesajda referent ifade varsa (ona/az once/su hasta), gecmisteki
    son hasta veya son aksiyonu prompt'a acikca isaret eden kisa bir not don.
    LLM 'son hasta' kim oldugunu sezse de, acikca bilmesi yorum kalitesini
    artirir."""
    folded = _fold_search_text(str(message or ""))
    if not folded:
        return ""
    if not any(t in folded for t in _SMART_DIALOG_REFERENT_TRIGGERS):
        return ""
    rows = []
    last_patient_label = ""
    last_patient_route = ""
    last_action = ""
    try:
        for row in (history or [])[-12:]:
            if not isinstance(row, dict):
                continue
            text = str(row.get("text") or "")
            meta = row.get("meta") if isinstance(row.get("meta"), dict) else {}
            action = meta.get("action") if isinstance(meta, dict) else None
            if isinstance(action, dict):
                route = str(action.get("route") or "")
                label = str(action.get("label") or "")
                if route.startswith("/hasta/"):
                    parts = [p for p in route.split("/") if p]
                    if len(parts) >= 2:
                        last_patient_route = "/" + "/".join(parts[:2])
                        last_patient_label = label or last_patient_route
                if label:
                    last_action = label
            # Mesaj icinde "Ahmet Yilmaz" gibi isim arama: sadece son aksiyondan al
            rows.append(text[:200])
        # Eger action_result'tan da hasta route'u cikabiliyorsa
        if not last_patient_route and isinstance(action_result, dict):
            ar_action = action_result.get("action") if isinstance(action_result.get("action"), dict) else {}
            route = str(ar_action.get("route") or action_result.get("route") or "")
            if route.startswith("/hasta/"):
                parts = [p for p in route.split("/") if p]
                if len(parts) >= 2:
                    last_patient_route = "/" + "/".join(parts[:2])
                    last_patient_label = ar_action.get("label") or last_patient_route
    except Exception:
        return ""
    hints = []
    if last_patient_route:
        if last_patient_label and last_patient_label != last_patient_route:
            hints.append(f"Son hasta: {last_patient_label} ({last_patient_route})")
        else:
            hints.append(f"Son hasta route'u: {last_patient_route}")
    if last_action and last_action.lower() not in (last_patient_label or "").lower():
        hints.append(f"Son aksiyon: {last_action}")
    if not hints:
        return ""
    return " | ".join(hints) + " — doktor 'ona/az once/su hasta' derken bunu kastediyor olabilir."


def _smart_dialog_ai_reply(message, action_result=None, history=None,
                           selected_patient="", client_context=None):
    history = history or []
    # D120 perf: voice modda kisa cevap, daha kucuk window — STT/TTS dongusu hizlansin
    is_voice_mode = bool(
        isinstance(client_context, dict)
        and (client_context.get("alex_mode") or client_context.get("voice")))
    history_window = 12 if is_voice_mode else 16
    char_per_turn = 380 if is_voice_mode else 600
    compact_history = []
    for row in history[-history_window:]:
        compact_history.append(
            f"{row.get('role', 'user')}: {str(row.get('text') or '')[:char_per_turn]}")
    action_text = ""
    if action_result:
        action = action_result.get("action") or {}
        action_text = (
            "\n\nYazKlinik islem durumu:\n"
            f"- Islem: {action.get('label') or action.get('key') or '-'}\n"
            f"- Durum: {action_result.get('status') or '-'}\n"
            f"- Sonuc: {str(action_result.get('result') or '')[:2500]}"
        )

    # B429: Aktif hasta context'i system prompt'a inject (hasta hakkinda
    # konusulabilsin - yas, gebelik haftasi, son tahliller, son geliÅŸ)
    # D120 perf: hasta context'ini 60sn cachle, her sesli turn'de yeniden
    # hesaplama yerine tekrar kullan
    active_patient_summary = ""
    try:
        ap = _smart_dialog_resolve_patient(
            message=message, selected_patient=selected_patient) or {}
        pkey = str(ap.get("patient_key") or "").strip()
        if pkey:
            ctx_cache_key = f"alex_patient_ctx_{pkey}"
            cached_ctx = cache_get(ctx_cache_key)
            if cached_ctx is not None:
                active_patient_summary = cached_ctx
            else:
                try:
                    ctx = _patient_context_for_ai(pkey, include_labs=True, include_usg=True)
                    if ctx and isinstance(ctx, str):
                        active_patient_summary = ctx[:3500]
                except Exception:
                    active_patient_summary = (
                        f"Hasta: {ap.get('label') or pkey} (key: {pkey})"
                    )
                try:
                    cache_set(ctx_cache_key, active_patient_summary, ttl_seconds=60)
                except Exception:
                    pass
    except Exception:
        active_patient_summary = ""

    context_text = ""
    if isinstance(client_context, dict):
        page_title = str(client_context.get("page_title") or "").strip()
        current_path = str(client_context.get("current_path") or "").strip()
        if page_title or current_path:
            context_text = (
                "\n\nEkran baglami:\n"
                f"- Sayfa: {page_title or '-'}\n"
                f"- Yol: {current_path or '-'}"
            )
        if client_context.get("alex_mode") or client_context.get("voice"):
            context_text += (
                "\n\nAlex canli konusma modu: Kisa, sicak, arkadas gibi ama "
                "profesyonel cevap ver. Komut varsa isi hemen yap; sohbetse "
                "karsilik ver ve gerekirse tek bir takip sorusu sor."
            )

    # D121: Referent cozumleme — "ona", "az once", "su hasta", "oncekine"
    # dedigi an gecmisteki son hasta/aksiyonu prompt'a acikca inject et.
    try:
        referent_hint = _smart_dialog_referent_hint(message, history, action_result)
        if referent_hint:
            context_text += "\n\nREFERENT IPUCU:\n" + referent_hint
    except Exception:
        pass

    prompt = (
        "Konusma gecmisi:\n" + "\n".join(compact_history[-8:]) +
        "\n\nKullanici istegi:\n" + str(message or "") +
        action_text +
        context_text +
        "\n\nBu kullaniciya Alex olarak dogal, kisa, sicak ve is yapan bir "
        "asistan cevabi ver. "
        "Eger sayfa acma/menu gecisi/dosya acma istegi varsa metin sonuna "
        "ACTION:{...} JSON'u ekle (route haritasini kullan)."
    )
    dialog_model = _smart_dialog_pick_chat_model()
    sys_prompt = _smart_dialog_system_prompt(
        active_patient_summary, voice_mode=is_voice_mode)

    # D121: voice modda kisa+hizli, normal modda kapsamli klinik konsult.
    # Klinik konsultant kalitesi icin temperature 0.3 (daha tutarli).
    voice_max_tokens = 340 if is_voice_mode else 600
    voice_timeout = 24 if is_voice_mode else 40
    voice_temperature = 0.3

    # D300 RTX 5090: auto modda yerel Ollama/RTX once gelsin. Sadece doktor
    # ozellikle cloud_first/online/OpenAI secmisse bulut once denenir.
    duration = 0
    provider_choice = _ai_provider_value()
    prefer_cloud = (
        provider_choice in {"cloud_first", "online", "cloud"}
        or _ai_provider_is_cloud(provider_choice)
    )
    strategy = _ai_strategy_available_order(
        images=False, prefer_cloud=prefer_cloud)
    for kind, provider in strategy:
        if kind == "cloud":
            ok, answer, duration = _b301_call_cloud_ai(
                provider, prompt,
                temperature=voice_temperature,
                max_tokens=voice_max_tokens,
                timeout=voice_timeout,
                use_cache=True,
                system=sys_prompt)
            if ok and answer:
                return _smart_dialog_polish_reply(answer, is_voice_mode), f"ai:{provider}", duration
            continue
        if kind == "ollama":
            ok, answer, duration = call_ollama(
                prompt,
                model=dialog_model,
                temperature=voice_temperature,
                max_tokens=voice_max_tokens,
                timeout=voice_timeout,
                use_cache=True,
                system=sys_prompt)
            if ok and answer:
                return _smart_dialog_polish_reply(answer, is_voice_mode), "ai:ollama", duration
            continue
    # B111: Eskiden raw action_result.result fallback olarak donerdi (JSON/HTML
    # parcasi). Doktor "saÃ§ma/aptal cevap" goruyordu. Artik kibar Turkce sarmal:
    fallback_raw = str(action_result.get("result") if action_result else "").strip()
    if fallback_raw:
        snippet = fallback_raw[:180].rstrip()
        if len(fallback_raw) > 180:
            snippet += "..."
        return (
            f"Komut tamamlandi. Sonuc ozeti: {snippet}",
            "action_fallback",
            duration,
        )
    return (
        "Seni anladim ama YZ motoru su an cevap veremedi. Tekrar dene, "
        "ya da menudeki ilgili ekrandan devam edebilirim.",
        "fallback",
        duration,
    )


def _smart_dialog_pick_chat_model():
    """B111: Akilli dialog icin hizli, thinking-yapmayan modeli sec.
    Once kullanicinin yapilandirdigi sohbet modelini kontrol et; sonra
    yuklu modellerden non-thinking olanlari sirayla dene; bulamazsa None
    don (call_ollama otomatik secime duser).
    """
    try:
        installed = _ollama_status().get("models") or []
    except Exception:
        installed = []
    installed_norm = [str(m).strip().lower() for m in installed if m]
    installed_by_lower = {
        str(m).strip().lower(): str(m).strip()
        for m in installed if str(m).strip()
    }
    for setting_key in (
            "sysparam_ollama_task_dialog_model",
            "sysparam_ollama_task_phone_model",
            "sysparam_ollama_model"):
        configured = str(_ollama_setting_value(setting_key, "") or "").strip()
        if not configured:
            continue
        configured = _normalize_ollama_model_name(configured)
        if _is_auto_model_value(configured):
            continue
        configured_key = configured.lower()
        if configured_key in installed_by_lower:
            return installed_by_lower[configured_key]
    # Tercih sirasi: hizli + iyi sohbet eden non-thinking modeller
    preferred = (
        "qwen2.5:32b",
        "qwen3-coder:30b",
        "yaz:latest",
        "llama3.1:8b",
        "llama3.1:latest",
        "qwen2.5:7b",
        "qwen2.5:14b",
        "mistral:7b",
        "gpt-oss:20b",
        "mixtral:8x7b",
    )
    for cand in preferred:
        if cand in installed_norm:
            return cand
    return None


def _smart_dialog_active_patient_match():
    try:
        from yazklinik_common import get_active_patient
        active = get_active_patient() or {}
    except Exception:
        active = {}
    patient_key = str(active.get("patient_key") or "").strip()
    if not patient_key:
        return None
    match = _voice_rx_find_patient(patient_key)
    if match:
        return match
    try:
        header = _get_patient_header_data(patient_key)
        display_name = (
            str(header.get("display_name") or active.get("display_name") or patient_key).strip()
            or patient_key
        )
    except Exception:
        display_name = (
            str(active.get("display_name") or patient_key).strip() or patient_key
        )
    return {
        "patient_key": patient_key,
        "display_name": display_name,
        "protocol_no": active.get("protocol_no") or "",
    }


def _smart_dialog_patient_options(limit=260):
    limit = max(20, min(int(limit or 260), 900))
    items = []
    seen = set()
    active = _smart_dialog_active_patient_match()
    if active and active.get("patient_key"):
        key = str(active.get("patient_key") or "").strip()
        seen.add(key)
        name = str(active.get("display_name") or key).strip() or key
        proto = str(active.get("protocol_no") or "").strip()
        label = name + (f" | Protokol {proto}" if proto else "")
        items.append({"patient_key": key, "display_name": name, "label": label})
    try:
        rows = _load_patient_listing(limit=limit, include_full_path=False) or []
    except Exception:
        rows = []
    for row in rows:
        key = str((row or {}).get("patient_key") or "").strip()
        if not key or key in seen:
            continue
        seen.add(key)
        name = str((row or {}).get("display_name") or key).strip() or key
        proto = str((row or {}).get("protocol_no") or "").strip()
        label = name + (f" | Protokol {proto}" if proto else "")
        items.append({"patient_key": key, "display_name": name, "label": label})
        if len(items) >= limit:
            break
    return items


def _smart_dialog_resolve_patient(message="", selected_patient=""):
    selected = str(selected_patient or "").strip()
    match = None
    if selected:
        match = _voice_rx_find_patient(selected) or _voice_rx_find_patient_from_text(selected)
        if match:
            return match
    if not match and message:
        match = _voice_rx_find_patient_from_text(message)
        if not match:
            query = _voice_rx_extract_patient_query(message)
            if query:
                match = _voice_rx_find_patient(query)
    if not match:
        match = _smart_dialog_active_patient_match()
    return match


def _smart_dialog_parse_float(value):
    raw = str(value or "").strip().replace(",", ".")
    m = re.search(r"-?\d+(?:\.\d+)?", raw)
    if not m:
        return None
    try:
        return float(m.group(0))
    except Exception:
        return None


def _smart_dialog_extract_note_text(message):
    raw = str(message or "").strip()
    if not raw:
        return ""
    patterns = [
        r"\bhasta(?:nin|ya)?\s+not(?:larina|una|a)?\s+ekle[:\s-]*(.+)$",
        r"\bnot(?:lara|a)?\s+ekle[:\s-]*(.+)$",
        r"\bdosyaya\s+not\s+ekle[:\s-]*(.+)$",
    ]
    for pat in patterns:
        m = re.search(pat, raw, flags=re.IGNORECASE)
        if m:
            return m.group(1).strip(" \t\r\n:;,-.")
    fallback = str(_extract_patient_note_command(raw) or "").strip()
    return fallback


def _smart_dialog_extract_patient_edits(message):
    raw = str(message or "").strip()
    folded = _fold_search_text(raw)
    folded_punct = _voice_rx_fold_keep_punct(raw)
    updates = {}

    age = None
    for pat in (
            r"\byas(?:i|ini|in)?\b[^0-9]{0,16}(\d{1,3})\b",
            r"\b(\d{1,3})\s*yas(?:inda)?\b"):
        m = re.search(pat, folded)
        if not m:
            continue
        try:
            candidate = int(m.group(1))
        except Exception:
            continue
        if 2 <= candidate <= 120:
            age = candidate
            break
    if age is not None:
        updates["age"] = age

    weight = None
    for pat in (
            r"\b(?:kilo|agirlik)\b[^0-9]{0,14}(\d{2,3}(?:[.,]\d{1,2})?)\b",
            r"\b(\d{2,3}(?:[.,]\d{1,2})?)\s*(?:kg|kilo)\b"):
        m = re.search(pat, folded_punct) or re.search(pat, folded)
        if not m:
            continue
        candidate = _smart_dialog_parse_float(m.group(1))
        if candidate is not None and 20 <= candidate <= 250:
            weight = round(candidate, 1)
            break
    if weight is not None:
        updates["weight"] = weight

    height = None
    m = (re.search(r"\bboy(?:u|unu|un)?\b[^0-9]{0,14}(\d{1,3}(?:[.,]\d{1,2})?)\b", folded_punct)
         or re.search(r"\bboy(?:u|unu|un)?\b[^0-9]{0,14}(\d{1,3}(?:[.,]\d{1,2})?)\b", folded))
    if m:
        candidate = _smart_dialog_parse_float(m.group(1))
        if candidate is not None:
            if candidate < 3:
                candidate *= 100
            if 90 <= candidate <= 230:
                height = round(candidate, 1)
    if height is None:
        m = (re.search(r"\b(\d(?:[.,]\d{1,2}))\s*(?:m|metre)\b", folded_punct)
             or re.search(r"\b(\d(?:[.,]\d{1,2}))\s*(?:m|metre)\b", folded))
        if m:
            candidate = _smart_dialog_parse_float(m.group(1))
            if candidate is not None:
                candidate *= 100
                if 90 <= candidate <= 230:
                    height = round(candidate, 1)
    if height is not None:
        updates["height"] = height

    bmi = None
    m = (re.search(r"\bbmi\b[^0-9]{0,10}(\d{1,2}(?:[.,]\d{1,2})?)\b", folded_punct)
         or re.search(r"\bbmi\b[^0-9]{0,10}(\d{1,2}(?:[.,]\d{1,2})?)\b", folded))
    if m:
        candidate = _smart_dialog_parse_float(m.group(1))
        if candidate is not None and 10 <= candidate <= 80:
            bmi = round(candidate, 1)
    if bmi is not None:
        updates["bmi"] = bmi

    note_text = _smart_dialog_extract_note_text(raw)
    return {
        "intent": bool(updates or note_text),
        "updates": updates,
        "note_text": note_text[:3000],
    }


def _smart_dialog_apply_patient_edits(message, selected_patient=""):
    payload = _smart_dialog_extract_patient_edits(message)
    if not payload.get("intent"):
        return None
    updates = dict(payload.get("updates") or {})
    note_text = str(payload.get("note_text") or "").strip()
    match = _smart_dialog_resolve_patient(message=message, selected_patient=selected_patient)
    if not match or not match.get("patient_key"):
        return {
            "ok": False,
            "status": "patient_required",
            "action": {
                "key": "patient_profile_update",
                "label": "Hasta secimi gerekli",
                "risk": "safe",
            },
            "result": (
                "Hasta secilemedi. Sohbet panelindeki Hasta baglami listesinden bir hasta secin "
                "veya mesaja hasta adini/protokolunu ekleyin."
            ),
        }
    patient_key = str(match.get("patient_key") or "").strip()
    if not patient_key:
        return {
            "ok": False,
            "status": "patient_required",
            "action": {
                "key": "patient_profile_update",
                "label": "Hasta secimi gerekli",
                "risk": "safe",
            },
            "result": "Hasta secilemedi.",
        }
    patient_name = str(match.get("display_name") or patient_key).strip() or patient_key
    if not updates and not note_text:
        return {
            "ok": False,
            "status": "blocked",
            "action": {
                "key": "patient_profile_update",
                "label": "Hasta profili guncelle",
                "risk": "safe",
            },
            "result": "Guncellenecek alan bulunamadi. Ornek: 'Hastanin yasi 30 olsun'.",
        }
    try:
        demo = load_patient_demographics(patient_key) or {}
        now = datetime.now().isoformat(sep=" ", timespec="seconds")
        changes = []
        if "age" in updates:
            demo["age"] = int(updates["age"])
            demo["age_source"] = "akilli_dialog"
            demo["age_confirmed_at"] = now
            changes.append(f"Yas: {int(updates['age'])}")
            try:
                with db_conn() as con:
                    con.execute(
                        "UPDATE patient_type SET age=?, updated_at=? WHERE patient_key=?",
                        (int(updates["age"]), now, patient_key))
                    con.commit()
            except Exception:
                pass
        if "weight" in updates:
            demo["weight"] = float(updates["weight"])
            changes.append(f"Kilo: {float(updates['weight']):.1f} kg")
        if "height" in updates:
            demo["height"] = float(updates["height"])
            changes.append(f"Boy: {float(updates['height']):.1f} cm")
        if "bmi" in updates:
            demo["bmi"] = float(updates["bmi"])
            changes.append(f"BMI: {float(updates['bmi']):.1f}")
        elif ("weight" in updates or "height" in updates):
            weight = _smart_dialog_parse_float(demo.get("weight"))
            height = _smart_dialog_parse_float(demo.get("height"))
            if weight and height and height > 0:
                height_m = height / 100.0
                if height_m > 0:
                    bmi_calc = round(weight / (height_m * height_m), 1)
                    demo["bmi"] = bmi_calc
                    changes.append(f"BMI otomatik: {bmi_calc:.1f}")
        if updates:
            save_patient_demographics(patient_key, demo)
        note_saved = False
        if note_text:
            _append_patient_general_note(
                patient_key, note_text, source_label="Akilli dialog notu")
            note_saved = True
        try:
            _invalidate_patient_web_cache(patient_key=patient_key)
        except Exception:
            pass
        result_lines = [f"{patient_name} hasta dosyasi guncellendi."]
        if changes:
            result_lines.extend(f"- {item}" for item in changes)
        if note_saved:
            short_note = note_text if len(note_text) <= 220 else (note_text[:217] + "...")
            result_lines.append(f"- Not eklendi: {short_note}")
        route = f"/hasta/{quote(patient_key, safe='')}"
        result_lines.append(f"- Hasta karti: {route}")
        return {
            "ok": True,
            "status": "executed",
            "action": {
                "key": "patient_profile_update",
                "label": "Hasta profili guncelle",
                "risk": "safe",
                "args": {"patient_key": patient_key},
            },
            "patient": {
                "patient_key": patient_key,
                "display_name": patient_name,
            },
            "route": route,
            "result": "\n".join(result_lines),
        }
    except Exception as ex:
        return {
            "ok": False,
            "status": "error",
            "action": {
                "key": "patient_profile_update",
                "label": "Hasta profili guncelle",
                "risk": "safe",
            },
            "result": f"Hasta guncelleme hatasi: {ex}",
        }


def _smart_dialog_handle(message, confirmed=False, speak=True, selected_patient="",
                         dialog_id=None, client_history=None, client_context=None):
    message = str(message or "").strip()
    if not message:
        return {"ok": False, "error": "message gerekli"}
    dialog_id = _smart_dialog_id(dialog_id)
    _smart_dialog_save(
        "user", message,
        meta={"client_context": client_context or {}},
        dialog_id=dialog_id)

    action = _command_center_parse(message)
    if action.get("key") == "blocked_shell":
        answer_text = (
            action.get("summary")
            or "Bu sistem komutu otomatik calistirilmiyor; klinik/YazKlinik aksiyonu olarak yorumlayabilirim."
        )
        meta = {
            "source": "command_guard",
            "duration_ms": 0,
            "action": None,
            "status": "blocked",
        }
        _smart_dialog_save("assistant", answer_text, meta=meta, dialog_id=dialog_id)
        return {
            "ok": True,
            "dialog_id": dialog_id,
            "answer": answer_text,
            "source": "command_guard",
            "duration_ms": 0,
            "action_result": {
                "ok": False,
                "action": action,
                "status": "blocked",
                "result": answer_text,
            },
            "action": None,
            "needs_confirm": False,
            "speak": bool(speak),
            "status": {"blocked": True},
        }
    action_result = _smart_dialog_apply_patient_edits(
        message, selected_patient=selected_patient)
    if action_result is None:
        if action.get("key") not in {"unknown", "blocked_shell"}:
            command_message = message
            if selected_patient and action.get("key") in {
                    "patient_tool", "open_patient_folder",
                    "patient_pdf_print", "workflow_draft"}:
                command_message = f"{message} {selected_patient}"
            action_result = _command_center_run_message(
                command_message, force_confirmed=bool(confirmed))
        elif any(k in _fold_search_text(message) for k in (
                "durum", "hazir", "model", "ollama", "orthanc", "comfyui",
                "dicom", "plugin")):
            action_result = {
                "ok": True,
                "status": "diagnostic",
                "action": {
                    "key": "smart_status",
                    "label": "Akilli sistem ozeti",
                },
                "result": "\n".join(
                    _smart_dialog_status_payload(deep=False).get("suggestions") or []),
            }

    action_status = str((action_result or {}).get("status") or "").strip()
    if action_result and (
            action_status == "waiting_confirm"
            or bool(action_result.get("ok"))
            or action_status in {"diagnostic", "success", "done", "routed"}):
        action_from_result = (
            dict((action_result or {}).get("action") or {})
            if isinstance((action_result or {}).get("action"), dict)
            else {}
        )
        resolved_action = _smart_dialog_normalize_action(action_from_result)
        if not resolved_action:
            route_from_result = str((action_result or {}).get("route") or "").strip()
            if _smart_dialog_is_allowed_route(route_from_result):
                result_key = str(action_from_result.get("key") or "").strip()
                resolved_action = {
                    "route": route_from_result,
                    "label": "Sayfayi ac",
                }
                if _smart_dialog_is_safe_command_key(result_key):
                    resolved_action["command_key"] = result_key
                else:
                    resolved_action["command_key"] = "navigate"
        if not resolved_action:
            resolved_action = _smart_dialog_normalize_action(action)
        answer_text = str(
            action_result.get("result")
            or action_result.get("message")
            or action_result.get("answer")
            or "").strip()
        if action_status == "waiting_confirm":
            answer_text = (
                answer_text
                or action_from_result.get("summary")
                or "Bu islem icin onay gerekiyor. Evet dersen uygularim."
            )
        elif not answer_text:
            if resolved_action and resolved_action.get("route"):
                answer_text = f"{resolved_action.get('label') or 'Sayfa'} aciliyor."
            else:
                answer_text = "Tamam, islemi yaptim."
        meta = {
            "source": "fast_action",
            "duration_ms": 0,
            "action": resolved_action or action_from_result or action,
            "status": action_status or "fast_action",
        }
        _smart_dialog_save("assistant", answer_text, meta=meta, dialog_id=dialog_id)
        return {
            "ok": True,
            "dialog_id": dialog_id,
            "answer": answer_text,
            "source": "fast_action",
            "duration_ms": 0,
            "action_result": action_result,
            "action": resolved_action,
            "needs_confirm": action_status == "waiting_confirm",
            "speak": bool(speak),
            "status": {"fast_action": True},
        }

    companion_reply = _smart_dialog_live_companion_reply(
        message, client_context=client_context)
    if companion_reply:
        meta = {
            "source": "live_companion",
            "duration_ms": 0,
            "action": None,
            "status": "chat",
        }
        _smart_dialog_save("assistant", companion_reply, meta=meta, dialog_id=dialog_id)
        return {
            "ok": True,
            "dialog_id": dialog_id,
            "answer": companion_reply,
            "source": "live_companion",
            "duration_ms": 0,
            "action_result": action_result,
            "action": None,
            "needs_confirm": False,
            "speak": bool(speak),
            "status": {"live_companion": True},
        }

    # D120: 12->20 server, 10->14 client, kombine 14->24 (sliding window).
    history = _smart_dialog_history(dialog_id=dialog_id, limit=20)
    client_turns = _smart_dialog_client_history(client_history, limit=14)
    if client_turns:
        history = (history + client_turns)[-24:]
    answer, source, duration = _smart_dialog_ai_reply(
        message, action_result=action_result, history=history,
        selected_patient=selected_patient, client_context=client_context)
    answer_text, parsed_action = _smart_dialog_extract_action_from_answer(answer)
    resolved_action = parsed_action
    if not resolved_action:
        action_from_result = (
            dict((action_result or {}).get("action") or {})
            if isinstance((action_result or {}).get("action"), dict)
            else {}
        )
        resolved_action = _smart_dialog_normalize_action(action_from_result)
    if not resolved_action:
        route_from_result = str((action_result or {}).get("route") or "").strip()
        if _smart_dialog_is_allowed_route(route_from_result):
            result_key = ""
            try:
                result_key = str(((action_result or {}).get("action") or {}).get("key") or "").strip()
            except Exception:
                result_key = ""
            resolved_action = {
                "route": route_from_result,
                "label": "Sayfayi ac",
            }
            if _smart_dialog_is_safe_command_key(result_key):
                resolved_action["command_key"] = result_key
            else:
                resolved_action["command_key"] = "navigate"
    if not resolved_action:
        resolved_action = _smart_dialog_normalize_action(action)
    if not answer_text and resolved_action:
        answer_text = "Islemi hazirladim."

    meta = {
        "source": source,
        "duration_ms": duration,
        "action": resolved_action or (action_result or {}).get("action") or action,
        "status": (action_result or {}).get("status") or "chat",
    }
    _smart_dialog_save("assistant", answer_text, meta=meta, dialog_id=dialog_id)
    payload = {
        "ok": True,
        "dialog_id": dialog_id,
        "answer": answer_text,
        "source": source,
        "duration_ms": duration,
        "action_result": action_result,
        "action": resolved_action,
        "needs_confirm": bool(
            action_result and action_result.get("status") == "waiting_confirm"),
        "speak": bool(speak),
        "status": _smart_dialog_status_payload(deep=False),
    }
    return payload


# ====== D122: IVF / Infertilite Super Destek Modulu ======
# Op. Dr. Hakan YAZ icin tup bebek ve infertilite konsult kalitesinde
# yardimci fonksiyonlar + ozel sayfa. Goal: tup bebek doktoru kadar
# kapsamli mantik yurusun, hizli karar destegi versin.

def _ivf_safe_float(value, default=None):
    try:
        if value is None:
            return default
        s = str(value).strip().replace(",", ".")
        if not s:
            return default
        return float(s)
    except Exception:
        return default


def _ivf_ovaryan_rezerv_yorum(amh, afc, fsh, age):
    """AMH (ng/mL), AFC, FSH (mIU/mL, D2-3), age -> kategori + yorum."""
    amh_v = _ivf_safe_float(amh)
    afc_v = _ivf_safe_float(afc)
    fsh_v = _ivf_safe_float(fsh)
    age_v = _ivf_safe_float(age)
    # Hesap: AMH oncelikli, AFC dogrulayici, FSH ileri yas onemli
    cat = "bilinmiyor"
    score_low = 0
    score_high = 0
    if amh_v is not None:
        if amh_v < 0.5:
            cat = "cok dusuk rezerv"
            score_low += 3
        elif amh_v < 1.1:
            cat = "dusuk rezerv (POR)"
            score_low += 2
        elif amh_v < 4.0:
            cat = "normal rezerv"
        elif amh_v < 7.0:
            cat = "yuksek rezerv (PCOS supheli)"
            score_high += 1
        else:
            cat = "cok yuksek rezerv (PCOS lehine)"
            score_high += 2
    if afc_v is not None:
        if afc_v < 5:
            score_low += 1
        elif afc_v < 7:
            pass
        elif afc_v > 24:
            score_high += 2
        elif afc_v > 16:
            score_high += 1
    if fsh_v is not None:
        if fsh_v > 10:
            score_low += 1
        if fsh_v > 15:
            score_low += 1
    if age_v is not None and age_v >= 38:
        score_low += 1
    bologna = (
        amh_v is not None and amh_v < 1.1
        or (afc_v is not None and afc_v < 7)
        or (age_v is not None and age_v >= 40)
    )
    return {
        "kategori": cat,
        "low_score": score_low,
        "high_score": score_high,
        "bologna_por": bologna,
        "amh": amh_v, "afc": afc_v, "fsh": fsh_v, "age": age_v,
    }


def _ivf_beklenen_oosit(amh, afc, age):
    """Tahmini retrieved oocyte sayisi (literatur korelasyonu)."""
    amh_v = _ivf_safe_float(amh)
    afc_v = _ivf_safe_float(afc)
    age_v = _ivf_safe_float(age) or 32
    base = None
    if afc_v is not None:
        # Klasik korelasyon: AFC ~ 0.8x oosit
        base = max(1.0, afc_v * 0.85)
    elif amh_v is not None:
        # AMH ng/mL * ~2.5 ≈ oosit sayisi
        base = max(1.0, amh_v * 2.6)
    if base is None:
        return None
    if age_v >= 40:
        base *= 0.75
    elif age_v >= 38:
        base *= 0.85
    return round(base, 1)


def _ivf_protokol_oneri(amh, afc, age, history=None):
    """Hasta parametrelerine gore protokol onerisi."""
    rez = _ivf_ovaryan_rezerv_yorum(amh, afc, None, age)
    cat = rez.get("kategori", "")
    age_v = rez.get("age") or 32
    history = (history or "").lower()
    suggestions = []
    if "yuksek" in cat or "pcos" in cat:
        suggestions.append({
            "name": "GnRH Antagonist + GnRH agonist trigger + freeze-all",
            "neden": "PCOS/yuksek rezerv -> OHSS riski yuksek; agonist trigger LH "
                    "patlamasini taklit eder, freeze-all luteal faz icin guvenli.",
            "doz": "rFSH 100-150 IU/gun, antagonist follikul >=14 mm.",
        })
        suggestions.append({
            "name": "PPOS (progestin priming)",
            "neden": "Esnek, freeze-all planlanan PCOS hastalarinda iyi alternatif.",
            "doz": "MPA 10 mg/gun + rFSH 150 IU.",
        })
    elif "dusuk" in cat or rez.get("bologna_por"):
        suggestions.append({
            "name": "GnRH Antagonist + dual trigger",
            "neden": "Dusuk rezervde antagonist en yaygin; dual trigger (hCG + GnRH "
                    "agonist) oosit kalitesi/maturasyon icin yararli olabilir.",
            "doz": "rFSH 300 IU + LH supplementasyon (luveris) 75-150 IU.",
        })
        suggestions.append({
            "name": "Mild stimulation / Mini-IVF (klomifen + dusuk doz FSH)",
            "neden": "Beklenen oosit sayisi <=4 ise yuksek dozun ek katki saglamadigi "
                    "gosterildi (ESHRE Bologna). Hastaya yum yumusak.",
            "doz": "Klomifen 100 mg D3-7 + rFSH 150 IU EOD.",
        })
        if age_v >= 40:
            suggestions.append({
                "name": "DuoStim (luteal faz stimulasyonu)",
                "neden": "Ileri yas + dusuk rezervde ayni siklusta foliküler ve luteal "
                        "faz stimulasyonu daha cok oosit elde edebilir.",
                "doz": "Foliküler faz standart antagonist; OPU sonrasi 5. gun ikinci "
                       "stimulasyon.",
            })
    else:
        # Normal rezerv
        suggestions.append({
            "name": "GnRH Antagonist (standart)",
            "neden": "Normal rezerv, basari ve guvenlik dengesi en iyi protokol. "
                    "Daha kisa, daha az enjeksiyon, OHSS riski dusuk.",
            "doz": "rFSH 150-225 IU; antagonist follikul >=14 mm; trigger 17-18 mm "
                   "dominant follikul.",
        })
        if "tekrarlayan basarisiz" in history or "tekrar et" in history:
            suggestions.append({
                "name": "Long agonist (uzun protokol)",
                "neden": "Tekrarlayan implantasyon basarisizligi veya endometriyozis "
                        "varsa daha kontrollu hipertekikiti saglar.",
                "doz": "Luteal faz 21. gun GnRH agonist + supresyon sonrasi rFSH.",
            })
    # Tum hastalar icin temel oneriler
    common = [
        "Folik asit 0.4-1 mg/gun (ovum kalitesi); PCOS/inositol denemesi opsiyonel.",
        "BMI 19-30 hedefi (uc dort kg degisim bile basariyi etkiler).",
        "DHEA 75 mg/gun POR'da (8-12 hf, kanit orta).",
        "CoQ10 200-600 mg/gun ileri yas/POR (mitokondriyal destek, kanit orta).",
        "Luteal destek vajinal progesteron 600-800 mg/gun + 8-10 hf devam.",
    ]
    return {
        "rezerv": rez,
        "beklenen_oosit": _ivf_beklenen_oosit(amh, afc, age),
        "protokoler": suggestions,
        "destek": common,
    }


def _ivf_ohss_risk(amh, afc, age, pcos=False, prev_ohss=False):
    amh_v = _ivf_safe_float(amh)
    afc_v = _ivf_safe_float(afc)
    age_v = _ivf_safe_float(age)
    score = 0
    risk = "dusuk"
    factors = []
    if amh_v is not None and amh_v >= 3.5:
        score += 2; factors.append(f"AMH {amh_v} ng/mL (>=3.5 yuksek)")
    if afc_v is not None and afc_v >= 24:
        score += 2; factors.append(f"AFC {int(afc_v)} (>=24 yuksek)")
    elif afc_v is not None and afc_v >= 18:
        score += 1; factors.append(f"AFC {int(afc_v)} (18-23 orta)")
    if pcos:
        score += 2; factors.append("PCOS tanisi")
    if prev_ohss:
        score += 3; factors.append("Onceki OHSS oykusu")
    if age_v is not None and age_v < 30:
        score += 1; factors.append(f"Genc yas ({int(age_v)})")
    if score >= 4:
        risk = "yuksek"
    elif score >= 2:
        risk = "orta"
    korunma = []
    if risk in ("orta", "yuksek"):
        korunma = [
            "GnRH antagonist + GnRH agonist trigger (hCG yerine)",
            "Freeze-all (segmentasyon) — taze transferden kacin",
            "Kabergolin 0.5 mg/gun 8 gun (D-day'den itibaren)",
            "Tek embriyo transferi (eSET)",
            "Coasting (gerekirse) yuksek E2'de gonadotropin durdurma",
        ]
    return {"risk": risk, "score": score, "factors": factors, "korunma": korunma}


def _ivf_blastosist_yorum(grade):
    """Gardner skoru (orn '4AA', '5BB', '3BC') yorumla."""
    g = str(grade or "").strip().upper().replace(" ", "")
    if not g:
        return ""
    m = re.match(r"^(\d)([A-C])([A-C])$", g)
    if not m:
        return "Format: <ekspansiyon 1-6><ICM A/B/C><TE A/B/C>, ornek 4AA."
    exp = int(m.group(1))
    icm = m.group(2)
    te = m.group(3)
    quality = (
        "yuksek (taze transfer / freeze)" if (icm in "A" and te in "AB") or (icm == "B" and te == "A")
        else "orta (transfer dusunulebilir)" if (icm in "AB" and te in "ABC")
        else "dusuk (kalite siniri)"
    )
    pgta = "PGT-A icin uygun (TE biyopsi >=3BB)" if exp >= 3 and te in "AB" else "PGT-A icin sinir"
    return (
        f"Blastosist {g}: ekspansiyon {exp}/6, ICM {icm}, TE {te}. "
        f"Kalite: {quality}. {pgta}. Implantasyon orani: AA ~%55-60, AB/BA ~%40-50, "
        f"BB ~%30-40, BC/CB ~%15-25, CC <%10."
    )


def _ivf_hcg_kinetik_yorum(hcg1, hcg2, gun_arasi):
    """Iki hCG degeri ve gun farki -> dublaj zamanı yorumu."""
    h1 = _ivf_safe_float(hcg1)
    h2 = _ivf_safe_float(hcg2)
    d = _ivf_safe_float(gun_arasi)
    if h1 is None or h2 is None or d is None or d <= 0 or h1 <= 0:
        return "Iki hCG degeri ve gun farki gerekli (orn. 50 -> 110, 2 gun)."
    artis_yuzde = ((h2 - h1) / h1) * 100.0
    import math
    katlanma_saat = (d * 24.0 * math.log(2)) / math.log(h2 / h1) if h2 > h1 else None
    yorum = []
    if h2 > h1:
        if h1 < 1500:
            beklenen = ">= %53 / 48 sa"
            uygun = artis_yuzde >= ((d / 2.0) * 53.0)
        elif h1 < 5000:
            beklenen = ">= %40 / 48 sa"
            uygun = artis_yuzde >= ((d / 2.0) * 40.0)
        else:
            beklenen = ">= %33 / 48 sa (yavaslar)"
            uygun = artis_yuzde >= ((d / 2.0) * 33.0)
        yorum.append(f"Artis: %{artis_yuzde:.1f} ({d:.1f} gunde). Beklenen {beklenen}.")
        if katlanma_saat:
            yorum.append(f"Katlanma suresi: ~{katlanma_saat:.0f} saat.")
        yorum.append("Kinetik UYGUN (viable gebelik lehine)." if uygun else
                     "Kinetik YETERSIZ — ektopik veya nonviable gebelik dusun.")
    else:
        yorum.append(f"hCG dusus / plato (%{artis_yuzde:.1f}) — gebelik kayip / "
                     f"ektopik degerlendirme gerekir.")
    return " ".join(yorum)


# ====== D122: Riskli Gebelik Takibi Super Destek Modulu ======
# Diyabetik gebelik (T1/T2/GDM), hipertansif bozukluklar, tiroid, APS,
# trombofili, oncekipreterm/IUGR — kanita dayali risk skor + plan motoru.

def _hrp_safe_float(value, default=None):
    return _ivf_safe_float(value, default)


def _hrp_gdm_glikoz_yorum(aclik, sa1, sa2):
    """GDM glikoz hedef takibi (IADPSG hedefleri)."""
    a = _hrp_safe_float(aclik); s1 = _hrp_safe_float(sa1); s2 = _hrp_safe_float(sa2)
    msgs = []; uygun = True
    if a is not None:
        if a < 95: msgs.append(f"Aclik {a:.0f} mg/dL — UYGUN (hedef <95).")
        else: msgs.append(f"Aclik {a:.0f} mg/dL — YUKSEK (hedef <95)."); uygun = False
    if s1 is not None:
        if s1 < 140: msgs.append(f"1. saat {s1:.0f} mg/dL — UYGUN (hedef <140).")
        else: msgs.append(f"1. saat {s1:.0f} mg/dL — YUKSEK (hedef <140)."); uygun = False
    if s2 is not None:
        if s2 < 120: msgs.append(f"2. saat {s2:.0f} mg/dL — UYGUN (hedef <120).")
        else: msgs.append(f"2. saat {s2:.0f} mg/dL — YUKSEK (hedef <120)."); uygun = False
    if not msgs:
        return ""
    if not uygun:
        msgs.append("Yonetim: 1-2 hafta yogun diyet+egzersiz; yetersizse insulin "
                    "(1. tercih) veya metformin. Hedef tutturulmazsa gunluk insulin "
                    "doz ayarla.")
    else:
        msgs.append("Glisemik kontrol uygun — diyet/egzersize devam, haftalik takip.")
    return " ".join(msgs)


def _hrp_preeklampsi_risk(age, bmi, parite, prev_pe, kronik_ht, kdh, t2dm,
                          aps, ckd, ivf, ailede_pe, ikiz=False, sat_uta_pi=None):
    """NICE 2019 preeklampsi risk skorlama (yuksek/orta risk -> aspirin)."""
    high_factors = []
    moderate_factors = []
    if prev_pe: high_factors.append("Onceki preeklampsi")
    if kronik_ht: high_factors.append("Kronik hipertansiyon")
    if t2dm: high_factors.append("Diyabet (Tip1/Tip2)")
    if aps: high_factors.append("Antifosfolipid sendrom (APS)")
    if ckd: high_factors.append("Kronik bobrek hastaligi")
    if kdh: high_factors.append("Otoimmun (SLE, vs)")
    age_v = _hrp_safe_float(age)
    bmi_v = _hrp_safe_float(bmi)
    if age_v is not None and age_v >= 40: moderate_factors.append(f"Yas {int(age_v)} (>=40)")
    if bmi_v is not None and bmi_v >= 35: moderate_factors.append(f"BMI {bmi_v:.1f} (>=35)")
    elif bmi_v is not None and bmi_v >= 30: moderate_factors.append(f"BMI {bmi_v:.1f} (>=30)")
    if str(parite or "").strip() in ("0", "nullipar", "ilk"): moderate_factors.append("Nullipar")
    if ailede_pe: moderate_factors.append("Aile oykusu preeklampsi")
    if ivf: moderate_factors.append("IVF gebelik")
    if ikiz: moderate_factors.append("Cogul gebelik (ikiz/uclu)")
    sat = _hrp_safe_float(sat_uta_pi)
    if sat is not None and sat >= 1.6: moderate_factors.append(f"Uterin arter PI {sat:.2f} >=95p")
    nice_high = len(high_factors) >= 1
    nice_moderate = len(moderate_factors) >= 2
    aspirin = nice_high or nice_moderate
    return {
        "yuksek_risk_faktorler": high_factors,
        "orta_risk_faktorler": moderate_factors,
        "aspirin_endike": aspirin,
        "aspirin_doz": "150 mg/gun, 12-16. haftada baslat, 36. haftaya devam.",
        "ek_oneri": [
            "Bazal lab (CBC, kreatinin, urik asit, KCFT, TIT, idrar P/Cr) <20 hf.",
            "TA evde takip (sabah-aksam ortalama).",
            "Kalsiyum >=1.5 g/gun (dusuk Ca alimi varsa).",
            "Kilo kontrolu (gebelik IOM hedeflerine gore).",
            "Risk yuksek -> 16-24 hf uterin arter Doppler.",
            "Yuksek risk -> 28-32 hf'den itibaren PlGF/sFlt-1 oranlandirma takibi.",
        ] if aspirin else ["Standart antenatal takip + 24-28 hf preeklampsi tarama."],
    }


def _hrp_preterm_risk(prev_preterm=False, cl_mm=None, fetal_fibronektin=False,
                     multipar_uzun_emr=False, twin=False, prev_konizasyon=False,
                     uterin_anomali=False):
    """Preterm dogum risk + onleme onerisi."""
    score = 0; factors = []
    if prev_preterm:
        score += 3; factors.append("Onceki spontan preterm dogum (en gucsuz prediktor)")
    cl = _hrp_safe_float(cl_mm)
    if cl is not None and cl < 15:
        score += 4; factors.append(f"CL {cl:.0f} mm (<15 ciddi kisa)")
    elif cl is not None and cl < 25:
        score += 2; factors.append(f"CL {cl:.0f} mm (<25 kisa)")
    if fetal_fibronektin: score += 2; factors.append("fFN pozitif (>=50 ng/mL)")
    if twin: score += 2; factors.append("Cogul gebelik")
    if prev_konizasyon: score += 1; factors.append("Onceki LEEP/konizasyon")
    if uterin_anomali: score += 1; factors.append("Uterin anomali")
    if multipar_uzun_emr: score += 1; factors.append("Onceki uzamis EMR")
    risk = "dusuk" if score < 2 else "orta" if score < 4 else "yuksek"
    plan = []
    if cl is not None and cl < 25:
        plan.append("Vajinal progesteron 200 mg/gun yatistan once 16-36 hf.")
    if cl is not None and cl < 25 and prev_preterm:
        plan.append("Tek fetus + onceki preterm + CL <25 mm -> serklaj (McDonald) "
                    "<24 hf dusun.")
    if prev_preterm:
        plan.append("17-OHPC (Makena) — 2020'den sonra etkisiz bulundu, FDA cekti; "
                    "vajinal progesteron tek kanitli secenek.")
    if score >= 4:
        plan.append("16-24 hf TVS-CL 2 haftada bir; preterm semptomda fFN.")
    if not plan:
        plan.append("Standart antenatal takip; CL 20-24 hf rutin tarama.")
    return {"risk": risk, "score": score, "factors": factors, "plan": plan}


def _hrp_vte_risk(yas=None, bmi=None, parite=0, immobilizasyon=False, varikose=False,
                  oncekivte=False, trombofili=False, sigara=False, ivf=False,
                  preeklampsi=False, sezaryen=False):
    """RCOG GTG37a benzeri VTE risk skoru."""
    score = 0; factors = []
    age_v = _hrp_safe_float(yas)
    bmi_v = _hrp_safe_float(bmi)
    if age_v is not None and age_v >= 35: score += 1; factors.append(f"Yas {int(age_v)}")
    if bmi_v is not None and bmi_v >= 40: score += 2; factors.append(f"BMI {bmi_v:.1f} (>=40)")
    elif bmi_v is not None and bmi_v >= 30: score += 1; factors.append(f"BMI {bmi_v:.1f} (>=30)")
    p = _hrp_safe_float(parite)
    if p is not None and p >= 3: score += 1; factors.append(f"Parite >=3")
    if immobilizasyon: score += 3; factors.append("Immobilizasyon")
    if varikose: score += 1; factors.append("Belirgin varikoz")
    if oncekivte: score += 4; factors.append("Onceki VTE")
    if trombofili: score += 3; factors.append("Trombofili")
    if sigara: score += 1; factors.append("Sigara")
    if ivf: score += 1; factors.append("IVF gebelik")
    if preeklampsi: score += 1; factors.append("Preeklampsi")
    if sezaryen: score += 2; factors.append("Sezaryen dogum")
    plan = []
    if score >= 4:
        plan.append("Antenatal LMWH profilaksi (enoksaparin 40 mg/gun, BMI'ye gore "
                    "ayarla; >=90 kg 60 mg, >=130 kg 80 mg).")
        plan.append("Postpartum 6 hf devam.")
    elif score >= 3:
        plan.append("28. haftadan itibaren antenatal LMWH profilaksi.")
        plan.append("Postpartum 6 hf devam.")
    elif score >= 2:
        plan.append("Antenatal mobilizasyon + hidrasyon; postpartum 10 gun LMWH.")
    else:
        plan.append("Genel mobilizasyon + hidrasyon, ek profilaksi gereksiz.")
    return {"score": score, "factors": factors, "plan": plan}


def _hrp_ta_yorum(sis, dia):
    """Gebelikte TA yorumu (NICE/ACOG)."""
    s = _hrp_safe_float(sis); d = _hrp_safe_float(dia)
    if s is None or d is None: return ""
    cat = "normal"
    notlar = []
    if s >= 160 or d >= 110:
        cat = "ciddi hipertansiyon"
        notlar.append("ACILII degerlendirme: 15 dk icinde tekrar olc; "
                      "preeklampsi taramasi (proteinuri, organ tutulumu).")
        notlar.append("Tedavi: 15-30 dk IV labetalol 20 mg / hidralazin 5-10 mg, hedef "
                      "TA <160/110.")
    elif s >= 140 or d >= 90:
        cat = "hipertansiyon (tedavi gerek)"
        notlar.append("Iki ayri olcumde >=140/90 -> antihipertansif baslat. "
                      "Hedef TA <135/85 (CHIPS).")
        notlar.append("1. tercih: labetalol 100 mg BID-TID, metildopa 250-500 mg TID, "
                      "nifedipin SR 30 mg BID. ACE/ARB KONTRAENDIKE.")
    elif s >= 130 or d >= 80:
        cat = "yuksek normal"
        notlar.append("Tekrar olcum + yasam tarzi; takip artir.")
    return f"TA {int(s)}/{int(d)} mmHg — {cat}. " + " ".join(notlar)


def _hrp_tiroid_yorum(tsh, free_t4, gebelik_haftasi=None, anti_tpo=False):
    """Gebelikte tiroid degerlendirme."""
    t = _hrp_safe_float(tsh); ft4 = _hrp_safe_float(free_t4)
    gh = _hrp_safe_float(gebelik_haftasi)
    if t is None: return ""
    # Trimester hedefleri (ATA 2017)
    if gh is not None and gh < 14:
        ust = 2.5; alt = 0.1
        trim = "1. trimester"
    elif gh is not None and gh < 28:
        ust = 3.0; alt = 0.2
        trim = "2. trimester"
    else:
        ust = 3.0; alt = 0.3
        trim = "3. trimester"
    msgs = [f"TSH {t:.2f} mIU/L ({trim} hedef {alt}-{ust})"]
    if t > ust:
        if ft4 is not None and ft4 < 0.8:
            msgs.append("ASIKAR HIPOTIROIDI -> levotiroksin baslat / artir.")
        else:
            msgs.append("Subklinik hipotiroidi.")
            if anti_tpo:
                msgs.append("Anti-TPO pozitif -> levotiroksin onerilir.")
            else:
                msgs.append("Anti-TPO negatif -> tartismali, TSH >4 ise tedaviyi dusun.")
        msgs.append("Levotiroksin baslangic: 1-2 mcg/kg/gun (TSH 4-10 ise 50-75 mcg).")
    elif t < alt:
        if ft4 is not None and ft4 > 1.7:
            msgs.append("ASIKAR HIPERTIROIDI -> 1. tri PTU, 2-3. tri metimazol.")
        else:
            msgs.append("Subklinik hipertiroidi (genelde gebelige bagli, takip).")
    else:
        msgs.append("Normal sinirlarda — hedef TSH'ya gore takip.")
    return " ".join(msgs)


