def _drug_normalize(name):
    """Recete satirindaki ilac adi -> standart anahtar."""
    if not name:
        return ""
    s = _fold_search_text(str(name))
    # Yaygin variant temizleme
    s = re.sub(r"\b(mg|gr|gram|ml|iu|tab|tablet|kaps|kapsul|suspansiyon|"
               r"sup|drop|ampul|amp|sirop|syrup|solusyon|vial)\b", "", s)
    s = re.sub(r"\b\d+([.,]\d+)?\b", "", s)  # rakamlar
    s = re.sub(r"\s+", " ", s).strip()
    return s


def _drug_lookup_safety(name):
    """Ilac adindan gebelik guvenlik bilgisi don. Kismi eslesme dahil."""
    norm = _drug_normalize(name)
    if not norm:
        return None
    # Tam eslesme
    if norm in _PREGNANCY_DRUG_DB:
        return _PREGNANCY_DRUG_DB[norm]
    # Kismi (one-word substring kontrol)
    for key, info in _PREGNANCY_DRUG_DB.items():
        if key and (key in norm or norm in key):
            return info
    # Tek tek token bazli arama
    tokens = norm.split()
    for tok in tokens:
        if len(tok) >= 4 and tok in _PREGNANCY_DRUG_DB:
            return _PREGNANCY_DRUG_DB[tok]
    return None


def _drug_check_interactions(drug_names):
    """Birden cok ilac adi -> uyari listesi."""
    if not drug_names:
        return []
    norm = []
    for n in drug_names:
        s = _drug_normalize(n)
        if s:
            norm.append(s)
    out = []
    for combo, severity, msg in _DRUG_INTERACTION_DB:
        # Her elementin en az birinin norm string'inde gectiginden emin ol
        if all(any(c in nstr or nstr in c for nstr in norm) for c in combo):
            out.append({"severity": severity, "message": msg, "drugs": list(combo)})
    return out


def _drug_check_pregnancy(drug_names, gebelik_haftasi=None):
    """Her ilac icin gebelik guvenlik degerlendirmesi."""
    if not drug_names:
        return []
    out = []
    gh = _ivf_safe_float(gebelik_haftasi)
    for raw in drug_names:
        info = _drug_lookup_safety(raw)
        if not info:
            out.append({"name": raw, "match": False,
                         "level": "bilinmiyor",
                         "message": "Bu ilac veritabaninda bulunamadi. Manuel referans kontrol et."})
            continue
        cat = info.get("cat", "?")
        ok = info.get("ok", True)
        warn = info.get("warn", "") or ""
        note = info.get("note", "") or ""
        # Trimester ozel kapilar
        msg = warn if warn else note
        level = "ok" if ok else ("danger" if cat in ("X", "D") else "warn")
        # Trimester filtresi
        if gh is not None:
            lower_warn = warn.lower()
            if "1. trimester" in lower_warn and gh >= 14:
                # 1. tri uyarisi 2. tridan sonra dusuk
                if "kontraendike" not in lower_warn:
                    level = "warn"
            if ">=15 hf" in lower_warn and gh < 15:
                level = "warn"  # daha az risk
            if ">=20 hf" in lower_warn and gh < 20:
                level = "warn"
            if ">=30 hf" in lower_warn and gh < 30:
                level = "warn" if "kontraendike" not in lower_warn else level
        out.append({
            "name": raw, "match": True, "category": cat, "level": level,
            "message": msg or "Standart guvenli kullanim.",
            "ok": ok,
        })
    return out


@app.route("/api/ilac-guvenlik-kontrol", methods=["POST"])
@permission_required("view_command_center")
def api_ilac_guvenlik_kontrol():
    """JSON: { drugs: [...], gebelik_haftasi: opsiyonel }
    Returns: gebelik kategorisi + etkilesim uyarilari."""
    payload = request.get_json(silent=True) or request.form or {}
    drugs = payload.get("drugs") or payload.get("ilaclar") or []
    if isinstance(drugs, str):
        drugs = [d.strip() for d in re.split(r"[;,\n]+", drugs) if d.strip()]
    gh = payload.get("gebelik_haftasi") or payload.get("hafta") or ""
    pregnancy_results = _drug_check_pregnancy(drugs, gh)
    interactions = _drug_check_interactions(drugs)
    return jsonify({
        "ok": True,
        "gebelik_haftasi": gh,
        "pregnancy_safety": pregnancy_results,
        "interactions": interactions,
        "drugs_count": len(drugs),
    })


