def _oi_protocol_oneri(endikasyon, age, amh, bmi, prev_cc_cycles, prev_cc_response,
                       hiperandrojenemi, klomifen_direncli, ivf_planlandi=False):
    """Endikasyon ve hasta profiline gore OI protokol onerisi."""
    age_v = _ivf_safe_float(age)
    amh_v = _ivf_safe_float(amh)
    bmi_v = _ivf_safe_float(bmi)
    prev_n = _ivf_safe_float(prev_cc_cycles) or 0
    e = (endikasyon or "").lower().strip()
    suggestions = []

    # PCOS anovulasyon
    if "pcos" in e or "anovulasyon" in e or "polikistik" in e:
        if klomifen_direncli or prev_n >= 3:
            if hiperandrojenemi:
                suggestions.append(_OI_PROTOCOLS["klomifen_deksametazon"])
            if bmi_v is not None and bmi_v >= 27:
                suggestions.append(_OI_PROTOCOLS["klomifen_metformin"])
            suggestions.append(_OI_PROTOCOLS["letrozol_gonadotropin"])
            suggestions.append(_OI_PROTOCOLS["gonadotropin_lowdose_step_up"])
        else:
            # 1. tercih PCOS'ta letrozol (PPCOS II)
            suggestions.append(_OI_PROTOCOLS["letrozol"])
            suggestions.append(_OI_PROTOCOLS["klomifen"])
            if bmi_v is not None and bmi_v >= 27:
                suggestions.append(_OI_PROTOCOLS["klomifen_metformin"])

    # Açıklanamayan infertilite
    elif "aciklanamayan" in e or "unexplained" in e:
        if age_v is not None and age_v >= 38:
            suggestions.append(_OI_PROTOCOLS["gonadotropin_lowdose_step_up"])
            suggestions.append({**_OI_PROTOCOLS["letrozol"],
                "label": "Letrozol + IUI (3-4 siklus)",
            })
        else:
            suggestions.append({**_OI_PROTOCOLS["klomifen"],
                "label": "Klomifen + IUI (FASTT/FORT-T 3-4 siklus)",
            })
            suggestions.append({**_OI_PROTOCOLS["letrozol"],
                "label": "Letrozol + IUI (3-4 siklus)",
            })
            suggestions.append({**_OI_PROTOCOLS["gonadotropin_lowdose_step_up"],
                "label": "Gonadotropin + IUI (cevap yetersizse)",
            })

    # Mild erkek faktor
    elif "erkek" in e or "male factor" in e or "oligo" in e:
        suggestions.append({**_OI_PROTOCOLS["klomifen"],
            "label": "Klomifen/Letrozol + IUI (mild erkek faktor)",
        })
        suggestions.append({**_OI_PROTOCOLS["gonadotropin_lowdose_step_up"],
            "label": "Gonadotropin + IUI (orta-ciddi)",
        })

    # Hipotalamik hipogonadizm
    elif "hipotalamik" in e or "kallman" in e or "wht" in e or "fonksiyonel amenore" in e:
        suggestions.append(_OI_PROTOCOLS["gnrh_pulsatil"])
        suggestions.append(_OI_PROTOCOLS["gonadotropin_lowdose_step_up"])

    # IUI icin stim
    elif "iui" in e:
        suggestions.append(_OI_PROTOCOLS["letrozol"])
        suggestions.append(_OI_PROTOCOLS["klomifen"])
        suggestions.append(_OI_PROTOCOLS["gonadotropin_lowdose_step_up"])

    # Default
    else:
        suggestions.append(_OI_PROTOCOLS["letrozol"])
        suggestions.append(_OI_PROTOCOLS["klomifen"])

    # IVF planlanan icin
    if ivf_planlandi or (age_v is not None and age_v >= 40 and prev_n >= 3):
        suggestions.append({"label": "IVF/ICSI'ye gec — yas/basarisiz oncekisikluslar"})

    # Genel ortak oneriler
    common = [
        "Folik asit 0.4-1 mg/gun (yuksek risk 5 mg).",
        "BMI hedef 19-30; >=30 hastalarda kilo verme tek basina ovulasyonu artirabilir.",
        "Bazal hormon panel (FSH, LH, E2, AMH, TSH, prolaktin, total/serbest testosteron, "
        "DHEA-S, 17-OHP) D2-3.",
        "Tubal aciklik testi (HSG/Hyfosi) genelde gereksinimdir (>=6 siklus oncesi).",
        "Partner spermiogram en az bir kere ovulasyonsuzluk tedavisi oncesi.",
    ]
    return {"protokoler": suggestions, "common": common}


def _oi_cycle_takvim(start_date_iso, protokol_key="letrozol"):
    """OI cycle takvimi — adim adim USG/trigger/IUI."""
    if not start_date_iso:
        return []
    try:
        from datetime import datetime as _dt, timedelta as _td
        d0 = _dt.strptime(start_date_iso, "%Y-%m-%d")
    except Exception:
        return []
    p = (protokol_key or "letrozol").lower()
    items = []
    items.append({"day": 1, "date": d0, "label": "Mens 1. gun — bazal USG (kist dislama), bazal hormon (FSH/E2/LH)."})
    if "letrozol" in p or "klomifen" in p:
        items.append({"day": 3, "date": d0 + _td(days=2), "label": f"Tedavi baslangic: {p.title()} 5 gun (D3-7)."})
        items.append({"day": 8, "date": d0 + _td(days=7), "label": "Tedavi bitis."})
        items.append({"day": 11, "date": d0 + _td(days=10), "label": "USG monitoring (dominant follikul + endometriyum)."})
        items.append({"day": 13, "date": d0 + _td(days=12), "label": "USG tekrar (follikul >=18 mm + endometriyum >=7 mm)."})
        items.append({"day": 14, "date": d0 + _td(days=13), "label": "TRIGGER hCG 5000-10000 IU IM (ya da spontan LH piki)."})
        items.append({"day": 15, "date": d0 + _td(days=14), "label": "IUI veya TI 24-36 sa sonra (D15-16)."})
        items.append({"day": 28, "date": d0 + _td(days=27), "label": "Beta-hCG (gebelik testi)."})
    elif "gonadotropin" in p:
        items.append({"day": 3, "date": d0 + _td(days=2), "label": "rFSH 75 IU/gun SC baslangic."})
        items.append({"day": 7, "date": d0 + _td(days=6), "label": "USG + E2 — yanit kontrol."})
        items.append({"day": 9, "date": d0 + _td(days=8), "label": "USG + E2 — doz ayar (step-up gerekirse)."})
        items.append({"day": 11, "date": d0 + _td(days=10), "label": "USG + E2 — trigger karari."})
        items.append({"day": 12, "date": d0 + _td(days=11), "label": "TRIGGER (folikul >=17-18 mm)."})
        items.append({"day": 13, "date": d0 + _td(days=12), "label": "IUI 24-36 sa sonra."})
        items.append({"day": 26, "date": d0 + _td(days=25), "label": "Beta-hCG."})
    return items


def _oi_iptal_kriter(follikul_sayi_14mm, e2_pg_ml):
    """OHSS/cogul gebelik korunma — siklus iptal kriterleri."""
    f = _ivf_safe_float(follikul_sayi_14mm)
    e = _ivf_safe_float(e2_pg_ml)
    risks = []
    if f is not None and f >= 4:
        risks.append(f"{int(f)} follikul >=14 mm: cogul gebelik / OHSS riski.")
    if e is not None and e >= 2500:
        risks.append(f"E2 {int(e)} pg/mL: yuksek (>=2500) — OHSS riski.")
    if risks:
        return {
            "iptal_oneri": True,
            "factors": risks,
            "alternatif": [
                "Trigger iptal + bu siklus iliski/IUI yasak (cogul/OHSS koruma).",
                "Cevap >=4 follikul + E2 yuksek -> IVF'e konvert (oosit topla, freeze-all).",
                "Trigger doz dusuk hCG (5000) veya GnRH agonist trigger (antagonist eklenmis ise).",
            ],
        }
    return {"iptal_oneri": False, "factors": [], "alternatif": []}


