def _guide_rx_link(combo_key, regimen_idx, gebe=False, gebelik_haftasi=""):
    params = {
        "rehber_rx": "mixt",
        "combo": combo_key,
        "rx_idx": str(regimen_idx),
    }
    if gebe:
        params["gebe"] = "1"
    if gebelik_haftasi:
        params["gebelik_haftasi"] = gebelik_haftasi
    return "/tedavi-planla?" + urlencode(params)


def _guide_rx_rows_from_text(text):
    raw = (text or "").strip()
    if not raw:
        return []
    clean = re.sub(r"\s+", " ", raw)
    clean = re.sub(r"^\s*(Alternatif|Gebede|Ampirik|Yetersizse)\s*:\s*", "", clean, flags=re.I)
    clean = re.sub(r"^\s*Penisilin alerjisi\s*\([^)]*\)\s*:\s*", "", clean, flags=re.I)
    clean = re.sub(r"\[[^\]]+\]", "", clean).strip(" .")
    clean = clean.split("—", 1)[0].strip(" .")
    parts = [p.strip(" .") for p in re.split(r"\s+\+\s+", clean) if p.strip(" .")]
    rows = []
    for part in parts:
        part = re.sub(r"^(VEYA|veya)\s+", "", part).strip(" .")
        tokens = part.split()
        split_at = None
        for idx, token in enumerate(tokens):
            t = token.strip("(),.;")
            if any(ch.isdigit() for ch in t) or t in ("%1", "%2"):
                split_at = idx
                break
        if split_at is None or split_at <= 0:
            drug = part
            usage = ""
        else:
            drug = " ".join(tokens[:split_at])
            usage = " ".join(tokens[split_at:])
        rows.append({"drug": drug.strip(), "usage": usage.strip()})
    return rows or [{"drug": raw, "usage": ""}]


def _guide_rx_from_request(values):
    if (values.get("rehber_rx") or "").strip() != "mixt":
        return None
    combo_key = (values.get("combo") or "").strip()
    item = _MIXT_INFECTION_REGIMENS.get(combo_key)
    if not item:
        return None
    try:
        idx = int((values.get("rx_idx") or "0").strip())
    except Exception:
        idx = 0
    regimens = item.get("tedavi", [])
    if idx < 0 or idx >= len(regimens):
        idx = 0
    regimen = regimens[idx] if regimens else ""
    return {
        "combo_key": combo_key,
        "label": item.get("label", combo_key),
        "regimen": regimen,
        "rows": _guide_rx_rows_from_text(regimen),
        "uyari": item.get("uyari", []),
        "takip": item.get("takip", ""),
    }


def _split_custom_rx_row(row_text):
    parts = (row_text or "").split("\t", 1)
    drug = parts[0].strip()
    usage = parts[1].strip() if len(parts) > 1 else ""
    return drug, usage


def _guide_rx_prefill_from_request(values):
    label = fix_mojibake_text(str(
        values.get("guide_rx_label")
        or values.get("custom_rx_tani")
        or ""
    )).strip()
    source = fix_mojibake_text(str(
        values.get("guide_rx_source") or ""
    )).strip()
    raw_rows = []
    try:
        raw_rows.extend(values.getlist("guide_rx_row"))
    except Exception:
        pass
    try:
        raw_rows.extend(values.getlist("custom_rx_row"))
    except Exception:
        pass
    items = []
    seen = set()
    for row_text in raw_rows:
        drug, usage = _split_custom_rx_row(row_text)
        drug = fix_mojibake_text(drug).strip()
        usage = fix_mojibake_text(usage).strip()
        if not drug and not usage:
            continue
        key = (drug.lower(), usage.lower())
        if key in seen:
            continue
        seen.add(key)
        items.append({
            "name": drug or "Ilac",
            "dose": usage,
            "box_count": "1",
            "daily_frequency": "",
        })
    return {"label": label, "source": source, "items": items}


def _tedavi_resolve_patient_key_for_rx(patient_key="", hasta_no=""):
    key = str(patient_key or "").strip()
    if key:
        return key
    proto = str(hasta_no or "").strip()
    if not proto:
        return ""
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            row = con.execute(
                "SELECT patient_key FROM patient_protocols "
                "WHERE CAST(protocol_no AS TEXT)=? LIMIT 1",
                (proto,),
            ).fetchone()
            if row:
                return str(row.get("patient_key") or "").strip()
    except Exception:
        pass
    return ""


def _vaginal_discharge_dx(rengi, kokusu, kasinti, gebe=False, gebelik_haftasi=None):
    """Akinti karakteristigi -> en olasi tani + tedavi onerisi (sade)."""
    rengi = (rengi or "").lower()
    kokusu = (kokusu or "").lower()
    kasinti = (kasinti or "").lower()

    # Profil eslesmesi
    if "yesil" in rengi or "kopuk" in rengi:
        return _DISCHARGE_PROFILES["yesil_kopuklu"]
    if "kanli" in rengi or "kahve" in rengi or "kanama" in rengi:
        return _DISCHARGE_PROFILES["kanli_kahverengi"]
    if "balik" in kokusu or "amin" in kokusu:
        if "yesil" in rengi:
            return _DISCHARGE_PROFILES["yesil_kopuklu"]
        return _DISCHARGE_PROFILES["beyaz_gri_ince_balik"]
    if "krem" in rengi or "peynir" in rengi or ("kalin" in rengi and "beyaz" in rengi):
        return _DISCHARGE_PROFILES["beyaz_krem_kalin"]
    if "purulan" in rengi or ("sari" in rengi and ("kalin" in rengi or "purulan" in rengi)):
        return _DISCHARGE_PROFILES["sari_kalin_purulan"]
    if "sari" in rengi and ("yesil" in rengi or "servisit" in rengi or "lezyon" in rengi):
        return _DISCHARGE_PROFILES["sari_yesil_servisit"]
    if "kasinti" in kasinti and "beyaz" in rengi:
        return _DISCHARGE_PROFILES["beyaz_krem_kalin"]
    return _DISCHARGE_PROFILES["normal_fizyolojik"]


