def _tr_brand_lookup(jenerik):
    """Jenerik adi -> Türkiye marka listesi."""
    if not jenerik:
        return []
    norm = _drug_normalize(jenerik) if "_drug_normalize" in globals() else str(jenerik).lower().strip()
    if norm in _TR_BRAND_DB:
        return _TR_BRAND_DB[norm]
    # Substring kontrol
    for key, brands in _TR_BRAND_DB.items():
        if key and (key in norm or norm in key):
            return brands
    return []


@app.route("/api/ilac-piyasa", methods=["GET", "POST"])
@permission_required("view_command_center")
def api_ilac_piyasa():
    """Jenerik adi -> Türkiye markalari."""
    payload = request.get_json(silent=True) or {}
    jen = (payload.get("jenerik") or request.values.get("jenerik") or "").strip()
    if jen:
        return jsonify({"ok": True, "jenerik": jen, "markalar": _tr_brand_lookup(jen)})
    # Tum DB
    return jsonify({
        "ok": True,
        "count": len(_TR_BRAND_DB),
        "items": [{"jenerik": k, "markalar": v} for k, v in _TR_BRAND_DB.items()],
    })


@app.route("/ilac-piyasa", methods=["GET"])
@app.route("/turkiye-ilaclari", methods=["GET"])
@permission_required("view_command_center")
def ilac_piyasa_destek():
    """D126: Türkiye piyasa ilaç DB - jenerik -> marka rehberi."""
    arama = (request.args.get("q") or "").strip().lower()
    items = []
    for jen, markalar in _TR_BRAND_DB.items():
        if not arama or arama in jen.lower() or any(arama in m.lower() for m in markalar):
            items.append((jen, markalar))
    rows_html = ""
    for jen, markalar in items:
        markalar_html = " · ".join(f"<span class='badge bg-primary-subtle text-primary'>{sh(m)}</span>" for m in markalar)
        rows_html += f"""
        <tr>
          <td><b>{sh(jen.title())}</b></td>
          <td>{markalar_html}</td>
        </tr>"""
    if not items:
        rows_html = "<tr><td colspan='2' class='text-muted'>Eslesme yok.</td></tr>"
    content = f"""
    <div class="container-fluid py-3">
      <div class="d-flex align-items-center mb-3 flex-wrap gap-2">
        <h2 class="mb-0"><i class="bi bi-capsule-pill"></i> Türkiye Piyasa Ilaç Rehberi</h2>
        <span class="badge bg-info">D126 BRAND DB</span>
        <a href="/akilli-dialog?prefill=Türkiye piyasa ilac sor" class="btn btn-outline-primary btn-sm ms-auto">
          <i class="bi bi-chat-dots"></i> Alex'e sor
        </a>
      </div>
      <p class="text-muted small mb-3">
        Jenerik isim → Türkiye'de mevcut piyasa marka listesi. {len(_TR_BRAND_DB)} jenerik, ~400+ marka.
      </p>
      <form method="GET" action="/ilac-piyasa" class="card mb-3">
        <div class="card-body">
          <div class="input-group">
            <input type="text" class="form-control" name="q" value="{sh(arama)}" placeholder="Jenerik veya marka adi (orn. seftriakson, Rocephin, Mirena)">
            <button class="btn btn-primary" type="submit"><i class="bi bi-search"></i> Ara</button>
          </div>
        </div>
      </form>
      <div class="card">
        <div class="card-body p-0">
          <table class="table table-hover mb-0">
            <thead><tr><th style="width:30%">Jenerik / Etken Madde</th><th>Türkiye Markalari</th></tr></thead>
            <tbody>{rows_html}</tbody>
          </table>
        </div>
      </div>
    </div>
    """
    return render(content, title="Türkiye Piyasa Ilaclari")


