def _diet_rehberi_kind_for_week_table(protocol_key):
    key = str(protocol_key or "").strip()
    if key == "gdm_diyet":
        return "diabetik"
    if key in ("normal_gebelik", "hiperemezis_diyet", "anemi_demir_diyet"):
        return "gebelik"
    if key in ("pcos_diyet",):
        return "prediyabet"
    if key in ("ivf_diyet",):
        return "infertilite"
    return "standart"


def _diet_rehberi_week_table_html(protocol_key, item):
    kind = _diet_rehberi_kind_for_week_table(protocol_key)
    try:
        rows = _diet_day_rows_v1000(kind, profile={})
    except Exception:
        rows = []
    rows = _diet_ensure_7_day_rows_v1000(rows, kind, profile={})
    if not rows:
        base_items = list((item or {}).get("ogun_listesi") or [])
        meals = []
        for raw in base_items[:5]:
            txt = fix_mojibake_text(str(raw or "")).strip()
            txt = re.sub(r"^\s*[^:：]{2,28}\s*[:：]\s*", "", txt)
            meals.append(txt)
        while len(meals) < 5:
            meals.append("Klinik plana gore duzenle")
        days = ["Pazartesi", "Sali", "Carsamba", "Persembe",
                "Cuma", "Cumartesi", "Pazar"]
        rows = [(d, meals[0], meals[1], meals[2], meals[3], meals[4])
                for d in days]
    body = ""
    for day, breakfast, snack1, lunch, snack2, dinner in rows:
        body += f"""
        <tr>
          <th data-diet-editable contenteditable="true" spellcheck="false">{sh(day)}</th>
          <td data-diet-editable contenteditable="true" spellcheck="true">{sh(breakfast)}</td>
          <td data-diet-editable contenteditable="true" spellcheck="true">{sh(snack1)}</td>
          <td data-diet-editable contenteditable="true" spellcheck="true">{sh(lunch)}</td>
          <td data-diet-editable contenteditable="true" spellcheck="true">{sh(snack2)}</td>
          <td data-diet-editable contenteditable="true" spellcheck="true">{sh(dinner)}</td>
        </tr>"""
    return f"""
    <div class="yk-diet-week-wrap">
      <div class="yk-diet-week-title">
        <b>7 Gunluk Diyet Tablosu</b>
        <span>Gune gore duzenlenebilir</span>
      </div>
      <div class="table-responsive">
        <table class="yk-diet-week-table">
          <thead>
            <tr>
              <th>Gun</th>
              <th>Kahvalti</th>
              <th>Kusluk</th>
              <th>Ogle</th>
              <th>Ikindi</th>
              <th>Aksam</th>
            </tr>
          </thead>
          <tbody>{body}</tbody>
        </table>
      </div>
    </div>"""


