def _gebelik_plan_olustur(sat_iso=None, usg_hafta=None, usg_tarih_iso=None):
    """SAT veya USG bazli 40 hafta kisisel takvim.

    Oncelik: SAT > USG. Eger ikisi varsa, USG bazli SAT >7 gun farkliysa
    USG-bazli SAT'ı dikkate al (ACOG: 1. tri USG > LMP if discrepant)."""
    from datetime import datetime as _dt, timedelta as _td
    sat_dt = None
    notlar = []
    try:
        if sat_iso:
            sat_dt = _dt.strptime(sat_iso.strip(), "%Y-%m-%d")
            notlar.append(f"SAT (verilen): {sat_dt.strftime('%d.%m.%Y')}")
    except Exception:
        notlar.append("SAT format hatali (YYYY-MM-DD bekleniyor).")
    if usg_hafta and usg_tarih_iso:
        try:
            uhf = float(str(usg_hafta).replace(",", "."))
            ud = _dt.strptime(usg_tarih_iso.strip(), "%Y-%m-%d")
            usg_sat = ud - _td(days=int(uhf * 7))
            notlar.append(f"USG (verilen) {ud.strftime('%d.%m.%Y')} = "
                          f"{uhf:.1f} hf -> hesaplanan SAT: {usg_sat.strftime('%d.%m.%Y')}")
            if not sat_dt:
                sat_dt = usg_sat
                notlar.append("SAT verilmedi — USG'den hesaplanan SAT kullaniliyor.")
            else:
                fark_gun = abs((sat_dt - usg_sat).days)
                if fark_gun > 7:
                    notlar.append(f"ONEMLI: SAT ile USG-SAT {fark_gun} gun farkli "
                                  "(>7) -> ACOG 1. tri USG'yi tercih et; SAT revize ediyorum.")
                    sat_dt = usg_sat
                else:
                    notlar.append(f"SAT ile USG uyumlu (fark {fark_gun} gun).")
        except Exception as ex:
            notlar.append(f"USG hesabi yapilamadi: {ex}")
    if not sat_dt:
        return None, notlar + ["SAT veya USG haftasi+tarihi gerekli."]
    etd = sat_dt + _td(days=280)
    bugun = _dt.now()
    bugun_gun = (bugun - sat_dt).days
    aktif_hf = bugun_gun // 7 + 1 if bugun_gun >= 0 else 0
    aktif_gun = bugun_gun % 7 if bugun_gun >= 0 else 0
    notlar.append(f"ETD (Naegele 280 gun): {etd.strftime('%d.%m.%Y')}")
    if bugun_gun >= 0:
        notlar.append(f"Su anki hafta: {aktif_hf} hf {aktif_gun} gun")
    items = []
    for hf in range(4, 43):
        baslangic = sat_dt + _td(weeks=hf-1)
        bitis = sat_dt + _td(weeks=hf, days=-1)
        gelisim = _GEBELIK_HAFTA_GELISIM.get(hf, {})
        is_aktif = (aktif_hf == hf)
        is_gecmis = (aktif_hf > hf and aktif_hf > 0)
        items.append({
            "hf": hf,
            "baslangic": baslangic,
            "bitis": bitis,
            "boy": gelisim.get("boy", "—"),
            "fetus": gelisim.get("fetus", "—"),
            "anne": gelisim.get("anne", "—"),
            "tetkik": gelisim.get("tetkik", "—"),
            "is_aktif": is_aktif,
            "is_gecmis": is_gecmis,
        })
    onemli_tarihler = []
    for hf, etiket in [
        (8, "1. Vizit + bazal lab"),
        (12, "1. trimester ikili tarama (NT+PAPP-A)"),
        (13, "FMF preeklampsi tarama (son hafta 13+6)"),
        (16, "Maternal serum (uctest/dortlu)"),
        (20, "DETAYLI ANOMALI USG"),
        (24, "75g OGTT (24-28 hf)"),
        (28, "Anti-D 28. hf + TdaP + CBC"),
        (32, "USG buyume + plasenta"),
        (35, "GBS kultur (35-37 hf)"),
        (37, "Term basi"),
        (40, "ETD"),
        (41, "Postdate -> indüksiyon"),
    ]:
        tarih = sat_dt + _td(weeks=hf-1)
        onemli_tarihler.append({"hf": hf, "tarih": tarih, "etiket": etiket})
    return {
        "sat": sat_dt,
        "etd": etd,
        "aktif_hf": aktif_hf,
        "aktif_gun": aktif_gun,
        "items": items,
        "onemli": onemli_tarihler,
    }, notlar


@app.route("/gebelik-plani", methods=["GET", "POST"])
@app.route("/gebelik-takvim", methods=["GET", "POST"])
@app.route("/hasta-gebelik-plan", methods=["GET", "POST"])
@permission_required("view_command_center")
def gebelik_plan_hasta():
    """D127: Hastaya ozel kisisel gebelik takip plani — SAT/USG bazli 40 hf."""
    sat = (request.values.get("sat") or "").strip()
    usg_hf = (request.values.get("usg_hafta") or "").strip()
    usg_t = (request.values.get("usg_tarih") or "").strip()
    hasta_adi = (request.values.get("hasta_adi") or "").strip()

    plan, notlar = _gebelik_plan_olustur(sat, usg_hf, usg_t) if (sat or (usg_hf and usg_t)) else (None, [])

    sonuc_html = ""
    if plan:
        # Aktif hafta vurgu kart
        aktif = plan["aktif_hf"]
        sonuc_html += f"""
        <div class="card mb-3 border-primary border-2">
          <div class="card-header bg-primary text-white">
            <b>{sh(hasta_adi or 'Hasta')}</b> — Su anki hafta:
            <span class="badge bg-warning text-dark fs-5">{aktif} hf {plan['aktif_gun']} gun</span>
          </div>
          <div class="card-body">
            <div class="row g-2 small">
              <div class="col-md-4"><b>SAT:</b> {plan['sat'].strftime('%d.%m.%Y (%a)')}</div>
              <div class="col-md-4"><b>ETD:</b> {plan['etd'].strftime('%d.%m.%Y (%a)')}</div>
              <div class="col-md-4"><b>Trimester:</b> {1 if aktif < 14 else 2 if aktif < 28 else 3}</div>
            </div>
          </div>
        </div>"""

        # Onemli tarihler ozet kart
        onemli_html = "<div class='row g-2'>"
        for o in plan["onemli"]:
            past = (o["tarih"] < _dt_today()) if "_dt_today" in dir() else False
            try:
                from datetime import datetime as _dt
                past = o["tarih"] < _dt.now()
            except Exception:
                past = False
            cls = "is-ok" if past else "is-warn"
            onemli_html += f"""
            <div class="col-md-4 col-lg-3">
              <div class="yk-vp-pcard {cls}" style="margin-bottom:0;">
                <div class="pcard-title small">{sh(o['etiket'])}</div>
                <div class="pcard-body small">
                  <b>{o['hf']}. hf</b> — {o['tarih'].strftime('%d.%m.%Y')}
                </div>
              </div>
            </div>"""
        onemli_html += "</div>"
        sonuc_html += f"""
        <h5 class="mt-3 mb-2"><i class="bi bi-flag-fill"></i> Onemli Tarihler</h5>
        {onemli_html}"""

        # 40 hafta detay tablo
        rows = ""
        for it in plan["items"]:
            cls = "table-warning" if it["is_aktif"] else ("table-light" if it["is_gecmis"] else "")
            tetkik_badge = ""
            if it["tetkik"] and it["tetkik"] != "—":
                tetkik_badge = f"<span class='badge bg-info-subtle text-primary'>{sh(it['tetkik'])}</span>"
            rows += f"""
            <tr class="{cls}">
              <td><b>{it['hf']}</b><br><small class="text-muted">{it['baslangic'].strftime('%d.%m')}-{it['bitis'].strftime('%d.%m.%Y')}</small></td>
              <td>{sh(it['boy'])}</td>
              <td>{sh(it['fetus'])}</td>
              <td>{sh(it['anne'])}</td>
              <td>{tetkik_badge}</td>
            </tr>"""
        sonuc_html += f"""
        <h5 class="mt-4 mb-2"><i class="bi bi-calendar-week"></i> Kisisel 40 Haftalik Takvim</h5>
        <div class="table-responsive">
        <table class="table table-bordered table-sm">
          <thead><tr>
            <th style="width:90px">Hafta</th><th>Bebek Boyu</th><th>Bebekte Gelisim</th>
            <th>Annede Olan</th><th>Tetkik / Vizit</th>
          </tr></thead>
          <tbody>{rows}</tbody>
        </table></div>

        <div class="alert alert-info small mt-3">
          <b>Hasta icin not:</b> Bu takvim genel bilgilendirme amaclidir; sizin gebeliginiz
          benzersizdir. Doktor kontrol takviminizi her zaman onceleyin. Asagidaki tarihler
          {plan['sat'].strftime('%d.%m.%Y')} SAT'a gore hesaplandi.
        </div>"""

    notlar_html = ""
    if notlar:
        notlar_html = "<div class='alert alert-secondary small'><b>Hesap notlari:</b><ul class='mb-0'>" + \
            "".join(f"<li>{sh(n)}</li>" for n in notlar) + "</ul></div>"

    content = f"""
    <div class="container-fluid py-3 yk-no-print-margin">
      <div class="d-flex align-items-center mb-3 flex-wrap gap-2 yk-no-print">
        <h2 class="mb-0"><i class="bi bi-calendar-heart"></i> Kisisel Gebelik Takip Plani</h2>
        <span class="badge bg-success">D127 HASTA REHBER</span>
        <button onclick="window.print()" class="btn btn-outline-secondary btn-sm">
          <i class="bi bi-printer"></i> Yazdir / PDF
        </button>
        <a href="/akilli-dialog?prefill=gebelik takip plani" class="btn btn-outline-primary btn-sm ms-auto">
          <i class="bi bi-chat-dots"></i> Alex'e sor
        </a>
      </div>
      <p class="text-muted small mb-3 yk-no-print">
        Hastanin SAT'i (oncelikli) veya USG haftasi + tarihine gore 40 haftalik
        kisisel gebelik takvimi. Her hafta bebek boyutu/gelisimi + anne degisimi +
        yapilacak tetkikler. ETD Naegele kuralina gore (SAT + 280 gun).
      </p>

      <form method="POST" action="/gebelik-plani" class="card mb-3 yk-no-print">
        <div class="card-header bg-light"><b>Hasta Bilgileri</b></div>
        <div class="card-body">
          <div class="row g-3">
            <div class="col-md-3"><label class="form-label">Hasta Adi (opsiyonel)</label>
              <input type="text" class="form-control" name="hasta_adi" value="{sh(hasta_adi)}"></div>
            <div class="col-md-3"><label class="form-label">SAT (Son Adet Tarihi)</label>
              <input type="date" class="form-control" name="sat" value="{sh(sat)}">
              <small class="text-muted">Birinci tercih</small></div>
            <div class="col-md-3"><label class="form-label">USG Haftasi (alternatif)</label>
              <input type="text" class="form-control" name="usg_hafta" value="{sh(usg_hf)}" placeholder="orn. 12.5" inputmode="decimal"></div>
            <div class="col-md-3"><label class="form-label">USG Tarihi</label>
              <input type="date" class="form-control" name="usg_tarih" value="{sh(usg_t)}"></div>
          </div>
          <div class="mt-3">
            <button type="submit" class="btn btn-primary"><i class="bi bi-calculator"></i> Plan Olustur</button>
          </div>
        </div>
      </form>

      {notlar_html}
      {sonuc_html or '<div class="alert alert-info">SAT (oncelikli) gir veya USG haftasi+USG tarihi gir, '
                       '<b>Plan Olustur</b>. Hasta icin 40 haftalik kisisel takvim cikar.</div>'}
    </div>
    <style>
    @media print {{
      .yk-no-print {{ display: none !important; }}
      body {{ background: #fff !important; }}
      .table {{ font-size: 11px !important; }}
      .yk-vp-pcard {{ page-break-inside: avoid; }}
    }}
    </style>
    """
    return render(content, title="Gebelik Takip Plani")


