def _tedavi_doz_kilo_bazli(jenerik, kilo_kg):
    """Kilo-bazli ilac dozu hesapla (gentamisin, vankomisin vs)."""
    try:
        kg = float(str(kilo_kg).replace(",", "."))
    except Exception:
        return ""
    j = (jenerik or "").lower()
    if "gentamisin" in j:
        return f"{round(kg * 5)} mg IV q24h (5 mg/kg) veya {round(kg * 1.5)} mg q8h (1.5 mg/kg)"
    if "vankomisin" in j:
        return f"{round(kg * 20)} mg IV q8h (20 mg/kg)"
    if "amikasin" in j:
        return f"{round(kg * 15)} mg IV q24h (15 mg/kg)"
    if "enoksaparin" in j:
        prof = round(kg * 0.5)
        ted = round(kg * 1.0)
        return f"profilaksi 40 mg/gun veya {prof} mg/gun (BMI gore); tedavi {ted} mg BID"
    if "klindamisin" in j:
        return f"600-900 mg IV q8h (yetiskin) veya {round(kg * 8)} mg q8h (8-10 mg/kg)"
    if "insulin" in j:
        return f"toplam {round(kg * 0.7)} IU/gun (1. tri) -> {round(kg * 0.9)} IU/gun (3. tri)"
    return ""


