@app.route("/anormal-uterin-kanama", methods=["GET", "POST"])
@app.route("/menometroraji", methods=["GET", "POST"])
@app.route("/aub", methods=["GET", "POST"])
@permission_required("view_command_center")
def aub_destek():
    """D124: Anormal uterin kanama (AUB) — FIGO PALM-COEIN siniflama + tedavi."""
    f = lambda k: request.values.get(k, "").strip()
    selected_acute = request.values.getlist("acute")
    cause = f("cause")
    sonuc_html = ""
    if cause and cause in _AUB_CAUSES:
        item = _AUB_CAUSES[cause]
        sonuc_html += f"""
        <div class="yk-vp-pcard is-warn mt-3">
          <div class="pcard-title">[{sh(item['code'])}] {sh(item['label'])}</div>
          <div class="pcard-body">
            <div class='small'><b>Klinik:</b> {sh(item['klinik'])}</div>
            <div class='small mt-2'><b>Tedavi:</b> {sh(item['tedavi'])}</div>
          </div>
        </div>"""
    if selected_acute:
        for k in selected_acute:
            it = _AUB_ACUTE_REGIMENS.get(k)
            if not it:
                continue
            t_html = "<ul class='small mb-0'>" + "".join(f"<li>{sh(x)}</li>" for x in it['tedavi']) + "</ul>"
            u_html = "<ul class='small mb-0 text-warning'>" + "".join(f"<li>{sh(x)}</li>" for x in it['uyari']) + "</ul>"
            sonuc_html += f"""
            <div class="yk-vp-pcard is-danger mt-3">
              <div class="pcard-title">{sh(it['label'])}</div>
              <div class="pcard-body">
                {t_html}
                <div class='mt-2'><b>Uyarilar:</b>{u_html}</div>
              </div>
            </div>"""
    cause_options = ""
    for k, v in _AUB_CAUSES.items():
        sel = "selected" if cause == k else ""
        cause_options += f'<option value="{sh(k)}" {sel}>[{sh(v["code"])}] {sh(v["label"])}</option>'
    acute_checks = ""
    for k, v in _AUB_ACUTE_REGIMENS.items():
        chk = "checked" if k in selected_acute else ""
        acute_checks += f"""
        <div class="form-check">
          <input class="form-check-input" type="checkbox" name="acute" value="{sh(k)}" id="ac_{sh(k)}" {chk}>
          <label class="form-check-label" for="ac_{sh(k)}"><b>{sh(v['label'])}</b></label>
        </div>"""
    cause_summary = ""
    for k, v in _AUB_CAUSES.items():
        cause_summary += f"""
        <div class="col-md-6 mb-3">
          <div class="card h-100">
            <div class="card-header bg-light"><b>[{sh(v['code'])}] {sh(v['label'])}</b></div>
            <div class="card-body small">
              <div><b>Klinik:</b> {sh(v['klinik'])}</div>
              <div class='mt-2'><b>Tedavi:</b> {sh(v['tedavi'])}</div>
            </div>
          </div>
        </div>"""
    content = f"""
    <div class="container-fluid py-3">
      <div class="d-flex align-items-center mb-3 flex-wrap gap-2">
        <h2 class="mb-0"><i class="bi bi-droplet"></i> Anormal Uterin Kanama (AUB)</h2>
        <span class="badge bg-danger">D124 PALM-COEIN</span>
        <a href="/endometrial-hiperplazi" class="btn btn-outline-secondary btn-sm"><i class="bi bi-arrow-right-circle"></i> Hiperplazi</a>
        <a href="/akilli-dialog?prefill=AUB FIGO yonetim" class="btn btn-outline-primary btn-sm ms-auto">
          <i class="bi bi-chat-dots"></i> Alex'e sor
        </a>
      </div>
      <p class="text-muted small mb-3">
        FIGO PALM-COEIN siniflama + akut/kronik yonetim. Menometroraji,
        ara kanama, postkoital kanama, agir kanami yonetim algoritmasi.
      </p>
      <form method="POST" action="/anormal-uterin-kanama" class="card mb-3">
        <div class="card-header bg-light"><b>Tani / Akut Yonetim</b></div>
        <div class="card-body">
          <div class="row g-3">
            <div class="col-md-5">
              <label class="form-label">FIGO PALM-COEIN sebep</label>
              <select class="form-select" name="cause">
                <option value="">— sec —</option>
                {cause_options}
              </select>
            </div>
            <div class="col-md-7">
              <label class="form-label">Akut yonetim secenegi (birden fazla)</label>
              {acute_checks}
            </div>
          </div>
          <div class="mt-3"><button type="submit" class="btn btn-primary"><i class="bi bi-check2-circle"></i> Plan Hazirla</button></div>
        </div>
      </form>
      {sonuc_html or '<div class="alert alert-info">FIGO PALM-COEIN sebebi sec ve/veya akut '
                       'yonetim secenegi(ler)i isaretle, <b>Plan Hazirla</b> butonuna bas.</div>'}
      <h4 class="mt-4 mb-3"><i class="bi bi-list-check"></i> FIGO PALM-COEIN Atlasi</h4>
      <div class="row">{cause_summary}</div>
    </div>
    """
    return render(content, title="Anormal Uterin Kanama (AUB)")


