@app.route("/api/alex/qa")
@permission_required("view_command_center")
def api_alex_qa():
    """D250: Sales-ready Alex module contract check without external AI calls."""
    from datetime import datetime
    required_routes = [
        "/ses-ve-alex",
        "/akilli-dialog",
        "/sessiz-alex",
        "/sesli-recete",
        "/yz-ses-cevir",
        "/ses-profilleri",
        "/mikrofon-tani",
        "/yz-telefon-diyalog",
        "/api/akilli-dialog/status",
        "/api/akilli-dialog/soyle",
        "/api/sesli-komut/uygula",
        "/api/phone/live-transcribe",
        "/api/phone/live-native-record",
    ]
    route_rules = {str(rule.rule) for rule in app.url_map.iter_rules()}
    route_status = [
        {
            "route": route,
            "ok": route in route_rules,
        }
        for route in required_routes
    ]
    required_dom_ids = [
        "ykVoiceAgent",
        "ykVoiceQuickText",
        "ykVoiceQuickSend",
        "ykVoiceQuickMic",
        "ykVoiceQuickClose",
        "ykVoiceText",
        "ykVoiceSend",
        "ykVoiceAlex",
        "ykVoiceMic",
        "ykVoiceStop",
        "ykVoiceHideBar",
        "ykVoiceSelfTest",
        "ykVoiceStatus",
    ]
    required_globals = [
        "window.ykVoiceAgent.open",
        "window.ykVoiceAgent.showSilent",
        "window.ykVoiceAgent.showVoice",
        "window.ykVoiceAgent.hideBar",
        "window.ykVoiceAgent.send",
        "window.ykVoiceAgent.selfTest",
        "window.ykCloseAlex",
        "window.ykEmergencyVoiceSend",
    ]
    ok = all(item["ok"] for item in route_status)
    return jsonify({
        "ok": ok,
        "module": "alex-voice-communication",
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "routes": route_status,
        "ui_contract": {
            "required_dom_ids": required_dom_ids,
            "required_globals": required_globals,
            "bar_default": "hidden",
            "typed_message_policy": "quickbar text is sent as written; voice/Alex starts only by explicit voice buttons",
        },
        "microphone_contract": {
            "browser": "localhost or HTTPS required for web microphone",
            "native_record_route": "/api/phone/live-native-record",
            "transcribe_route": "/api/phone/live-transcribe",
        },
        "message": (
            "Alex iletisim sozlesmesi hazir."
            if ok else "Alex route sozlesmesinde eksik var."
        ),
    })


# B432: Windows komut yetkisi - doktor onayli uygulama/klasor/URL acma.
# Doktor 'akilli sohbette windows yonetebilme istiyorum codex tarzi' istedi.
# Ham shell exec yok; klinik uygulamada tek tikla app/klasor/URL acma var.
_B432_APP_WHITELIST = dict(_SMART_DIALOG_WINDOWS_APP_WHITELIST)


@app.route("/api/akilli-dialog/win-exec", methods=["POST"])
@permission_required("manage_command_center")
def api_smart_dialog_win_exec():
    """B432: Akilli Dialog'tan Windows uygulama/klasor/URL ac.

    open_app (notepad/calc/explorer/...), open_folder (path),
    open_url (https?://). Doktor onay zorunlu (frontend confirmed=1 yollar).
    """
    data = request.get_json(silent=True) or {}
    confirmed = bool(data.get("confirmed"))
    if not confirmed:
        return jsonify({"ok": False, "error": "onay gerekli"}), 400

    if os.name != "nt":
        return jsonify({"ok": False, "error": "sadece Windows"}), 400
    normalized = _smart_dialog_normalize_action(data) or {}
    command = str(normalized.get("command") or "").strip().lower()
    if not command:
        return jsonify({
            "ok": False,
            "error": "Komut gecersiz veya desteklenmiyor.",
        }), 400

    try:
        if command == "open_app":
            app_key = str(normalized.get("app") or "").strip().lower().replace(" ", "_")
            target = _B432_APP_WHITELIST.get(app_key)
            if not target:
                return jsonify({
                    "ok": False,
                    "error": f"Desteklenmeyen uygulama kisayolu: {app_key}. "
                             f"Mevcut kisayollar: {', '.join(sorted(set(_B432_APP_WHITELIST.keys())))}",
                }), 400
            try:
                if target.startswith("ms-settings:"):
                    os.startfile(target)
                else:
                    import subprocess
                    subprocess.Popen([target], shell=False)
                return jsonify({"ok": True, "message": f"Acildi: {target}"})
            except Exception as ex:
                return jsonify({"ok": False, "error": f"Acilamadi: {ex}"}), 500

        elif command == "open_folder":
            path = str(normalized.get("path") or "").strip().strip('"').strip("'")
            if not path or not os.path.isdir(path):
                return jsonify({"ok": False, "error": f"Klasor yok: {path}"}), 400
            try:
                os.startfile(path)
                return jsonify({"ok": True, "message": f"Klasor acildi: {path}"})
            except Exception as ex:
                return jsonify({"ok": False, "error": str(ex)}), 500

        elif command == "open_url":
            url = str(normalized.get("url") or "").strip()
            if not (url.startswith("http://") or url.startswith("https://")):
                return jsonify({"ok": False, "error": "URL http(s):// ile baslamali"}), 400
            try:
                import webbrowser
                webbrowser.open(url, new=2)
                return jsonify({"ok": True, "message": f"URL acildi: {url}"})
            except Exception as ex:
                return jsonify({"ok": False, "error": str(ex)}), 500

        elif command == "list_apps":
            return jsonify({
                "ok": True,
                "apps": sorted(set(_B432_APP_WHITELIST.keys())),
            })

        else:
            return jsonify({
                "ok": False,
                "error": f"Desteklenmeyen komut: {command}. "
                         f"Mevcut: open_app, open_folder, open_url, list_apps",
            }), 400
    except Exception as ex:
        return jsonify({"ok": False, "error": f"Exec hatasi: {ex}"}), 500


