@permission_required("edit_patient")
def api_patient_data_suggestion(patient_key):
    data = request.get_json(silent=True) or request.form
    field_key = str(data.get("field") or data.get("field_key") or "").strip()
    value = data.get("value") if hasattr(data, "get") else ""
    result = _patient_data_suggest_value(
        patient_key, field_key, value,
        source=str(data.get("source") or "ajan").strip() or "ajan",
        source_ref=str(data.get("source_ref") or data.get("ref") or "").strip(),
        confidence=float(data.get("confidence") or 0.6),
        auto_apply_empty=str(data.get("auto_apply_empty", "1")).lower()
        not in {"0", "false", "hayir", "hayÄ±r", "no"})
    if result.get("status") == "unsupported_field":
        return jsonify(result), 400
    return jsonify(result)


