# ====================================================================
# Kamera / NVR reverse-proxy
# Dis erisimde kamera/NVR portu acilmaz; browser sadece YazKlinik
# origin'ine gelir. Server ic agdaki NVR'a baglanip cevabi ayni 5443
# hattindan yayinlar.
# ====================================================================

_NVR_PROXY_HOP_HEADERS = {
    "connection", "keep-alive", "proxy-authenticate",
    "proxy-authorization", "te", "trailers", "transfer-encoding",
    "upgrade", "content-encoding", "content-length",
    "x-frame-options", "content-security-policy",
    "www-authenticate", "set-cookie",
}

_NVR_PROXY_METHODS = ["GET", "HEAD", "POST", "PUT", "DELETE", "OPTIONS"]


def _nvr_normalize_base_url_input(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    if not re.match(r"^https?://", raw, re.I):
        raw = "http://" + raw
    try:
        parts = urlsplit(raw)
        if not parts.scheme or not parts.netloc:
            return raw.rstrip("/")
        host = parts.hostname or ""
        port = parts.port
        remove_port = False
        if port and port == _yk_https_port():
            try:
                import ipaddress
                ip = ipaddress.ip_address(host)
                remove_port = bool(ip.is_private or ip.is_loopback)
            except Exception:
                remove_port = host.lower() in _yk_local_host_tokens()
        netloc = host
        if ":" in netloc and not netloc.startswith("["):
            netloc = f"[{netloc}]"
        if port and not remove_port:
            netloc = f"{netloc}:{port}"
        path = parts.path.rstrip("/")
        query = ("?" + parts.query) if parts.query else ""
        return f"{parts.scheme}://{netloc}{path}{query}".rstrip("/")
    except Exception:
        return raw.rstrip("/")


def _nvr_request_with_auth(req, method, target, cfg, **kwargs):
    auths = [None]
    username = str((cfg or {}).get("username") or "").strip()
    if username:
        try:
            from requests.auth import HTTPBasicAuth, HTTPDigestAuth
            password = str((cfg or {}).get("password") or "")
            auths = [
                HTTPBasicAuth(username, password),
                HTTPDigestAuth(username, password),
                None,
            ]
        except Exception:
            auths = [(username, str((cfg or {}).get("password") or "")), None]
    last_resp = None
    for auth in auths:
        if last_resp is not None:
            try:
                last_resp.close()
            except Exception:
                pass
        resp = req.request(method, target, auth=auth, **kwargs)
        last_resp = resp
        if resp.status_code != 401:
            return resp
        challenge = str(resp.headers.get("WWW-Authenticate") or "").lower()
        if "digest" not in challenge and auth is not None:
            continue
        if auth is None:
            return resp
    return last_resp


def _nvr_device_fallback():
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            row = con.execute(
                "SELECT * FROM integration_devices "
                "WHERE enabled=1 AND device_type IN ('camera','other') "
                "ORDER BY device_type, id LIMIT 1").fetchone()
    except Exception:
        row = None
    if not row:
        return {}
    proto = str(row.get("protocol") or "").strip().lower()
    if proto not in {"http", "https"}:
        return {}
    host = str(row.get("host") or "").strip()
    if not host:
        return {}
    port = str(row.get("port") or "").strip()
    netloc = host if not port else f"{host}:{port}"
    return {
        "base_url": f"{proto}://{netloc}",
        "username": str(row.get("username") or "").strip(),
        "password": str(row.get("encrypted_secret") or "").strip(),
        "device_name": str(row.get("name") or "").strip(),
    }


def _nvr_config():
    fallback = _nvr_device_fallback()
    base_url = (
        os.environ.get("YAZKLINIK_NVR_BASE_URL")
        or _db_get_setting("nvr_base_url", "")
        or _db_get_setting("sysparam_nvr_base_url", "")
        or fallback.get("base_url", "")
    )
    username = (
        os.environ.get("YAZKLINIK_NVR_USER")
        or _db_get_setting("nvr_username", "")
        or _db_get_setting("sysparam_nvr_username", "")
        or fallback.get("username", "")
    )
    password = (
        os.environ.get("YAZKLINIK_NVR_PASS")
        or _db_get_setting("nvr_password", "")
        or _db_get_setting("sysparam_nvr_password", "")
        or fallback.get("password", "")
    )
    panel_path = _db_get_setting("nvr_panel_path", "/") or "/"
    snapshot_path = _db_get_setting("nvr_snapshot_path", "")
    stream_path = _db_get_setting("nvr_stream_path", "")
    name = (_db_get_setting("nvr_display_name", "")
            or fallback.get("device_name", "")
            or "Kamera / NVR")
    base_url = str(base_url or "").strip().rstrip("/")
    if base_url and not re.match(r"^https?://", base_url, re.I):
        base_url = "http://" + base_url
    base_url = _nvr_normalize_base_url_input(base_url)
    # D300: kanal sayisi (varsayilan 20 - 20 kanalli NVR icin)
    try:
        channel_count = int(
            _db_get_setting("nvr_channel_count", "")
            or os.environ.get("YAZKLINIK_NVR_CHANNEL_COUNT", "")
            or "20")
    except Exception:
        channel_count = 20
    channel_count = max(1, min(64, channel_count))
    # D300: snapshot URL pattern (Hikvision ISAPI default).
    # {N} yerine kanal numarasi konur.
    snapshot_pattern = (
        _db_get_setting("nvr_snapshot_pattern", "")
        or "/ISAPI/Streaming/channels/{N}01/picture")
    return {
        "base_url": base_url,
        "username": str(username or "").strip(),
        "password": str(password or "").strip(),
        "panel_path": str(panel_path or "/").strip() or "/",
        "snapshot_path": str(snapshot_path or "").strip(),
        "stream_path": str(stream_path or "").strip(),
        "name": str(name or "Kamera / NVR").strip(),
        "configured": bool(base_url),
        "channel_count": channel_count,
        "snapshot_pattern": snapshot_pattern,
    }


def _nvr_proxy_local_path(path=""):
    raw = str(path or "/").strip() or "/"
    if raw.startswith("http://") or raw.startswith("https://"):
        parts = urlsplit(raw)
        raw = parts.path or "/"
        if parts.query:
            raw += "?" + parts.query
    if not raw.startswith("/"):
        raw = "/" + raw
    return "/kamera/nvr-proxy" + raw


def _nvr_target_url(path=""):
    cfg = _nvr_config()
    base = cfg.get("base_url", "")
    if not base:
        return "", cfg, "NVR ic adresi ayarli degil."
    parts = urlsplit(base)
    if parts.scheme not in {"http", "https"} or not parts.netloc:
        return "", cfg, "NVR adresi http:// veya https:// ile baslamali."
    sub = str(path or "").lstrip("/")
    base_path = (parts.path or "").rstrip("/")
    target_path = (base_path + "/" + sub).replace("//", "/")
    if not target_path:
        target_path = "/"
    query_bits = []
    if parts.query:
        query_bits.append(parts.query)
    req_qs = request.query_string.decode("utf-8", errors="ignore")
    if req_qs:
        query_bits.append(req_qs)
    query = "&".join(q for q in query_bits if q)
    target = f"{parts.scheme}://{parts.netloc}{target_path}"
    if query:
        target += "?" + query
    return target, cfg, ""


def _nvr_rewrite_html(text, cfg):
    local_prefix = "/kamera/nvr-proxy"
    base = str(cfg.get("base_url") or "").rstrip("/")
    nvr_prefixes = (
        "doc", "ISAPI", "SDK", "PSIA", "webLib", "cgi-bin",
        "js", "css", "lib", "images", "image", "static")
    if base:
        text = text.replace(base + "/", local_prefix + "/")
        text = text.replace(base, local_prefix)
    for attr in ("href", "src", "action", "poster"):
        text = re.sub(
            rf'({attr}\s*=\s*["\'])/(?!/|kamera/nvr-proxy/)',
            rf'\1{local_prefix}/',
            text,
            flags=re.I,
        )
    text = re.sub(r'url\(\s*/(?!/|kamera/nvr-proxy/)',
                  f"url({local_prefix}/", text, flags=re.I)
    text = re.sub(
        r'((?:fetch|open)\s*\(\s*["\'])/(?!/|kamera/nvr-proxy/)',
        rf'\1{local_prefix}/',
        text,
        flags=re.I,
    )
    text = re.sub(
        r'(((?:window\.|document\.)?location(?:\.href)?\s*=\s*["\']))/(?!/|kamera/nvr-proxy/)',
        rf'\1{local_prefix}/',
        text,
        flags=re.I,
    )
    text = re.sub(
        r'(((?:window\.)?location\.(?:replace|assign)\s*\(\s*["\']))/(?!/|kamera/nvr-proxy/)',
        rf'\1{local_prefix}/',
        text,
        flags=re.I,
    )
    prefix_pattern = "|".join(re.escape(p) for p in nvr_prefixes)
    text = re.sub(
        rf'(["\'])/(?!/|kamera/nvr-proxy/)((?:{prefix_pattern})(?:/[^"\']*)?)\1',
        rf'\1{local_prefix}/\2\1',
        text,
        flags=re.I,
    )
    if "<head" in text.lower() and "yk-nvr-proxy-base" not in text:
        text = re.sub(
            r"(<head[^>]*>)",
            r'\1<base id="yk-nvr-proxy-base" href="/kamera/nvr-proxy/">',
            text,
            count=1,
            flags=re.I,
        )
    return text


def _nvr_proxy_request(path=""):
    import requests as _req
    from flask import Response

    try:
        _req.packages.urllib3.disable_warnings()
    except Exception:
        pass

    if request.method == "OPTIONS":
        return ("", 204)
    if request.method not in {"GET", "HEAD", "POST", "PUT", "DELETE"}:
        return jsonify({"ok": False, "error": "Metod desteklenmiyor"}), 405
    if request.method not in {"GET", "HEAD"} and session.get("role") != "doktor":
        return jsonify({"ok": False, "error": "Sadece doktor"}), 403

    target, cfg, err = _nvr_target_url(path)
    if err:
        return jsonify({"ok": False, "error": err}), 503

    forward_headers = {}
    for h in ("Accept", "Accept-Language", "If-Modified-Since",
              "If-None-Match", "Range", "Origin", "Content-Type",
              "User-Agent"):
        v = request.headers.get(h)
        if v:
            forward_headers[h] = v

    try:
        resp = _nvr_request_with_auth(
            _req,
            request.method,
            target,
            cfg,
            headers=forward_headers,
            data=request.get_data() if request.method not in {"GET", "HEAD"} else None,
            stream=True,
            allow_redirects=False,
            verify=False,
            timeout=30,
        )
    except _req.RequestException as ex:
        return jsonify({"ok": False, "error": f"NVR baglanti: {ex}"}), 502

    if resp.status_code in (301, 302, 303, 307, 308):
        loc = resp.headers.get("Location") or ""
        parsed = urlsplit(loc)
        if parsed.scheme in {"http", "https"}:
            base_parts = urlsplit(cfg.get("base_url") or "")
            if parsed.netloc and parsed.netloc != base_parts.netloc:
                return jsonify({
                    "ok": False,
                    "error": "NVR farkli host'a yonlendirdi; guvenlik icin engellendi.",
                    "location": loc,
                }), 502
        local = parsed.path or loc or "/"
        if parsed.query:
            local += "?" + parsed.query
        return redirect(_nvr_proxy_local_path(local), code=resp.status_code)

    out_headers = []
    for key, value in resp.headers.items():
        if key.lower() in _NVR_PROXY_HOP_HEADERS:
            continue
        out_headers.append((key, value))

    content_type = str(resp.headers.get("Content-Type") or "").lower()
    rewrite_text_response = any(t in content_type for t in (
        "text/html", "javascript", "text/css", "application/json"))
    if rewrite_text_response:
        try:
            text = resp.text
            text = _nvr_rewrite_html(text, cfg)
            out = Response(
                text,
                status=resp.status_code,
                headers=out_headers,
                mimetype=resp.headers.get("Content-Type", "text/html").split(";", 1)[0],
            )
            out.headers["X-YazKlinik-NVR-Proxy"] = "1"
            return out
        finally:
            try:
                resp.close()
            except Exception:
                pass

    def _stream():
        try:
            for chunk in resp.iter_content(chunk_size=64 * 1024):
                if chunk:
                    yield chunk
        finally:
            try:
                resp.close()
            except Exception:
                pass

    out = Response(_stream(), status=resp.status_code, headers=out_headers)
    out.headers["X-YazKlinik-NVR-Proxy"] = "1"
    return out


def _nvr_absolute_proxy_factory(prefix):
    def _handler(path=""):
        full_path = f"{prefix}/{path}" if path else prefix
        return _nvr_proxy_request(full_path)
    return _handler


for _yk_nvr_abs_prefix in ("doc", "ISAPI", "SDK", "PSIA", "webLib"):
    _yk_nvr_endpoint = "camera_nvr_abs_" + _yk_nvr_abs_prefix.lower()
    _yk_nvr_handler = login_required(_nvr_absolute_proxy_factory(_yk_nvr_abs_prefix))
    _yk_nvr_handler.__name__ = _yk_nvr_endpoint
    app.add_url_rule(
        "/" + _yk_nvr_abs_prefix,
        defaults={"path": ""},
        view_func=_yk_nvr_handler,
        methods=_NVR_PROXY_METHODS,
        endpoint=_yk_nvr_endpoint + "_root")
    app.add_url_rule(
        "/" + _yk_nvr_abs_prefix + "/<path:path>",
        view_func=_yk_nvr_handler,
        methods=_NVR_PROXY_METHODS,
        endpoint=_yk_nvr_endpoint)


def _nvr_status_payload(timeout=5):
    import requests as _req

    try:
        _req.packages.urllib3.disable_warnings()
    except Exception:
        pass

    target, cfg, err = _nvr_target_url("")
    safe_cfg = {
        "name": cfg.get("name", "Kamera / NVR"),
        "base_url": cfg.get("base_url", ""),
        "panel_path": cfg.get("panel_path", "/"),
        "snapshot_path": cfg.get("snapshot_path", ""),
        "stream_path": cfg.get("stream_path", ""),
        "configured": bool(cfg.get("configured")),
        "has_auth": bool(cfg.get("username")),
    }
    if err:
        return {"ok": False, "configured": False, "error": err, "config": safe_cfg}
    try:
        resp = _nvr_request_with_auth(
            _req,
            "GET",
            target,
            cfg,
            timeout=timeout,
            stream=True,
            verify=False,
            allow_redirects=False,
            headers={"Accept": "text/html,application/json,*/*"},
        )
        auth_probe = {}
        if cfg.get("username") and cfg.get("base_url"):
            probe_url = str(cfg.get("base_url")).rstrip("/") + "/ISAPI/System/deviceInfo"
            try:
                probe = _nvr_request_with_auth(
                    _req,
                    "GET",
                    probe_url,
                    cfg,
                    timeout=timeout,
                    stream=True,
                    verify=False,
                    allow_redirects=False,
                    headers={"Accept": "application/xml,text/xml,*/*"},
                )
                auth_probe = {
                    "url": "/ISAPI/System/deviceInfo",
                    "status_code": probe.status_code,
                    "ok": probe.status_code < 400,
                    "auth": "digest/basic auto",
                }
                try:
                    probe.close()
                except Exception:
                    pass
            except Exception as probe_ex:
                auth_probe = {
                    "url": "/ISAPI/System/deviceInfo",
                    "ok": False,
                    "error": str(probe_ex),
                    "auth": "digest/basic auto",
                }
        try:
            resp.close()
        except Exception:
            pass
        payload = {
            "ok": resp.status_code < 500,
            "configured": True,
            "status_code": resp.status_code,
            "content_type": resp.headers.get("Content-Type", ""),
            "config": safe_cfg,
        }
        if auth_probe:
            payload["auth_probe"] = auth_probe
        return payload
    except _req.RequestException as ex:
        return {
            "ok": False,
            "configured": True,
            "error": str(ex),
            "config": safe_cfg,
        }


