@app.route("/api/web/patient/<patient_key>/overview")
@login_required
def api_web_patient_overview(patient_key):
    try:
        cache_key = f"web_patient_overview_{patient_key}"
        cached, exists, fresh = cache_get_with_state(cache_key)
        if fresh and cached is not None:
            return jsonify({
                "ok": True,
                "html": fix_mojibake_text(cached),
                "cached": True,
            })

        force_sync = str(request.args.get("sync") or "").strip().lower() in {
            "1", "true", "evet", "yes", "force"
        }
        if force_sync:
            html = fix_mojibake_text(_build_patient_overview_html(patient_key))
            return jsonify({"ok": True, "html": html, "cached": False})

        _perf_singleflight_async(
            f"patient_overview:{patient_key}",
            lambda: _build_patient_overview_html(patient_key))

        if exists and cached is not None:
            return jsonify({
                "ok": True,
                "html": fix_mojibake_text(cached),
                "cached": False,
                "stale": True,
                "building": True,
            })

        return jsonify({
            "ok": True,
            "html": _patient_overview_loading_html(patient_key),
            "cached": False,
            "stale": False,
            "building": True,
        })
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


