@app.route("/hasta/<patient_key>/gelis/<visit_key>/dosya/<path:file_name>")
@permission_required("view_files")
def serve_visit_file(patient_key, visit_key, file_name):
    try:
        file_path, kind = _resolve_visit_media_path(patient_key, visit_key, file_name)
        return _send_web_media_file(
            file_path,
            kind=kind,
            download=request.args.get("download") == "1")
    except Exception:
        if _file_kind_for_path(file_name) == "pdf":
            row = _load_archived_pdf_record(
                patient_key=patient_key,
                visit_key=visit_key,
                file_name=file_name)
            if row:
                return _send_archived_pdf_blob(
                    row, download=request.args.get("download") == "1")
        raise
    """Visit iÃ§indeki dosyayÄ± gÃ¶ster (PDF viewer veya image)."""
    # GÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼venlik: path traversal'ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± engelle
    if ".." in file_name or file_name.startswith("/"):
        abort(403)
    root = get_nas_root()
    file_path = root / patient_key / visit_key / file_name
    if not file_path.exists() or not file_path.is_file():
        abort(404)
    # GÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼venlik: NAS root dÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±na ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±kmadÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±mÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±zÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± doÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸rula
    try:
        file_path.resolve().relative_to(root.resolve())
    except ValueError:
        abort(403)
    return _send_web_media_file(
        file_path,
        kind=_file_kind_for_path(file_path),
        download=request.args.get("download") == "1")


@app.route("/hasta/<patient_key>/gelis/<visit_key>/dicom-preview/<path:file_name>")
@permission_required("view_files")
def serve_visit_dicom_preview(patient_key, visit_key, file_name):
    file_path, kind = _resolve_visit_media_path(patient_key, visit_key, file_name)
    if kind != "dicom":
        abort(404)
    return _dicom_preview_response(file_path)


@app.route("/hasta/<patient_key>/dicom-dosya/<path:rel_path>")
@permission_required("view_files")
def serve_patient_dicom_file(patient_key, rel_path):
    file_path = _resolve_patient_relative_media_path(patient_key, rel_path)
    if _patient_explorer_file_kind(file_path) != "dicom":
        abort(404)
    if request.args.get("raw") == "1":
        return _send_web_media_file(
            file_path,
            kind="dicom",
            download=request.args.get("download") == "1")
    return _dicom_preview_response(file_path)


@app.route("/hasta/<patient_key>/medya-dosya/<path:rel_path>")
@permission_required("view_files")
def serve_patient_media_file(patient_key, rel_path):
    try:
        file_path = _resolve_patient_relative_media_path(patient_key, rel_path)
        kind = _file_kind_for_path(file_path)
        if kind not in ("image", "video", "pdf"):
            abort(404)
        return _send_web_media_file(
            file_path,
            kind=kind,
            download=request.args.get("download") == "1")
    except Exception:
        if _file_kind_for_path(rel_path) == "pdf":
            row = _load_archived_pdf_record(
                patient_key=patient_key,
                rel_path=rel_path)
            if row:
                return _send_archived_pdf_blob(
                    row, download=request.args.get("download") == "1")
        raise


@app.route("/hasta/<patient_key>/nas-dosya/<path:rel_path>")
@permission_required("view_files")
def serve_patient_nas_file(patient_key, rel_path):
    _, file_path, _ = _resolve_patient_explorer_path(
        patient_key, rel_path, require_file=True)
    kind = _patient_explorer_file_kind(file_path)
    return _send_web_media_file(
        file_path,
        kind=kind,
        download=(request.args.get("download") == "1" or kind == "other"))


@app.route("/hasta/<patient_key>/dosya-gezgini")
@permission_required("view_files")
def patient_nas_dicom_file_explorer(patient_key):
    source = str(request.args.get("source", "") or "").strip().lower()
