    root_text = safe_html(str(root_path))

    def explorer_url(src, rel="", file_rel=""):
        parts = [f"source={quote(str(src), safe='')}"]
        if rel:
            parts.append(f"rel={quote(str(rel), safe='')}")
        if file_rel:
            parts.append(f"file={quote(str(file_rel), safe='')}")
        return route_base + "?" + "&".join(parts)

