def _find_visit_for_whatsapp(patient_key, visit_key=None):
    """Return (visit_row, folder_path) for a requested or latest visit."""
    def _add_unique_path(items, path):
        try:
            p = Path(path).expanduser()
        except Exception:
            return
        key = _windows_path_key(str(p))
        if key and key not in {item[0] for item in items}:
            items.append((key, p))

    def _candidate_patient_roots():
        roots = []
        _add_unique_path(roots, _patient_root_for_nas(patient_key))
        _add_unique_path(roots, get_nas_root() / str(patient_key))
        try:
            _add_unique_path(roots, Path(get_data_root_dir()) / str(patient_key))
        except Exception:
            pass
        try:
            _add_unique_path(roots, _patient_media_root(patient_key))
            _add_unique_path(roots, get_multimedia_root() / str(patient_key))
        except Exception:
            pass
        return [p for _key, p in roots]

    def _media_files_in_folder(folder, limit=120):
        try:
            return list(_nas_sync_iter_files(
                Path(folder), recursive=True, max_files=limit))
        except Exception:
            return []

    def _disk_visit_row(folder, root, visit_key_value=""):
        folder = Path(folder)
        try:
            key = visit_key_value or _nas_sync_safe_visit_key(folder, root)
        except Exception:
            key = visit_key_value or folder.name or "_KOK_DOSYALAR"
        try:
            mtime = folder.stat().st_mtime
        except Exception:
            mtime = 0
        return {
            "id": None,
            "patient_folder_key": patient_key,
            "visit_key": key,
            "full_path": str(folder),
            "visit_date": _nas_sync_parse_visit_date(folder),
            "folder_mtime": mtime,
        }

    def _find_on_disk():
        wanted = str(visit_key or "").strip()
        wanted_folded = wanted.lower()
        best = None
        for root in _candidate_patient_roots():
            try:
                if not root.exists() or not root.is_dir():
                    continue
            except Exception:
                continue

            direct_candidates = []
            if wanted:
                direct_candidates.append(root / wanted)
                if "__" in wanted:
                    direct_candidates.append(root.joinpath(*wanted.split("__")))
            for folder in direct_candidates:
                try:
                    if folder.exists() and folder.is_dir():
                        files = _media_files_in_folder(folder)
                        if files:
                            latest = max(
                                (f.stat().st_mtime for f in files),
                                default=folder.stat().st_mtime)
                            candidate = (latest, len(files), folder, wanted, root)
                            if best is None or candidate[:2] > best[:2]:
                                best = candidate
                except Exception:
                    continue

            try:
                visit_candidates = list(_nas_sync_visit_candidates(
                    root, max_visits_per_patient=500))
            except Exception:
                visit_candidates = []
            for key, folder, _descend in visit_candidates:
                try:
                    folder = Path(folder)
                    if wanted and wanted_folded not in {
                            str(key).lower(), folder.name.lower()}:
                        folded_path = str(folder).lower()
                        if wanted_folded not in folded_path:
                            continue
                    files = _media_files_in_folder(folder)
                    if not files:
                        continue
                    latest = max(
                        (f.stat().st_mtime for f in files),
                        default=folder.stat().st_mtime)
                    candidate = (latest, len(files), folder, str(key), root)
                    if best is None or candidate[:2] > best[:2]:
                        best = candidate
                except Exception:
                    continue

            if best is None and not wanted:
                # Last resort: if files are nested under a structure not shaped
                # like visits, send the folder that owns the newest media file.
                try:
                    entries = _scan_patient_nas_media(
                        patient_key, max_candidates=900, timeout=5.5)
                except Exception:
                    entries = []
                for entry in entries:
                    try:
                        path = Path(entry.get("path"))
                        if not _is_path_relative_to(path, root):
                            continue
                        folder = path.parent
                        latest = float(entry.get("mtime") or path.stat().st_mtime)
                        candidate = (latest, 1, folder, folder.name, root)
                        if best is None or candidate[:2] > best[:2]:
                            best = candidate
                    except Exception:
                        continue
        if best is None:
            return None, None
        _latest, _count, folder, key, root = best
        return _disk_visit_row(folder, root, key), folder

    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        if visit_key:
            visit = con.execute(
                "SELECT * FROM visits "
                "WHERE patient_folder_key=? AND visit_key=?",
                (patient_key, visit_key),
            ).fetchone()
        else:
            visit = con.execute(
                "SELECT * FROM visits "
                "WHERE patient_folder_key=? "
                "ORDER BY visit_date DESC, visit_key DESC LIMIT 1",
                (patient_key,),
            ).fetchone()
    if not visit:
        return _find_on_disk()
    folder_value = str(visit.get("full_path") or "").strip()
    folder = Path(folder_value) if folder_value else (
        get_nas_root() / str(patient_key) / str(visit.get("visit_key") or ""))
    try:
        if folder.exists() and folder.is_dir():
            if _media_files_in_folder(folder, limit=1):
                return visit, folder
    except Exception:
        pass
    disk_visit, disk_folder = _find_on_disk()
    if disk_visit and disk_folder:
        return disk_visit, disk_folder
    return visit, folder


_WHATSAPP_VISIT_SHARE_EXTS = {
    ".pdf",
    ".jpg",
    ".jpeg",
    ".png",
    ".bmp",
    ".webp",
    ".tif",
    ".tiff",
    ".gif",
}
_WHATSAPP_VISIT_SKIP_EXTS = {
    ".tmp",
    ".temp",
    ".bak",
    ".log",
    ".db",
    ".sqlite",
    ".sqlite3",
    ".db-wal",
    ".db-shm",
    ".db-journal",
    ".ini",
}


def _whatsapp_visit_share_files(folder, max_files=5000):
    """Return all sendable regular files from the selected visit folder."""
    out = []
    seen = set()
    try:
        candidates = _nas_sync_iter_files(
            Path(folder), recursive=True, max_files=5000)
    except Exception:
        candidates = []
    for raw in candidates:
        try:
            path = Path(raw)
            if not path.exists() or not path.is_file():
                continue
            name = path.name.strip()
            suffix = path.suffix.lower()
            if not name or name.startswith("~$") or suffix in _WHATSAPP_VISIT_SKIP_EXTS:
                continue
            key = _windows_path_key(str(path.resolve()))
            if key in seen:
                continue
            seen.add(key)
            out.append(path)
            if len(out) >= int(max_files or 5000):
                break
        except Exception:
            continue

    def _sort_key(path):
        try:
            return (float(Path(path).stat().st_mtime), Path(path).name.lower())
        except Exception:
            return (0.0, str(path).lower())

    return sorted(out, key=_sort_key)


def _whatsapp_target_digits_for_patient_a100(patient_key):
    """Use patient WhatsApp first; fall back to clinic default number."""
    patient_phone = ""
    default_phone = ""
    try:
        patient_phone = load_phone_db(patient_key) or ""
    except Exception:
        patient_phone = ""
    digits = _normalize_whatsapp_digits_v1000(patient_phone)
    if digits:
        return digits, patient_phone, "patient"
    try:
        default_phone = get_default_whatsapp_number() or ""
    except Exception:
        default_phone = ""
    digits = _normalize_whatsapp_digits_v1000(default_phone)
    if digits:
        return digits, default_phone, "default"
    return "", patient_phone or default_phone, ""


def _copy_file_paths_to_windows_clipboard_v1000(files):
    """Copy selected files to the Windows clipboard as CF_HDROP."""
    paths = []
    for raw in files or []:
        try:
            path = Path(raw).resolve()
            if path.exists() and path.is_file():
                paths.append(path)
        except Exception:
            continue
    if not paths:
        return False, "Kopyalanacak dosya yok."
    if os.name != "nt":
        return False, "Dosya panosu sadece Windows oturumunda calisir."
    try:
        import ctypes
        import struct
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        user32.OpenClipboard.argtypes = [ctypes.c_void_p]
        user32.OpenClipboard.restype = ctypes.c_int
        user32.EmptyClipboard.argtypes = []
        user32.EmptyClipboard.restype = ctypes.c_int
        user32.SetClipboardData.argtypes = [ctypes.c_uint, ctypes.c_void_p]
        user32.SetClipboardData.restype = ctypes.c_void_p
        user32.CloseClipboard.argtypes = []
        user32.CloseClipboard.restype = ctypes.c_int
        kernel32.GlobalAlloc.argtypes = [ctypes.c_uint, ctypes.c_size_t]
        kernel32.GlobalAlloc.restype = ctypes.c_void_p
        kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
        kernel32.GlobalLock.restype = ctypes.c_void_p
        kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
        kernel32.GlobalUnlock.restype = ctypes.c_int
        kernel32.GlobalFree.argtypes = [ctypes.c_void_p]
        kernel32.GlobalFree.restype = ctypes.c_void_p

        path_blob = ("".join(str(path) + "\0" for path in paths) + "\0").encode(
            "utf-16-le")
        header = struct.pack("<IiiII", 20, 0, 0, 0, 1)
        handle = kernel32.GlobalAlloc(0x0002 | 0x0040, len(header) + len(path_blob))
        if not handle:
            return False, "Windows clipboard bellegi ayrilamadi."
        locked = kernel32.GlobalLock(handle)
        if not locked:
            kernel32.GlobalFree(handle)
            return False, "Windows clipboard bellegi kilitlenemedi."
        ctypes.memmove(locked, header, len(header))
        ctypes.memmove(locked + len(header), path_blob, len(path_blob))
        kernel32.GlobalUnlock(handle)

        opened = False
        for _attempt in range(18):
            if user32.OpenClipboard(None):
                opened = True
                break
            time.sleep(0.12)
        if not opened:
            kernel32.GlobalFree(handle)
            return False, "Windows clipboard acilamadi."
        try:
            user32.EmptyClipboard()
            if not user32.SetClipboardData(15, handle):
                kernel32.GlobalFree(handle)
                return False, "Windows clipboard dosya verisi yazilamadi."
            handle = None
            try:
                verified = bool(user32.IsClipboardFormatAvailable(15))
            except Exception:
                verified = True
            return (True, "") if verified else (False, "Windows clipboard dosya formati dogrulanamadi.")
        finally:
            user32.CloseClipboard()
    except Exception as ex:
        return False, str(ex)


def _windows_clipboard_has_files_v1000():
    if os.name != "nt":
        return False
    try:
        import ctypes
        return bool(ctypes.windll.user32.IsClipboardFormatAvailable(15))
    except Exception:
        return False


def _read_windows_clipboard_text_v1000():
    """Read plain Unicode text from the local Windows clipboard."""
    if os.name != "nt":
        return False, "Windows panosu sadece server PC uzerinde okunabilir."
    try:
        import ctypes
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        CF_UNICODETEXT = 13

        user32.IsClipboardFormatAvailable.argtypes = [ctypes.c_uint]
        user32.IsClipboardFormatAvailable.restype = ctypes.c_int
        user32.OpenClipboard.argtypes = [ctypes.c_void_p]
        user32.OpenClipboard.restype = ctypes.c_int
        user32.GetClipboardData.argtypes = [ctypes.c_uint]
        user32.GetClipboardData.restype = ctypes.c_void_p
        user32.CloseClipboard.argtypes = []
        user32.CloseClipboard.restype = ctypes.c_int
        kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
        kernel32.GlobalLock.restype = ctypes.c_void_p
        kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
        kernel32.GlobalUnlock.restype = ctypes.c_int

        if not user32.IsClipboardFormatAvailable(CF_UNICODETEXT):
            return False, "Panoda okunabilir metin yok."
        opened = False
        for _attempt in range(18):
            if user32.OpenClipboard(None):
                opened = True
                break
            time.sleep(0.08)
        if not opened:
            return False, "Windows panosu su an baska program tarafindan kullanimda."
        try:
            handle = user32.GetClipboardData(CF_UNICODETEXT)
            if not handle:
                return False, "Panodaki metin alinamadi."
            ptr = kernel32.GlobalLock(handle)
            if not ptr:
                return False, "Panodaki metin kilitlenemedi."
            try:
                text = ctypes.wstring_at(ptr)
            finally:
                kernel32.GlobalUnlock(handle)
            text = str(text or "")
            if not text.strip():
                return False, "Panodaki metin bos."
            return True, text
        finally:
            user32.CloseClipboard()
    except Exception as ex:
        return False, str(ex)


def _whatsapp_server_log_a111(message):
    try:
        import tempfile as _tempfile
        from datetime import datetime as _dt
        base = Path(_tempfile.gettempdir()) / "YazKlinikWhatsAppShare"
        base.mkdir(parents=True, exist_ok=True)
        line = f"{_dt.now().isoformat(timespec='seconds')} {message}\n"
        with (base / "server_paste.log").open("a", encoding="utf-8") as fh:
            fh.write(line)
    except Exception:
        pass


def _find_whatsapp_target_window_a111(timeout_sec: float = 8.0):
    if os.name != "nt":
        return None
    import ctypes
    import time as _time
    user32 = ctypes.windll.user32
    WNDENUMPROC = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)
    user32.EnumWindows.argtypes = [WNDENUMPROC, ctypes.c_void_p]
    user32.EnumWindows.restype = ctypes.c_int
    user32.IsWindowVisible.argtypes = [ctypes.c_void_p]
    user32.IsWindowVisible.restype = ctypes.c_int
    user32.GetWindowTextW.argtypes = [ctypes.c_void_p, ctypes.c_wchar_p, ctypes.c_int]
    user32.GetWindowTextW.restype = ctypes.c_int
    user32.GetWindow.argtypes = [ctypes.c_void_p, ctypes.c_uint]
    user32.GetWindow.restype = ctypes.c_void_p
    preferred_terms = ("whatsapp", "web.whatsapp")
    browser_terms = ("chrome", "edge", "firefox", "brave", "opera")

    def scan_once():
        preferred = []
        browsers = []

        def callback(hwnd, _param):
            try:
                if not user32.IsWindowVisible(hwnd) or user32.GetWindow(hwnd, 4):
                    return True
                buf = ctypes.create_unicode_buffer(512)
                user32.GetWindowTextW(hwnd, buf, 512)
                title = (buf.value or "").strip()
                folded = title.lower()
                if any(term in folded for term in preferred_terms):
                    preferred.append(int(hwnd))
                    return False
                if any(term in folded for term in browser_terms):
                    browsers.append(int(hwnd))
            except Exception:
                return True
            return True

        cb = WNDENUMPROC(callback)
        try:
            user32.EnumWindows(cb, None)
        except Exception:
            return None
        return preferred[0] if preferred else (browsers[0] if browsers else None)

    deadline = _time.time() + max(0.2, float(timeout_sec or 0))
    while _time.time() < deadline:
        hwnd = scan_once()
        if hwnd:
            return hwnd
        _time.sleep(0.25)
    return scan_once()


def _focus_window_for_paste_a111(hwnd) -> bool:
    if os.name != "nt" or not hwnd:
        return False
    try:
        import ctypes
        import time as _time
        user32 = ctypes.windll.user32
        user32.ShowWindow(hwnd, 9)  # SW_RESTORE
        VK_MENU = 0x12
        KEYEVENTF_KEYUP = 0x0002
        user32.keybd_event(VK_MENU, 0, 0, 0)
        user32.keybd_event(VK_MENU, 0, KEYEVENTF_KEYUP, 0)
        user32.BringWindowToTop(hwnd)
        ok = bool(user32.SetForegroundWindow(hwnd))
        _time.sleep(0.35)
        return ok
    except Exception:
        return False


def _send_ctrl_v_with_powershell_a111():
    if os.name != "nt":
        return False, "SendKeys sadece Windows'ta calisir."
    try:
        import subprocess as _subprocess
        cmd = (
            "Add-Type -AssemblyName System.Windows.Forms; "
            "[System.Windows.Forms.SendKeys]::SendWait('^v')"
        )
        flags = 0x08000000 if os.name == "nt" else 0
        completed = _subprocess.run(
            [
                "powershell", "-NoProfile", "-STA",
                "-ExecutionPolicy", "Bypass", "-Command", cmd,
            ],
            timeout=6,
            capture_output=True,
            text=True,
            creationflags=flags,
        )
        if completed.returncode == 0:
            return True, ""
        err = (completed.stderr or completed.stdout or "").strip()
        return False, err or f"SendKeys rc={completed.returncode}"
    except Exception as ex:
        return False, str(ex)


def _press_whatsapp_ctrl_v_key(delay_sec: float = 0.6, window_timeout_sec: float = 8.0):
    """Press Ctrl+V after bringing WhatsApp/App/Web to the foreground.

    B202: Eskiden hwnd yoksa Ctrl+V aktif pencereye gidiyordu - bu yanlislikla
    browser/Notepad/baska pencereye dosyalarin yapisma riskini doguruyordu
    ('kopyalama-yapistirma sorunlu' raporunun ana sebebi). Artik:
    - hwnd bulunamazsa Ctrl+V GONDERILMEZ, hata donulur
    - focus dogrulanamazsa Ctrl+V GONDERILMEZ
    - CF_HDROP pano dogrulanmazsa Ctrl+V GONDERILMEZ
    Doktor manuel Ctrl+V yapsin diye dosyalar panoda kalir.
    """
    if os.name != "nt":
        return False, "Ctrl+V otomasyonu sadece Windows masaustu oturumunda calisir."
    try:
        import ctypes
        import time as _time
        _time.sleep(max(0.1, float(delay_sec or 0)))
        hwnd = _find_whatsapp_target_window_a111(window_timeout_sec)
        if not hwnd:
            _whatsapp_server_log_a111("ABORT: WhatsApp penceresi bulunamadi; Ctrl+V atlandi (yanlis pencereye yapistirma riski)")
            return False, "WhatsApp penceresi bulunamadi; Ctrl+V atlandi. Dosyalar panoda - manuel Ctrl+V yapin."
        # B207: Eski B202 mantigi cok katiydi - SetForegroundWindow basarili
        # olsa bile foreground match degilse Ctrl+V ATILIYORDU. Doktor "otomatik
        # yapistirmiyor" raporladi. Artik 6 deneme + uzun sleep + foreground
        # match dogrulugu. 6 sonunda foreground hala WhatsApp degil ama hwnd
        # bizimse, yine de Ctrl+V dene (best-effort): Windows foreground-lock
        # politikalari nedeniyle bazen GetForegroundWindow eski deger doner.
        focus_ok = False
        focus_match = False
        user32 = ctypes.windll.user32
        for _attempt in range(6):
            ret = _focus_window_for_paste_a111(hwnd)
            if ret:
                focus_ok = True
            try:
                actual_fg = int(user32.GetForegroundWindow() or 0)
                if actual_fg == int(hwnd):
                    focus_match = True
                    break
            except Exception:
                pass
            _time.sleep(0.30)
        # B208: Window title + class log (tani icin kritik - doktor log dosyasini
        # gonderirse hangi pencere yakalandi, foreground'da ne var net gorulur).
        try:
            buf = ctypes.create_unicode_buffer(256)
            user32.GetWindowTextW(hwnd, buf, 256)
            target_title = buf.value
            cls = ctypes.create_unicode_buffer(128)
            user32.GetClassNameW(hwnd, cls, 128)
            target_class = cls.value
            actual_fg = int(user32.GetForegroundWindow() or 0)
            fg_buf = ctypes.create_unicode_buffer(256)
            user32.GetWindowTextW(actual_fg, fg_buf, 256)
            fg_title = fg_buf.value
            fg_cls_buf = ctypes.create_unicode_buffer(128)
            user32.GetClassNameW(actual_fg, fg_cls_buf, 128)
            fg_class = fg_cls_buf.value
            _whatsapp_server_log_a111(
                f"window-info target hwnd={hwnd} title='{target_title}' class='{target_class}' "
                f"| foreground hwnd={actual_fg} title='{fg_title}' class='{fg_class}'")
        except Exception as _ex:
            _whatsapp_server_log_a111(f"window-info dump failed: {_ex}")
        if focus_match:
            _whatsapp_server_log_a111(f"focus MATCH hwnd={hwnd}")
        elif focus_ok:
            _whatsapp_server_log_a111(f"focus best-effort hwnd={hwnd} (foreground match olmadi, Ctrl+V yine de denenecek)")
        else:
            _whatsapp_server_log_a111("warning: focus completely failed; Ctrl+V yine de deneyecegim")
        if not _windows_clipboard_has_files_v1000():
            # B207: CF_HDROP kayipsa hemen kalkma; arada bir program panoyu
            # eline almis olabilir. Bekle ve tekrar kontrol et.
            _whatsapp_server_log_a111("warning: CF_HDROP gorulmedi, 200ms beklenip tekrar denenecek")
            _time.sleep(0.20)
            if not _windows_clipboard_has_files_v1000():
                _whatsapp_server_log_a111("ABORT: CF_HDROP pano kayboldu; Ctrl+V atlandi")
                return False, "Dosyalar panodan kayboldu (baska bir program panoyu kullandi). Tekrar deneyin."
        ps_ok, ps_err = _send_ctrl_v_with_powershell_a111()
        if ps_ok:
            _whatsapp_server_log_a111("Ctrl+V sent with PowerShell SendKeys")
            return True, ""
        _whatsapp_server_log_a111(f"SendKeys failed; keybd_event fallback: {ps_err}")
        VK_CONTROL = 0x11
        VK_V = 0x56
        KEYEVENTF_KEYUP = 0x0002
        user32 = ctypes.windll.user32
        user32.keybd_event(VK_CONTROL, 0, 0, 0)
        _time.sleep(0.04)
        user32.keybd_event(VK_V, 0, 0, 0)
        _time.sleep(0.08)
        user32.keybd_event(VK_V, 0, KEYEVENTF_KEYUP, 0)
        _time.sleep(0.04)
        user32.keybd_event(VK_CONTROL, 0, KEYEVENTF_KEYUP, 0)
        _whatsapp_server_log_a111("Ctrl+V sent with keybd_event fallback")
        return True, ""
    except Exception as ex:
        _whatsapp_server_log_a111(f"Ctrl+V failed: {ex}")
        return False, str(ex)


def _whatsapp_is_running_v1000():
    """WhatsApp.exe/MS Store surecini hizlica tara - cold start tespiti."""
    if os.name != "nt":
        return False
    try:
        import subprocess as _sp
        # tasklist /FI "IMAGENAME eq WhatsApp.exe" - hizli, sessiz
        completed = _sp.run(
            ["tasklist", "/FI", "IMAGENAME eq WhatsApp.exe", "/NH"],
            capture_output=True, text=True, timeout=3,
            creationflags=0x08000000)
        out = (completed.stdout or "").lower()
        return "whatsapp.exe" in out
    except Exception:
        return False


def _open_whatsapp_and_paste_server_v1000(digits, file_count):
    """Open the patient chat on the server desktop and press Ctrl+V.

    D300 FIX: WhatsApp kapaliysa cold-start 4-6sn alir (ozellikle MS Store
    versiyonu). Eski delay'ler 1.4-2.6sn idi, pencere acilmadan Ctrl+V
    deneniyordu. Cold start tespit -> daha uzun delay.
    """
    if not digits:
        return False, "", "Telefon numarasi yok."
    file_count_int = max(1, int(file_count or 0))
    # D300: WhatsApp acik mi? Acik degilse cold-start delay
    was_running = _whatsapp_is_running_v1000()
    try:
        _url, method = open_whatsapp(digits, prefer_desktop=True)
    except Exception as ex:
        return False, "", f"WhatsApp acilamadi: {ex}"
    method_text = str(method or "")
    app_label = "WhatsApp Desktop" if method_text.startswith("desktop") else "WhatsApp Web"
    _whatsapp_server_log_a111(
        f"open method={method_text or '-'} files={int(file_count or 0)} "
        f"phone={digits[-4:] if digits else '-'} was_running={was_running}")
    if method_text.startswith("desktop"):
        last_err = ""
        # D300 FIX: Cold start (WhatsApp kapaliydi) icin 4-7sn ek delay
        if was_running:
            desktop_delays = (
                2.0 if file_count_int > 1 else 1.4,
                3.8 if file_count_int > 1 else 2.6,
            )
        else:
            # Cold start: MS Store WhatsApp icin 5-8sn gerek
            desktop_delays = (
                6.0 if file_count_int > 1 else 5.0,
                9.0 if file_count_int > 1 else 7.5,
            )
        for idx, delay_sec in enumerate(desktop_delays):
            ok, err = _press_whatsapp_ctrl_v_key(
                delay_sec=delay_sec,
                window_timeout_sec=18.0 if not was_running else
                                   (10.0 if idx == 0 else 14.0))
            if ok:
                if _get_whatsapp_auto_send_web():
                    _press_whatsapp_enter_key(
                        delay_sec=2.2 if file_count_int > 1 else 0.8)
                return True, app_label, ""
            last_err = err or last_err
        fallback_ok, fallback_err = wait_for_whatsapp_and_paste(
            timeout_sec=10.0 if not was_running else 8.0,
            initial_delay_sec=2.0 if not was_running else 0.7)
        if fallback_ok:
            if _get_whatsapp_auto_send_web():
                _press_whatsapp_enter_key(
                    delay_sec=2.2 if file_count_int > 1 else 0.8)
            return True, app_label, ""
        # App zaten acik gorunuyorsa gereksiz web acma: doktor manuel gonderebilir.
        if _find_whatsapp_target_window_a111(2.8):
            return False, app_label, (
                fallback_err or last_err or
                "WhatsApp App acildi ancak Ctrl+V otomatik tamamlanamadi.")
        try:
            import webbrowser as _webbrowser
            _webbrowser.open(_whatsapp_web_url_v1000(digits))
            web_ok, web_err = _press_whatsapp_ctrl_v_key(
                delay_sec=6.2, window_timeout_sec=12.0)
            if web_ok:
                if _get_whatsapp_auto_send_web():
                    _press_whatsapp_enter_key(
                        delay_sec=2.4 if file_count_int > 1 else 1.0)
                return True, "WhatsApp Web", ""
            return False, "WhatsApp Web", (
                web_err or fallback_err or last_err or
                "Ctrl+V otomatik tamamlanamadi.")
        except Exception as web_ex:
            return False, app_label, (
                last_err or f"WhatsApp Web yedegi acilamadi: {web_ex}")
    ok, err = _press_whatsapp_ctrl_v_key(delay_sec=6.2, window_timeout_sec=12.0)
    if ok:
        if _get_whatsapp_auto_send_web():
            _press_whatsapp_enter_key(delay_sec=2.4 if file_count_int > 1 else 1.0)
        return True, app_label, ""
    return False, app_label, err or "WhatsApp Web acildi; Ctrl+V otomatik tamamlanamadi."


def _normalize_whatsapp_digits_v1000(phone):
    digits = "".join(c for c in str(phone or "") if c.isdigit())
    if digits.startswith("00"):
        digits = digits[2:]
    if digits.startswith("0") and len(digits) == 11:
        digits = "90" + digits[1:]
    elif len(digits) == 10:
        digits = "90" + digits
    return digits


def _whatsapp_web_url_v1000(digits, message=""):
    from urllib.parse import quote as _quote
    url = f"https://web.whatsapp.com/send?phone={digits}"
    if message:
        url += "&text=" + _quote(str(message))
    return url


def _whatsapp_app_url_v1000(digits, message=""):
    from urllib.parse import quote as _quote
    url = f"whatsapp://send?phone={digits}"
    if message:
        url += "&text=" + _quote(str(message))
    return url


def _whatsapp_preferred_url_v1000(digits, message="", back=""):
    """Internal URL that opens app first; falls back to WhatsApp Web."""
    try:
        if not digits:
            return _whatsapp_web_url_v1000(digits, message)
        kwargs = {"phone": digits}
        if message:
            kwargs["text"] = message
        if back:
            kwargs["back"] = back
        return url_for("whatsapp_client_launcher", **kwargs)
    except Exception:
        return _whatsapp_web_url_v1000(digits, message)


def _whatsapp_share_temp_dir_v1000():
    import tempfile as _tempfile
    base = Path(_tempfile.gettempdir()) / "yazklinik_wa_share"
    base.mkdir(parents=True, exist_ok=True)
    return base.resolve()


def _whatsapp_file_mime_v1000(path):
    import mimetypes as _mimetypes
    mime = _mimetypes.guess_type(str(path))[0] or ""
    suffix = Path(path).suffix.lower()
    if not mime and suffix in {".jpg", ".jpeg"}:
        mime = "image/jpeg"
    elif not mime and suffix == ".png":
        mime = "image/png"
    elif not mime and suffix == ".webp":
        mime = "image/webp"
    elif not mime and suffix == ".pdf":
        mime = "application/pdf"
    return mime or "application/octet-stream"


def _whatsapp_share_token_path_v1000(token):
    token = str(token or "").strip()
    if not re.match(r"^[A-Za-z0-9_-]{16,80}$", token):
        return None
    return _whatsapp_share_temp_dir_v1000() / (token + ".json")


def _create_whatsapp_share_manifest_v1000(patient_key, visit, files, zip_url="", zip_name=""):
    import secrets as _secrets
    token = _secrets.token_urlsafe(24)
    token_path = _whatsapp_share_token_path_v1000(token)
    if token_path is None:
        raise RuntimeError("WhatsApp paylasim anahtari uretilemedi.")
    rows = []
    for raw in files or []:
        try:
            path = Path(raw).resolve()
            if not path.exists() or not path.is_file():
                continue
            stat = path.stat()
            mime = _whatsapp_file_mime_v1000(path)
            suffix = path.suffix.lower()
            if suffix == ".pdf":
                kind = "pdf"
            elif suffix in {".jpg", ".jpeg", ".png", ".bmp", ".webp", ".tif", ".tiff", ".gif"}:
                kind = "image"
            else:
                kind = "file"
            rows.append({
                "name": path.name,
                "path": str(path),
                "size": int(stat.st_size),
                "mtime": float(stat.st_mtime),
                "mime": mime,
                "kind": kind,
            })
        except Exception:
            continue
    payload = {
        "created_at": datetime.now().isoformat(sep=" ", timespec="seconds"),
        "patient_key": str(patient_key or ""),
        "visit_key": str((visit or {}).get("visit_key") or ""),
        "visit_date": str((visit or {}).get("visit_date") or ""),
        "zip_url": str(zip_url or ""),
        "zip_name": str(zip_name or ""),
        "files": rows,
    }
    token_path.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
    return token


def _load_whatsapp_share_manifest_v1000(token):
    token_path = _whatsapp_share_token_path_v1000(token)
    if token_path is None or not token_path.exists():
        return None
    try:
        data = json.loads(token_path.read_text(encoding="utf-8-sig") or "{}")
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    files = []
    for row in data.get("files") or []:
        try:
            path = Path(row.get("path") or "").resolve()
            if not path.exists() or not path.is_file():
                continue
            item = dict(row)
            item["path"] = str(path)
            item["name"] = Path(item.get("name") or path.name).name
            item["mime"] = item.get("mime") or _whatsapp_file_mime_v1000(path)
            files.append(item)
        except Exception:
            continue
    data["files"] = files
    return data


@app.route("/yk-whatsapp-launch")
@login_required
def whatsapp_client_launcher():
    """Client-side launcher: try WhatsApp app first, then WhatsApp Web."""
    digits = _normalize_whatsapp_digits_v1000(request.args.get("phone", ""))
    message = request.args.get("text", "")
    back_url = request.args.get("back", "/dashboard")
    if not digits:
        flash("WhatsApp icin telefon numarasi yok.", "warning")
        return redirect(back_url if str(back_url).startswith("/") else "/dashboard")
    app_url = _whatsapp_app_url_v1000(digits, message)
    web_url = _whatsapp_web_url_v1000(digits, message)
    import json as _json
    content = f"""
    <div class="yk-wa-launch-card">
      <div class="yk-wa-launch-icon"><i class="bi bi-whatsapp"></i></div>
      <div>
        <div class="text-uppercase small fw-bold text-success">WhatsApp istemci acilisi</div>
        <h2 class="mb-2">Once WhatsApp App deneniyor</h2>
        <p class="text-muted mb-3">
          Uygulama bu bilgisayarda yukluyse dogrudan WhatsApp programi acilir.
          App acilmazsa birkac saniye sonra WhatsApp Web yedek olarak acilir.
        </p>
        <div class="d-flex flex-wrap gap-2">
          <a id="ykWaAppBtn" class="btn btn-success btn-lg" href="{safe_attr(app_url)}">
            <i class="bi bi-whatsapp"></i> WhatsApp App'i Ac
          </a>
          <a id="ykWaWebBtn" class="btn btn-outline-primary btn-lg" target="_blank" rel="noopener"
             href="{safe_attr(web_url)}">
            <i class="bi bi-globe2"></i> WhatsApp Web
          </a>
          <a class="btn btn-outline-secondary btn-lg" href="{safe_attr(back_url if str(back_url).startswith('/') else '/dashboard')}">
            Geri Don
          </a>
        </div>
        <div id="ykWaLaunchStatus" class="small text-muted mt-3">
          App baslatiliyor...
        </div>
      </div>
    </div>
    <style>
      .yk-wa-launch-card {{
        max-width: 820px;
        margin: 8vh auto;
        padding: 30px;
        border-radius: 28px;
        display: flex;
        gap: 22px;
        align-items: flex-start;
        background:
          radial-gradient(circle at 0% 0%, rgba(37,211,102,.20), transparent 34%),
          linear-gradient(135deg, rgba(255,255,255,.98), rgba(235,255,248,.94));
        border: 1px solid rgba(16,185,129,.26);
        box-shadow: 0 24px 70px rgba(20,93,142,.15);
      }}
      .yk-wa-launch-icon {{
        width: 72px;
        height: 72px;
        flex: 0 0 72px;
        border-radius: 24px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        color: #fff;
        font-size: 34px;
        background: linear-gradient(135deg, #128C7E, #25D366);
        box-shadow: 0 18px 38px rgba(18,140,126,.24);
      }}
    </style>
    <script>
      (function() {{
        const appUrl = {_json.dumps(app_url)};
        const status = document.getElementById('ykWaLaunchStatus');
        // B202: Otomatik web fallback tamamen kaldirildi. Eskiden auto_web_fallback=1
        // parametresiyle 4.2 sn sonra window.location.href web URL'sine gidiyordu;
        // bu cogu zaman App acilmis olsa bile Web'i de aciyordu (cift WhatsApp).
        // Artik sadece App URL denenir; kullanici App acilmazsa "WhatsApp Web"
        // dugmesine manuel basar.
        function markExternal() {{
          if (status) status.textContent = 'WhatsApp App acildiysa bu sekmeyi kapatabilirsiniz.';
        }}
        window.addEventListener('blur', markExternal, {{once: true}});
        window.addEventListener('pagehide', markExternal, {{once: true}});
        document.addEventListener('visibilitychange', function() {{
          if (document.hidden) markExternal();
        }});
        function tryApp() {{
          try {{
            if (status) status.textContent = 'WhatsApp App deneniyor... acilmazsa "WhatsApp Web" dugmesini kullanin.';
            window.location.href = appUrl;
          }} catch (err) {{
            if (status) status.textContent = 'App tetiklenemedi: ' + (err && err.message ? err.message : err) + '. WhatsApp Web dugmesine basin.';
          }}
        }}
        window.addEventListener('DOMContentLoaded', function() {{
          setTimeout(tryApp, 180);
          // App butonu manuel click - hicbir setTimeout fallback yok
        }});
      }})();
    </script>
    """
    return render(content, title="WhatsApp App")


@app.route("/yk-whatsapp-zip/<path:filename>")
@permission_required("send_whatsapp")
def whatsapp_visit_zip_download(filename):
    """Download a temporary WhatsApp ZIP without touching the server desktop."""
    import tempfile as _tempfile
    base = (Path(_tempfile.gettempdir()) / "yazklinik_wa_zip").resolve()
    safe_name = Path(str(filename or "")).name
    if not safe_name:
        abort(404)
    zip_path = (base / safe_name).resolve()
    try:
        if not _is_path_relative_to(zip_path, base):
            abort(404)
    except Exception:
        abort(404)
    if not zip_path.exists() or not zip_path.is_file():
        abort(404)
    return send_file(zip_path, as_attachment=True, download_name=safe_name)


@app.route("/yk-whatsapp-share/<token>/manifest")
def whatsapp_visit_share_manifest(token):
    """Client-side WhatsApp share manifest for the current browser/device."""
    data = _load_whatsapp_share_manifest_v1000(token)
    if not data:
        return jsonify({"ok": False, "error": "Paylasim dosyasi bulunamadi."}), 404
    public_files = []
    for index, row in enumerate(data.get("files") or []):
        name = Path(row.get("name") or f"dosya-{index + 1}").name
        public_files.append({
            "index": index,
            "name": name,
            "path": row.get("path") or "",
            "local_path": row.get("path") or "",
            "size": int(row.get("size") or 0),
            "mime": row.get("mime") or "",
            "kind": row.get("kind") or "",
            "url": url_for(
                "whatsapp_visit_share_file",
                token=token,
                index=index,
                filename=name),
            "download_url": url_for(
                "whatsapp_visit_share_file",
                token=token,
                index=index,
                filename=name,
                download="1"),
        })
    response = jsonify({
        "ok": True,
        "patient_key": data.get("patient_key") or "",
        "visit_key": data.get("visit_key") or "",
        "visit_date": data.get("visit_date") or "",
        "zip_url": data.get("zip_url") or "",
        "zip_name": data.get("zip_name") or "",
        "count": len(public_files),
        "files": public_files,
    })
    response.headers["Cache-Control"] = "no-store"
    return response


@app.route("/yk-whatsapp-share/<token>/file/<int:index>/<path:filename>")
def whatsapp_visit_share_file(token, index, filename):
    """Serve a prepared visit file to the browser that initiated WhatsApp share."""
    data = _load_whatsapp_share_manifest_v1000(token)
    files = (data or {}).get("files") or []
    if index < 0 or index >= len(files):
        abort(404)
    row = files[index]
    path = Path(row.get("path") or "").resolve()
    if not path.exists() or not path.is_file():
        abort(404)
    safe_name = Path(row.get("name") or path.name).name
    if Path(filename or "").name != safe_name:
        abort(404)
    return send_file(
        path,
        mimetype=row.get("mime") or _whatsapp_file_mime_v1000(path),
        as_attachment=request.args.get("download") == "1",
        download_name=safe_name)


def _local_interface_ips_a100():
    """Return local interface IPs so browser-on-this-PC can use native helpers."""
    now = time.time()
    cached = getattr(_local_interface_ips_a100, "_cache", None)
    if cached and now - cached[0] < 120:
        return set(cached[1])
    ips = {"127.0.0.1", "::1", "localhost"}
    try:
        import socket as _socket
        names = {_socket.gethostname(), _socket.getfqdn()}
        for name in names:
            if not name:
                continue
            try:
                for item in _socket.gethostbyname_ex(name)[2]:
                    if item:
                        ips.add(str(item).strip().lower())
            except Exception:
                pass
            try:
                for info in _socket.getaddrinfo(name, None):
                    if info and info[4] and info[4][0]:
                        ips.add(str(info[4][0]).strip().lower())
            except Exception:
                pass
    except Exception:
        pass
    if os.name == "nt":
        try:
            completed = subprocess.run(
                ["ipconfig"],
                capture_output=True,
                text=True,
                timeout=2,
                encoding="utf-8",
                errors="ignore")
            text = (completed.stdout or "") + "\n" + (completed.stderr or "")
            for item in re.findall(r"\b(?:\d{1,3}\.){3}\d{1,3}\b", text):
                ips.add(item.strip().lower())
        except Exception:
            pass
    setattr(_local_interface_ips_a100, "_cache", (now, set(ips)))
    return set(ips)


def _is_local_browser_request_a100():
    """True only when the browser is running on the same PC as the server.

    Terminal/iPhone/Mac users must use browser/WebShell-native actions so an
    image, video or WhatsApp flow opens on their own device, not on the server
    desktop.
    """
    try:
        remote = (
            request.headers.get("X-Forwarded-For", "").split(",", 1)[0]
            or request.headers.get("X-Real-IP", "")
            or request.remote_addr
            or "")
        remote = str(remote).strip().lower()
        if remote.startswith("::ffff:"):
            remote = remote.rsplit(":", 1)[-1]
        if remote in {"", "127.0.0.1", "::1", "localhost"}:
            return True
        return remote in _local_interface_ips_a100()
    except Exception:
        return False


def _prepare_whatsapp_visit_share_a100(patient_key, visit_key=None, mode="files"):
    """Build the current visit file list/manifest for local client sending."""
    mode = (mode or "files").strip().lower()
    visit, folder = _find_visit_for_whatsapp(patient_key, visit_key)
    if not visit or not folder or not folder.exists() or not folder.is_dir():
        return None, "Son gelis klasoru bulunamadi."

    try:
        header = _get_patient_header_data(patient_key)
        patient_name = header.get("display_name") or patient_key
    except Exception:
        patient_name = patient_key

    files = _whatsapp_visit_share_files(folder)
    if not files:
        return None, "Bu geliste WhatsApp icin gonderilecek dosya bulunamadi."

    share_files = list(files)
    zip_url = ""
    zip_name = ""
    if mode == "zip":
        zip_path = build_zip_for_visit(
            folder,
            patient_name,
            str(visit.get("visit_date") or visit.get("visit_key") or ""))
        if not zip_path or not Path(zip_path).exists():
            return None, "ZIP hazirlanamadi."
        share_files = [Path(zip_path)]
        zip_name = Path(zip_path).name
        zip_url = url_for("whatsapp_visit_zip_download", filename=zip_name)

    token = _create_whatsapp_share_manifest_v1000(
        patient_key, visit, share_files, zip_url=zip_url, zip_name=zip_name)
    return {
        "visit": visit,
        "folder": folder,
        "files": files,
        "share_files": share_files,
        "token": token,
        "zip_url": zip_url,
        "zip_name": zip_name,
        "mode": mode,
    }, ""


def _whatsapp_send_visit_files_now_a100(patient_key, visit_key=None, mode="files"):
    """Copy visit files silently, open WhatsApp, paste, and maybe send."""
    mode = (mode or "files").strip().lower()
    visit, folder = _find_visit_for_whatsapp(patient_key, visit_key)
    if not visit or not folder or not folder.exists() or not folder.is_dir():
        return False, "Son gelis klasoru bulunamadi."

    try:
        header = _get_patient_header_data(patient_key)
        patient_name = header.get("display_name") or patient_key
    except Exception:
        patient_name = patient_key

    files = _whatsapp_visit_share_files(folder)
    if not files:
        return False, "Bu geliste WhatsApp icin gonderilecek dosya bulunamadi."

    files_to_send = files
    detail = f"{len(files)} dosya"
    if mode == "zip":
        zip_path = build_zip_for_visit(
            folder,
            patient_name,
            str(visit.get("visit_date") or visit.get("visit_key") or ""))
        if not zip_path or not Path(zip_path).exists():
            return False, "ZIP hazirlanamadi."
        files_to_send = [Path(zip_path)]
        detail = f"{len(files)} dosya tek ZIP"

    digits, raw_phone, phone_source = _whatsapp_target_digits_for_patient_a100(
        patient_key)
    if not digits:
        return False, "Hasta numarasi veya varsayilan WhatsApp numarasi yok."

    copied, copy_error = _copy_file_paths_to_windows_clipboard_v1000(files_to_send)
    if not copied:
        time.sleep(0.35)
        copied, copy_error = _copy_file_paths_to_windows_clipboard_v1000(files_to_send)
    if not copied:
        return False, f"Windows dosya panosuna kopyalanamadi: {copy_error}"

    pasted, app_label, paste_error = _open_whatsapp_and_paste_server_v1000(
        digits, len(files_to_send))
    phone_text = "hasta numarasi" if phone_source == "patient" else "varsayilan numara"
    auto_text = (
        "Otomatik gonderme acik; Gonder tusu denendi."
        if _get_whatsapp_auto_send_web() else
        "Manuel mod; doktor WhatsApp penceresinde Gonder tusuna basacak.")
    if pasted:
        return True, (
            f"{detail} arka planda panoya alindi; {phone_text} ile {app_label} "
            f"acildi ve Ctrl+V yapildi. {auto_text}")
    target = app_label or "WhatsApp"
    # B110: Eskiden burada True donuyordu; doktor 'success' flash gorup yapistirma
    # tamamlandi sanip yarim mesaj birakiyordu. Artik dogru sekilde False donulur,
    # boylece UI kullaniciya 'el ile Ctrl+V yapin' uyarisini net gosterir.
    return False, (
        f"{detail} dosyalari panoya alindi ve {target} acildi, ancak otomatik "
        f"Ctrl+V tamamlanmadi ({paste_error or 'bilinmeyen hata'}). "
        "Lutfen acilan WhatsApp sohbet kutusuna tiklayip Ctrl+V ile "
        "dosyalari elinizle yapistirin.")


@app.route("/hasta/<patient_key>/whatsapp/son-gelis", methods=["POST"])
@permission_required("send_whatsapp")
def whatsapp_latest_visit_prepare(patient_key):
    """Send latest/requested visit files through WhatsApp immediately."""
    mode = (request.form.get("mode") or "files").strip().lower()
    visit_key = (request.form.get("visit_key") or "").strip() or None
    # B208: Doktor manuel telefon girebilsin diye opsiyonel manual_phone param.
    manual_phone = (request.form.get("manual_phone") or "").strip()
    # D300: WhatsApp send akisi log basla (sorun tanisi icin)
    try:
        _whatsapp_server_log_a111(
            f"START patient_key={patient_key} mode={mode} "
            f"visit_key={visit_key} manual_phone={'set' if manual_phone else '-'}")
    except Exception:
        pass
    try:
        prepared, error = _prepare_whatsapp_visit_share_a100(
            patient_key, visit_key=visit_key, mode=mode)
        if not prepared:
            try:
                _whatsapp_server_log_a111(f"PREPARE FAIL: {error}")
            except Exception:
                pass
            flash(error, "danger")
            return redirect(url_for("whatsapp_link", patient_key=patient_key))
        digits = ""
        if manual_phone:
            try:
                digits = _normalize_whatsapp_digits_v1000(manual_phone)
            except Exception:
                digits = "".join(c for c in manual_phone if c.isdigit())
        if not digits:
            digits, _raw_phone, _phone_source = _whatsapp_target_digits_for_patient_a100(
                patient_key)
        if not digits:
            # B208: Manuel numara form'una yonlendir (whatsapp_link sayfasi
            # need_phone=1 ile bir form gosterecek - eski 'danger' flash + cikmaz
            # sokaktan kurtuldu).
            flash("Bu hasta icin kayitli telefon yok. Asagidaki kutuya numara girip 'Manuel numara ile gonder' diyebilirsiniz.", "warning")
            return redirect(url_for(
                "whatsapp_link",
                patient_key=patient_key,
                need_phone="1",
                mode=mode,
                visit_key=visit_key or ""))
        flash(
            "Son gelis dosyalari bu bilgisayardaki WhatsApp'a gonderilmek uzere "
            "arka planda hazirlandi.",
            "success")
        return redirect(url_for(
            "whatsapp_link",
            patient_key=patient_key,
            client_open="1",
            prepared=mode,
            count=str(len(prepared.get("files") or [])),
            zip_url=prepared.get("zip_url") or "",
            zip_name=prepared.get("zip_name") or "",
            share_token=prepared.get("token") or "",
            visit_key=str((prepared.get("visit") or {}).get("visit_key") or visit_key or "")))
    except Exception as ex:
        try:
            import traceback as _tb
            _whatsapp_server_log_a111(
                f"EXCEPTION: {type(ex).__name__}: {ex}\n{_tb.format_exc()}")
        except Exception:
            pass
        flash(f"WhatsApp gonderme hatasi: {ex}", "danger")
    return redirect(url_for("whatsapp_link", patient_key=patient_key))


@app.route("/hasta/<patient_key>/whatsapp/son-gelis/pano-yapistir", methods=["POST"])
@permission_required("send_whatsapp")
def whatsapp_latest_visit_paste_local(patient_key):
    """Server-local fallback only; terminals use browser/WebShell sharing."""
    if not _is_local_browser_request_a100():
        flash(
            "Bu dugme server PC ekranina yapistirir. Terminal/iPhone/Mac icin "
            "'Bu cihazdan paylas', 'Bu cihaz panosuna kopyala' veya ZIP kullanin.",
            "warning")
        return redirect(url_for("whatsapp_link", patient_key=patient_key))
    visit_key = (
        request.form.get("visit_key")
        or request.args.get("visit_key")
        or ""
    ).strip() or None
    mode = (request.form.get("mode") or request.args.get("mode") or "files").strip().lower()
    try:
        ok, message = _whatsapp_send_visit_files_now_a100(
            patient_key, visit_key=visit_key, mode=mode)
        flash(message, "success" if ok else "danger")
    except Exception as ex:
        flash(f"WhatsApp pano/yapistirma hatasi: {ex}", "danger")
    return redirect(url_for("whatsapp_link", patient_key=patient_key))


# ===========================================================================
# B304: WhatsApp paste async + progress + thread bloke onleme
# ===========================================================================
# Mevcut sync endpoint (whatsapp_latest_visit_paste_local) butun thread'i
# 5-30 sn isgal ediyor (NAS yavasligi + clipboard kopyalama + WhatsApp
# acilma + tus basma). 8 thread'lik waitress'ta cabuk kuyruga giriyor,
# UI donuyor. Bu blok ayni isi arka planda yapan bir async yola sunar:
#   POST /api/whatsapp/async-share -> task_id, hemen 202 doner
#   GET  /api/whatsapp/async-share/<task_id>/status -> progress polling
# Sayfadaki butonlar bu endpoint'i fetch ile cagirip overlay gosterir.
# Auto-send default ON: ilk acilista DB'ye explicit "1" yazilir.
# ===========================================================================

import uuid as _b304_uuid
_B304_WA_TASKS = {}  # task_id -> dict
_B304_WA_LOCK = threading.Lock()
_B304_WA_TASK_TTL = 600  # 10 dk sonra eski task'lar temizlenir
_B304_WA_AUTOSEND_INIT_DONE = False


def _b304_wa_log(task_id, msg, stage=None, percent=None):
    line = f"[{datetime.now().strftime('%H:%M:%S')}] {str(msg).rstrip()}"
    with _B304_WA_LOCK:
        st = _B304_WA_TASKS.setdefault(task_id, {})
        log = st.setdefault("log", [])
        log.append(line)
        if len(log) > 80:
            del log[: len(log) - 80]
        if stage is not None:
            st["stage"] = stage
        if percent is not None:
            st["percent"] = int(percent)


def _b304_wa_cleanup_old_tasks():
    """10 dk dolmus task kayitlarini sil."""
    now = time.time()
    with _B304_WA_LOCK:
        keys_to_del = []
        for k, v in _B304_WA_TASKS.items():
            ended = float(v.get("ended_at") or 0)
            if ended and (now - ended) > _B304_WA_TASK_TTL:
                keys_to_del.append(k)
        for k in keys_to_del:
            _B304_WA_TASKS.pop(k, None)


def _b304_ensure_autosend_default():
    """B304: Otomatik gonder varsayilan ON. Doktor ekranlarinda 'manuel mod'
    yazisi bir daha cikmasin diye DB'ye explicit '1' yaz (zaten set degilse)."""
    global _B304_WA_AUTOSEND_INIT_DONE
    if _B304_WA_AUTOSEND_INIT_DONE:
        return
    try:
        cur = _db_get_setting("whatsapp_auto_send", "")
        if not str(cur).strip():
            _db_set_setting("whatsapp_auto_send", "1")
            _db_set_setting("clinic/whatsapp_auto_send", "1")
        _B304_WA_AUTOSEND_INIT_DONE = True
    except Exception:
        pass


def _b304_wa_share_worker(task_id, patient_key, visit_key, mode, manual_phone):
    """Arka plan thread: dosyalari panoya kopyala, WhatsApp ac, Ctrl+V,
    auto-send. Tum asamalar log'lanir, UI polling yapar."""
    try:
        _b304_ensure_autosend_default()
        with _B304_WA_LOCK:
            _B304_WA_TASKS[task_id] = {
                "running": True, "completed": False, "ok": False,
                "started_at": time.time(), "ended_at": 0.0,
                "log": [], "stage": "starting", "percent": 0,
                "patient_key": patient_key, "visit_key": visit_key,
                "mode": mode, "message": "", "app_label": "",
            }
        _b304_wa_log(task_id, f"Hasta {patient_key} icin WhatsApp paylasimi basliyor.",
                     stage="prepare", percent=5)

        # 1) Visit/folder cozumle
        visit, folder = _find_visit_for_whatsapp(patient_key, visit_key)
        if not visit or not folder or not folder.exists() or not folder.is_dir():
            _b304_wa_log(task_id, "Son gelis klasoru bulunamadi.", stage="error")
            with _B304_WA_LOCK:
                _B304_WA_TASKS[task_id].update({
                    "running": False, "completed": True, "ok": False,
                    "ended_at": time.time(),
                    "message": "Son gelis klasoru bulunamadi.",
                })
            return

        files = _whatsapp_visit_share_files(folder)
        if not files:
            _b304_wa_log(task_id, "Bu geliste paylasilacak dosya yok.", stage="error")
            with _B304_WA_LOCK:
                _B304_WA_TASKS[task_id].update({
                    "running": False, "completed": True, "ok": False,
                    "ended_at": time.time(),
                    "message": "Bu geliste WhatsApp icin gonderilecek dosya yok.",
                })
            return

        files_to_send = files
        detail = f"{len(files)} dosya"
        if mode == "zip":
            _b304_wa_log(task_id, "ZIP hazirlaniyor (uzun surebilir)...",
                         stage="zipping", percent=15)
            try:
                header = _get_patient_header_data(patient_key)
                patient_name = header.get("display_name") or patient_key
            except Exception:
                patient_name = patient_key
            zip_path = build_zip_for_visit(
                folder, patient_name,
                str(visit.get("visit_date") or visit.get("visit_key") or ""))
            if not zip_path or not Path(zip_path).exists():
                _b304_wa_log(task_id, "ZIP olusturulamadi.", stage="error")
                with _B304_WA_LOCK:
                    _B304_WA_TASKS[task_id].update({
                        "running": False, "completed": True, "ok": False,
                        "ended_at": time.time(), "message": "ZIP hazirlanamadi.",
                    })
                return
            files_to_send = [Path(zip_path)]
            detail = f"{len(files)} dosya tek ZIP"

        # 2) Telefon numarasi
        digits = ""
        if manual_phone:
            try:
                digits = _normalize_whatsapp_digits_v1000(manual_phone)
            except Exception:
                digits = "".join(c for c in manual_phone if c.isdigit())
        if not digits:
            d, _raw, _src = _whatsapp_target_digits_for_patient_a100(patient_key)
            digits = d
        if not digits:
            _b304_wa_log(task_id, "Telefon numarasi yok.", stage="error")
            with _B304_WA_LOCK:
                _B304_WA_TASKS[task_id].update({
                    "running": False, "completed": True, "ok": False,
                    "ended_at": time.time(),
                    "message": "Hasta numarasi veya varsayilan WhatsApp numarasi yok.",
                })
            return

        # 3) Panoya kopyala
        _b304_wa_log(task_id, f"{detail} panoya kopyalaniyor...",
                     stage="clipboard", percent=30)
        copied, copy_err = _copy_file_paths_to_windows_clipboard_v1000(files_to_send)
        if not copied:
            time.sleep(0.4)
            _b304_wa_log(task_id, "Panoya kopyalama 2. deneme...")
            copied, copy_err = _copy_file_paths_to_windows_clipboard_v1000(files_to_send)
        if not copied:
            _b304_wa_log(task_id, f"Panoya kopyalanamadi: {copy_err}",
                         stage="error")
            with _B304_WA_LOCK:
                _B304_WA_TASKS[task_id].update({
                    "running": False, "completed": True, "ok": False,
                    "ended_at": time.time(),
                    "message": f"Pano kopyalama hatasi: {copy_err}",
                })
            return
        _b304_wa_log(task_id, "Pano OK.", percent=50)

        # 4) WhatsApp ac + paste + auto-send
        _b304_wa_log(task_id, "WhatsApp aciliyor (Desktop once, fail ise Web)...",
                     stage="opening", percent=60)
        retry_delays = (0.0, 1.3, 2.4)
        pasted = False
        app_label = "WhatsApp"
        paste_err = ""
        copy_retry_err = ""
        for attempt_idx, delay_sec in enumerate(retry_delays, start=1):
            if attempt_idx > 1:
                _b304_wa_log(
                    task_id,
                    f"Yapistirma tekrar deneme {attempt_idx}/{len(retry_delays)} "
                    f"({delay_sec:.1f} sn bekleme + pano yenileme)...",
                    percent=65 + (attempt_idx * 5))
                try:
                    time.sleep(max(0.1, float(delay_sec)))
                except Exception:
                    pass
                copied_retry, copy_retry_err = _copy_file_paths_to_windows_clipboard_v1000(
                    files_to_send)
                if not copied_retry:
                    paste_err = (
                        f"Pano yeniden kopyalanamadi: "
                        f"{copy_retry_err or 'bilinmeyen hata'}")
                    _b304_wa_log(task_id, paste_err)
                    continue

            pasted, app_label, paste_err = _open_whatsapp_and_paste_server_v1000(
                digits, len(files_to_send))
            with _B304_WA_LOCK:
                _B304_WA_TASKS[task_id]["app_label"] = app_label or "WhatsApp"
            if pasted:
                break

            _b304_wa_log(
                task_id,
                f"Deneme {attempt_idx}/{len(retry_delays)} basarisiz: "
                f"{paste_err or 'bilinmeyen hata'}")

        autosend_on = _get_whatsapp_auto_send_web()
        auto_text = ("Otomatik gonder acik; Enter denendi."
                     if autosend_on else
                     "Otomatik gonder kapali; Gonder tusuna manuel basin.")
        if pasted:
            _b304_wa_log(task_id,
                         f"Yapistirildi ({app_label}). {auto_text}",
                         stage="done", percent=100)
            with _B304_WA_LOCK:
                _B304_WA_TASKS[task_id].update({
                    "running": False, "completed": True, "ok": True,
                    "ended_at": time.time(),
                    "message": f"{detail} {app_label}'da yapistirildi. {auto_text}",
                })
            return

        # Paste basarisiz - kullanici elle yapsin
        _b304_wa_log(task_id,
                     f"Otomatik Ctrl+V {len(retry_delays)} denemede tamamlanmadi: {paste_err or '?'}",
                     stage="error", percent=90)
        with _B304_WA_LOCK:
            _B304_WA_TASKS[task_id].update({
                "running": False, "completed": True, "ok": False,
                "ended_at": time.time(),
                "message": (
                    f"{detail} panoya alindi ve {app_label or 'WhatsApp'} acildi, "
                    f"ancak otomatik Ctrl+V {len(retry_delays)} denemede tamamlanmadi "
                    f"({paste_err or copy_retry_err or 'bilinmeyen hata'}). "
                    "Acilan WhatsApp sohbet kutusuna tiklayip Ctrl+V yapin."
                ),
            })
    except Exception as ex:
        _b304_wa_log(task_id, f"BEKLENMEDIK HATA: {ex}", stage="error")
        with _B304_WA_LOCK:
            _B304_WA_TASKS.setdefault(task_id, {}).update({
                "running": False, "completed": True, "ok": False,
                "ended_at": time.time(),
                "message": f"Beklenmedik hata: {ex}",
            })


@app.route("/api/whatsapp/async-share", methods=["POST"])
@permission_required("send_whatsapp")
def b304_api_whatsapp_async_share():
    """B304: WhatsApp paylasimi arka planda baslat. Hemen task_id doner.

    D300 terminal-safe: this server-side clipboard path is available only when
    the browser is on the server PC. Terminals use manifest/Web Share/native
    WebShell helpers so WhatsApp opens on the terminal device.
    """
    if not _is_local_browser_request_a100():
        return jsonify({
            "ok": False,
            "error": (
                "Server PC WhatsApp yapistirma terminalden kapali. "
                "Bu cihazdan paylas, cihaz panosu veya ZIP kullanin."),
            "client_mode": True,
        }), 409
    _b304_wa_cleanup_old_tasks()
    data = request.get_json(silent=True) or request.form or {}
    patient_key = str(data.get("patient_key") or "").strip()
    if not patient_key:
        return jsonify({"ok": False, "error": "patient_key gerekli"}), 400
    visit_key = (str(data.get("visit_key") or "").strip() or None)
    mode = (str(data.get("mode") or "files").strip().lower() or "files")
    manual_phone = str(data.get("manual_phone") or "").strip()
    task_id = _b304_uuid.uuid4().hex[:16]
    try:
        t = threading.Thread(
            target=_b304_wa_share_worker,
            args=(task_id, patient_key, visit_key, mode, manual_phone),
            name=f"b304-wa-{task_id}", daemon=True)
        t.start()
        return jsonify({
            "ok": True, "running": True, "task_id": task_id,
            "message": "WhatsApp paylasimi arka planda baslatildi.",
        })
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/whatsapp/async-share/<task_id>/status", methods=["GET"])
@permission_required("send_whatsapp")
def b304_api_whatsapp_async_status(task_id):
    """B304: Async WhatsApp task durumu (UI polling)."""
    with _B304_WA_LOCK:
        st = _B304_WA_TASKS.get(task_id) or {}
        if not st:
            return jsonify({
                "ok": False, "completed": True, "running": False,
                "error": "Bilinmeyen task_id veya zaman asimi.",
                "log": [], "stage": "unknown", "percent": 0,
            }), 404
        return jsonify(dict(st))


@app.route("/api/whatsapp/auto-send", methods=["GET", "POST"])
@permission_required("send_whatsapp")
def b304_api_whatsapp_auto_send_toggle():
    """B304: Otomatik gonder ayarini oku/yaz."""
    if request.method == "POST":
        data = request.get_json(silent=True) or request.form or {}
        new_val = str(data.get("enabled") or "").lower() in {
            "1", "true", "yes", "on", "evet"}
        try:
            _set_whatsapp_auto_send_web(bool(new_val))
            return jsonify({"ok": True, "enabled": bool(new_val)})
        except Exception as ex:
            return jsonify({"ok": False, "error": str(ex)}), 500
    return jsonify({"ok": True, "enabled": _get_whatsapp_auto_send_web()})


