@app.route("/hasta/<patient_key>/tahlil-dosya/<int:media_id>")
@permission_required("view_lab")
def lab_media_file(patient_key, media_id):
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            row = con.execute(
                "SELECT * FROM lab_media_files WHERE id=? AND patient_key=?",
                (media_id, patient_key)).fetchone()
        if not row:
            abort(404)
        patient_root = _patient_root_for_nas(patient_key).resolve()
        path = (patient_root / str(row.get("rel_path") or "")).resolve()
        path.relative_to(patient_root)
        if not path.exists() or not path.is_file():
            abort(404)
        return _send_web_media_file(
            path,
            kind=_file_kind_for_path(path),
            download=request.args.get("download") == "1")
    except Exception:
        abort(404)


@app.route("/hasta/<patient_key>/yz-lab-usg-yorum")
@permission_required("view_lab")
def ai_lab_usg_review(patient_key):
    try:
        labs = list_lab_results(patient_key)[:6]
    except Exception:
        labs = []
    lab_media = _list_lab_media(patient_key, limit=6)
    lab_text_parts = []
    for item in lab_media[:4]:
        if item.get("ocr_text"):
            lab_text_parts.append(
                f"[{item.get('test_date') or ''} {item.get('file_name')}] "
                f"{str(item.get('ocr_text') or '')[:2500]}")

    media = _collect_patient_media_for_ai(patient_key, max_images=8, max_video_frames=3)
    pdf_context = _collect_patient_pdf_text_for_ai(patient_key, max_pdfs=3, max_chars=7000)
    vision_choice = _select_ollama_vision_model() if media.get("images") else {}
    model = vision_choice.get("model") or _select_ollama_model()
    selected_images = media.get("images") if vision_choice.get("model") else []
    prompt = (
        _patient_context_for_ai(patient_key, include_labs=True, include_usg=True)
        + "\n\nEk tahlil OCR metinleri:\n"
        + ("\n\n".join(lab_text_parts) if lab_text_parts else "Yok")
        + "\n\n[NAS HASTA KLASORU]\n"
        + f"Klasor: {media.get('source_root') or 'Bilinmiyor'}\n"
        + f"Okunan medya: {', '.join(media.get('image_names') or []) or 'Yok'}\n"
        + f"DICOM/RAW: {', '.join(media.get('dicom_names') or []) or 'Yok'}\n"
        + f"PDF: {', '.join(media.get('pdf_names') or []) or 'Yok'}\n"
        + "\n\n[USG/VOLUSON PDF RAPOR METNI - TETKIK PDF DEGIL]\n"
        + (pdf_context or "Okunabilir PDF metni bulunamadi.")
        + "\n\n[GORUNTULU MODEL]\n"
        + (
            f"{vision_choice.get('model')} ({vision_choice.get('source')})"
            if selected_images else
            "Goruntu varsa bile kurulu vision model bulunamadi; metin/PDF kullanildi."
        )
        + "\n\nGorev: Bu hasta icin son tahlilleri, yuklenen tahlil "
        "goruntulerini ve mevcut USG/DICOM/USG medya baglamini birlikte "
        "yorumla. Voluson/USG PDF bilgisini USG kaynagi, "
        "lab_media/lab_results bilgisini tetkik kaynagi olarak ayri tut; "
        "birini digerinin yerine yazma. Cikti baskiya uygun, doktor tarafindan hizla okunacak "
        "kalitede olsun. Zorunlu basliklar: 1. Son Tahlil Sonuclari, "
        "2. USG ile Birlikte Kontrol Edilecek Noktalar, 3. Riskler ve "
        "Kontrol Gerektiren Durumlar, 4. Takip Plani, 5. Ilac/Tedavi "
        "Karar Destegi, 6. Hekim Notu. USG raporu yoksa varsayimsal "
        "bulgu uydurma; sadece kontrol listesi olarak belirt. Gebelik "
        "olasiligi varsa statin, NSAID ve benzeri ilaclari dogrudan "
        "onerme; risk/yarar ve hekim/ilgili uzman dogrulamasi gerektigini "
        "yaz. Kesin tani koyma."
    )
    ok, answer, dur = call_ollama(
        prompt,
        model=model,
        system=_doctor_ai_system("combined_lab_usg_review"),
        images=selected_images or [],
        max_tokens=2400,
        use_cache=False,
    )
    if not ok:
        answer = answer or "YZ yaniti alinamadi."

    lab_rows = ""
    for r in labs:
        vals = r.get("values") or {}
        short = ", ".join(
            f"{k}: {v.get('value') if isinstance(v, dict) else v}"
            for k, v in list(vals.items())[:10])
        lab_rows += (
            f"<tr><td>{sh(r.get('test_date') or '')}</td>"
            f"<td>{sh(short or r.get('notes') or r.get('source') or '')}</td></tr>")
    report_html = _yk_ai_clinical_report_html(
        answer,
        labs=labs,
        subtitle="Hasta dosyasindaki tahlil, OCR ve USG/PDF baglamindan uretildi",
        model=model,
        duration=dur,
    )
    content = f"""
    <a href="/hasta/{patient_key}/tahliller" class="btn btn-secondary mb-3">
      Tahlillere don
    </a>
    {report_html}
    <div class="card">
      <div class="card-header">Kullanilan son tahlil ozeti</div>
      <div class="card-body p-0">
        <table class="table table-sm mb-0">
          <tbody>{lab_rows or '<tr><td class="text-muted">Kayitli tahlil yok.</td></tr>'}</tbody>
        </table>
      </div>
    </div>
    """
