@app.route("/hasta/<patient_key>/dogum", methods=["GET", "POST"])
@permission_required("record_delivery")
def delivery(patient_key):
    """ğŸ¤± DoÄŸum kaydÄ± - hasta doÄŸduÄŸunda."""
    if request.method == "POST":
        f = request.form
        try:
            delivery_date = f.get("delivery_date", "").strip()
            delivery_type = f.get("delivery_type", "").strip()
            if not delivery_date or not delivery_type:
                flash("Tarih ve doÄŸum tipi zorunludur.", "danger")
                return redirect(url_for("delivery",
                                          patient_key=patient_key))

            # GA calculation
            ga_days = None
            demo = load_patient_demographics(patient_key)
            lmp = demo.get("lmp_override", "")
            if lmp:
                try:
                    dd, mm, yy = lmp.split(".")
                    lmp_dt = datetime(int(yy), int(mm), int(dd))
                    del_dt = datetime.strptime(delivery_date,
                                                 "%Y-%m-%d")
                    ga_days = (del_dt - lmp_dt).days
                except Exception:
                    pass

            baby_weight = None
            try:
                bw = f.get("baby_weight", "").strip()
                if bw:
                    baby_weight = int(bw)
            except ValueError:
                pass

            baby_count = 1
            try:
                bc = f.get("baby_count", "1").strip()
                if bc:
                    baby_count = int(bc)
            except ValueError:
                pass

            record_delivery(
                patient_key,
                delivery_date=delivery_date,
                delivery_type=delivery_type,
                ga_at_delivery_days=ga_days,
                baby_count=baby_count,
                baby_weight_g=baby_weight,
                baby_sex=f.get("baby_sex", "") or None,
                outcome=f.get("outcome", "") or None,
                hospital=f.get("hospital", "") or None,
                notes=f.get("notes", "") or None)
            _invalidate_patient_web_cache(patient_key)
            flash(f"âœ… DoÄŸum kaydÄ± baÅŸarÄ±lÄ±! "
                   f"Hasta artÄ±k DoÄŸuranlar grubunda.", "success")
        except Exception as ex:
            flash(f"Kayit hatasÄ±: {ex}", "danger")
        return redirect(url_for("patient_detail",
                                  patient_key=patient_key))

