# Kategoriler: Gebelik, Jinekoloji, Jinekolojik Estetik,
# Medikal Estetik, Infertilite, Paylasim Izinleri.
def _onam_classify_bulk(filename, content_snippet="", parent_dir=""):
    """Dosya adi + iceriginden uygun kategori ve aciklamayi dondurur.

    Doner: (category, purpose)"""
    def _norm(s):
        s = str(s or "").lower()
        for src, dst in zip("ığüşöçİĞÜŞÖÇ", "igusociIGUSOC"):
            s = s.replace(src, dst)
        for bad in ("�", "ý", "þ"):
            s = s.replace(bad, "")
        return s

    fname = _norm(filename)
    parent = _norm(parent_dir)
    text = _norm(f"{filename} {content_snippet} {parent_dir}")

    # 1) JINEKOLOJIK ESTETIK (vajinoplasti, labioplasti, perine, vajen daraltma...)
    gyn_aesthetic_kw = [
        "vajinoplast", "labioplast", "labiaplast", "labium major",
        "labium minor", "labia major", "labia minor", "vajen daralt",
        "vajinal rejuv", "perine plast", "g spot", "g-spot",
        "klitoris", "kliteroplasti", "hymenoplasti", "himenoplasti",
        "vulvoplasti", "vajinal estetik", "intim estetik",
        "intima estetik", "kadin estetik",
    ]
    if any(k in text for k in gyn_aesthetic_kw):
        return "Jinekolojik Estetik", "Jinekolojik / intim estetik onam"

    # 2) MEDIKAL ESTETIK (botox, dolgu, PRP, mezo, lazer epilasyon...)
