def _onam_read_pdf_snippet(blob, max_bytes=4000):
    """Yukar listede secilen blob/file'dan PDF text ilk birkac KB."""
    try:
        import fitz  # PyMuPDF
        doc = fitz.open(stream=blob, filetype="pdf")
        text = ""
        for page in doc[:2]:
            text += page.get_text() or ""
            if len(text) > max_bytes:
                break
        doc.close()
        return text[:max_bytes]
    except Exception:
        return ""


def _onam_read_file_snippet(path, max_bytes=4000):
    """Disk uzerinden okuyup ilk birkac KB text dondurur."""
    try:
        import os as _os
        ext = _os.path.splitext(str(path))[1].lower()
        if ext == ".pdf":
            try:
                import fitz
                doc = fitz.open(str(path))
                text = ""
                for page in doc[:2]:
                    text += page.get_text() or ""
                    if len(text) > max_bytes:
                        break
                doc.close()
                return text[:max_bytes]
            except Exception:
                return ""
        if ext == ".txt":
            try:
                with open(str(path), "rb") as f:
                    raw = f.read(max_bytes)
                return raw.decode("utf-8", errors="ignore")
            except Exception:
                return ""
        if ext == ".docx":
            try:
                from docx import Document  # type: ignore
                doc = Document(str(path))
                return "\n".join(p.text for p in doc.paragraphs[:30])[:max_bytes]
            except Exception:
                return ""
    except Exception:
        pass
    return ""


_ONAM_BULK_SUPPORTED_EXT = {".pdf", ".doc", ".docx", ".txt", ".rtf",
                            ".jpg", ".jpeg", ".png"}
_ONAM_BULK_EXCLUDE_DIRS = {"#recycle", "$recycle.bin", ".trash", "test",
                           "tests", "turizm"}


