def _onam_bulk_make_key(short_name, cur):
    base_key = _consent_form_key(short_name) or f"onam_{int(time.time())}"
    key = base_key
    n = 2
    while cur.execute(
        "SELECT 1 FROM consent_forms WHERE form_key=?", (key,)
    ).fetchone():
        key = f"{base_key}_{n}"
        n += 1
    return key


def _onam_bulk_insert_row(cur, *, short, file_name, file_ext, blob,
                          size, category_internal, purpose, paper_size="A4",
                          created_by="bulk_import"):
    """consent_forms tablosuna 1 satir ekler. category_internal = display ad."""
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    key = _onam_bulk_make_key(short, cur)
    cur.execute(
        "INSERT INTO consent_forms("
        "form_key, category, short_name, file_name, file_ext, "
        "file_blob, file_size, description, paper_size, added_at, "
        "purpose, is_active, updated_at, created_by"
        ") VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (key, category_internal, short, file_name, file_ext, blob, size,
         purpose, paper_size, now, purpose, 1, now, created_by),
    )
    return key


def _onam_bulk_import_folder(folder_path, dry_run=False):
    """Sunucu tarafindan klasor tara, kategorize et ve DB'ye ekle.

    Doner: (inserted_count, skipped_count, summary_text)"""
    import os as _os
    from pathlib import Path
    folder = Path(folder_path)
    if not folder.exists() or not folder.is_dir():
        raise ValueError(f"Klasor bulunamadi veya gecersiz: {folder_path}")

    # Tum dosyalari recursive tara
    files = []
    for p in folder.rglob("*"):
        try:
            if not p.is_file():
                continue
            if p.suffix.lower() not in _ONAM_BULK_SUPPORTED_EXT:
                continue
            if p.name.startswith("._"):
                continue
            if p.name.lower() in {"thumbs.db", ".ds_store", "desktop.ini"}:
                continue
            try:
                if p.stat().st_size < 1024:
                    continue
                if p.stat().st_size > TEMPLATE_BLOB_MAX_MB * 1024 * 1024:
                    continue
            except Exception:
                continue
            if any(part.lower() in _ONAM_BULK_EXCLUDE_DIRS for part in p.parts):
                continue
            files.append(p)
        except Exception:
            continue
    files.sort()

    if not files:
        return 0, 0, f"Klasorde uygun dosya bulunamadi: {folder_path}"

    # Kategorize et
    plan = []
    by_cat = {}
    for p in files:
        snippet = _onam_read_file_snippet(p)
        parent = p.parent.name if p.parent != folder else ""
        cat, purpose = _onam_classify_bulk(p.name, snippet, parent_dir=parent)
        by_cat[cat] = by_cat.get(cat, 0) + 1
        plan.append({
            "path": p,
            "filename": p.name,
            "ext": p.suffix.lower().lstrip("."),
            "category": cat,
            "purpose": purpose,
            "size": p.stat().st_size,
            "parent": parent,
        })

    summary_bits = [f"{c}: {n}" for c, n in sorted(by_cat.items())]
    summary = ", ".join(summary_bits)

    if dry_run:
        return 0, 0, f"({len(files)} dosya) {summary}"

    # DB'ye yaz
    inserted, skipped = 0, 0
    with db_conn() as con:
        _ensure_ready_consent_schema(con)
        cur = con.cursor()
        for item in plan:
            try:
                short = item["filename"].rsplit(".", 1)[0]
                # Ayni isim + kategori varsa atla
                exists = cur.execute(
                    "SELECT 1 FROM consent_forms WHERE LOWER(short_name)=? "
                    "AND LOWER(category)=? AND COALESCE(is_active,1)=1 LIMIT 1",
                    (short.lower(), item["category"].lower()),
                ).fetchone()
                if exists:
                    skipped += 1
                    continue
                blob = item["path"].read_bytes()
                _onam_bulk_insert_row(
                    cur,
                    short=short,
                    file_name=item["filename"],
                    file_ext=item["ext"],
                    blob=blob,
                    size=item["size"],
                    category_internal=item["category"],
                    purpose=item["purpose"],
                    paper_size="A4",
                    created_by="bulk_folder_import",
                )
                inserted += 1
            except Exception:
                skipped += 1
        con.commit()
    return inserted, skipped, summary


def _onam_bulk_import_uploads(files):
    """Coklu HTTP upload'tan otomatik kategorize + DB'ye ekle.

    files: request.files.getlist("bulk_files")
    Doner: (inserted, skipped, summary_text)"""
    if not files:
        return 0, 0, "Dosya yok."

    inserted, skipped = 0, 0
    by_cat = {}
    plan = []
    for f in files:
        try:
            name = (f.filename or "").strip()
            if not name:
                skipped += 1
                continue
            ext = ("." + name.rsplit(".", 1)[-1].lower()) if "." in name else ""
            if ext not in _ONAM_BULK_SUPPORTED_EXT:
                skipped += 1
                continue
            blob = f.read()
            if not blob or len(blob) < 1024:
                skipped += 1
                continue
            if len(blob) > TEMPLATE_BLOB_MAX_MB * 1024 * 1024:
                skipped += 1
                continue
            snippet = ""
            if ext == ".pdf":
                snippet = _onam_read_pdf_snippet(blob)
            cat, purpose = _onam_classify_bulk(name, snippet)
            by_cat[cat] = by_cat.get(cat, 0) + 1
            plan.append({
                "filename": name,
                "ext": ext.lstrip("."),
                "category": cat,
                "purpose": purpose,
                "blob": blob,
                "size": len(blob),
            })
        except Exception:
            skipped += 1

    with db_conn() as con:
        _ensure_ready_consent_schema(con)
        cur = con.cursor()
        for item in plan:
            try:
                short = item["filename"].rsplit(".", 1)[0]
                exists = cur.execute(
                    "SELECT 1 FROM consent_forms WHERE LOWER(short_name)=? "
                    "AND LOWER(category)=? AND COALESCE(is_active,1)=1 LIMIT 1",
                    (short.lower(), item["category"].lower()),
                ).fetchone()
                if exists:
                    skipped += 1
                    continue
                _onam_bulk_insert_row(
                    cur,
                    short=short,
                    file_name=item["filename"],
                    file_ext=item["ext"],
                    blob=item["blob"],
                    size=item["size"],
                    category_internal=item["category"],
                    purpose=item["purpose"],
                    paper_size="A4",
                    created_by="bulk_upload",
                )
                inserted += 1
            except Exception:
                skipped += 1
        con.commit()
    summary = ", ".join(f"{c}: {n}" for c, n in sorted(by_cat.items()))
    return inserted, skipped, summary


def _ensure_ready_consent_schema(con=None):
    def _run(open_con):
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS consent_forms (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                category TEXT NOT NULL,
                short_name TEXT NOT NULL,
                file_name TEXT NOT NULL,
                file_ext TEXT NOT NULL,
                file_blob BLOB NOT NULL,
                file_size INTEGER DEFAULT 0,
                description TEXT DEFAULT '',
                paper_size TEXT DEFAULT 'A4',
                added_at TEXT NOT NULL,
                last_printed_at TEXT,
                print_count INTEGER DEFAULT 0
            )
        """)
        columns = {
            str(r[1]) for r in
            open_con.execute("PRAGMA table_info(consent_forms)").fetchall()
        }
        for col, ddl in (
            ("form_key", "ALTER TABLE consent_forms ADD COLUMN form_key TEXT"),
            ("purpose", "ALTER TABLE consent_forms ADD COLUMN purpose TEXT"),
            ("is_active", "ALTER TABLE consent_forms ADD COLUMN is_active INTEGER DEFAULT 1"),
            ("updated_at", "ALTER TABLE consent_forms ADD COLUMN updated_at TEXT"),
            ("created_by", "ALTER TABLE consent_forms ADD COLUMN created_by TEXT"),
            ("usage_count", "ALTER TABLE consent_forms ADD COLUMN usage_count INTEGER DEFAULT 0"),
            ("last_used_at", "ALTER TABLE consent_forms ADD COLUMN last_used_at TEXT"),
        ):
            if col not in columns:
                try:
                    open_con.execute(ddl)
                except Exception:
                    pass
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_ready_consent_active
            ON consent_forms(is_active, category, short_name)
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_ready_consent_key
            ON consent_forms(form_key)
        """)
        now = datetime.now().isoformat(sep=" ", timespec="seconds")
        try:
            open_con.execute(
                "UPDATE consent_forms SET purpose=COALESCE(NULLIF(purpose,''), "
                "description, ''), updated_at=COALESCE(updated_at, ?), "
                "is_active=COALESCE(is_active, 1) "
                "WHERE purpose IS NULL OR purpose='' OR updated_at IS NULL "
                "OR is_active IS NULL",
                (now,))
        except Exception:
            pass

    if con is not None:
        _run(con)
        return
    with db_conn() as open_con:
        _run(open_con)
        open_con.commit()


def _list_ready_consent_forms(include_inactive=False, query=""):
    _ensure_ready_consent_schema()
    q = str(query or "").strip().lower()
    where = []
    params = []
    if not include_inactive:
        where.append("COALESCE(is_active,1)=1")
    if q:
        like = f"%{q}%"
        where.append(
            "(LOWER(short_name) LIKE ? OR LOWER(purpose) LIKE ? OR "
            "LOWER(category) LIKE ? OR LOWER(description) LIKE ?)")
        params.extend([like, like, like, like])
    clause = ("WHERE " + " AND ".join(where)) if where else ""
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        # D250 2026-05-12: Kategori alfabetik, ICINDE en cok kullanilanlar
        # ustte. Tiebreak: en son kullanilan, sonra alfabetik isim.
        # use_score = usage_count + print_count (tum kullanim sayilarinin
        # toplami) - bazi formlar eski "print_count"u kullanmis olabilir.
        rows = con.execute(
            "SELECT id, category, short_name, file_name, file_ext, file_size, "
            "description, paper_size, added_at, last_printed_at, print_count, "
            "form_key, purpose, is_active, updated_at, created_by, usage_count, "
            "last_used_at, "
            "(COALESCE(usage_count,0) + COALESCE(print_count,0)) AS use_score "
            "FROM consent_forms "
            f"{clause} ORDER BY "
            "  category COLLATE NOCASE ASC, "
            "  use_score DESC, "
            "  COALESCE(last_used_at, last_printed_at, '') DESC, "
            "  short_name COLLATE NOCASE ASC",
            params).fetchall()
    out = []
    for row in rows:
        item = dict(row)
        item["category"] = _normalize_ready_consent_category(
            item.get("category"))
        if not item.get("purpose"):
            item["purpose"] = item.get("description") or ""
        out.append(item)
    return out


def _save_ready_consent_form(form, upload=None, form_id=None):
    name = (form.get("name") or form.get("short_name") or "").strip()
    purpose = (form.get("purpose") or "").strip()
    category = _normalize_ready_consent_category(form.get("category"))
    description = (form.get("description") or purpose).strip()
    paper_size = (form.get("paper_size") or "A4").strip() or "A4"
    if not name:
        raise ValueError("Onam form adi zorunlu.")
    if not purpose:
        raise ValueError("Onam formunun ne icin oldugu zorunlu.")
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    file_name = file_ext = None
    blob = None
    file_size = None
    if upload and upload.filename:
        file_name = _safe_upload_filename(upload.filename, fallback="onam")
        file_ext = Path(file_name).suffix.lower().lstrip(".") or "bin"
        blob = upload.read()
        file_size = len(blob or b"")
        _validate_template_blob_upload(
            file_name, file_ext, blob, "Onam formu")
    if not form_id and not blob:
        raise ValueError("Yeni onam formu icin dosya yuklemek zorunlu.")
    with db_conn() as con:
        _ensure_ready_consent_schema(con)
        if form_id:
            sets = [
                "category=?", "short_name=?", "description=?",
                "paper_size=?", "purpose=?", "updated_at=?",
                "is_active=1",
            ]
            params = [category, name, description, paper_size, purpose, now]
            if blob is not None:
                sets.extend([
                    "file_name=?", "file_ext=?", "file_blob=?", "file_size=?",
                ])
                params.extend([file_name, file_ext, blob, file_size])
            params.append(form_id)
            con.execute(
                f"UPDATE consent_forms SET {', '.join(sets)} WHERE id=?",
                params)
        else:
            key = _consent_form_key(name)
            base = key
            suffix = 2
            while con.execute(
                    "SELECT 1 FROM consent_forms WHERE form_key=?",
                    (key,)).fetchone():
                key = f"{base}_{suffix}"
                suffix += 1
            con.execute(
                "INSERT INTO consent_forms("
                "form_key, category, short_name, file_name, file_ext, "
                "file_blob, file_size, description, paper_size, added_at, "
                "purpose, is_active, updated_at, created_by"
                ") VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (key, category, name, file_name, file_ext, blob,
                 file_size or 0, description, paper_size, now, purpose, 1,
                 now, session.get("user", "?")))
        con.commit()


def _ready_consent_file_blob(form_id):
    _ensure_ready_consent_schema()
    with db_conn() as con:
        row = con.execute(
            "SELECT file_blob, file_name, file_ext "
            "FROM consent_forms WHERE id=? AND COALESCE(is_active,1)=1",
            (form_id,)).fetchone()
    if row and row[0]:
        return row[0], row[1] or "onam", (row[2] or "bin").lower()
    return None


def _record_ready_consent_use(form_id):
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    try:
        with db_conn() as con:
            _ensure_ready_consent_schema(con)
            con.execute(
                "UPDATE consent_forms SET "
                "print_count=COALESCE(print_count,0)+1, "
                "usage_count=COALESCE(usage_count,0)+1, "
                "last_printed_at=?, last_used_at=? WHERE id=?",
                (now, now, form_id))
            con.commit()
    except Exception:
        pass


_DB_PRINTABLE_MIME_TYPES = {
    "pdf": "application/pdf",
    "txt": "text/plain; charset=utf-8",
    "jpg": "image/jpeg",
    "jpeg": "image/jpeg",
    "png": "image/png",
    "doc": "application/msword",
    "docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
}
_DB_PRINTABLE_INLINE_EXTS = {"pdf", "txt", "jpg", "jpeg", "png"}


_ONAM_CP437_UTF8_MARKERS = (
    "\u2500", "\u2502", "\u250c", "\u2510", "\u2514", "\u2518",
    "\u2524", "\u2534", "\u253c", "\u2550", "\u2551", "\u2554",
    "\u2557", "\u255a", "\u255d", "\u2560", "\u2563", "\u2566",
    "\u2569", "\u256c", "\u2591", "\u2592", "\u2593",
)


def _onam_display_text(value):
    """Fix consent metadata shown in the UI, including CP437/UTF-8 mixups."""
    text = fix_mojibake_text(str(value or ""))
    if not text:
        return ""
    text = unicodedata.normalize("NFC", text)
    if not any(marker in text for marker in _ONAM_CP437_UTF8_MARKERS):
        return text

    def _score(candidate):
        return (
            sum(candidate.count(marker) for marker in _ONAM_CP437_UTF8_MARKERS)
            + candidate.count("\ufffd") * 4
            + candidate.count("?")
        )

    best = text
    best_score = _score(best)
    for enc in ("cp437", "cp850", "cp857"):
        try:
            candidate = text.encode(enc).decode("utf-8")
        except Exception:
            continue
        candidate = unicodedata.normalize("NFC", fix_mojibake_text(candidate))
        score = _score(candidate)
        if score < best_score:
            best = candidate
            best_score = score
    return best


def _db_printable_bytes(blob):
    if blob is None:
        return b""
    if isinstance(blob, bytes):
        return blob
    if isinstance(blob, bytearray):
        return bytes(blob)
    if isinstance(blob, memoryview):
        return blob.tobytes()
    if isinstance(blob, str):
        return blob.encode("utf-8", "replace")
    try:
        return bytes(blob)
    except Exception:
        return b""


def _db_printable_mime(file_name, file_ext):
    ext = str(file_ext or "").lower().strip().lstrip(".")
    if ext in _DB_PRINTABLE_MIME_TYPES:
        return _DB_PRINTABLE_MIME_TYPES[ext]
    try:
        import mimetypes
        guessed, _ = mimetypes.guess_type(str(file_name or ""))
        if guessed:
            return guessed
    except Exception:
        pass
    return "application/octet-stream"


def _send_db_printable_blob(blob, file_name, file_ext, *, download=False):
    data = _db_printable_bytes(blob)
    if not data:
        abort(404)
    ext = str(file_ext or "").lower().strip().lstrip(".")
    display_name = _onam_display_text(file_name)
    safe_name = Path(str(display_name or "")).name.strip() or f"onam.{ext or 'bin'}"
    if ext and not Path(safe_name).suffix:
        safe_name = f"{safe_name}.{ext}"
    force_download = bool(download) or ext not in _DB_PRINTABLE_INLINE_EXTS
    response = send_file(
        BytesIO(data),
        mimetype=_db_printable_mime(safe_name, ext),
        as_attachment=force_download,
        download_name=safe_name,
        max_age=0,
        conditional=False,
    )
    response.headers["Cache-Control"] = "no-store, max-age=0"
    response.headers["X-Content-Type-Options"] = "nosniff"
    return response


def _onam_docx_text_from_bytes(data):
    """Best-effort DOCX preview text without external dependencies."""
    try:
        import zipfile
        import xml.etree.ElementTree as ET
        with zipfile.ZipFile(BytesIO(data)) as zf:
            xml_data = zf.read("word/document.xml")
        root = ET.fromstring(xml_data)
        lines = []
        for para in root.iter():
            if not str(para.tag).endswith("}p"):
                continue
            parts = []
            for node in para.iter():
                tag = str(node.tag)
                if tag.endswith("}t") and node.text:
                    parts.append(node.text)
                elif tag.endswith("}tab"):
                    parts.append(" ")
                elif tag.endswith("}br"):
                    parts.append("\n")
            line = "".join(parts).strip()
            if line:
                lines.append(line)
        return "\n".join(lines).strip()
    except Exception:
        return ""


def _onam_doc_text_from_bytes(data):
    """Very small fallback for legacy .doc files; keeps Ac from downloading."""
    if not data:
        return ""
    candidates = []
    for enc in ("utf-8", "cp1254", "latin-1", "utf-16le"):
        try:
            text = data.decode(enc, errors="ignore")
        except Exception:
            continue
        printable = sum(1 for ch in text if ch.isprintable() or ch in "\r\n\t")
        candidates.append((printable, text))
    text = max(candidates, key=lambda item: item[0])[1] if candidates else ""
    text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]+", " ", text)
    text = re.sub(r"[ \t]{2,}", " ", text)
    lines = []
    for line in re.split(r"[\r\n]+", text):
        line = line.strip()
        if len(line) >= 3 and not re.fullmatch(r"[\W_]+", line):
            lines.append(line)
    if len(lines) < 4:
        chunks = re.findall(rb"[ -~\x80-\xff]{4,}", data)
        lines = []
        for chunk in chunks[:600]:
            try:
                line = chunk.decode("cp1254", errors="ignore").strip()
            except Exception:
                continue
            line = re.sub(r"\s+", " ", line)
            if len(line) >= 3 and not re.fullmatch(r"[\W_]+", line):
                lines.append(line)
    return "\n".join(lines[:900]).strip()


def _onam_text_from_blob(data, ext):
    ext = (ext or "").lower().lstrip(".")
    if ext == "docx":
        return _onam_docx_text_from_bytes(data)
    if ext == "doc":
        return _onam_doc_text_from_bytes(data)
    for enc in ("utf-8", "cp1254", "latin-1"):
        try:
            return data.decode(enc, errors="ignore").strip()
        except Exception:
            pass
    return ""


def _onam_viewer_response(form_id, blob, file_name, file_ext, *,
                          autoprint=False):
    data = _db_printable_bytes(blob)
    if not data:
        abort(404)
    ext = str(file_ext or "").lower().strip().lstrip(".")
    safe_name = Path(str(file_name or "")).name.strip() or f"onam_{form_id}"
    raw_url = url_for("open_consent_file", form_id=form_id)
    download_url = url_for("download_consent", form_id=form_id)
    print_url = url_for("print_consent", form_id=form_id)
    title = safe_html(safe_name)
    raw_attr = safe_attr(raw_url)
    download_attr = safe_attr(download_url)
