@app.route("/onam-sablonlari", methods=["GET", "POST"])
@permission_required("view_consent")
def ready_consent_forms_page():
    patient_key = (request.values.get("patient") or "").strip()
    if request.method == "POST":
        if not can("edit_consent"):
            flash("Onam formu duzenleme yetkiniz yok.", "danger")
            return redirect(url_for("ready_consent_forms_page",
                                    patient=patient_key))
        action = (request.form.get("action") or "save").strip()
        try:
            if action == "delete":
                form_id = _int_or_none(request.form.get("form_id"))
                if form_id:
                    with db_conn() as con:
                        _ensure_ready_consent_schema(con)
                        con.execute(
                            "UPDATE consent_forms SET is_active=0, "
                            "updated_at=? WHERE id=?",
                            (datetime.now().isoformat(
                                sep=" ", timespec="seconds"), form_id))
                        con.commit()
                    flash("Onam formu pasife alindi.", "warning")
            elif action == "bulk_folder_import":
                # D250 2026-05-12: Sunucu tarafindan klasor tara + kategorize
                folder_path = (request.form.get("folder_path") or "").strip()
                dry_run = bool(request.form.get("dry_run"))
                if not folder_path:
                    flash("Klasor yolu bos.", "danger")
                else:
                    inserted, skipped, summary = _onam_bulk_import_folder(
                        folder_path, dry_run=dry_run)
                    if dry_run:
                        flash(f"[Onizleme] {summary}", "info")
                    else:
                        flash(
                            f"Toplu import: {inserted} eklendi, {skipped} atlandi. {summary}",
                            "success")
            elif action == "bulk_upload":
                # D250 2026-05-12: Coklu dosya upload + otomatik kategorize
                files = request.files.getlist("bulk_files")
                files = [f for f in files if f and f.filename]
                if not files:
                    flash("Hicbir dosya secilmedi.", "warning")
                else:
                    inserted, skipped, summary = _onam_bulk_import_uploads(files)
                    flash(
                        f"Toplu upload: {inserted} eklendi, {skipped} atlandi. {summary}",
                        "success")
            else:
                form_id = _int_or_none(request.form.get("form_id"))
                _save_ready_consent_form(
                    request.form,
                    upload=request.files.get("source_file"),
                    form_id=form_id)
                flash("Onam formu database'e kaydedildi.", "success")
        except Exception as ex:
            flash(f"Kayit hatasi: {ex}", "danger")
        return redirect(url_for("ready_consent_forms_page",
                                patient=patient_key))

    q = (request.args.get("q") or "").strip()
    forms = _list_ready_consent_forms(query=q)
    category_options = ""
    for cat in READY_CONSENT_CATEGORIES:
        category_options += f'<option value="{sh(cat)}">{sh(cat)}</option>'

    create_html = ""
    if can("edit_consent"):
        create_html = f"""
        <form method="POST" enctype="multipart/form-data" class="card mb-4">
          <div class="card-header yk-safe-head"><b>Yeni onam formu yukle / kaydet</b></div>
          <div class="card-body row g-3">
            <input type="hidden" name="action" value="save">
            <input type="hidden" name="patient" value="{sh(patient_key)}">
            <div class="col-md-4">
              <label class="form-label">Onam form adi</label>
              <input name="name" class="form-control" required
                     placeholder="Orn: Gebelik takip onami">
            </div>
            <div class="col-md-4">
              <label class="form-label">Ne icin?</label>
              <input name="purpose" class="form-control" required
                     placeholder="Orn: Gebelik takibi ve ultrason izni">
            </div>
            <div class="col-md-4">
              <label class="form-label">Grup</label>
              <select name="category" class="form-select">{category_options}</select>
            </div>
            <div class="col-md-8">
              <label class="form-label">Aciklama / not</label>
              <input name="description" class="form-control"
                     placeholder="Kisa klinik not veya kullanim aciklamasi">
            </div>
            <div class="col-md-4">
              <label class="form-label">Kagit</label>
              <select name="paper_size" class="form-select">
                <option value="A4">A4</option>
                <option value="A5">A5</option>
              </select>
            </div>
            <div class="col-md-12">
              <label class="form-label">Onam dosyasi</label>
              <input type="file" name="source_file" class="form-control"
                     accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png" required>
              <small class="text-muted">
                Dosya database icine BLOB olarak saklanir; kategori ve ne icin
                bilgisi listede aranabilir kalir. DB sismemesi icin dosya
                siniri: {TEMPLATE_BLOB_MAX_MB} MB.
              </small>
            </div>
            <div class="col-12">
              <button class="btn btn-success">Onam formunu database'e kaydet</button>
            </div>
          </div>
        </form>
        """

    # D250 2026-05-12: Kategoriye gore grupla ve her grup icinde
    # sirayi koru (server zaten use_score DESC ile sorted donduruyor).
    # Her kategori bir baslik satiri + altina o gruba ait formlar.
    forms_by_cat = {}
    cat_order = []
    for item in forms:
        cat = item.get("category") or "Diger"
        if cat not in forms_by_cat:
            forms_by_cat[cat] = []
            cat_order.append(cat)
        forms_by_cat[cat].append(item)

    # Kategori icon eslemesi (cat name -> bi-* icon)
    _cat_icons = {
        "Gebelik": "bi-balloon-heart",
        "Infertilite": "bi-droplet-half",
        "Jinekoloji": "bi-flower1",
        "Jinekolojik Estetik": "bi-gem",
        "Medikal Estetik": "bi-stars",
        "Paylasim Izinleri": "bi-shield-check",
        "Diger": "bi-folder",
    }

    def _use_score(it):
        return int(it.get("use_score")
                   or (int(it.get("usage_count") or 0)
                       + int(it.get("print_count") or 0)))

    rows = ""
    for cat in cat_order:
        items = forms_by_cat[cat]
        if not items:
            continue
        display_cat = _onam_display_text(cat)
        icon = _cat_icons.get(cat, "bi-folder")
        # Kategori basligi satiri
        rows += (
            f'<tr class="yk-onam-cat-row table-secondary">'
            f'  <td colspan="5">'
            f'    <i class="bi {icon}"></i> <b>{sh(display_cat)}</b> '
            f'    <small class="text-muted">({len(items)} form '
            f'    - en cok kullanilan ustte)</small>'
            f'  </td>'
            f'</tr>'
        )

        for rank, item in enumerate(items, 1):
            form_id = int(item.get("id") or 0)
            size_kb = (item.get("file_size", 0) or 0) / 1024
            display_short = _onam_display_text(item.get("short_name") or "")
            display_purpose = _onam_display_text(
                item.get("purpose") or item.get("description") or "")
            display_desc = _onam_display_text(item.get("description") or "")
            display_file = _onam_display_text(item.get("file_name") or "")
            display_ext = _onam_display_text(item.get("file_ext") or "bin")
            file_label = f"{display_ext or 'bin'} - {size_kb:.0f} KB"
            use_count = _use_score(item)
            # En cok kullanilan ilk 3 icin altin/gumus/bronz rozet
            rank_badge = ""
            if rank == 1 and use_count > 0:
                rank_badge = '<span class="badge bg-warning text-dark me-1" title="En cok kullanilan"><i class="bi bi-trophy-fill"></i> #1</span>'
            elif rank == 2 and use_count > 0:
                rank_badge = '<span class="badge bg-secondary me-1" title="2. en cok kullanilan">#2</span>'
            elif rank == 3 and use_count > 0:
                rank_badge = '<span class="badge bg-secondary me-1" title="3. en cok kullanilan">#3</span>'

            # Use count badge (renkli)
            if use_count >= 20:
                use_badge_cls = "bg-success"
            elif use_count >= 5:
                use_badge_cls = "bg-info text-dark"
            elif use_count >= 1:
                use_badge_cls = "bg-light text-dark border"
            else:
                use_badge_cls = "bg-light text-muted border"
            use_badge = (
                f'<span class="badge {use_badge_cls}" '
                f'title="Toplam kullanim sayisi">'
                f'<i class="bi bi-bar-chart-fill"></i> {use_count}</span>')
            edit_html = ""
            if can("edit_consent"):
                cat_opts = ""
                for cat_o in READY_CONSENT_CATEGORIES:
                    sel = "selected" if cat_o == (item.get("category") or "") else ""
                    cat_opts += f'<option value="{sh(cat_o)}" {sel}>{sh(cat_o)}</option>'
                a4_sel = "selected" if (item.get("paper_size") or "A4") == "A4" else ""
                a5_sel = "selected" if (item.get("paper_size") or "") == "A5" else ""
                edit_html = f"""
                <details class="mt-2">
                  <summary>Duzenle</summary>
                  <form method="POST" enctype="multipart/form-data" class="row g-2 mt-2">
                    <input type="hidden" name="action" value="save">
                    <input type="hidden" name="form_id" value="{form_id}">
                    <input type="hidden" name="patient" value="{sh(patient_key)}">
                     <div class="col-md-4">
                       <input name="name" class="form-control"
                              value="{sh(display_short)}" required>
                     </div>
                     <div class="col-md-4">
                       <input name="purpose" class="form-control"
                              value="{sh(display_purpose)}" required>
                     </div>
                    <div class="col-md-4">
                      <select name="category" class="form-select">{cat_opts}</select>
                    </div>
                     <div class="col-md-8">
                       <input name="description" class="form-control"
                              value="{sh(display_desc)}">
                     </div>
                    <div class="col-md-4">
                      <select name="paper_size" class="form-select">
                        <option value="A4" {a4_sel}>A4</option>
                        <option value="A5" {a5_sel}>A5</option>
                      </select>
                    </div>
                    <div class="col-md-12">
                      <input type="file" name="source_file" class="form-control">
                    </div>
                    <div class="col-12 d-flex gap-2">
                      <button class="btn btn-sm btn-primary">Kaydet</button>
                    </div>
                  </form>
                  <form method="POST" class="mt-2">
                    <input type="hidden" name="action" value="delete">
                    <input type="hidden" name="form_id" value="{form_id}">
                    <input type="hidden" name="patient" value="{sh(patient_key)}">
                    <button class="btn btn-sm btn-outline-danger"
                            onclick="return confirm('Bu onam formu pasife alinsin mi?');">
                      Pasife al
                    </button>
                  </form>
                </details>
                """
            rows += f"""
            <tr data-onam-cat="{sh(item.get('category') or '')}" data-onam-use="{use_count}">
              <td>
                {rank_badge}<b>{sh(display_short)}</b>
              </td>
              <td>{sh(display_purpose)}</td>
              <td><small>{sh(file_label)}<br>{sh(display_file)}</small></td>
              <td>{use_badge}</td>
              <td class="text-end">
                <div class="btn-group btn-group-sm">
                  <a href="/onam/ac/{form_id}" class="btn btn-primary" target="_blank">Ac</a>
                  <a href="/onam/yazdir/{form_id}" class="btn btn-success" target="_blank"
                     title="Yeni sekmede ac ve baski penceresini ac">
                    <i class="bi bi-printer"></i> Baski
                  </a>
                  <a href="/onam/indir/{form_id}" class="btn btn-outline-primary">Indir</a>
                </div>
                {edit_html}
              </td>
            </tr>
            """

    back_url = f"/hasta/{quote(patient_key, safe='')}/onam" if patient_key else "/"
    patient_btn = ""
    if patient_key:
        patient_btn = (
            f'<a class="btn btn-outline-success" '
            f'href="/hasta/{quote(patient_key, safe="")}/onam">'
            f'Secili hastanin onam ekranina don</a>')
    content = f"""
    <style>
      .yk-consent-db .yk-safe-head > b {{
        display:inline-block;
        padding-left:6px;
      }}
      .yk-consent-db h2 {{
        display:inline-block;
        padding-left:4px;
      }}
      .yk-consent-db .alert.alert-info {{
        padding-left: calc(var(--space-5, 20px) + 6px);
      }}
      /* D250 2026-05-12: Kategori bant satiri ve kullanim rozet stilleri */
      .yk-consent-db .yk-onam-cat-row td {{
        font-size: 14px;
        padding: 10px 14px;
        background: linear-gradient(90deg, #f1f5f9 0%, #ffffff 100%);
        border-top: 2px solid #94a3b8;
      }}
      .yk-consent-db .yk-onam-cat-row b {{
        font-size: 15px;
        letter-spacing: 0.02em;
      }}
      .yk-consent-db .yk-onam-cat-row i.bi {{
        color: #0EA5E9;
        margin-right: 4px;
      }}
      [data-theme="dark"] .yk-consent-db .yk-onam-cat-row td {{
        background: linear-gradient(90deg, #1f2937 0%, #0f172a 100%);
        border-top: 2px solid #475569;
        color: #e2e8f0;
      }}
      .yk-consent-db tr[data-onam-use] td {{
        vertical-align: middle;
      }}
      .yk-consent-db .badge .bi-trophy-fill {{
        margin-right: 2px;
      }}
    </style>
    <div class="yk-consent-db">
    <a href="{back_url}" class="btn btn-secondary mb-3">Geri</a>
    <div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3">
      <h2 class="mb-0">Onam Formlari Database</h2>
      {patient_btn}
    </div>
    <div class="alert alert-info">
      Gruplar: <b>Gebelik</b>, <b>Jinekoloji</b>, <b>Jinekolojik Estetik</b>,
      <b>Medikal Estetik</b>, Infertilite, Paylasim Izinleri.
      <br>
      <small>
      <b>Siralama:</b> Her kategori icinde <b>en cok kullanilan onam ustte</b>
      (kullanim ve baski sayisi toplami). Tiebreak: en son kullanilan, sonra
      alfabetik. Ilk 3'te <i class="bi bi-trophy-fill text-warning"></i> rozet,
      kullanim sayisi yaninda renkli badge (yesil = cok kullanilan).
      "Ac" onami program icinde goruntuler; "Baski" A4 yazdirma modunu acar;
      "Indir" sadece dosya indirmek icindir.
      </small>
    </div>
    <form method="GET" class="input-group mb-3">
      <input type="hidden" name="patient" value="{sh(patient_key)}">
      <input name="q" class="form-control" value="{sh(q)}"
             placeholder="Onam adi, ne icin, grup veya aciklama ara">
      <button class="btn btn-primary">Ara</button>
    </form>

    {_onam_bulk_import_panel_html(patient_key) if can("edit_consent") else ""}

    {create_html}
    <div class="card">
      <div class="card-header yk-safe-head"><b>Database onam formlari ({len(forms)})</b></div>
      <div class="card-body p-0">
        <table class="table table-hover align-middle mb-0 yk-edge-safe-table">
          <thead class="table-light">
            <tr><th>Form adi / grup</th><th>Ne icin</th><th>Dosya</th><th>Kullanim</th><th class="text-end">Islem</th></tr>
          </thead>
          <tbody>{rows or '<tr><td colspan="5" class="p-4 text-muted">Onam formu yok.</td></tr>'}</tbody>
        </table>
      </div>
    </div>
    </div>
    """
    return render(content, title="Onam Formlari")


@app.route("/onam/ac/<int:form_id>")
@permission_required("view_consent")
def open_consent(form_id):
    """Onam formunu program icinde ac; indirme sadece /onam/indir yolunda."""
    try:
        result = _ready_consent_file_blob(form_id)
        if not result:
            flash("Form bulunamadÄ±.", "danger")
            return redirect(request.referrer or url_for("ready_consent_forms_page"))
        blob, file_name, file_ext = result
        _record_ready_consent_use(form_id)
        return _onam_viewer_response(
            form_id, blob, file_name, file_ext, autoprint=False)
    except Exception as ex:
        flash(f"Acma hatasi: {ex}", "danger")
        return redirect(request.referrer or url_for("ready_consent_forms_page"))


@app.route("/onam/dosya/<int:form_id>")
@permission_required("view_consent")
def open_consent_file(form_id):
    """Viewer icin ham dosya. Download zorlamaz; Indir route'u ayri."""
    try:
        result = _ready_consent_file_blob(form_id)
        if not result:
            abort(404)
        blob, file_name, file_ext = result
        return _send_db_printable_blob(
            blob, file_name, file_ext, download=False)
    except Exception:
        abort(404)


@app.route("/onam/indir/<int:form_id>")
@permission_required("view_consent")
def download_consent(form_id):
    """Onam formunu guvenli sekilde indir."""
    try:
        result = _ready_consent_file_blob(form_id)
        if not result:
            flash("Form bulunamadÄ±.", "danger")
            return redirect(request.referrer or url_for("ready_consent_forms_page"))
        blob, file_name, file_ext = result
        _record_ready_consent_use(form_id)
        return _send_db_printable_blob(
            blob, file_name, file_ext, download=True)
    except Exception as ex:
        flash(f"Indirme hatasi: {ex}", "danger")
        return redirect(request.referrer or url_for("ready_consent_forms_page"))


@app.route("/onam/yazdir/<int:form_id>")
@permission_required("view_consent")
def print_consent(form_id):
    """Onami A4 baski modunda ac; DOC/DOCX indirme yerine preview basar."""
    try:
        result = _ready_consent_file_blob(form_id)
        if not result:
            flash("Form bulunamadi.", "danger")
            return redirect(
                request.referrer or url_for("ready_consent_forms_page"))
        blob, file_name, file_ext = result
        _record_ready_consent_use(form_id)
        return _onam_viewer_response(
            form_id, blob, file_name, file_ext, autoprint=True)
    except Exception as ex:
        flash(f"Baski hatasi: {ex}", "danger")
        return redirect(
            request.referrer or url_for("ready_consent_forms_page"))


