_RX_CATALOG_FILE_CACHE = {}
_RX_TEXT_FOLD_CACHE = {}
_RX_MOJIBAKE_FIX_CACHE = {}
_RX_CATALOG_WARMED = False


def _rx_fold_cached(value):
    text = str(value or "")
    cached = _RX_TEXT_FOLD_CACHE.get(text)
    if cached is not None:
        return cached
    folded = _fold_search_text(text)
    if len(_RX_TEXT_FOLD_CACHE) > 80000:
        _RX_TEXT_FOLD_CACHE.clear()
    _RX_TEXT_FOLD_CACHE[text] = folded
    return folded


def _rx_mojibake_fix_cached(value):
    """D120 perf: katalog hot path icin fix_mojibake_text wrapper'i.
    Per-sorgu 19K entry'de tekrar tekrar fix yerine sonucu cachle."""
    if not isinstance(value, str) or not value:
        return value
    cached = _RX_MOJIBAKE_FIX_CACHE.get(value)
    if cached is not None:
        return cached
    fixed = fix_mojibake_text(value)
    if len(_RX_MOJIBAKE_FIX_CACHE) > 80000:
        _RX_MOJIBAKE_FIX_CACHE.clear()
    _RX_MOJIBAKE_FIX_CACHE[value] = fixed
    return fixed


def _rx_catalog_file_lines(file_name):
    path = Path(__file__).with_name("static") / str(file_name or "")
    try:
        if not path.exists() or not path.is_file():
            return []
        stat = path.stat()
        signature = (str(path), int(stat.st_mtime), int(stat.st_size))
        cached = _RX_CATALOG_FILE_CACHE.get(str(path))
        if cached and cached.get("signature") == signature:
            return list(cached.get("lines") or [])
        lines = []
        with path.open("r", encoding="utf-8", errors="ignore") as fh:
            for raw in fh:
                clean = str(raw or "").strip()
                if not clean or clean.startswith("#"):
                    continue
                lines.append(clean)
        _RX_CATALOG_FILE_CACHE[str(path)] = {
            "signature": signature,
            "lines": tuple(lines),
        }
        return lines
    except Exception:
        return []


def _rx_iter_catalog_file_lines(file_name):
    for clean in _rx_catalog_file_lines(file_name):
        yield clean


def _rx_warm_catalog_cache_async():
    global _RX_CATALOG_WARMED
    if _RX_CATALOG_WARMED:
        return
    _RX_CATALOG_WARMED = True

    def _worker():
        for catalog_file in (
                RX_DIAGNOSIS_CATALOG_FILES + RX_MEDICATION_CATALOG_FILES):
            for raw in _rx_catalog_file_lines(catalog_file):
                fixed = _rx_mojibake_fix_cached(raw).strip()
                _rx_fold_cached(fixed)
                if "|" in raw:
                    for part in raw.split("|", 2):
                        fixed_part = _rx_mojibake_fix_cached(part).strip()
                        _rx_fold_cached(fixed_part)

    try:
        _perf_singleflight_async("rx_catalog_warm", _worker)
    except Exception:
        try:
            _worker()
        except Exception:
            pass


def _rx_catalog_limit(limit):
    if limit is None:
        return None
    try:
        value = int(limit)
    except Exception:
        return None
    return max(0, value)


def _rx_catalog_query_fold(query):
    return _fold_search_text(str(query or "").strip())


