def _rx_catalog_query_plan(query_fold):
    query_fold = str(query_fold or "")
    cached = _RX_QUERY_PLAN_CACHE.get(query_fold)
    if cached is not None:
        return cached
    query_tokens = [
        tok for tok in re.findall(r"[a-z0-9]+", query_fold)
        if len(tok) >= 2
    ]
    token_groups = []
    for token in query_tokens:
        group = [token]
        group.extend(_RX_QUERY_SYNONYMS.get(token, ()))
        group = [_rx_fold_cached(alias) for alias in group]
        token_groups.append(group)
    plan = (tuple(query_tokens), tuple(tuple(group) for group in token_groups))
    if len(_RX_QUERY_PLAN_CACHE) > 2048:
        _RX_QUERY_PLAN_CACHE.clear()
    _RX_QUERY_PLAN_CACHE[query_fold] = plan
    return plan


def _rx_catalog_matches(query_fold, *values):
    if not query_fold:
        return True
    query_tokens, token_groups = _rx_catalog_query_plan(query_fold)
    for value in values:
        folded_value = _rx_fold_cached(value)
        if query_fold in folded_value:
            return True
        if query_tokens and all(tok in folded_value for tok in query_tokens):
            return True
        if token_groups and all(
                any(alias in folded_value for alias in group)
                for group in token_groups):
            return True
    return False


def _rx_catalog_score(query_fold, *values):
    if not query_fold:
        return 0
    query_tokens, token_groups = _rx_catalog_query_plan(query_fold)
    best = None
    for value_index, value in enumerate(values):
        folded_value = _rx_fold_cached(value)
        if not folded_value:
            continue
        words = [word for word in re.findall(r"[a-z0-9]+", folded_value) if word]
        score = None
        if folded_value == query_fold:
            score = 0
        elif folded_value.startswith(query_fold):
            score = 4
        elif any(word.startswith(query_fold) for word in words):
            score = 8
        elif query_fold in folded_value:
            score = 32 + folded_value.find(query_fold)
        elif query_tokens and all(
                token in folded_value or any(word.startswith(token) for word in words)
                for token in query_tokens):
            score = 58
        elif token_groups and all(
                any(
                    alias and (
                        alias in folded_value or any(word.startswith(alias) for word in words))
                    for alias in group)
                for group in token_groups):
            score = 78
        if score is not None:
            score += value_index * 7
            score += min(len(folded_value), 220) / 1000.0
            best = score if best is None else min(best, score)
    return best if best is not None else 9999


def _rx_catalog_option_value(item):
    if isinstance(item, dict):
        parts = [
            str(item.get("name") or "").strip(),
            str(item.get("dose") or "").strip(),
            str(item.get("meta") or "").strip(),
        ]
        return " ".join(p for p in parts if p)
    return str(item or "").strip()


RX_DIAGNOSIS_CATALOG_FILES = (
    "tr_icd10_katalogu.txt",
    "tr_tani_katalogu.txt",
)
RX_MEDICATION_CATALOG_FILES = (
    "tr_ilac_katalogu_titck.txt",
    "tr_ilac_katalogu.txt",
)


def _rx_all_diagnoses(limit=None, query=""):
    max_items = _rx_catalog_limit(limit)
    if max_items == 0:
        return []
    query_fold = _rx_catalog_query_fold(query)
    collect_limit = max_items
    if query_fold and max_items is not None:
        collect_limit = min(max(max_items * 5, 500), 2200)
    cache_key = f"rx_search_diagnosis_{max_items}_{query_fold}"
    try:
        cached = cache_get(cache_key)
        if cached is not None:
            return list(cached)
    except Exception:
        pass
    results = []
    seen = set()

    def _at_limit():
        return collect_limit is not None and len(results) >= collect_limit

    def _add(text):
        if _at_limit():
            return
        value = _rx_mojibake_fix_cached(str(text or "")).strip()
        if not value:
            return
        if not _rx_catalog_matches(query_fold, value):
            return
        key = _rx_fold_cached(value)
        if key in seen:
            return
        seen.add(key)
        results.append(value)

    for item in RX_COMMON_DIAGNOSES:
        _add(item)
        if _at_limit():
            break
    for item in RX_ALL_DIAGNOSES_FALLBACK:
        _add(item)
        if _at_limit():
            break
    for catalog_file in RX_DIAGNOSIS_CATALOG_FILES:
        if _at_limit():
            break
        for item in _rx_iter_catalog_file_lines(catalog_file):
            _add(item)
            if _at_limit():
                break
    try:
        if not _at_limit():
            _ensure_ready_prescription_schema()
            with db_conn() as con:
                _ensure_rx_favorites_schema(con)
                for row in con.execute(
                        "SELECT value FROM rx_favorites "
                        "WHERE is_active=1 AND kind='diagnosis' "
                        "AND TRIM(COALESCE(value,''))<>'' "
                        "ORDER BY usage_count DESC, updated_at DESC LIMIT 2000"):
                    _add(row[0])
                    if _at_limit():
                        break
                if not _at_limit():
                    for row in con.execute(
                            "SELECT diagnosis FROM ready_prescription_templates "
                            "WHERE is_active=1 AND TRIM(COALESCE(diagnosis,''))<>'' "
                            "ORDER BY usage_count DESC, name COLLATE NOCASE LIMIT 2000"):
                        _add(row[0])
                        if _at_limit():
                            break
                if not _at_limit():
                    for row in con.execute(
                            "SELECT diagnosis FROM prescriptions "
                            "WHERE TRIM(COALESCE(diagnosis,''))<>'' "
                            "AND COALESCE(deleted_at,'')='' "
                            "ORDER BY id DESC LIMIT 2500"):
                        _add(row[0])
                        if _at_limit():
                            break
    except Exception:
        pass
    if query_fold:
        results.sort(key=lambda value: (
            _rx_catalog_score(query_fold, value),
            len(value),
            _rx_fold_cached(value),
        ))
    if max_items is not None and len(results) > max_items:
        results = results[:max_items]
    try:
        cache_set(cache_key, tuple(results), ttl_seconds=900)
    except Exception:
        pass
    return results


def _rx_all_medications(limit=None, query=""):
    max_items = _rx_catalog_limit(limit)
    if max_items == 0:
        return []
    query_fold = _rx_catalog_query_fold(query)
    collect_limit = max_items
    if query_fold and max_items is not None:
        collect_limit = min(max(max_items * 6, 600), 2600)
    cache_key = f"rx_search_medication_{max_items}_{query_fold}"
    try:
        cached = cache_get(cache_key)
        if cached is not None:
            return [dict(item) for item in cached]
    except Exception:
        pass
    results = []
    seen = set()

    def _at_limit():
        return collect_limit is not None and len(results) >= collect_limit

    def _add_item(name, dose="", meta=""):
        if _at_limit():
            return
        clean_name = _rx_mojibake_fix_cached(str(name or "")).strip()
        if not clean_name:
            return
        clean_dose = _rx_mojibake_fix_cached(str(dose or "")).strip()
        clean_meta = _rx_mojibake_fix_cached(str(meta or "")).strip()
        if not _rx_catalog_matches(
                query_fold, clean_name, clean_dose, clean_meta):
            return
        key = f"{_rx_fold_cached(clean_name)}|{_rx_fold_cached(clean_dose)}"
        if key in seen:
            return
        seen.add(key)
        results.append({
            "name": clean_name,
            "dose": clean_dose,
            "meta": clean_meta,
        })

    for item in RX_COMMON_MEDICATIONS:
        _add_item(item.get("name"), item.get("dose"))
        if _at_limit():
            break
    for item in RX_ALL_MEDICATIONS_FALLBACK:
        _add_item(item.get("name"), item.get("dose"))
        if _at_limit():
            break
    for catalog_file in RX_MEDICATION_CATALOG_FILES:
        if _at_limit():
            break
        for raw in _rx_iter_catalog_file_lines(catalog_file):
            parts = raw.split("|", 2)
            if len(parts) >= 3:
                _add_item(parts[0], parts[1], parts[2])
            elif len(parts) == 2:
                _add_item(parts[0], parts[1])
            else:
                _add_item(raw, "")
            if _at_limit():
                break
    try:
        if not _at_limit():
            _ensure_ready_prescription_schema()
            with db_conn() as con:
                _ensure_rx_favorites_schema(con)
                for row in con.execute(
                        "SELECT value, dose, meta FROM rx_favorites "
                        "WHERE is_active=1 AND kind='medication' "
                        "AND TRIM(COALESCE(value,''))<>'' "
                        "ORDER BY usage_count DESC, updated_at DESC LIMIT 2000"):
                    _add_item(row[0], row[1], row[2])
                    if _at_limit():
                        break
                if not _at_limit():
                    for row in con.execute(
                            "SELECT medications FROM ready_prescription_templates "
                            "WHERE is_active=1 ORDER BY usage_count DESC, id DESC LIMIT 2000"):
                        for med_item in _rx_parse_medications_items(row[0]):
                            _add_item(med_item.get("name"), med_item.get("dose"))
                            if _at_limit():
                                break
                        if _at_limit():
                            break
                if not _at_limit():
                    for row in con.execute(
                            "SELECT medications FROM prescriptions "
                            "WHERE COALESCE(deleted_at,'')='' "
                            "ORDER BY id DESC LIMIT 3000"):
                        for med_item in _rx_parse_medications_items(row[0]):
                            _add_item(med_item.get("name"), med_item.get("dose"))
                            if _at_limit():
                                break
                        if _at_limit():
                            break
    except Exception:
        pass
    if query_fold:
        results.sort(key=lambda item: (
            _rx_catalog_score(
                query_fold,
                item.get("name") or "",
                item.get("meta") or "",
                item.get("dose") or "",
            ),
            len(item.get("name") or ""),
            _rx_fold_cached(item.get("name") or ""),
        ))
    if max_items is not None and len(results) > max_items:
        results = results[:max_items]
    try:
        cache_set(cache_key, tuple(dict(item) for item in results), ttl_seconds=900)
    except Exception:
        pass
    return results


def _rx_template_category_from_text(text):
    folded = _fold_search_text(text)
    if any(tok in folded for tok in (
            "gebe", "gebelik", "obstetr", "hamile", "trimester",
            "postpartum", "lohusa", "dogum")):
        return "Gebelik"
    if any(tok in folded for tok in (
            "infertil", "ivf", "tup bebek", "ovul", "amh", "embriyo")):
        return "Infertilite"
    if any(tok in folded for tok in (
            "operasyon", "postop", "postoperatif", "ameliyat", "laparoskop", "histeroskop")):
        return "Operasyon"
    if any(tok in folded for tok in (
            "enfeks", "vajinit", "servisit", "idrar yolu", "sistit", "kandid")):
        return "Enfeksiyon"
    if any(tok in folded for tok in ("agri", "dismenore", "pelvik agri")):
        return "Agri"
    return "Jinekoloji"


def _rx_template_key(text):
    raw = unicodedata.normalize("NFKD", str(text or "").strip().lower())
    ascii_text = raw.encode("ascii", "ignore").decode("ascii")
    key = re.sub(r"[^a-z0-9]+", "_", ascii_text).strip("_")
    return key[:80] or "recete"


def _int_or_none(value):
    try:
        text = str(value or "").strip()
        return int(text) if text else None
    except Exception:
        return None


def _ensure_ready_prescription_schema(con=None):
    def _run(open_con):
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS prescriptions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                patient_key TEXT NOT NULL,
                visit_key TEXT,
                medications TEXT,
                diagnosis TEXT,
                notes TEXT,
                created_by TEXT,
                created_at TEXT,
                updated_at TEXT,
                template_id INTEGER,
                template_name TEXT,
                purpose TEXT,
                patient_name TEXT,
                protocol_no TEXT,
                deleted_at TEXT,
                deleted_by TEXT,
                deleted_reason TEXT
            )
        """)
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS ready_prescription_templates (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_key TEXT UNIQUE,
                name TEXT NOT NULL,
                purpose TEXT DEFAULT '',
                category TEXT DEFAULT 'Diger',
                diagnosis TEXT DEFAULT '',
                medications TEXT NOT NULL,
                notes TEXT DEFAULT '',
                source_file_name TEXT,
                source_file_ext TEXT,
                source_file_blob BLOB,
                file_size INTEGER DEFAULT 0,
                is_active INTEGER DEFAULT 1,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                created_by TEXT,
                usage_count INTEGER DEFAULT 0,
                last_used_at TEXT
            )
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_ready_rx_active
            ON ready_prescription_templates(is_active, category, name)
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_ready_rx_key
            ON ready_prescription_templates(template_key)
        """)
        columns = {
            str(r[1]) for r in
            open_con.execute("PRAGMA table_info(prescriptions)").fetchall()
        }
        for col, ddl in (
            ("visit_key", "ALTER TABLE prescriptions ADD COLUMN visit_key TEXT"),
            ("template_id", "ALTER TABLE prescriptions ADD COLUMN template_id INTEGER"),
            ("template_name", "ALTER TABLE prescriptions ADD COLUMN template_name TEXT"),
            ("purpose", "ALTER TABLE prescriptions ADD COLUMN purpose TEXT"),
            ("patient_name", "ALTER TABLE prescriptions ADD COLUMN patient_name TEXT"),
            ("protocol_no", "ALTER TABLE prescriptions ADD COLUMN protocol_no TEXT"),
            ("updated_at", "ALTER TABLE prescriptions ADD COLUMN updated_at TEXT"),
            ("deleted_at", "ALTER TABLE prescriptions ADD COLUMN deleted_at TEXT"),
            ("deleted_by", "ALTER TABLE prescriptions ADD COLUMN deleted_by TEXT"),
            ("deleted_reason", "ALTER TABLE prescriptions ADD COLUMN deleted_reason TEXT"),
        ):
            if col not in columns:
                try:
                    open_con.execute(ddl)
                except Exception:
                    pass
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_rx_patient_active
            ON prescriptions(patient_key, deleted_at, created_at DESC)
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_rx_visit_active
            ON prescriptions(patient_key, visit_key, deleted_at, created_at DESC)
        """)
        _seed_ready_prescription_templates(open_con)
        _ensure_rx_favorites_schema(open_con)

    if con is not None:
        _run(con)
        return
    with db_conn() as open_con:
        _run(open_con)
        open_con.commit()


def _ensure_rx_favorites_schema(con=None):
    def _run(open_con):
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS rx_favorites (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                kind TEXT NOT NULL,
                value TEXT NOT NULL,
                dose TEXT DEFAULT '',
                meta TEXT DEFAULT '',
                is_active INTEGER DEFAULT 1,
                usage_count INTEGER DEFAULT 0,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                created_by TEXT
            )
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_rx_favorites_kind
            ON rx_favorites(kind, is_active, usage_count, updated_at)
        """)
        open_con.execute("""
            CREATE UNIQUE INDEX IF NOT EXISTS idx_rx_favorites_unique
            ON rx_favorites(kind, value, dose)
        """)

    if con is not None:
        _run(con)
        return
    with db_conn() as open_con:
        _run(open_con)
        open_con.commit()


def _rx_save_favorite_diagnosis(text):
    value = fix_mojibake_text(str(text or "")).strip()
