def _seed_ready_prescription_templates(con):
    try:
        row = con.execute(
            "SELECT COUNT(*) FROM ready_prescription_templates").fetchone()
        if row and int(row[0] or 0) > 0:
            return
    except Exception:
        return
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    for key, item in RX_QUICK_TEMPLATES.items():
        name = item.get("title") or key
        purpose = item.get("diagnosis") or ""
        category = "Gebelik" if key in (
            "prenatal_destek", "demir_destek", "bulanti") else "Jinekoloji"
        try:
            con.execute(
                "INSERT OR IGNORE INTO ready_prescription_templates("
                "template_key, name, purpose, category, diagnosis, "
                "medications, notes, created_at, updated_at, created_by"
                ") VALUES(?,?,?,?,?,?,?,?,?,?)",
                (key, name, purpose, category, item.get("diagnosis") or "",
                 item.get("medications") or "", item.get("notes") or "",
                 now, now, "system"))
        except Exception:
            pass


def _list_ready_prescription_templates(include_inactive=False, query=""):
    _ensure_ready_prescription_schema()
    q = str(query or "").strip().lower()
    where = []
    params = []
    if not include_inactive:
        where.append("is_active=1")
    if q:
        like = f"%{q}%"
        where.append(
            "(LOWER(name) LIKE ? OR LOWER(purpose) LIKE ? OR "
            "LOWER(category) LIKE ? OR LOWER(diagnosis) LIKE ?)")
        params.extend([like, like, like, like])
    clause = ("WHERE " + " AND ".join(where)) if where else ""
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        rows = con.execute(
            "SELECT * FROM ready_prescription_templates "
            f"{clause} ORDER BY category, name COLLATE NOCASE",
            params).fetchall()
    return [dict(r) for r in rows]


def _get_ready_prescription_template(template_ref):
    _ensure_ready_prescription_schema()
    template_id = _int_or_none(template_ref)
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        if template_id:
            row = con.execute(
                "SELECT * FROM ready_prescription_templates WHERE id=?",
                (template_id,)).fetchone()
        else:
            row = con.execute(
                "SELECT * FROM ready_prescription_templates "
                "WHERE template_key=?",
                (str(template_ref or "").strip(),)).fetchone()
    return dict(row) if row else None


def _rx_form_items_from_fields(form, prefix="rx_drug"):
    if not hasattr(form, "getlist"):
        return []
    names = form.getlist(f"{prefix}_name[]")
    if not names:
        return []
    doses = form.getlist(f"{prefix}_dose[]")
    box_counts = form.getlist(f"{prefix}_box[]")
    daily_counts = form.getlist(f"{prefix}_daily[]")
    routes = form.getlist(f"{prefix}_route[]")
    period_counts = form.getlist(f"{prefix}_period_count[]")
    period_units = form.getlist(f"{prefix}_period_unit[]")
    items = []
    for idx, name in enumerate(names):
        item = {
            "name": fix_mojibake_text(str(name or "")).strip(),
            "dose": fix_mojibake_text(
                str(doses[idx] if idx < len(doses) else "")).strip(),
            "box_count": fix_mojibake_text(
                str(box_counts[idx] if idx < len(box_counts) else "")).strip(),
            "daily_frequency": fix_mojibake_text(
                str(daily_counts[idx] if idx < len(daily_counts) else "")).strip(),
            "route": fix_mojibake_text(
                str(routes[idx] if idx < len(routes) else "")).strip(),
            "period_count": fix_mojibake_text(
                str(period_counts[idx] if idx < len(period_counts) else "")).strip(),
            "period_unit": fix_mojibake_text(
                str(period_units[idx] if idx < len(period_units) else "")).strip(),
        }
        if any(str(v or "").strip() for v in item.values()):
            items.append(item)
    return items


def _save_ready_prescription_template(form, upload=None, template_id=None):
    name = fix_mojibake_text(str(form.get("name") or "")).strip()
    purpose = fix_mojibake_text(str(form.get("purpose") or "")).strip()
    category = fix_mojibake_text(
        str(form.get("category") or "Diger")).strip() or "Diger"
    diagnosis = fix_mojibake_text(str(form.get("diagnosis") or "")).strip()
    structured_items = (
        _rx_form_items_from_fields(form, "tpl_rx_drug")
        or _rx_form_items_from_fields(form, "rx_drug")
    )
    medications = _rx_build_medications_text(structured_items) if structured_items else ""
    if not medications:
        medications = fix_mojibake_text(str(form.get("medications") or "")).strip()
    notes = fix_mojibake_text(str(form.get("notes") or "")).strip()
    if not name:
        raise ValueError("Recete adi zorunlu.")
    if not purpose:
        raise ValueError("Recetenin ne icin oldugu zorunlu.")
    if not medications:
        raise ValueError("Recete metni bos olamaz.")
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    file_name = file_ext = None
    blob = None
    file_size = None
    if upload and upload.filename:
        file_name = _safe_upload_filename(upload.filename, fallback="recete")
        file_ext = Path(file_name).suffix.lower().lstrip(".") or "bin"
        blob = upload.read()
        file_size = len(blob or b"")
        _validate_template_blob_upload(
            file_name, file_ext, blob, "Recete sablonu")
    with db_conn() as con:
        _ensure_ready_prescription_schema(con)
        if template_id:
            sets = [
                "name=?", "purpose=?", "category=?", "diagnosis=?",
                "medications=?", "notes=?", "updated_at=?", "is_active=1",
            ]
            params = [name, purpose, category, diagnosis, medications, notes, now]
            if blob is not None:
                sets.extend([
                    "source_file_name=?", "source_file_ext=?",
                    "source_file_blob=?", "file_size=?",
                ])
                params.extend([file_name, file_ext, blob, file_size])
            params.append(template_id)
            con.execute(
                f"UPDATE ready_prescription_templates SET {', '.join(sets)} "
                "WHERE id=?", params)
        else:
            key = _rx_template_key(name)
            base = key
            suffix = 2
            while con.execute(
                    "SELECT 1 FROM ready_prescription_templates "
                    "WHERE template_key=?", (key,)).fetchone():
                key = f"{base}_{suffix}"
                suffix += 1
            con.execute(
                "INSERT INTO ready_prescription_templates("
                "template_key, name, purpose, category, diagnosis, medications, "
                "notes, source_file_name, source_file_ext, source_file_blob, "
                "file_size, created_at, updated_at, created_by"
                ") VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (key, name, purpose, category, diagnosis, medications, notes,
                 file_name, file_ext, blob, file_size or 0, now, now,
                 session.get("user", "?")))
        con.commit()


