def _brand_logo_data_uri():
    """C27: Doktor 'Yaz Klinik yazan yerlere 3.resmi (renkli gradient
    figur) koyalim, sidebar daha guzel olsun' dedi. Sidebar + gebe-takip
    + diyet sayfalarinda 'YK' rozeti yerine bu logo kullanilir.
    Aranan dosyalar (sirayla):
      static/brand_logo.png    (TERCIH EDILEN - resim 3)
      static/amblem_renkli.png
      static/yk_logo.png
      static/yazklinik_logo.png
      static/brand.png
      static/logo.png
    Yoksa '' doner; HTML'de fallback 'YK' rozeti gorunur.
    """
    global _BRAND_LOGO_DATA_URI
    if _BRAND_LOGO_DATA_URI is not None:
        return _BRAND_LOGO_DATA_URI
    root = Path(__file__).with_name("static")
    candidates = [
        root / "brand_logo.png",
        root / "amblem_renkli.png",
        root / "yk_logo.png",
        root / "yazklinik_logo.png",
        root / "brand.png",
        root / "logo.png",
        root / "brand_logo.jpg",
        root / "yk_logo.jpg",
    ]
    for path in candidates:
        try:
            if path.exists() and path.is_file():
                # D250: base64 inline yerine /static/ URL kullan. Sayfa basina
                # ~175 KB azalir + tarayici 7 gun cache eder. Custom logo upload
                # da static/ klasoruna gittigi icin geri uyumlu.
                _BRAND_LOGO_DATA_URI = f"/static/{path.name}?v=d250-1"
                return _BRAND_LOGO_DATA_URI
        except Exception:
            continue
    _BRAND_LOGO_DATA_URI = ""
    return ""


def _prescription_logo_data_uri():
    """C26: Doktor 'recete ustundeki figur 1.resimdeki gibi olsun, 2.resim
    1. ile yer degissin' dedi. static/ klasorunde sirayla logo dosyalari
    aranir, ilk bulunan kullanilir. Doktor 'recete_figur.png' veya
    'recete_logo.png' olarak yeni figuru yukleyince mevcut .jpeg'in
    yerine gecer (eski dosyayi silmek gerekmez).
    Aranan dosyalar (oncelikli sirayla):
      static/recete_figur.png      (yeni - C26 doktor onerisi)
      static/recete_logo.png       (yeni)
      static/recete_logo_v2.png    (yeni)
      static/recete_logo.jpeg      (eski, geri uyumluluk)
      static/recete_logo.jpg       (alternatif)
    """
    global _PRESCRIPTION_LOGO_DATA_URI
    if _PRESCRIPTION_LOGO_DATA_URI is not None:
        return _PRESCRIPTION_LOGO_DATA_URI
    root = Path(__file__).with_name("static")
    candidates = [
        (root / "recete_figur.png", "image/png"),
        (root / "recete_logo.png", "image/png"),
        (root / "recete_logo_v2.png", "image/png"),
        (root / "recete_logo.jpeg", "image/jpeg"),
        (root / "recete_logo.jpg", "image/jpeg"),
    ]
    for path, mime in candidates:
        try:
            if path.exists() and path.is_file():
                data = path.read_bytes()
                encoded = base64.b64encode(data).decode("ascii")
                _PRESCRIPTION_LOGO_DATA_URI = (
                    f"data:{mime};base64,{encoded}")
                return _PRESCRIPTION_LOGO_DATA_URI
        except Exception:
            continue
    _PRESCRIPTION_LOGO_DATA_URI = ""
    return _PRESCRIPTION_LOGO_DATA_URI


def _data_uri_from_image(file_path):
    """C25 helper: imaj dosyasini data: URI'a cevirir.
    PNG/JPG/JPEG/GIF/WEBP destekler. Bulamazsa veya okuyamazsa '' doner.
    """
    try:
        p = Path(file_path)
        if not p.exists() or not p.is_file():
            return ""
        suffix = p.suffix.lower().lstrip(".")
        if suffix == "jpg":
            mime = "image/jpeg"
        elif suffix in ("png", "jpeg", "gif", "webp"):
            mime = f"image/{'jpeg' if suffix == 'jpeg' else suffix}"
        else:
            mime = "image/png"  # default
        data = p.read_bytes()
        encoded = base64.b64encode(data).decode("ascii")
        return f"data:{mime};base64,{encoded}"
    except Exception:
        return ""


