def _clinic_setting_value(key, default=""):
    getter = globals().get("_db_get_setting")
    if callable(getter):
        keys = [key]
        if not key.startswith("sysparam_"):
            keys.insert(0, f"sysparam_{key}")
        for candidate in keys:
            value = getter(candidate, "")
            if value not in (None, ""):
                return str(value).strip()
        return default
    keys = [key]
    if not key.startswith("sysparam_"):
        keys.insert(0, f"sysparam_{key}")
    try:
        with db_conn() as con:
            con.execute(
                "CREATE TABLE IF NOT EXISTS settings "
                "(key TEXT PRIMARY KEY, value TEXT)")
            for candidate in keys:
                row = con.execute(
                    "SELECT value FROM settings WHERE key=?",
                    (candidate,)).fetchone()
                if row and row[0]:
                    return str(row[0]).strip()
    except Exception:
        pass
    return default


def _format_prescription_medications_html(medications):
    text = str(medications or "").strip()
    if not text:
        return '<div class="rx-empty">Ilac bilgisi girilmedi.</div>'
    groups = []
    current = []
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if re.match(r"^\d+\s*[-.)]", line):
            if current:
                groups.append(current)
            current = [line]
        elif current:
            current.append(line)
        else:
            current = [line]
    if current:
        groups.append(current)

    rows = []
    for idx, parts in enumerate(groups, 1):
        first = parts[0]
        match = re.match(r"^\d+\s*[-.)]\s*(.+)$", first)
        name = (match.group(1) if match else first).strip()
        details = [p for p in parts[1:] if p.strip()]
        dose_html = ""
        if details:
            dose_html = (
                '<div class="rx-drug-dose">'
                + "<br>".join(sh(p) for p in details)
                + "</div>"
            )
        rows.append(
            '<div class="rx-drug">'
            f'<div class="rx-drug-main"><span class="rx-no">{idx}</span>'
            f'<span>{sh(name)}</span></div>{dose_html}</div>'
        )
    return "\n".join(rows)


def _rx_normalize_box_count(value, default=1):
    text = fix_mojibake_text(str(value or "")).strip()
    number = None
    if text:
        match = re.search(r"\d+", text)
        if match:
            try:
                number = int(match.group(0))
            except Exception:
                number = None
    if number is None or number <= 0:
        number = int(default or 1)
    return max(1, min(number, 999))


_RX_BOX_ONES_TR = {
    0: "",
    1: "Bir",
    2: "İki",
    3: "Üç",
    4: "Dört",
    5: "Beş",
    6: "Altı",
    7: "Yedi",
    8: "Sekiz",
    9: "Dokuz",
}
_RX_BOX_TENS_TR = {
    10: "On",
    20: "Yirmi",
    30: "Otuz",
    40: "Kırk",
    50: "Elli",
    60: "Altmış",
    70: "Yetmiş",
    80: "Seksen",
    90: "Doksan",
}


def _rx_box_number_to_words_tr(value):
    number = _rx_normalize_box_count(value)
    if number < 10:
        return _RX_BOX_ONES_TR.get(number, str(number))
    if number < 100:
        tens = (number // 10) * 10
        ones = number % 10
        words = [_RX_BOX_TENS_TR.get(tens, str(tens))]
        if ones:
            words.append(_RX_BOX_ONES_TR.get(ones, str(ones)))
        return " ".join(part for part in words if part)
    if number < 1000:
        hundreds = number // 100
        rest = number % 100
        prefix = "Yüz" if hundreds == 1 else f"{_RX_BOX_ONES_TR.get(hundreds, str(hundreds))} Yüz"
        if rest:
            return f"{prefix} {_rx_box_number_to_words_tr(rest)}"
        return prefix
    return str(number)


def _rx_box_display(value):
    number = _rx_normalize_box_count(value)
    return f"D:{number}({_rx_box_number_to_words_tr(number)})B"


def _rx_extract_box_count_from_line(value):
    clean = fix_mojibake_text(str(value or "")).strip()
    if not clean:
        return ""
    d_match = re.match(
        r"^d\s*[:\-]?\s*(\d+)\s*(?:\([^)]*\))?\s*b\b",
        clean,
        re.IGNORECASE,
    )
    if d_match:
        return str(_rx_normalize_box_count(d_match.group(1)))
    dib_match = re.match(
        r"^d[ıi]?b\s*[:\-]?\s*(\d+)",
        clean,
        re.IGNORECASE,
    )
    if dib_match:
        return str(_rx_normalize_box_count(dib_match.group(1)))
    box_match = re.match(r"^kutu\s*[:\-]?\s*(\d+)", clean, re.IGNORECASE)
    if box_match:
        return str(_rx_normalize_box_count(box_match.group(1)))
    return ""


def _rx_parse_medications_items(medications):
    text = fix_mojibake_text(str(medications or "")).strip()
    if not text:
        return []
    groups = []
    current = []
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if re.match(r"^\d+\s*[-.)]", line):
            if current:
                groups.append(current)
            current = [line]
        elif current:
            current.append(line)
        else:
            current = [line]
    if current:
        groups.append(current)

    items = []
    for parts in groups:
        first = parts[0]
        match = re.match(r"^\d+\s*[-.)]\s*(.+)$", first)
        name = (match.group(1) if match else first).strip()
        if not name:
            continue
        dose_lines = []
        box_count = ""
        daily_frequency = ""
        route_value = ""
        period_count = ""
        period_unit = ""
        for part in parts[1:]:
            clean = fix_mojibake_text(str(part or "")).strip()
            if not clean:
                continue
            box_value = _rx_extract_box_count_from_line(clean)
            if box_value:
                box_count = box_value
                continue
            route_label_match = re.match(
                r"^(?:kullan[ıi]m\s*[şs]ekli|uygulama\s*yolu|yol)"
                r"\s*[:\-]\s*(.+)$",
                clean,
                re.IGNORECASE,
            )
            if route_label_match:
                route_value = route_label_match.group(1).strip().upper()
                continue
            # D250: "Kullanim Sekli" satiri (AGIZDAN/VAJINAL/INTRAMUSKULER/SUBKUTAN/REKTAL)
            route_match = re.match(
                r"^(agizdan|ağ[ıi]zdan|vajinal|vag[ıi]nal|intramusk[üu]ler|intramuskuler|subkutan|rektal|rektum|rectal|anal|oral|i\.?m\.?|s\.?c\.?|s\.?k\.?|p\.?r\.?|topikal|g[öo]ze|kula[ğg]a|buruna)\s*[.,]?\s*\(?[^)]*\)?\s*$",
                clean,
                re.IGNORECASE,
            )
            if route_match:
                # Normalize'i tutarli yap
                up = clean.upper().strip()
                if up.startswith(("REKTAL", "REKTUM", "RECTAL", "ANAL", "P.R", "PR")):
                    route_value = "REKTAL"
                else:
                    route_value = up
                continue
            # D250: "Periyot" satiri (haftada N, ayda N gibi)
            period_match = re.match(
                r"^(haftada|ayda)\s*[:\-]?\s*(\d+)",
                clean,
                re.IGNORECASE,
            )
            if period_match:
                period_count = period_match.group(2).strip()
                period_unit = "HAFTA" if period_match.group(1).lower().startswith("hafta") else "AY"
                continue
            period_label_match = re.match(
                r"^(?:periyot|s[üu]re)\s*[:\-]?\s*(\d+)\s*"
                r"(g[üu]n|gun|hafta|ay)\b",
                clean,
                re.IGNORECASE,
            )
            if period_label_match:
                period_count = period_label_match.group(1).strip()
                unit_raw = period_label_match.group(2).lower()
                if unit_raw.startswith("hafta"):
                    period_unit = "HAFTA"
                elif unit_raw.startswith("ay"):
                    period_unit = "AY"
                else:
                    period_unit = "GUN"
                continue
            period_x_match = re.match(
                r"^(\d+)\s*[xX]\s*(g[üu]n|gun|hafta|ay)\b",
                clean,
                re.IGNORECASE,
            )
            if period_x_match:
                period_count = period_x_match.group(1).strip()
                unit_raw = period_x_match.group(2).lower()
                if unit_raw.startswith("hafta"):
                    period_unit = "HAFTA"
                elif unit_raw.startswith("ay"):
                    period_unit = "AY"
                else:
                    period_unit = "GUN"
                continue
            # D250: ESKI tek-satir kombinasyon parser:
            # "Agizdan (Oral) S: 2x1 (Gun)" -> route + dose + period_unit ayrı sutunlara
            old_combo = re.match(
                r"^(agizdan|ağ[ıi]zdan|vajinal|vag[ıi]nal|intramusk[üu]ler|intramuskuler|subkutan|oral)"
                r"(?:\s*\([^)]*\))?"
                r"\s*[Ss]\s*[:\-]?\s*(\d+(?:[.,]\d+)?)\s*[xX*]\s*(\d+(?:[.,]\d+)?)"
                r"(?:\s*\(([^)]+)\))?",
                clean,
                re.IGNORECASE,
            )
            if old_combo:
                if not route_value:
                    route_value = old_combo.group(1).upper().strip()
                dose_n = old_combo.group(2).replace(',', '.')
                dose_m = old_combo.group(3).replace(',', '.')
                if not dose_lines:
                    dose_lines.append(f"{dose_n}x{dose_m}")
                if old_combo.group(4):
                    unit_raw = old_combo.group(4).strip().upper()
                    if not period_unit:
                        if "HAFTA" in unit_raw:
                            period_unit = "HAFTA"
                        elif unit_raw.startswith("AY"):
                            period_unit = "AY"
                        else:
                            period_unit = "GUN"
                    if not period_count:
                        period_count = "1"
                if not daily_frequency:
                    daily_frequency = dose_n
                continue
            daily_match = re.match(
                r"^(g[üu]nl[üu]k\s*kullan[ıi]m|g[üu]nde)\s*[:\-]?\s*(\d+)\s*(kez)?",
                clean,
                re.IGNORECASE,
            )
            if daily_match:
                daily_frequency = daily_match.group(2).strip()
                continue
            dose_label_match = re.match(
                r"^(?:doz|kullan[ıi]m\s*tarifi)\s*[:\-]\s*(.+)$",
                clean,
                re.IGNORECASE,
            )
            if dose_label_match:
                dose_lines.append(dose_label_match.group(1).strip())
                continue
            dose_lines.append(clean)
        dose = "\n".join(dose_lines).strip()
        items.append({
            "name": name,
            "dose": dose,
            "box_count": box_count,
            "daily_frequency": daily_frequency,
            "route": route_value,
            "period_count": period_count,
            "period_unit": period_unit,
        })
    return items


def _rx_build_medications_text(items):
    """D250 2026-05-12: Recete meds text artik tum e-Recete alanlarini icerir:
    route (AGIZDAN/VAJINAL/INTRAMUSKULER/SUBKUTAN/REKTAL),
    daily_frequency (gunluk kac kez),
    period_count + period_unit (1xGUN / 2xHAFTA / 1xAY)
    Bu sayede DB'de gidip-gelmeye round-trip kayipsiz olur."""
    rows = []
    for idx, raw_item in enumerate(items or [], 1):
        if not isinstance(raw_item, dict):
            continue
        name = fix_mojibake_text(str(raw_item.get("name") or "")).strip()
        if not name:
            continue
        lines = [f"{idx}- {name}"]
        dose_text = fix_mojibake_text(str(raw_item.get("dose") or "")).strip()
        box_count = fix_mojibake_text(
            str(raw_item.get("box_count") or "")).strip()
        for dose_line in dose_text.splitlines():
            clean = dose_line.strip()
            if not clean:
                continue
            box_value = _rx_extract_box_count_from_line(clean)
            if box_value:
                box_count = box_count or box_value
                continue
            lines.append(f" {clean}")
        daily_frequency = fix_mojibake_text(
            str(raw_item.get("daily_frequency") or "")).strip()
        route_value = fix_mojibake_text(
            str(raw_item.get("route") or "")).strip().upper()
        period_count = fix_mojibake_text(
            str(raw_item.get("period_count") or "")).strip()
        period_unit = fix_mojibake_text(
            str(raw_item.get("period_unit") or "")).strip().upper()
        if route_value and route_value not in ("",):
            lines.append(f" Kullanim sekli: {route_value}")
        lines.append(f" {_rx_box_display(box_count)}")
        if daily_frequency:
            lines.append(f" Gunluk kullanim: {daily_frequency} kez")
        # D250: period satirini ekle (parser haftada/ayda match'ler)
        if period_count and period_unit:
            if period_unit == "HAFTA":
                lines.append(f" Haftada {period_count}")
            elif period_unit == "AY":
                lines.append(f" Ayda {period_count}")
            elif period_unit == "GUN" and period_count != "1":
                # 1 GUN default, sadece >=2 ise yaz
                lines.append(f" Periyot: {period_count} GUN")
        rows.append("\n".join(lines))
    return "\n\n".join(rows).strip()


