def _rx_box_display_pretty(value):
    """e-Recete standardina yakin format: DIB (Bir)."""
    number = _rx_normalize_box_count(value)
    return f"DIB ({_rx_box_number_to_words_tr(number)})"


def _rx_parse_list_setting(value):
    if value is None:
        return []
    if isinstance(value, (list, tuple, set)):
        return list(value)
    text = fix_mojibake_text(str(value or "")).strip()
    if not text:
        return []
    try:
        loaded = json.loads(text)
        if isinstance(loaded, (list, tuple, set)):
            return list(loaded)
    except Exception:
        pass
    return [
        part.strip()
        for part in re.split(r"[,;\n]+", text)
        if part and part.strip()
    ]


def _rx_normalize_field_keys(value, allowed, default):
    default_items = list(default or [])
    raw_items = _rx_parse_list_setting(value)
    if not raw_items:
        raw_items = default_items
    allowed_keys = set(allowed.keys())
    clean = []
    for item in raw_items:
        key = fix_mojibake_text(str(item or "")).strip()
        if key in allowed_keys and key not in clean:
            clean.append(key)
    return clean or default_items


def _rx_normalize_custom_fields(value):
    raw_items = value
    if isinstance(value, str):
        text = fix_mojibake_text(value).strip()
        if not text:
            return []
        try:
            raw_items = json.loads(text)
        except Exception:
            raw_items = []
            for line in text.splitlines():
                clean = line.strip()
                if not clean:
                    continue
                parts = re.split(r"\s*[:=]\s*", clean, maxsplit=1)
                if len(parts) == 2:
                    raw_items.append({"label": parts[0], "value": parts[1]})
                else:
                    raw_items.append({"label": "Ek Alan", "value": clean})
    if isinstance(raw_items, dict):
        raw_items = [raw_items]
    if not isinstance(raw_items, (list, tuple)):
        return []
    fields = []
    for item in raw_items:
        if isinstance(item, dict):
            label = fix_mojibake_text(str(item.get("label") or "")).strip()
            field_value = fix_mojibake_text(str(item.get("value") or "")).strip()
        else:
            parts = re.split(r"\s*[:=]\s*", fix_mojibake_text(str(item)), maxsplit=1)
            label = parts[0].strip() if len(parts) == 2 else "Ek Alan"
            field_value = parts[1].strip() if len(parts) == 2 else parts[0].strip()
        label = re.sub(r"\s+", " ", label)[:40]
        field_value = re.sub(r"\s+", " ", field_value)[:180]
        if not label and not field_value:
            continue
        fields.append({"label": label or "Ek Alan", "value": field_value})
        if len(fields) >= 12:
            break
    return fields


def _rx_print_setting_storage_value(value):
    if isinstance(value, bool):
        return "1" if value else "0"
    if isinstance(value, (list, tuple, dict)):
        return json.dumps(value, ensure_ascii=False)
    return str(value)


def _rx_custom_fields_html(fields):
    rows = []
    for field in _rx_normalize_custom_fields(fields):
        label = fix_mojibake_text(str(field.get("label") or "Ek Alan")).strip()
        value = fix_mojibake_text(str(field.get("value") or "")).strip()
        if not value:
            continue
        rows.append(
            '<div class="rx-line-row rx-custom-field">'
            f'<span class="lbl">{sh(label)}:</span>'
            f'<span class="val">{sh(value)}</span>'
            '</div>'
        )
    return "\n".join(rows)


def _rx_medications_table_html(medications, visible_fields=None):
    items = _rx_parse_medications_items(medications)
    if not items:
        return '<div class="rx-empty">Ilac bilgisi girilmedi.</div>'
    visible = set(_rx_normalize_field_keys(
        visible_fields,
        RX_PRINT_DRUG_FIELDS,
        RX_PRINT_DEFAULTS["drug_fields"]))

    def _hidden_attr(key):
        return "" if key in visible else ' style="display:none"'

    def _drug_value(item, key, idx):
        # D250: e-Recete standart formatina yakin sutun degerleri.
        # Foto referans: Ilac Adi | Kullanim Sekli | Doz | Periyot | Adet
        if key == "no":
            return str(idx)
        if key == "name":
            return item.get("name") or ""
        if key == "route":
            # Kullanim Sekli: default AGIZDAN. Doktor istegi (D250):
            # AGIZDAN / VAJINAL / INTRAMUSKULER / SUBKUTAN / REKTAL
            raw = (item.get("route") or "").strip().upper()
            # Alias normalize
            if raw in ("", "ORAL", "AGIZDAN (ORAL)", "AGIZDAN(ORAL)", "PO"):
                raw = "AGIZDAN"
            elif raw in ("IM", "INTRAMUSCULER", "INTRAMUSCULAR"):
                raw = "INTRAMUSKULER"
            elif raw in ("SC", "SK", "SUBCUTANEOUS", "SUBCUT"):
                raw = "SUBKUTAN"
            elif raw in ("VAGINAL", "VAJINAL (PV)", "PV"):
                raw = "VAJINAL"
            elif raw in ("RECTAL", "REKTUM", "ANAL", "PR", "P.R", "P.R."):
                raw = "REKTAL"
            return raw
        if key == "dose":
            # Doz: "2x1" formati = gunde X kez x her seferinde Y tane
            # Kullanici manuel girdi varsa onu kullan; yoksa parser'dan turet
            manual = (item.get("dose") or "").strip()
            if manual:
                # Eger zaten "NxM" formatindaysa kullan, degilse normalize et
                m = re.match(r"^\s*(\d+(?:[.,]\d+)?)\s*[xX*]\s*(\d+(?:[.,]\d+)?)\s*$", manual)
                if m:
                    return f"{m.group(1).replace(',', '.')}x{m.group(2).replace(',', '.')}"
                # Tek sayi varsa onu "X" sayisi olarak al, per-dose=1 ekle
                m1 = re.match(r"^\s*(\d+(?:[.,]\d+)?)\s*$", manual)
                if m1:
                    return f"{m1.group(1).replace(',', '.')}x1"
                # Diger durumda kullanicinin yazdigini koru
                return manual
            # Parser'dan gunluk frekans algilandiysa onu kullan, per-dose default 1
            freq = (item.get("daily_frequency") or "").strip()
            per_dose = (item.get("per_dose") or "1").strip() or "1"
            if freq:
                return f"{freq}x{per_dose}"
            # Hicbir bilgi yoksa varsayilan
            return "1x1"
        if key == "box":
            # Adet: e-Recete standardi - DIB (Bir), DIB (Iki), DIB (Uc) ...
            return _rx_box_display_pretty(item.get("box_count"))
        if key == "daily":
            # Periyot: default "1 X GUN"; haftalik ise "1 X HAFTA" veya "2 X HAFTA"
            # Item icinde period_count + period_unit varsa kullan, yoksa default
            period_count = (item.get("period_count") or "1").strip() or "1"
            period_unit = (item.get("period_unit") or "GUN").strip().upper()
            if period_unit not in ("GUN", "HAFTA", "AY"):
                period_unit = "GUN"
            return f"{period_count} X {period_unit}"
        return ""

    header_cells = []
    for key, label in RX_PRINT_DRUG_FIELDS.items():
        header_cells.append(
            f'<th class="rx-drug-col-{key}" data-rx-drug-field="{key}"'
            f'{_hidden_attr(key)}>{sh(label)}</th>'
        )
    body_rows = []
    for idx, item in enumerate(items, 1):
        cells = []
        for key in RX_PRINT_DRUG_FIELDS:
            value = _drug_value(item, key, idx)
            cells.append(
                f'<td class="rx-drug-col-{key}" data-rx-drug-field="{key}"'
                f'{_hidden_attr(key)}>{sh(value).replace(chr(10), "<br>")}</td>'
            )
        body_rows.append("<tr>" + "".join(cells) + "</tr>")
    return (
        '<table class="rx-drug-table">'
        '<thead><tr>' + "".join(header_cells) + '</tr></thead>'
        '<tbody>' + "".join(body_rows) + '</tbody>'
        '</table>'
    )


