def _ready_rx_live_search_assets():
    return """
 <style>
 .yk-rx-search-wrap {
 border-bottom: 1px solid #dbe7f3;
 background: linear-gradient(90deg, #f8fcff, #eef8fb);
 padding: 16px 18px;
 }
 .yk-rx-search-box {
 position: relative;
 max-width: 760px;
 }
 .yk-rx-search-input {
 height: 48px;
 border-radius: 14px;
 border: 1px solid #bfd4e8;
 padding: 0 48px 0 16px;
 font-size: 16px;
 box-shadow: 0 8px 22px rgba(15, 86, 142, .08);
 }
 .yk-rx-search-icon {
 position: absolute;
 right: 16px;
 top: 50%;
 transform: translateY(-50%);
 color: #0b63b6;
 font-weight: 800;
 pointer-events: none;
 }
 .yk-rx-search-meta {
 margin-top: 8px;
 color: #62748a;
 font-size: 13px;
 }
 .yk-rx-suggestions {
 display: none;
 gap: 8px;
 flex-wrap: wrap;
 margin-top: 12px;
 }
 .yk-rx-suggestions.is-open {
 display: flex;
 }
 .yk-rx-suggestion {
 border: 1px solid #c8dae9;
 border-radius: 999px;
 background: #fff;
 color: #12314d;
 padding: 7px 12px;
 font-size: 13px;
 cursor: pointer;
 max-width: 320px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 }
 .yk-rx-suggestion:hover,
 .yk-rx-suggestion:focus {
 border-color: #0b74c9;
 color: #075ea8;
 outline: none;
 }
 tr.yk-rx-hidden {
 display: none;
 }
 tr.yk-rx-match {
 background: #eaf6ff;
 }
 </style>
 <script>
 (function() {
 function fold(value) {
 return String(value || "")
 .toLocaleLowerCase("tr-TR")
 .replace(/Ä±/g, "i").replace(/Ä°/g, "i")
 .replace(/ÅŸ/g, "s").replace(/ÄŸ/g, "g")
 .replace(/Ã¼/g, "u").replace(/Ã¶/g, "o")
 .replace(/Ã§/g, "c")
 .normalize("NFD").replace(/[\\u0300-\\u036f]/g, "")
 .replace(/[^a-z0-9]+/g, " ")
 .trim();
 }
 function setup(panel) {
 var input = panel.querySelector("[data-rx-live-input]");
 var rows = Array.prototype.slice.call(
 panel.querySelectorAll("[data-rx-row]"));
 var count = panel.querySelector("[data-rx-count]");
 var suggestions = panel.querySelector("[data-rx-suggestions]");
 if (!input || !rows.length) return;
 function rowMatches(row, query) {
 if (!query) return true;
 var haystack = row.getAttribute("data-rx-search") || "";
 return query.split(" ").every(function(part) {
 return !part || haystack.indexOf(part) !== -1;
 });
 }
 function openRow(row) {
 if (!row) return;
 var href = row.getAttribute("data-rx-href") || "";
 if (href) {
 window.location.href = href;
 return;
 }
 row.scrollIntoView({block: "center", behavior: "smooth"});
 row.classList.add("yk-rx-match");
 setTimeout(function() { row.classList.remove("yk-rx-match"); }, 1200);
 }
 function renderSuggestions(matches, query) {
 if (!suggestions) return;
 suggestions.innerHTML = "";
 if (!query) {
 suggestions.classList.remove("is-open");
 return;
 }
 matches.slice(0, 8).forEach(function(row) {
 var btn = document.createElement("button");
 btn.type = "button";
 btn.className = "yk-rx-suggestion";
 btn.textContent = row.getAttribute("data-rx-title") || "Recete";
 var meta = row.getAttribute("data-rx-meta") || "";
 if (meta) btn.title = meta;
 btn.addEventListener("click", function() { openRow(row); });
 suggestions.appendChild(btn);
 });
 if (!matches.length) {
 var empty = document.createElement("span");
 empty.className = "yk-rx-search-meta";
 empty.textContent = "Sonuc yok";
 suggestions.appendChild(empty);
 }
 suggestions.classList.add("is-open");
 }
 function apply() {
 var query = fold(input.value);
 var matches = [];
 rows.forEach(function(row) {
 var ok = rowMatches(row, query);
 row.classList.toggle("yk-rx-hidden", !ok);
 if (ok) matches.push(row);
 });
 if (count) {
 count.textContent = matches.length + " / " + rows.length;
 }
 renderSuggestions(matches, query);
 }
 input.addEventListener("input", apply);
 input.addEventListener("keydown", function(event) {
 if (event.key !== "Enter") return;
 var first = rows.find(function(row) {
 return !row.classList.contains("yk-rx-hidden");
 });
 if (first) {
 event.preventDefault();
 openRow(first);
 }
 });
 apply();
 }
 document.querySelectorAll("[data-yk-rx-search]").forEach(setup);
 })();
 </script>
 """


def _patient_rx_identity(patient_key):
    header = _get_patient_header_data(patient_key)
    return {
        "patient_name": header.get("display_name") or patient_key,
        "protocol_no": str(header.get("protocol_no") or patient_key),
        "patient_key": patient_key,
    }


VOICE_PRESCRIPTION_SETTING = "voice_prescription_enabled"
VOICE_RX_NUMBER_WORDS = {
    "bir": 1, "iki": 2, "uc": 3, "dort": 4, "bes": 5,
    "alti": 6, "yedi": 7, "sekiz": 8, "dokuz": 9, "on": 10,
}


def _voice_rx_enabled():
    return _db_get_setting(VOICE_PRESCRIPTION_SETTING, "1") != "0"


def _voice_rx_set_enabled(enabled):
    value = "1" if enabled else "0"
    _db_set_setting(VOICE_PRESCRIPTION_SETTING, value)
    try:
        if has_request_context():
            _log_audit("voice_prescription_toggle",
                       entity_type="setting",
                       entity_id=VOICE_PRESCRIPTION_SETTING,
                       details=f"enabled={value}")
    except Exception:
        pass


def _ensure_voice_prescription_schema(con=None):
    def _run(open_con):
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS prescriptions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                patient_key TEXT NOT NULL,
                visit_key TEXT,
                medications TEXT,
                diagnosis TEXT,
                notes TEXT,
                created_by TEXT,
                created_at TEXT
            )
        """)
        _ensure_ready_prescription_schema(open_con)
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS voice_prescription_drafts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                patient_key TEXT,
                patient_name TEXT,
                protocol_no TEXT,
                transcript TEXT NOT NULL,
                diagnosis TEXT DEFAULT '',
                medications TEXT DEFAULT '',
                notes TEXT DEFAULT '',
                status TEXT DEFAULT 'draft',
                print_requested INTEGER DEFAULT 0,
                prescription_id INTEGER,
                created_by TEXT,
                created_at TEXT NOT NULL,
                updated_at TEXT,
                printed_at TEXT
            )
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_voice_rx_patient
            ON voice_prescription_drafts(patient_key, created_at DESC)
        """)
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_voice_rx_status
            ON voice_prescription_drafts(status, created_at DESC)
        """)
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS doctor_prescription_style (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                doctor_user TEXT NOT NULL UNIQUE,
                common_diagnoses TEXT DEFAULT '{}',
                common_medications TEXT DEFAULT '{}',
                style_notes TEXT DEFAULT '',
                updated_at TEXT NOT NULL
            )
        """)

    if con is not None:
        _run(con)
        return
    with db_conn() as open_con:
        _run(open_con)
        open_con.commit()


def _voice_rx_fold_keep_punct(text):
    text = str(text or "").lower()
    text = (text.replace("Ä±", "i").replace("Ä°", "i")
                .replace("ÅŸ", "s").replace("ÄŸ", "g")
                .replace("Ã¼", "u").replace("Ã¶", "o")
                .replace("Ã§", "c")
                .replace("Ä±", "i").replace("Ä°", "i")
                .replace("ÅŸ", "s").replace("ÄŸ", "g")
                .replace("Ã¼", "u").replace("Ã¶", "o")
                .replace("Ã§", "c"))
    text = unicodedata.normalize("NFD", text)
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    text = re.sub(r"[^a-z0-9,.;:+/\-\s]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def _voice_rx_number(raw):
    token = _fold_search_text(raw)
    if not token:
        return None
    m = re.search(r"\d+", token)
    if m:
        try:
            return int(m.group(0))
        except Exception:
            return None
    return VOICE_RX_NUMBER_WORDS.get(token)


VOICE_RX_CATALOG_STOPWORDS = {
    "alex", "aleks", "aleksa", "recete", "receteye", "recetede",
    "yaz", "yazdir", "hazirla", "olustur", "ekle", "ver",
    "tani", "tanisi", "teshis", "endikasyon", "hasta", "protokol",
    "ilac", "ilaci", "ilaclar", "ilaclari", "kutu", "paket",
    "gunde", "gunluk", "kullanim", "kez", "defa", "kere", "sabah",
    "ogle", "aksam", "gece", "tok", "ac", "karna", "rp", "not",
    "tek", "doz",
}


def _voice_rx_unique_texts(values, limit=8):
    results = []
    seen = []
    for value in values or []:
        clean = fix_mojibake_text(str(value or "")).strip()
        if not clean:
            continue
        key = _fold_search_text(clean)
        if not key or any(key == old or key in old or old in key for old in seen):
            continue
        seen.append(key)
        results.append(clean)
        if limit and len(results) >= int(limit):
            break
    return results


def _voice_rx_significant_tokens(text, min_len=3):
    folded = _fold_search_text(text)
    tokens = []
    for token in re.findall(r"[a-z0-9]+", folded):
        if token.isdigit():
            continue
        if len(token) < min_len:
            continue
        if token in VOICE_RX_CATALOG_STOPWORDS:
            continue
        tokens.append(token)
    return tokens


def _voice_rx_best_diagnosis(query):
    raw = fix_mojibake_text(str(query or "")).strip(" .,:;-")
    if not raw:
        return ""
    try:
        matches = _rx_all_diagnoses(limit=10, query=raw)
    except Exception:
        matches = []
    return (matches[0] if matches else raw)[:180]


def _voice_rx_match_diagnoses(text, explicit=""):
    folded = _fold_search_text(text)
    found = []
    if explicit:
        found.append(_voice_rx_best_diagnosis(explicit))

    shortcut_queries = (
        ("vajinit", ("vajinit", "vaginit", "mantar", "kandid", "kandidiyaz", "akinti")),
        ("idrar yolu enfeksiyonu", ("idrar yolu", "sistit", "dizuri", "idrarda yanma")),
        ("gebelik takibi", ("gebe takip", "gebelik takibi", "hamilelik takibi")),
        ("bulanti kusma", ("bulanti", "kusma", "hiperemezis")),
        ("pelvik agri", ("pelvik agri", "kasik agrisi", "dismenore")),
        ("infertilite", ("infertilite", "kisirlik", "tup bebek")),
    )
    for query, keys in shortcut_queries:
        if any(_fold_search_text(key) in folded for key in keys):
            found.append(_voice_rx_best_diagnosis(query))

    try:
        catalog = _rx_all_diagnoses(limit=900)
    except Exception:
        catalog = []
    for diagnosis in catalog:
        diag_fold = _fold_search_text(diagnosis)
        if not diag_fold:
            continue
        if re.search(rf"\b{re.escape(diag_fold)}\b", folded):
            found.append(diagnosis)
            continue
        diag_tokens = _voice_rx_significant_tokens(diagnosis)[:4]
        if diag_tokens and len(diag_tokens) <= 3 and all(
                re.search(rf"\b{re.escape(tok)}\b", folded)
                for tok in diag_tokens):
            found.append(diagnosis)

    return _voice_rx_unique_texts(found, limit=3)


def _voice_rx_best_medication_query(query):
    raw = fix_mojibake_text(str(query or "")).strip(" .,:;-")
    if not raw:
        return None
    try:
        matches = _rx_all_medications(limit=10, query=raw)
    except Exception:
        matches = []
    if matches:
        return matches[0]
    tokens = _voice_rx_significant_tokens(raw)
    for width in range(min(4, len(tokens)), 0, -1):
        q = " ".join(tokens[:width]).strip()
        if not q:
            continue
        try:
            matches = _rx_all_medications(limit=8, query=q)
        except Exception:
            matches = []
        if matches:
            return matches[0]
    for token in tokens:
        try:
            matches = _rx_all_medications(limit=6, query=token)
        except Exception:
            matches = []
        if matches:
            return matches[0]
    return None


def _voice_rx_match_medication_name(raw_name):
    item = _voice_rx_best_medication_query(raw_name)
    if not item:
        return None
    return {
        "name": fix_mojibake_text(str(item.get("name") or "")).strip(),
        "dose": fix_mojibake_text(str(item.get("dose") or "")).strip(),
        "meta": fix_mojibake_text(str(item.get("meta") or "")).strip(),
    }


def _voice_rx_dose_with_frequency(default_dose, freq, med_name=""):
    dose = fix_mojibake_text(str(default_dose or "")).strip()
    if not freq:
        return dose
    freq_text = str(int(freq))
    if re.search(r"\bS\s*:\s*\d+\s*x\s*\d+\b", dose, re.IGNORECASE):
        return re.sub(
            r"\bS\s*:\s*\d+\s*x\s*\d+\b",
            f"S: {freq_text}x1",
            dose,
            flags=re.IGNORECASE,
        )
    med_fold = _fold_search_text(med_name)
    if any(k in med_fold for k in (
            "fitil", "ovul", "vajinal", "vaginal", "supozituvar",
            "suppozituvar", "supposituvar", "krem", "jel")):
        return f"Vajinal S: {freq_text}x1 (Gun)"
    return f"Agizdan (Oral) S: {freq_text}x1 (Gun)"


def _voice_rx_extract_patient_query(text):
    folded = _fold_search_text(text)
    if not folded:
        return ""
    m = re.search(r"\bprotokol\s+(\d+)\b", folded)
    if m:
        return m.group(1)
    m = re.search(
        r"\bhasta\s+(.+?)(?=\s+(?:protokol|tani|tanisi|teshis|ilac|recete|yazdir|bas|cikti)\b|$)",
        folded)
    return (m.group(1).strip() if m else "")


def _voice_rx_find_patient(query):
    query = str(query or "").strip()
    folded_query = _fold_search_text(query)
    if not folded_query:
        return None
    with db_conn() as con:
        _ensure_protocol_schema(con)
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        if folded_query.isdigit():
            row = con.execute(
                "SELECT p.folder_key AS patient_key, p.display_name, "
                "pp.protocol_no FROM patients p "
                "LEFT JOIN patient_protocols pp ON pp.patient_key=p.folder_key "
                "WHERE pp.protocol_no=? LIMIT 1",
                (int(folded_query),)).fetchone()
            if row:
                data = dict(row)
                data["display_name"] = _patient_display_label(
                    data.get("patient_key"), data.get("display_name"))
                return data
        rows = con.execute(
            "SELECT p.folder_key AS patient_key, p.display_name, "
            "pp.protocol_no FROM patients p "
            "LEFT JOIN patient_protocols pp ON pp.patient_key=p.folder_key "
            "ORDER BY COALESCE(p.display_name, p.folder_key) LIMIT 2500"
        ).fetchall()
    for row in rows:
        data = dict(row)
        name = data.get("display_name") or data.get("patient_key") or ""
        key = data.get("patient_key") or ""
        protocol = str(data.get("protocol_no") or "")
        blob = _fold_search_text(" ".join([name, key, protocol]))
        if folded_query == _fold_search_text(protocol) or folded_query in blob:
            data["display_name"] = _patient_display_label(key, name)
            return data
    return None


def _voice_rx_find_patient_from_text(text):
    query = _voice_rx_extract_patient_query(text)
    if query:
        match = _voice_rx_find_patient(query)
        if match:
            return match
    folded_text = _fold_search_text(text)
    if not folded_text:
        return None
    with db_conn() as con:
        _ensure_protocol_schema(con)
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        rows = con.execute(
            "SELECT p.folder_key AS patient_key, p.display_name, "
            "pp.protocol_no FROM patients p "
            "LEFT JOIN patient_protocols pp ON pp.patient_key=p.folder_key "
            "ORDER BY COALESCE(p.display_name, p.folder_key) LIMIT 2500"
        ).fetchall()
    candidates = []
    for row in rows:
        data = dict(row)
        name = data.get("display_name") or data.get("patient_key") or ""
        key = data.get("patient_key") or ""
        protocol = str(data.get("protocol_no") or "")
        name_fold = _fold_search_text(name)
        key_fold = _fold_search_text(key)
        score = 0
        if protocol and re.search(rf"\b{re.escape(protocol)}\b", folded_text):
            score = 100
        elif name_fold and name_fold in folded_text:
            score = 90
        elif key_fold and key_fold in folded_text:
            score = 80
        else:
            tokens = [t for t in name_fold.split() if len(t) >= 3]
            hits = [t for t in tokens if re.search(rf"\b{re.escape(t)}\b", folded_text)]
            if hits:
                score = 20 + len(hits)
        if score:
            data["display_name"] = _patient_display_label(key, name)
            candidates.append((score, data))
    if not candidates:
        return None
    candidates.sort(key=lambda item: item[0], reverse=True)
    return candidates[0][1]


def _voice_rx_extract_diagnosis(text):
    folded = _voice_rx_fold_keep_punct(text)
    m = re.search(
        r"\b(?:tani|tanisi|teshis|endikasyon)\s+(.+?)"
        r"(?=\s+(?:ilac|ilaci|ilaclari|recete|rp|not|hasta|protokol|yazdir|bas|cikti)\b|$)",
        folded)
    if not m:
        return ""
    diagnosis = re.sub(r"\s+", " ", m.group(1)).strip(" ,.;:-")
    return diagnosis[:160]


def _voice_rx_split_med_chunks(text):
    folded = _voice_rx_fold_keep_punct(text)
    if not folded:
        return []
    folded = re.sub(r"\b(?:yazdir|cikti\s+al|bas)\b.*$", "", folded)
    folded = re.sub(r"\b(?:alex|aleks|aleksa)\b", " ", folded)
    folded = re.sub(
        r"\brecete\s+(?:yaz|hazirla|olustur|ekle)\b", " ", folded)
    folded = re.sub(r"\b(?:recete|yaz|hazirla|olustur)\b", " ", folded)
    markers = r"\b(?:ilac|ilaci|ilaclar|ilaclari|receteye|rp)\b"
    parts = re.split(markers, folded)
    if len(parts) > 1:
        source = " ; ".join(parts[1:])
    elif any(k in folded for k in ("gunde", "kutu", "tablet", "mg", "kapsul")):
        source = folded
    else:
        return []
    for diagnosis in _voice_rx_match_diagnoses(text):
        diag_fold = _voice_rx_fold_keep_punct(diagnosis)
        if diag_fold:
            source = re.sub(rf"\b{re.escape(diag_fold)}\b", " ", source)
        for token in _voice_rx_significant_tokens(diagnosis):
            source = re.sub(rf"\b{re.escape(token)}\b", " ", source)
    source = re.sub(
        r"\b(?:tani|tanisi|teshis|endikasyon|hasta|protokol|not)\b.*$",
        " ", source)
    source = re.sub(
        r"\b(?:tanisiyle|tanisiyla|icin|nedeniyle|receteye|ekle|kullan|kullanilacak|ver|yaz)\b",
        " ", source)
    source = re.sub(
        r"\b(gunde\s+[a-z0-9]+\s*(?:kez|defa|kere|x)(?:\s+(?:tok|ac)\s+karna)?)\s+(?!(?:tok|ac)\b)(?=[a-z]{3,}\b)",
        r"\1 ; ",
        source)
    source = re.sub(
        r"\b([a-z0-9]+\s*(?:kutu|paket))\s+(?!(?:gunde|gunluk|tok|ac|sabah|ogle|aksam|gece|tek|doz)\b)(?=[a-z]{3,}\b)",
        r"\1 ; ",
        source)
    raw_chunks = re.split(r"[,;]+|\s+\+\s+|\s+arti\s+", source)
    chunks = []
    for chunk in raw_chunks:
        chunk = re.sub(r"\s+", " ", chunk).strip(" .,:;-")
        if chunk:
            chunks.append(chunk)
    return chunks


def _voice_rx_format_medication_chunk(chunk, idx):
    text = re.sub(r"\s+", " ", str(chunk or "")).strip(" .,:;-")
    if not text:
        return None
    freq = None
    m = re.search(
        r"\bgunde\s+([a-z0-9]+)\s*(?:kez|defa|kere|x)\b", text)
    if m:
        freq = _voice_rx_number(m.group(1))
    elif "sabah" in text and "aksam" in text:
        freq = 2
    elif "gece" in text:
        freq = 1

    box_count = None
    m = re.search(r"\b([a-z0-9]+)\s*(?:kutu|paket)\b", text)
    if m:
        box_count = _voice_rx_number(m.group(1))

    timing = ""
    if "tok karna" in text:
        timing = "tok karna"
    elif "ac karna" in text:
        timing = "ac karna"
    elif "sabah" in text and "aksam" in text:
        timing = "sabah/aksam"
    elif "gece" in text:
        timing = "gece"

    name = text
    name = re.sub(
        r"\bgunde\s+[a-z0-9]+\s*(?:kez|defa|kere|x)\b", " ", name)
    name = re.sub(r"\b[a-z0-9]+\s*(?:kutu|paket)\b", " ", name)
    name = re.sub(
        r"\b(?:sabah\s+ve\s+aksam|sabah\s+aksam|sabah|ogle|aksam|gece)\b",
        " ", name)
    name = re.sub(r"\b(?:tok|ac)\s+karna\b", " ", name)
    name = re.sub(r"\b(?:tek\s+doz|tek|doz)\b", " ", name)
    name = re.sub(r"\b(?:kullan|kullanilacak|ver|yaz)\b", " ", name)
    name = re.sub(r"\s+", " ", name).strip(" .,:;-")
    if not _voice_rx_significant_tokens(name, min_len=2):
        return None
    if not name:
        if timing:
            return None
        name = text[:80]

    catalog_match = _voice_rx_match_medication_name(name)
    matched_name = (catalog_match or {}).get("name") or name
    dose = _voice_rx_dose_with_frequency(
        (catalog_match or {}).get("dose") or "", freq,
        f"{name} {matched_name} {text}")

    details = []
    if dose:
        details.extend(line.strip() for line in dose.splitlines() if line.strip())
    if box_count:
        details.append(_rx_box_display(box_count))
    if freq:
        details.append(f"Gunde: {freq} kez")
    if timing:
        details.append(f"Zaman: {timing}")
    return {
        "name": matched_name[:160],
        "dose": dose,
        "box_count": str(box_count or ""),
        "daily_frequency": str(freq or ""),
        "catalog_match": bool(catalog_match),
        "details": details,
        "line": "\n".join([f"{idx}) {matched_name[:160]}"] + details),
    }


def _voice_rx_extract_notes(text):
    folded = _voice_rx_fold_keep_punct(text)
    m = re.search(r"\bnot\s+(.+?)(?=\s+(?:yazdir|bas|cikti)\b|$)", folded)
    return (m.group(1).strip(" .,:;-")[:300] if m else "")


def _voice_rx_parse_transcript(text):
    transcript = re.sub(r"\s+", " ", str(text or "")).strip()
    folded = _fold_search_text(transcript)
    explicit_diagnosis = _voice_rx_extract_diagnosis(transcript)
    diagnosis_matches = _voice_rx_match_diagnoses(
        transcript, explicit=explicit_diagnosis)
    diagnosis = " / ".join(diagnosis_matches) if diagnosis_matches else explicit_diagnosis
    chunks = _voice_rx_split_med_chunks(transcript)
    items = []
    for chunk in chunks:
        item = _voice_rx_format_medication_chunk(chunk, len(items) + 1)
        if item:
            items.append(item)
    medications = "\n".join(item["line"] for item in items)
    notes = _voice_rx_extract_notes(transcript)
    print_now = any(k in folded for k in (
        "yazdir", "cikti al", "recete yazdir", "bas"))
    enable_voice = any(k in folded for k in (
        "sesli recete ac", "sesli komut ac", "mikrofon ac"))
    disable_voice = any(k in folded for k in (
        "sesli recete kapat", "sesli komut kapat", "mikrofon kapat"))
    if not medications and transcript and "ilac" not in folded:
        notes = notes or transcript[:300]
    return {
        "transcript": transcript,
        "patient_query": _voice_rx_extract_patient_query(transcript),
        "diagnosis": diagnosis,
        "medications": medications,
        "medication_items": items,
        "notes": notes,
        "print_now": bool(print_now),
        "enable_voice": bool(enable_voice),
        "disable_voice": bool(disable_voice),
    }


def _voice_rx_save_draft(patient_key, transcript, parsed):
    _ensure_voice_prescription_schema()
    rx_identity = _patient_rx_identity(patient_key)
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    with db_conn() as con:
        _ensure_voice_prescription_schema(con)
        cur = con.execute(
            "INSERT INTO voice_prescription_drafts("
            "patient_key, patient_name, protocol_no, transcript, diagnosis, "
            "medications, notes, status, print_requested, created_by, "
            "created_at, updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
            (patient_key, rx_identity["patient_name"],
             str(rx_identity["protocol_no"]), transcript or "",
             parsed.get("diagnosis") or "", parsed.get("medications") or "",
             parsed.get("notes") or "", "draft",
             1 if parsed.get("print_now") else 0, _current_session_user("?"),
             now, now))
        con.commit()
        return cur.lastrowid


def _voice_rx_get_draft(draft_id):
    if not draft_id:
        return None
    _ensure_voice_prescription_schema()
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        row = con.execute(
            "SELECT * FROM voice_prescription_drafts WHERE id=?",
            (int(draft_id),)).fetchone()
    return dict(row) if row else None


def _voice_rx_json_counts(value):
    import json as _json
    try:
        data = _json.loads(value or "{}")
        if isinstance(data, dict):
            return {str(k): int(v or 0) for k, v in data.items() if k}
    except Exception:
        pass
    return {}


def _voice_rx_trim_counts(counts, limit=40):
    pairs = sorted(counts.items(), key=lambda item: (-int(item[1]), item[0]))
    return dict(pairs[:limit])


def _voice_rx_style_profile():
    import json as _json
    _ensure_voice_prescription_schema()
    doctor_user = _current_session_user("doktor")
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        row = con.execute(
            "SELECT * FROM doctor_prescription_style WHERE doctor_user=?",
            (doctor_user,)).fetchone()
    if not row:
        return {"diagnoses": [], "medications": [], "style_notes": ""}
    row = dict(row)
    diagnoses = _voice_rx_json_counts(row.get("common_diagnoses"))
    medications = _voice_rx_json_counts(row.get("common_medications"))
    top_diag = sorted(diagnoses.items(), key=lambda item: -item[1])[:8]
    top_meds = sorted(medications.items(), key=lambda item: -item[1])[:8]
    return {
        "diagnoses": top_diag,
        "medications": top_meds,
        "style_notes": row.get("style_notes") or "",
        "raw": {
            "diagnoses": _json.dumps(diagnoses, ensure_ascii=False),
            "medications": _json.dumps(medications, ensure_ascii=False),
        },
    }


def _voice_rx_update_doctor_style(parsed):
    import json as _json
    if not parsed:
        return
    _ensure_voice_prescription_schema()
    doctor_user = _current_session_user("doktor")
    diagnosis = (parsed.get("diagnosis") or "").strip().lower()
    med_names = []
    for item in parsed.get("medication_items") or []:
        name = (item.get("name") or "").strip().lower()
        if name:
            med_names.append(name)
    for line in str(parsed.get("medications") or "").splitlines():
        m = re.match(r"^\d+\s*[-.)]\s*(.+)$", line.strip())
        if m:
            med_names.append(m.group(1).strip().lower())
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    with db_conn() as con:
        _ensure_voice_prescription_schema(con)
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        row = con.execute(
            "SELECT * FROM doctor_prescription_style WHERE doctor_user=?",
            (doctor_user,)).fetchone()
        diag_counts = _voice_rx_json_counts(
            row.get("common_diagnoses") if row else "{}")
        med_counts = _voice_rx_json_counts(
            row.get("common_medications") if row else "{}")
        if diagnosis:
            diag_counts[diagnosis] = diag_counts.get(diagnosis, 0) + 1
        for name in med_names:
            med_counts[name] = med_counts.get(name, 0) + 1
        diag_json = _json.dumps(_voice_rx_trim_counts(diag_counts),
                               ensure_ascii=False)
        med_json = _json.dumps(_voice_rx_trim_counts(med_counts),
                              ensure_ascii=False)
        notes = "Onaylanan sesli recetelerden otomatik ogrenildi."
        if row:
            con.execute(
                "UPDATE doctor_prescription_style SET common_diagnoses=?, "
                "common_medications=?, style_notes=?, updated_at=? "
                "WHERE doctor_user=?",
                (diag_json, med_json, notes, now, doctor_user))
        else:
            con.execute(
                "INSERT INTO doctor_prescription_style("
                "doctor_user, common_diagnoses, common_medications, "
                "style_notes, updated_at) VALUES(?,?,?,?,?)",
                (doctor_user, diag_json, med_json, notes, now))
        con.commit()


def _voice_rx_create_prescription(patient_key, parsed, draft_id=None,
                                  auto_print=False):
    rx_identity = _patient_rx_identity(patient_key)
    patient_name = rx_identity["patient_name"]
    protocol_no = str(rx_identity["protocol_no"])
    diagnosis = (parsed.get("diagnosis") or "").strip()
    medications = (parsed.get("medications") or "").strip()
    notes = (parsed.get("notes") or "").strip()
    if not medications:
        raise ValueError("Recete metni bos olamaz.")
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    today = datetime.now().strftime("%d.%m.%Y")
    with db_conn() as con:
        _ensure_voice_prescription_schema(con)
        cur = con.execute(
            "INSERT INTO prescriptions(patient_key, medications, diagnosis, "
            "notes, created_by, created_at, template_name, purpose, "
            "patient_name, protocol_no) VALUES(?,?,?,?,?,?,?,?,?,?)",
            (patient_key, medications, diagnosis, notes,
             _current_session_user("?"), now, "Sesli recete",
             diagnosis or "Sesli recete", patient_name, protocol_no))
        prescription_id = cur.lastrowid
        if draft_id:
            con.execute(
                "UPDATE voice_prescription_drafts SET status=?, "
                "prescription_id=?, print_requested=?, updated_at=?, "
                "printed_at=CASE WHEN ? THEN ? ELSE printed_at END "
                "WHERE id=?",
                ("printed" if auto_print else "approved", prescription_id,
                 1 if auto_print else 0, now, 1 if auto_print else 0, now,
                 int(draft_id)))
        con.commit()
    _voice_rx_update_doctor_style(parsed)
    try:
        _memory_extract_from_text(
            patient_key,
            "\n".join([diagnosis, medications, notes]),
            source="voice_prescription")
    except Exception:
        pass
    try:
        _log_audit("voice_prescription_create",
                   entity_type="patient", entity_id=str(patient_key),
                   details=f"prescription_id={prescription_id}")
    except Exception:
        pass
    html = _build_prescription_print_html(
        patient_name, protocol_no, diagnosis, medications, notes, today,
        auto_print=auto_print)
    return prescription_id, html


def _voice_rx_patient_from_path(current_path):
    path = str(current_path or "")
    m = re.search(r"/hasta/([^/?#]+)", path)
    if not m:
        return None
    patient_key = unquote(m.group(1)).strip()
    if not patient_key:
        return None
    match = _voice_rx_find_patient(patient_key)
    if match:
        return match
    try:
        ident = _patient_rx_identity(patient_key)
        return {
            "patient_key": patient_key,
            "display_name": ident.get("patient_name") or patient_key,
            "protocol_no": ident.get("protocol_no") or "",
        }
    except Exception:
        return {"patient_key": patient_key, "display_name": patient_key, "protocol_no": ""}


def _voice_rx_command_intent(text, current_path=""):
    folded = _fold_search_text(text)
    if not folded:
        return False
    if any(k in folded for k in (
            "recete yaz", "recete hazirla", "sesli recete", "receteye",
            "recete olustur", "recete ekle", "ilac ekle", "tani ekle")):
        return True
    if "recete" in _fold_search_text(current_path) and any(k in folded for k in (
            "ilac", "tani", "tanisi", "kutu", "gunde", "tablet", "kapsul", "mg")):
        return True
    return False


def _voice_rx_apply_from_command(message, current_path=""):
    if not _voice_rx_command_intent(message, current_path=current_path):
        return None
    if not can("edit_prescription"):
        return {
            "ok": False,
            "status": "forbidden",
            "answer": "Recete yazma yetkin yok; doktor yetkisiyle giris gerekiyor.",
            "result": "Recete yazma yetkin yok; doktor yetkisiyle giris gerekiyor.",
        }

    if not _voice_rx_enabled():
        try:
            _voice_rx_set_enabled(True)
        except Exception:
            pass

    patient_match = (
        _voice_rx_find_patient_from_text(message)
        or _voice_rx_patient_from_path(current_path)
        or _smart_dialog_active_patient_match()
    )
    patient_key = str((patient_match or {}).get("patient_key") or "").strip()
    if not patient_key:
        return {
            "ok": False,
            "status": "needs_patient",
            "answer": "Recete icin once hastayi secmem gerekiyor. Hasta ekranini aciyorum.",
            "result": "Recete icin once hastayi secmem gerekiyor. Hasta ekranini aciyorum.",
            "action": {
                "key": "open_route",
                "label": "Hastalari ac",
                "route": "/hastalar",
            },
        }

    parsed = _voice_rx_parse_transcript(message)
    medications = (parsed.get("medications") or "").strip()
    diagnosis = (parsed.get("diagnosis") or "").strip()
    rx_identity = _patient_rx_identity(patient_key)
    patient_name = rx_identity.get("patient_name") or (
        patient_match or {}).get("display_name") or patient_key
    q_patient = quote(str(patient_key), safe="")

    if not medications:
        try:
            session["rx_prepare_voice_prefill"] = {
                "patient_key": patient_key,
                "transcript": message,
                "parsed": parsed,
            }
        except Exception:
            pass
        draft_id = _voice_rx_save_draft(patient_key, message, parsed) if diagnosis else ""
        route = f"/hasta/{q_patient}/recete-hazirla"
        if draft_id:
            route += f"?draft_id={int(draft_id)}"
        answer = (
            f"{patient_name} icin recete hazirlik ekranini actim."
            + (f" Taniyi buldum: {diagnosis}." if diagnosis else "")
            + " Alex recete yardimcisina ilaci, kutuyu ve gunluk kullanim sayisini soyle; ekleyecegim."
        )
        return {
            "ok": True,
            "status": "voice_rx_open",
            "answer": answer,
            "result": answer,
            "parsed": parsed,
            "action": {
                "key": "open_route",
                "label": "Sesli recete",
                "route": route,
            },
        }

    draft_id = _voice_rx_save_draft(patient_key, message, parsed)
    prescription_id, _html = _voice_rx_create_prescription(
        patient_key, parsed, draft_id=draft_id, auto_print=parsed.get("print_now"))
    med_names = [
        str(item.get("name") or "").strip()
        for item in parsed.get("medication_items") or []
        if str(item.get("name") or "").strip()
    ]
    summary_parts = []
    if diagnosis:
        summary_parts.append(f"tani: {diagnosis}")
    if med_names:
        summary_parts.append("ilac: " + ", ".join(med_names[:4]))
    route = f"/hasta/{q_patient}/recete-hazirla?rx_id={int(prescription_id)}"
    answer = (
        f"{patient_name} icin receteyi hazirladim. "
        + ("; ".join(summary_parts) if summary_parts else "Ilac bilgileri islendi.")
        + ". Kutu ve gunde kac kez bilgilerini de receteye ekledim."
    )
    return {
        "ok": True,
        "status": "voice_rx_created",
        "answer": answer,
        "result": answer,
        "prescription_id": int(prescription_id),
        "draft_id": int(draft_id or 0),
        "patient": rx_identity,
        "parsed": parsed,
        "action": {
            "key": "open_route",
            "label": "Receteyi ac",
            "route": route,
            "args": {
                "patient_key": patient_key,
                "prescription_id": int(prescription_id),
            },
        },
    }


def _voice_rx_chips_html(items, empty_text):
    chips = ""
    for label, count in items:
        chips += (
            f'<span class="badge rounded-pill bg-light text-dark border me-1">'
            f'{sh(label)} <span class="text-muted">x{int(count)}</span></span>')
    return chips or f'<span class="text-muted">{sh(empty_text)}</span>'


