def _upcoming_appointments(patient_key, limit=3):
    _init_appointments_table()
    today = datetime.now().strftime("%Y-%m-%d")
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            rows = con.execute(
                "SELECT * FROM appointments WHERE patient_key=? "
                "AND appointment_date>=? AND status!='cancelled' "
                "ORDER BY appointment_date, appointment_time LIMIT ?",
                (patient_key, today, int(limit))).fetchall()
        return [dict(r) for r in rows]
    except Exception:
        return []


def _clinical_assistant_payload(patient_key):
    rx_identity = _patient_rx_identity(patient_key)
    memory = _memory_list(patient_key, active_only=True, limit=12)
    latest_note = _latest_patient_note(patient_key)
    latest_rx = _latest_prescriptions(patient_key, limit=5)
    upcoming = _upcoming_appointments(patient_key, limit=4)
    style = _voice_rx_style_profile()
    warnings = []
    if latest_rx:
        top = latest_rx[0]
        warnings = _prescription_safety_checks(
            patient_key, top.get("diagnosis") or "",
            top.get("medications") or "", top.get("notes") or "")
    return {
        "identity": rx_identity,
        "memory": memory,
        "latest_note": latest_note,
        "latest_rx": latest_rx,
        "upcoming": upcoming,
        "style": style,
        "warnings": warnings,
    }


def _workflow_extract_days(text):
    folded = _fold_search_text(text)
    m = re.search(r"\b(\d+)\s+gun\s+sonra\b", folded)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            pass
    if "hafta sonra" in folded:
        return 7
    if "yarin" in folded:
        return 1
    return None


def _workflow_create_draft(command_text):
    text = str(command_text or "").strip()
    match = _voice_rx_find_patient_from_text(text)
    patient_key = match.get("patient_key") if match else ""
    patient_name = match.get("display_name") if match else ""
    parsed = _voice_rx_parse_transcript(text)
    days = _workflow_extract_days(text)
    appt_hint = ""
    if days is not None:
        appt_date = (datetime.now() + timedelta(days=days)).strftime("%Y-%m-%d")
        appt_hint = f"{appt_date} kontrol randevusu"
    elif "randevu" in _fold_search_text(text):
        appt_hint = "Randevu isteniyor; tarih/saat doktor onayi bekler."
    whatsapp_hint = "WhatsApp bilgilendirmesi" if "whatsapp" in _fold_search_text(text) else ""
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    _ensure_clinical_assistant_schema()
    with db_conn() as con:
        cur = con.execute(
            "INSERT INTO ai_workflow_drafts("
            "patient_key, patient_name, command_text, prescription_hint, "
            "appointment_hint, whatsapp_hint, status, created_by, created_at) "
            "VALUES(?,?,?,?,?,?,?,?,?)",
            (patient_key, patient_name, text, parsed.get("transcript") or text,
             appt_hint, whatsapp_hint, "draft", _current_session_user("?"), now))
        con.commit()
        draft_id = cur.lastrowid
    return {
        "id": draft_id,
        "patient_key": patient_key,
        "patient_name": patient_name,
        "prescription_hint": parsed.get("transcript") or text,
        "appointment_hint": appt_hint,
        "whatsapp_hint": whatsapp_hint,
    }


def _daily_clinic_summary(summary_date=None):
    _ensure_clinical_assistant_schema()
    _ensure_ready_prescription_schema()
    day = summary_date or datetime.now().strftime("%Y-%m-%d")
    result = {
        "date": day,
        "appointments": 0,
        "prescriptions": 0,
        "voice_drafts": 0,
        "pending_appointments": 0,
        "memory_cards": 0,
        "lines": [],
    }
    with db_conn() as con:
        try:
            result["appointments"] = con.execute(
                "SELECT COUNT(*) FROM appointments WHERE appointment_date=? "
                "AND status!='cancelled'", (day,)).fetchone()[0]
        except Exception:
            pass
        try:
            result["prescriptions"] = con.execute(
                "SELECT COUNT(*) FROM prescriptions "
                "WHERE substr(created_at,1,10)=? "
                "AND COALESCE(deleted_at,'')=''",
                (day,)).fetchone()[0]
        except Exception:
            pass
        try:
            result["voice_drafts"] = con.execute(
                "SELECT COUNT(*) FROM voice_prescription_drafts "
                "WHERE substr(created_at,1,10)=?", (day,)).fetchone()[0]
        except Exception:
            pass
        try:
            result["pending_appointments"] = con.execute(
                "SELECT COUNT(*) FROM ai_phone_pending_appointments "
                "WHERE status NOT IN ('booked','done','cancelled')").fetchone()[0]
        except Exception:
            pass
        try:
            result["memory_cards"] = con.execute(
                "SELECT COUNT(*) FROM patient_memory_cards WHERE is_active=1").fetchone()[0]
        except Exception:
            pass
    result["lines"] = [
        f"{day} ozeti",
        f"Randevu: {result['appointments']}",
        f"Recete: {result['prescriptions']}",
        f"Sesli recete taslagi: {result['voice_drafts']}",
        f"Onay bekleyen randevu talebi: {result['pending_appointments']}",
        f"Aktif hasta hafiza karti: {result['memory_cards']}",
    ]
    return result


def _command_center_patient_tool_result(args):
    tool = str((args or {}).get("tool") or "patient").strip()
    query = str((args or {}).get("patient_query") or "").strip()
    match = _voice_rx_find_patient(query) or _voice_rx_find_patient_from_text(query)
    if not match:
        return False, f"Hasta bulunamadi: {query or '-'}"
    patient_key = match.get("patient_key")
    name = match.get("display_name") or patient_key
    routes = {
        "patient": f"/hasta/{quote(str(patient_key), safe='')}",
        "voice_rx": f"/hasta/{quote(str(patient_key), safe='')}/sesli-recete",
        "rx": f"/hasta/{quote(str(patient_key), safe='')}/recete-hazirla",
        "appointment": f"/randevu/yeni?hasta={quote(str(patient_key), safe='')}",
        "lab": f"/hasta/{quote(str(patient_key), safe='')}/tetkik-istemi",
        "whatsapp": f"/hasta/{quote(str(patient_key), safe='')}/whatsapp",
        "assistant": f"/hasta/{quote(str(patient_key), safe='')}/akilli-asistan",
        "diet": f"/hasta/{quote(str(patient_key), safe='')}/yz-diyet",
        "hd_studio": f"/hasta/{quote(str(patient_key), safe='')}/yz-resim-iyilestir",
        "memory": f"/hasta/{quote(str(patient_key), safe='')}/hafiza",
        "file_explorer": f"/hasta/{quote(str(patient_key), safe='')}/dosya-gezgini",
        "voice_note": f"/hasta/{quote(str(patient_key), safe='')}/konusarak-not",
    }
    if tool == "last_note":
        note = _latest_patient_note(patient_key)
        if not note:
            return True, f"{name}: kayitli son not bulunamadi."
        return True, (
            f"{name} son not:\n"
            f"{note.get('visit_date') or note.get('updated_at') or '-'}\n"
            f"{note.get('note') or ''}")
    return True, f"{name} icin acilacak yol: {routes.get(tool, routes['patient'])}"


def _open_patient_folder_result(args):
    query = str((args or {}).get("patient_query") or "").strip()
    match = _voice_rx_find_patient(query) or _voice_rx_find_patient_from_text(query)
    if not match:
        return False, f"Hasta bulunamadi: {query or '-'}"
    patient_key = match.get("patient_key")
    root = _patient_root_for_nas(patient_key)
    try:
        if not root.exists():
            return False, f"Hasta klasoru bulunamadi: {root}"
    except Exception as ex:
        return False, f"Hasta klasoru kontrol edilemedi: {ex}"
    if os.name == "nt":
        try:
            os.startfile(str(root))  # noqa: S606 - whitelisted patient folder
            return True, (
                f"Hasta Windows klasoru acildi: {root}\n"
                f"Web dosya gezgini: /hasta/{quote(str(patient_key), safe='')}/dosya-gezgini")
        except Exception as ex:
            return False, f"Hasta klasoru acilamadi: {root}\nHata: {ex}"
    return True, f"Hasta klasoru: {root}"


def _patient_latest_pdf_print_target(patient_key):
    q_patient = quote(str(patient_key), safe="")
    latest = None
    try:
        entries = [
            e for e in _scan_patient_nas_media(
                patient_key, max_candidates=500, timeout=7.5)
            if e.get("kind") == "pdf"
        ]
    except Exception:
        entries = []
    for entry in entries:
        try:
            path = Path(entry.get("path"))
            rel = _patient_media_rel_url(patient_key, path)
            if not rel:
                continue
            mtime = float(entry.get("mtime") or path.stat().st_mtime or 0)
            item = {"path": path, "rel": rel, "mtime": mtime, "name": path.name}
            if latest is None or item["mtime"] > latest["mtime"]:
                latest = item
        except Exception:
            continue
    if latest is None:
        try:
            pdfs = _pdf_editor_list_pdfs(patient_key, limit=1)
        except Exception:
            pdfs = []
        if pdfs:
            latest = {
                "path": None,
                "rel": pdfs[0].get("rel") or "",
                "mtime": 0,
                "name": pdfs[0].get("name") or "rapor.pdf",
            }
    if not latest or not latest.get("rel"):
        return None
    media_url = f"/hasta/{q_patient}/medya-dosya/{quote(str(latest['rel']), safe='/')}"
    print_url = (
        "/yk-print-media?kind=pdf&src=" + quote(media_url, safe="")
        + "&title=" + quote(str(latest.get("name") or "Rapor PDF"), safe="")
        + "&autoprint=1"
    )
    return {
        "patient_key": patient_key,
        "name": latest.get("name") or "rapor.pdf",
        "media_url": media_url,
        "print_url": print_url,
    }


def _command_center_pdf_print_result(args):
    query = str((args or {}).get("patient_query") or "").strip()
    match = _voice_rx_find_patient(query) or _voice_rx_find_patient_from_text(query)
    if not match:
        return False, f"Hasta bulunamadi: {query or '-'}"
    patient_key = match.get("patient_key")
    target = _patient_latest_pdf_print_target(patient_key)
    if not target:
        return False, (
            f"{match.get('display_name') or patient_key} icin PDF bulunamadi. "
            f"Dosya gezgini: /hasta/{quote(str(patient_key), safe='')}/dosya-gezgini")
    return True, (
        f"PDF yazdirma sayfasi hazir: {target['name']}\n"
        f"{target['print_url']}\n"
        "Bu adres acilinca yazdirma penceresi otomatik tetiklenir.")


def _extract_patient_note_command(text):
    folded = _fold_search_text(text)
    if not folded:
        return ""
    raw = str(text or "").strip()
    patterns = [
        r"\bnot(?:lara|a)?\s+ekle[:\s-]*(.+)$",
        r"\bhasta\s+notuna\s+ekle[:\s-]*(.+)$",
        r"\bdosyaya\s+not\s+ekle[:\s-]*(.+)$",
    ]
    raw_fold = _voice_rx_fold_keep_punct(raw)
    for pat in patterns:
        m = re.search(pat, raw_fold)
        if m:
            return m.group(1).strip(" .,:;-")
    return ""


def _command_center_append_note_result(args):
    text = str((args or {}).get("command_text") or "").strip()
    match = _voice_rx_find_patient_from_text(text)
    if not match:
        return False, "Not eklenecek hasta bulunamadi."
    note_text = str((args or {}).get("note_text") or "").strip()
    if not note_text:
        return False, "Eklenecek not metni bulunamadi."
    _append_patient_general_note(
        match.get("patient_key"), note_text, source_label="Komut merkezi notu")
    return True, (
        f"{match.get('display_name') or match.get('patient_key')} hasta notuna eklendi:\n"
        f"{note_text}")


def _command_center_workflow_result(args):
    draft = _workflow_create_draft((args or {}).get("command_text") or "")
    if not draft.get("patient_key"):
        return False, "Zincir taslak olustu ama hasta bulunamadi; hasta adi/protokol ekleyin."
    pk = quote(str(draft["patient_key"]), safe="")
    lines = [
        f"Zincir islem taslagi #{draft['id']}: {draft.get('patient_name') or pk}",
        f"Sesli recete: /hasta/{pk}/sesli-recete",
        f"Randevu: /randevu/yeni?hasta={pk}",
        f"WhatsApp: /hasta/{pk}/whatsapp",
        f"Taslaklar: /islem-zincirleri",
    ]
    if draft.get("appointment_hint"):
        lines.append("Randevu ipucu: " + draft["appointment_hint"])
    return True, "\n".join(lines)


@app.route("/hasta/<patient_key>/hafiza", methods=["GET", "POST"])
@permission_required("view_patient_notes")
def patient_memory_page(patient_key):
    _ensure_clinical_assistant_schema()
    if request.method == "POST":
        action = request.form.get("action", "add")
        if action == "deactivate":
            if not can("edit_patient_notes"):
                flash("Duzenleme yetkiniz yok.", "danger")
            else:
                _memory_deactivate(request.form.get("memory_id"))
                flash("Hafiza karti pasife alindi.", "success")
            return redirect(url_for("patient_memory_page", patient_key=patient_key))
        if action == "scan":
            added = _memory_scan_patient(patient_key)
            flash(f"Otomatik tarama tamamlandi. Eklenen kart: {added}", "success")
            return redirect(url_for("patient_memory_page", patient_key=patient_key))
        if not can("edit_patient_notes"):
            flash("Duzenleme yetkiniz yok.", "danger")
            return redirect(url_for("patient_memory_page", patient_key=patient_key))
        _memory_add(
            patient_key,
            request.form.get("title"),
            request.form.get("detail"),
            request.form.get("memory_type") or "note",
            request.form.get("importance") or "normal",
            "manual")
        flash("Hasta hafiza karti eklendi.", "success")
        return redirect(url_for("patient_memory_page", patient_key=patient_key))

    cards = _memory_list(patient_key, active_only=False, limit=120)
    rows = ""
    for card in cards:
        badge = {
            "critical": "danger", "high": "warning", "normal": "secondary"
        }.get(card.get("importance"), "secondary")
        inactive = "" if int(card.get("is_active") or 0) else "opacity:.45;"
        deactivate = ""
        if can("edit_patient_notes") and int(card.get("is_active") or 0):
            deactivate = f"""
            <form method="POST" class="d-inline">
              <input type="hidden" name="action" value="deactivate">
              <input type="hidden" name="memory_id" value="{int(card.get('id') or 0)}">
              <button class="btn btn-sm btn-outline-secondary">Pasife al</button>
            </form>
            """
        rows += f"""
        <tr style="{inactive}">
          <td><span class="badge bg-{badge}">{sh(card.get('importance'))}</span></td>
          <td><b>{sh(card.get('title'))}</b><br><small>{sh(card.get('memory_type'))} / {sh(card.get('source'))}</small></td>
          <td>{sh(card.get('detail'))}</td>
          <td>{sh((card.get('updated_at') or '')[:16])}</td>
          <td class="text-end">{deactivate}</td>
        </tr>
        """
    create_form = ""
    if can("edit_patient_notes"):
        create_form = f"""
        <form method="POST" class="card mb-4">
          <div class="card-body row g-3">
            <div class="col-md-3">
              <label class="form-label">Tip</label>
              <select name="memory_type" class="form-select">
                <option value="allergy">Alerji</option>
                <option value="diagnosis">Tani</option>
                <option value="preference">Calisma notu</option>
                <option value="note">Not</option>
              </select>
            </div>
            <div class="col-md-3">
              <label class="form-label">Onem</label>
              <select name="importance" class="form-select">
                <option value="critical">Kritik</option>
                <option value="high">Yuksek</option>
                <option value="normal" selected>Normal</option>
              </select>
            </div>
            <div class="col-md-6">
              <label class="form-label">Baslik</label>
              <input name="title" class="form-control" required>
            </div>
            <div class="col-12">
              <label class="form-label">Detay</label>
              <textarea name="detail" class="form-control" rows="3"></textarea>
            </div>
            <div class="col-12 d-flex gap-2">
              <button class="btn btn-success">Hafizaya ekle</button>
              <button name="action" value="scan" class="btn btn-outline-primary">Notlardan otomatik tara</button>
            </div>
          </div>
        </form>
        """
    content = f"""
    <a href="/hasta/{patient_key}" class="btn btn-secondary mb-3">Hasta detay</a>
    <div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3">
      <h2 class="mb-0">Hasta Hafizasi - {sh(patient_key)}</h2>
      <a href="/hasta/{patient_key}/akilli-asistan" class="btn btn-outline-primary">Akıllı asistan</a>
    </div>
    {create_form}
    <div class="card">
      <div class="card-header"><b>Hafiza kartlari</b></div>
      <div class="card-body p-0">
        <table class="table table-hover mb-0">
          <thead><tr><th>Onem</th><th>Baslik</th><th>Detay</th><th>Tarih</th><th></th></tr></thead>
          <tbody>{rows or '<tr><td colspan="5" class="p-4 text-muted">Hafiza karti yok.</td></tr>'}</tbody>
        </table>
      </div>
    </div>
    """
    return render(content, title="Hasta Hafizasi")


