@app.route("/islem-zincirleri")
@permission_required("view_command_center")
def workflow_drafts_page():
    _ensure_clinical_assistant_schema()
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        rows = con.execute(
            "SELECT * FROM ai_workflow_drafts ORDER BY created_at DESC LIMIT 80"
        ).fetchall()
    tr = ""
    for r in rows:
        pk = r.get("patient_key") or ""
        qpk = quote(str(pk), safe="")
        links = ""
        if pk:
            links = (
                f'<a class="btn btn-sm btn-success" href="/hasta/{qpk}/sesli-recete">Recete</a> '
                f'<a class="btn btn-sm btn-outline-primary" href="/randevu/yeni?hasta={qpk}">Randevu</a> '
                f'<a class="btn btn-sm btn-outline-success" href="/hasta/{qpk}/whatsapp">WhatsApp</a>')
        tr += f"""
        <tr><td>{sh((r.get('created_at') or '')[:16])}</td>
        <td><b>{sh(r.get('patient_name') or pk or '-')}</b></td>
        <td>{sh(r.get('command_text') or '')}<br><small>{sh(r.get('appointment_hint') or '')} {sh(r.get('whatsapp_hint') or '')}</small></td>
        <td class="text-end">{links}</td></tr>
        """
    content = f"""
    <a href="/yz-komut-merkezi" class="btn btn-secondary mb-3">Komut merkezi</a>
    <h2 class="mb-3">Zincir Islem Taslaklari</h2>
    <div class="card"><div class="card-body p-0">
      <table class="table table-hover mb-0"><thead><tr><th>Tarih</th><th>Hasta</th><th>Komut</th><th></th></tr></thead>
      <tbody>{tr or '<tr><td colspan="4" class="p-4 text-muted">Taslak yok.</td></tr>'}</tbody></table>
    </div></div>
    """
    return render(content, title="Zincir Islemler")


