@app.route("/hasta/<patient_key>/recete/goruntule/<int:rx_id>")
@permission_required("view_prescription")
def view_saved_prescription(patient_key, rx_id):
    """D250 2026-05-12: Hastaya kayitli bir receteyi tekrar yazdirma-formatinda goster.

    Query param ?print=1 ise sayfa yuklendigi anda window.print() tetiklenir.
    Doktor 'yazdigim receteleri gorebilmeli' dedi."""
    try:
        with db_conn() as con:
            _ensure_ready_prescription_schema(con)
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            row = con.execute(
                "SELECT * FROM prescriptions "
                "WHERE id=? AND patient_key=? AND COALESCE(deleted_at,'')='' "
                "LIMIT 1",
                (rx_id, patient_key)).fetchone()
            row = dict(row) if row else None
    except Exception as ex:
        flash(f"Recete okuma hatasi: {ex}", "danger")
        return redirect(url_for("prescriptions", patient_key=patient_key))
    if not row:
        flash("Bu hastada bu kayit yok.", "warning")
        return redirect(url_for("prescriptions", patient_key=patient_key))

    # Hasta kimlik bilgilerini DB'den AL (recetede saklanan eski isim
    # olabilir, ama mevcut kayit dogrunun kaynagi)
    try:
        rx_identity = _patient_rx_identity(patient_key)
        patient_name = rx_identity.get("patient_name") or row.get("patient_name") or patient_key
        protocol_no = rx_identity.get("protocol_no") or row.get("protocol_no") or patient_key
    except Exception:
        patient_name = row.get("patient_name") or patient_key
        protocol_no = row.get("protocol_no") or patient_key

    diagnosis = row.get("diagnosis") or ""
    meds = row.get("medications") or ""
    notes = row.get("notes") or ""
    template_name = row.get("template_name") or ""
    rx_date = (row.get("created_at") or "")[:10] or datetime.now().strftime("%Y-%m-%d")
    patient_notes = _patient_facing_prescription_notes(notes, template_name)
    html = _build_prescription_print_html(
        patient_name, protocol_no, diagnosis, meds, patient_notes, rx_date)

    # ?print=1 query param geldiyse otomatik baski tetikle
    auto_print = str(request.args.get("print") or "").strip().lower() in {
        "1", "true", "yes", "evet"}
    if auto_print:
        # Mevcut <body> kapanmadan once script ekle
        inject = (
            "<script>"
            "window.addEventListener('load', function(){"
            "  setTimeout(function(){ try { window.print(); } catch(e) {} }, 300);"
            "});"
            "</script>"
        )
        if "</body>" in html:
            html = html.replace("</body>", inject + "</body>", 1)
        else:
            html += inject
    resp = make_response(html)
    resp.headers["Content-Type"] = "text/html; charset=utf-8"
    return resp


@app.route("/hasta/<patient_key>/recete/sil/<int:rx_id>", methods=["POST"])
@permission_required("edit_prescription")
def delete_saved_prescription(patient_key, rx_id):
    """Hastaya yazilmis bir receteyi normal kayit listesinden kaldir."""
    try:
        with db_conn() as con:
            _ensure_ready_prescription_schema(con)
            cur = con.cursor()
            existing = cur.execute(
                "SELECT id, created_at FROM prescriptions "
                "WHERE id=? AND patient_key=? AND COALESCE(deleted_at,'')='' "
                "LIMIT 1",
                (rx_id, patient_key)).fetchone()
            if not existing:
                flash("Silinmek istenen recete bulunamadi.", "warning")
                return redirect(url_for("prescriptions", patient_key=patient_key))
            deleted_at = datetime.now().isoformat(sep=" ", timespec="seconds")
            deleted_by = _current_session_user("?")
            cur.execute(
                "UPDATE prescriptions SET deleted_at=?, deleted_by=?, "
                "deleted_reason=? WHERE id=? AND patient_key=?",
                (deleted_at, deleted_by, "manual_delete", rx_id, patient_key))
            con.commit()
            flash(
                f"Recete kayit listesinden silindi ({(existing[1] or '')[:19]}).",
                "success")
        try:
            _log_audit("prescription_delete",
                       entity_type="patient", entity_id=str(patient_key),
                       details=f"prescription_id={int(rx_id)}")
        except Exception:
            pass
    except Exception as ex:
        flash(f"Silme hatasi: {ex}", "danger")
    return redirect(url_for("prescriptions", patient_key=patient_key))


@app.route("/recete/indir/<int:tmpl_id>")
@permission_required("view_prescription")
def download_prescription(tmpl_id):
    """ReÃ§ete ÅŸablonu indir."""
    try:
        result = db_get_printable_blob("prescription_templates",
                                          tmpl_id)
        if not result:
            flash("Åablon bulunamadÄ±.", "danger")
            return redirect(url_for("home"))
        blob, file_name, file_ext = result
        mime = "application/pdf" if file_ext == "pdf" else \
                "application/octet-stream"
        return send_file(BytesIO(blob), mimetype=mime,
                          as_attachment=False,
                          download_name=file_name)
    except Exception as ex:
        flash(f"Ä°ndirme hatasÄ±: {ex}", "danger")
        return redirect(url_for("home"))


