@app.route("/gunluk-ozet")
@login_required
def daily_summary():
    """BugÃ¼nÃ¼n Ã¶zet raporu - geliÅŸler, doÄŸumlar, yeni kayÄ±tlar."""
    today = datetime.now().strftime("%Y-%m-%d")
    today_turkish = datetime.now().strftime("%d.%m.%Y")

    data = {"today_visits": [], "today_deliveries": [],
            "today_new_patients": [], "today_labs": [],
            "today_signatures": [], "today_appts": []}

    try:
        with db_conn() as con:
            # BugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n randevularÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±
            try:
                rows = con.execute(
                    "SELECT a.patient_key, a.appointment_time, "
                    "a.purpose, a.status, p.display_name "
                    "FROM appointments a "
                    "LEFT JOIN patients p ON p.folder_key = a.patient_key "
                    "WHERE a.appointment_date = ? "
                    "ORDER BY a.appointment_time",
                    (today,)).fetchall()
                data["today_appts"] = [
                    (r[0], r[1], r[2] or "", r[3] or "",
                      r[4] or r[0]) for r in rows]
            except Exception:
                data["today_appts"] = []
            # BugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n gelen hastalar
            rows = con.execute(
                "SELECT patient_folder_key, visit_key, visit_date "
                "FROM visits WHERE visit_date LIKE ? "
                "ORDER BY visit_date DESC",
                (f"{today}%",)).fetchall()
            data["today_visits"] = [(r[0], r[1], r[2]) for r in rows]

            # BugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n doÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸um yapanlar
            rows = con.execute(
                "SELECT patient_key, delivery_type, baby_count, "
                "baby_weight_g FROM deliveries "
                "WHERE delivery_date LIKE ?",
                (f"{today}%",)).fetchall()
            data["today_deliveries"] = [
                (r[0], r[1], r[2], r[3]) for r in rows]

            # BugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n kaydedilen yeni hastalar
            rows = con.execute(
                "SELECT folder_key, display_name, first_seen_at "
                "FROM patients WHERE first_seen_at LIKE ? "
                "ORDER BY first_seen_at DESC",
                (f"{today}%",)).fetchall()
            data["today_new_patients"] = [
                (r[0], r[1], r[2]) for r in rows]

            # BugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n yÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼klenen tahliller
            rows = con.execute(
                "SELECT patient_key, test_date, uploaded_at "
                "FROM lab_results WHERE uploaded_at LIKE ? "
                "ORDER BY uploaded_at DESC",
                (f"{today}%",)).fetchall()
            data["today_labs"] = [(r[0], r[1], r[2]) for r in rows]

            # BugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n alÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±nan imzalar
            rows = con.execute(
                "SELECT patient_key, marked_at, pregnancy_week_text "
                "FROM signature_log WHERE marked_at LIKE ? "
                "ORDER BY marked_at DESC",
                (f"{today}%",)).fetchall()
            data["today_signatures"] = [
                (r[0], r[1], r[2]) for r in rows]

    except Exception as ex:
        flash(f"Rapor hatasÄ±: {ex}", "warning")

    # Sections
    def _section(title, icon, items, render_fn, empty_text):
        count = len(items)
        if not count:
            body = f'<p class="text-muted">{empty_text}</p>'
        else:
            body = ""
            for item in items:
                body += render_fn(item)
        return f"""
        <div class="card mb-3">
          <div class="card-header d-flex align-items-center gap-2 flex-wrap">
            {icon} <b>{title}</b>
            <span class="badge bg-primary float-end">{count}</span>
          </div>
          <div class="card-body">{body}</div>
        </div>
        """

