@app.route("/api/medya/jpeg-foto-yazdir-hazirla", methods=["POST"])
@login_required
def api_prepare_jpeg_photo_file_print():
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        payload = request.form.to_dict() if request.form else {}
    src = str(payload.get("src") or "").strip()
    title = str(payload.get("title") or "YazKlinik Medya").strip() or "YazKlinik Medya"
    if (not src or not src.startswith("/") or src.startswith("//")
            or "\n" in src or "\r" in src):
        return jsonify({"ok": False, "message": "Gecersiz resim kaynagi."}), 400
    if not (src.startswith("/hasta/") or src.startswith("/yk-")
            or src.startswith("/dicom/preview/")):
        return jsonify({"ok": False, "message": "Bu resim kaynagi yazdirilamaz."}), 400
    printer_name = _preferred_photo_printer_name()
    native_file_hint = _yk_photo_print_file_hint(src)
    native_absolute_src = _yk_absolute_internal_src(src)
    native_print_params = {
        "src": native_absolute_src,
        "url": native_absolute_src,
        "title": title,
        "printer": printer_name,
        "paper": "PHOTO_6X8",
        "action": "print",
    }
    native_preview_params = {
        "src": native_absolute_src,
        "url": native_absolute_src,
        "title": title,
        "printer": printer_name,
        "paper": "PHOTO_6X8",
        "action": "preview",
    }
    if native_file_hint:
        native_print_params["file"] = native_file_hint
        native_preview_params["file"] = native_file_hint
    native_print_url = "yazklinik-print-photo://print?" + urlencode(native_print_params)
    native_preview_url = "yazklinik-print-photo://open?" + urlencode(native_preview_params)
    return jsonify({
        "ok": bool(native_print_url),
        "native_url": native_print_url,
        "native_preview_url": native_preview_url,
        "file_hint": native_file_hint,
        "src": src,
        "printer": printer_name,
        "paper": "PHOTO_6X8",
        "paper_label": "6x8 Foto",
        "message": (
            "JPEG dosyasi yerel baski yardimcisi icin hazir."
            if native_file_hint else
            "Yerel dosya yolu yok; yardimci resmi URL uzerinden indirip acar."
        ),
    })


@app.route("/api/medya/jpeg-foto-yazdir", methods=["POST"])
@login_required
def api_print_jpeg_photo_file():
    """B401: Yazdirma artik FIRE-AND-FORGET arka plan thread'inde calisir,
    hemen 202 doner. Eskiden sync calisiyordu - server thread bloke + JS tab
    donuyordu (Chrome 'Sayfa Yanit Vermiyor' diyalogu). Doktor 'dondu yine'
    sikayetinden sonra B310'un fire-and-forget mantigi yazdirmaya da
    uygulandi. Tum agir is (NAS dosya kopya + Photos print dialog) bgworker'da."""
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        payload = request.form.to_dict() if request.form else {}
    if not _is_local_browser_request_a100():
        return jsonify({
            "ok": False,
            "message": (
                "Foto server PC'de yazdirilmadi. Terminalde tarayici "
                "yazdirma/WebShell yerel baski yolunu kullanin."),
            "client_mode": True,
        }), 409
    src = str(payload.get("src") or "").strip()
    if (not src or not src.startswith("/") or src.startswith("//")
            or "\n" in src or "\r" in src):
        return jsonify({"ok": False, "message": "GeÃ§ersiz resim kaynaÄŸÄ±."}), 400

    def _b401_print_photo_bg(src_arg):
        try:
            image_path = _yk_materialize_photo_print_file(src_arg)
            printer_name = _preferred_photo_printer_name()
            try:
                from yazklinik_photo_print_helper import open_photo_print_dialog
                # D78: yazdirma sihirbazi acilsin; tercih penceresi ekstradan acilmasin.
                ok, message = open_photo_print_dialog(
                    image_path,
                    preferred_printer=printer_name,
                    open_preferences=False)
                if not ok:
                    raise RuntimeError(message)
            except Exception:
                try:
                    if os.name == "nt" and hasattr(os, "startfile"):
                        os.startfile(str(image_path), "print")
                except Exception:
                    pass
        except Exception:
            pass

    try:
        threading.Thread(
            target=_b401_print_photo_bg,
            args=(src,),
            name="b401-print-photo", daemon=True).start()
        return jsonify({
            "ok": True,
            "running": True,
            "message": "JPEG/foto baskÄ± arka planda hazÄ±rlanÄ±yor; yazÄ±cÄ± penceresi server PC ekranÄ±nda aÃ§Ä±lÄ±r.",
        }), 202
    except Exception as ex:
        return jsonify({
            "ok": False,
            "message": f"JPEG/foto baskÄ± baÅŸlatÄ±lamadÄ±: {ex}",
        }), 400


