@app.route("/api/medya/video-bilgisayarda-ac", methods=["POST"])
@login_required
def api_open_video_in_default_player():
    """B400: Video dosyasini server PC'sinde Windows default player'da
    (Filmler ve TV / WMP / MPC-HC etc) acar. Tarayici icindeki video
    onizleme tum hastalarda guvenilir calismiyor (yavas ag, codec, autoplay
    blocking) - bu endpoint guvenilir alternatif. Foto endpoint'inin
    aynisi: arka plan thread, hemen 202 doner, server thread bloke olmaz."""
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        payload = request.form.to_dict() if request.form else {}
    if not _is_local_browser_request_a100():
        return jsonify({
            "ok": False,
            "message": (
                "Video server PC'de acilmadi. Terminalde medya dosyasi "
                "tarayici veya WebShell yerel oynatici ile acilir."),
            "client_mode": True,
        }), 409
    src = str(payload.get("src") or "").strip()
    if (not src or not src.startswith("/") or src.startswith("//")
            or "\n" in src or "\r" in src):
        return jsonify({"ok": False,
                        "message": "Gecersiz video kaynagi."}), 400

    def _b400_open_video_bg(src_arg):
        try:
            try:
                file_path, kind = _yk_resolve_media_source_path_for_print(src_arg)
            except Exception:
                file_path, kind = (None, None)
            if not file_path:
                # Fallback: hasta-key'den dosya yolu cozmeye calis
                try:
                    pk = _yk_patient_key_from_media_src(src_arg)
                    if pk:
                        from urllib.parse import unquote
                        rel = unquote(src_arg.split(pk, 1)[-1].lstrip("/"))
                        candidate = Path(get_nas_root()) / pk / rel
                        if candidate.exists() and candidate.is_file():
                            file_path = candidate
                except Exception:
                    pass
            if not file_path:
                return
            try:
                p = Path(str(file_path))
                if not p.exists() or not p.is_file():
                    return
                if os.name == "nt" and hasattr(os, "startfile"):
                    os.startfile(str(p))
                else:
                    import subprocess
                    subprocess.Popen(["xdg-open", str(p)])
            except Exception:
                pass
        except Exception:
            pass

    try:
        threading.Thread(
            target=_b400_open_video_bg,
            args=(src,),
            name="b400-open-video", daemon=True).start()
        return jsonify({
            "ok": True,
            "running": True,
            "message": "Video arkaplanda Windows default player'da aciliyor.",
        }), 202
    except Exception as ex:
        return jsonify({
            "ok": False,
            "message": f"Video acma baslatilamadi: {ex}",
        }), 400


