@app.route("/temiz-kurulum", methods=["GET", "POST"])
@app.route("/sistem-format", methods=["GET", "POST"])
@app.route("/sistem-sifirla", methods=["GET", "POST"])
@login_required
def system_reset_page():
    """Reset page for a clean installation or full database wipe."""
    if session.get("role") != "doktor":
        flash("Sadece doktor yapabilir.", "danger")
        return redirect(url_for("settings_page"))

    db_path = str(DB_PATH)
    phrase = SYSTEM_RESET_CONFIRMATION

    if request.method == "POST":
        confirm = (request.form.get("confirmation", "") or "").strip()
        scope = request.form.get("scope", "patient")
        erase_templates = request.form.get("erase_templates") == "1"
        erase_settings = request.form.get("erase_settings") == "1"

        if confirm != phrase:
            flash(
                f"Onay cÃ¼mlesi hatalÄ±. Devam etmek iÃ§in tam olarak "
                f"'{phrase}' yazÄ±lmalÄ±.", "danger")
            return redirect(url_for("system_reset_page"))

        mode = (request.form.get("reset_mode") or "").strip()
        if mode in {"clean", "setup", "format"}:
            try:
                if mode == "format":
                    info = full_system_reset_database(
                        erase_templates=erase_templates,
                        erase_settings=True,
                        erase_audit=True,
                        backup_first=True,
                    )
                else:
                    info = full_system_reset_database(
                        erase_templates=erase_templates,
                        erase_settings=False,
                        erase_audit=False,
                        backup_first=True,
                    )
                    if mode == "setup":
                        try:
                            with db_conn() as con:
                                con.execute(
                                    "DELETE FROM settings WHERE key=?",
                                    ("first_run_complete",))
                                con.commit()
                        except Exception:
                            pass
                cache_invalidate()
                backup = info.get("backup") or {}
                deleted_total = info.get("deleted_total", 0)
                _log_audit(
                    "system_reset_clean_install",
                    entity_type="system",
                    details=(f"mode={mode}; deleted={deleted_total}; "
                             f"backup={backup.get('path')}"))
                if mode in {"setup", "format"}:
                    flash(
                        f"Temiz kurulum hazir. Silinen kayit: {deleted_total}. "
                        f"Guvenlik yedegi: {backup.get('path')}",
                        "success")
                    return redirect(url_for("first_run_wizard"))
                flash(
                    f"Hasta/veritabani kayitlari temizlendi. "
                    f"Silinen kayit: {deleted_total}. "
                    f"Guvenlik yedegi: {backup.get('path')}",
                    "success")
                return redirect(url_for("settings_page"))
            except Exception as ex:
                flash(f"Sifirlama basarisiz: {ex}", "danger")
                return redirect(url_for("system_reset_page"))

        try:
            if scope == "full":
                info = full_system_reset_database(
                    erase_templates=erase_templates,
                    erase_settings=erase_settings,
                    erase_audit=True,
                    backup_first=True,
                )
                backup = info.get("backup") or {}
                deleted_total = info.get("deleted_total", 0)
                msg = (
                    f"Tam sistem sÄ±fÄ±rlama tamamlandÄ±. "
                    f"Silinen kayÄ±t: {deleted_total}. "
                    f"Yedek: {backup.get('path', 'oluÅŸturulmadÄ±')}")
                if erase_settings:
                    session.clear()
                    flash(msg + " Ä°lk kurulum sihirbazÄ±ndan devam edin.",
                          "success")
                    return redirect(url_for("login"))
                flash(msg, "success")
                return redirect(url_for("settings_page"))

            info = full_system_reset_database(
                erase_templates=erase_templates,
                erase_settings=False,
                erase_audit=False,
                backup_first=True,
            )
            backup = info.get("backup") or {}
            deleted_total = info.get("deleted_total", 0)
            flash(
                f"Hasta/veritabanÄ± kayÄ±tlarÄ± temizlendi. "
                f"Silinen kayÄ±t: {deleted_total}. "
                f"GÃ¼venlik yedeÄŸi: {backup.get('path')}",
                "success")
            return redirect(url_for("settings_page"))
        except Exception as ex:
            flash(f"SÄ±fÄ±rlama baÅŸarÄ±sÄ±z: {ex}", "danger")
            return redirect(url_for("system_reset_page"))

