def _voice_command_alias_hit(folded, aliases):
    for alias in aliases:
        item = _fold_search_text(alias)
        if item and item in folded:
            return True
    return False


def _voice_command_route_result(label, route, source, patient_name="",
                                needs_patient=False):
    route = str(route or "/").strip() or "/"
    if needs_patient:
        route = "/" if route == "/hastalar" else route
        answer = f"{label} icin once hasta secilmesi gerekiyor; hasta listesi aciliyor."
    elif patient_name:
        answer = f"{patient_name} icin {label} aciliyor."
    else:
        answer = f"{label} aciliyor."
    return {
        "label": label,
        "route": route,
        "source": source,
        "patient_name": patient_name,
        "needs_patient": bool(needs_patient),
        "answer": answer,
    }


def _voice_command_patient_from_path(current_path):
    path = str(current_path or "").strip()
    m = re.search(r"/hasta/([^/?#]+)", path)
    if not m:
        return None
    patient_key = unquote(m.group(1)).strip()
    if not patient_key:
        return None
    return {
        "patient_key": patient_key,
        "display_name": _patient_display_label(patient_key, patient_key),
    }


def _voice_command_patient_route(template, text, label, source, current_path=""):
    match = None
    try:
        match = _voice_rx_find_patient_from_text(text)
    except Exception:
        match = None
    if not match:
        match = _voice_command_patient_from_path(current_path)
    if match and match.get("patient_key"):
        patient_key = quote(str(match.get("patient_key")), safe="")
        return _voice_command_route_result(
            label,
            template.replace("{patient}", patient_key),
            source,
            patient_name=str(match.get("display_name") or match.get("patient_key") or ""))
    resolved = _menu_search_resolve_url(template)
    route = resolved.get("url") or "/"
    if resolved.get("needs_patient"):
        route = "/"
    return _voice_command_route_result(
        label,
        route,
        source,
        patient_name=str(resolved.get("patient_name") or ""),
        needs_patient=bool(resolved.get("needs_patient")))


def _voice_command_meaningful_tokens(text):
    folded = _fold_search_text(text)
    return [
        t for t in folded.split()
        if len(t) >= 2 and t not in VOICE_COMMAND_STOPWORDS
    ]


def _voice_command_catalog_route(text, current_path=""):
    folded = _fold_search_text(text)
    tokens = _voice_command_meaningful_tokens(text)
    if not folded or not tokens:
        return None
    best = None
    for title, url, group, keywords in FUNCTION_CATALOG:
        hay = _fold_search_text(f"{title} {group} {keywords}")
        hits = sum(1 for t in tokens if t in hay)
        title_fold = _fold_search_text(title)
        score = hits
        if title_fold and title_fold in folded:
            score += 5
        if hits >= max(1, min(3, len(tokens))) or score >= 4:
            if not best or score > best[0]:
                best = (score, title, url)
    if not best:
        return None
    resolved = _menu_search_resolve_url(best[2])
    route = resolved.get("url") or "/"
    if resolved.get("needs_patient"):
        path_match = _voice_command_patient_from_path(current_path)
        if path_match and path_match.get("patient_key"):
            route = str(best[2]).replace(
                "{patient}", quote(str(path_match.get("patient_key")), safe=""))
            resolved = {
                "patient_name": str(path_match.get("display_name") or ""),
                "needs_patient": False,
            }
        else:
            route = "/"
    return _voice_command_route_result(
        best[1],
        route,
        "catalog",
        patient_name=str(resolved.get("patient_name") or ""),
        needs_patient=bool(resolved.get("needs_patient")))


def _voice_command_resolve_route(text, current_path=""):
    folded = _fold_search_text(text)
    if not folded:
        return None
    if any(k in folded for k in ("ayar", "ayarlari", "parametre", "model")):
        for aliases, route, label in VOICE_COMMAND_GLOBAL_ROUTES:
            if _voice_command_alias_hit(folded, aliases):
                return _voice_command_route_result(label, route, "global_alias")
    for aliases, template, label in VOICE_COMMAND_PATIENT_ROUTES:
        if _voice_command_alias_hit(folded, aliases):
            return _voice_command_patient_route(
                template, text, label, "patient_alias", current_path=current_path)
    for aliases, route, label in VOICE_COMMAND_GLOBAL_ROUTES:
        if _voice_command_alias_hit(folded, aliases):
            return _voice_command_route_result(label, route, "global_alias")
    return _voice_command_catalog_route(text, current_path=current_path)


def _voice_command_extract_route_from_text(text):
    raw = str(text or "")
    if not raw:
        return ""
    m = re.search(
        r"(?P<route>/(?:hasta|yk-print-media|randevu|yz|dicom|enabiz|"
        r"dashboard|gun-plani|hizli-not|sistem|whatsapp|ayarlar|menu-ara|"
        r"kullanim|medikal|takip|recete|onam|protokol|veritabani|performans|"
        r"temiz-kurulum)[^\s<>'\"]*)",
        raw)
    if not m:
        return ""
    return m.group("route").rstrip(".,;)")


def _voice_command_enrich_result(result):
    if not isinstance(result, dict):
        return result
    action = dict(result.get("action") or {})
    if not action.get("route"):
        route = _voice_command_extract_route_from_text(
            result.get("result") or result.get("answer") or "")
        if route:
            action["route"] = route
            action.setdefault("key", "open_route")
            action.setdefault("label", "Sayfa ac")
            result["action"] = action
            result["answer"] = result.get("answer") or result.get("result") or "Sayfa aciliyor."
    return result


def _voice_parse_appointment_intent(message):
    """D300: Turkce 'randevu ver/al, X gun saat Y' tarz cumlelerden tarih/saat cikar."""
    if not message:
        return None
    msg = str(message).lower().strip()
    msg = msg.replace("ı", "i").replace("ş", "s").replace("ç", "c")
    msg = msg.replace("ğ", "g").replace("ü", "u").replace("ö", "o")
    trigger_words = ("randevu", "randevular", "appointment", "muayene rezerv")
    if not any(t in msg for t in trigger_words):
        return None
    from datetime import datetime, timedelta
    now = datetime.now()
    target = None
    # Yarin / bugun / obur gun
    if "yarin" in msg:
        target = now + timedelta(days=1)
    elif "bugun" in msg:
        target = now
    elif "obur gun" in msg or "obur" in msg:
        target = now + timedelta(days=2)
    # Hafta gunleri
    weekdays = {
        "pazartesi": 0, "sali": 1, "carsamba": 2, "persembe": 3,
        "cuma": 4, "cumartesi": 5, "pazar": 6,
    }
    for wname, widx in weekdays.items():
        if wname in msg:
            days_ahead = (widx - now.weekday()) % 7
            if days_ahead == 0:
                days_ahead = 7
            target = now + timedelta(days=days_ahead)
            break
    # Saat parse: "saat 14", "saat 14:30", "14:30"
    import re as _re
    saat = None
    m = _re.search(r"saat\s+(\d{1,2})[:\.\s](\d{2})", msg)
    if m:
        saat = f"{int(m.group(1)):02d}:{m.group(2)}"
    else:
        m = _re.search(r"saat\s+(\d{1,2})\b", msg)
        if m:
            saat = f"{int(m.group(1)):02d}:00"
        else:
            m = _re.search(r"(\d{1,2}):(\d{2})", msg)
            if m:
                saat = f"{int(m.group(1)):02d}:{m.group(2)}"
    if not target and not saat:
        return None
    return {
        "tarih": target.strftime("%Y-%m-%d") if target else "",
        "saat": saat or "",
        "raw": message,
    }


@app.route("/api/sesli-komut/uygula", methods=["POST"])
@login_required
def api_voice_command_apply():
    data = request.get_json(silent=True) or request.form
    message = (
        data.get("message")
        or data.get("text")
        or data.get("command")
        or ""
    ).strip()
    if not message:
        return jsonify({"ok": False, "status": "empty",
                        "error": "message gerekli"}), 400

    current_path = str(data.get("current_path") or "").strip()
    if not current_path:
        try:
            current_path = urlsplit(request.referrer or "").path
        except Exception:
            current_path = ""

    # D300: Sesli randevu intent
    appt = _voice_parse_appointment_intent(message)
    if appt and (appt.get("tarih") or appt.get("saat")):
        from urllib.parse import urlencode as _urlenc
        params = {"alex": 1}
        if appt.get("tarih"):
            params["tarih"] = appt["tarih"]
        if appt.get("saat"):
            params["saat"] = appt["saat"]
        route = "/randevu/yeni?" + _urlenc(params)
        return jsonify({
            "ok": True,
            "status": "routed",
            "source": "voice_appointment",
            "answer": (
                f"Randevu formu aciliyor: "
                f"{appt.get('tarih') or 'bugun'} {appt.get('saat') or ''}".strip()),
            "result": "Randevu formu aciliyor.",
            "action": {
                "key": "open_route",
                "label": "Randevu ver",
                "route": route,
            },
        })

    rx_result = _voice_rx_apply_from_command(message, current_path=current_path)
    if rx_result:
        return jsonify(rx_result)

    route_result = _voice_command_resolve_route(message, current_path=current_path)
    if route_result:
        action = {
            "key": "open_route",
            "label": route_result.get("label") or "Sayfa ac",
            "route": route_result.get("route") or "/",
            "args": route_result,
        }
        return jsonify({
            "ok": True,
            "status": "routed",
            "source": route_result.get("source"),
            "answer": route_result.get("answer") or "Sayfa aciliyor.",
            "result": route_result.get("answer") or "Sayfa aciliyor.",
            "action": action,
        })

    if can("view_command_center") and can("manage_command_center"):
        confirmed = str(data.get("confirmed") or "").lower() in {
            "1", "true", "yes", "evet", "on"}
        result = _command_center_run_message(message, force_confirmed=confirmed)
        enriched = _voice_command_enrich_result(result)
        action = (enriched or {}).get("action") or {}
        action_key = str(action.get("key") or "").strip()
        if (
                not (enriched or {}).get("ok")
                and (enriched or {}).get("status") in {"blocked", "unmatched", "error"}
                and action_key in {"unknown", ""}):
            return jsonify({
                "ok": False,
                "status": "unmatched",
                "answer": "Bunu hazir kuralda bulamadim; akilli dialog yorumlayacak.",
                "result": "Bunu hazir kuralda bulamadim; akilli dialog yorumlayacak.",
            })
        if (enriched or {}).get("status") == "waiting_confirm":
            enriched["needs_confirm"] = True
            enriched["answer"] = (
                enriched.get("result")
                or action.get("summary")
                or "Bu islem icin onay gerekiyor. Evet dersen uygularim."
            )
        elif (enriched or {}).get("result") and not enriched.get("answer"):
            enriched["answer"] = enriched.get("result")
        return jsonify(enriched)

    return jsonify({
        "ok": False,
        "status": "unmatched",
        "answer": "Komutu bir sayfa veya fonksiyona baglayamadim.",
        "result": "Komutu bir sayfa veya fonksiyona baglayamadim.",
    })


@app.route("/menu-ara")
@login_required
def menu_search_page():
    q = request.args.get("q", "").strip()
    folded = _fold_search_text(q)
    tokens = [t for t in folded.split() if t]
    rows = []
    for title, url, group, keywords in FUNCTION_CATALOG:
        hay = _fold_search_text(f"{title} {group} {keywords}")
        if not tokens or all(t in hay for t in tokens):
            rows.append((title, url, group, keywords))
    cards = ""
    for title, url, group, keywords in rows:
        resolved = _menu_search_resolve_url(url)
        target_url = resolved["url"]
        hint = ""
        if resolved.get("needs_patient"):
            hint = (
                '<span class="menu-card-hint">Once hasta secilmesi gerekiyor</span>'
            )
        elif resolved.get("patient_name"):
            prefix = "Son aktif hasta" if not resolved.get("fallback") else "Son gelis"
            hint = (
                f'<span class="menu-card-hint">{sh(prefix)}: '
                f'{sh(resolved["patient_name"])}</span>'
            )
        cards += f"""
        <article data-menu-target="{safe_attr(target_url)}"
                 onclick="window.location.assign(this.dataset.menuTarget)"
                 onkeydown="if(event.key==='Enter'||event.key===' '){{event.preventDefault();window.location.assign(this.dataset.menuTarget)}}"
                 role="button" tabindex="0"
                 class="card text-decoration-none mb-2 yk-menu-search-card">
          <div class="card-body d-flex justify-content-between align-items-center gap-3">
            <div>
              <span class="badge bg-primary mb-2">{sh(group)}</span>
              <h5 class="mb-1">{sh(title)}</h5>
              <small class="text-muted">{sh(keywords)}</small>
              {hint}
            </div>
            <button class="btn btn-primary menu-open-btn" type="button"
                    onclick="event.stopPropagation();window.location.assign('{safe_attr(target_url)}')">
              Ac <i class="bi bi-arrow-right-circle"></i>
            </button>
          </div>
        </article>
        """
    if not cards:
        cards = '<div class="alert alert-warning">Bu fonksiyon icin sonuc bulunamadi.</div>'
    content = f"""
    <style>
      .yk-menu-search-page {{
        position: relative;
        z-index: 2;
      }}
      .yk-menu-search-card {{
        cursor: pointer;
        position: relative;
        z-index: 5;
        pointer-events: auto !important;
        border: 1px solid rgba(47, 127, 214, .18);
        border-radius: 18px;
        background:
          linear-gradient(135deg, rgba(242, 247, 255, .96), rgba(236, 255, 249, .88));
        box-shadow: 0 16px 42px rgba(26, 80, 140, .10);
        color: #122033;
        transition: transform .12s ease, box-shadow .12s ease, border-color .12s ease;
      }}
      .yk-menu-search-card:hover {{
        transform: translateY(-1px);
        border-color: rgba(0, 135, 210, .45);
        box-shadow: 0 20px 48px rgba(0, 116, 190, .16);
      }}
      .yk-menu-search-card h5 {{
        color: #17315a;
        font-weight: 780;
      }}
      .yk-menu-search-card .badge {{
        background: linear-gradient(135deg, #0d6efd, #02a6a6) !important;
      }}
      .yk-menu-search-card,
      .yk-menu-search-card * {{
        pointer-events: auto !important;
      }}
      .yk-menu-search-card .card-body {{
        pointer-events: none !important;
      }}
      .yk-menu-search-card .menu-open-btn {{
        pointer-events: auto !important;
        min-width: 96px;
        border-radius: 16px;
        background: linear-gradient(135deg, #0877d9, #00a9a6);
        border: 0;
        box-shadow: 0 10px 24px rgba(0, 120, 210, .18);
      }}
      .menu-card-hint {{
        display: block;
        margin-top: .55rem;
        color: #326075;
        font-size: .9rem;
        font-weight: 650;
      }}
      .yk-menu-search-form .form-control,
      .yk-menu-search-form .btn {{
        position: relative;
        z-index: 4;
      }}
    </style>
    <div class="yk-menu-search-page">
      <div class="patient-header">
        <span class="eyebrow">Fonksiyon arama</span>
        <h1>Menu ve islev bul</h1>
        <p class="lede">
          Bu arama hasta aramasindan ayridir; sadece program fonksiyonlarini,
          ekranlari ve araclari bulur.
        </p>
      </div>
      <form method="GET" class="mb-4 yk-menu-search-form">
        <div class="input-group input-group-lg">
          <input name="q" class="form-control" value="{safe_attr(q)}"
                 placeholder="Orn: diyet, onam, DICOM, protokol, tema">
          <button class="btn btn-primary" type="submit">
            <i class="bi bi-search"></i> Fonksiyon ara
          </button>
        </div>
      </form>
      {cards}
    </div>
    <script>
      document.addEventListener('click', function(event) {{
        var card = event.target.closest('.yk-menu-search-card');
        if (!card) return;
        var target = card.getAttribute('data-menu-target');
        if (target) {{
          event.preventDefault();
          window.location.assign(target);
        }}
      }}, true);
    </script>
    """
    return render(content, title="Fonksiyon Arama")


