@app.route("/kullanici-sil/<username>")
@login_required
def delete_user(username):
    """KullanÄ±cÄ± sil."""
    if session.get("role") != "doktor":
        flash("Sadece doktor yapabilir.", "danger")
        return redirect(url_for("home"))

    if username == session.get("user"):
        flash("Kendi hesabÄ±nÄ±zÄ± silemezsiniz!", "danger")
        return redirect(url_for("settings_page"))

    if username not in USERS:
        flash(f"KullanÄ±cÄ± yok: {username}", "warning")
    else:
        del USERS[username]
        _save_users_to_disk()
        flash(f"âœ… '{username}' silindi.", "success")

    return redirect(url_for("settings_page"))


