@app.route("/sistem-guncelleme", methods=["GET", "POST"])
@login_required
def system_update():
    """ğŸ”„ ZIP dosyasÄ±ndan sistem gÃ¼ncelleme."""
    if session.get("role") != "doktor":
        flash("Sadece doktor.", "danger")
        return redirect(url_for("home"))

    try:
        from yazklinik_updater import (
            apply_update, validate_update_zip,
            list_backups, rollback_to_backup,
            get_install_dir, get_backup_dir,
            get_version_info, load_install_config)
    except ImportError:
        flash(
            "yazklinik_updater.py modÃ¼lÃ¼ yok.", "danger")
        return redirect(url_for("settings_page"))

    install_dir = get_install_dir()
    backup_dir = get_backup_dir()
    cfg = load_install_config()
    version_info = get_version_info(install_dir)

    if request.method == "POST":
        action = request.form.get("action", "")

        if action == "upload":
            # ZIP dosyasÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± yÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼klendi
            f = request.files.get("update_zip")
            if not f or not f.filename:
                flash("ZIP dosyasÄ± seÃ§medin.", "warning")
                return redirect(url_for("system_update"))

            if not f.filename.lower().endswith(".zip"):
                flash("Sadece .zip dosyasÄ± yÃ¼klenebilir.",
                      "danger")
                return redirect(url_for("system_update"))

            # GeÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ici dosyaya kaydet
            import tempfile
            temp_zip = tempfile.NamedTemporaryFile(
                delete=False, suffix=".zip")
            f.save(temp_zip.name)
            temp_zip.close()

            try:
                # ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œnce doÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸rula
                valid, msg, manifest = validate_update_zip(
                    temp_zip.name)
                if not valid:
                    flash(f"âŒ DoÄŸrulama: {msg}",
                          "danger")
                    os.unlink(temp_zip.name)
                    return redirect(url_for("system_update"))

                # Manifest detaylarÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± session'a koy
                session["pending_update_zip"] = temp_zip.name
                session["pending_update_manifest"] = (
                    manifest)
                return redirect(url_for("system_update"))
            except Exception as ex:
                flash(f"Hata: {ex}", "danger")
                try:
                    os.unlink(temp_zip.name)
                except Exception:
                    pass
                return redirect(url_for("system_update"))

        elif action == "apply":
            # OnaylanmÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼ncellemeyi uygula
            zip_path = session.get("pending_update_zip")
            if not zip_path or not os.path.exists(
                    zip_path):
                flash(
                    "Bekleyen gÃ¼ncelleme yok. Ã–nce ZIP yÃ¼kle.",
                    "warning")
                return redirect(url_for("system_update"))

            messages = []
            def progress(msg):
                messages.append(msg)

            ok, result_msg = apply_update(
                zip_path,
                install_dir=install_dir,
                backup_dir=backup_dir,
                on_progress=progress)

            # Temp temizle
            try:
                os.unlink(zip_path)
            except Exception:
                pass
            session.pop("pending_update_zip", None)
            session.pop("pending_update_manifest", None)

            if ok:
                full = result_msg + "<br><br><b>Log:</b><br>"
                full += "<br>".join(
                    f"â€¢ {m}" for m in messages)
                flash(full, "success")
            else:
                flash(
                    f"âŒ GÃ¼ncelleme: {result_msg}",
                    "danger")

            return redirect(url_for("system_update"))

        elif action == "cancel":
            zip_path = session.get("pending_update_zip")
            if zip_path and os.path.exists(zip_path):
                try:
                    os.unlink(zip_path)
                except Exception:
                    pass
            session.pop("pending_update_zip", None)
            session.pop("pending_update_manifest", None)
            flash("Ä°ptal edildi.", "info")
            return redirect(url_for("system_update"))

        elif action == "rollback":
            backup_name = request.form.get(
                "backup_name", "")
            if backup_name:
                ok, msg = rollback_to_backup(
                    backup_name,
                    install_dir=install_dir,
                    backup_dir=backup_dir)
                flash(
                    msg.replace("\n", "<br>"),
                    "success" if ok else "danger")
            return redirect(url_for("system_update"))

