@app.route("/arama")
@login_required
def search():
    """Turkce/ingilizce karakter duyarsiz hasta arama."""
    q = request.args.get("q", "").strip()

    results = []
    if q and len(q) >= 2:
        try:
            q_fold = _fold_search_text(q)
            tokens = [t for t in q_fold.split() if t]
            with db_conn() as con:
                con.row_factory = lambda cur, row: {
                    d[0]: row[i] for i, d in enumerate(cur.description)}
                rows = con.execute(
                    "SELECT p.folder_key as patient_key, p.display_name, "
                    "pp.protocol_no FROM patients p "
                    "LEFT JOIN patient_protocols pp ON pp.patient_key=p.folder_key "
                    "ORDER BY COALESCE(p.display_name, p.folder_key) LIMIT 1000"
                ).fetchall()
                for row in rows:
                    hay = _fold_search_text(
                        f"{row.get('protocol_no') or ''} "
                        f"{row.get('display_name') or ''} "
                        f"{row.get('patient_key') or ''}")
                    if not tokens or all(t in hay for t in tokens):
                        results.append(row)
                    if len(results) >= 80:
                        break
        except Exception as ex:
            flash(f"Arama hatasÄ±: {ex}", "danger")

    cards = []
    for r in results:
        key = r["patient_key"]
        q_key = quote(str(key), safe="")
        name = r["display_name"] or key
        proto = r.get("protocol_no") or ""
        cards.append(f"""
 <div class="patient-card">
 <div class="d-flex justify-content-between align-items-start">
 <div>
 <h5 class="mb-1">ğŸ‘¤ {name}</h5>
              <small class="text-muted">Protokol: {sh(proto or '-')} Â· {sh(key)}</small>
            </div>
            <a href="/hasta/{q_key}" class="btn btn-sm btn-primary">
 ğŸ“‚ AÃ§
 </a>
 </div>
 </div>
 """)

    body = ""
    if not q:
        body = ('<p class="text-muted text-center py-5">'
                'Arama terimi girin (en az 2 karakter).</p>')
    elif len(q) < 2:
        body = ('<p class="text-muted text-center py-5">'
                'En az 2 karakter girin.</p>')
    elif not cards:
        body = (f'<div class="alert alert-warning">'
                f'<b>"{q}"</b> ile eÅŸleÅŸen hasta yok.</div>')
    else:
        body = (f'<p class="text-muted">'
                f'<b>"{q}"</b> iÃ§in {len(cards)} sonuÃ§:</p>'
                + "".join(cards))

    content = f"""
 <a href="/" class="btn btn-secondary mb-3"><- Hasta listesi</a>
 <h2>ğŸ” Arama</h2>
 <form method="GET" action="/arama" class="mb-4">
 <div class="input-group input-group-lg">
 <input type="search" name="q" class="form-control"
 value="{safe_attr(q)}" autofocus
 placeholder="Hasta adÄ± yazÄ±n..."
 minlength="2">
 <button class="btn btn-primary" type="submit">ğŸ” Ara</button>
 </div>
 </form>
 {body}
    """
    return render(content, title="Arama")


