@app.route("/randevu/<int:appt_id>/duzenle", methods=["GET", "POST"])
@permission_required("edit_appointment")
def edit_appointment(appt_id):
    """Randevu dÃ¼zenle."""
    if request.method == "POST":
        f = request.form
        appt_date = f.get("appointment_date", "").strip()
        appt_time = f.get("appointment_time", "").strip()
        purpose = f.get("purpose", "").strip()
        note = f.get("note", "").strip()
        status = f.get("status", "planned").strip()

        try:
            with db_conn() as con:
                con.execute(
                    "UPDATE appointments SET "
                    "appointment_date=?, appointment_time=?, "
                    "purpose=?, note=?, status=? WHERE id=?",
                    (appt_date, appt_time, purpose, note,
                      status, appt_id))
                con.commit()
            flash("âœ… Randevu gÃ¼ncellendi.", "success")
        except Exception as ex:
            flash(f"GÃ¼ncelleme hatasÄ±: {ex}", "danger")
