@app.route("/randevu/<int:appt_id>/sil")
@permission_required("delete_appointment")
def delete_appointment(appt_id):
    """Randevu sil."""
    try:
        with db_conn() as con:
            con.execute("DELETE FROM appointments WHERE id=?",
                         (appt_id,))
            con.commit()
        _log_audit("appointment_delete",
                    entity_type="appointment",
                    entity_id=str(appt_id))
        flash("ğŸ—‘ Randevu silindi.", "info")
    except Exception as ex:
        flash(f"Silme hatasÄ±: {ex}", "danger")
    return redirect(url_for("appointments_list"))


