@app.route("/randevu/<int:appt_id>/durum/<string:new_status>")
@permission_required("edit_appointment")
def quick_status_change(appt_id, new_status):
    """HÄ±zlÄ± durum deÄŸiÅŸimi - tek tikla."""
    allowed = {"confirmed", "completed", "cancelled",
               "no_show", "planned"}
    if new_status not in allowed:
        flash("GeÃ§ersiz durum.", "danger")
        return redirect(url_for("appointments_list"))

    try:
        with db_conn() as con:
            con.execute(
                "UPDATE appointments SET status=? WHERE id=?",
                (new_status, appt_id))
            con.commit()
        _log_audit("appointment_status",
                    entity_type="appointment",
                    entity_id=str(appt_id),
                    details=f"-> {new_status}")
        status_label = {
            "planned": "PlanlÄ±",
            "confirmed": "âœ… OnaylandÄ±",
            "completed": "âœ“ TamamlandÄ±",
            "cancelled": "ğŸš« Ä°ptal edildi",
            "no_show": "âŒ Gelmedi",
        }.get(new_status, new_status)
        flash(f"Randevu durumu: {status_label}", "info")
    except Exception as ex:
        flash(f"GÃ¼ncelleme hatasÄ±: {ex}", "danger")

    # Referer'e geri dÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶n
    next_url = _safe_next_url(request.args.get("next"),
                              fallback=url_for("appointments_list"))
    return redirect(next_url)


