@app.route("/export/hastalar.csv")
@login_required
def export_patients_csv():
    """TÃ¼m hastalarÄ± CSV olarak indir - Excel uyumlu."""
    if session.get("role") not in ("doktor", "asistan"):
        flash("Yetkin yok.", "danger")
        return redirect(url_for("home"))

    import csv
    import io

    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            rows = con.execute("""
                SELECT p.folder_key as key, p.display_name as name,
                       p.first_seen_at,
                       pt.ptype, pt.age, pt.phone
                FROM patients p
                LEFT JOIN patient_type pt ON pt.patient_key = p.folder_key
                ORDER BY p.display_name
            """).fetchall()
    except Exception as ex:
        flash(f"DB hatasÄ±: {ex}", "danger")
        return redirect(url_for("home"))

    # CSV olarak yaz
    # UTF-8 BOM + TÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼rkÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§e karakter desteÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸i iÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§in Excel uyumlu
    output = io.StringIO()
    output.write("\ufeff")  # BOM ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â Excel TÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼rkÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§e karakter gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶rsÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n
    writer = csv.writer(output, delimiter=';')
    writer.writerow(["Hasta Anahtar", "Ad Soyad", "Kayit Tarihi",
                      "Tip", "YaÅŸ", "Telefon"])
    for r in rows:
        writer.writerow([
            r.get("key", ""),
            r.get("name", "") or "",
            (r.get("first_seen_at") or "")[:10],
            PATIENT_TYPE_LABELS.get(r.get("ptype") or "", ""),
            r.get("age") or "",
            r.get("phone") or "",
        ])

    csv_data = output.getvalue().encode("utf-8")
    output.close()

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"hastalar_{timestamp}.csv"
    return send_file(
        BytesIO(csv_data),
        mimetype="text/csv; charset=utf-8",
        as_attachment=True,
        download_name=filename)


@app.route("/export/randevular.csv")
@permission_required("view_appointments")
def export_appointments_csv():
    """TÃ¼m randevularÄ± CSV olarak indir."""
    import csv
    import io

    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            rows = con.execute("""
                SELECT a.*, p.display_name
                FROM appointments a
                LEFT JOIN patients p ON p.folder_key = a.patient_key
                ORDER BY a.appointment_date DESC,
                         a.appointment_time DESC
            """).fetchall()
    except Exception as ex:
        flash(f"DB hatasÄ±: {ex}", "danger")
        return redirect(url_for("appointments_list"))

    output = io.StringIO()
    output.write("\ufeff")
    writer = csv.writer(output, delimiter=';')
    writer.writerow(["Tarih", "Saat", "Hasta Anahtar",
                      "Hasta AdÄ±", "AmaÃ§", "Durum", "Not",
                      "OluÅŸturan", "OluÅŸturma"])
    status_map = {
        "planned": "PlanlÄ±",
        "confirmed": "OnaylandÄ±",
        "completed": "TamamlandÄ±",
        "cancelled": "Ä°ptal",
        "no_show": "Gelmedi",
    }
    for r in rows:
        writer.writerow([
            r.get("appointment_date", ""),
            r.get("appointment_time", ""),
            r.get("patient_key", ""),
            r.get("display_name", "") or "",
            r.get("purpose") or "",
            status_map.get(r.get("status", ""), r.get("status", "")),
            (r.get("note") or "").replace("\n", " ")[:200],
            r.get("created_by") or "",
            (r.get("created_at") or "")[:16],
        ])

    csv_data = output.getvalue().encode("utf-8")
    output.close()

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"randevular_{timestamp}.csv"
    return send_file(
        BytesIO(csv_data),
        mimetype="text/csv; charset=utf-8",
        as_attachment=True,
        download_name=filename)


