def _patient_exam_summary_first(*values):
    for value in values:
        if value is None:
            continue
        text = str(value).strip()
        if text:
            return value
    return ""


def _patient_exam_summary_digits(value):
    return re.sub(r"\D+", "", str(value or ""))


def _patient_exam_summary_date(value):
    if value is None or value == "":
        return ""
    if isinstance(value, (int, float)) and value > 100000:
        try:
            return datetime.fromtimestamp(float(value)).strftime("%d.%m.%Y")
        except Exception:
            return ""
    text = str(value).strip()
    if not text:
        return ""
    head = text[:10]
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y"):
        try:
            return datetime.strptime(head, fmt).strftime("%d.%m.%Y")
        except Exception:
            pass
    return text


def _patient_exam_summary_number(value, decimals=1):
    if value is None or value == "":
        return ""
    try:
        number = float(str(value).replace(",", "."))
    except Exception:
        return str(value).strip()
    if abs(number - round(number)) < 0.0001:
        return str(int(round(number)))
    return f"{number:.{decimals}f}".rstrip("0").rstrip(".")


def _patient_exam_summary_custom_phone(patient_key, demo=None):
    raw = ""
    try:
        raw = (demo or {}).get("phone") or ""
    except Exception:
        raw = ""
    if not raw:
        try:
            raw = load_phone_db(patient_key) or ""
        except Exception:
            raw = ""
    digits = _patient_exam_summary_digits(raw)
    if not digits:
        return ""
    try:
        default_digits = _patient_exam_summary_digits(get_default_whatsapp_number())
    except Exception:
        default_digits = ""
    if default_digits and digits[-10:] == default_digits[-10:]:
        return ""
    try:
        if not has_saved_phone_db(patient_key):
            return ""
    except Exception:
        pass
    try:
        return normalize_phone(raw)
    except Exception:
        return digits


def _patient_exam_summary_clean_text(value):
    text = str(value or "").strip()
    if not text:
        return ""
    cp1254_legacy_map = str.maketrans({
        "\u00f0": "\u011f",
        "\u00d0": "\u011e",
        "\u00fe": "\u015f",
        "\u00de": "\u015e",
        "\u00fd": "\u0131",
        "\u00dd": "\u0130",
    })
    if any(ch in text for ch in ("\u00f0", "\u00d0", "\u00fe", "\u00de", "\u00fd", "\u00dd")):
        text = text.translate(cp1254_legacy_map)
    if any(marker in text for marker in ("Ã", "Ä", "Å", "Â", "\ufffd")):
        try:
            fixed = fix_mojibake_text(text).strip()
            if fixed:
                return fixed
        except Exception:
            pass
    return text


def _patient_exam_lab_status(test_name, payload):
    payload = payload or {}
    value = payload.get("value") if isinstance(payload, dict) else payload
    number = _yk_lab_parse_number(value)
    if number is None:
        return "neutral", "kontrol", ""
    ref = str((payload or {}).get("ref") or "").strip() if isinstance(payload, dict) else ""
    ref_nums = []
    for m in re.finditer(r"-?\d+(?:[.,]\d+)?", ref):
        try:
            ref_nums.append(float(m.group(0).replace(",", ".")))
        except Exception:
            pass
    if len(ref_nums) >= 2:
        low, high = min(ref_nums[0], ref_nums[1]), max(ref_nums[0], ref_nums[1])
        if number < low:
            return "warn", "dusuk", f"Ref {ref}"
        if number > high:
            return "warn", "yuksek", f"Ref {ref}"
        return "ok", "normal", f"Ref {ref}"
    if len(ref_nums) == 1 and ref:
        limit = ref_nums[0]
        if re.search(r"[<≤]\s*-?\d", ref) and number > limit:
            return "warn", "yuksek", f"Ref {ref}"
        if re.search(r"[>≥]\s*-?\d", ref) and number < limit:
            return "warn", "dusuk", f"Ref {ref}"
    try:
        status, label, note = _yk_ai_report_metric_status(test_name, number)
        if status in ("danger", "warn"):
            return status, label.lower(), note
        if status == "ok":
            return "ok", "normal", note
    except Exception:
        pass
    return "neutral", "kontrol", ""


def _patient_exam_latest_lab_summary(patient_key, limit=2):
    try:
        labs = _list_lab_results_clean(patient_key)
    except Exception:
        try:
            labs = list_lab_results(patient_key)
        except Exception:
            labs = []
    out = []
    for lab in (labs or [])[:max(1, int(limit or 2))]:
        values = lab.get("values") or {}
        date_text = _patient_exam_summary_date(
            lab.get("test_date") or lab.get("uploaded_at")) or "Tarih yok"
        abnormal = []
        normal_count = 0
        for test, payload in sorted(values.items()):
            if not isinstance(payload, dict):
                payload = {"value": payload}
            state, label, note = _patient_exam_lab_status(test, payload)
            value_text = str(payload.get("value") or "").strip()
            unit_text = str(payload.get("unit") or "").strip()
            bit = f"{test}: {value_text}{(' ' + unit_text) if unit_text else ''}"
            if state in ("danger", "warn"):
                abnormal.append(
                    bit + f" ({label}" + (f", {note}" if note else "") + ")")
            elif state == "ok":
                normal_count += 1
        if abnormal:
            out.append({
                "date": date_text,
                "status": "abnormal",
                "text": f"{date_text} - Normal disi: "
                        + "; ".join(abnormal[:8]),
                "items": abnormal[:8],
                "count": len(values),
            })
        elif values:
            out.append({
                "date": date_text,
                "status": "normal",
                "text": f"{date_text} - {len(values)} tetkik: normal.",
                "items": [],
                "count": len(values),
            })
        else:
            out.append({
                "date": date_text,
                "status": "empty",
                "text": f"{date_text} - Tetkik PDF kayitli, okunabilir deger yok.",
                "items": [],
                "count": 0,
            })
    return out


def _patient_exam_latest_lab_html(patient_key, labs=None):
    summaries = _patient_exam_latest_lab_summary(patient_key, limit=1)
    if not summaries:
        return ""
    s = summaries[0]
    tone = {
        "abnormal": ("warning", "Normal disi deger var"),
        "normal": ("success", "Son tetkikler normal"),
        "empty": ("secondary", "Deger okunamadi"),
    }.get(s.get("status"), ("secondary", "Tetkik ozeti"))
    q_patient = quote(str(patient_key), safe="")
    item_html = ""
    if s.get("items"):
        item_html = "<ul class='mb-2'>" + "".join(
            f"<li>{sh(item)}</li>" for item in s.get("items")[:5]) + "</ul>"
    return f"""
    <div class="alert alert-{tone[0]} border d-flex justify-content-between align-items-start gap-3 flex-wrap">
      <div>
        <div class="fw-bold"><i class="bi bi-clipboard2-pulse"></i> Son tetkik ozeti - {sh(s.get('date'))}</div>
        <div>{sh(tone[1])}</div>
        {item_html if item_html else f"<div class='small'>{sh(s.get('text'))}</div>"}
      </div>
      <a href="/hasta/{q_patient}/tahliller" class="btn btn-outline-dark btn-sm">
        Doktor isterse tum tetkikleri ac
      </a>
    </div>
    """


def _patient_exam_summary_name(patient_key):
    display_name = patient_key
    try:
        with db_conn() as con:
            row = con.execute(
                "SELECT display_name FROM patients WHERE folder_key=?",
                (patient_key,)).fetchone()
            if row:
                display_name = row[0] or patient_key
    except Exception:
        display_name = patient_key
    try:
        display_name = _patient_display_label(patient_key, display_name)
    except Exception:
        try:
            display_name = _clean_patient_display_name(display_name)
        except Exception:
            pass
    return _patient_exam_summary_clean_text(display_name or patient_key)


def _patient_exam_summary_fetal_summary(fetal):
    fetal = dict(fetal or {})
    bits = []
    if fetal.get("ga_weeks") not in (None, ""):
        bits.append(
            f"GA {_patient_exam_summary_number(fetal.get('ga_weeks'), 0)}+"
            f"{_patient_exam_summary_number(fetal.get('ga_days') or 0, 0)}")
    for key, label in (
            ("bpd", "BPD"), ("hc", "HC"), ("ac", "AC"), ("fl", "FL"),
            ("crl", "CRL"), ("nt", "NT"), ("efw", "EFW"),
            ("afi", "AFI"), ("fhr", "FHR")):
        if fetal.get(key) not in (None, ""):
            bits.append(
                f"{label} {_patient_exam_summary_number(fetal.get(key), 1)}")
    return ", ".join(bits[:10])


def _patient_exam_summary_pdf_entries(patient_key, pdf_payload):
    entries = []
    seen = set()

    def add_entry(date_value="", source="", fetal=None):
        fetal = dict(fetal or {})
        if fetal.get("efw") in (None, "") and fetal.get("efw_grams") not in (None, ""):
            fetal["efw"] = fetal.get("efw_grams")
        summary = _patient_exam_summary_fetal_summary(fetal)
        if not summary:
            return
        date_text = _patient_exam_summary_date(date_value)
        source_text = os.path.basename(str(source or "USG PDF"))
        key = (date_text, source_text.lower(), summary)
        if key in seen:
            return
        seen.add(key)
        prefix = date_text or "Tarih yok"
        entries.append(f"{prefix} - {summary}")

    raw_pdfs = list((pdf_payload or {}).get("pdfs") or [])
    try:
        raw_pdfs.sort(
            key=lambda item: str(item.get("mtime") or item.get("visit_date")
                                 or item.get("date") or ""),
            reverse=True)
    except Exception:
        pass
    for entry in raw_pdfs:
        if not isinstance(entry, dict):
            continue
        fetal = dict(entry.get("fetal") or {})
        add_entry(
            _patient_exam_summary_first(
                entry.get("visit_date"), entry.get("date"),
                fetal.get("usg_date"), fetal.get("exam_date")),
            _patient_exam_summary_first(entry.get("name"), entry.get("path")),
            fetal)
        if len(entries) >= 5:
            break

    top_fetal = dict((pdf_payload or {}).get("fetal") or {})
    if top_fetal and not entries:
        add_entry(
            _patient_exam_summary_first(top_fetal.get("usg_date"),
                                        top_fetal.get("exam_date")),
            "PDF ozeti",
            top_fetal)

    try:
        with db_conn() as con:
            con.row_factory = sqlite3.Row
            rows = con.execute(
                "SELECT * FROM usg_measurements WHERE patient_key=? "
                "AND COALESCE(source_type,'')='pdf' "
                "ORDER BY COALESCE(usg_date,'') DESC, rowid DESC LIMIT 8",
                (patient_key,)).fetchall()
        for row in rows:
            fetal = dict(row)
            add_entry(
                fetal.get("usg_date"),
                _patient_exam_summary_first(
                    fetal.get("source_accession_number"),
                    fetal.get("source_study_id"),
                    fetal.get("source_instance_id")),
                fetal)
            if len(entries) >= 5:
                break
    except Exception:
        pass
    return entries[:5]


def _build_patient_exam_summary_payload(patient_key):
    try:
        demo = load_patient_demographics(patient_key)
    except Exception:
        demo = {}
    try:
        data_json = _patient_file_load_data_json(patient_key)
    except Exception:
        data_json = {}
    if not isinstance(data_json, dict):
        data_json = {}
    pdf_payload = data_json.get("pdf_patient_extract") or {}
    if not isinstance(pdf_payload, dict):
        pdf_payload = {}
    pdf_demo = pdf_payload.get("demographics") or {}
    if not isinstance(pdf_demo, dict):
        pdf_demo = {}

    patient_name = _patient_exam_summary_name(patient_key)
    lines = [
        "Muayene Özeti",
        f"Hasta: {patient_name}",
    ]
    phone = _patient_exam_summary_custom_phone(patient_key, demo)
    if phone:
        lines.append(f"Telefon: {phone}")

    info_bits = []
    age = _patient_exam_summary_first(demo.get("age"), pdf_demo.get("age"))
    if age not in (None, ""):
        info_bits.append(f"Yaş: {_patient_exam_summary_number(age, 0)}")
    lmp = _patient_exam_summary_first(
        demo.get("lmp_override"), pdf_demo.get("lmp_override"))
    if lmp:
        info_bits.append(f"SAT/LMP: {_patient_exam_summary_date(lmp)}")
    edd = _patient_exam_summary_first(
        demo.get("edd"), pdf_demo.get("edd_from_pdf"), pdf_demo.get("edd"))
    if edd:
        info_bits.append(f"Tahmini doğum: {_patient_exam_summary_date(edd)}")
    height = _patient_exam_summary_first(
        demo.get("height"), pdf_demo.get("height"))
    weight = _patient_exam_summary_first(
        demo.get("weight"), pdf_demo.get("weight"))
    bmi = _patient_exam_summary_first(demo.get("bmi"), pdf_demo.get("bmi"))
    size_bits = []
    if height not in (None, ""):
        size_bits.append(f"Boy {_patient_exam_summary_number(height, 1)} cm")
    if weight not in (None, ""):
        size_bits.append(f"Kilo {_patient_exam_summary_number(weight, 1)} kg")
    if bmi not in (None, ""):
        size_bits.append(f"BMI {_patient_exam_summary_number(bmi, 1)}")
    if size_bits:
        info_bits.append(", ".join(size_bits))
    if info_bits:
        lines.append("Hasta bilgileri: " + " | ".join(info_bits))

    pdf_entries = _patient_exam_summary_pdf_entries(patient_key, pdf_payload)
    lines.append("USG/PDF bilgileri:")
    if pdf_entries:
        lines.extend(f"- {entry}" for entry in pdf_entries)
    else:
        lines.append("- Kayıtlı USG/PDF ölçümü bulunamadı.")

    lab_summaries = _patient_exam_latest_lab_summary(patient_key, limit=2)
    lines.append("Tetkik özeti:")
    if lab_summaries:
        lines.extend(f"- {item.get('text')}" for item in lab_summaries)
    else:
        lines.append("- Kayıtlı tetkik/tahlil sonucu bulunamadı.")

    text = _patient_exam_summary_clean_text("\n".join(lines).strip())
    return {
        "ok": True,
        "patient_key": patient_key,
        "patient_name": patient_name,
        "text": text,
        "generated_at": datetime.now().isoformat(
            sep=" ", timespec="seconds"),
    }


@app.route("/api/hasta/<patient_key>/muayene-ozeti")
@login_required
def api_patient_exam_summary(patient_key):
    payload = _build_patient_exam_summary_payload(patient_key)
    try:
        _log_audit(
            "patient_exam_summary_copy",
            "patient",
            patient_key,
            patient_key=patient_key,
            details=json.dumps(
                {"chars": len(payload.get("text") or "")},
                ensure_ascii=False))
    except Exception:
        pass
    return jsonify(payload)


