@app.route("/gun-plani")
@permission_required("view_appointments")
def day_schedule():
    """GÃ¼nlÃ¼k slot planlamasÄ± - saat saat boÅŸ/dolu gÃ¶rÃ¼nÃ¼mÃ¼."""
    from datetime import timedelta

    date_str = request.args.get("gun",
                                  datetime.now().strftime("%Y-%m-%d"))
    try:
        day_dt = datetime.strptime(date_str, "%Y-%m-%d")
    except Exception:
        day_dt = datetime.now()
        date_str = day_dt.strftime("%Y-%m-%d")

    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            appts = con.execute(
                "SELECT a.*, p.display_name FROM appointments a "
                "LEFT JOIN patients p ON p.folder_key = a.patient_key "
                "WHERE a.appointment_date = ? "
                "AND a.status != 'cancelled' "
                "ORDER BY a.appointment_time",
                (date_str,)).fetchall()
    except Exception as ex:
        flash(f"Plan hatasÄ±: {ex}", "danger")
        appts = []

    # Saat slotlarÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±nÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± dakikaya ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§evir
    def _to_mins(t):
        try:
            parts = t.split(":")
            return int(parts[0]) * 60 + int(parts[1])
        except Exception:
            return -1

    # RandevularÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± saate gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶re mapping
    appt_by_slot = {}  # mins -> appt
    for a in appts:
        m = _to_mins(a.get("appointment_time", ""))
        if m >= 0:
            appt_by_slot[m // 15 * 15] = a  # 15 dk'lÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±k slot

    # 08:00 - 20:00 arasÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± 15'er dakika slot
    slots = []
    for hr in range(8, 20):
        for mn in (0, 15, 30, 45):
            slot_min = hr * 60 + mn
            time_label = f"{hr:02d}:{mn:02d}"
            a = appt_by_slot.get(slot_min)
            slots.append((time_label, slot_min, a))

    # TÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼rkÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§e gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n
    day_names_tr = ["Pazartesi", "SalÄ±", "Ã‡arÅŸamba", "PerÅŸembe",
                     "Cuma", "Cumartesi", "Pazar"]
    day_name = day_names_tr[day_dt.weekday()]
    day_label = (f"{day_dt.day:02d}.{day_dt.month:02d}.{day_dt.year} "
                 f"- {day_name}")

    # BugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n mÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼?
    today = datetime.now().strftime("%Y-%m-%d")
    is_today = date_str == today

    # Slot grid
    grid = ""
    for time_label, slot_min, a in slots:
        if a:
            pt_name = a.get("display_name") or a.get("patient_key", "")
            pt_key = a.get("patient_key", "")
            purpose = a.get("purpose") or ""
            status = a.get("status", "planned")
            status_bg = {
                "planned": "#E3F2FD",
                "confirmed": "#C8E6C9",
                "completed": "#EEEEEE",
                "no_show": "#FFE0B2",
            }.get(status, "#FFFFFF")

            grid += f"""
            <div class="slot filled"
                 style="background:{status_bg};">
              <div class="time">{time_label}</div>
              <div class="content">
                <a href="/hasta/{pt_key}">
 <b>ğŸ‘¤ {pt_name}</b>
 </a>
 <br><small>ğŸ©º {purpose}</small>
                <div class="slot-actions">
                  <a href="/randevu/{a['id']}/duzenle"
 class="btn btn-sm btn-outline-primary">
 âœï¸
 </a>
 </div>
 </div>
 </div>
 """
        else:
            # BoÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ slot ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â tÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±klayarak yeni randevu
            grid += f"""
            <div class="slot empty">
              <div class="time">{time_label}</div>
              <div class="content">
                <a href="/randevu/yeni?tarih={date_str}&saat={time_label}"
 class="btn btn-sm btn-outline-success">
 â• Randevu Ekle
 </a>
 </div>
 </div>
 """

    # ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œnceki/sonraki gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n
    prev_day = (day_dt - timedelta(days=1)).strftime("%Y-%m-%d")
    next_day = (day_dt + timedelta(days=1)).strftime("%Y-%m-%d")

    content = f"""
    <style>
      .slot {{ display: flex; border-bottom: 1px solid #eee;
               padding: 8px; min-height: 48px;
               align-items: center; }}
      .slot.empty {{ background: #FAFAFA; }}
      .slot.filled {{ font-weight: 500; }}
      .slot .time {{ min-width: 70px; font-weight: bold;
                      color: #0078D4; font-size: 15px; }}
      .slot .content {{ flex: 1; }}
      .slot-actions {{ float: right; }}
 </style>

 <a href="/randevular" class="btn btn-secondary mb-3">
 <- Randevular
 </a>

 <div class="d-flex justify-content-between align-items-center mb-4">
 <h2>ğŸ“‹ GÃ¼nlÃ¼k Plan</h2>
 <div>
 <a href="/takvim" class="btn btn-outline-info">
 ğŸ“† HaftalÄ±k
 </a>
 </div>
 </div>

 <div class="mb-3 d-flex align-items-center">
 <a href="/gun-plani?gun={prev_day}"
 class="btn btn-outline-primary me-2"><- Ã–nceki GÃ¼n</a>
 <div class="flex-grow-1 text-center">
 <h5 class="mb-0">
 {"ğŸ“ BUGÃœN - " if is_today else ""}{day_label}
        </h5>
        <small class="text-muted">
          {len(appts)} randevu Â· 08:00-20:00 Â· 15dk slotlar
 </small>
 </div>
 <a href="/gun-plani?gun={next_day}"
 class="btn btn-outline-primary ms-2">Sonraki GÃ¼n -></a>
 </div>

 {"<div class='text-center mb-3'><a href='/gun-plani' class='btn btn-warning'>ğŸ“ BugÃ¼ne DÃ¶n</a></div>" if not is_today else ""}

 <div class="card">
 <div class="card-header">
 <b>Saat BazlÄ± Plan</b>
 <small class="text-muted float-end">
 BoÅŸ slota tikla -> randevu ekle
 </small>
 </div>
 <div class="card-body p-0">
 {grid}
      </div>
    </div>
    """
    return render(content, title=f"Plan {date_str}")


