@app.route("/gorev/<int:task_id>/durum/<string:new_status>")
@permission_required("edit_task")
def task_status_change(task_id, new_status):
    """GÃ¶rev durumu deÄŸiÅŸtir - open/done."""
    if new_status not in ("open", "done"):
        flash("GeÃ§ersiz durum.", "danger")
        return redirect(url_for("tasks_list"))
    try:
        now = datetime.now().isoformat(sep=" ", timespec="seconds")
        with db_conn() as con:
            if new_status == "done":
                con.execute(
                    "UPDATE web_tasks SET status=?, completed_at=? "
                    "WHERE id=?",
                    (new_status, now, task_id))
            else:
                con.execute(
                    "UPDATE web_tasks SET status=?, completed_at=NULL "
                    "WHERE id=?", (new_status, task_id))
            con.commit()
        _log_audit("task_status", entity_type="task",
                    entity_id=str(task_id),
                    details=f"-> {new_status}")
        if new_status == "done":
            flash("âœ… GÃ¶rev tamamlandÄ±.", "success")
        else:
            flash("â†© GÃ¶rev tekrar aÃ§Ä±ldÄ±.", "info")
    except Exception as ex:
        flash(f"Hata: {ex}", "danger")
    return redirect(_safe_next_url(request.args.get("next"),
                                   fallback=url_for("tasks_list")))


