@app.route("/otomatik-yedekler")
@login_required
def auto_backups_view():
    """Otomatik yedeklenen dosyalarÄ± listele + indir + manuel tetikle."""
    if session.get("role") != "doktor":
        flash("âŒ Sadece doktor.", "danger")
        return redirect(url_for("home"))

    backup_dir = _get_backup_dir()
    files = []
    try:
        for f in sorted(backup_dir.glob("auto_yedek_*.sqlite3"),
                         key=lambda p: p.stat().st_mtime,
                         reverse=True):
            stat = f.stat()
            files.append({
                "name": f.name,
                "size_mb": stat.st_size / 1024 / 1024,
                "mtime": datetime.fromtimestamp(stat.st_mtime),
            })
    except Exception as ex:
        flash(f"Liste hatasÄ±: {ex}", "danger")

    rows = ""
    for f in files:
        ts = f["mtime"].strftime("%d.%m.%Y %H:%M")
        days_ago = (datetime.now() - f["mtime"]).days
        days_label = f"{days_ago} gÃ¼n Ã¶nce" if days_ago > 0 else "bugÃ¼n"
        rows += f"""
        <tr>
          <td><b>{f['name']}</b></td>
          <td>{ts}<br>
            <small class="text-muted">{days_label}</small></td>
          <td>{f['size_mb']:.1f} MB</td>
          <td>
            <a href="/otomatik-yedek/indir/{f['name']}"
 class="btn btn-sm btn-primary">
 ğŸ“¥ Ä°ndir
 </a>
 </td>
 </tr>
 """

    if not rows:
        rows = ('<tr><td colspan="4" class="text-center '
                'text-muted py-5">HenÃ¼z otomatik yedek yok. '
                'Ä°lk yedek server baÅŸlatÄ±ldÄ±ktan 5 dakika '
                'sonra alÄ±nÄ±r.</td></tr>')

    content = f"""
 <a href="/ayarlar" class="btn btn-secondary mb-3"><- Ayarlar</a>
 <h2 class="mb-3">ğŸ¤– Otomatik Yedekler</h2>
 <p class="text-muted">
 Server her 24 saatte bir otomatik yedek alÄ±yor.
 30 gÃ¼nden eski yedekler otomatik siliniyor.
 <br>ğŸ“ KlasÃ¶r: <code>{_get_backup_dir()}</code>
 </p>

 <div class="d-flex gap-2 mb-4">
 <a href="/otomatik-yedek/simdi-al"
 class="btn btn-success">
 âš¡ Åimdi Manuel Yedek Al
 </a>
 <a href="/yedek-indir" class="btn btn-warning">
 ğŸ’¾ AnlÄ±k DB Ä°ndir
 </a>
 </div>

 <div class="card">
 <div class="card-header">
 <b>{len(files)} otomatik yedek</b>
      </div>
      <div class="card-body p-0">
        <table class="table table-hover mb-0">
          <thead class="table-light">
            <tr>
              <th>Dosya</th>
              <th>Tarih</th>
              <th>Boyut</th>
              <th></th>
            </tr>
          </thead>
          <tbody>{rows}</tbody>
 </table>
 </div>
 </div>

 <div class="alert alert-info mt-4">
 <b>ğŸ’¡ Felaket Senaryosunda:</b><br>
 1. En yeni yedek dosyasÄ±nÄ± indir<br>
 2. Server kapat<br>
 3. Mevcut DB'nin yedeÄŸini al (Ã¶nemli!)<br>
 4. Ä°ndirdiÄŸin yedeÄŸi DB konumuna kopyala<br>
 5. Server'Ä± tekrar baÅŸlat
 </div>
 """
    return render(content, title="Otomatik Yedekler")


@app.route("/otomatik-yedek/indir/<filename>")
@login_required
def download_auto_backup(filename):
    """Otomatik yedeklerden birini indir."""
    if session.get("role") != "doktor":
        flash("âŒ Sadece doktor.", "danger")
        return redirect(url_for("home"))

    # GÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼venlik ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â sadece auto_yedek_ ile baÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸layan
    if not filename.startswith("auto_yedek_") or \
            not filename.endswith(".sqlite3"):
        flash("GeÃ§ersiz dosya.", "danger")
        return redirect(url_for("auto_backups_view"))

    backup_dir = _get_backup_dir()
    file_path = backup_dir / filename
    if not file_path.exists():
        flash("Dosya bulunamadÄ±.", "danger")
        return redirect(url_for("auto_backups_view"))

    return send_file(
        str(file_path),
        as_attachment=True,
        download_name=filename,
        mimetype="application/x-sqlite3")


