@app.route("/yedek-yukle", methods=["POST"])
@login_required
def restore_backup_upload():
    if session.get("role") != "doktor":
        flash("Sadece doktor.", "danger")
        return redirect(url_for("home"))
    if request.form.get("confirm", "").strip() != "GERI YUKLE":
        flash("Onay metni hatali. Geri yukleme yapilmadi.", "warning")
        return redirect(url_for("backup_center_view"))
    upload = request.files.get("backup_file")
    if not upload or not upload.filename:
        flash("Yedek dosyasi secilmedi.", "danger")
        return redirect(url_for("backup_center_view"))
    name = Path(upload.filename).name
    if not name.lower().endswith((".sqlite3", ".db")):
        flash("Sadece .sqlite3 veya .db dosyasi yuklenebilir.", "danger")
        return redirect(url_for("backup_center_view"))
    tmp_dir = Path(tempfile.mkdtemp(prefix="yazklinik_restore_"))
    tmp_path = tmp_dir / name
    try:
        upload.save(str(tmp_path))
        result = restore_database(tmp_path)
        _log_audit("database_restore", entity_type="system",
                   details=f"from={name}")
        flash(
            "Geri yukleme tamamlandi. Serveri yeniden baslatmaniz onerilir. "
            f"Hasta sayisi: {result.get('patient_count', '-')}",
            "success")
    except Exception as ex:
        flash(f"Geri yukleme hatasi: {ex}", "danger")
    return redirect(url_for("backup_center_view"))


