@app.route("/araclar/gebelik-hesapla", methods=["GET", "POST"])
@login_required
def pregnancy_calculator():
    """Gebelik haftasÄ± hesaplayÄ±cÄ± - LMP, USG veya EDD'den."""
    from datetime import timedelta

    result_html = ""

    if request.method == "POST":
        method = request.form.get("method", "")
        try:
            today = datetime.now()
            if method == "lmp":
                lmp_str = request.form.get("lmp", "")
                lmp = datetime.strptime(lmp_str, "%Y-%m-%d")
                edd = lmp + timedelta(days=280)
                ga_days = (today - lmp).days
                ga_w = ga_days // 7
                ga_d = ga_days % 7
                trimester = (1 if ga_w < 14
                              else 2 if ga_w < 28 else 3)
                result_html = f"""
 <div class="alert alert-success">
 <h4 class="mb-3">ğŸ“Š SonuÃ§</h4>
 <table class="table table-sm">
 <tr><td><b>LMP:</b></td>
 <td>{lmp.strftime('%d.%m.%Y')}</td></tr>
 <tr><td><b>BugÃ¼n:</b></td>
 <td>{today.strftime('%d.%m.%Y')}</td></tr>
 <tr><td><b>Gebelik HaftasÄ±:</b></td>
 <td><h3 class="mb-0">{ga_w}+{ga_d}</h3></td></tr>
                    <tr><td><b>Trimester:</b></td>
                        <td>{trimester}. trimester</td></tr>
                    <tr><td><b>EDD (Naegele):</b></td>
                        <td><h4 class="mb-0">
                          {edd.strftime('%d.%m.%Y')}
                        </h4>
                        ({(edd - today).days} gÃ¼n kaldÄ±)</td></tr>
 </table>
 </div>
 """
            elif method == "usg":
                usg_date_str = request.form.get("usg_date", "")
                usg_w = int(request.form.get("usg_weeks", 0))
                usg_d = int(request.form.get("usg_days", 0))
                usg_date = datetime.strptime(
                    usg_date_str, "%Y-%m-%d")
                # USG gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼nÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼nde kaÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼ndÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼ ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬ÂÃ‚Â¢ bugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n iÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§in ekle
                ga_at_usg = usg_w * 7 + usg_d
                days_since_usg = (today - usg_date).days
                ga_now = ga_at_usg + days_since_usg
                # LMP: bugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼nden ga_now kadar geri
                lmp = today - timedelta(days=ga_now)
                edd = lmp + timedelta(days=280)
                result_html = f"""
 <div class="alert alert-success">
 <h4 class="mb-3">ğŸ“Š SonuÃ§ (USG'ye GÃ¶re)</h4>
 <table class="table table-sm">
 <tr><td><b>USG Tarihi:</b></td>
 <td>{usg_date.strftime('%d.%m.%Y')}</td></tr>
                    <tr><td><b>USG'de GA:</b></td>
                        <td>{usg_w}+{usg_d}</td></tr>
 <tr><td><b>GeÃ§en SÃ¼re:</b></td>
 <td>{days_since_usg} gÃ¼n</td></tr>
 <tr><td><b>Åu An GA:</b></td>
 <td><h3 class="mb-0">
 {ga_now // 7}+{ga_now % 7}
 </h3></td></tr>
 <tr><td><b>HesaplÄ± LMP:</b></td>
 <td>{lmp.strftime('%d.%m.%Y')}</td></tr>
                    <tr><td><b>EDD:</b></td>
                        <td><h4 class="mb-0">
                          {edd.strftime('%d.%m.%Y')}
                        </h4></td></tr>
                  </table>
                </div>
                """
            elif method == "edd":
                edd_str = request.form.get("edd", "")
                edd = datetime.strptime(edd_str, "%Y-%m-%d")
                lmp = edd - timedelta(days=280)
                ga_days = (today - lmp).days
                ga_w = ga_days // 7
                ga_d = ga_days % 7
                days_to_edd = (edd - today).days
                result_html = f"""
 <div class="alert alert-success">
 <h4 class="mb-3">ğŸ“Š SonuÃ§ (EDD'ye GÃ¶re)</h4>
 <table class="table table-sm">
 <tr><td><b>EDD:</b></td>
 <td>{edd.strftime('%d.%m.%Y')}</td></tr>
 <tr><td><b>HesaplÄ± LMP:</b></td>
 <td>{lmp.strftime('%d.%m.%Y')}</td></tr>
 <tr><td><b>Åu An GA:</b></td>
 <td><h3 class="mb-0">{ga_w}+{ga_d}</h3></td></tr>
 <tr><td><b>Kalan SÃ¼re:</b></td>
 <td>{days_to_edd} gÃ¼n
 ({days_to_edd // 7} hf {days_to_edd % 7} gn)</td></tr>
                  </table>
                </div>
                """
        except Exception as ex:
            result_html = (f'<div class="alert alert-danger">'
                           f'Hesaplama hatasÄ±: {ex}</div>')

    today_str = datetime.now().strftime("%Y-%m-%d")
