@app.route("/perinatoloji")
@login_required
def perinatology_dashboard():
    """ğŸ©º Riskli Gebelik Takip Merkezi - kritik gebelik takipleri tek ekranda.

 Doktorun her sabah aÃ§acaÄŸÄ± sayfa: kim risk altÄ±nda, kim
 bugÃ¼n gelecek, hangi tetkik gecikmiÅŸ, kim doÄŸacak.
 """
    from datetime import timedelta
    today = datetime.now()
    today_str = today.strftime("%Y-%m-%d")

    # KATEGORÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â° 1: Acil/Kritik gebeler
    critical_pts = []
    # KATEGORÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â° 2: EDD yaklaÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸an (ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¤7 gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n)
    imminent_delivery = []
    # KATEGORÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â° 3: EDD geÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§miÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ (postterm)
    postterm = []
    # KATEGORÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â° 4: BugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n randevu
    today_appts = []
    # KATEGORÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â° 5: NST/USG ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶nerilen
    needs_test = []
    # KATEGORÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â° 6: Tahlil gecikmiÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ (28 gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n)
    overdue_lab = []
    # KATEGORÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â° 7: YÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼ksek riskli bayraklÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±
    high_risk = []

    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}

            # BugÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼nkÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼ randevular
            try:
                rows = con.execute(
                    "SELECT a.appointment_time, a.patient_key, "
                    "a.purpose, a.status, p.display_name "
                    "FROM appointments a "
                    "LEFT JOIN patients p "
                    "  ON p.folder_key = a.patient_key "
                    "WHERE a.appointment_date=? "
                    "AND a.status NOT IN ('cancelled','completed') "
                    "ORDER BY a.appointment_time",
                    (today_str,)).fetchall()
                today_appts = rows
            except Exception:
                pass

            # YÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼ksek risk bayraklÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± (danger seviyesi)
            danger_flags = [
                k for k, v in PATIENT_FLAG_LEVELS.items()
                if v == "danger"]
            if danger_flags:
                placeholders = ",".join("?" * len(danger_flags))
                rows = con.execute(
                    f"SELECT DISTINCT pf.patient_key, "
                    f"p.display_name, "
                    f"GROUP_CONCAT(pf.flag_name) as flags "
                    f"FROM patient_flags pf "
                    f"LEFT JOIN patients p "
                    f"  ON p.folder_key = pf.patient_key "
                    f"WHERE pf.value='1' "
                    f"AND pf.flag_name IN ({placeholders}) "
                    f"GROUP BY pf.patient_key "
                    f"ORDER BY p.display_name LIMIT 30",
                    danger_flags).fetchall()
                high_risk = rows

            # TÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼m LMP'li gebeler ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â EDD analizi
            rows = con.execute(
                "SELECT patient_key, data_json FROM "
                "patient_demographics "
                "WHERE data_json LIKE '%lmp%'").fetchall()
            for r in rows:
                try:
                    import json as _json
                    data = _json.loads(r.get("data_json") or "{}")
                    lmp_str = data.get("lmp_override")
                    if not lmp_str:
                        continue
                    parts = lmp_str.split(".")
                    if len(parts) != 3:
                        continue
                    lmp_dt = datetime(
                        int(parts[2]), int(parts[1]),
                        int(parts[0]))
                    edd_dt = lmp_dt + timedelta(days=280)
                    days_to_edd = (edd_dt - today).days
                    ga_days = (today - lmp_dt).days
                    ga_w = ga_days // 7
                    ga_d = ga_days % 7

                    # Hasta adÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±
                    nm = con.execute(
                        "SELECT display_name FROM patients "
                        "WHERE folder_key=?",
                        (r["patient_key"],)).fetchone()
                    name = (nm["display_name"] if nm
                            else r["patient_key"])

                    pt_data = {
                        "key": r["patient_key"],
                        "name": name,
                        "ga": f"{ga_w}+{ga_d}",
                        "ga_w": ga_w,
                        "edd": edd_dt.strftime("%d.%m.%Y"),
                        "days_to_edd": days_to_edd,
                    }

                    # Postterm (EDD geÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ti)
                    if days_to_edd < 0 and days_to_edd >= -14:
                        postterm.append(pt_data)
                    # EDD ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¤7 gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¼n
                    elif 0 <= days_to_edd <= 7:
                        imminent_delivery.append(pt_data)

                    # NST gerekli (32+ hafta)
                    if 32 <= ga_w <= 41:
                        # Son geliÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸?
                        v_row = con.execute(
                            "SELECT MAX(visit_date) "
                            "FROM visits WHERE "
                            "patient_folder_key=?",
                            (r["patient_key"],)).fetchone()
                        last_v = v_row[0] if v_row else None
                        days_since_visit = 999
                        if last_v:
                            try:
                                last_dt = datetime.strptime(
                                    last_v[:10], "%Y-%m-%d")
                                days_since_visit = (
                                    today - last_dt).days
                            except Exception:
                                pass
                        if days_since_visit > 7:
                            needs_test.append({
                                **pt_data,
                                "reason": (f"NST iÃ§in "
                                           f"{days_since_visit} "
                                           f"gÃ¼ndÃ¼r gelmemiÅŸ")})

                    # OGTT (24-28 hf)
                    if 24 <= ga_w <= 28:
                        # OGTT yapÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±lmÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ mÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± kontrol
                        l_row = con.execute(
                            "SELECT COUNT(*) FROM lab_results "
                            "WHERE patient_key=? AND "
                            "(LOWER(extracted_json) LIKE '%ogtt%' "
                            "OR LOWER(extracted_json) LIKE "
                            "'%tolerans%' OR "
                            "LOWER(notes) LIKE '%ogtt%')",
                            (r["patient_key"],)).fetchone()
                        if l_row and l_row[0] == 0:
                            critical_pts.append({
                                **pt_data,
                                "issue": "ğŸ§ª OGTT zamanÄ± (24-28 hf)",
                            })

                    # Tahlil gecikmesi
                    l_row = con.execute(
                        "SELECT MAX(uploaded_at) FROM lab_results "
                        "WHERE patient_key=?",
                        (r["patient_key"],)).fetchone()
                    last_lab = l_row[0] if l_row else None
                    if last_lab:
                        try:
                            last_lab_dt = datetime.strptime(
                                last_lab[:10], "%Y-%m-%d")
                            days_no_lab = (
                                today - last_lab_dt).days
                            if days_no_lab > 28 and ga_w < 38:
                                overdue_lab.append({
                                    **pt_data,
                                    "days": days_no_lab,
                                })
                        except Exception:
                            pass
                except Exception as _ex:
                    pass

    except Exception as ex:
        flash(f"Riskli gebelik veri hatasÄ±: {ex}", "warning")

    # === HTML render ===

    def _make_card(title, color, items, render_fn, empty_text,
                    icon=""):
        count = len(items)
        if not count:
            body = (f'<p class="text-muted text-center py-3">'
                    f'{empty_text}</p>')
        else:
            body = "".join(render_fn(i) for i in items[:10])
            if count > 10:
                body += (f'<p class="text-muted text-center mt-2">'
                         f'<small>+{count - 10} daha...</small></p>')
        return f"""
        <div class="card mb-3">
          <div class="card-header bg-{color} text-white">
            {icon} <b>{title}</b>
            <span class="badge bg-light text-dark float-end">
              {count}
            </span>
          </div>
          <div class="card-body p-2">{body}</div>
        </div>
        """

    # Her kategori iÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§in render fonksiyonu
