@app.route("/api/hasta/<patient_key>/diyet-listele", methods=["GET"])
@login_required
def api_diet_list_saved_files(patient_key):
    """Kayitli diyetleri listele. D88: yeni kayitlar DB BLOB'dur; eski
    NAS/Diyet dosyalari geriye uyumluluk icin altta listelenir."""
    from pathlib import Path as _Path
    import datetime as _dt
    try:
        items = []
        try:
            _diet_docs_ensure_schema()
            with db_conn() as con:
                con.row_factory = sqlite3.Row
                rows = con.execute(
                    "SELECT id, file_name, diet_type, created_at, "
                    "LENGTH(pdf_blob) AS pdf_size "
                    "FROM patient_diet_documents "
                    "WHERE patient_key=? AND COALESCE(deleted_at,'')='' "
                    "ORDER BY created_at DESC, id DESC LIMIT 100",
                    (patient_key,)).fetchall()
            q_patient = quote(str(patient_key), safe="")
            for row in rows:
                d = _yk_row_dict(row)
                created = str(d.get("created_at") or "")
                try:
                    mtime = int(_dt.datetime.fromisoformat(
                        created.replace("T", " ")).timestamp())
                except Exception:
                    mtime = 0
                fname = d.get("file_name") or f"YZ_Diyet_{d.get('id')}.pdf"
                items.append({
                    "id": int(d.get("id") or 0),
                    "record_id": int(d.get("id") or 0),
                    "name": fname,
                    "title": fname,
                    "size": int(d.get("pdf_size") or 0),
                    "mtime": mtime,
                    "mtime_text": created[:16],
                    "ext": "pdf",
                    "source": "db",
                    "db": True,
                    "file_url": f"/hasta/{q_patient}/diyet-kayit/{int(d.get('id') or 0)}",
                    "pdf_url": f"/hasta/{q_patient}/diyet-kayit/{int(d.get('id') or 0)}/pdf",
                })
        except Exception:
            pass
        diet_dir = None
        try:
            proot = _Path(_patient_root_for_nas(patient_key))
            diet_dir = proot / "Diyet"
        except Exception:
            diet_dir = None
        if diet_dir and diet_dir.exists():
            for p in diet_dir.iterdir():
                if not p.is_file():
                    continue
                if p.suffix.lower() not in (".html", ".htm", ".pdf"):
                    continue
                try:
                    st = p.stat()
                    items.append({
                        "name": p.name,
                        "size": st.st_size,
                        "mtime": int(st.st_mtime),
                        "mtime_text": _dt.datetime.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d %H:%M"),
                        "ext": p.suffix.lower().lstrip("."),
                        "source": "legacy-file",
                        "db": False,
                        "file_url": (
                            f"/api/hasta/{quote(str(patient_key), safe='')}"
                            f"/diyet-dosya/{quote(p.name, safe='')}"
                        ),
                    })
                except Exception:
                    continue
        items.sort(key=lambda x: x["mtime"], reverse=True)
        return jsonify({"ok": True, "files": items})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/hasta/<patient_key>/diyet-sil", methods=["POST"])
@login_required
def api_diet_delete_saved_file(patient_key):
    """C11: Hasta klasorundeki diyet dosyasini sil. Doktor 'kilosu degisirse
    yeni liste gerek, eski silinebilsin' istedi."""
    from pathlib import Path as _Path
    data = request.get_json(silent=True) or {}
    doc_id_raw = data.get("id") or data.get("record_id") or data.get("doc_id")
    try:
        doc_id = int(doc_id_raw or 0)
    except Exception:
        doc_id = 0
    if doc_id > 0:
        try:
            _diet_docs_ensure_schema()
            now = _yk_now_text()
            with db_conn() as con:
                cur = con.execute(
                    "UPDATE patient_diet_documents "
                    "SET deleted_at=?, deleted_by=? "
                    "WHERE id=? AND patient_key=? AND COALESCE(deleted_at,'')=''",
                    (now, str(session.get("user") or ""), doc_id, patient_key))
                con.commit()
            if cur.rowcount < 1:
                return jsonify({"ok": False, "error": "Kayit bulunamadi."}), 404
            _log_audit(
                "ai_diet_delete_db",
                entity_type="patient",
                patient_key=patient_key,
                details=f"id:{doc_id}",
            )
            return jsonify({"ok": True, "message": f"Diyet kaydi silindi: {doc_id}"})
        except Exception as ex:
            return jsonify({"ok": False, "error": str(ex)}), 500
    file_name = str(data.get("file_name") or "").strip()
    if not file_name or "/" in file_name or "\\" in file_name or ".." in file_name:
        return jsonify({"ok": False, "error": "Gecersiz dosya adi."}), 400
    if not file_name.lower().endswith((".html", ".md", ".pdf")):
        return jsonify({"ok": False, "error": "Sadece diyet HTML/MD/PDF silinebilir."}), 400
    try:
        proot = _Path(_patient_root_for_nas(patient_key))
        target = proot / "Diyet" / file_name
        if not target.exists():
            target = proot / file_name
        if not target.exists():
            return jsonify({"ok": False, "error": "Dosya bulunamadi."}), 404
        try:
            with db_conn() as con:
                con.execute(
                    "DELETE FROM files WHERE patient_folder_key=? AND file_name=?",
                    (patient_key, file_name))
                con.commit()
        except Exception:
            pass
        target.unlink()
        # Md karsiligi da varsa sil
        try:
            md_pair = target.with_suffix(".md")
            if md_pair.exists():
                md_pair.unlink()
        except Exception:
            pass
        _log_audit(
            "ai_diet_delete_saved",
            entity_type="patient",
            patient_key=patient_key,
            details=f"file:{file_name}",
        )
        return jsonify({"ok": True, "message": f"Silindi: {file_name}"})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/hasta/<patient_key>/diyet-dosya/<file_name>", methods=["GET"])
@login_required
def api_diet_view_saved_file(patient_key, file_name):
    """B440/C14: Hasta klasorune kaydedilen diyet HTML dosyasini sun."""
    return _diet_serve_saved_file_helper(patient_key, file_name)


def _diet_serve_saved_file_helper(patient_key, file_name):
    """C14: Hem yeni /api/hasta/<key>/diyet-dosya/ hem eski (B439 oncesi)
    /hasta/<key>/dosya/ route'undan diyet HTML dosyasini sun.

    Doktor C13 uygulanmadan B439 calistirir + onceden kaydedilmis
    YZ_Diyet_*.html dosyalarini gormek isterse 404 alirdi - bu helper
    'Diyet/' klasorunden de dener, oyle ki eski URL'ler de calisir.
    """
    from pathlib import Path as _Path
    from flask import send_file as _send_file
    if "/" in file_name or "\\" in file_name or ".." in file_name:
        return jsonify({"ok": False, "error": "Gecersiz dosya."}), 400
    try:
        proot = _Path(_patient_root_for_nas(patient_key))
        candidates = [
            proot / "Diyet" / file_name,
            proot / file_name,
        ]
        for cp in candidates:
            if cp.exists() and cp.is_file():
                if cp.suffix.lower() in (".html", ".htm"):
                    html_text = cp.read_text(encoding="utf-8", errors="replace")
                    resp = make_response(_diet_sanitize_saved_html_v1000(html_text))
                    resp.headers["Content-Type"] = "text/html; charset=utf-8"
                    return resp
                return _send_file(str(cp), as_attachment=False)
        return jsonify({
            "ok": False,
            "error": f"Dosya bulunamadi: {file_name}",
            "looked_in": [str(c) for c in candidates],
        }), 404
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/hasta/<patient_key>/dosya/<path:file_name>", methods=["GET"])
@login_required
def api_diet_view_saved_file_legacy(patient_key, file_name):
    """C14 GERIYE UYUMLULUK: B439 ve onceki sÃ¼rÃ¼mler diyet kaydetince file_url
    olarak '/hasta/<key>/dosya/<file>' uretiyordu. C10'dan itibaren yeni endpoint
    /api/hasta/<key>/diyet-dosya/<file> kullanildi - ama doktor B439 cagrilarini
    da gormeye devam ediyor (eski JS cache veya eski uretilmis link). Bu route
    YZ_Diyet_*.html ve onceden kaydedilmis diyet dosyalarini Diyet/ klasorunden
    sunar - 404 vermek yerine. Sadece HTML/MD/PDF + 'YZ_Diyet_' prefix'li
    dosyalar guvenli olarak servisedir.
    """
    safe = (file_name or "").strip()
    if not safe or "\\" in safe or ".." in safe:
        return jsonify({"ok": False, "error": "Gecersiz dosya."}), 400
    # Sadece diyet sample'lari + onam + standart hasta belge tipleri
    safe_lower = safe.lower()
    allowed_exts = (".html", ".htm", ".md", ".pdf", ".txt")
    if not any(safe_lower.endswith(e) for e in allowed_exts):
        return jsonify({
            "ok": False,
            "error": "Bu legacy route sadece HTML/MD/PDF/TXT diyet dosyalari icin.",
        }), 400
    return _diet_serve_saved_file_helper(patient_key, safe)


