@app.route("/hasta/<patient_key>/diyet-kayit/<int:doc_id>", methods=["GET"])
@login_required
def api_diet_view_db_document(patient_key, doc_id):
    try:
        _diet_docs_ensure_schema()
        with db_conn() as con:
            con.row_factory = sqlite3.Row
            row = con.execute(
                "SELECT html_blob, file_name, patient_label, diet_type, "
                "markdown, created_at "
                "FROM patient_diet_documents "
                "WHERE id=? AND patient_key=? AND COALESCE(deleted_at,'')='' "
                "LIMIT 1",
                (int(doc_id), patient_key)).fetchone()
        if not row:
            return jsonify({"ok": False, "error": "Diyet kaydi bulunamadi."}), 404
        html_text = _diet_document_html_from_row_v1000(row, patient_key)
        resp = make_response(html_text)
        resp.headers["Content-Type"] = "text/html; charset=utf-8"
        resp.headers["Cache-Control"] = "no-store"
        return resp
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/hasta/<patient_key>/diyet-kayit/<int:doc_id>/pdf", methods=["GET"])
@login_required
def api_diet_view_db_pdf(patient_key, doc_id):
    try:
        _diet_docs_ensure_schema()
        with db_conn() as con:
            con.row_factory = sqlite3.Row
            row = con.execute(
                "SELECT pdf_blob, html_blob, file_name, patient_label, "
                "diet_type, markdown, created_at "
                "FROM patient_diet_documents "
                "WHERE id=? AND patient_key=? AND COALESCE(deleted_at,'')='' "
                "LIMIT 1",
                (int(doc_id), patient_key)).fetchone()
        if not row:
            return jsonify({"ok": False, "error": "Diyet PDF bulunamadi."}), 404
        blob = bytes(row["pdf_blob"] or b"")
        try:
            html_text = _diet_document_html_from_row_v1000(row, patient_key)
            source_text = _diet_canonical_pdf_source_v1000(
                str(row["markdown"] or ""), html_text)
            if source_text:
                profile = _diet_profile_v1000(patient_key)
                fresh_blob = _diet_pdf_blob_from_text(
                    row["patient_label"] or _patient_display_label(patient_key, include_date=True),
                    row["diet_type"] or "standart",
                    source_text,
                    profile=profile)
                if fresh_blob:
                    blob = fresh_blob
        except Exception:
            pass
        if not blob:
            return jsonify({"ok": False, "error": "PDF icerigi bos."}), 404
        return send_file(
            BytesIO(blob),
            mimetype="application/pdf",
            download_name=row["file_name"] or f"YZ_Diyet_{doc_id}.pdf",
            as_attachment=False,
            max_age=0)
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/hasta/<patient_key>/diyet-kaydet", methods=["POST"])
@login_required
def api_diet_save_to_patient(patient_key):
    """B438/C12: YZ ile uretilen diyet listesini hasta klasorune HTML olarak
    kaydet. C12: Adim adim hata raporu - doktor 'database de sikinti mi var'
    deyince hangi adimda takildigi netlessin diye 'trace' alani eklendi.
    """
    trace = []  # C12: adim adim ne basarildi
    try:
        # 0) Payload parse
        data = request.get_json(silent=True) or {}
        diet_type = (data.get("diet_type") or "diyet").strip() or "diyet"
        markdown = _diet_display_block_text_v1000(data.get("markdown") or "")
        html_body = _diet_light_mojibake_clean_v1000(
            data.get("html") or "", collapse=False).strip()
        trace.append(f"payload md_len={len(markdown)} html_len={len(html_body)}")
        if not (markdown or html_body):
            return jsonify({
                "ok": False,
                "error": "Bos icerik. Markdown ve HTML ikisi de bos geldi.",
                "trace": trace,
            }), 400
        # D88: Diyet kayitlari artik NAS klasorune degil, hasta veritabanina
        # gomulu HTML + PDF BLOB olarak kaydedilir. Eski disk kodu geriye
        # uyumluluk icin altta kalir ama bu noktadan sonra calismaz.
        doc = _diet_save_document_db(
            patient_key=patient_key,
            diet_type=diet_type,
            markdown=markdown,
            html_body=html_body,
            created_by=str(session.get("user") or ""),
            source="manual-save")
        trace.append("DB diet document OK")
        try:
            _log_audit(
                "ai_diet_save_to_patient_db",
                entity_type="patient",
                patient_key=patient_key,
                details=f"type:{diet_type} id:{doc.get('id')}",
            )
        except Exception:
            pass
        return jsonify({
            "ok": True,
            "record_id": doc.get("id"),
            "file_name": doc.get("file_name"),
            "file_path": doc.get("file_path"),
            "file_url": doc.get("file_url"),
            "pdf_url": doc.get("pdf_url"),
            "diet_dir": "YazKlinik veritabani",
            "message": f"Diyet listesi veritabanina kaydedildi: {doc.get('file_name')}",
            "trace": trace,
        })

        # 1) Hasta klasor kokunu bul
        patient_root = None
        root_err = ""
        try:
            patient_root = _patient_root_for_nas(patient_key)
            trace.append(f"patient_root={patient_root}")
        except Exception as ex:
            root_err = str(ex)
            trace.append(f"patient_root ERR: {ex}")
        if not patient_root:
            return jsonify({
                "ok": False,
                "error": (
                    f"Hasta klasoru bulunamadi (key={patient_key}). "
                    f"{root_err}"
                ),
                "trace": trace,
            }), 400

        from pathlib import Path as _Path
        import datetime as _dt
        proot = _Path(patient_root)
        if not proot.exists():
            # NAS yoksa lokal yedek altinda yazalim - asla 'kaydetme' demeyelim
            try:
                local_root = _Path.home() / "YazKlinik_DiyetYedek" / str(patient_key)
                local_root.mkdir(parents=True, exist_ok=True)
                proot = local_root
                trace.append(f"NAS yok, lokal yedek: {proot}")
            except Exception as ex:
                return jsonify({
                    "ok": False,
                    "error": f"Hasta klasoru hem NAS'ta hem lokal yedekte yok: {ex}",
                    "trace": trace,
                }), 500

        # 2) Diyet alt klasoru olustur
        diet_dir = proot / "Diyet"
        try:
            diet_dir.mkdir(parents=True, exist_ok=True)
            trace.append(f"diet_dir OK: {diet_dir}")
        except Exception as ex:
            trace.append(f"diet_dir mkdir ERR ({ex}); fallback to proot")
            diet_dir = proot
        ts = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
        base_name = f"YZ_Diyet_{diet_type}_{ts}"

        # 3) Markdown raw kayit (debug/historik)
        try:
            (diet_dir / f"{base_name}.md").write_text(
                markdown or "", encoding="utf-8")
            trace.append("md write OK")
        except Exception as ex:
            trace.append(f"md write ERR: {ex}")

        # 4) HTML standalone (yazdirma + arsiv)
        try:
            patient_label = _patient_display_label(patient_key, include_date=True)
        except Exception:
            patient_label = patient_key
        # C22: Premium A4 template - day-card grid CSS embed
        full_html = _diet_save_premium_html_c22(
            patient_label=patient_label,
            diet_type=diet_type,
            ts=ts,
            inner_html=(html_body or _diet_markdown_html_v1000(markdown)),
        )
        html_path = diet_dir / f"{base_name}.html"
        try:
            html_path.write_text(full_html, encoding="utf-8")
            trace.append(f"html write OK: {html_path.name} ({html_path.stat().st_size} bytes)")
        except Exception as ex:
            return jsonify({
                "ok": False,
                "error": f"HTML yazma hatasi: {ex}",
                "trace": trace,
                "diet_dir": str(diet_dir),
            }), 500

        # 5) Files DB'ye index'le (opsiyonel - varsa)
        try:
            with db_conn() as con:
                con.execute(
                    "INSERT OR IGNORE INTO files "
                    "(patient_folder_key, visit_key, file_kind, file_name, "
                    "full_path, mtime, size_bytes, first_seen_at, "
                    "last_synced_at) "
                    "VALUES(?, '', 'html', ?, ?, ?, ?, ?, ?)",
                    (patient_key, html_path.name, str(html_path),
                     int(html_path.stat().st_mtime),
                     html_path.stat().st_size,
                     _dt.datetime.now().isoformat(timespec="seconds"),
                     _dt.datetime.now().isoformat(timespec="seconds")))
                con.commit()
                trace.append("DB index OK")
        except Exception as ex:
            trace.append(f"DB index skipped: {ex}")

        # 6) Web URL - C10: dedicated endpoint /api/hasta/<key>/diyet-dosya/<name>
        try:
            from urllib.parse import quote as _q
            file_url = (
                f"/api/hasta/{_q(patient_key, safe='')}"
                f"/diyet-dosya/{_q(html_path.name, safe='')}"
            )
        except Exception:
            file_url = ""

        try:
            _log_audit(
                "ai_diet_save_to_patient",
                entity_type="patient",
                patient_key=patient_key,
                details=f"type:{diet_type} file:{html_path.name}",
            )
        except Exception:
            pass

        return jsonify({
            "ok": True,
            "file_name": html_path.name,
            "file_path": str(html_path),
            "file_url": file_url,
            "diet_dir": str(diet_dir),
            "message": f"Diyet listesi kaydedildi: {html_path.name}",
            "trace": trace,
        })
    except Exception as ex:
        import traceback as _tb
        return jsonify({
            "ok": False,
            "error": f"Beklenmeyen hata: {ex}",
            "trace": trace,
            "tb": _tb.format_exc()[-600:],
        }), 500
    """ğŸ¥— YZ KiÅŸisel Diyet PlanÄ± - LMP, BMI, tahliller, gebelik dahil."""
    import urllib.request as _urllib_req
    import urllib.error as _urllib_err
    import json as _json

    plan_text = ""
    error_msg = ""

    # Hasta verilerini topla
    try:
        demo = load_patient_demographics(patient_key)
    except Exception:
        demo = {}

    age = demo.get("age") or "-"
    weight = demo.get("weight")
    height = demo.get("height")
    pre_weight = demo.get("pre_pregnancy_weight")
