_BG_JOB_STATUS_CACHE = {"ts": 0.0, "user": None, "payload": None}
_BG_JOB_STATUS_CACHE_TTL = 20.0


def _yk_bg_jobs_clear_status_cache():
    try:
        _BG_JOB_STATUS_CACHE["ts"] = 0.0
        _BG_JOB_STATUS_CACHE["user"] = None
        _BG_JOB_STATUS_CACHE["payload"] = None
    except Exception:
        pass


@app.route("/api/arka-plan-gorevleri/durum", methods=["GET"])
@login_required
def api_background_jobs_status():
    """D88: Diyet ve HD Studio arka plan isleri icin global bildirim verisi."""
    try:
        username = str(session.get("user") or "")
        now = time.time()
        force = str(request.args.get("force") or request.args.get("refresh") or "").strip().lower() in {
            "1", "true", "yes", "evet"
        }
        cached = _BG_JOB_STATUS_CACHE.get("payload")
        if (
            not force
            and cached is not None
            and _BG_JOB_STATUS_CACHE.get("user") == username
            and now - float(_BG_JOB_STATUS_CACHE.get("ts") or 0.0) < _BG_JOB_STATUS_CACHE_TTL
        ):
            return jsonify(cached)

        _yk_bg_jobs_ensure_schema()
        params = []
        where = []
        if username:
            where.append("(created_by=? OR COALESCE(created_by,'')='')")
            params.append(username)
        where.append("COALESCE(dismissed_at,'')=''")
        sql = (
            "SELECT id, job_type, patient_key, title, status, progress, "
            "result_url, result_label, error, created_at, started_at, "
            "finished_at, updated_at "
            "FROM yk_background_jobs "
        )
        if where:
            sql += "WHERE " + " AND ".join(where) + " "
        sql += "ORDER BY updated_at DESC, id DESC LIMIT 40"
        with db_conn() as con:
            con.row_factory = sqlite3.Row
            rows = con.execute(sql, params).fetchall()
        jobs = []
        cutoff_ts = time.time() - (24 * 60 * 60)
        for row in rows:
            d = _yk_row_dict(row)
            updated = str(d.get("updated_at") or d.get("created_at") or "")
            try:
                updated_ts = datetime.fromisoformat(
                    updated.replace("T", " ")).timestamp()
            except Exception:
                updated_ts = time.time()
            if updated_ts < cutoff_ts and d.get("status") not in ("running", "queued"):
                continue
            label = d.get("result_label") or d.get("title") or ""
            if d.get("job_type") == "ai_diet":
                kind_label = "YZ diyet"
                icon = "bi bi-egg-fried"
            elif d.get("job_type") == "hd_studio":
                kind_label = "HD Studio"
                icon = "bi bi-magic"
            else:
                kind_label = "Arka plan"
                icon = "bi bi-hourglass-split"
            jobs.append({
                "id": int(d.get("id") or 0),
                "type": d.get("job_type") or "",
                "kind_label": kind_label,
                "icon": icon,
                "patient_key": d.get("patient_key") or "",
                "title": d.get("title") or kind_label,
                "status": d.get("status") or "",
                "progress": d.get("progress") or "",
                "result_url": d.get("result_url") or "",
                "result_label": label,
                "error": d.get("error") or "",
                "updated_at": updated,
            })
        payload = {"ok": True, "jobs": jobs}
        _BG_JOB_STATUS_CACHE["ts"] = now
        _BG_JOB_STATUS_CACHE["user"] = username
        _BG_JOB_STATUS_CACHE["payload"] = payload
        return jsonify(payload)
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/arka-plan-gorevleri/temizle", methods=["POST"])
@login_required
def api_background_jobs_dismiss():
    """Persistently hide background-job toasts once the user clears them."""
    try:
        username = str(session.get("user") or "")
        data = request.get_json(silent=True) or {}
        raw_ids = data.get("job_ids") or data.get("ids") or []
        if isinstance(raw_ids, (str, int)):
            raw_ids = [raw_ids]
        job_ids = []
        for raw in raw_ids:
            try:
                val = int(raw)
                if val > 0:
                    job_ids.append(val)
            except Exception:
                pass
        job_ids = sorted(set(job_ids))
        now_text = _yk_now_text()
        _yk_bg_jobs_ensure_schema()
        with db_conn() as con:
            if job_ids:
                placeholders = ",".join("?" for _ in job_ids)
                params = [now_text, username] + job_ids
                sql = (
                    "UPDATE yk_background_jobs "
                    "SET dismissed_at=?, dismissed_by=?, updated_at=? "
                    f"WHERE id IN ({placeholders}) "
                    "AND COALESCE(dismissed_at,'')=''"
                )
                params.insert(2, now_text)
                if username:
                    sql += " AND (created_by=? OR COALESCE(created_by,'')='')"
                    params.append(username)
                cur = con.execute(sql, params)
            else:
                params = [now_text, username, now_text]
                sql = (
                    "UPDATE yk_background_jobs "
                    "SET dismissed_at=?, dismissed_by=?, updated_at=? "
                    "WHERE status IN ('done','error') "
                    "AND COALESCE(dismissed_at,'')=''"
                )
                if username:
                    sql += " AND (created_by=? OR COALESCE(created_by,'')='')"
                    params.append(username)
                cur = con.execute(sql, params)
            con.commit()
            count = int(cur.rowcount or 0)
        _yk_bg_jobs_clear_status_cache()
        return jsonify({"ok": True, "dismissed": count, "ids": job_ids})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


