@app.route("/hasta/<patient_key>/tarama-dosya/<filename>")
@login_required
def screening_file(patient_key, filename):
    """Tarama testi dosyasÄ±nÄ± indir/gÃ¶rÃ¼ntÃ¼le."""
    file_path = (Path(get_data_root_dir()) / patient_key /
                  "tarama" / filename)
