def _hd_float(form, name, default, low=None, high=None):
    try:
        value = float(str(form.get(name, default)).replace(",", "."))
    except Exception:
        value = float(default)
    if low is not None:
        value = max(low, value)
    if high is not None:
        value = min(high, value)
    return value


