def _hd_apply_gamma(img, gamma):
    if abs(float(gamma or 1.0) - 1.0) < 0.02:
        return img
    inv = 1.0 / max(0.05, float(gamma))
    table = [min(255, int(((i / 255.0) ** inv) * 255)) for i in range(256)]
    if img.mode == "RGB":
        return img.point(table * 3)
    return img.point(table)


def _hd_apply_warmth(img, amount):
    from PIL import ImageEnhance
    img = img.convert("RGB")
    r, g, b = img.split()
    warm = float(amount or 1.0)
    r = r.point(lambda p: min(255, int(p * warm)))
    b = b.point(lambda p: max(0, int(p * (2.0 - warm))))
    img = __import__("PIL.Image", fromlist=["Image"]).merge("RGB", (r, g, b))
    return ImageEnhance.Color(img).enhance(1.03 if warm >= 1 else 0.98)


def _hd_directional_light(img, strength=0.22, angle=315):
    from PIL import Image, ImageChops
    import math
    strength = max(0.0, min(float(strength or 0), 1.2))
    if strength <= 0.01:
        return img
    img = img.convert("RGB")
    w, h = img.size
    theta = math.radians(float(angle or 315))
    dx, dy = math.cos(theta), math.sin(theta)
    px = img.load()
    overlay = Image.new("RGB", (w, h), (0, 0, 0))
    opx = overlay.load()
    denom = max(1, w + h)
    for y in range(h):
        for x in range(w):
            t = ((x - w / 2) * dx + (y - h / 2) * dy) / denom + 0.5
            val = int(max(0, min(255, 255 * t * strength)))
            opx[x, y] = (val, int(val * 0.92), int(val * 0.78))
    return ImageChops.screen(img, overlay)


def _hd_spot_light(img, strength=0.28, center_x=50, center_y=36, size=58):
    from PIL import Image, ImageChops, ImageFilter
    strength = max(0.0, min(float(strength or 0), 1.2))
    if strength <= 0.01:
        return img
    img = img.convert("RGB")
    w, h = img.size
    diameter = int(max(w, h) * max(0.12, min(float(size or 58), 180.0)) / 100.0)
    diameter = max(64, diameter)
    cx = int(w * max(0.0, min(float(center_x or 50), 100.0)) / 100.0)
    cy = int(h * max(0.0, min(float(center_y or 36), 100.0)) / 100.0)
    mask = Image.new("L", (w, h), 0)
    grad = Image.radial_gradient("L").resize((diameter, diameter))
    grad = ImageChops.invert(grad).filter(ImageFilter.GaussianBlur(max(2, diameter // 22)))
    grad = grad.point(lambda p: int(p * strength))
    mask.paste(grad, (cx - diameter // 2, cy - diameter // 2))
    overlay = Image.new("RGB", (w, h), (255, 244, 220))
    return Image.composite(ImageChops.screen(img, overlay), img, mask)


def _hd_vignette(img, amount=0.22):
    from PIL import Image, ImageChops, ImageFilter
    amount = max(0.0, min(float(amount or 0), 1.0))
    if amount <= 0.01:
        return img
    img = img.convert("RGB")
    w, h = img.size
    diameter = int(max(w, h) * 1.55)
    grad = Image.radial_gradient("L").resize((diameter, diameter))
    grad = grad.crop((
        (diameter - w) // 2,
        (diameter - h) // 2,
        (diameter - w) // 2 + w,
        (diameter - h) // 2 + h,
    ))
    mask = grad.filter(ImageFilter.GaussianBlur(max(8, int(max(w, h) * 0.035))))
    mask = mask.point(lambda p: int(p * amount))
    dark = Image.new("RGB", (w, h), (0, 0, 0))
    return Image.composite(dark, img, mask)


def _hd_apply_light_mode(img, settings):
    mode = str((settings or {}).get("light_mode") or "preset").strip().lower()
    if mode in ("", "preset", "none"):
        vignette = float((settings or {}).get("vignette") or 0)
        return _hd_vignette(img, vignette) if vignette > 0.01 else img
    strength = float((settings or {}).get("light_strength") or 0.22)
    angle_map = {
        "left_top": 225,
        "right_top": 315,
        "left_bottom": 135,
        "right_bottom": 45,
        "top": 270,
        "bottom": 90,
        "side_left": 180,
        "side_right": 0,
    }
    if mode in angle_map:
        img = _hd_directional_light(img, strength=strength, angle=angle_map[mode])
    elif mode == "center":
        img = _hd_spot_light(
            img, strength=strength,
            center_x=(settings or {}).get("spot_x", 50),
            center_y=(settings or {}).get("spot_y", 42),
            size=(settings or {}).get("spot_size", 72))
    elif mode == "spot":
        img = _hd_spot_light(
            img, strength=strength,
            center_x=(settings or {}).get("spot_x", 50),
            center_y=(settings or {}).get("spot_y", 36),
            size=(settings or {}).get("spot_size", 58))
    elif mode == "dual":
        img = _hd_directional_light(img, strength=strength * 0.75, angle=315)
        img = _hd_directional_light(img, strength=strength * 0.52, angle=225)
        img = _hd_spot_light(
            img, strength=strength * 0.46,
            center_x=(settings or {}).get("spot_x", 50),
            center_y=(settings or {}).get("spot_y", 38),
            size=(settings or {}).get("spot_size", 70))
    elif mode == "ambient":
        img = _hd_directional_light(img, strength=strength * 0.34, angle=270)
        img = _hd_spot_light(
            img, strength=strength * 0.32,
            center_x=(settings or {}).get("spot_x", 50),
            center_y=(settings or {}).get("spot_y", 45),
            size=max(96, float((settings or {}).get("spot_size", 96) or 96)))
    elif mode == "rim":
        img = _hd_directional_light(img, strength=strength * 0.85, angle=315)
        img = _hd_directional_light(img, strength=strength * 0.45, angle=135)
    elif mode == "cinema":
        img = _hd_spot_light(
            img, strength=strength,
            center_x=(settings or {}).get("spot_x", 50),
            center_y=(settings or {}).get("spot_y", 35),
            size=(settings or {}).get("spot_size", 64))
        img = _hd_vignette(img, max(0.18, float((settings or {}).get("vignette") or 0.28)))
        return img
    elif mode == "vignette":
        img = _hd_vignette(img, max(0.18, float((settings or {}).get("vignette") or 0.28)))
        return img
    vignette = float((settings or {}).get("vignette") or 0)
    if vignette > 0.01:
        img = _hd_vignette(img, vignette)
    return img


def _hd_apply_premium_voluson(img, settings=None):
    """Deterministic HD Live style finish for USG presentation copies."""
    from PIL import Image
    settings = settings or {}
    preset_name = str(settings.get("preset") or "").strip().lower()
    if preset_name:
        tuned = dict(settings)
        if preset_name == "voluson_hd_live_extreme":
            tuned["contrast"] = max(float(tuned.get("contrast", 1.18) or 1.18), 1.34)
            tuned["micro_contrast"] = max(float(tuned.get("micro_contrast", 1.12) or 1.12), 1.65)
            tuned["structure"] = max(float(tuned.get("structure", 1.08) or 1.08), 1.55)
            tuned["depth"] = max(float(tuned.get("depth", 0.42) or 0.42), 0.78)
            tuned["relief"] = max(float(tuned.get("relief", 0.70) or 0.70), 1.15)
            tuned["light_strength"] = max(float(tuned.get("light_strength", 0.22) or 0.22), 0.52)
            tuned["light_mix"] = max(float(tuned.get("light_mix", 0.65) or 0.65), 0.78)
            if str(tuned.get("light_mode") or "preset").lower() in {"", "preset", "none"}:
                tuned["light_mode"] = "cinema"
            tuned["vignette"] = max(float(tuned.get("vignette", 0) or 0), 0.16)
        elif preset_name == "usg_ultra_clean":
            tuned["denoise"] = max(float(tuned.get("denoise", 1.0) or 1.0), 1.35)
            tuned["speckle"] = max(float(tuned.get("speckle", 0.85) or 0.85), 1.55)
            tuned["edge_guard"] = max(float(tuned.get("edge_guard", 0.55) or 0.55), 0.72)
            tuned["micro_contrast"] = min(max(float(tuned.get("micro_contrast", 1.12) or 1.12), 0.96), 1.36)
            tuned["structure"] = min(max(float(tuned.get("structure", 1.08) or 1.08), 0.86), 1.30)
        elif preset_name == "usg_shadow_rescue":
            tuned["brightness"] = max(float(tuned.get("brightness", 1.04) or 1.04), 1.16)
            tuned["contrast"] = max(float(tuned.get("contrast", 1.18) or 1.18), 1.12)
            tuned["shadow_lift"] = max(float(tuned.get("shadow_lift", 0.12) or 0.12), 0.46)
            tuned["black_guard"] = max(float(tuned.get("black_guard", 0.88) or 0.88), 0.92)
            tuned["light_strength"] = max(float(tuned.get("light_strength", 0.22) or 0.22), 0.24)
            if str(tuned.get("light_mode") or "preset").lower() in {"", "preset", "none"}:
                tuned["light_mode"] = "ambient"
        elif preset_name == "usg_print_crisp":
            tuned["contrast"] = max(float(tuned.get("contrast", 1.18) or 1.18), 1.42)
            tuned["clarity"] = max(float(tuned.get("clarity", 1.0) or 1.0), 1.75)
            tuned["micro_contrast"] = max(float(tuned.get("micro_contrast", 1.12) or 1.12), 1.58)
            tuned["structure"] = max(float(tuned.get("structure", 1.08) or 1.08), 1.45)
            tuned["highlight_guard"] = max(float(tuned.get("highlight_guard", 0.62) or 0.62), 0.82)
            tuned["label_guard"] = max(float(tuned.get("label_guard", 0.92) or 0.92), 0.96)
        elif preset_name == "usg_soft_depth":
            tuned["warmth"] = max(float(tuned.get("warmth", 1.10) or 1.10), 1.16)
            tuned["depth"] = max(float(tuned.get("depth", 0.42) or 0.42), 0.64)
            tuned["relief"] = max(float(tuned.get("relief", 0.70) or 0.70), 0.96)
            tuned["structure"] = min(max(float(tuned.get("structure", 1.08) or 1.08), 0.92), 1.32)
            tuned["vignette"] = max(float(tuned.get("vignette", 0) or 0), 0.12)
        settings = tuned
    img = img.convert("RGB")
    log = []
    try:
        import math
        import cv2
        import numpy as np

        original = np.array(img).astype(np.float32)
        arr = original.copy()
        h, w = arr.shape[:2]
        if not h or not w:
            return img, ["Premium HD Live: goruntu boyutu okunamadi"]

        gray_u8 = cv2.cvtColor(original.astype(np.uint8), cv2.COLOR_RGB2GRAY)
        hsv = cv2.cvtColor(original.astype(np.uint8), cv2.COLOR_RGB2HSV)
        tissue = np.clip((gray_u8.astype(np.float32) - 38.0) / 72.0, 0.0, 1.0)
        tissue = cv2.GaussianBlur(tissue, (0, 0), max(1.4, min(w, h) * 0.006))
        tissue = np.clip(tissue, 0.0, 1.0)
        tissue3 = tissue[:, :, None]

        denoise = float(settings.get("denoise", 1.0) or 0)
        speckle = float(settings.get("speckle", 0.85) or 0)
        if denoise > 0.05:
            # Bilateral filtering keeps USG contours better than a flat blur.
            filtered = cv2.bilateralFilter(
                arr.astype(np.uint8), 5,
                18 + int(denoise * 14), 18 + int(denoise * 12))
            alpha = min(0.55, 0.22 + denoise * 0.12)
            arr = arr * (1.0 - alpha) + filtered.astype(np.float32) * alpha
            log.append("Premium denoise: gren azaltilip kenarlar korunarak yumusatildi")
        if speckle > 0.05:
            kernel = 5 if max(w, h) < 1600 else 7
            filtered = cv2.bilateralFilter(
                arr.astype(np.uint8), kernel,
                22 + int(speckle * 18), 16 + int(speckle * 14))
            alpha = min(0.64, 0.14 + speckle * 0.18)
            arr = arr * (1.0 - alpha) + filtered.astype(np.float32) * alpha
            log.append("Speckle temizleme: USG grenleri kontur ezmeden azaltildi")

        micro = float(settings.get("micro_contrast", 1.12) or 0)
        local_contrast = float(settings.get("local_contrast", 1.0) or 0)
        contrast_drive = max(micro, local_contrast * 0.92)
        if contrast_drive > 0.02:
            lab = cv2.cvtColor(arr.astype(np.uint8), cv2.COLOR_RGB2LAB)
            l_chan, a_chan, b_chan = cv2.split(lab)
            clahe = cv2.createCLAHE(
                clipLimit=max(1.2, min(5.4, 1.35 + contrast_drive * 1.12)),
                tileGridSize=(8, 8))
            l2 = clahe.apply(l_chan)
            alpha = min(0.86, 0.20 + contrast_drive * 0.22)
            l_chan = cv2.addWeighted(l_chan, 1.0 - alpha, l2, alpha, 0)
            arr = cv2.cvtColor(
                cv2.merge((l_chan, a_chan, b_chan)), cv2.COLOR_LAB2RGB
            ).astype(np.float32)
            log.append("Lokal kontrast: USG dokusu bolgesel kontrastla belirginlestirildi")

        brightness = float(settings.get("brightness", 1.04) or 1.0)
        contrast = float(settings.get("contrast", 1.18) or 1.0)
        gamma = float(settings.get("gamma", 0.96) or 1.0)
        arr = ((arr - 127.5) * contrast) + 127.5
        arr = arr * brightness
        if abs(gamma - 1.0) > 0.02:
            norm = np.clip(arr / 255.0, 0.0, 1.0)
            arr = np.power(norm, 1.0 / max(0.08, gamma)) * 255.0

        white_balance = float(settings.get("white_balance", 1.0) or 1.0)
        if abs(white_balance - 1.0) > 0.03:
            wb = arr.copy()
            delta = white_balance - 1.0
            wb[:, :, 0] *= 1.0 + 0.10 * delta
            wb[:, :, 1] *= 1.0 + 0.04 * delta
            wb[:, :, 2] *= 1.0 - 0.10 * delta
            arr = arr * (1.0 - 0.45 * tissue3) + wb * (0.45 * tissue3)
            log.append("Beyaz dengesi: USG sunum tonu kontrollu duzeltildi")

        shadow_lift = float(settings.get("shadow_lift", 0.12) or 0)
        if shadow_lift > 0.01:
            luma = cv2.cvtColor(np.clip(arr, 0, 255).astype(np.uint8), cv2.COLOR_RGB2GRAY).astype(np.float32) / 255.0
            shadow = np.power(1.0 - luma, 1.85) * tissue
            arr += (shadow[:, :, None] * (255.0 * shadow_lift * 0.42))
            log.append("Golgelendirme: koyu doku alanlari siyah zemin bozulmadan acildi")

        structure = float(settings.get("structure", 1.08) or 0)
        if structure > 0.02:
            sigma = 0.72 + min(structure, 2.4) * 0.32
            blur = cv2.GaussianBlur(arr, (0, 0), sigma)
            highpass = arr - blur
            arr = arr + highpass * min(0.72, 0.20 + structure * 0.18) * tissue3
            log.append("Doku isciligi: kontur ve ince yuzey detaylari kontrollu netlestirildi")

        depth = float(settings.get("depth", 0.42) or 0)
        relief = float(settings.get("relief", 0.70) or 0)
        depth = min(1.8, depth + relief * 0.28)
        if depth > 0.01:
            surface = cv2.GaussianBlur(
                gray_u8.astype(np.float32) / 255.0, (0, 0),
                max(1.0, min(w, h) * 0.004))
            gx = cv2.Sobel(surface, cv2.CV_32F, 1, 0, ksize=3)
            gy = cv2.Sobel(surface, cv2.CV_32F, 0, 1, ksize=3)
            theta = math.radians(float(settings.get("light_angle", 315) or 315))
            bump = gx * math.cos(theta) + gy * math.sin(theta)
            scale = np.percentile(np.abs(bump), 96) + 1e-5
            bump = np.clip(bump / scale, -1.0, 1.0)
            arr += bump[:, :, None] * (24.0 * depth) * tissue3
            log.append("Hacim hissi: HD Live benzeri yuzey isigi ve derinlik verildi")

        warmth = float(settings.get("warmth", 1.10) or 1.0)
        if abs(warmth - 1.0) > 0.02:
            warm = arr.copy()
            delta = warmth - 1.0
            warm[:, :, 0] *= 1.0 + (0.30 * delta)
            warm[:, :, 1] *= 1.0 + (0.08 * delta)
            warm[:, :, 2] *= 1.0 - (0.24 * delta)
            arr = arr * (1.0 - 0.65 * tissue3) + warm * (0.65 * tissue3)
            log.append("Sicak HD ton: fetal sunum icin ilik hacim rengi uygulandi")

        strength = float(settings.get("light_strength", 0.34) or 0)
        light_mix = float(settings.get("light_mix", 0.65) or 0.65)
        mode = str(settings.get("light_mode") or "cinema").strip().lower()
        if strength > 0.01:
            yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
            angle_map = {
                "left_top": 225, "right_top": 315,
                "left_bottom": 135, "right_bottom": 45,
                "top": 270, "bottom": 90,
                "side_left": 180, "side_right": 0,
            }
            angle = float(angle_map.get(mode, settings.get("light_angle", 315) or 315))
            theta = math.radians(angle)
            denom = max(1.0, math.sqrt(w * w + h * h))
            beam = ((xx - w / 2.0) * math.cos(theta) + (yy - h / 2.0) * math.sin(theta)) / denom + 0.52
            beam = np.clip(beam, 0.0, 1.0) ** 1.12
            spot_x = w * float(settings.get("spot_x", 50) or 50) / 100.0
            spot_y = h * float(settings.get("spot_y", 36) or 36) / 100.0
            spot_size = max(0.18, min(float(settings.get("spot_size", 64) or 64) / 100.0, 1.4))
            sigma = max(w, h) * spot_size * 0.34
            spot = np.exp(-(((xx - spot_x) ** 2 + (yy - spot_y) ** 2) / (2.0 * sigma * sigma)))
            if mode == "spot":
                beam *= 0.35
                spot *= 1.15
            elif mode == "rim":
                beam *= 1.35
                spot *= 0.45
            elif mode == "center":
                beam *= 0.22
                spot *= 1.24
            elif mode == "dual":
                beam2 = ((xx - w / 2.0) * math.cos(math.radians(225)) + (yy - h / 2.0) * math.sin(math.radians(225))) / denom + 0.52
                beam = np.clip(beam + np.clip(beam2, 0.0, 1.0) ** 1.12 * 0.68, 0.0, 1.35)
                spot *= 0.72
            elif mode == "ambient":
                beam = np.clip(beam * 0.32 + 0.42, 0.0, 1.0)
                spot *= 0.38
            elif mode in ("cinema", "preset", ""):
                beam *= 0.72
                spot *= 1.05
            light_alpha = np.clip(
                (beam * 0.38 + spot * 0.78) * strength * (0.55 + light_mix * 0.65),
                0.0, 0.92) * tissue
            light = np.zeros_like(arr)
            light[:, :, 0] = 255
            light[:, :, 1] = 236
            light[:, :, 2] = 198
            screen = 255.0 - (255.0 - arr) * (255.0 - light) / 255.0
            arr = arr * (1.0 - light_alpha[:, :, None]) + screen * light_alpha[:, :, None]
            log.append("Canli isik: spot ve yonlu isik doku uzerine maskeleyerek uygulandi")

        edge_guard = float(settings.get("edge_guard", 0.55) or 0)
        if edge_guard > 0.01:
            edges = cv2.Canny(gray_u8, 36, 118).astype(np.float32) / 255.0
            edges = cv2.dilate(edges, np.ones((2, 2), np.uint8), iterations=1)
            edges = cv2.GaussianBlur(edges, (0, 0), 0.85)[:, :, None]
            arr = arr * (1.0 - edges * edge_guard * 0.55) + original * (edges * edge_guard * 0.55)
            log.append("Kenar koruma: kontur ve olcum kenarlari asiri islemden korundu")

        highlight_guard = float(settings.get("highlight_guard", 0.62) or 0)
        if highlight_guard > 0.01:
            high_mask = np.clip((gray_u8.astype(np.float32) - 218.0) / 37.0, 0.0, 1.0)
            high_mask = cv2.GaussianBlur(high_mask, (0, 0), 0.8)[:, :, None]
            arr = arr * (1.0 - high_mask * highlight_guard) + original * (high_mask * highlight_guard)
            log.append("Highlight guard: parlak olcum/yazi alanlari patlatilmadi")

        label_guard = float(settings.get("label_guard", 0.92) or 0)
        if label_guard > 0.01:
            label_like = ((gray_u8 > 138) & (hsv[:, :, 1] < 78)).astype(np.uint8)
            label_like = cv2.dilate(label_like, np.ones((2, 2), np.uint8), iterations=1).astype(np.float32)
            label_like = cv2.GaussianBlur(label_like, (0, 0), 0.75)[:, :, None]
            arr = arr * (1.0 - label_like * label_guard) + original * (label_like * label_guard)
            log.append("Yazi/olcum koruma: cihaz yazilari ve markerlar orijinale yakin tutuldu")

        black_guard = float(settings.get("black_guard", 0.88) or 0)
        if black_guard > 0.01:
            black_mask = np.clip((62.0 - gray_u8.astype(np.float32)) / 62.0, 0.0, 1.0)
            black_mask = cv2.GaussianBlur(black_mask, (0, 0), 1.1)[:, :, None]
            arr = arr * (1.0 - black_mask * black_guard) + original * (black_mask * black_guard)
            log.append("Siyah zemin koruma: USG arka plani ve bos alanlar kirletilmedi")

        out = Image.fromarray(np.clip(arr, 0, 255).astype(np.uint8))
        return out, log
    except Exception as ex:
        from PIL import ImageEnhance, ImageFilter, ImageOps
        gray = ImageOps.grayscale(img)
        gray = ImageOps.autocontrast(gray, cutoff=1)
        warm = ImageOps.colorize(gray, black="#050608", mid="#8F5C34", white="#F5C58A")
        out = Image.blend(img, warm, 0.42)
        out = ImageEnhance.Contrast(out).enhance(float(settings.get("contrast", 1.22) or 1.22))
        out = out.filter(ImageFilter.UnsharpMask(radius=1.3, percent=150, threshold=4))
        out = _hd_apply_light_mode(out, settings)
        return out, [f"Premium fallback: OpenCV yok veya hata verdi, PIL motoru kullanildi ({ex})"]


def _hd_apply_diagnostic_safe_usg(img, settings=None):
    """Conservative deterministic USG cleanup. It never generates new anatomy."""
    from PIL import Image
    settings = settings or {}
    img = img.convert("RGB")
    log = [
        "Tanisal guvenli mod: generative model kullanilmadi; orijinal degismeden kopya uretildi"
    ]
    try:
        import cv2
        import numpy as np
        arr0 = np.array(img).astype(np.uint8)
        gray0 = cv2.cvtColor(arr0, cv2.COLOR_RGB2GRAY)

        # Preserve black background, device labels and bright measurement text.
        black_mask = np.clip((58.0 - gray0.astype(np.float32)) / 58.0, 0.0, 1.0)
        black_mask = cv2.GaussianBlur(black_mask, (0, 0), 1.1)[:, :, None]
        label_mask = ((gray0 > 136) & (cv2.cvtColor(arr0, cv2.COLOR_RGB2HSV)[:, :, 1] < 82)).astype(np.float32)
        label_mask = cv2.dilate(label_mask, np.ones((2, 2), np.uint8), iterations=1)
        label_mask = cv2.GaussianBlur(label_mask, (0, 0), 0.8)[:, :, None]
        high_mask = np.clip((gray0.astype(np.float32) - 222.0) / 32.0, 0.0, 1.0)
        high_mask = cv2.GaussianBlur(high_mask, (0, 0), 0.8)[:, :, None]
        protect = np.clip(black_mask * 0.94 + label_mask * 0.92 + high_mask * 0.72, 0.0, 0.96)

        filtered = cv2.bilateralFilter(arr0, 5, 32, 24).astype(np.float32)
        arr = arr0.astype(np.float32) * 0.56 + filtered * 0.44
        log.append("Speckle azaltma: bilateral filtre ile USG grenleri kontur ezmeden yumusatildi")

        lab = cv2.cvtColor(np.clip(arr, 0, 255).astype(np.uint8), cv2.COLOR_RGB2LAB)
        l_chan, a_chan, b_chan = cv2.split(lab)
        clahe = cv2.createCLAHE(clipLimit=1.85, tileGridSize=(8, 8))
        l2 = clahe.apply(l_chan)
        l_chan = cv2.addWeighted(l_chan, 0.54, l2, 0.46, 0)
        arr = cv2.cvtColor(cv2.merge((l_chan, a_chan, b_chan)), cv2.COLOR_LAB2RGB).astype(np.float32)
        log.append("Lokal kontrast: CLAHE ile gri skala okunurlugu kontrollu artirildi")

        blur = cv2.GaussianBlur(arr, (0, 0), 1.05)
        arr = arr + (arr - blur) * 0.34
        log.append("Netlik: olcum cizgilerini koruyan hafif unsharp mask uygulandi")

        arr = ((arr - 127.5) * 1.08) + 127.5
        arr *= 1.02
        arr = arr * (1.0 - protect) + arr0.astype(np.float32) * protect
        log.append("Koruma: siyah zemin, cihaz yazilari ve parlak markerlar orijinale yakin tutuldu")

        return Image.fromarray(np.clip(arr, 0, 255).astype(np.uint8)), log
    except Exception as ex:
        from PIL import ImageEnhance, ImageFilter, ImageOps
        gray = ImageOps.grayscale(img)
        gray = ImageOps.autocontrast(gray, cutoff=1)
        safe = ImageEnhance.Contrast(gray.convert("RGB")).enhance(1.12)
        safe = safe.filter(ImageFilter.UnsharpMask(radius=1.1, percent=92, threshold=5))
        log.append(f"Guvenli fallback: OpenCV yok veya hata verdi, PIL motoru kullanildi ({ex})")
        return safe, log


def _hd_apply_professional_ultrasound_tools(img, settings=None):
    """Apply neutral-by-default professional USG editor controls."""
    from PIL import Image
    settings = settings or {}
    log = []

    def f(name, default):
        try:
            return float(settings.get(name, default))
        except Exception:
            return float(default)

    values = {
        "level_black": f("level_black", 0),
        "level_white": f("level_white", 255),
        "midtone": f("midtone", 1.0),
        "dynamic_range": f("dynamic_range", 1.0),
        "tgc_near": f("tgc_near", 1.0),
        "tgc_mid": f("tgc_mid", 1.0),
        "tgc_far": f("tgc_far", 1.0),
        "lateral_gain": f("lateral_gain", 1.0),
        "clahe_clip": f("clahe_clip", 0.0),
        "bilateral_strength": f("bilateral_strength", 0.0),
        "median_despeckle": f("median_despeckle", 0.0),
        "pro_sharpen": f("pro_sharpen", 0.0),
        "pro_sharpen_radius": f("pro_sharpen_radius", 1.2),
        "pro_zoom": f("pro_zoom", 1.0),
        "pro_rotate": f("pro_rotate", 0.0),
        "pro_pan_x": f("pro_pan_x", 0.0),
        "pro_pan_y": f("pro_pan_y", 0.0),
    }
    neutral = (
        abs(values["level_black"]) < 0.01
        and abs(values["level_white"] - 255) < 0.01
        and abs(values["midtone"] - 1.0) < 0.01
        and abs(values["dynamic_range"] - 1.0) < 0.01
        and abs(values["tgc_near"] - 1.0) < 0.01
        and abs(values["tgc_mid"] - 1.0) < 0.01
        and abs(values["tgc_far"] - 1.0) < 0.01
        and abs(values["lateral_gain"] - 1.0) < 0.01
        and values["clahe_clip"] <= 0.01
        and values["bilateral_strength"] <= 0.01
        and values["median_despeckle"] <= 0.01
        and values["pro_sharpen"] <= 0.01
        and abs(values["pro_zoom"] - 1.0) < 0.01
        and abs(values["pro_rotate"]) < 0.01
        and abs(values["pro_pan_x"]) < 0.01
        and abs(values["pro_pan_y"]) < 0.01
    )
    if neutral:
        return img, log

    img = img.convert("RGB")
    try:
        import cv2
        import numpy as np

        original = np.array(img).astype(np.float32)
        arr = original.copy()
        h, w = arr.shape[:2]

        zoom = max(1.0, min(values["pro_zoom"], 3.0))
        rotate = values["pro_rotate"]
        pan_x = values["pro_pan_x"]
        pan_y = values["pro_pan_y"]
        if zoom > 1.01 or abs(rotate) > 0.05 or abs(pan_x) > 0.05 or abs(pan_y) > 0.05:
            center = (w / 2.0 - (pan_x / 100.0) * w, h / 2.0 - (pan_y / 100.0) * h)
            mat = cv2.getRotationMatrix2D(center, rotate, zoom)
            arr = cv2.warpAffine(
                arr, mat, (w, h), flags=cv2.INTER_CUBIC,
                borderMode=cv2.BORDER_CONSTANT, borderValue=(0, 0, 0))
            original = cv2.warpAffine(
                original, mat, (w, h), flags=cv2.INTER_CUBIC,
                borderMode=cv2.BORDER_CONSTANT, borderValue=(0, 0, 0))
            log.append("Geometri: zoom/rotasyon/pan profesyonel edit uygulanmistir")

        gray = cv2.cvtColor(np.clip(original, 0, 255).astype(np.uint8), cv2.COLOR_RGB2GRAY)
        hsv = cv2.cvtColor(np.clip(original, 0, 255).astype(np.uint8), cv2.COLOR_RGB2HSV)
        black_mask = np.clip((58.0 - gray.astype(np.float32)) / 58.0, 0.0, 1.0)
        black_mask = cv2.GaussianBlur(black_mask, (0, 0), 1.1)[:, :, None]
        label_mask = ((gray > 136) & (hsv[:, :, 1] < 82)).astype(np.float32)
        label_mask = cv2.dilate(label_mask, np.ones((2, 2), np.uint8), iterations=1)
        label_mask = cv2.GaussianBlur(label_mask, (0, 0), 0.8)[:, :, None]
        high_mask = np.clip((gray.astype(np.float32) - 222.0) / 32.0, 0.0, 1.0)
        high_mask = cv2.GaussianBlur(high_mask, (0, 0), 0.8)[:, :, None]
        protect = np.clip(
            black_mask * f("black_guard", 0.88)
            + label_mask * f("label_guard", 0.92)
            + high_mask * f("highlight_guard", 0.62),
            0.0, 0.97)

        bilateral = values["bilateral_strength"]
        if bilateral > 0.01:
            filtered = cv2.bilateralFilter(
                np.clip(arr, 0, 255).astype(np.uint8),
                5 if max(w, h) < 1800 else 7,
                18 + int(bilateral * 24),
                15 + int(bilateral * 18)).astype(np.float32)
            alpha = min(0.74, 0.18 + bilateral * 0.22)
            arr = arr * (1.0 - alpha) + filtered * alpha
            log.append("Pro despeckle: bilateral filtre ile gren azaltilip kontur korundu")

        median = values["median_despeckle"]
        if median > 0.01:
            k = 3 if median < 1.35 else 5
            med = cv2.medianBlur(np.clip(arr, 0, 255).astype(np.uint8), k).astype(np.float32)
            alpha = min(0.55, 0.16 + median * 0.18)
            arr = arr * (1.0 - alpha) + med * alpha
            log.append("Median speckle: noktasal USG gurultusu azaltildi")

        black = max(0.0, min(values["level_black"], 120.0))
        white = max(black + 8.0, min(values["level_white"], 255.0))
        mid = max(0.35, min(values["midtone"], 2.4))
        dyn = max(0.45, min(values["dynamic_range"], 2.2))
        if abs(black) > 0.01 or abs(white - 255.0) > 0.01 or abs(mid - 1.0) > 0.01 or abs(dyn - 1.0) > 0.01:
            arr = (arr - black) * (255.0 / max(1.0, white - black))
            arr = np.clip(arr, 0, 255)
            arr = ((arr - 127.5) * dyn) + 127.5
            norm = np.clip(arr / 255.0, 0.0, 1.0)
            arr = np.power(norm, 1.0 / mid) * 255.0
            log.append("Levels: siyah/beyaz nokta, midtone ve dinamik aralik ayarlandi")

        tgc_near = values["tgc_near"]
        tgc_mid = values["tgc_mid"]
        tgc_far = values["tgc_far"]
        lateral = values["lateral_gain"]
        if (abs(tgc_near - 1.0) > 0.01 or abs(tgc_mid - 1.0) > 0.01
                or abs(tgc_far - 1.0) > 0.01 or abs(lateral - 1.0) > 0.01):
            y = np.linspace(0.0, 1.0, h, dtype=np.float32)
            curve = np.interp(y, [0.0, 0.5, 1.0], [tgc_near, tgc_mid, tgc_far])
            curve = curve[:, None, None]
            if abs(lateral - 1.0) > 0.01:
                x = np.linspace(-1.0, 1.0, w, dtype=np.float32)
                lateral_curve = 1.0 + (lateral - 1.0) * (1.0 - np.abs(x))
                curve = curve * lateral_curve[None, :, None]
            arr = arr * curve
            log.append("TGC: yakin/orta/uzak alan gain egrisi uygulandi")

        clahe_clip = values["clahe_clip"]
        if clahe_clip > 0.01:
            lab = cv2.cvtColor(np.clip(arr, 0, 255).astype(np.uint8), cv2.COLOR_RGB2LAB)
            l_chan, a_chan, b_chan = cv2.split(lab)
            clahe = cv2.createCLAHE(clipLimit=max(0.8, clahe_clip), tileGridSize=(8, 8))
            l2 = clahe.apply(l_chan)
            l_chan = cv2.addWeighted(l_chan, 0.50, l2, 0.50, 0)
            arr = cv2.cvtColor(cv2.merge((l_chan, a_chan, b_chan)), cv2.COLOR_LAB2RGB).astype(np.float32)
            log.append("CLAHE: bolgesel kontrast profesyonel USG modu ile artirildi")

        sharpen = values["pro_sharpen"]
        radius = values["pro_sharpen_radius"]
        if sharpen > 0.01:
            blur = cv2.GaussianBlur(arr, (0, 0), max(0.4, radius))
            high = arr - blur
            edge_guard = max(0.0, min(f("edge_guard", 0.55), 1.0))
            edge_mask = 1.0 - (cv2.Canny(gray, 34, 112).astype(np.float32) / 255.0)
            edge_mask = cv2.GaussianBlur(edge_mask, (0, 0), 0.8)[:, :, None]
            arr = arr + high * min(1.4, sharpen * 0.42) * (edge_mask * (1.0 - edge_guard * 0.35) + 0.28)
            log.append("Pro keskinlik: radius/amount kontrollu unsharp mask uygulandi")

        arr = arr * (1.0 - protect) + original * protect
        if protect.max() > 0.02:
            log.append("Pro koruma: siyah zemin, cihaz yazilari ve olcumler maskelendi")
        return Image.fromarray(np.clip(arr, 0, 255).astype(np.uint8)), log
    except Exception as ex:
        from PIL import ImageEnhance, ImageFilter, ImageOps
        out = img
        black = max(0, min(int(values["level_black"]), 120))
        white = max(black + 8, min(int(values["level_white"]), 255))
        if black > 0 or white < 255:
            out = ImageOps.autocontrast(out, cutoff=0)
        if values["pro_sharpen"] > 0.01:
            out = out.filter(ImageFilter.UnsharpMask(
                radius=max(0.4, values["pro_sharpen_radius"]),
                percent=int(80 + values["pro_sharpen"] * 70),
                threshold=3))
        if abs(values["dynamic_range"] - 1.0) > 0.01:
            out = ImageEnhance.Contrast(out).enhance(values["dynamic_range"])
        log.append(f"Pro fallback: OpenCV yok veya hata verdi, PIL araci kullanildi ({ex})")
        return out, log


def _apply_hd_studio_image(img, preset="hd_warm", settings=None):
    from PIL import Image, ImageEnhance, ImageFilter, ImageOps
    img = img.convert("RGB")
    settings = settings or {}
    ops = list(HD_STUDIO_PRESETS.get(preset, HD_STUDIO_PRESETS["hd_warm"])["ops"])
    log = []
    for op in ops:
        if op == "diagnostic_safe":
            safe_img, safe_log = _hd_apply_diagnostic_safe_usg(img, settings)
            img = safe_img
            log.extend(safe_log)
        elif op == "premium_voluson":
            premium, premium_log = _hd_apply_premium_voluson(img, settings)
            img = premium
            log.extend(premium_log)
        elif op == "denoise":
            if settings.get("denoise", 1.0) > 0:
                img = img.filter(ImageFilter.MedianFilter(size=3))
                log.append("Denoise: ince gren ve sikistirma izi azaltildi")
        elif op == "auto_level":
            img = ImageOps.autocontrast(img, cutoff=1)
            img = _hd_apply_gamma(img, settings.get("gamma", 0.96))
            log.append("Auto level: siyah/beyaz seviyesi ve gamma dengelendi")
        elif op == "contrast":
            img = ImageEnhance.Contrast(img).enhance(settings.get("contrast", 1.18))
            log.append("Kontrast: genel kontrast dengelendi")
        elif op == "soft_contrast":
            img = ImageEnhance.Contrast(img).enhance(max(1.05, settings.get("contrast", 1.16)))
            img = ImageEnhance.Brightness(img).enhance(settings.get("brightness", 1.04))
            log.append("Soft contrast: doku ezilmeden kontrast verildi")
        elif op == "usg_contrast":
            gray = ImageOps.grayscale(img)
            gray = ImageOps.autocontrast(gray, cutoff=2)
            img = ImageEnhance.Contrast(gray.convert("RGB")).enhance(1.38)
            log.append("USG kontrast: gri skala ve fetal doku ayrimi guclendirildi")
        elif op == "fetal_surface_tone":
            gray = ImageOps.grayscale(img)
            gray = ImageOps.autocontrast(gray, cutoff=1)
            gray = ImageEnhance.Contrast(gray).enhance(1.18)
            warm = ImageOps.colorize(
                gray, black="#140B07", mid="#8D5B31", white="#F6C78C")
            img = Image.blend(gray.convert("RGB"), warm, 0.68)
            img = ImageEnhance.Brightness(img).enhance(
                settings.get("brightness", 1.06))
            log.append("Fetus HD Live: gri USG dokusu sicak hacim tonuna cevrildi")
        elif op == "fetal_depth_light":
            img = _hd_spot_light(
                img,
                strength=max(0.22, settings.get("light_strength", 0.24)),
                center_x=settings.get("spot_x", 50),
                center_y=settings.get("spot_y", 38),
                size=settings.get("spot_size", 64))
            img = _hd_directional_light(
                img,
                strength=max(0.10, settings.get("light_strength", 0.18) * 0.55),
                angle=settings.get("light_angle", 315))
            img = _hd_vignette(img, max(0.12, settings.get("vignette", 0.16)))
            log.append("Fetus HD Live: merkez isik, kenar golgesi ve hacim hissi eklendi")
        elif op == "warmth":
            img = _hd_apply_warmth(img, settings.get("warmth", 1.10))
            img = ImageEnhance.Color(img).enhance(settings.get("color", 1.08))
            log.append("Sicaklik: HD stÃ¼dyo benzeri ilik ton uygulandi")
        elif op == "directional_light":
            img = _hd_directional_light(
                img, settings.get("light_strength", 0.22),
                settings.get("light_angle", 315))
            log.append("Yonlu isik: acili, yumusak aydinlatma eklendi")
        elif op == "shadow_lift":
            img = ImageEnhance.Brightness(img).enhance(max(1.0, settings.get("brightness", 1.08)))
            log.append("Golgelendirme: koyu alanlar kontrollu acildi")
        elif op == "soft_light":
            img = ImageEnhance.Brightness(img).enhance(1.07)
            img = ImageEnhance.Contrast(img).enhance(1.08)
            log.append("Soft light: yumuÅŸak klinik isik etkisi")
        elif op == "skin_soft":
            soft = img.filter(ImageFilter.SMOOTH_MORE)
            img = Image.blend(img, soft, 0.22)
            log.append("Yumusatma: estetik takip goruntusu icin sertlik azaltildi")
        elif op == "edge_preserve":
            img = img.filter(ImageFilter.UnsharpMask(radius=1.4, percent=105, threshold=4))
            log.append("Kenar koruma: kontur belirginlestirildi")
        elif op == "clarity":
            amount = 120 + int(settings.get("clarity", 1.0) * 70)
            img = img.filter(ImageFilter.UnsharpMask(radius=1.8, percent=amount, threshold=3))
            log.append("Clarity: mikrokontrast ve netlik artirildi")
        elif op == "sharpen":
            img = img.filter(ImageFilter.UnsharpMask(radius=2.0, percent=160, threshold=3))
            log.append("Keskinlik: rapor/baski icin netlik uygulandi")
    before_mode = str((settings or {}).get("light_mode") or "preset").strip().lower()
    extra_vignette = float((settings or {}).get("vignette") or 0)
    premium_light_done = "premium_voluson" in ops
    if not premium_light_done and (before_mode not in ("", "preset", "none") or extra_vignette > 0.01):
        img = _hd_apply_light_mode(img, settings)
        log.append("Isik oyunlari: secilen aci/spot/vinyet sahnesi uygulandi")
    pro_img, pro_log = _hd_apply_professional_ultrasound_tools(img, settings)
    img = pro_img
    log.extend(pro_log)
    return img, log


def _hd_image_vision_b64(img, max_side=1280):
    from io import BytesIO
    import base64
    tmp = img.convert("RGB")
    w, h = tmp.size
    scale = min(1.0, max_side / max(w, h))
    if scale < 1.0:
        tmp = tmp.resize((int(w * scale), int(h * scale)))
    buf = BytesIO()
    tmp.save(buf, format="JPEG", quality=84)
    return base64.b64encode(buf.getvalue()).decode("ascii")


def _ai_hd_studio_recommendation(img_or_frames, kind="image"):
    try:
        vision_choice = _select_ollama_vision_model()
        model = vision_choice.get("model") or ""
        if not model:
            return "", "Kurulu vision model bulunamadi; manuel preset uygulandi."
        images = img_or_frames if isinstance(img_or_frames, list) else [img_or_frames]
        prompt = (
            "Bir kadin dogum USG/medikal estetik goruntu isleme asistani gibi davran. "
            "Bu goruntu icin en uygun preset adini sec: voluson_hd_live_premium, hd_warm, usg_clarity, "
            "fetus_hd_live, soft_portrait, illumination, print_ready. "
            "Sadece kisa gerekceyle yaz. "
            "Tani koyma; sadece goruntu kalitesi, isik, kontrast, sicaklik ve netlik oner.")
        ok, text, _dur = call_ollama(
            prompt, model=model, images=images[:4],
            system=_doctor_ai_system("goruntu kalitesi ve isleme preset secimi"),
            temperature=0.1, max_tokens=600, timeout=180, use_cache=False)
        if not ok:
            return "", text
        folded = _fold_search_text(text)
        for key in HD_STUDIO_PRESETS:
            if key in folded:
                return key, text
        if "fetus" in folded or "fetal" in folded or "bebek" in folded:
            if "hd live" in folded or "voluson" in folded or "3d" in folded:
                return "voluson_hd_live_premium", text
            return "fetus_hd_live", text
        if "usg" in folded or "gri" in folded or "kontrast" in folded:
            return "usg_clarity", text
        if "estetik" in folded or "portre" in folded or "yumus" in folded:
            return "soft_portrait", text
        if "isik" in folded or "aydin" in folded:
            return "illumination", text
        return "hd_warm", text
    except Exception as ex:
        return "", f"YZ preset onerisi alinamadi: {ex}"


def _process_hd_video_bytes(data, filename, preset, settings, max_seconds=18,
                            video_smooth=False):
    import tempfile
    from io import BytesIO
    try:
        import cv2
        from PIL import Image
        import numpy as np
    except Exception as ex:
        raise RuntimeError(f"Video isleme icin opencv/numpy gerekli: {ex}")
    suffix = Path(filename or "video.mp4").suffix or ".mp4"
    in_path = Path(tempfile.gettempdir()) / f"yk_hd_in_{uuid.uuid4().hex}{suffix}"
    out_path = Path(tempfile.gettempdir()) / f"yk_hd_out_{uuid.uuid4().hex}.mp4"
    in_path.write_bytes(data)
    cap = cv2.VideoCapture(str(in_path))
    if not cap.isOpened():
        try:
            in_path.unlink(missing_ok=True)
        except Exception:
            pass
        raise RuntimeError("Video acilamadi.")
    fps = float(cap.get(cv2.CAP_PROP_FPS) or 24.0)
    fps = fps if 1 <= fps <= 120 else 24.0
    width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 0)
    height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0)
    total = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
    max_frames = int(max(1, fps * max(3, min(float(max_seconds or 18), 90))))
    if total > 0:
        max_frames = min(max_frames, total)
    fourcc = cv2.VideoWriter_fourcc(*"mp4v")
    writer = cv2.VideoWriter(str(out_path), fourcc, fps, (width, height))
    if not writer.isOpened():
        cap.release()
        raise RuntimeError("Video cikti dosyasi olusturulamadi.")
    frame_count = 0
    last_log = []
    prev_arr = None
    while frame_count < max_frames:
        ok, frame = cap.read()
        if not ok:
            break
        rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        pil = Image.fromarray(rgb)
        enhanced, last_log = _apply_hd_studio_image(pil, preset, settings)
        arr = cv2.cvtColor(np.array(enhanced), cv2.COLOR_RGB2BGR)
        if video_smooth and prev_arr is not None and prev_arr.shape == arr.shape:
            arr = cv2.addWeighted(arr, 0.84, prev_arr, 0.16, 0)
        if video_smooth:
            prev_arr = arr.copy()
        writer.write(arr)
        frame_count += 1
    cap.release()
    writer.release()
    if frame_count <= 0:
        try:
            in_path.unlink(missing_ok=True)
            out_path.unlink(missing_ok=True)
        except Exception:
            pass
        raise RuntimeError("Video icinden islenebilir kare okunamadi.")
    output = out_path.read_bytes()
    try:
        in_path.unlink(missing_ok=True)
        out_path.unlink(missing_ok=True)
    except Exception:
        pass
    return output, frame_count, fps, last_log


def _normalize_comfyui_base_url(value):
    raw = str(value or "").strip().rstrip("/")
    if not raw:
        return ""
    if not raw.startswith(("http://", "https://")):
        raw = "http://" + raw
    try:
        parsed = urlsplit(raw)
    except Exception:
        return ""
    host = (parsed.hostname or "").strip()
    if not host:
        return ""
    scheme = (parsed.scheme or "http").lower()
    try:
        port = int(parsed.port) if parsed.port else 8188
    except Exception:
        port = 8188
    path = (parsed.path or "").strip().rstrip("/")
    host_token = f"[{host}]" if ":" in host and not host.startswith("[") else host
    return f"{scheme}://{host_token}:{port}{path}"


def _comfyui_is_local_url(url):
    try:
        host = (urlsplit(str(url or "")).hostname or "").strip().lower()
    except Exception:
        return False
    if not host:
        return True
    if host in {"localhost", "127.0.0.1", "::1"}:
        return True
    machine = (os.environ.get("COMPUTERNAME") or "").strip().lower()
    if machine and host == machine:
        return True
    return False


def _comfyui_base_url():
    url = (
        os.environ.get("YAZKLINIK_COMFYUI_URL", "").strip()
        or _db_get_setting("sysparam_comfyui_url", "").strip()
        or "http://127.0.0.1:8188"
    )
    return _normalize_comfyui_base_url(url) or "http://127.0.0.1:8188"


