    return Path(
        os.environ.get("YAZKLINIK_COMFYUI_HOME", "").strip()
        or _db_get_setting("sysparam_comfyui_home", "").strip()
        or r"C:\YazKlinik_AI\ComfyUI"
    ).expanduser()


