def _hd_apply_quick_action(form):
    data = dict(form or {})
    quick = str(data.get("quick_action") or "").strip()
    recipe = HD_STUDIO_QUICK_ACTIONS.get(quick)
    if not recipe:
        return data, quick, None
    data["preset"] = recipe.get("preset", data.get("preset", "hd_warm"))
    data["engine"] = recipe.get("engine", data.get("engine", "local"))
    if recipe.get("checkpoint"):
        data["comfyui_checkpoint"] = recipe["checkpoint"]
    if recipe.get("upscale_model"):
        data["comfyui_upscale_model"] = recipe["upscale_model"]
    data["comfyui_strength"] = recipe.get("strength", "0.22")
    data["comfyui_steps"] = recipe.get("steps", "16")
    data["comfyui_cfg"] = recipe.get("cfg", "5.5")
    data["comfyui_prompt"] = recipe.get("prompt", "")
    data["comfyui_negative"] = recipe.get("negative", "")
    for field, value in (recipe.get("settings") or {}).items():
        data[str(field)] = str(value)
    if recipe.get("upscale"):
        data["hd_upscale_factor"] = recipe["upscale"]
    if recipe.get("intent"):
        data["hd_intent"] = recipe["intent"]
    if recipe.get("clinical_safe"):
        data["clinical_safe"] = recipe["clinical_safe"]
    else:
        data.setdefault("clinical_safe", "on")
    return data, quick, recipe


def _hd_original_preview_b64(raw):
    import base64
    try:
        from PIL import Image
        from io import BytesIO
        img = Image.open(BytesIO(raw)).convert("RGB")
        img.thumbnail((1600, 1600))
        buf = BytesIO()
        img.save(buf, format="PNG", optimize=True)
        return base64.b64encode(buf.getvalue()).decode("ascii")
    except Exception:
        return ""


def _hd_source_kind_hint(source_url="", source_name=""):
    raw_kind = str(request.args.get("kind", "") or "").strip().lower()
    if raw_kind in {"image", "video", "dicom"}:
        return raw_kind
    try:
        path_hint = urlsplit(str(source_url or "")).path
    except Exception:
        path_hint = str(source_url or "")
    ext = Path(str(source_name or path_hint or "")).suffix.lower()
    if ext in VIDEO_EXTS_WEB:
        return "video"
    if ext in DICOM_EXTS_WEB:
        return "dicom"
    return "image"


def _hd_apply_optional_upscale(image_bytes, factor, engine="local",
                               filename="hd_upscale.png",
                               upscale_model=None):
    try:
        factor = max(1.0, min(float(str(factor or 1).replace(",", ".")), 4.0))
    except Exception:
        factor = 1.0
    if factor <= 1.01:
        return image_bytes, []
    if engine == "comfyui":
        try:
            return _run_comfyui_upscale(
                image_bytes, factor, filename=filename,
                model_name=upscale_model)
        except Exception as ex:
            fallback_note = f"ComfyUI upscale basarisiz, yerel buyutme kullanildi: {ex}"
        else:
            fallback_note = ""
    else:
        fallback_note = ""
    from PIL import Image
    from io import BytesIO
    img = Image.open(BytesIO(image_bytes)).convert("RGB")
    w, h = img.size
    img = img.resize((int(w * factor), int(h * factor)), Image.Resampling.LANCZOS)
    buf = BytesIO()
    img.save(buf, format="PNG", optimize=True)
    log = [f"Boyut: {factor:.1f}x LANCZOS buyutme uygulandi"]
    if fallback_note:
        log.insert(0, fallback_note)
    return buf.getvalue(), log


def _run_comfyui_image_enhance(raw, filename, preset, form):
    from io import BytesIO
    from PIL import Image
    status = _comfyui_status(timeout=4, autostart=True)
    if not status.get("online"):
        raise RuntimeError(
            "ComfyUI bagli degil. Server PC'de ComfyUI'yi "
            "python main.py --listen 0.0.0.0 --port 8188 ile acin. "
            f"Detay: {status.get('error')}")
    checkpoint = (form.get("comfyui_checkpoint") or "").strip()
    checkpoint = checkpoint or _comfyui_checkpoint_name()
    inpaint_mode = "inpaint" in checkpoint.lower()
    img = Image.open(BytesIO(raw))
    if inpaint_mode and img.mode in {"RGBA", "LA"}:
        img = img.convert("RGBA")
    else:
        img = img.convert("RGB")
    buf = BytesIO()
    img.save(buf, format="PNG", optimize=True)
    uploaded = _comfyui_upload_image(buf.getvalue(), filename)
    prompt = (form.get("comfyui_prompt") or "").strip()
    if not prompt:
        label = HD_STUDIO_PRESETS.get(
            preset, HD_STUDIO_PRESETS["hd_warm"])["label"]
        prompt = (
            "medical image quality enhancement, clean clinical lighting, "
            "preserve anatomy, preserve original structure, subtle denoise, "
            f"sharp details, {label}")
    negative = (form.get("comfyui_negative") or "").strip()
    if not negative:
        negative = (
            "diagnostic alteration, fake lesion, extra anatomy, distorted text, "
            "cartoon, painting, watermark, overprocessed, hallucinated detail")
    clinical_safe = str((form or {}).get("clinical_safe") or "on").lower() in {
        "1", "on", "true", "yes",
    }
    strength = _hd_float(form, "comfyui_strength", 0.28, 0.05, 0.85)
    if clinical_safe:
        strength = min(strength, 0.32)
        negative = (
            negative + ", hallucination, diagnostic change, altered anatomy, "
            "invented finding")
    steps = int(_hd_float(form, "comfyui_steps", 18, 4, 60))
    cfg = _hd_float(form, "comfyui_cfg", 6.5, 1.0, 14.0)
    grow_mask_by = int(_hd_float(form, "inpaint_mask_grow", 6, 0, 64))
    workflow = _comfyui_img2img_workflow(
        uploaded, prompt, negative, checkpoint,
        strength=strength, steps=steps, cfg=cfg,
        inpaint=inpaint_mode, grow_mask_by=grow_mask_by)
    prompt_id = _comfyui_queue_prompt(workflow)
    output_meta = _comfyui_wait_for_output(
        prompt_id, timeout=int(_hd_float(form, "comfyui_timeout", 240, 30, 900)))
    out = _comfyui_download_image(output_meta)
    log = [
        f"ComfyUI: {status.get('url')}",
        f"Checkpoint: {checkpoint}",
        f"Prompt ID: {prompt_id}",
        f"Strength: {strength:.2f}, steps: {steps}, CFG: {cfg:.1f}",
    ]
    if clinical_safe:
        log.append("Klinik guvenli mod: strength sinirlandi ve anatomi koruma negatifleri eklendi")
    if inpaint_mode:
        log.append(f"Inpaint workflow: alfa maskesi varsa kullanildi, grow_mask_by={grow_mask_by}")
    return out, log, prompt_id


def _openai_extract_image_payload(payload):
    found_b64 = []
    found_urls = []

    def walk(node):
        if isinstance(node, dict):
            for key in ("b64_json", "image_base64", "result"):
                value = node.get(key)
                if isinstance(value, str) and len(value) > 120:
                    found_b64.append(value)
            value = node.get("url")
            if isinstance(value, str) and value.startswith(("http://", "https://")):
                found_urls.append(value)
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(payload)
    if found_b64:
        return "b64", found_b64[0]
    if found_urls:
        return "url", found_urls[0]
    return "", ""


def _run_openai_image_premium_enhance(raw, filename, preset, form):
    import urllib.request as _urllib_req
    import urllib.error as _urllib_err
    import json as _json
    import base64 as _base64
    from io import BytesIO
    from PIL import Image

    form = form or {}
    cfg = _openai_image_config()
    if not cfg.get("api_key"):
        raise RuntimeError(
            "OpenAI API anahtari yok. Ayarlar > Online ChatGPT ekranindan "
            "OPENAI_API_KEY kaydedin veya yerel ucretsiz modlari kullanin.")

    quality = str(
        form.get("openai_image_quality")
        or cfg.get("quality")
        or "medium"
    ).strip().lower()
    if quality not in {"low", "medium", "high", "auto"}:
        quality = "medium"
    accept = str(form.get("cloud_cost_accept") or "").strip().lower()
    if accept not in {"1", "on", "true", "yes"}:
        raise RuntimeError(
            "Premium bulut duzeltme OpenAI API maliyeti olusturabilir "
            f"({_openai_image_estimate_text(quality)}). Devam etmek icin "
            "ucret onay kutusunu isaretleyin.")

    img = Image.open(BytesIO(raw)).convert("RGB")
    img.thumbnail((1536, 1536), Image.Resampling.LANCZOS)
    buf = BytesIO()
    img.save(buf, format="PNG", optimize=True)
    png_bytes = buf.getvalue()
    image_b64 = _base64.b64encode(png_bytes).decode("ascii")
    prompt = (form.get("comfyui_prompt") or "").strip()
    if not prompt:
        label = HD_STUDIO_PRESETS.get(
            preset, HD_STUDIO_PRESETS["hd_warm"])["label"]
        prompt = (
            "YazKlinik premium ultrasound presentation image enhancement.\n"
            f"Preset: {label}.\n"
            "Improve perceived quality, contrast, black background, soft HD Live "
            "lighting and patient-facing clarity. Preserve original anatomy, "
            "fetal/clinical structures, labels, overlays and measurements exactly. "
            "Do not add, remove, invent or diagnose any finding. This output is "
            "only for patient presentation/archive, not for diagnostic decision.")
    negative = (form.get("comfyui_negative") or "").strip()
    if negative:
        prompt += "\nAvoid: " + negative
    payload = {
        "model": cfg.get("main_model") or "gpt-5.5",
        "input": [
            {
                "role": "user",
                "content": [
                    {"type": "input_text", "text": prompt},
                    {
                        "type": "input_image",
                        "image_url": f"data:image/png;base64,{image_b64}",
                    },
                ],
            }
        ],
        "tools": [
            {
                "type": "image_generation",
                "model": cfg.get("image_model") or "gpt-image-2",
                "quality": quality,
                "size": cfg.get("size") or "1024x1024",
                "output_format": "png",
                "action": "edit",
            }
        ],
        "tool_choice": {"type": "image_generation"},
    }
    body = _json.dumps(payload).encode("utf-8")
    req = _urllib_req.Request(
        cfg.get("base_url") or "https://api.openai.com/v1/responses",
        data=body,
        headers={
            "Authorization": f"Bearer {cfg.get('api_key')}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )
    try:
        with _urllib_req.urlopen(req, timeout=int(cfg.get("timeout") or 60)) as resp:
            data = _json.loads(resp.read().decode("utf-8", errors="replace"))
    except _urllib_err.HTTPError as ex:
        detail = ex.read().decode("utf-8", errors="replace")[:1200]
        raise RuntimeError(f"OpenAI gorsel API hatasi: HTTP {ex.code} - {detail}") from ex

    kind, value = _openai_extract_image_payload(data)
    if kind == "b64":
        out = _base64.b64decode(value)
    elif kind == "url":
        with _urllib_req.urlopen(value, timeout=90) as resp:
            out = resp.read()
    else:
        raise RuntimeError(
            "OpenAI yanitinda uretilecek PNG bulunamadi. Model/endpoint "
            "ayarlarini Online ChatGPT ekranindan kontrol edin.")
    return out, [
        "Premium bulut duzeltme: OpenAI Image API kullanildi",
        f"Model: {cfg.get('image_model')} / ana model: {cfg.get('main_model')}",
        f"Kalite: {quality}, tahmini maliyet: {_openai_image_estimate_text(quality)}",
        "Klinik ayrim: sonuc sunum/arsiv kopyasidir; tani icin orijinal USG/DICOM esas alinir",
    ]


def _hd_live_stage_html(source_url, title="", kind="image", eager=False):
    """Fast GPU preview shell for HD Live light tuning."""
    source_attr = safe_attr(source_url)
    title_safe = safe_attr(title or "Secili medya")
    kind = "video" if str(kind or "").lower() == "video" else "image"
    priority = "eager" if eager else "lazy"
    if kind == "video":
        media = (
            f'<video class="yk-hd-live-media" data-hd-live-media '
            f'src="{source_attr}" controls muted playsinline preload="metadata"></video>')
    else:
        media = (
            f'<img class="yk-hd-live-media" data-hd-live-media '
            f'src="{source_attr}" alt="{title_safe}" loading="{priority}" '
            f'decoding="async" fetchpriority="{"high" if eager else "low"}">')
    return f"""
    <div class="yk-hd-live-stage" data-hd-live-stage data-hd-live-kind="{kind}">
      {media}
      <span class="yk-hd-live-layer yk-hd-live-beam"></span>
      <span class="yk-hd-live-layer yk-hd-live-spot"></span>
      <span class="yk-hd-live-layer yk-hd-live-vignette"></span>
      <span class="yk-hd-live-crosshair" aria-hidden="true"></span>
    </div>
    """


def _hd_studio_source_picker_html(patient_key, selected_url="", selected_name=""):
    q_patient = quote(str(patient_key), safe="")
    selected_url = str(selected_url or "").strip()
    selected_name = str(selected_name or "").strip()
    cards = []
    seen = set()

    def _add_card(source_url, title, kind, badge, size_text=""):
        if not source_url:
            return
        key = source_url.split("?", 1)[0].lower()
        if key in seen:
            return
        seen.add(key)
        active = " is-active" if source_url == selected_url else ""
        checked = "checked" if source_url == selected_url else ""
        title_safe = sh(title or "Medya")
        source_attr = safe_attr(source_url)
        title_attr = safe_attr(title or "Medya")
        if kind == "video":
            preview = (
                f'<video src="{source_attr}" muted preload="none" '
                f'playsinline></video>')
        else:
            preview = f'<img src="{source_attr}" loading="lazy" decoding="async" fetchpriority="low" alt="{title_safe}">'
        cards.append(f"""
        <label class="yk-hd-pick-card{active}" data-hd-source-card>
          <input type="radio" name="source_pick" value="{source_attr}"
                 data-title="{title_attr}" data-kind="{safe_attr(kind)}" {checked}>
          <span class="yk-hd-pick-preview">{preview}</span>
          <span class="yk-hd-pick-info">
            <b>{title_safe}</b>
            <small>{sh(badge)}{f' - {sh(size_text)}' if size_text else ''}</small>
          </span>
        </label>
        """)

    archive_rows = _list_archive_media(patient_key=patient_key, limit=120)
    for row in archive_rows:
        kind = row.get("media_kind") or "other"
        if kind not in ("image", "video", "dicom"):
            continue
        mid = row.get("id")
        if not mid:
            continue
        url = f"/hasta/{q_patient}/takip-medya-dosya/{mid}"
        title = row.get("title") or row.get("file_name") or "Hasta medyasi"
        module = MEDIA_MODULE_LABELS.get(row.get("module"), row.get("module") or "Medya")
        phase = MEDIA_PHASE_LABELS.get(row.get("phase"), row.get("phase") or "")
        _add_card(url, title, "video" if kind == "video" else "image",
                  f"Arsiv - {module} {phase}".strip())

    try:
        nas_entries = _scan_patient_nas_media(
            patient_key, max_candidates=180, timeout=4.0)
    except Exception:
        nas_entries = []
    for entry in nas_entries:
        kind = entry.get("kind")
        if kind not in ("image", "video", "dicom"):
            continue
        path = Path(entry.get("path"))
        try:
            rel = path.resolve().relative_to(
                _patient_root_for_nas(patient_key).resolve()).as_posix()
        except Exception:
            continue
        rel_url = quote(rel, safe="/")
        if kind == "dicom":
            url = f"/hasta/{q_patient}/dicom-dosya/{rel_url}"
            card_kind = "image"
            badge = "NAS/DICOM preview"
        else:
            url = f"/hasta/{q_patient}/medya-dosya/{rel_url}"
            card_kind = kind
            badge = "NAS hasta klasoru"
        size_mb = ""
        try:
            size_mb = f"{(int(entry.get('size') or 0) / 1024 / 1024):.1f} MB"
        except Exception:
            pass
        _add_card(url, path.name, card_kind, badge, size_mb)

    if not cards:
        return """
        <div class="yk-hd-picker-empty">
          Bu hastada secilebilir resim/video onizlemesi bulunamadi.
          Medya veya NAS senkronizasyonundan sonra burada otomatik gorunur.
        </div>
        """

    if selected_url:
        initial_kind = _hd_source_kind_hint(selected_url, selected_name)
        initial_preview = _hd_live_stage_html(
            selected_url, selected_name or "Secili medya", initial_kind, eager=True)
    else:
        initial_preview = """
        <div class="yk-hd-live-preview-inner">
          <span>Onizleme alanindan bir resim veya video secin.</span>
        </div>
        """

    return f"""
    <div class="yk-hd-picker">
      <div class="yk-hd-live-preview" id="ykHdLivePreview">
        {initial_preview}
      </div>
      <div class="yk-hd-pick-grid">
        {"".join(cards)}
      </div>
    </div>
    """


