@app.route("/api/yz/sor", methods=["POST"])
@login_required
def api_ai_ask():
    """ğŸŒ Terminal PC'lerin server'dan YZ desteÄŸi almasÄ±nÄ± saÄŸlayan
 JSON API. Hangi PC olursa olsun bu endpoint'i Ã§aÄŸÄ±rarak
 server'daki RTX 5090 + Llama 70B'yi kullanabilir.

 Request: {"question": "...", "context": "...", "patient_key": "..."}
 Response: {"answer": "...", "duration_ms": ...}
 """
    import urllib.request as _urllib_req
    import urllib.error as _urllib_err
    import json as _json
    import time as _t

    try:
        data = request.get_json(force=True) or {}
        question = (data.get("question") or "").strip()
        context = (data.get("context") or "").strip()
        patient_key = (data.get("patient_key") or "").strip()
        temperature = float(data.get("temperature", 0.3))
        model = _select_ollama_model(data.get("model"))

        if not question:
            return {"error": "question gerekli"}, 400

        ctx_parts = []
        if context:
            ctx_parts.append(context)
        if patient_key:
            ctx_parts.append(_patient_context_for_ai(patient_key))
        ctx = "\n\n".join([p for p in ctx_parts if p])

        if ctx:
            full_prompt = f"[BAGLAM]\n{ctx}\n\n[SORU]\n{question}\n\n[CEVAP]"
        else:
            full_prompt = f"[SORU]\n{question}\n\n[CEVAP]"

        ok, answer, duration_ms = call_ollama(
            full_prompt,
            model=model,
            system=_doctor_ai_system("terminal/web klinik soru-cevap"),
            temperature=temperature,
            max_tokens=2400,
            timeout=180,
            use_cache=False)
        if not ok:
            return {
                "error": answer,
                "hint": "Ollama servisi, model adi veya YZ ayarlari kontrol edilmeli.",
            }, 503

        _log_audit("api_ai_call", entity_type="api",
                    patient_key=patient_key or None,
                    details=f"{duration_ms}ms")

        return {
            "answer": answer,
            "duration_ms": duration_ms,
            "model": model,
            "from_pc": request.remote_addr,
        }

    except Exception as ex:
        return {"error": str(ex)}, 500

    try:
        data = request.get_json(force=True) or {}
        question = (data.get("question") or "").strip()
        context = (data.get("context") or "").strip()
        patient_key = (data.get("patient_key") or "").strip()
        model = (data.get("model") or "llama3.1:70b").strip()
        temperature = float(data.get("temperature", 0.3))

        if not question:
            return {"error": "question gerekli"}, 400

        # Hasta baÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸lamÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± (varsa otomatik ekle)
        ctx = context
        if patient_key:
            try:
                demo = load_patient_demographics(patient_key)
                ctx_parts = [
                    f"Hasta: {patient_key}",
                    f"YaÅŸ: {demo.get('age', '?')}",
                ]
                if demo.get("lmp_override"):
                    from datetime import timedelta
                    parts = demo["lmp_override"].split(".")
                    if len(parts) == 3:
                        lmp_dt = datetime(int(parts[2]),
                                             int(parts[1]),
                                             int(parts[0]))
                        ga_w = (datetime.now() - lmp_dt).days // 7
                        ctx_parts.append(f"GA: {ga_w} hafta")
                if demo.get("blood_type"):
                    ctx_parts.append(
                        f"Kan: {demo['blood_type']}")
                if demo.get("medications"):
                    ctx_parts.append(
                        f"Ä°laÃ§: {demo['medications']}")
                ctx = (ctx + " Â· " if ctx else "") + \
                    " Â· ".join(ctx_parts)
            except Exception:
                pass

        # Sistem prompt
        system = (
            "Sen bir kadÄ±n doÄŸum klinik karar destek "
            "asistanÄ±sÄ±n. TÃ¼rkÃ§e cevap ver. KanÄ±ta dayalÄ± "
            "tÄ±p + gÃ¼ncel kÄ±lavuzlarÄ± (ACOG, NICE, RCOG, TJOD) "
            "kullan. Klinik Ã¶neriler kÄ±sa, net olsun. "
            "Asla kesin tanÄ± koyma.")

        full_prompt = (
            f"[SÄ°STEM]\n{system}\n\n"
            f"{f'[BAÄLAM]{chr(10)}{ctx}{chr(10)}{chr(10)}' if ctx else ''}"
            f"[SORU]\n{question}\n\n[CEVAP]")

        start = _t.time()
        payload_obj = {
            "model": model,
            "prompt": full_prompt,
            "stream": False,
            "options": {"temperature": temperature,
                          "num_predict": 2048,
                          "num_ctx": 8192},
        }
        _apply_ollama_think_policy(payload_obj, model)
        payload = _json.dumps(payload_obj).encode("utf-8")

        req = _urllib_req.Request(
            "http://localhost:11434/api/generate",
            data=payload,
            headers={"Content-Type": "application/json"})

        with _urllib_req.urlopen(req, timeout=120) as resp:
            result = _json.loads(resp.read().decode("utf-8"))
            answer = result.get("response", "").strip()

        duration_ms = int((_t.time() - start) * 1000)

        _log_audit("api_ai_call", entity_type="api",
                    patient_key=patient_key or None,
                    details=f"{duration_ms}ms")

        return {
            "answer": answer,
            "duration_ms": duration_ms,
            "model": model,
            "from_pc": request.remote_addr,
        }

    except _urllib_err.URLError as ex:
        return {
            "error": f"Yerel LLM baÄŸlantÄ± hatasÄ±: {ex}",
            "hint": "Ollama servisi Ã§alÄ±ÅŸÄ±yor mu?",
        }, 503
    except Exception as ex:
        return {"error": str(ex)}, 500


@app.route("/api/yz/durum", methods=["GET"])
@login_required
def api_ai_status():
    """ğŸŒ YZ servis durumu - terminal PC'ler kontrol eder.

    B428: Sadece Ollama degil, cloud provider'lar (Claude/OpenAI/DeepSeek/Gemini)
    da kontrol eder - 'online' herhangi biri varsa true.
    """
    force = str(request.args.get("force") or request.args.get("refresh") or "").strip().lower() in {
        "1", "true", "evet", "yes", "force"
    }
    status_data = _ollama_status(force=force, fast=not force)
    models = list(status_data.get("models") or [])
    ollama_online = bool(status_data.get("online"))

    # Fast mode counts configured cloud providers without doing remote network
    # probes. Deep verification is still available with ?force=1 / ?refresh=1.
    if force:
        cloud_status = {}
        for prov in ("openai", "claude", "deepseek", "gemini"):
            try:
                cloud_status[prov] = bool(_b301_cloud_available(prov))
            except Exception:
                cloud_status[prov] = False
        cloud_status = _b301_cloud_badge_status(cloud_status)
    else:
        cloud_status = _b301_cloud_badge_status()

    # Toplam sayim: Ollama model sayisi + aktif cloud provider sayisi
    cloud_active = sum(1 for v in cloud_status.values() if v)
    total = len(models) + cloud_active
    online = ollama_online or any(cloud_status.values())

    return {
        "status": "online" if online else "offline",
        "ollama_online": ollama_online,
        "openai_online": cloud_status.get("openai", False),
        "claude_online": cloud_status.get("claude", False),
        "deepseek_online": cloud_status.get("deepseek", False),
        "gemini_online": cloud_status.get("gemini", False),
        "models": models,
        "count": total,
        "ollama_count": len(models),
        "cloud_count": cloud_active,
        "server": _AI_CONFIG.get("base_url", "localhost:11434"),
        "hint": status_data.get("hint", ""),
        "fast": bool(status_data.get("fast") or not force),
        "cloud_fast_skipped": False,
        "cloud_status_mode": "verified" if force else "configured",
    }


