@app.route("/api/active-patient", methods=["GET"])
@login_required
def api_get_active_patient():
    """En son aktif hastayÄ± dÃ¶ner."""
    from flask import jsonify
    try:
        from yazklinik_common import get_active_patient
        ap = get_active_patient()
        return jsonify(ap or {"empty": True})
    except Exception as ex:
        return jsonify({"error": str(ex)}), 500


@app.route("/api/active-patient/set", methods=["POST"])
@login_required
def api_set_active_patient():
    """Aktif hasta belirle (URL parameter veya JSON)."""
    from flask import jsonify
    try:
        from yazklinik_common import (
            set_active_patient, clean_patient_name)
        data = request.get_json() or request.form
        patient_key = data.get("patient_key", "")
        display_name = data.get("display_name", "")
        source = data.get("source", "manual")

        if not patient_key:
            return jsonify({"error": "patient_key gerekli"}), 400

        # Display name yoksa DB'den ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§ek
        if not display_name:
            try:
                with db_conn() as con:
                    r = con.execute(
                        "SELECT display_name FROM patients "
                        "WHERE folder_key = ?",
                        (patient_key,)).fetchone()
                    if r:
                        display_name = clean_patient_name(r[0])
            except Exception:
                pass

        set_active_patient(
            patient_key, display_name, source)
        return jsonify({
            "ok": True,
            "patient_key": patient_key,
            "display_name": display_name,
        })
    except Exception as ex:
        return jsonify({"error": str(ex)}), 500


@app.route("/api/active-patient/clear", methods=["POST"])
@login_required
def api_clear_active_patient():
    """Aktif hasta temizle."""
    from flask import jsonify
    try:
        from yazklinik_common import clear_active_patient
        clear_active_patient()
        return jsonify({"ok": True})
    except Exception as ex:
        return jsonify({"error": str(ex)}), 500


