def _check_terminal_auth():
    """Terminal kimliÄŸi kontrol - basit token tabanlÄ±."""
    token = request.headers.get("X-Terminal-Token", "")
    expected = os.environ.get("YAZKLINIK_TERMINAL_TOKEN", "").strip()
    return bool(expected) and token == expected


@app.route("/api/terminal/login", methods=["POST"])
def api_terminal_login():
    """Terminal PC'den login - token dÃ¶ner."""
    from flask import jsonify
    data = request.get_json() or {}
    user = data.get("user", "")
    pwd = data.get("password", "")
    terminal_token = os.environ.get("YAZKLINIK_TERMINAL_TOKEN", "").strip()
    if not terminal_token:
        return jsonify({"ok": False, "error": "Terminal token ayarli degil"}), 503

    if user in USERS and USERS[user]["password"] == pwd:
        return jsonify({
            "ok": True,
            "user": user,
            "role": USERS[user]["role"],
            "name": USERS[user].get("name", user),
            "token": terminal_token,
        })
    return jsonify({"ok": False, "error": "HatalÄ± giriÅŸ"}), 401


@app.route("/api/terminal/patients", methods=["GET"])
def api_terminal_patients():
    """Hasta listesi (JSON)."""
    from flask import jsonify
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401

    try:
        limit = request.args.get("limit", "50000")
        patients = _load_patient_listing(limit=limit, include_full_path=True)
    except Exception as ex:
        return jsonify({"error": str(ex)}), 500

    return jsonify({
        "ok": True,
        "count": len(patients),
        "patients": patients,
    })


@app.route("/api/terminal/active-patient", methods=["GET"])
def api_terminal_active_patient():
    """Terminal kabuk icin aktif hasta durumunu dondur."""
    from flask import jsonify
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401
    try:
        from yazklinik_common import get_active_patient
        active = get_active_patient() or {}
        if not active:
            return jsonify({"ok": True, "empty": True})
        active["ok"] = True
        active["empty"] = False
        return jsonify(active)
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/terminal/active-patient/set", methods=["POST"])
def api_terminal_set_active_patient():
    """Terminal kabuktan secilen hastayi web/v1000 aktif hastasi yap."""
    from flask import jsonify
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401
    try:
        from yazklinik_common import set_active_patient, clean_patient_name
        data = request.get_json(silent=True) or {}
        patient_key = str(data.get("patient_key") or "").strip()
        display_name = str(data.get("display_name") or "").strip()
        source = str(data.get("source") or "windows_shell_api").strip()
        if not patient_key:
            return jsonify({"ok": False, "error": "patient_key gerekli"}), 400
        if not display_name:
            try:
                with db_conn() as con:
                    row = con.execute(
                        "SELECT display_name FROM patients WHERE folder_key=?",
                        (patient_key,)).fetchone()
                if row:
                    display_name = clean_patient_name(row[0])
            except Exception:
                display_name = ""
        set_active_patient(patient_key, display_name or patient_key, source)
        return jsonify({
            "ok": True,
            "patient_key": patient_key,
            "display_name": display_name or patient_key,
            "source": source,
        })
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/terminal/active-patient/clear", methods=["POST"])
def api_terminal_clear_active_patient():
    """Terminal kabuktan aktif hastayi temizle."""
    from flask import jsonify
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401
    try:
        from yazklinik_common import clear_active_patient
        clear_active_patient()
        return jsonify({"ok": True})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/terminal/nas-sync", methods=["POST"])
def api_terminal_nas_sync():
    """Terminal PC'den NAS/Data hasta ve dosya indeksini server'da yenile."""
    from flask import jsonify
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401

    data = request.get_json(silent=True) or {}
    result = run_nas_drive_sync(
        watch_folder=data.get("watch_folder") or data.get("nas_root"),
        data_root=data.get("data_root"),
        accepted_prefix=data.get("accepted_prefix"),
        clear_existing=bool(data.get("clear_existing", True)),
        max_dirs=data.get("max_dirs", 10000),
        max_patients=data.get("max_patients", 50000),
        max_visits_per_patient=data.get("max_visits_per_patient", 500),
        max_files_per_visit=data.get("max_files_per_visit", 2000),
    )
    status = 200 if result.get("ok") else (409 if result.get("busy") else 400)
    return jsonify(result), status


@app.route("/api/terminal/patient/<patient_key>", methods=["GET"])
def api_terminal_patient_detail(patient_key):
    """Tek hasta detayÄ±."""
    from flask import jsonify
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401

    try:
        detail = _get_terminal_patient_detail_cached(patient_key)
    except Exception as ex:
        return jsonify({"error": str(ex)}), 500

    return jsonify({"ok": True, "patient": detail})


