def api_terminal_ai_ask():
    """Terminal'den YZ sorusu - server'da Ollama Ã§alÄ±ÅŸÄ±r."""
    from flask import jsonify
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401

    data = request.get_json() or {}
    question = data.get("question", "").strip()
    patient_key = data.get("patient_key", "")
    system_prompt = data.get("system", "")
    try:
        ask_timeout = max(10, min(180, int(data.get("timeout") or 180)))
    except Exception:
        ask_timeout = 180
    try:
        ask_max_tokens = max(64, min(2048, int(data.get("max_tokens") or 2048)))
    except Exception:
        ask_max_tokens = 2048

    if not question:
        return jsonify({"error": "Soru boÅŸ"}), 400

    # Hasta baÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸lamÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± varsa ekle
    context = ""
    if patient_key:
        try:
            demo = load_patient_demographics(patient_key)
            ga_line = ""
            if demo.get("lmp_override"):
                try:
                    parts = demo["lmp_override"].split(".")
                    if len(parts) == 3:
                        lmp_dt = datetime(int(parts[2]),
                                            int(parts[1]),
                                            int(parts[0]))
                        ga_w = ((datetime.now() - lmp_dt).days
                                 // 7)
                        ga_line = f", {ga_w} hafta gebe"
                except Exception:
                    pass
            context = (
                f"[HASTA BÄ°LGÄ°SÄ°]\n"
                f"YaÅŸ: {demo.get('age', '?')}{ga_line}\n"
                f"Mevcut ilaÃ§lar: "
                f"{demo.get('medications', '-')}\n"
                f"Alerji: {demo.get('allergies', '-')}\n"
                f"Kronik hastalÄ±k: "
                f"{demo.get('chronic_conditions', '-')}\n\n"
            )
        except Exception:
            pass

    full_prompt = context + question

    success, answer, duration = call_ollama(
        full_prompt,
        system=(system_prompt or
                "Sen deneyimli bir kadÄ±n doÄŸum uzmanÄ±sÄ±n. "
                "TÃ¼rkÃ§e, klinik ve net cevap ver."),
        temperature=0.3,
        max_tokens=ask_max_tokens,
        timeout=ask_timeout,
    )

    return jsonify({
        "ok": success,
        "answer": answer if success else "",
        "error": "" if success else answer,
        "duration_ms": duration,
    })


