@app.route("/api/terminal/clipboard/import", methods=["POST"])
def api_terminal_clipboard_import():
    """v1000'den clipboard ile yakalanan veriyi hasta dosyasÄ±na iÅŸle."""
    from flask import jsonify
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401

    data = request.get_json() or {}
    patient_key = data.get("patient_key", "").strip()
    parsed = data.get("parsed_data", {})
    raw_text = data.get("raw_text", "")[:5000]

    if not patient_key:
        return jsonify({"ok": False, "error": "patient_key gerekli"})

    # Yeni hasta oluÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸turma isteÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸i mi?
    is_new = patient_key.startswith("__NEW__:")
    if is_new:
        try:
            _, name, tc = patient_key.split(":", 2)
            name = name.strip()
            tc = (tc or "").strip()
            if not name:
                return jsonify({"ok": False,
                                  "error": "Ä°sim boÅŸ"})
            root = get_patient_storage_root()
            patient_key = _build_voluson_patient_key(name, patient_root=root)
            _ensure_patient_folder_identity(
                patient_key, display_name=name,
                note_text="Terminal clipboard aktarimindan olusturuldu.",
                create_first_visit=True)
            demo = load_patient_demographics(patient_key) or {}
            demo["canonical_name"] = name
            digits = re.sub(r"\D+", "", str(tc))
            if digits:
                demo["tc_no"] = digits[:11]
            _clean_name, folder_prefix, _folder_date = _patient_key_name_parts(patient_key)
            if folder_prefix:
                demo["dicom_patient_id"] = folder_prefix
                demo["dicom_accession_prefix"] = folder_prefix
            mwl_name = _person_name_to_family_given(name or _clean_name or patient_key)
            if mwl_name:
                demo["dicom_patient_name"] = mwl_name
            demo["dicom_station_aet"] = VOLUSON_AET
            save_patient_demographics(patient_key, demo)
        except Exception as ex:
            return jsonify({"ok": False,
                              "error": f"Yeni hasta: {ex}"})
    else:
        # Mevcut hastayÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± bul (TC veya folder_key veya isim)
        try:
            with db_conn() as con:
                # ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œnce direkt key
                r = con.execute(
                    "SELECT folder_key FROM patients "
                    "WHERE folder_key = ?",
                    (patient_key,)).fetchone()
                if not r:
                    # ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â°sim ile dene
                    r = con.execute(
                        "SELECT folder_key FROM patients "
                        "WHERE display_name LIKE ? "
                        "OR folder_key LIKE ? LIMIT 1",
                        (f"%{patient_key}%",
                          f"%{patient_key}%")).fetchone()
                if r:
                    patient_key = r[0]
                else:
                    return jsonify({
                        "ok": False,
                        "error": (f"Hasta bulunamadÄ±: "
                                    f"{patient_key}")})
        except Exception:
            pass

    actions_done = []

    # 1. Telefon
    try:
        phones = parsed.get("phones", [])
        if phones:
            decision = _patient_data_suggest_value(
                patient_key, "phone", phones[0],
                source="clipboard_import",
                source_ref="Pano / dis sistem aktarimi",
                confidence=0.68,
                auto_apply_empty=True)
            actions_done.append(
                "Telefon: " + ("onaya alindi" if decision.get("status") == "queued" else str(phones[0])))
    except Exception:
        pass

    # 2. Demografi (yaÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸, doÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸um tarihi)
    try:
        demo_updates = {}
        if parsed.get("age"):
            demo_updates["age"] = str(parsed["age"])
        if parsed.get("dob"):
            demo_updates["birth_date"] = parsed["dob"]
        # TC numarasÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± (varsa demografi iÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§inde tut)
        tcs = parsed.get("tc_numbers", [])
        if tcs:
            demo_updates["tc_no"] = tcs[0]

        if demo_updates:
            try:
                decisions = _patient_data_suggest_demographics(
                    patient_key, demo_updates,
                    source="clipboard_import",
                    source_ref="Pano / dis sistem aktarimi",
                    confidence=0.68,
                    auto_apply_empty=True)
                queued = sum(1 for d in decisions if d.get("status") == "queued")
                actions_done.append(
                    f"Demografi: {len(demo_updates)} alan"
                    + (f" ({queued} onay bekliyor)" if queued else ""))
            except Exception:
                pass
    except Exception:
        pass

    # 3. Tahlil deÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸erleri ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬ÂÃ‚Â¢ lab_results tablosuna
    try:
        labs = parsed.get("lab_values", {})
        if labs:
            with db_conn() as con:
                con.execute("""
                    CREATE TABLE IF NOT EXISTS lab_results (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        patient_key TEXT,
                        test_date TEXT,
                        source TEXT,
                        values_json TEXT,
                        notes TEXT,
                        created_at TEXT
                    )
                """)
                lab_dict = {
                    k: {"value": v["value"]}
                    for k, v in labs.items()}
                con.execute(
                    "INSERT INTO lab_results "
                    "(patient_key, test_date, source, "
                    "values_json, notes, created_at) "
                    "VALUES (?, ?, ?, ?, ?, ?)",
                    (patient_key,
                      datetime.now().strftime("%Y-%m-%d"),
                      parsed.get("source_hint", "clipboard"),
                      json.dumps(lab_dict, ensure_ascii=False),
                      f"Clipboard'dan otomatik aktarÄ±m "
                      f"({parsed.get('source_hint', '?')})",
                      datetime.now().isoformat()))
                con.commit()
                actions_done.append(
                    f"Tahlil: {len(labs)} parametre")
    except Exception as ex:
        actions_done.append(f"Tahlil hatasÄ±: {ex}")

    # 4. USG deÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸erleri ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬ÂÃ‚Â¢ visit notu olarak
    try:
        usgs = parsed.get("usg_values", {})
        if usgs:
            usg_text = "\n".join(
                f" â€¢ {k}: {v.get('value')}"
                for k, v in usgs.items())
            with db_conn() as con:
                con.execute("""
                    CREATE TABLE IF NOT EXISTS visits (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        patient_folder_key TEXT,
                        visit_date TEXT,
                        notes TEXT,
                        examination TEXT,
                        diagnosis TEXT,
                        plan TEXT,
                        created_at TEXT,
                        source TEXT
                    )
                """)
                con.execute(
                    "INSERT INTO visits (patient_folder_key, "
                    "visit_date, notes, examination, "
                    "created_at, source) "
                    "VALUES (?, ?, ?, ?, ?, ?)",
                    (patient_key,
                      datetime.now().strftime("%Y-%m-%d %H:%M"),
                      f"USG bulgularÄ± (clipboard'dan):\n"
                      f"{usg_text}",
                      usg_text,
                      datetime.now().isoformat(),
                      f"clipboard:{parsed.get('source_hint')}"))
                con.commit()
                actions_done.append(f"USG: {len(usgs)} Ã¶lÃ§Ã¼m")
    except Exception:
        pass

    # 5. Ham metni de visit notu olarak ekle (debug/iz)
    if raw_text and len(raw_text) > 100:
        try:
            with db_conn() as con:
                con.execute(
                    "INSERT INTO visits (patient_folder_key, "
                    "visit_date, notes, source, created_at) "
                    "VALUES (?, ?, ?, ?, ?)",
                    (patient_key,
                      datetime.now().strftime("%Y-%m-%d %H:%M"),
                      f"ğŸ“‹ Clipboard iÃ§eriÄŸi "
                      f"({parsed.get('source_hint', '?')})\n\n"
                      f"{raw_text[:3000]}",
                      f"clipboard_raw",
                      datetime.now().isoformat()))
                con.commit()
                actions_done.append("Ham not eklendi")
        except Exception:
            pass

    # 6. YZ ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶zeti tetikle (asenkron, beklenmez)
    try:
        if parsed.get("lab_values") or parsed.get("usg_values"):
            # YZ asenkron ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§aÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸rÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± iÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§in arka plan thread
            def _ai_summarize():
                try:
                    summary_input = {}
                    if parsed.get("lab_values"):
                        summary_input["lab"] = parsed["lab_values"]
                    if parsed.get("usg_values"):
                        summary_input["usg"] = parsed["usg_values"]

                    prompt = (
                        f"AÅŸaÄŸÄ±daki klinik verileri yorumla "
                        f"(2-3 cÃ¼mle Ã¶zet, sonra kritik bulgular):\n"
                        f"{json.dumps(summary_input, ensure_ascii=False, indent=2)}")

                    success, ans, dur = call_ollama(
                        prompt,
                        system=("Sen kadÄ±n doÄŸum uzmanÄ±sÄ±n. "
                                "Klinik veriyi kÄ±sa Ã¶z yorumla."),
                        temperature=0.2,
                        max_tokens=800,
                        timeout=120)

                    if success:
                        with db_conn() as con:
                            con.execute(
                                "INSERT INTO visits "
                                "(patient_folder_key, visit_date, "
                                "notes, source, created_at) "
                                "VALUES (?, ?, ?, ?, ?)",
                                (patient_key,
                                  datetime.now().strftime(
                                    "%Y-%m-%d %H:%M"),
                                  f"ğŸ¤– YZ Yorumu (clipboard verisi)\n\n"
                                  f"{ans}",
                                  "ai_clipboard_summary",
                                  datetime.now().isoformat()))
                            con.commit()
                except Exception:
                    pass

            import threading as _th
            _th.Thread(target=_ai_summarize, daemon=True).start()
            actions_done.append("YZ Ã¶zet tetiklendi (arka plan)")
    except Exception:
        pass

    return jsonify({
        "ok": True,
        "patient_key": patient_key,
        "actions_done": actions_done,
        "imported_at": datetime.now().isoformat(),
    })


@app.route("/api/terminal/patient/find-by-tc",
                   methods=["POST"])
def api_terminal_find_by_tc():
    """TC kimlik numarasÄ±ndan hasta bul."""
    from flask import jsonify
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401

    data = request.get_json() or {}
    tc = (data.get("tc") or "").strip()
    if len(tc) != 11:
        return jsonify({
            "ok": False,
            "error": "11 haneli TC gerekli"})

    try:
        # Demographics tablosunda tc_no alanÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±nÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± ara
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            r = con.execute(
                "SELECT pd.patient_key, p.display_name "
                "FROM patient_demographics pd "
                "LEFT JOIN patients p "
                "ON p.folder_key = pd.patient_key "
                "WHERE pd.key = 'tc_no' AND pd.value = ? "
                "LIMIT 1", (tc,)).fetchone()
            if r:
                return jsonify({
                    "ok": True,
                    "found": True,
                    "patient_key": r["patient_key"],
                    "display_name": r["display_name"],
                })
            else:
                return jsonify({
                    "ok": True,
                    "found": False,
                })
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)})


