@app.route("/api/terminal/stats", methods=["GET"])
def api_terminal_stats():
    """Dashboard istatistikleri."""
    from flask import jsonify
    if not _check_terminal_auth():
        return jsonify({"error": "auth"}), 401

    stats = {"total": 0, "risky": 0, "delivered": 0,
              "today_visits": 0, "today_appts": 0}
    try:
        with db_conn() as con:
            try:
                r = con.execute(
                    "SELECT COUNT(*) FROM patients").fetchone()
                stats["total"] = r[0] if r else 0
            except Exception:
                pass

            try:
                r = con.execute(
                    "SELECT COUNT(DISTINCT patient_key) "
                    "FROM patient_flags WHERE value='1'"
                ).fetchone()
                stats["risky"] = r[0] if r else 0
            except Exception:
                pass

            try:
                r = con.execute(
                    "SELECT COUNT(*) FROM deliveries"
                ).fetchone()
                stats["delivered"] = r[0] if r else 0
            except Exception:
                pass

            today = datetime.now().strftime("%Y-%m-%d")
            try:
                r = con.execute(
                    "SELECT COUNT(*) FROM visits "
                    "WHERE visit_date LIKE ?",
                    (f"{today}%",)).fetchone()
                stats["today_visits"] = r[0] if r else 0
            except Exception:
                pass

            try:
                r = con.execute(
                    "SELECT COUNT(*) FROM appointments "
                    "WHERE date_time LIKE ?",
                    (f"{today}%",)).fetchone()
                stats["today_appts"] = r[0] if r else 0
            except Exception:
                pass
    except Exception:
        pass

    return jsonify({"ok": True, "stats": stats})


