@app.route("/api/ai/provider", methods=["GET", "POST"])
@login_required
def api_ai_provider():
    """Read/update the app-wide AI engine choice."""
    if request.method == "POST":
        if session.get("role") != "doktor":
            return jsonify({"ok": False, "error": "Sadece doktor."}), 403
        data = request.get_json(silent=True) or request.form or {}
        provider = str(data.get("provider") or data.get("ai_provider") or "").strip().lower()
        if provider in {"chatgpt", "gpt", "open_ai"}:
            provider = "openai"
        if provider in {"bulut", "cloud_only", "online_ai"}:
            provider = "online"
        if provider not in _AI_PROVIDER_VALUES:
            return jsonify({
                "ok": False,
                "error": "Gecersiz YZ saglayici.",
                "allowed": sorted(_AI_PROVIDER_VALUES),
            }), 400
        _db_set_setting("sysparam_ai_provider", provider)
        _refresh_ai_config()
        _ai_runtime_caches_clear()
    provider = _ai_provider_value()
    try:
        ollama_status = _ollama_status(force=False, fast=True)
    except Exception as ex:
        ollama_status = {"online": False, "hint": str(ex), "models": []}
    try:
        cloud_status = _b301_cloud_badge_status()
    except Exception:
        cloud_status = {}
    prefer_cloud = provider in ({"online", "cloud", "cloud_first"} | _AI_CLOUD_PROVIDERS)
    active_provider = _ai_strategy_pick_active_provider(
        images=False, prefer_cloud=prefer_cloud)
    return jsonify({
        "ok": bool(active_provider),
        "provider": provider,
        "provider_label": _ai_provider_display_label(provider),
        "active_provider": active_provider,
        "active_label": _ai_provider_display_label(active_provider),
        "strict_online": _ai_provider_is_strict_online(provider),
        "ollama_online": bool(ollama_status.get("online")),
        "ollama_url": ollama_status.get("url", _AI_CONFIG.get("url", "")),
        "ollama_model_count": int(ollama_status.get("count") or 0),
        "cloud_ready": cloud_status,
        "cloud_ready_count": len([v for v in cloud_status.values() if v]),
    })


def _save_ollama_url_setting(url):
    url = _normalize_ollama_generate_url(url)
    if not url:
        return False
    try:
        with db_conn() as con:
            con.execute(
                "INSERT OR REPLACE INTO settings(key, value) VALUES(?, ?)",
                ("sysparam_ollama_url", url))
            con.commit()
        _set_ai_ollama_url(url, source="settings")
        _OLLAMA_STATUS_CACHE["ts"] = 0
        _OLLAMA_STATUS_CACHE["data"] = None
        return True
    except Exception:
        return False


