_BULUTKLINIK_SETTING_KEYS = {
    "api_client_id": "bulutklinik_api_client_id",
    "api_secret_key": "bulutklinik_api_secret_key",
    "api_user_name": "bulutklinik_api_user_name",
    "api_user_password": "bulutklinik_api_user_password",
    "base_url": "bulutklinik_base_url",
}
_BULUTKLINIK_CLIENT_CACHE = {"client": None, "fingerprint": ""}
_BULUTKLINIK_CLIENT_LOCK = threading.Lock()


def _bulutklinik_load_credentials():
    from yazklinik_bulutklinik_client import (
        BulutklinikCredentials, DEFAULT_BASE_URL)
    data = {}
    for field, key in _BULUTKLINIK_SETTING_KEYS.items():
        data[field] = _db_get_setting(key, "")
    if not (data.get("base_url") or "").strip():
        data["base_url"] = DEFAULT_BASE_URL
    return BulutklinikCredentials(**data)


def _bulutklinik_save_credentials(form):
    """form: dict-like. Bos gelen sifre/secret degerleri mevcut degeri korur."""
    current = _bulutklinik_load_credentials()
    incoming = {}
    for field in _BULUTKLINIK_SETTING_KEYS:
        if field in form and form.get(field) is not None:
            value = str(form.get(field) or "").strip()
            if not value and field in {"api_secret_key", "api_user_password"}:
                value = getattr(current, field, "")
            incoming[field] = value
        else:
            incoming[field] = getattr(current, field, "")
    if not (incoming.get("base_url") or "").strip():
        from yazklinik_bulutklinik_client import DEFAULT_BASE_URL
        incoming["base_url"] = DEFAULT_BASE_URL
    for field, key in _BULUTKLINIK_SETTING_KEYS.items():
        _db_set_setting(key, incoming.get(field, ""))
    with _BULUTKLINIK_CLIENT_LOCK:
        _BULUTKLINIK_CLIENT_CACHE["client"] = None
        _BULUTKLINIK_CLIENT_CACHE["fingerprint"] = ""
    return _bulutklinik_load_credentials()


def _bulutklinik_credentials_fingerprint(creds):
    return "|".join([
        str(getattr(creds, "api_client_id", "")),
        str(getattr(creds, "api_secret_key", "")),
        str(getattr(creds, "api_user_name", "")),
        str(getattr(creds, "api_user_password", "")),
        str(getattr(creds, "base_url", "")),
    ])


def _bulutklinik_get_client(force_login=False):
    from yazklinik_bulutklinik_client import BulutklinikClient
    creds = _bulutklinik_load_credentials()
    if not creds.is_complete():
        return None, creds
    fingerprint = _bulutklinik_credentials_fingerprint(creds)
    with _BULUTKLINIK_CLIENT_LOCK:
        cached = _BULUTKLINIK_CLIENT_CACHE.get("client")
        if cached and _BULUTKLINIK_CLIENT_CACHE.get("fingerprint") == fingerprint:
            client = cached
        else:
            client = BulutklinikClient(creds)
            _BULUTKLINIK_CLIENT_CACHE["client"] = client
            _BULUTKLINIK_CLIENT_CACHE["fingerprint"] = fingerprint
    if force_login:
        client.login()
    return client, creds


_BULUTKLINIK_UUID_RE = re.compile(
    r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}"
    r"-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")
_BULUTKLINIK_EMAIL_RE = re.compile(
    r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$")


def _bulutklinik_validate_credentials(creds):
    """4 alanlik credential setini denetle. Iki kategori:
        errors: login denemesini engelleyen sorunlar
        warnings: login denenebilir ama olasi typo
    Devir notundaki 'hakanyaz27@gmail.com1' typo'sunu yakalamak icin
    e-posta sonundaki tek rakami isaretliyoruz.
    """
    errors = []
    warnings = []

    cid = str(getattr(creds, "api_client_id", "") or "").strip()
    if not cid:
        errors.append({"field": "api_client_id",
                       "message": "API Client ID bos."})
    elif not _BULUTKLINIK_UUID_RE.match(cid):
        # UYARI - HATA degil. BulutKlinik bazen UUID disi format kullanir,
        # son karari API'ye birakiyoruz. Login denemesini bloke etmiyoruz.
        warnings.append({"field": "api_client_id",
                         "message": ("API Client ID UUID formatinda gorunmuyor. "
                                     "BulutKlinik panelinde 'API erisim "
                                     "bilgileri' bolumunden tam degerini kopyalayin. "
                                     "Tipik format: 0a1b2c3d-4e5f-6789-abcd-0123456789ab")})

    secret = str(getattr(creds, "api_secret_key", "") or "")
    if not secret.strip():
        errors.append({"field": "api_secret_key",
                       "message": "API Secret Key bos."})
    elif len(secret.strip()) < 16:
        warnings.append({"field": "api_secret_key",
                         "message": ("Secret cok kisa gorunuyor "
                                     f"({len(secret.strip())} karakter). "
                                     "BulutKlinik panelinden 'API erisim "
                                     "bilgileri'ni tekrar kontrol edin.")})

    user = str(getattr(creds, "api_user_name", "") or "").strip()
    if not user:
        errors.append({"field": "api_user_name",
                       "message": "API kullanici adi (e-posta) bos."})
    else:
        if "@" not in user:
            errors.append({"field": "api_user_name",
                           "message": ("Kullanici adi e-posta formatinda "
                                       "olmali.")})
        elif not _BULUTKLINIK_EMAIL_RE.match(user):
            warnings.append({"field": "api_user_name",
                             "message": "E-posta formati standart disi."})
        # 'hakanyaz27@gmail.com1' gibi: TLD'den sonra tek rakam supheli
        m = re.match(r"^(.*?@[^@\s]+?\.[A-Za-z]{2,})(\d)$", user)
        if m:
            warnings.append({
                "field": "api_user_name",
                "message": (f"E-postanin sonunda fazladan rakam var "
                            f"('{m.group(2)}'). '{m.group(1)}' olmali "
                            f"olabilir. Login basarisizsa bu rakami silin.")
            })

    pwd = str(getattr(creds, "api_user_password", "") or "")
    if not pwd:
        errors.append({"field": "api_user_password",
                       "message": "API sifresi bos."})
    elif len(pwd) < 4:
        warnings.append({"field": "api_user_password",
                         "message": "Sifre cok kisa gorunuyor."})

    base = str(getattr(creds, "base_url", "") or "").strip()
    if not base:
        warnings.append({"field": "base_url",
                         "message": ("Base URL bos. Varsayilan "
                                     "https://api.bulutklinik.com kullanilacak.")})
    elif not (base.startswith("http://") or base.startswith("https://")):
        errors.append({"field": "base_url",
                       "message": "Base URL http:// veya https:// ile baslamali."})
    elif base.startswith("http://"):
        warnings.append({"field": "base_url",
                         "message": ("HTTP kullaniliyor. KVKK acisindan "
                                     "HTTPS onerilir.")})

    return {"ok": not errors, "errors": errors, "warnings": warnings,
            "configured": creds.is_complete()}


def _bulutklinik_audit(action, ok, detail="", entity_id=""):
    try:
        _log_audit(
            action=f"bulutklinik:{action}",
            entity_type="integration",
            entity_id=str(entity_id or ""),
            details=("OK " if ok else "ERR ") + str(detail or "")[:500],
        )
    except Exception:
        pass


def _bulutklinik_jsonify_error(ex):
    from yazklinik_bulutklinik_client import (
        BulutklinikAuthError, BulutklinikError)
    if isinstance(ex, BulutklinikAuthError):
        code = 401
    elif isinstance(ex, BulutklinikError):
        code = int(getattr(ex, "status_code", 0) or 502) or 502
        if code < 400 or code >= 600:
            code = 502
    else:
        code = 500
    payload = {
        "ok": False,
        "error": str(ex) or "BulutKlinik hata",
    }
    api_payload = getattr(ex, "payload", None)
    if api_payload is not None:
        payload["api_payload"] = api_payload
    return jsonify(payload), code


