@app.route("/api/bulutklinik/cookie/export/<int:cid>", methods=["GET"])
@login_required
def api_bulutklinik_cookie_export(cid):
    """BulutKlinik kategori indir (cid 0..7). Direkt dosya dondurur."""
    try:
        import yazklinik_bulutklinik_cookie_client as _bkc
        cl = _bkc.get_client()
        if not cl:
            return jsonify({"ok": False, "error": "cookie yok"}), 503
        res = cl.export_category(cid)
        if not res.get("ok"):
            return jsonify(res), 500
        from flask import Response
        fn = res["filename"]
        # ASCII fallback icin (Content-Disposition)
        safe_fn = re.sub(r'[^\w\-_.]', '_', fn) or f"export_{cid}.bin"
        return Response(
            res["content"],
            mimetype=res["content_type"],
            headers={
                "Content-Disposition": (
                    f'attachment; filename="{safe_fn}"; '
                    f"filename*=UTF-8''{quote(fn)}"),
                "Content-Length": str(res["size"]),
            })
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/bulutklinik/cookie/export-all", methods=["POST"])
@login_required
def api_bulutklinik_cookie_export_all():
    """8 kategoriyi indir + lokal klasore kaydet + ZIP olarak dondur."""
    try:
        import yazklinik_bulutklinik_cookie_client as _bkc
        cl = _bkc.get_client()
        if not cl:
            return jsonify({"ok": False, "error": "cookie yok"}), 503
        import datetime as _dt
        stamp = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
        out_dir = rf"D:\YazKlinik_Final_D300\bk_exports\{stamp}"
        result = cl.export_all(out_dir)
        # ZIP'le
        import zipfile, io as _io, os as _os
        buf = _io.BytesIO()
        with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
            for f in result["files"]:
                if f.get("ok") and _os.path.exists(f["path"]):
                    zf.write(f["path"], arcname=f["filename"])
        from flask import Response
        return Response(
            buf.getvalue(),
            mimetype="application/zip",
            headers={
                "Content-Disposition":
                    f'attachment; filename="bulutklinik_export_{stamp}.zip"',
                "X-BK-Out-Dir": out_dir,
                "X-BK-File-Count": str(result["count"]),
                "X-BK-Total-Bytes": str(result["total_bytes"]),
            })
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/bulutklinik/cookie/export-status", methods=["GET"])
@login_required
def api_bulutklinik_cookie_export_status():
    """Mevcut export klasorlerini listele (gecmis)."""
    try:
        import os as _os
        base = r"D:\YazKlinik_Final_D300\bk_exports"
        if not _os.path.exists(base):
            return jsonify({"ok": True, "exports": []})
        exports = []
        for d in sorted(_os.listdir(base), reverse=True)[:20]:
            dp = _os.path.join(base, d)
            if not _os.path.isdir(dp):
                continue
            files = []
            total = 0
            for fn in sorted(_os.listdir(dp)):
                fp = _os.path.join(dp, fn)
                sz = _os.path.getsize(fp)
                files.append({"name": fn, "size": sz})
                total += sz
            exports.append({"timestamp": d, "files": files,
                            "count": len(files), "total_bytes": total})
        return jsonify({"ok": True, "exports": exports})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


