@app.route("/api/bk-voluson/auto-confirm", methods=["POST"])
@login_required
def api_bk_voluson_auto_confirm():
    """1 aday + score=1.0 (exact match) olan tum eslesmeleri otomatik kaydet.
    Sadece sayfada gosterilen tarih filtresine giren hastalar uzerinde calisir."""
    days_raw = request.args.get("days", "90")
    try:
        days = None if days_raw in ("all", "0", "") else int(days_raw)
    except ValueError:
        days = 90
    try:
        data = _bk_voluson_compute_candidates(days=days)
        import datetime as _dt
        now = _dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        user = str(session.get("user") or "")
        con = _alex_db_conn()
        _bk_voluson_ensure_schema(con)
        linked, skipped = 0, 0
        for row in data["rows"]:
            if row["linked"]:
                skipped += 1
                continue
            cs = row["candidates"]
            if len(cs) == 1 and cs[0]["score"] >= 0.99:
                con.execute("""
                    INSERT INTO bk_voluson_links (bk_hasta_no, folder_key,
                        match_kind, confidence, matched_at, matched_by, note)
                    VALUES (?,?,?,?,?,?,?)
                    ON CONFLICT(bk_hasta_no) DO NOTHING
                """, (row["bk_hasta_no"], cs[0]["folder_key"], "auto",
                      cs[0]["score"], now, user, "auto-confirm: 1 exact"))
                linked += 1
            else:
                skipped += 1
        con.commit()
        con.close()
        return jsonify({"ok": True, "linked": linked, "skipped": skipped})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


