@app.route("/api/bulutklinik/randevu/olustur", methods=["POST"])
@login_required
def api_bulutklinik_reservation_create():
    if str(session.get("role") or "") not in {"doktor", "asistan"}:
        return jsonify({"ok": False, "error": "Yetki yok"}), 403
    client, _ = _bulutklinik_get_client()
    if not client:
        return jsonify({"ok": False, "error": "Credentials eksik"}), 400
    body = request.get_json(silent=True) or {}
    if not body or not isinstance(body, dict):
        return jsonify({"ok": False, "error": "Randevu icin gorev/hasta verisi gerekli"}), 400
    try:
        data = client.reservation(body)
    except Exception as ex:
        _bulutklinik_audit("randevu.create", False, str(ex))
        return _bulutklinik_jsonify_error(ex)
    _bulutklinik_audit("randevu.create", True, "reservation ok")
    return jsonify({"ok": True, "data": data})


