def _enabiz_normalize_date(value: str) -> str:
    """'12.05.2026' / '2026-05-12' / '12/05/26' -> 'YYYY-MM-DD'."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%d-%m-%Y",
                "%Y/%m/%d", "%d.%m.%y", "%d/%m/%y"):
        try:
            return datetime.strptime(raw, fmt).strftime("%Y-%m-%d")
        except Exception:
            continue
    return ""


def _enabiz_apply_randevu(patient_key: str, records: list,
                          transfer_id: str) -> dict:
    """Secili randevu kayitlarini appointments tablosuna her kayda bir satir olarak ekle."""
    if not records:
        return {"count": 0, "appointment_ids": []}
    user = session.get("user", "?") if has_request_context() else "system"
    now_iso = datetime.now().isoformat(sep=" ", timespec="seconds")
    appt_ids = []
    summary = []
    with db_conn() as con:
        for rec in records:
            try:
                rec = rec or {}
                appt_date = _enabiz_normalize_date(rec.get("tarih") or "")
                if not appt_date:
                    continue
                appt_time = str(rec.get("saat") or "").strip() or "09:00"
                kurum = str(rec.get("kurum") or "").strip()
                bolum = str(rec.get("bolum") or "").strip()
                purpose = "e-Nabiz randevu aktarimi"
                note_bits = [transfer_id]
                if kurum:
                    note_bits.append(kurum)
                if bolum:
                    note_bits.append(bolum)
                note = "e-Nabiz: " + " / ".join(b for b in note_bits if b)
                cur = con.execute(
                    "INSERT INTO appointments("
                    "patient_key, appointment_date, appointment_time, "
                    "purpose, note, status, created_by, created_at) "
                    "VALUES(?,?,?,?,?,?,?,?)",
                    (patient_key, appt_date, appt_time, purpose, note,
                     "planned", user, now_iso))
                appt_ids.append(int(cur.lastrowid or 0))
                summary.append(f"{appt_date} {appt_time} {kurum}".strip())
            except Exception as ex:
                print(f"enabiz randevu insert: {ex}")
                continue
        con.commit()
    return {"count": len(appt_ids), "appointment_ids": appt_ids,
            "summary": summary}


def _enabiz_match_candidates(extracted_demographics, limit=5):
    demo = dict(extracted_demographics or {})
    tc = re.sub(r"\D", "", str(demo.get("tc_no") or ""))
    phone = re.sub(r"\D", "", str(demo.get("phone") or ""))
    name = str(demo.get("patient_name") or "").strip()
    rows = []
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            seen = set()
            queries = []
            if tc and len(tc) >= 8:
                queries.append((
                    "SELECT folder_key, display_name FROM patients "
                    "WHERE folder_key LIKE ? OR display_name LIKE ? LIMIT 10",
                    (f"%{tc}%", f"%{tc}%")))
            if phone and len(phone) >= 9:
                queries.append((
                    "SELECT folder_key, display_name FROM patients "
                    "WHERE folder_key LIKE ? LIMIT 10",
                    (f"%{phone[-10:]}%",)))
            if name:
                tokens = [t for t in re.split(r"\s+", name) if len(t) >= 3]
                for tok in tokens[:3]:
                    queries.append((
                        "SELECT folder_key, display_name FROM patients "
                        "WHERE display_name LIKE ? LIMIT 10",
                        (f"%{tok}%",)))
            for sql, args in queries:
                try:
                    for row in con.execute(sql, args).fetchall():
                        key = row.get("folder_key")
                        if not key or key in seen:
                            continue
                        seen.add(key)
                        rows.append(row)
                except Exception:
                    continue
    except Exception:
        return []
    from yazklinik_enabiz_agent import score_patient_match, confidence_label
    scored = []
    for r in rows:
        score, reasons = score_patient_match(r, demo)
        if score <= 0:
            continue
        scored.append({
            "folder_key": r.get("folder_key"),
            "display_name": r.get("display_name") or r.get("folder_key"),
            "score": round(score, 3),
            "confidence": confidence_label(score),
            "reasons": reasons,
        })
    scored.sort(key=lambda x: x["score"], reverse=True)
    return scored[:limit]


def _enabiz_lab_safe_demographics(demo, records, report_type=""):
    """Lab-only PDFs should not offer obstetric fields guessed from table text."""
    demo = dict(demo or {})
    records = records or {}
    if report_type in ("obstetric", "gynecologic"):
        return demo
    if not records.get("tahlil"):
        return demo
    allowed = {
        "patient_name", "canonical_name", "full_name", "ad_soyad", "name",
        "tc_no", "phone", "birth_date", "age", "blood_type", "rh_factor",
        "weight", "height", "bmi", "pre_pregnancy_weight",
    }
    return {k: v for k, v in demo.items() if k in allowed and v not in ("", None)}


