@app.route("/api/enabiz/upload", methods=["POST"])
@login_required
def api_enabiz_upload():
    upload = request.files.get("pdf") or request.files.get("file")
    if not upload or not getattr(upload, "filename", ""):
        return jsonify({"ok": False, "error": "PDF dosyasi gerekli (form alani: 'pdf')"}), 400
    started = time.time()
    try:
        name, size, text, raw_bytes = _enabiz_extract_pdf_text(upload)
    except Exception as ex:
        _enabiz_audit("upload.parse", False, str(ex), entity_id=str(getattr(upload, "filename", "")))
        return jsonify({"ok": False, "error": str(ex)}), 400

    from yazklinik_enabiz_agent import (
        build_candidate_payload, detect_enabiz_signature,
        extract_enabiz_records)

    signature = detect_enabiz_signature(text)
    pdf_payload = _yk_extract_patient_pdf_payload([{
        "name": name,
        "path": "",
        "mtime": time.time(),
        "text": text,
    }])
    elapsed_ms = int((time.time() - started) * 1000)
    candidate = build_candidate_payload(
        pdf_payload, name, size, elapsed_ms, signature)
    candidate["records"] = extract_enabiz_records(text, source=name)
    candidate["report_type"] = _detect_report_type_from_text(text)
    candidate["demographics"] = _enabiz_lab_safe_demographics(
        candidate.get("demographics") or {},
        candidate.get("records") or {},
        candidate.get("report_type") or "")
    candidate["match_candidates"] = _enabiz_match_candidates(
        candidate.get("demographics") or {}, limit=5)

    transfer_id = uuid.uuid4().hex
    pdf_path = _enabiz_persist_pdf(transfer_id, raw_bytes, name)
    candidate["transfer_id"] = transfer_id
    candidate["pdf_path"] = pdf_path

    try:
        _enabiz_ensure_audit_schema()
        with db_conn() as con:
            con.execute(
                "INSERT INTO enabiz_audit("
                "transfer_id, file_name, file_size, pdf_path, status, "
                "created_by, created_at, candidate_json, "
                "signature_is_enabiz) "
                "VALUES(?,?,?,?,?,?,?,?,?)",
                (transfer_id, name, int(size or 0), pdf_path, "candidate",
                 session.get("user", "?"),
                 datetime.now().isoformat(sep=" ", timespec="seconds"),
                 json.dumps(candidate, ensure_ascii=False),
                 1 if signature.get("is_enabiz") else 0))
            con.commit()
    except Exception as ex:
        _enabiz_audit("upload.persist", False, str(ex), entity_id=name)

    rec = candidate["records"]
    _enabiz_audit(
        "upload.parse", True,
        (f"{name} {size}B sig={signature.get('is_enabiz')} "
         f"transfer_id={transfer_id} "
         f"demo={len(candidate.get('demographics') or {})} "
         f"tahlil={len(rec.get('tahlil') or [])} "
         f"ilac={len(rec.get('ilac') or [])} "
         f"tani={len(rec.get('tani') or [])} "
         f"randevu={len(rec.get('randevu') or [])}"),
        entity_id=transfer_id)
    return jsonify({"ok": True, "transfer_id": transfer_id,
                    "candidate": candidate})


@app.route("/api/enabiz/onayla", methods=["POST"])
@login_required
def api_enabiz_apply():
    if str(session.get("role") or "") != "doktor":
        return jsonify({"ok": False, "error": "Sadece doktor onaylayabilir"}), 403
    body = request.get_json(silent=True) or {}
    patient_key = str(body.get("patient_key") or "").strip()
    if not patient_key:
        return jsonify({"ok": False, "error": "patient_key gerekli"}), 400
    transfer_id = str(body.get("transfer_id") or "").strip()
    overwrite = bool(body.get("overwrite"))
    create_if_missing = bool(body.get("create_if_missing"))

    from yazklinik_enabiz_agent import (
        filter_demographics, filter_records_by_selection, SOURCE_LABEL)

    # ----- 1) Kategori secimi (tahlil/ilac/tani/randevu) -----
    selection_in = body.get("selection") or {}
    if not isinstance(selection_in, dict):
        selection_in = {}
    selection = {}
    for tip in ("tahlil", "ilac", "tani", "randevu"):
        idx_list = selection_in.get(tip)
        if idx_list is None:
            continue
        if not isinstance(idx_list, list):
            continue
        selection[tip] = [int(i) for i in idx_list
                          if isinstance(i, (int, float, str))
                          and str(i).lstrip("-").isdigit()]

    # ----- 2) Demografi alanlari -----
    candidate_demo = body.get("demographics") or {}
    if not isinstance(candidate_demo, dict):
        candidate_demo = {}
    selected_fields = body.get("selected_fields")
    if selected_fields is None:
        selected_fields = list(candidate_demo.keys())

    # ----- 3) transfer_id varsa veritabanindan kayitlari yukle -----
    transfer_row = _enabiz_load_transfer(transfer_id) if transfer_id else None
    stored_candidate = {}
    stored_records = {}
    pdf_path = ""
    report_type = ""
    if transfer_row:
        if transfer_row.get("status") == "cancelled":
            return jsonify({"ok": False,
                            "error": "Bu transfer iptal edilmis"}), 400
        try:
            stored = json.loads(transfer_row.get("candidate_json") or "{}")
        except Exception:
            stored = {}
        stored_candidate = stored
        stored_records = stored.get("records") or {}
        pdf_path = transfer_row.get("pdf_path") or ""
        report_type = str(stored.get("report_type") or "").strip().lower()
        if not candidate_demo:
            candidate_demo = stored.get("demographics") or {}
            if selected_fields == [] or selected_fields is None:
                selected_fields = list(candidate_demo.keys())
    else:
        # transfer_id yok - body icindeki records ile devam (UI parser'i)
        body_records = body.get("records") or {}
        if isinstance(body_records, dict):
            stored_records = body_records
    if report_type not in ("obstetric", "gynecologic"):
        report_type = str(body.get("report_type") or "").strip().lower()
    if report_type not in ("obstetric", "gynecologic") and pdf_path:
        report_type = _detect_report_type_from_pdf_file(pdf_path)

    # ----- 3.5) Hasta anahtarini dogrula / gerekirse yeni hasta olustur -----
    resolved_patient_key = patient_key
    created_new_patient = False
    if not _patient_key_exists(resolved_patient_key):
        try:
            with db_conn() as con:
                row = con.execute(
                    "SELECT folder_key FROM patients WHERE folder_key=? LIMIT 1",
                    (resolved_patient_key,)).fetchone()
                if not row:
                    row = con.execute(
                        "SELECT folder_key FROM patients WHERE display_name=? LIMIT 1",
                        (resolved_patient_key,)).fetchone()
                if not row and resolved_patient_key:
                    row = con.execute(
                        "SELECT folder_key FROM patients "
                        "WHERE display_name LIKE ? LIMIT 1",
                        (f"%{resolved_patient_key}%",)).fetchone()
            if row:
                try:
                    resolved_patient_key = str(row["folder_key"] or "")
                except Exception:
                    resolved_patient_key = str(row[0] or "")
        except Exception:
            pass

    if not _patient_key_exists(resolved_patient_key):
        demo_name = str(
            candidate_demo.get("patient_name")
            or candidate_demo.get("canonical_name")
            or candidate_demo.get("full_name")
            or candidate_demo.get("ad_soyad")
            or candidate_demo.get("name")
            or "").strip()
        if not demo_name:
            demo_name = _clean_patient_display_name(resolved_patient_key)
        if not create_if_missing:
            return jsonify({
                "ok": False,
                "error": (
                    "Hasta bulunamadi. Mevcut bir dosya secin veya "
                    "yeni hasta olusturmayi onaylayin."
                ),
                "need_create_confirmation": True,
                "candidate_name": demo_name,
                "requested_patient_key": resolved_patient_key,
            }), 409
        storage_root = get_patient_storage_root()
        if _is_voluson_folder_key_like(resolved_patient_key):
            new_patient_key = resolved_patient_key
        else:
            new_patient_key = _build_voluson_patient_key(
                demo_name or resolved_patient_key,
                patient_root=storage_root)
        _ensure_patient_folder_identity(
            new_patient_key,
            display_name=demo_name or resolved_patient_key,
            note_text="e-Nabiz PDF aktarimindan olusturuldu.",
            create_first_visit=True)
        demo_seed = load_patient_demographics(new_patient_key) or {}
        if demo_name:
            demo_seed["canonical_name"] = demo_name
        tc_digits = re.sub(r"\D+", "", str(candidate_demo.get("tc_no") or ""))
        if tc_digits:
            demo_seed["tc_no"] = tc_digits[:11]
        birth_text = str(candidate_demo.get("birth_date") or "").strip()
        if birth_text:
            demo_seed["birth_date"] = birth_text
        phone_digits = re.sub(r"\D+", "", str(candidate_demo.get("phone") or ""))
        if phone_digits:
            demo_seed["phone"] = (
                phone_digits[-11:]
                if len(phone_digits) >= 11 else phone_digits)
        _clean_name, folder_prefix, _folder_date = _patient_key_name_parts(new_patient_key)
        if folder_prefix:
            demo_seed["dicom_patient_id"] = folder_prefix
            demo_seed["dicom_accession_prefix"] = folder_prefix
        mwl_name = _person_name_to_family_given(
            demo_name or _clean_name or new_patient_key)
        if mwl_name:
            demo_seed["dicom_patient_name"] = mwl_name
        demo_seed["dicom_station_aet"] = VOLUSON_AET
        save_patient_demographics(new_patient_key, demo_seed)
        resolved_patient_key = new_patient_key
        created_new_patient = True

    patient_key = resolved_patient_key

    # ----- 4) En az bir is var mi? -----
    has_demo = bool(candidate_demo) and bool(selected_fields)
    has_records = any(selection.get(t) for t in
                      ("tahlil", "ilac", "tani", "randevu"))
    if not has_demo and not has_records:
        return jsonify({"ok": False,
                        "error": "Onaylanacak alan veya kayit secilmedi"}), 400

    summary = {
        "transfer_id": transfer_id,
        "patient_key": patient_key,
        "report_type": report_type or "",
        "patient_type_updated": False,
        "pdf_archived": False,
        "demographics": {"applied": [], "queued": [], "decisions": []},
        "tahlil": {"count": 0},
        "ilac": {"count": 0},
        "tani": {"count": 0},
        "randevu": {"count": 0, "appointment_ids": []},
        "created_new_patient": created_new_patient,
        "errors": [],
    }

    try:
        if report_type in ("obstetric", "gynecologic"):
            summary["patient_type_updated"] = bool(
                _set_patient_type_from_report(
                    patient_key, report_type, source="enabiz-pdf"))
    except Exception as ex:
        summary["errors"].append(f"patient_type: {ex}")

    if pdf_path:
        try:
            archived = _archive_patient_pdf_file(
                patient_key=patient_key,
                visit_key="",
                file_path=pdf_path,
                source="enabiz-upload",
                report_type=report_type,
                text_hint="\n".join(stored_candidate.get("summary_lines") or []))
            summary["pdf_archived"] = bool(archived)
            if archived and not report_type:
                detected_type = archived.get("report_type") or ""
                if detected_type in ("obstetric", "gynecologic"):
                    summary["report_type"] = detected_type
                    summary["patient_type_updated"] = bool(
                        _set_patient_type_from_report(
                            patient_key, detected_type,
                            source="enabiz-pdf-archive"))
        except Exception as ex:
            summary["errors"].append(f"pdf_archive: {ex}")

    # ----- 5) Demografiyi onay kuyruguna goz at -----
    if has_demo:
        try:
            filtered = filter_demographics(candidate_demo, selected_fields)
            if filtered:
                decisions = _patient_data_suggest_demographics(
                    patient_key, filtered,
                    source="enabiz_pdf",
                    source_ref=SOURCE_LABEL,
                    confidence=0.78,
                    auto_apply_empty=True,
                    overwrite=overwrite)
                summary["demographics"]["decisions"] = decisions
                summary["demographics"]["applied"] = [
                    d for d in decisions
                    if d.get("status") in {"applied", "applied_empty"}]
                summary["demographics"]["queued"] = [
                    d for d in decisions if d.get("status") == "queued"]
        except Exception as ex:
            summary["errors"].append(f"demografi: {ex}")
            _enabiz_audit("apply.demographics", False, str(ex),
                          entity_id=patient_key)

    # ----- 6) Secili kategorileri filtreleyip dispatch et -----
    chosen = filter_records_by_selection(stored_records, selection)
    try:
        if chosen.get("tahlil"):
            summary["tahlil"] = _enabiz_apply_tahlil(
                patient_key, chosen["tahlil"], transfer_id, pdf_path)
    except Exception as ex:
        summary["errors"].append(f"tahlil: {ex}")
        _enabiz_audit("apply.tahlil", False, str(ex), entity_id=patient_key)
    try:
        if chosen.get("ilac"):
            summary["ilac"] = _enabiz_apply_ilac(
                patient_key, chosen["ilac"], transfer_id)
    except Exception as ex:
        summary["errors"].append(f"ilac: {ex}")
        _enabiz_audit("apply.ilac", False, str(ex), entity_id=patient_key)
    try:
        if chosen.get("tani"):
            summary["tani"] = _enabiz_apply_tani(
                patient_key, chosen["tani"], transfer_id)
    except Exception as ex:
        summary["errors"].append(f"tani: {ex}")
        _enabiz_audit("apply.tani", False, str(ex), entity_id=patient_key)
    try:
        if chosen.get("randevu"):
            summary["randevu"] = _enabiz_apply_randevu(
                patient_key, chosen["randevu"], transfer_id)
    except Exception as ex:
        summary["errors"].append(f"randevu: {ex}")
        _enabiz_audit("apply.randevu", False, str(ex), entity_id=patient_key)

    # ----- 7) Audit kaydini guncelle -----
    if transfer_id:
        try:
            _enabiz_ensure_audit_schema()
            with db_conn() as con:
                con.execute(
                    "UPDATE enabiz_audit SET status=?, patient_key=?, "
                    "applied_at=?, applied_json=? WHERE transfer_id=?",
                    ("applied", patient_key,
                     datetime.now().isoformat(sep=" ", timespec="seconds"),
                     json.dumps(summary, ensure_ascii=False, default=str),
                     transfer_id))
                con.commit()
        except Exception as ex:
            summary["errors"].append(f"audit_update: {ex}")

    _enabiz_audit(
        "apply", not summary["errors"],
        (f"patient={patient_key} transfer={transfer_id} "
         f"demo_applied={len(summary['demographics']['applied'])} "
         f"demo_queued={len(summary['demographics']['queued'])} "
         f"tahlil={summary['tahlil'].get('count', 0)} "
         f"ilac={summary['ilac'].get('count', 0)} "
         f"tani={summary['tani'].get('count', 0)} "
         f"randevu={summary['randevu'].get('count', 0)} "
         f"errors={len(summary['errors'])}"),
        entity_id=transfer_id or patient_key)

    return jsonify({"ok": not summary["errors"], **summary})


@app.route("/api/enabiz/transfer/<transfer_id>", methods=["GET"])
@login_required
def api_enabiz_transfer_detail(transfer_id):
    row = _enabiz_load_transfer(transfer_id)
    if not row:
        return jsonify({"ok": False, "error": "Transfer bulunamadi"}), 404
    try:
        candidate = json.loads(row.get("candidate_json") or "{}")
    except Exception:
        candidate = {}
    try:
        applied = json.loads(row.get("applied_json") or "{}")
    except Exception:
        applied = {}
    return jsonify({
        "ok": True,
        "transfer_id": row.get("transfer_id"),
        "status": row.get("status"),
        "file_name": row.get("file_name"),
        "file_size": row.get("file_size"),
        "pdf_path": row.get("pdf_path"),
        "patient_key": row.get("patient_key"),
        "created_at": row.get("created_at"),
        "applied_at": row.get("applied_at"),
        "cancelled_at": row.get("cancelled_at"),
        "candidate": candidate,
        "applied": applied,
    })


@app.route("/api/enabiz/iptal", methods=["POST"])
@login_required
def api_enabiz_cancel():
    body = request.get_json(silent=True) or {}
    transfer_id = str(body.get("transfer_id") or "").strip()
    reason = str(body.get("reason") or "").strip()[:500]
    if not transfer_id:
        return jsonify({"ok": False, "error": "transfer_id gerekli"}), 400
    row = _enabiz_load_transfer(transfer_id)
    if not row:
        return jsonify({"ok": False, "error": "Transfer bulunamadi"}), 404
    if row.get("status") == "applied":
        return jsonify({"ok": False,
                        "error": "Zaten uygulanmis transfer iptal edilemez"}), 409
    try:
        with db_conn() as con:
            con.execute(
                "UPDATE enabiz_audit SET status=?, cancelled_at=?, notes=? "
                "WHERE transfer_id=?",
                ("cancelled",
                 datetime.now().isoformat(sep=" ", timespec="seconds"),
                 reason, transfer_id))
            con.commit()
    except Exception as ex:
        _enabiz_audit("iptal", False, str(ex), entity_id=transfer_id)
        return jsonify({"ok": False, "error": str(ex)}), 500
    _enabiz_audit("iptal", True, f"transfer_id={transfer_id} reason={reason}",
                  entity_id=transfer_id)
    return jsonify({"ok": True, "transfer_id": transfer_id,
                    "status": "cancelled"})


@app.route("/api/enabiz/dosya/<transfer_id>", methods=["GET"])
@login_required
def api_enabiz_pdf_download(transfer_id):
    row = _enabiz_load_transfer(transfer_id)
    if not row:
        return jsonify({"ok": False, "error": "PDF bulunamadi"}), 404
    download = request.args.get("download") == "1"
    pdf_path = row.get("pdf_path") or ""
    if pdf_path and Path(str(pdf_path)).exists():
        try:
            from flask import send_file
            return send_file(pdf_path, mimetype="application/pdf",
                             as_attachment=download,
                             download_name=row.get("file_name") or "enabiz.pdf")
        except Exception as ex:
            return jsonify({"ok": False, "error": str(ex)}), 500
    archive_row = _load_archived_pdf_record(
        patient_key=row.get("patient_key") or "",
        file_name=row.get("file_name") or "")
    if archive_row:
        return _send_archived_pdf_blob(archive_row, download=download)
    if not pdf_path:
        return jsonify({"ok": False, "error": "PDF bulunamadi"}), 404
    try:
        from flask import send_file
        return send_file(pdf_path, mimetype="application/pdf",
                         as_attachment=download,
                         download_name=row.get("file_name") or "enabiz.pdf")
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/enabiz/gecmis", methods=["GET"])
@login_required
def api_enabiz_history():
    items = []
    transfers = []
    try:
        _enabiz_ensure_audit_schema()
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            items = con.execute(
                "SELECT timestamp, username, action, entity_id, patient_key, details "
                "FROM web_audit_log WHERE action LIKE 'enabiz:%' "
                "ORDER BY timestamp DESC LIMIT 50").fetchall()
            transfers = con.execute(
                "SELECT transfer_id, file_name, file_size, status, "
                "patient_key, created_by, created_at, applied_at, "
                "cancelled_at, signature_is_enabiz "
                "FROM enabiz_audit ORDER BY created_at DESC LIMIT 50"
            ).fetchall()
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500
    return jsonify({"ok": True, "items": items, "transfers": transfers})


