# ===========================================================================
# B300: AI / Ollama Kurulum Sihirbazi
# ===========================================================================
# Ollama opsiyonel: server Ollama olmadan calisir. Kullanici buradan URL'i
# editler (yerel veya uzak: http://192.168.1.40:11434), test eder, "Bu PC'ye
# kur" diyerek winget veya OllamaSetup.exe ile yukleme baslatir, log'u
# polling ile gosterir.
# ===========================================================================

_B300_AI_INSTALL_STATE = {
    "running": False,
    "completed": False,
    "ok": False,
    "started_at": 0.0,
    "ended_at": 0.0,
    "log": [],         # list[str]
    "stage": "idle",   # idle | starting | downloading | installing | pulling | done | error
    "error": "",
    "pid": 0,
}
_B300_AI_INSTALL_LOCK = threading.Lock()
_B300_OLLAMA_INSTALLER_URL = "https://ollama.com/download/OllamaSetup.exe"


def _b300_install_log(msg, stage=None):
    """Thread-safe log append + son 200 satiri tut."""
    line = f"[{datetime.now().strftime('%H:%M:%S')}] {str(msg).rstrip()}"
    with _B300_AI_INSTALL_LOCK:
        log = _B300_AI_INSTALL_STATE.setdefault("log", [])
        log.append(line)
        if len(log) > 200:
            del log[: len(log) - 200]
        if stage:
            _B300_AI_INSTALL_STATE["stage"] = stage


def _b300_ollama_cli_present():
    """Ollama CLI PATH'te bulunabiliyor mu?"""
    import shutil as _shutil
    return bool(_shutil.which("ollama"))


def _b300_install_ollama_worker():
    """Arka plan thread: winget -> OllamaSetup.exe -> ollama pull."""
    import subprocess as _subprocess
    import urllib.request as _urlreq
    try:
        with _B300_AI_INSTALL_LOCK:
            _B300_AI_INSTALL_STATE.update({
                "running": True, "completed": False, "ok": False,
                "started_at": time.time(), "ended_at": 0.0,
                "log": [], "stage": "starting", "error": "",
            })
        _b300_install_log("YZ kurulum baslatiliyor (Ollama)...", stage="starting")

        creation_flags = getattr(_subprocess, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0

        # 1) winget dene
        winget_path = None
        try:
            import shutil as _shutil
            winget_path = _shutil.which("winget")
        except Exception:
            winget_path = None

        installed_via_winget = False
        if winget_path and os.name == "nt":
            _b300_install_log("winget bulundu, Ollama.Ollama paketini deniyorum...", stage="installing")
            try:
                proc = _subprocess.run(
                    [winget_path, "install", "--id", "Ollama.Ollama", "-e",
                     "--accept-source-agreements", "--accept-package-agreements",
                     "--silent", "--scope", "user"],
                    capture_output=True, text=True, timeout=900,
                    creationflags=creation_flags)
                _b300_install_log(f"winget exit={proc.returncode}")
                if proc.stdout:
                    for ln in str(proc.stdout).splitlines()[-20:]:
                        _b300_install_log(f"  {ln}")
                if proc.returncode == 0:
                    installed_via_winget = True
                    _b300_install_log("winget kurulumu basarili.")
                else:
                    if proc.stderr:
                        for ln in str(proc.stderr).splitlines()[-10:]:
                            _b300_install_log(f"  ERR {ln}")
                    _b300_install_log("winget basarisiz; OllamaSetup.exe'ye dusuyorum.")
            except Exception as ex:
                _b300_install_log(f"winget hatasi: {ex}")
        else:
            _b300_install_log("winget yok; OllamaSetup.exe akisi kullanilacak.")

        # 2) OllamaSetup.exe (winget basarisizsa)
        if not installed_via_winget:
            if os.name != "nt":
                _b300_install_log("HATA: Otomatik installer sadece Windows'ta calisir.", stage="error")
                with _B300_AI_INSTALL_LOCK:
                    _B300_AI_INSTALL_STATE.update({
                        "running": False, "completed": True, "ok": False,
                        "ended_at": time.time(),
                        "error": "Linux/Mac icin manuel kurulum: https://ollama.com",
                    })
                return
            _b300_install_log("OllamaSetup.exe indiriliyor...", stage="downloading")
            installer_path = os.path.join(
                os.environ.get("TEMP", os.getcwd()), "OllamaSetup_yazklinik.exe")
            try:
                req = _urlreq.Request(
                    _B300_OLLAMA_INSTALLER_URL,
                    headers={"User-Agent": "YazKlinik-B300"})
                with _urlreq.urlopen(req, timeout=120) as resp, \
                        open(installer_path, "wb") as out:
                    total_kb = 0
                    while True:
                        chunk = resp.read(65536)
                        if not chunk:
                            break
                        out.write(chunk)
                        total_kb += len(chunk) // 1024
                        if total_kb % 4096 == 0:  # her ~4MB log
                            _b300_install_log(f"  indirildi ~{total_kb // 1024} MB")
                _b300_install_log(f"Indirme tamam: {installer_path}")
            except Exception as ex:
                _b300_install_log(f"HATA: indirme basarisiz: {ex}", stage="error")
                with _B300_AI_INSTALL_LOCK:
                    _B300_AI_INSTALL_STATE.update({
                        "running": False, "completed": True, "ok": False,
                        "ended_at": time.time(), "error": str(ex),
                    })
                return

            _b300_install_log("Sessiz kurulum baslatiliyor (/SILENT)...", stage="installing")
            try:
                proc = _subprocess.run(
                    [installer_path, "/SILENT", "/CLOSEAPPLICATIONS", "/NORESTART"],
                    capture_output=True, text=True, timeout=900,
                    creationflags=creation_flags)
                _b300_install_log(f"Installer exit={proc.returncode}")
                if proc.returncode != 0:
                    err = proc.stderr or proc.stdout or "kurulum hatasi"
                    _b300_install_log(f"HATA: kurulum basarisiz: {err[:300]}", stage="error")
                    with _B300_AI_INSTALL_LOCK:
                        _B300_AI_INSTALL_STATE.update({
                            "running": False, "completed": True, "ok": False,
                            "ended_at": time.time(), "error": err[:300],
                        })
                    return
            except Exception as ex:
                _b300_install_log(f"HATA: installer calistirilamadi: {ex}", stage="error")
                with _B300_AI_INSTALL_LOCK:
                    _B300_AI_INSTALL_STATE.update({
                        "running": False, "completed": True, "ok": False,
                        "ended_at": time.time(), "error": str(ex),
                    })
                return

        # 3) Ollama'nin baslamasini bekle (servis ya da arka plan)
        _b300_install_log("Ollama servisi acilmasi bekleniyor...", stage="starting")
        time.sleep(4)
        # Ollama Setup default servisi otomatik baslatir; yine de manuel deneme:
        try:
            import shutil as _shutil
            ollama_exe = _shutil.which("ollama")
            if ollama_exe:
                # Eger servis acik degilse `ollama serve` arka planda baslat
                # (zaten acik ise bu komut hemen donmez ama servis kayitliysa
                # yeni instance hata verir; sessizce gec).
                try:
                    _subprocess.Popen(
                        [ollama_exe, "serve"],
                        stdout=_subprocess.DEVNULL,
                        stderr=_subprocess.DEVNULL,
                        creationflags=creation_flags)
                    _b300_install_log("`ollama serve` arka planda denendi.")
                except Exception:
                    pass
            time.sleep(3)
        except Exception:
            pass

        # 4) BaÄŸlantÄ± dogrula (5 deneme)
        _b300_install_log("Baglanti testi yapiliyor...")
        ok_online = False
        for attempt in range(5):
            try:
                status = _ollama_status(force=True)
                if status.get("online"):
                    ok_online = True
                    _b300_install_log(f"Ollama AYAKTA: {len(status.get('models') or [])} model kurulu.")
                    break
            except Exception as ex:
                _b300_install_log(f"  test {attempt+1}/5: {ex}")
            time.sleep(3)

        if not ok_online:
            _b300_install_log(
                "UYARI: Ollama yuklendi ama henuz cevap vermiyor. PC'yi "
                "yeniden baslatmanÄ±z ya da Ollama uygulamasini manuel acmaniz "
                "gerekebilir. Ayarlar sayfasindan tekrar test edebilirsiniz.",
                stage="error")
            with _B300_AI_INSTALL_LOCK:
                _B300_AI_INSTALL_STATE.update({
                    "running": False, "completed": True, "ok": False,
                    "ended_at": time.time(),
                    "error": "Ollama yuklendi fakat servise baglanilamadi.",
                })
            return

        # 5) Onerilen modeli pull et
        _b300_install_log("Onerilen model indiriliyor: llama3.1:8b ...", stage="pulling")
        try:
            ollama_exe = _shutil.which("ollama") or "ollama"
            proc = _subprocess.Popen(
                [ollama_exe, "pull", "llama3.1:8b"],
                stdout=_subprocess.PIPE,
                stderr=_subprocess.STDOUT,
                text=True,
                creationflags=creation_flags)
            with _B300_AI_INSTALL_LOCK:
                _B300_AI_INSTALL_STATE["pid"] = proc.pid
            line_count = 0
            for raw_line in proc.stdout:
                line = (raw_line or "").rstrip()
                if not line:
                    continue
                line_count += 1
                # cok yogun pull progress satirlari var; her 6'da bir log
                if line_count % 6 == 0 or "success" in line.lower() or "error" in line.lower():
                    _b300_install_log(f"  pull: {line[:180]}")
            proc.wait(timeout=1200)
            _b300_install_log(f"pull exit={proc.returncode}")
            pull_ok = (proc.returncode == 0)
        except Exception as ex:
            _b300_install_log(f"pull hatasi: {ex}")
            pull_ok = False

        with _B300_AI_INSTALL_LOCK:
            _B300_AI_INSTALL_STATE.update({
                "running": False, "completed": True, "ok": True,
                "ended_at": time.time(),
                "stage": "done" if pull_ok else "done_no_model",
                "error": "" if pull_ok else "Ollama hazir; ana model indirilemedi (manuel pull yapabilirsiniz).",
            })
        _b300_install_log("KURULUM TAMAM. Akıllı Diyalog'u tekrar açabilirsiniz.")
    except Exception as ex:
        _b300_install_log(f"BEKLENMEDIK HATA: {ex}", stage="error")
        with _B300_AI_INSTALL_LOCK:
            _B300_AI_INSTALL_STATE.update({
                "running": False, "completed": True, "ok": False,
                "ended_at": time.time(), "error": str(ex),
            })


def _b300_normalize_ollama_url(value):
    """Kullanicinin girdigi URL'i tam /api/generate haline getir."""
    s = str(value or "").strip().rstrip("/")
    if not s:
        return ""
    if not s.startswith(("http://", "https://")):
        # IP veya hostname yazmissa http://...:11434 default
        s = "http://" + s
    if ":11434" not in s and "/api/" not in s:
        # protokol://host -> protokol://host:11434
        if s.count(":") < 2:
            s = s + ":11434"
    if not s.endswith("/api/generate"):
        if "/api/generate" in s:
            s = s.split("/api/generate")[0] + "/api/generate"
        else:
            s = s.rstrip("/") + "/api/generate"
    return s


