            new_provider = (request.form.get("ai_provider") or "").strip().lower()
            if new_provider in _AI_PROVIDER_VALUES:
                _db_set_setting("sysparam_ai_provider", new_provider)
                _ai_runtime_caches_clear()
                saved_parts.append(f"saglayici={new_provider}")
            # Ollama URL (B300)
            ollama_url_raw = (request.form.get("ollama_url") or "").strip()
            if ollama_url_raw:
                new_url = _b300_normalize_ollama_url(ollama_url_raw)
