@app.route("/api/ai/test-connection", methods=["POST"])
@login_required
def api_b300_test_ai_connection():
    """B300: Anlik Ollama baglanti testi. Form'da URL gelirse onu dener;
    yoksa mevcut config URL'i ile dener (cache bypass)."""
    data = request.get_json(silent=True) or request.form or {}
    requested_url = _b300_normalize_ollama_url(data.get("url") or "")
    import urllib.request as _urlreq
    import json as _json
    test_url = requested_url or _AI_CONFIG.get("url") or "http://localhost:11434/api/generate"
    tags_url = test_url.replace("/api/generate", "/api/tags")
    try:
        req = _urlreq.Request(tags_url)
        with _urlreq.urlopen(req, timeout=4) as resp:
            payload = _json.loads(resp.read().decode("utf-8"))
            models = [
                (m.get("name") or m.get("model") or "").strip()
                for m in (payload.get("models") or []) if isinstance(m, dict)
            ]
            models = [m for m in models if m]
            return jsonify({
                "ok": True, "online": True, "count": len(models),
                "models": models[:30], "url": test_url, "hint": "Hazır",
            })
    except Exception as ex:
        return jsonify({
            "ok": True, "online": False, "count": 0, "models": [],
            "url": test_url, "hint": str(ex)[:200],
        })


@app.route("/api/ai/test-cloud", methods=["POST"])
@login_required
def api_b301_test_cloud_ai():
    """B301: Bulut saglayici (Claude/ChatGPT/DeepSeek/Gemini) bagantilarini
    anlik test eder. Form'da api_key + model + provider gelir; gecici olarak
    DB anahtari yerine form'daki anahtarla cagri yapilir (form kaydedilmemis
    ise bile test edilebilir).
    """
    if session.get("role") != "doktor":
        return jsonify({"ok": False, "error": "permission"}), 403
    data = request.get_json(silent=True) or request.form or {}
    provider = str(data.get("provider") or "").strip().lower()
    if provider not in {"claude", "openai", "deepseek", "gemini"}:
        return jsonify({"ok": False, "error": "Bilinmeyen saglayici"}), 400
    form_api_key = str(data.get("api_key") or "").strip()
    form_model = str(data.get("model") or "").strip()
    setting_key_name = (
        "sysparam_openai_api_key" if provider == "openai"
        else f"sysparam_{provider}_api_key")
    setting_model_name = (
        "sysparam_openai_model" if provider == "openai"
        else f"sysparam_{provider}_model")
    # Test sirasinda form'daki anahtari/model'i gecici override et
    saved_api_key = _ai_setting_value(setting_key_name, "") or ""
    saved_model = _ai_setting_value(setting_model_name, "") or ""
    try:
        if form_api_key:
            _db_set_setting(setting_key_name, form_api_key)
        if form_model:
            _db_set_setting(setting_model_name, form_model)
        # Kisa, ucuz test prompt
        test_prompt = "Tek cumle ile 'OK' yaz."
        cfg_for_test = (
            _openai_config() if provider == "openai"
            else _b301_cloud_config(provider)
        )
        ok, answer, dur = _b301_call_cloud_ai(
            provider, test_prompt,
            temperature=0.1, max_tokens=60, timeout=20, use_cache=False)
        if ok and answer:
            return jsonify({
                "ok": True, "provider": provider,
                "duration_ms": dur, "answer": answer[:200],
                "model": cfg_for_test.get("model") or "",
                "endpoint": cfg_for_test.get("base_url") or "",
            })
        err = str(answer or "")[:1200]
        hint = err or "Cevap alinamadi"
        if provider == "openai":
            hint = _openai_error_hint(hint) or hint
        if provider == "deepseek":
            low = hint.lower()
            if "401" in low or "authentication fails" in low or "invalid" in low:
                hint = (
                    "DeepSeek anahtari reddetti (401). Kayitli/eski anahtari silip "
                    "platform.deepseek.com uzerinden yeni API key olusturun ve tekrar yapistirin."
                )
            elif "insufficient" in low or "balance" in low or "402" in low:
                hint = "DeepSeek bakiye/kredi yetersiz gorunuyor; platform.deepseek.com uzerinden bakiyeyi kontrol edin."
            elif "model" in low and ("not" in low or "invalid" in low):
                hint = "DeepSeek model adi kabul edilmedi. Onerilen: deepseek-v4-flash veya deepseek-v4-pro."
            elif "timed out" in low or "timeout" in low or "zaman asimi" in low:
                hint = "DeepSeek baglantisi zaman asimina ugradi; internet/guvenlik duvari veya DeepSeek servis durumunu kontrol edin."
        return jsonify({
            "ok": False, "provider": provider,
            "error": err[:500] if err else "Cevap alinamadi",
            "hint": hint[:500],
            "duration_ms": dur,
            "model": cfg_for_test.get("model") or "",
            "endpoint": cfg_for_test.get("base_url") or "",
        })
    finally:
        # Test bitince eski degeri geri yukle (form daha sonra kaydedilirse o
        # zaman degisir; aksi halde gecici yazma kalmasin).
        try:
            if form_api_key:
                _db_set_setting(setting_key_name, saved_api_key)
            if form_model:
                _db_set_setting(setting_model_name, saved_model)
        except Exception:
            pass


