# ===========================================================================
# B403/B404: Program-ici klasor gezgini (Explorer yerine).
# Doktor "Explorer ile degistirme" yerine "program icinde gezerek sec"
# istedi. Iki endpoint: browse (klasoru listele) + mkdir (yeni klasor olustur).
# Doktor yetkisi gerektirir, hidden/system klasorler atlanir.
# ===========================================================================

def _b403_list_drives_and_known():
    """Windows surucu harfleri + bilinen NAS / data root'lari."""
    drives = []
    seen = set()
    if os.name == "nt":
        try:
            import ctypes
            mask = ctypes.windll.kernel32.GetLogicalDrives()
            for i in range(26):
                if mask & (1 << i):
                    letter = chr(ord("A") + i)
                    p = f"{letter}:\\"
                    if p.lower() not in seen and os.path.exists(p):
                        drives.append({"name": f"{letter}: surucu", "full": p})
                        seen.add(p.lower())
        except Exception:
            pass
    extras = []
    try:
        for it in _B302_PATH_REGISTRY:
            label = it.get("label") or it.get("key")
            p = _b302_current_path(it)
            if not p:
                continue
            try:
                base = p if os.path.isdir(p) else os.path.dirname(p)
                if base and os.path.isdir(base) and base.lower() not in seen:
                    extras.append({"name": f"YazKlinik - {label}", "full": base})
                    seen.add(base.lower())
            except Exception:
                continue
    except Exception:
        pass
    try:
        home = os.path.expanduser("~")
        for sub, lbl in (
            ("Desktop", "Masaustu"),
            ("OneDrive\\Desktop", "OneDrive Masaustu"),
            ("Documents", "Belgeler"),
            ("OneDrive\\Documents", "OneDrive Belgeler"),
        ):
            p = os.path.join(home, sub)
            if os.path.isdir(p) and p.lower() not in seen:
                extras.append({"name": lbl, "full": p})
                seen.add(p.lower())
    except Exception:
        pass
    return drives, extras


@app.route("/api/dosya-yerleri/browse", methods=["GET"])
@login_required
def b403_api_browse_folders():
    if session.get("role") != "doktor":
        return jsonify({"ok": False, "error": "permission"}), 403
    raw = (request.args.get("path") or "").strip().strip('"').strip("'")
    drives, extras = _b403_list_drives_and_known()
    if not raw:
        return jsonify({
            "ok": True, "path": "", "parent": "", "is_root": True,
            "drives": drives, "shortcuts": extras, "dirs": [],
        })
    try:
        path = os.path.abspath(raw) if not raw.startswith("\\\\") else raw
        if not os.path.isdir(path):
            return jsonify({
                "ok": False, "error": f"Klasor bulunamadi: {path}",
                "path": path,
            }), 404
        parent = os.path.dirname(path.rstrip("\\/")) or ""
        if parent == path:
            parent = ""
        try:
            entries = os.scandir(path)
            dirs = []
            for e in entries:
                try:
                    if not e.is_dir(follow_symlinks=False):
                        continue
                    name = e.name
                    if name.startswith(".") or name.startswith("$"):
                        continue
                    dirs.append({"name": name, "full": os.path.join(path, name)})
                except (PermissionError, OSError):
                    continue
            entries.close()
            dirs.sort(key=lambda d: d["name"].lower())
        except (PermissionError, OSError) as ex:
            return jsonify({
                "ok": False, "error": f"Erisim reddedildi: {ex}",
                "path": path,
            }), 403
        return jsonify({
            "ok": True, "path": path, "parent": parent, "is_root": False,
            "drives": drives, "shortcuts": extras, "dirs": dirs,
        })
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


@app.route("/api/dosya-yerleri/mkdir", methods=["POST"])
@login_required
def b403_api_mkdir():
    if session.get("role") != "doktor":
        return jsonify({"ok": False, "error": "permission"}), 403
    data = request.get_json(silent=True) or request.form or {}
    parent = str(data.get("parent") or "").strip()
    name = str(data.get("name") or "").strip()
    if not parent or not name:
        return jsonify({"ok": False, "error": "parent ve name gerekli"}), 400
    bad = set('<>:"/\\|?*')
    if any(ch in bad for ch in name):
        return jsonify({
            "ok": False,
            "error": "Klasor adinda gecersiz karakter (< > : \" / \\ | ? *)",
        }), 400
    try:
        if not os.path.isdir(parent):
            return jsonify({
                "ok": False,
                "error": f"Ana klasor bulunamadi: {parent}",
            }), 400
        target = os.path.join(parent, name)
        if os.path.exists(target):
            return jsonify({
                "ok": True, "exists": True, "path": target,
                "message": "Klasor zaten var",
            })
        os.makedirs(target, exist_ok=False)
        return jsonify({"ok": True, "path": target, "message": "Klasor olusturuldu"})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)}), 500


