ORTHANC_DEFAULT_HOST = os.environ.get("YAZKLINIK_ORTHANC_HOST", "192.168.1.148").strip()
ORTHANC_DEFAULT_PORT = os.environ.get("YAZKLINIK_ORTHANC_PORT", "8042").strip()
ORTHANC_DICOM_PORT = os.environ.get("YAZKLINIK_ORTHANC_DICOM_PORT", "4242").strip() or "4242"
ORTHANC_AET = os.environ.get("YAZKLINIK_ORTHANC_AET", "ORTHANC").strip() or "ORTHANC"
VOLUSON_AET = os.environ.get("YAZKLINIK_VOLUSON_AET", "VOLUSON").strip() or "VOLUSON"
ORTHANC_ALLOW_FIND = os.environ.get("YAZKLINIK_ORTHANC_ALLOW_FIND", "1").strip() or "1"
ORTHANC_ALLOW_FIND_WORKLIST = os.environ.get(
    "YAZKLINIK_ORTHANC_ALLOW_FIND_WORKLIST", "1").strip() or "1"
ORTHANC_URL = os.environ.get(
    "YAZKLINIK_ORTHANC_URL",
    f"http://{ORTHANC_DEFAULT_HOST}:{ORTHANC_DEFAULT_PORT}",
).strip().rstrip("/")
ORTHANC_USER = os.environ.get("YAZKLINIK_ORTHANC_USER", "").strip()
ORTHANC_PASS = os.environ.get("YAZKLINIK_ORTHANC_PASS", "")

_ORTHANC_LEGACY_URLS = {
    "",
    "http://localhost:8042",
    "http://127.0.0.1:8042",
    "http://192.168.1.100:8042",
}
_ORTHANC_LEGACY_USERS = {"", "admin"}
_ORTHANC_LEGACY_PASSES = {"", "CHANGE_ME"}


def _is_legacy_orthanc_value(target, value):
    raw = str(value or "").strip()
    if target == "url":
        return raw.rstrip("/") in _ORTHANC_LEGACY_URLS
    if target == "user":
        return raw in _ORTHANC_LEGACY_USERS
    if target == "pass":
        return raw in _ORTHANC_LEGACY_PASSES
    return not raw


def _normalize_orthanc_config(url=None, user=None, password=None):
    raw_url = str(url or "").strip().rstrip("/")
    raw_user = str(user or "").strip()
    raw_pass = "" if password is None else str(password)
    legacy_bundle = (
        raw_url in _ORTHANC_LEGACY_URLS
        and raw_user in _ORTHANC_LEGACY_USERS
        and (raw_pass in _ORTHANC_LEGACY_PASSES or raw_pass == ORTHANC_PASS)
    )
    if not raw_url or legacy_bundle:
        raw_url = ORTHANC_URL
    if not raw_user or legacy_bundle:
        raw_user = ORTHANC_USER
    if not raw_pass or legacy_bundle:
        raw_pass = ORTHANC_PASS
    return raw_url, raw_user, raw_pass


def _get_orthanc_config():
    """Read Orthanc settings from both old and sysparam keys."""
    import base64
    cfg = {
        "url": ORTHANC_URL,
        "user": ORTHANC_USER,
        "pass": ORTHANC_PASS,
    }
    key_map = {
        "url": ("sysparam_orthanc_url", "orthanc_url", "orthanc/url"),
        "user": ("sysparam_orthanc_user", "orthanc_user", "orthanc/user"),
        "pass": ("sysparam_orthanc_pass", "orthanc_pass", "orthanc/pass"),
    }
    try:
        with db_conn() as con:
            for target, keys in key_map.items():
                fallback = ""
                for key in keys:
                    row = con.execute(
                        "SELECT value FROM settings WHERE key=?",
                        (key,)).fetchone()
                    if row and row[0]:
                        value = str(row[0]).strip()
                        if not fallback:
                            fallback = value
                        if not _is_legacy_orthanc_value(target, value):
                            cfg[target] = value
                            break
                else:
                    if fallback:
                        cfg[target] = fallback
    except Exception:
        pass
    cfg["url"], cfg["user"], cfg["pass"] = _normalize_orthanc_config(
        cfg.get("url"), cfg.get("user"), cfg.get("pass"))
    auth = base64.b64encode(
        f"{cfg['user']}:{cfg['pass']}".encode()).decode()
    return cfg["url"], cfg["user"], cfg["pass"], {
        "Authorization": f"Basic {auth}"}


def _get_orthanc_mwl_config():
    def _setting(keys, default):
        for key in keys:
            try:
                value = str(_db_get_setting(key, "") or "").strip()
            except Exception:
                value = ""
            if value:
                return value
        return default

    return {
        "server_aet": _dicom_safe_text(_setting(
            ("sysparam_orthanc_aet", "orthanc_aet", "dicom_aet"),
            ORTHANC_AET), 16) or "ORTHANC",
        "station_aet": _dicom_safe_text(_setting(
            ("sysparam_voluson_aet", "voluson_aet",
             "dicom_worklist_station_aet", "sysparam_dicom_worklist_station_aet"),
            VOLUSON_AET), 16) or "VOLUSON",
        "dicom_port": _setting(
            ("sysparam_orthanc_dicom_port", "orthanc_dicom_port", "dicom_port"),
            ORTHANC_DICOM_PORT) or "4242",
        "allow_find": _setting(
            ("sysparam_orthanc_allow_find", "orthanc_allow_find"),
            ORTHANC_ALLOW_FIND),
        "allow_find_worklist": _setting(
            ("sysparam_orthanc_allow_find_worklist", "orthanc_allow_find_worklist"),
            ORTHANC_ALLOW_FIND_WORKLIST),
    }


def _get_voluson_worklist_public_port():
    """Voluson Worklist may enter through Windows portproxy 104 -> Orthanc 4242."""
    import socket
    import time

    for key in (
        "sysparam_voluson_worklist_port",
        "voluson_worklist_port",
        "sysparam_dicom_worklist_public_port",
        "dicom_worklist_public_port",
    ):
        try:
            value = str(_db_get_setting(key, "") or "").strip()
        except Exception:
            value = ""
        if value:
            return re.sub(r"\D", "", value) or value
    env_port = str(
        os.environ.get("YAZKLINIK_VOLUSON_WORKLIST_PORT", "") or ""
    ).strip()
    if env_port:
        return re.sub(r"\D", "", env_port) or env_port

    # No explicit port configured: detect the reachable option to avoid
    # recommending a stale 104 when portproxy is not active.
    cache = globals().setdefault("_DICOM_PUBLIC_PORT_CACHE", {
        "ts": 0.0,
        "value": "104",
    })
    now = time.time()
    if (now - float(cache.get("ts") or 0.0)) <= 30.0:
        cached = str(cache.get("value") or "").strip()
        if cached:
            return cached

    host = ORTHANC_DEFAULT_HOST
    try:
        orthanc_url, _u, _p, _h = _get_orthanc_config()
        host = urlsplit(str(orthanc_url or "")).hostname or host
    except Exception:
        pass
    try:
        dicom_internal_port = int(str(_get_orthanc_mwl_config().get("dicom_port") or "4242"))
    except Exception:
        dicom_internal_port = 4242

    def _can_connect(target_host, target_port):
        try:
            with socket.create_connection(
                (str(target_host), int(target_port)), timeout=0.8
            ):
                return True
        except Exception:
            return False

    selected = "104"
    if _can_connect(host, 104):
        selected = "104"
    elif _can_connect(host, dicom_internal_port):
        selected = str(dicom_internal_port)

    cache["ts"] = now
    cache["value"] = selected
    return selected


def _orthanc_studies_list_url(orthanc_url, limit=20):
    """Orthanc requires since whenever limit is used on list endpoints."""
    safe_limit = max(1, int(limit or 20))
    return f"{str(orthanc_url).rstrip('/')}/studies?expand&since=0&limit={safe_limit}"


def _orthanc_url_join(path=""):
    orthanc_url, _user, _password, _headers = _get_orthanc_config()
    clean_path = str(path or "")
    if clean_path.startswith("http://") or clean_path.startswith("https://"):
        return clean_path
    if clean_path and not clean_path.startswith("/"):
        clean_path = "/" + clean_path
    return str(orthanc_url or ORTHANC_URL).rstrip("/") + clean_path


def _orthanc_api_json(path, timeout=5):
    """Read a small JSON payload from Orthanc without copying DICOM data."""
    import json as _json
    import urllib.request as _urllib_req

    _url, _user, _password, headers = _get_orthanc_config()
    req = _urllib_req.Request(_orthanc_url_join(path), headers=headers)
    with _urllib_req.urlopen(req, timeout=timeout) as resp:
        raw = resp.read()
        if not raw:
            return None
        return _json.loads(raw.decode("utf-8-sig"))


def _orthanc_api_bytes(path, timeout=12, max_bytes=24 * 1024 * 1024):
    """Read bounded binary payloads from Orthanc for private tag probing."""
    import urllib.request as _urllib_req

    _url, _user, _password, headers = _get_orthanc_config()
    req = _urllib_req.Request(_orthanc_url_join(path), headers=headers)
    with _urllib_req.urlopen(req, timeout=timeout) as resp:
        raw = resp.read(max_bytes + 1)
        if len(raw) > max_bytes:
            raise ValueError("DICOM dosyasi private tarama limiti ustunde.")
        return raw


def _orthanc_api_request_json(path, method="GET", payload=None, timeout=8):
    """GET/POST JSON to Orthanc using configured clinic credentials."""
    import json as _json
    import urllib.request as _urllib_req

    _url, _user, _password, headers = _get_orthanc_config()
    clean_headers = dict(headers or {})
    data = None
    if payload is not None:
        data = _json.dumps(payload, ensure_ascii=True, default=str).encode("utf-8")
        clean_headers["Content-Type"] = "application/json"
    req = _urllib_req.Request(
        _orthanc_url_join(path),
        data=data,
        headers=clean_headers,
        method=str(method or "GET").upper())
    with _urllib_req.urlopen(req, timeout=timeout) as resp:
        raw = resp.read()
        if not raw:
            return {
                "ok": 200 <= int(getattr(resp, "status", 200)) < 400,
                "status": int(getattr(resp, "status", 200)),
            }
        text = raw.decode("utf-8-sig", errors="replace")
        try:
            parsed = _json.loads(text)
        except Exception:
            parsed = {"raw": text}
        if isinstance(parsed, dict):
            parsed.setdefault("status", int(getattr(resp, "status", 200)))
            parsed.setdefault("ok", 200 <= int(getattr(resp, "status", 200)) < 400)
        return parsed


def _orthanc_probe_http_path(path, timeout=4):
    import urllib.request as _urllib_req
    import urllib.error as _urllib_err

    _url, _user, _password, headers = _get_orthanc_config()
    target = _orthanc_url_join(path)
    try:
        req = _urllib_req.Request(target, headers=headers)
        with _urllib_req.urlopen(req, timeout=timeout) as resp:
            return {
                "ok": 200 <= int(getattr(resp, "status", 200)) < 400,
                "status": int(getattr(resp, "status", 200)),
                "url": target,
                "content_type": resp.headers.get("Content-Type", ""),
            }
    except _urllib_err.HTTPError as ex:
        return {"ok": False, "status": int(ex.code), "url": target,
                "error": str(ex)}
    except Exception as ex:
        return {"ok": False, "status": 0, "url": target, "error": str(ex)}


def _orthanc_proxy_local_path(path=""):
    clean = str(path or "").strip()
    if clean.startswith("http://") or clean.startswith("https://"):
        try:
            parsed = urlsplit(clean)
            clean = parsed.path or "/"
            if parsed.query:
                clean += "?" + parsed.query
        except Exception:
            clean = "/"
    if not clean:
        return "/"
    if not clean.startswith("/"):
        clean = "/" + clean
    return clean


def _orthanc_viewer_url(viewer, study_id="", study_uid=""):
    base = _orthanc_url_join("").rstrip("/")
    viewer = str(viewer or "").strip().lower()
    sid = quote(str(study_id or ""), safe="")
    suid = quote(str(study_uid or ""), safe="")
    if _orthanc_proxy_enabled():
        if viewer == "ohif":
            return (f"/ohif/viewer?StudyInstanceUIDs={suid}"
                    if suid else "/ohif/")
        if viewer == "stone":
            return (f"/stone-webviewer/index.html?study={sid}"
                    if sid else "/stone-webviewer/index.html")
        if viewer == "volview":
            return "/volview/index.html"
        if viewer == "web-viewer":
            return (f"/web-viewer/app/viewer.html?study={sid}"
                    if sid else "/web-viewer/app/viewer.html")
        if viewer == "classic":
            return "/app/explorer.html"
        return (f"/ui/app/#/studies/{sid}" if sid else "/ui/app/")
    if viewer == "ohif":
        return (f"{base}/ohif/viewer?StudyInstanceUIDs={suid}"
                if suid else f"{base}/ohif/")
    if viewer == "stone":
        return (f"{base}/stone-webviewer/index.html?study={sid}"
                if sid else f"{base}/stone-webviewer/index.html")
    if viewer == "volview":
        return f"{base}/volview/index.html"
    if viewer == "web-viewer":
        return (f"{base}/web-viewer/app/viewer.html?study={sid}"
                if sid else f"{base}/web-viewer/app/viewer.html")
    if viewer == "classic":
        return f"{base}/app/explorer.html"
    return (f"{base}/ui/app/#/studies/{sid}" if sid else f"{base}/ui/app/")


def _orthanc_service_catalog(plugins, dicomweb_ok=False):
    plugin_set = {str(p) for p in (plugins or [])}

    def item(key, label, plugin, detail, path="", internal="", viewer=""):
        ok = True if not plugin else plugin in plugin_set
        return {
            "key": key,
            "label": label,
            "plugin": plugin,
            "ok": bool(ok),
            "detail": detail,
            "url": _orthanc_proxy_local_path(path) if path else "",
            "internal_url": internal,
            "viewer": viewer,
        }

    services = [
        item("explorer2", "Explorer 2", "orthanc-explorer-2",
             "Modern Orthanc hasta/study gezgini", "/ui/app/"),
        item("classic", "Klasik Explorer", "explorer.js",
             "Eski ama hizli Orthanc web arayuzu", "/app/explorer.html"),
        item("ohif", "OHIF Viewer", "ohif",
             "DICOMweb tabanli modern viewer", "/ohif/", viewer="ohif"),
        item("stone", "Stone WebViewer", "stone-webviewer",
             "Hizli DICOM goruntu viewer", "/stone-webviewer/index.html",
             viewer="stone"),
        item("volview", "VolView", "volview",
             "3D/volumetrik viewer girisi", "/volview/index.html",
             viewer="volview"),
        item("web-viewer", "Web Viewer", "web-viewer",
             "Orthanc web-viewer plugin", "/web-viewer/app/viewer.html",
             viewer="web-viewer"),
        item("dicom-web", "DICOMweb API", "dicom-web",
             "OHIF ve harici viewer'lar icin DICOMweb",
             "/dicom-web/studies?limit=1"),
        item("worklists", "Modality Worklist", "orthanc-worklists",
             "Voluson/USG hasta is listesi", "", "/dicom-worklist"),
        item("transfers", "Transfers", "transfers",
             "Orthanc arasi study transfer altyapisi"),
        item("connectivity", "Connectivity Checks", "connectivity-checks",
             "DICOM ag baglanti kontrolleri"),
        item("gdcm", "GDCM", "gdcm",
             "DICOM codec ve sikistirma destegi"),
        item("indexer", "Indexer", "indexer",
             "Orthanc index yardimci servisi"),
        item("housekeeper", "Housekeeper", "housekeeper",
             "PACS bakim ve temizlik servisi"),
    ]
    for service in services:
        if service["key"] == "dicom-web":
            service["ok"] = bool(service["ok"] and dicomweb_ok)
    return services


_ORTHANC_STATUS_CACHE = {}
_ORTHANC_STATUS_CACHE_TTL = 45.0


def _orthanc_status_payload(deep=True):
    orthanc_url, orthanc_user, _orthanc_pass, _headers = _get_orthanc_config()
    system_timeout = 5 if deep else 1.2
    aux_timeout = 4 if deep else 0.8
    dicomweb_timeout = 5 if deep else 1.2
    payload = {
        "ok": False,
        "online": False,
        "url": orthanc_url,
        "user": orthanc_user,
        "version": "",
        "system": {},
        "statistics": {},
        "plugins": [],
        "plugins_count": 0,
        "dicomweb_ok": False,
        "services": [],
        "error": "",
        "checked_at": datetime.now().isoformat(timespec="seconds"),
    }
    try:
        system = _orthanc_api_json("/system", timeout=system_timeout) or {}
        payload["system"] = system
        payload["version"] = str(system.get("Version") or "")
        payload["online"] = True
        payload["ok"] = True
    except Exception as ex:
        payload["error"] = f"{type(ex).__name__}: {ex}"
        payload["services"] = _orthanc_service_catalog([])
        return payload

    try:
        payload["statistics"] = _orthanc_api_json(
            "/statistics", timeout=aux_timeout) or {}
    except Exception as ex:
        payload["statistics_error"] = str(ex)
    try:
        plugins = _orthanc_api_json("/plugins", timeout=aux_timeout) or []
        payload["plugins"] = sorted(str(p) for p in plugins)
        payload["plugins_count"] = len(payload["plugins"])
    except Exception as ex:
        payload["plugins_error"] = str(ex)
    try:
        _orthanc_api_json(
            "/dicom-web/studies?limit=1", timeout=dicomweb_timeout)
        payload["dicomweb_ok"] = True
    except Exception as ex:
        payload["dicomweb_error"] = str(ex)
    payload["services"] = _orthanc_service_catalog(
        payload["plugins"], dicomweb_ok=payload["dicomweb_ok"])
    if deep:
        for service in payload["services"]:
            if service.get("url") and service.get("plugin"):
                service["probe"] = _orthanc_probe_http_path(
                    service["url"], timeout=3)
    return payload


def _orthanc_status_payload_cached(deep=False, ttl=None, force=False):
    """Small Orthanc status cache for frequently rendered dashboards."""
    ttl = _ORTHANC_STATUS_CACHE_TTL if ttl is None else float(ttl)
    try:
        orthanc_url, orthanc_user, orthanc_pass, _headers = _get_orthanc_config()
        cache_key = (orthanc_url, orthanc_user, orthanc_pass, bool(deep))
    except Exception:
        cache_key = ("default", "", "", bool(deep))
    now = time.time()
    cached = _ORTHANC_STATUS_CACHE.get(cache_key)
    if (
        not force
        and cached
        and now - float(cached.get("ts", 0.0)) < ttl
    ):
        return cached.get("data") or {}
    payload = _orthanc_status_payload(deep=deep)
    _ORTHANC_STATUS_CACHE[cache_key] = {"ts": now, "data": payload}
    return payload


def _dicom_command_panel_state():
    """Small, fast state block for the DICOM command-center hero."""
    state = {
        "today_date": datetime.now().strftime("%Y-%m-%d"),
        "today_worklist_count": 0,
        "today_ready_count": 0,
        "today_sent_count": 0,
        "local_counts": {},
        "error": "",
    }
    try:
        state["local_counts"] = _dicom_exchange_local_counts()
    except Exception as ex:
        state["error"] = f"{type(ex).__name__}: {ex}"
    try:
        items, diagnostics = _dicom_worklist_rows(state["today_date"])
        state["today_worklist_count"] = len(items or [])
        state["today_ready_count"] = sum(
            1 for item in (items or [])
            if str(item.get("patient_key") or "").strip())
        state["today_sent_count"] = sum(
            1 for item in (items or [])
            if item.get("worklist_sent"))
        if diagnostics and not state["error"]:
            state["diagnostics"] = diagnostics
    except Exception as ex:
        if not state["error"]:
            state["error"] = f"{type(ex).__name__}: {ex}"
    return state


_DICOM_COMMAND_PANEL_STATE_CACHE = {"ts": 0.0, "data": None}


def _dicom_command_panel_state_cached(ttl=30.0):
    now = time.time()
    cached = _DICOM_COMMAND_PANEL_STATE_CACHE.get("data")
    if cached is not None and now - float(
            _DICOM_COMMAND_PANEL_STATE_CACHE.get("ts") or 0.0) < float(ttl):
        return dict(cached)
    state = _dicom_command_panel_state()
    _DICOM_COMMAND_PANEL_STATE_CACHE["ts"] = now
    _DICOM_COMMAND_PANEL_STATE_CACHE["data"] = dict(state)
    return state


