    command_state = _dicom_command_panel_state_cached()
    local_counts = command_state.get("local_counts") or {}
    online = bool(status_payload.get("online"))
    state_class = "success" if online else "danger"
    state_text = "AKTIF" if online else "BAGLANTI YOK"
    status_hint = (
        "Orthanc hazir. Alttaki butonlarla test, senkron ve worklist islemleri yapilir."
        if online else
        "Once Orthanc baglantisini test edin; ayar gerekirse DICOM Ayarlari'na gidin."
    )
    plugin_chips = "".join(
        f'<span class="yk-dicom-chip">{sh(p)}</span>' for p in plugins)
    service_cards = ""
    for service in services:
        ok = bool(service.get("ok"))
        badge_class = "yk-service-ok" if ok else "yk-service-warn"
        badge_text = "Hazir" if ok else "Pasif"
