def _ensure_dicom_ai_tables(con=None):
    """Create/upgrade DICOM index tables. Never stores image/video/PDF blobs."""
    if con is None:
        with db_conn() as open_con:
            return _ensure_dicom_ai_tables(open_con)
    try:
        con.execute("""
            CREATE TABLE IF NOT EXISTS dicom_studies (
                orthanc_study_id TEXT PRIMARY KEY,
                study_instance_uid TEXT,
                patient_name TEXT,
                patient_id TEXT,
                study_date TEXT,
                study_time TEXT,
                accession_number TEXT,
                institution_name TEXT,
                raw_json TEXT,
                created_at TEXT,
                updated_at TEXT
            )
        """)
        for column, ddl in (
            ("patient_key", "ALTER TABLE dicom_studies ADD COLUMN patient_key TEXT"),
            ("visit_key", "ALTER TABLE dicom_studies ADD COLUMN visit_key TEXT"),
            ("worklist_accession_number", "ALTER TABLE dicom_studies ADD COLUMN worklist_accession_number TEXT"),
            ("matched_confidence", "ALTER TABLE dicom_studies ADD COLUMN matched_confidence REAL DEFAULT 0"),
            ("match_reason", "ALTER TABLE dicom_studies ADD COLUMN match_reason TEXT"),
            ("last_synced_at", "ALTER TABLE dicom_studies ADD COLUMN last_synced_at TEXT"),
        ):
            try:
                con.execute(ddl)
            except Exception:
                pass
        con.execute("""
            CREATE TABLE IF NOT EXISTS dicom_series (
                orthanc_series_id TEXT PRIMARY KEY,
                orthanc_study_id TEXT,
                series_instance_uid TEXT,
                modality TEXT,
                series_number TEXT,
                series_description TEXT,
                instance_count INTEGER DEFAULT 0,
                raw_json TEXT,
                created_at TEXT
            )
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS dicom_instances (
                orthanc_instance_id TEXT PRIMARY KEY,
                orthanc_series_id TEXT,
                sop_instance_uid TEXT,
                sop_class_uid TEXT,
                instance_number TEXT,
                image_type TEXT,
                rows INTEGER,
                columns INTEGER,
                pixel_spacing TEXT,
                has_us_region INTEGER DEFAULT 0,
                has_kretz_private INTEGER DEFAULT 0,
                has_structured_measurement INTEGER DEFAULT 0,
                raw_json TEXT,
                created_at TEXT
            )
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS dicom_measurement_candidates (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                patient_key TEXT,
                visit_key TEXT,
                source_type TEXT,
                source_id TEXT,
                measurement_name TEXT,
                measurement_value TEXT,
                unit TEXT,
                confidence REAL DEFAULT 0,
                needs_doctor_review INTEGER DEFAULT 1,
                doctor_approved INTEGER DEFAULT 0,
                raw_text TEXT,
                raw_json TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)
        con.execute("""
            CREATE UNIQUE INDEX IF NOT EXISTS ux_dicom_measurement_source
            ON dicom_measurement_candidates(
                source_type, source_id, measurement_name, measurement_value
            )
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS dicom_ai_reviews (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                patient_key TEXT,
                visit_key TEXT,
                orthanc_study_id TEXT,
                review_type TEXT,
                model_name TEXT,
                result_json TEXT,
                result_text TEXT,
                confidence REAL DEFAULT 0,
                doctor_approved INTEGER DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS dicom_media_quality_scores (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                patient_key TEXT,
                media_source TEXT,
                media_id TEXT,
                media_path TEXT,
                fetus_score REAL DEFAULT 0,
                face_score REAL DEFAULT 0,
                quality_score REAL DEFAULT 0,
                blur_score REAL DEFAULT 0,
                best_frame INTEGER DEFAULT 0,
                result_json TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS dicom_private_tag_reports (
                orthanc_instance_id TEXT PRIMARY KEY,
                orthanc_series_id TEXT,
                patient_key TEXT,
                private_creator_list TEXT,
                private_tag_count INTEGER DEFAULT 0,
                text_probe_count INTEGER DEFAULT 0,
                decoded_measurement_count INTEGER DEFAULT 0,
                has_4dview_payload INTEGER DEFAULT 0,
                summary_json TEXT,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)
        con.execute("CREATE INDEX IF NOT EXISTS idx_dicom_studies_patient ON dicom_studies(patient_key, study_date DESC)")
        con.execute("CREATE INDEX IF NOT EXISTS idx_dicom_studies_visit ON dicom_studies(patient_key, visit_key, study_date DESC)")
        con.execute("CREATE INDEX IF NOT EXISTS idx_dicom_studies_accession ON dicom_studies(accession_number)")
        con.execute("CREATE INDEX IF NOT EXISTS idx_dicom_series_study ON dicom_series(orthanc_study_id)")
        con.execute("CREATE INDEX IF NOT EXISTS idx_dicom_instances_series ON dicom_instances(orthanc_series_id)")
        con.execute("CREATE INDEX IF NOT EXISTS idx_dicom_measure_patient ON dicom_measurement_candidates(patient_key, created_at DESC)")
        con.execute("CREATE INDEX IF NOT EXISTS idx_dicom_ai_patient ON dicom_ai_reviews(patient_key, created_at DESC)")
        con.execute("CREATE INDEX IF NOT EXISTS idx_dicom_private_patient ON dicom_private_tag_reports(patient_key, updated_at DESC)")
        try:
            _ensure_usg_measurement_dicom_columns(con)
        except Exception:
            pass
        con.commit()
    except Exception:
        try:
            con.rollback()
        except Exception:
            pass
        raise


def _dicom_ai_norm_text(value):
    text = str(value or "").replace("^", " ").replace("_", " ")
    text = re.sub(r"\bF\d{3,}[-\d]*\b", " ", text, flags=re.I)
    text = re.sub(r"\b\d{2,4}[-./]\d{1,2}[-./]\d{1,2}\b", " ", text)
    try:
        return _fold_search_text(text)
    except Exception:
        text = text.lower()
        table = str.maketrans("Ã§ÄŸÄ±Ã¶ÅŸÃ¼Ã‡ÄÄ°Ã–ÅÃœ", "cgiosuCGIOSU")
        return re.sub(r"\s+", " ", text.translate(table)).strip()


def _dicom_ai_patient_name_from_study(study):
    patient = (study or {}).get("PatientMainDicomTags") or {}
    raw = patient.get("PatientName") or (study or {}).get("PatientName") or ""
    return str(raw or "").replace("^", " ").strip()


def _dicom_ai_study_main(study):
    return (study or {}).get("MainDicomTags") or {}


def _dicom_ai_match_candidates_for_study(study, max_candidates=5):
    study = study or {}
    patient = study.get("PatientMainDicomTags") or {}
    main = study.get("MainDicomTags") or {}
    patient_id = str(patient.get("PatientID") or "").strip()
    dicom_name = _dicom_ai_patient_name_from_study(study)
    norm_name = _dicom_ai_norm_text(dicom_name)
    name_tokens = [t for t in norm_name.split() if len(t) >= 2]
    study_date = str(main.get("StudyDate") or "").strip()
    rows = []
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            _web_ensure_patient_demographics_schema_v1000(con)
            rows = con.execute("""
                SELECT p.folder_key, p.display_name, COALESCE(pp.protocol_no, '') AS protocol_no,
                       COALESCE(pd.canonical_name, '') AS canonical_name,
                       COALESCE(pd.dicom_patient_id, '') AS dicom_patient_id,
                       COALESCE(pd.dicom_patient_name, '') AS dicom_patient_name
                FROM patients p
                LEFT JOIN patient_protocols pp ON pp.patient_key=p.folder_key
                LEFT JOIN patient_demographics pd ON pd.patient_key=p.folder_key
                ORDER BY COALESCE(p.display_name, p.folder_key)
                LIMIT 8000
            """).fetchall()
    except Exception:
        rows = []
    scored = []
    for row in rows:
        key = str(row.get("folder_key") or "")
        display = _patient_display_label(
            key, row.get("canonical_name") or row.get("display_name") or key)
        dicom_pid = str(row.get("dicom_patient_id") or "").strip()
        dicom_pname = str(row.get("dicom_patient_name") or "").strip()
        blob = _dicom_ai_norm_text(" ".join([
            key, display, dicom_pid, dicom_pname, str(row.get("protocol_no") or "")
        ]))
        score = 0.0
        reasons = []
        if patient_id:
            pid_norm = _dicom_ai_norm_text(patient_id)
            if dicom_pid and _dicom_ai_norm_text(dicom_pid) == pid_norm:
                score += 0.72
                reasons.append("MWL PatientID")
            if pid_norm and pid_norm in blob:
                score += 0.45
                reasons.append("PatientID")
            if str(row.get("protocol_no") or "") and str(row.get("protocol_no")) == patient_id:
                score += 0.08
                reasons.append("protokol")
        if norm_name:
            if norm_name == _dicom_ai_norm_text(display):
                score += 0.55
                reasons.append("ad soyad birebir")
            elif dicom_pname and norm_name == _dicom_ai_norm_text(
                    str(dicom_pname).replace("^", " ")):
                score += 0.52
                reasons.append("MWL PatientName")
            elif name_tokens and all(t in blob for t in name_tokens):
                score += 0.46
                reasons.append("ad soyad token")
            elif name_tokens:
                hit = sum(1 for t in name_tokens if t in blob)
                if hit >= max(1, len(name_tokens) - 1):
                    score += 0.32
                    reasons.append("kismi ad")
        if study_date and len(study_date) == 8:
            folder_date = _patient_folder_date_label(key)
            folded_date = _dicom_ai_norm_text(folder_date)
            if study_date[2:4] in folded_date and study_date[4:6] in folded_date:
                score += 0.06
                reasons.append("tarih yakin")
        if score > 0:
            scored.append({
                "patient_key": key,
                "display_name": display,
                "score": round(min(score, 0.99), 3),
                "reason": ", ".join(reasons) or "benzerlik",
            })
    scored.sort(key=lambda item: (item["score"], item["display_name"]), reverse=True)
    return scored[:max(1, int(max_candidates or 5))]


def _dicom_ai_best_match_for_study(study):
    candidates = _dicom_ai_match_candidates_for_study(study, max_candidates=3)
    if not candidates:
        return {"patient_key": "", "confidence": 0.0, "reason": "eslesme yok", "candidates": []}
    best = candidates[0]
    return {
        "patient_key": best.get("patient_key") if best.get("score", 0) >= 0.58 else "",
        "confidence": float(best.get("score") or 0),
        "reason": best.get("reason") or "otomatik eslesme",
        "candidates": candidates,
    }


def _dicom_date_to_iso(value):
    raw = re.sub(r"\D", "", str(value or ""))
    if len(raw) >= 8:
        return f"{raw[:4]}-{raw[4:6]}-{raw[6:8]}"
    return _date_iso_from_text(value)


def _dicom_rowdict(row):
    if row is None:
        return {}
    try:
        return dict(row)
    except Exception:
        try:
            return {k: row[k] for k in row.keys()}
        except Exception:
            return {}


def _dicom_find_visit_for_study(con, patient_key, study_date="", accession_number=""):
    patient_key = str(patient_key or "").strip()
    if not patient_key:
        return ""
    date_iso = _dicom_date_to_iso(study_date)
    try:
        con.execute("SELECT 1 FROM visits LIMIT 1")
    except Exception:
        return ""
    if date_iso:
        try:
            row = con.execute("""
                SELECT visit_key FROM visits
                WHERE patient_folder_key=?
                  AND (visit_date LIKE ? OR visit_key LIKE ?)
                ORDER BY COALESCE(folder_mtime,0) DESC, visit_key DESC
                LIMIT 1
            """, (patient_key, f"{date_iso}%", f"%{date_iso.replace('-', '')}%")).fetchone()
            if row:
                return str(row[0] if not hasattr(row, "keys") else row["visit_key"] or "")
        except Exception:
            pass
    acc = str(accession_number or "")
    acc_date = _dicom_date_to_iso(acc)
    if acc_date:
        try:
            row = con.execute("""
                SELECT visit_key FROM visits
                WHERE patient_folder_key=?
                  AND (visit_date LIKE ? OR visit_key LIKE ?)
                ORDER BY COALESCE(folder_mtime,0) DESC, visit_key DESC
                LIMIT 1
            """, (patient_key, f"{acc_date}%", f"%{acc_date.replace('-', '')}%")).fetchone()
            if row:
                return str(row[0] if not hasattr(row, "keys") else row["visit_key"] or "")
        except Exception:
            pass
    try:
        row = con.execute("""
            SELECT visit_key FROM visits
            WHERE patient_folder_key=?
            ORDER BY COALESCE(visit_date,'' ) DESC, COALESCE(folder_mtime,0) DESC,
                     visit_key DESC
            LIMIT 1
        """, (patient_key,)).fetchone()
        if row:
            return str(row[0] if not hasattr(row, "keys") else row["visit_key"] or "")
    except Exception:
        pass
    return ""


def _dicom_worklist_match_for_study(con, study):
    study = study or {}
    patient = study.get("PatientMainDicomTags") or {}
    main = study.get("MainDicomTags") or {}
    accession = str(main.get("AccessionNumber") or "").strip()
    study_uid = str(main.get("StudyInstanceUID") or "").strip()
    patient_id = str(patient.get("PatientID") or "").strip()
    patient_name = str(patient.get("PatientName") or "").replace("^", " ").strip()
    study_date_iso = _dicom_date_to_iso(main.get("StudyDate") or "")
    try:
        _ensure_dicom_worklist_tables(con)
    except Exception:
        pass

    def _from_row(row, confidence, reason):
        item = _dicom_rowdict(row)
        pkey = str(item.get("patient_key") or "").strip()
        visit_key = str(item.get("visit_key") or "").strip()
        if not visit_key:
            visit_key = _dicom_find_visit_for_study(
                con, pkey, main.get("StudyDate") or "", accession)
        return {
            "patient_key": pkey,
            "visit_key": visit_key,
            "confidence": confidence,
            "reason": reason,
            "worklist_accession_number": str(item.get("accession_number") or ""),
            "worklist_export_id": str(item.get("id") or ""),
            "candidates": [{
                "patient_key": pkey,
                "display_name": _patient_display_label(pkey, item.get("patient_name") or pkey),
                "score": confidence,
                "reason": reason,
            }] if pkey else [],
        }

    queries = []
    if accession:
        queries.append(("""
            SELECT * FROM dicom_worklist_exports
            WHERE accession_number=?
            ORDER BY updated_at DESC LIMIT 1
        """, (accession,), 0.99, "Worklist AccessionNumber birebir"))
    if study_uid:
        queries.append(("""
            SELECT * FROM dicom_worklist_exports
            WHERE study_instance_uid=?
            ORDER BY updated_at DESC LIMIT 1
        """, (study_uid,), 0.97, "Worklist StudyInstanceUID birebir"))
    if patient_id and study_date_iso:
        queries.append(("""
            SELECT * FROM dicom_worklist_exports
            WHERE patient_id=? AND scheduled_date=?
            ORDER BY updated_at DESC LIMIT 1
        """, (patient_id, study_date_iso), 0.90, "Worklist PatientID + tarih"))
    if patient_id:
        queries.append(("""
            SELECT * FROM dicom_worklist_exports
            WHERE patient_id=?
            ORDER BY updated_at DESC LIMIT 1
        """, (patient_id,), 0.80, "Worklist PatientID"))
    if patient_name and study_date_iso:
        folded = _dicom_ai_norm_text(patient_name)
        try:
            rows = con.execute("""
                SELECT * FROM dicom_worklist_exports
                WHERE scheduled_date=?
                ORDER BY updated_at DESC LIMIT 200
            """, (study_date_iso,)).fetchall()
            for row in rows:
                item = _dicom_rowdict(row)
                if folded and folded == _dicom_ai_norm_text(item.get("patient_name") or ""):
                    return _from_row(row, 0.88, "Worklist PatientName + tarih")
        except Exception:
            pass

    for sql, params, confidence, reason in queries:
        try:
            row = con.execute(sql, params).fetchone()
            if row:
                return _from_row(row, confidence, reason)
        except Exception:
            continue
    return None


def _dicom_study_patient_match(study, con=None):
    if con is not None:
        wl_match = _dicom_worklist_match_for_study(con, study)
        if wl_match and wl_match.get("patient_key"):
            return wl_match
    match = _dicom_ai_best_match_for_study(study)
    if match.get("patient_key") and con is not None:
        main = (study or {}).get("MainDicomTags") or {}
        match["visit_key"] = _dicom_find_visit_for_study(
            con, match.get("patient_key"), main.get("StudyDate") or "",
            main.get("AccessionNumber") or "")
    return match


def _dicom_extract_measurements_from_text(text, source_type="text", source_id=""):
    text = str(text or "")
    if not text.strip():
        return []
    items = []
    for name, pattern in _DICOM_MEASUREMENT_PATTERNS.items():
        for m in re.finditer(pattern, text, flags=re.I):
            value = str(m.group(1) or "").strip().replace(",", ".")
            unit = ""
            if len(m.groups()) >= 2:
                unit = str(m.group(2) or "").strip()
            items.append({
                "source_type": source_type,
                "source_id": source_id,
                "measurement_name": name,
                "measurement_value": value,
                "unit": unit,
                "confidence": 0.72 if source_type == "pdf" else 0.48,
                "raw_text": m.group(0),
            })
    return items


def _dicom_entry_value_text(value, limit=2400):
    if value is None:
        return ""
    if isinstance(value, dict):
        if "Value" in value:
            return _dicom_entry_value_text(value.get("Value"), limit=limit)
        chunks = []
        for v in value.values():
            text = _dicom_entry_value_text(v, limit=limit)
            if text:
                chunks.append(text)
        return " ".join(chunks)[:limit]
    if isinstance(value, (list, tuple)):
        chunks = []
        for v in value:
            text = _dicom_entry_value_text(v, limit=limit)
            if text:
                chunks.append(text)
        return " ".join(chunks)[:limit]
    return str(value or "").replace("\x00", " ").strip()[:limit]


def _dicom_tag_name(entry):
    if not isinstance(entry, dict):
        return ""
    return str(entry.get("Name") or entry.get("name") or "").strip()


def _dicom_find_tag_entry(node, names):
    if not isinstance(node, dict):
        return None
    wanted = {str(x).lower().replace(" ", "") for x in (names or []) if x}
    for tag, entry in node.items():
        if not isinstance(entry, dict):
            continue
        keys = {
            str(tag or "").lower().replace(" ", ""),
            _dicom_tag_name(entry).lower().replace(" ", ""),
        }
        if keys & wanted:
            return entry
    return None


def _dicom_sequence_items(node, names):
    entry = _dicom_find_tag_entry(node, names)
    if not isinstance(entry, dict):
        return []
    value = entry.get("Value")
    if isinstance(value, dict):
        return [value]
    if isinstance(value, list):
        return [item for item in value if isinstance(item, dict)]
    return []


def _dicom_walk_orthanc_nodes(obj):
    if isinstance(obj, dict):
        if any(isinstance(v, dict) and ("Name" in v or "Value" in v)
               for v in obj.values()):
            yield obj
        for value in obj.values():
            if isinstance(value, dict):
                if "Value" in value:
                    yield from _dicom_walk_orthanc_nodes(value.get("Value"))
                else:
                    yield from _dicom_walk_orthanc_nodes(value)
            elif isinstance(value, list):
                for item in value:
                    yield from _dicom_walk_orthanc_nodes(item)
    elif isinstance(obj, list):
        for item in obj:
            yield from _dicom_walk_orthanc_nodes(item)


def _dicom_sr_label_to_measurement(label):
    text = str(label or "")
    if not text.strip():
        return ""
    for name, pattern in _DICOM_SR_LABEL_PATTERNS:
        if re.search(pattern, text, flags=re.I):
            return name
    return ""


def _dicom_sr_item_value(item, names):
    entry = _dicom_find_tag_entry(item, names)
    if not isinstance(entry, dict):
        return ""
    return _dicom_entry_value_text(entry.get("Value"))


def _dicom_extract_measurements_from_report_tags(tags, full_tags=None,
                                                 source_type="dicom-sr",
                                                 source_id=""):
    """Extract SR/REPORT measurements from Orthanc full tags, then text fallback."""
    source_id = str(source_id or "")
    full_tags = full_tags if isinstance(full_tags, dict) else {}
    tags = tags if isinstance(tags, dict) else {}
    found = []
    for node in _dicom_walk_orthanc_nodes(full_tags or tags):
        measured_items = _dicom_sequence_items(
            node, ("MeasuredValueSequence", "0040,a300", "0040,A300"))
        if not measured_items:
            continue
        concept_items = _dicom_sequence_items(
            node, ("ConceptNameCodeSequence", "0040,a043", "0040,A043"))
        concept_text = ""
        if concept_items:
            concept_text = " ".join(filter(None, [
                _dicom_sr_item_value(concept_items[0], ("CodeMeaning", "0008,0104")),
                _dicom_sr_item_value(concept_items[0], ("CodeValue", "0008,0100")),
            ]))
        context_text = _dicom_entry_value_text(node, limit=1200)
        measure_name = _dicom_sr_label_to_measurement(
            f"{concept_text} {context_text}")
        if not measure_name:
            continue
        for measured in measured_items:
            value = _dicom_sr_item_value(
                measured, ("NumericValue", "0040,a30a", "0040,A30A"))
            if not value:
                continue
            unit_items = _dicom_sequence_items(
                measured, ("MeasurementUnitsCodeSequence", "0040,08ea", "0040,08EA"))
            unit = ""
            if unit_items:
                unit = (
                    _dicom_sr_item_value(unit_items[0], ("CodeMeaning", "0008,0104"))
                    or _dicom_sr_item_value(unit_items[0], ("CodeValue", "0008,0100"))
                )
            found.append({
                "source_type": source_type,
                "source_id": source_id,
                "measurement_name": measure_name,
                "measurement_value": str(value).strip().replace(",", "."),
                "unit": str(unit or "").strip(),
                "confidence": 0.92,
                "raw_text": f"{concept_text} {value} {unit}".strip(),
            })
    raw_text = json.dumps(full_tags or tags, ensure_ascii=False, default=str)
    fallback = _dicom_extract_measurements_from_text(
        raw_text, source_type=source_type, source_id=source_id)
    for item in fallback:
        item["confidence"] = max(float(item.get("confidence") or 0), 0.70)
    return _dicom_dedupe_measurement_candidates(found + fallback)


def _dicom_dedupe_measurement_candidates(items):
    seen = set()
    clean = []
    for item in items or []:
        name = str(item.get("measurement_name") or "").strip().upper()
        value = str(item.get("measurement_value") or "").strip().replace(",", ".")
        unit = str(item.get("unit") or "").strip().lower()
        source_id = str(item.get("source_id") or "")
        if not name or not value:
            continue
        key = (name, value, unit, source_id)
        if key in seen:
            continue
        seen.add(key)
        row = dict(item)
        row["measurement_name"] = name
        row["measurement_value"] = value
        row["unit"] = unit
        clean.append(row)
    return clean


def _dicom_is_report_instance(tags=None, series_modality="", full_tags=None):
    raw = json.dumps(tags or {}, ensure_ascii=False, default=str).lower()
    if full_tags:
        raw += " " + json.dumps(full_tags or {}, ensure_ascii=False, default=str).lower()
    modality = str(series_modality or (tags or {}).get("Modality") or "").strip().upper()
    sop = str((tags or {}).get("SOPClassUID") or "").strip()
    return bool(
        modality == "SR"
        or sop.startswith("1.2.840.10008.5.1.4.1.1.88.")
        or "structured report" in raw
        or "comprehensive sr" in raw
        or "measurement report" in raw
    )


def _dicom_numeric(value):
    try:
        return float(str(value or "").replace(",", ".").strip())
    except Exception:
        return None


def _dicom_measurement_value_for_column(name, value, unit):
    name = str(name or "").upper()
    unit = str(unit or "").strip().lower()
    number = _dicom_numeric(value)
    if number is None:
        return None
    if name in {"BPD", "HC", "AC", "FL", "CRL", "NT", "GS", "YS"}:
        if unit in {"cm", "centimeter", "centimetre"}:
            number *= 10.0
        return round(number, 2)
    if name == "AFI":
        if unit in {"mm", "millimeter", "millimetre"}:
            number /= 10.0
        return round(number, 2)
    if name == "EFW":
        return int(round(number))
    if name == "FHR":
        return int(round(number))
    if name == "MCA_PSV" and unit in {"m/s", "meter/second", "metre/second"}:
        number *= 100.0
    return round(number, 3)


def _dicom_parse_ga(value):
    text = str(value or "").strip().lower().replace(" ", "")
    m = re.search(r"(\d{1,2})(?:w|hf|\+)(\d?)", text)
    if m:
        return int(m.group(1)), int(m.group(2) or 0)
    m = re.search(r"(\d{1,2})", text)
    if m:
        return int(m.group(1)), 0
    return None, None


def _ensure_usg_measurement_dicom_columns(con=None):
    def _run(open_con):
        open_con.execute("""
            CREATE TABLE IF NOT EXISTS usg_measurements (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                patient_key TEXT NOT NULL,
                usg_date TEXT NOT NULL,
                ga_weeks INTEGER,
                ga_days INTEGER,
                bpd REAL, hc REAL, ac REAL, fl REAL,
                crl REAL, nt REAL,
                efw INTEGER,
                afi REAL,
                placenta TEXT,
                fetal_position TEXT,
                notes TEXT,
                created_by TEXT,
                created_at TEXT NOT NULL
            )
        """)
        for column, ddl in (
            ("visit_key", "ALTER TABLE usg_measurements ADD COLUMN visit_key TEXT"),
            ("fhr", "ALTER TABLE usg_measurements ADD COLUMN fhr REAL"),
            ("ua_pi", "ALTER TABLE usg_measurements ADD COLUMN ua_pi REAL"),
            ("ua_ri", "ALTER TABLE usg_measurements ADD COLUMN ua_ri REAL"),
            ("ua_sd", "ALTER TABLE usg_measurements ADD COLUMN ua_sd REAL"),
            ("mca_pi", "ALTER TABLE usg_measurements ADD COLUMN mca_pi REAL"),
            ("mca_ri", "ALTER TABLE usg_measurements ADD COLUMN mca_ri REAL"),
            ("mca_psv", "ALTER TABLE usg_measurements ADD COLUMN mca_psv REAL"),
            ("uta_pi", "ALTER TABLE usg_measurements ADD COLUMN uta_pi REAL"),
            ("uta_ri", "ALTER TABLE usg_measurements ADD COLUMN uta_ri REAL"),
            ("dv_pi", "ALTER TABLE usg_measurements ADD COLUMN dv_pi REAL"),
            ("cpr", "ALTER TABLE usg_measurements ADD COLUMN cpr REAL"),
            ("source_type", "ALTER TABLE usg_measurements ADD COLUMN source_type TEXT"),
            ("source_study_id", "ALTER TABLE usg_measurements ADD COLUMN source_study_id TEXT"),
            ("source_instance_id", "ALTER TABLE usg_measurements ADD COLUMN source_instance_id TEXT"),
            ("source_accession_number", "ALTER TABLE usg_measurements ADD COLUMN source_accession_number TEXT"),
        ):
            try:
                open_con.execute(ddl)
            except Exception:
                pass
        open_con.execute("""
            CREATE INDEX IF NOT EXISTS idx_usg_dicom_source
            ON usg_measurements(patient_key, source_instance_id, source_study_id)
        """)
    if con is not None:
        _run(con)
        return
    with db_conn() as open_con:
        _run(open_con)
        open_con.commit()


_DICOM_USG_COLUMN_MAP = {
    "BPD": "bpd", "HC": "hc", "AC": "ac", "FL": "fl",
    "CRL": "crl", "NT": "nt", "EFW": "efw", "AFI": "afi",
    "FHR": "fhr", "UA_PI": "ua_pi", "UA_RI": "ua_ri", "UA_SD": "ua_sd",
    "MCA_PI": "mca_pi", "MCA_RI": "mca_ri", "MCA_PSV": "mca_psv",
    "UTA_PI": "uta_pi", "UTA_RI": "uta_ri", "DV_PI": "dv_pi", "CPR": "cpr",
}


def _dicom_upsert_usg_measurement_from_candidates(
        con, patient_key, candidates, visit_key="", study_date="",
        study_id="", instance_id="", accession_number="", source_type="dicom-sr"):
    patient_key = str(patient_key or "").strip()
    if not patient_key:
        return 0
    _ensure_usg_measurement_dicom_columns(con)
    values = {}
    seen_names = []
    for item in candidates or []:
        name = str(item.get("measurement_name") or "").strip().upper()
        if name == "GA":
            weeks, days = _dicom_parse_ga(item.get("measurement_value"))
            if weeks is not None:
                values["ga_weeks"] = weeks
                values["ga_days"] = days or 0
                seen_names.append("GA")
            continue
        column = _DICOM_USG_COLUMN_MAP.get(name)
        if not column:
            continue
        val = _dicom_measurement_value_for_column(
            name, item.get("measurement_value"), item.get("unit"))
        if val is None:
            continue
        values[column] = val
        seen_names.append(name)
    if not values:
        return 0
    usg_date = _dicom_date_to_iso(study_date) or datetime.now().strftime("%Y-%m-%d")
    now = datetime.now().isoformat(sep=" ", timespec="seconds")
    source_type = str(source_type or "dicom-sr")
    instance_id = str(instance_id or "")
    study_id = str(study_id or "")
    accession_number = str(accession_number or "")
    visit_key = str(visit_key or "")
    row = None
    if instance_id:
        row = con.execute("""
            SELECT id FROM usg_measurements
            WHERE patient_key=? AND source_instance_id=?
            LIMIT 1
        """, (patient_key, instance_id)).fetchone()
    if not row and study_id:
        row = con.execute("""
            SELECT id FROM usg_measurements
            WHERE patient_key=? AND source_study_id=? AND usg_date=?
            LIMIT 1
        """, (patient_key, study_id, usg_date)).fetchone()
    notes = (
        "DICOM REPORT/SR olcumleri hasta dosyasina eslendi; "
        "doktor onayi bekleyen aday: " + ", ".join(sorted(set(seen_names)))
    )
    meta_values = {
        "patient_key": patient_key,
        "usg_date": usg_date,
        "visit_key": visit_key,
        "source_type": source_type,
        "source_study_id": study_id,
        "source_instance_id": instance_id,
        "source_accession_number": accession_number,
        "notes": notes,
        "created_by": "dicom",
        "created_at": now,
    }
    if row:
        row_id = row["id"] if hasattr(row, "keys") else row[0]
        update_values = dict(values)
        update_values.update({
            "visit_key": visit_key,
            "source_type": source_type,
            "source_study_id": study_id,
            "source_instance_id": instance_id,
            "source_accession_number": accession_number,
            "notes": notes,
        })
        sets = ", ".join(f"{col}=?" for col in update_values.keys())
        con.execute(
            f"UPDATE usg_measurements SET {sets} WHERE id=?",
            list(update_values.values()) + [row_id])
        return 0
    insert_values = dict(meta_values)
    insert_values.update(values)
    cols = list(insert_values.keys())
    placeholders = ", ".join("?" for _ in cols)
    con.execute(
        f"INSERT INTO usg_measurements({', '.join(cols)}) VALUES({placeholders})",
        [insert_values[c] for c in cols])
    return 1


def _dicom_tags_flags(tags):
    raw = json.dumps(tags or {}, ensure_ascii=False, default=str).lower()
    return {
        "has_us_region": 1 if (
            "sequenceofultrasoundregions" in raw
            or "ultrasound region" in raw
            or "0018,6011" in raw
        ) else 0,
        "has_kretz_private": 1 if (
            "kretz" in raw or "ge medical" in raw or "voluson" in raw
            or "7fe1" in raw or "7fe3" in raw
        ) else 0,
        "has_structured_measurement": 1 if (
            "structured report" in raw or "measurement report" in raw
            or "sr document" in raw
        ) else 0,
    }


def _dicom_insert_measurement_candidates(con, patient_key, candidates,
                                         visit_key="", raw_json=None):
    inserted = 0
    now = datetime.now().isoformat(timespec="seconds")
    for item in candidates or []:
        name = str(item.get("measurement_name") or "").strip()
        value = str(item.get("measurement_value") or "").strip()
        if not name or not value:
            continue
        try:
            cur = con.execute("""
                INSERT OR IGNORE INTO dicom_measurement_candidates(
                    patient_key, visit_key, source_type, source_id,
                    measurement_name, measurement_value, unit, confidence,
                    needs_doctor_review, raw_text, raw_json, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?)
            """, (
                patient_key,
                visit_key,
                str(item.get("source_type") or "unknown"),
                str(item.get("source_id") or ""),
                name,
                value,
                str(item.get("unit") or ""),
                float(item.get("confidence") or 0),
                str(item.get("raw_text") or ""),
                json.dumps(raw_json if raw_json is not None else item,
                           ensure_ascii=True, default=str),
                now,
            ))
            inserted += int(cur.rowcount or 0)
        except Exception:
            continue
    return inserted


def _dicom_private_compact_json(analysis):
    analysis = dict(analysis or {})
    compact = {
        "source": analysis.get("source") or "",
        "source_id": analysis.get("source_id") or "",
        "private_creators": list(analysis.get("private_creators") or [])[:24],
        "private_tag_count": int(analysis.get("private_tag_count") or 0),
        "text_probe_count": int(analysis.get("text_probe_count") or 0),
        "decoded_measurement_count": int(analysis.get("decoded_measurement_count") or 0),
        "has_4dview_payload": bool(analysis.get("has_4dview_payload")),
        "text_samples": list(analysis.get("text_samples") or [])[:16],
        "errors": list(analysis.get("errors") or [])[:6],
        "candidate_count": len(analysis.get("candidates") or []),
    }
    return compact


def _dicom_store_private_report(con, patient_key, series_id, instance_id, analysis):
    if not instance_id:
        return 0
    analysis = dict(analysis or {})
    creators = ", ".join(str(x) for x in (analysis.get("private_creators") or [])[:24])
    now = datetime.now().isoformat(timespec="seconds")
    cur = con.execute("""
        INSERT INTO dicom_private_tag_reports(
            orthanc_instance_id, orthanc_series_id, patient_key,
            private_creator_list, private_tag_count, text_probe_count,
            decoded_measurement_count, has_4dview_payload,
            summary_json, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(orthanc_instance_id) DO UPDATE SET
            orthanc_series_id=excluded.orthanc_series_id,
            patient_key=excluded.patient_key,
            private_creator_list=excluded.private_creator_list,
            private_tag_count=excluded.private_tag_count,
            text_probe_count=excluded.text_probe_count,
            decoded_measurement_count=excluded.decoded_measurement_count,
            has_4dview_payload=excluded.has_4dview_payload,
            summary_json=excluded.summary_json,
            updated_at=excluded.updated_at
    """, (
        str(instance_id),
        str(series_id or ""),
        str(patient_key or ""),
        creators,
        int(analysis.get("private_tag_count") or 0),
        int(analysis.get("text_probe_count") or 0),
        int(analysis.get("decoded_measurement_count") or 0),
        1 if analysis.get("has_4dview_payload") else 0,
        json.dumps(_dicom_private_compact_json(analysis),
                   ensure_ascii=True, default=str),
        now,
    ))
    return int(cur.rowcount or 0)


def _dicom_private_scan_instance(instance_id, tags=None, download=False):
    instance_id = str(instance_id or "").strip()
    if not instance_id:
        return {"candidates": [], "error": "instance_id yok"}
    tag_analysis = {}
    file_analysis = {}
    try:
        full_tags = _orthanc_api_json(
            f"/instances/{quote(instance_id, safe='')}/tags",
            timeout=14) or {}
        tag_analysis = _yk_analyze_orthanc_tags(
            full_tags or tags or {}, source_id=instance_id)
    except Exception as ex:
        tag_analysis = _yk_analyze_orthanc_tags(
            tags or {}, source_id=instance_id)
        tag_analysis["error"] = f"full tag okunamadi: {ex}"
    if download:
        try:
            raw = _orthanc_api_bytes(
                f"/instances/{quote(instance_id, safe='')}/file",
                timeout=24,
                max_bytes=32 * 1024 * 1024)
            file_analysis = _yk_analyze_dicom_bytes(raw, source_id=instance_id)
        except Exception as ex:
            file_analysis = {"error": f"dicom file okunamadi: {ex}",
                             "candidates": [], "source_id": instance_id}
    return _yk_merge_private_analyses(tag_analysis, file_analysis)


def _dicom_sync_from_orthanc(limit=120, detail=True, instance_cap=1200,
                            private_scan_cap=120, private_download_cap=0):
    import json as _json

    limit = max(1, min(int(limit or 120), 500))
    instance_cap = max(0, min(int(1200 if instance_cap is None else instance_cap), 5000))
    private_scan_cap = max(0, min(int(private_scan_cap or 0), 2000))
    private_download_cap = max(0, min(int(private_download_cap or 0), 500))
    studies = _orthanc_api_json(
        f"/studies?expand&since=0&limit={limit}", timeout=25) or []
    now = datetime.now().isoformat(timespec="seconds")
    result = {
        "ok": True,
        "studies_seen": len(studies),
        "studies_synced": 0,
        "series_synced": 0,
        "instances_synced": 0,
        "measurement_candidates": 0,
        "private_reports": 0,
        "private_scanned": 0,
        "private_downloaded": 0,
        "private_measurement_candidates": 0,
        "sr_measurements_linked": 0,
        "usg_measurement_rows": 0,
        "matched": 0,
        "worklist_matched": 0,
        "sr_found": 0,
        "instance_cap": instance_cap,
        "private_scan_cap": private_scan_cap,
        "private_download_cap": private_download_cap,
    }
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        _ensure_dicom_ai_tables(con)
        _ensure_dicom_worklist_tables(con)
        for study in studies:
            study_id = str(study.get("ID") or "").strip()
            if not study_id:
                continue
            main = study.get("MainDicomTags") or {}
            patient = study.get("PatientMainDicomTags") or {}
            match = _dicom_study_patient_match(study, con)
            match_patient_key = match.get("patient_key") or ""
            match_visit_key = match.get("visit_key") or ""
            if match_patient_key:
                result["matched"] += 1
            if match.get("worklist_accession_number"):
                result["worklist_matched"] += 1
            con.execute("""
                INSERT INTO dicom_studies(
                    orthanc_study_id, study_instance_uid, patient_name,
                    patient_id, study_date, study_time, accession_number,
                    institution_name, raw_json, patient_key,
                    visit_key, worklist_accession_number,
                    matched_confidence, match_reason, created_at, updated_at,
                    last_synced_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(orthanc_study_id) DO UPDATE SET
                    study_instance_uid=excluded.study_instance_uid,
                    patient_name=excluded.patient_name,
                    patient_id=excluded.patient_id,
                    study_date=excluded.study_date,
                    study_time=excluded.study_time,
                    accession_number=excluded.accession_number,
                    institution_name=excluded.institution_name,
                    raw_json=excluded.raw_json,
                    patient_key=COALESCE(NULLIF(dicom_studies.patient_key, ''), excluded.patient_key),
                    visit_key=COALESCE(NULLIF(dicom_studies.visit_key, ''), excluded.visit_key),
                    worklist_accession_number=COALESCE(NULLIF(dicom_studies.worklist_accession_number, ''), excluded.worklist_accession_number),
                    matched_confidence=excluded.matched_confidence,
                    match_reason=excluded.match_reason,
                    updated_at=excluded.updated_at,
                    last_synced_at=excluded.last_synced_at
            """, (
                study_id,
                str(main.get("StudyInstanceUID") or ""),
                str(patient.get("PatientName") or "").replace("^", " "),
                str(patient.get("PatientID") or ""),
                str(main.get("StudyDate") or ""),
                str(main.get("StudyTime") or ""),
                str(main.get("AccessionNumber") or ""),
                str(main.get("InstitutionName") or ""),
                _json.dumps(study, ensure_ascii=True, default=str),
                match_patient_key,
                match_visit_key,
                match.get("worklist_accession_number") or "",
                float(match.get("confidence") or 0),
                match.get("reason") or "",
                now,
                now,
                now,
            ))
            if match.get("worklist_accession_number"):
                try:
                    con.execute("""
                        UPDATE dicom_worklist_exports
                        SET matched_study_id=?, matched_at=?, status='matched',
                            last_message=?, updated_at=?
                        WHERE accession_number=?
                           OR (study_instance_uid<>'' AND study_instance_uid=?)
                    """, (
                        study_id,
                        now,
                        "Voluson'dan gelen DICOM study YazKlinik hastasina baglandi.",
                        now,
                        match.get("worklist_accession_number") or "",
                        str(main.get("StudyInstanceUID") or ""),
                    ))
                except Exception:
                    pass
            result["studies_synced"] += 1
            if not detail:
                continue
            for series_id in list(study.get("Series") or []):
                try:
                    series = _orthanc_api_json(
                        f"/series/{quote(str(series_id), safe='')}",
                        timeout=8) or {}
                except Exception:
                    continue
                smain = series.get("MainDicomTags") or {}
                instances = list(series.get("Instances") or [])
                con.execute("""
                    INSERT INTO dicom_series(
                        orthanc_series_id, orthanc_study_id,
                        series_instance_uid, modality, series_number,
                        series_description, instance_count, raw_json, created_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT(orthanc_series_id) DO UPDATE SET
                        orthanc_study_id=excluded.orthanc_study_id,
                        series_instance_uid=excluded.series_instance_uid,
                        modality=excluded.modality,
                        series_number=excluded.series_number,
                        series_description=excluded.series_description,
                        instance_count=excluded.instance_count,
                        raw_json=excluded.raw_json
                """, (
                    str(series_id),
                    study_id,
                    str(smain.get("SeriesInstanceUID") or ""),
                    str(smain.get("Modality") or ""),
                    str(smain.get("SeriesNumber") or ""),
                    str(smain.get("SeriesDescription") or ""),
                    len(instances),
                    _json.dumps(series, ensure_ascii=True, default=str),
                    now,
                ))
                result["series_synced"] += 1
                for instance_id in instances:
                    if result["instances_synced"] >= instance_cap:
                        break
                    instance_id = str(instance_id)
                    try:
                        tags = _orthanc_api_json(
                            f"/instances/{quote(instance_id, safe='')}/simplified-tags",
                            timeout=8) or {}
                    except Exception:
                        tags = {}
                    flags = _dicom_tags_flags(tags)
                    is_report = _dicom_is_report_instance(
                        tags, series_modality=smain.get("Modality") or "")
                    if is_report:
                        flags["has_structured_measurement"] = 1
                    result["sr_found"] += int(flags.get("has_structured_measurement") or 0)
                    con.execute("""
                        INSERT INTO dicom_instances(
                            orthanc_instance_id, orthanc_series_id,
                            sop_instance_uid, sop_class_uid, instance_number,
                            image_type, rows, columns, pixel_spacing,
                            has_us_region, has_kretz_private,
                            has_structured_measurement, raw_json, created_at
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        ON CONFLICT(orthanc_instance_id) DO UPDATE SET
                            orthanc_series_id=excluded.orthanc_series_id,
                            sop_instance_uid=excluded.sop_instance_uid,
                            sop_class_uid=excluded.sop_class_uid,
                            instance_number=excluded.instance_number,
                            image_type=excluded.image_type,
                            rows=excluded.rows,
                            columns=excluded.columns,
                            pixel_spacing=excluded.pixel_spacing,
                            has_us_region=excluded.has_us_region,
                            has_kretz_private=excluded.has_kretz_private,
                            has_structured_measurement=excluded.has_structured_measurement,
                            raw_json=excluded.raw_json
                    """, (
                        instance_id,
                        str(series_id),
                        str(tags.get("SOPInstanceUID") or ""),
                        str(tags.get("SOPClassUID") or ""),
                        str(tags.get("InstanceNumber") or ""),
                        str(tags.get("ImageType") or ""),
                        int(float(tags.get("Rows") or 0) if str(tags.get("Rows") or "").replace(".", "", 1).isdigit() else 0),
                        int(float(tags.get("Columns") or 0) if str(tags.get("Columns") or "").replace(".", "", 1).isdigit() else 0),
                        str(tags.get("PixelSpacing") or ""),
                        int(flags.get("has_us_region") or 0),
                        int(flags.get("has_kretz_private") or 0),
                        int(flags.get("has_structured_measurement") or 0),
                        _json.dumps(tags, ensure_ascii=True, default=str),
                        now,
                    ))
                    result["instances_synced"] += 1
                    if match_patient_key:
                        full_tags = {}
                        source_type = "dicom-sr" if is_report else "dicom-meta"
                        if is_report:
                            try:
                                full_tags = _orthanc_api_json(
                                    f"/instances/{quote(instance_id, safe='')}/tags",
                                    timeout=14) or {}
                            except Exception:
                                full_tags = {}
                        if is_report:
                            candidates = _dicom_extract_measurements_from_report_tags(
                                tags, full_tags,
                                source_type=source_type,
                                source_id=instance_id)
                        else:
                            candidates = _dicom_extract_measurements_from_text(
                                _json.dumps(tags, ensure_ascii=False, default=str),
                                source_type=source_type,
                                source_id=instance_id)
                        inserted = _dicom_insert_measurement_candidates(
                            con, match_patient_key, candidates,
                            visit_key=match_visit_key, raw_json=full_tags or tags)
                        result["measurement_candidates"] += inserted
                        if candidates:
                            result["sr_measurements_linked"] += len(candidates) if is_report else 0
                            result["usg_measurement_rows"] += _dicom_upsert_usg_measurement_from_candidates(
                                con, match_patient_key, candidates,
                                visit_key=match_visit_key,
                                study_date=main.get("StudyDate") or "",
                                study_id=study_id,
                                instance_id=instance_id,
                                accession_number=main.get("AccessionNumber") or "",
                                source_type=source_type)
                    scan_private = (
                        result["private_scanned"] < private_scan_cap
                        and (
                            flags.get("has_kretz_private")
                            or "voluson" in _json.dumps(
                                tags, ensure_ascii=False, default=str).lower()
                            or "ge healthcare" in _json.dumps(
                                tags, ensure_ascii=False, default=str).lower()
                        )
                    )
                    if scan_private:
                        download_private = (
                            result["private_downloaded"] < private_download_cap)
                        analysis = _dicom_private_scan_instance(
                            instance_id, tags=tags, download=download_private)
                        result["private_scanned"] += 1
                        if download_private:
                            result["private_downloaded"] += 1
                        result["private_reports"] += _dicom_store_private_report(
                            con, match_patient_key or "",
                            str(series_id), instance_id, analysis)
                        private_candidates = analysis.get("candidates") or []
                        if match_patient_key and private_candidates:
                            added = _dicom_insert_measurement_candidates(
                                con, match_patient_key, private_candidates,
                                visit_key=match_visit_key,
                                raw_json=_dicom_private_compact_json(analysis))
                            result["private_measurement_candidates"] += added
                            result["measurement_candidates"] += added
                            result["usg_measurement_rows"] += _dicom_upsert_usg_measurement_from_candidates(
                                con, match_patient_key, private_candidates,
                                visit_key=match_visit_key,
                                study_date=main.get("StudyDate") or "",
                                study_id=study_id,
                                instance_id=instance_id,
                                accession_number=main.get("AccessionNumber") or "",
                                source_type="dicom-private")
                if result["instances_synced"] >= instance_cap:
                    break
        con.commit()
    return result


def _dicom_patient_payload(patient_key, live=True, limit=80):
    _ensure_dicom_ai_tables()
    q_patient = str(patient_key or "")
    studies = []
    measurements = []
    reviews = []
    private_reports = []
    usg_rows = []
    stats = {}
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        studies = con.execute("""
            SELECT ds.*,
                   (SELECT COUNT(*) FROM dicom_series s
                    WHERE s.orthanc_study_id=ds.orthanc_study_id) AS series_count,
                   (SELECT COUNT(*) FROM dicom_instances i
                    JOIN dicom_series s ON s.orthanc_series_id=i.orthanc_series_id
                    WHERE s.orthanc_study_id=ds.orthanc_study_id) AS instance_count
            FROM dicom_studies ds
            WHERE ds.patient_key=?
            ORDER BY COALESCE(ds.study_date, '') DESC, ds.updated_at DESC
            LIMIT ?
        """, (q_patient, max(1, min(int(limit or 80), 300)))).fetchall()
        measurements = con.execute("""
            SELECT * FROM dicom_measurement_candidates
            WHERE patient_key=?
            ORDER BY doctor_approved DESC, created_at DESC, id DESC
            LIMIT 80
        """, (q_patient,)).fetchall()
        reviews = con.execute("""
            SELECT * FROM dicom_ai_reviews
            WHERE patient_key=?
            ORDER BY created_at DESC, id DESC
            LIMIT 12
        """, (q_patient,)).fetchall()
        private_reports = con.execute("""
            SELECT * FROM dicom_private_tag_reports
            WHERE patient_key=?
            ORDER BY updated_at DESC
            LIMIT 30
        """, (q_patient,)).fetchall()
        try:
            usg_rows = con.execute("""
                SELECT usg_date, ga_weeks, ga_days, bpd, hc, ac, fl, crl, nt, efw, afi,
                       fhr, ua_pi, ua_ri, ua_sd, mca_pi, mca_ri, mca_psv, uta_pi, uta_ri,
                       dv_pi, cpr, source_type, source_accession_number, source_study_id,
                       source_instance_id, notes, created_at
                FROM usg_measurements
                WHERE patient_key=?
                ORDER BY COALESCE(usg_date,'') DESC, COALESCE(created_at,'') DESC
                LIMIT 12
            """, (q_patient,)).fetchall()
        except Exception:
            usg_rows = []
        stats = {
            "studies": len(studies),
            "measurements": len(measurements),
            "reviews": len(reviews),
            "private_reports": len(private_reports),
            "usg_rows": len(usg_rows),
            "private_measurement_reports": sum(
                1 for row in private_reports
                if int(row.get("decoded_measurement_count") or 0) > 0),
            "approved_measurements": sum(
                1 for row in measurements if int(row.get("doctor_approved") or 0)),
        }
    live_candidates = []
    if live and not studies:
        try:
            all_studies = _orthanc_api_json(
                f"/studies?expand&since=0&limit={max(20, min(int(limit or 80), 120))}",
                timeout=20) or []
            for study in all_studies:
                match = _dicom_ai_best_match_for_study(study)
                if match.get("patient_key") == q_patient:
                    live_candidates.append({
                        "orthanc_study_id": study.get("ID") or "",
                        "study_instance_uid": (_dicom_ai_study_main(study)
                                               .get("StudyInstanceUID") or ""),
                        "patient_name": _dicom_ai_patient_name_from_study(study),
                        "patient_id": (study.get("PatientMainDicomTags") or {})
                                      .get("PatientID") or "",
                        "study_date": (_dicom_ai_study_main(study)
                                       .get("StudyDate") or ""),
                        "study_time": (_dicom_ai_study_main(study)
                                       .get("StudyTime") or ""),
                        "raw_json": json.dumps(study, ensure_ascii=True, default=str),
                        "series_count": len(study.get("Series") or []),
                        "instance_count": 0,
                        "matched_confidence": match.get("confidence") or 0,
                        "match_reason": "canli aday: " + (match.get("reason") or ""),
                    })
        except Exception:
            live_candidates = []
    return {
        "ok": True,
        "patient_key": q_patient,
        "guardrail": _DICOM_AI_GUARDRAIL,
        "studies": [dict(r) for r in studies] + live_candidates,
        "measurements": [dict(r) for r in measurements],
        "reviews": [dict(r) for r in reviews],
        "private_reports": [dict(r) for r in private_reports],
        "usg_rows": [dict(r) for r in usg_rows],
        "stats": stats,
        "live_candidates": len(live_candidates),
    }


def _dicom_pdf_measurement_candidates(patient_key):
    candidates = []
    try:
        pdf_info = _diet_collect_pdf_fetal_info_v1000(
            patient_key, max_pdfs=8, max_chars=24000) or {}
    except Exception:
        pdf_info = {}
    for item in (pdf_info.get("items") or []):
        source_name = item.get("source_name") or item.get("source") or "PDF"
        for key, label, unit in (
            ("efw_g", "EFW", "g"),
            ("afi", "AFI", "cm"),
            ("bpd", "BPD", "mm"),
            ("hc", "HC", "mm"),
            ("ac", "AC", "mm"),
            ("fl", "FL", "mm"),
        ):
            if item.get(key) is not None:
                candidates.append({
                    "source_type": "pdf",
                    "source_id": source_name,
                    "measurement_name": label,
                    "measurement_value": str(item.get(key)),
                    "unit": unit,
                    "confidence": 0.82,
                    "raw_text": f"{label}: {item.get(key)} {unit}".strip(),
                })
        if item.get("ga_w") is not None:
            candidates.append({
                "source_type": "pdf",
                "source_id": source_name,
                "measurement_name": "GA",
                "measurement_value": f"{item.get('ga_w')}+{item.get('ga_d') or 0}",
                "unit": "hf",
                "confidence": 0.82,
                "raw_text": "PDF GA",
            })
        if item.get("edd_from_pdf"):
            candidates.append({
                "source_type": "pdf",
                "source_id": source_name,
                "measurement_name": "EDD",
                "measurement_value": str(item.get("edd_from_pdf")),
                "unit": "",
                "confidence": 0.82,
                "raw_text": "PDF EDD",
            })
    return candidates


def _dicom_ai_review_text(patient_key, payload, generated_text="", model_name=""):
    header = _get_patient_header_data(patient_key)
    display = header.get("display_name") or patient_key
    studies = payload.get("studies") or []
    measurements = payload.get("measurements") or []
    private_reports = payload.get("private_reports") or []
    lines = [
        f"Hasta: {display}",
        f"DICOM calisma sayisi: {len(studies)}",
        f"Olcum adayi: {len(measurements)}",
        f"GE/4DView private rapor: {len(private_reports)}",
        "Standart DICOM SR: Bu arÅŸivde genellikle yok; PDF/OCR/DICOM meta birlikte yorumlanir.",
        _DICOM_AI_GUARDRAIL,
    ]
    if studies:
        s = studies[0]
        lines.append(
            "Son DICOM: "
            f"{s.get('study_date') or '-'} / "
            f"{s.get('patient_name') or '-'} / "
            f"{s.get('series_count') or 0} seri"
        )
    approved = [m for m in measurements if int(m.get("doctor_approved") or 0)]
    if approved:
        lines.append("Onayli olcumler: " + ", ".join(
            f"{m.get('measurement_name')}={m.get('measurement_value')}{m.get('unit') or ''}"
            for m in approved[:8]))
    elif measurements:
        lines.append("Doktor onayi bekleyen olcum adaylari: " + ", ".join(
            f"{m.get('measurement_name')}={m.get('measurement_value')}{m.get('unit') or ''}"
            for m in measurements[:8]))
    else:
        lines.append("Olcum adayi bulunmadi; PDF rapor veya goruntu OCR gerekli.")
    if private_reports:
        decoded = sum(
            1 for row in private_reports
            if int(row.get("decoded_measurement_count") or 0) > 0)
        lines.append(
            f"GE/Kretz private analiz: {len(private_reports)} instance tarandi, "
            f"{decoded} instance icinde okunabilir olcum adayi bulundu.")
    if generated_text:
        lines.extend(["", "YZ notu:", generated_text.strip()])
    if model_name:
        lines.append(f"Model: {model_name}")
    return "\n".join(lines)


_ORTHANC_DASHBOARD_CACHE = {}
_ORTHANC_DASHBOARD_CACHE_TTL = 60.0


class _OrthancDashboardCacheHit(Exception):
    pass


def _filter_orthanc_studies_for_request(studies_data):
    patient_filter = (request.args.get("patient", "") or "").lower()
    if not patient_filter:
        return list(studies_data or [])
    patient_name = patient_filter
    try:
        with db_conn() as con:
            row = con.execute(
                "SELECT display_name FROM patients WHERE folder_key=?",
                (request.args.get("patient", ""),)).fetchone()
            if row and row[0]:
                patient_name = str(row[0]).lower()
    except Exception:
        pass
    tokens = [t for t in (
        patient_filter.replace("_", " ").split()
        + patient_name.replace("^", " ").split())
        if len(t) >= 2]
    return [
        s for s in list(studies_data or [])
        if any(t in (
            str(s.get("PatientMainDicomTags", {})).lower()
            + " "
            + str(s.get("MainDicomTags", {})).lower())
            for t in tokens)
    ]


def _orthanc_study_patient_match_map(studies_data):
    """Build DICOM study -> patient match map with one DB read."""
    studies = list(studies_data or [])
    if not studies:
        return {}
    try:
        with db_conn() as con:
            rows = con.execute(
                "SELECT folder_key, display_name FROM patients "
                "WHERE COALESCE(archived_at,'')=''").fetchall()
    except Exception:
        rows = []
    patients = []
    for row in rows:
        try:
            folder_key = str(row[0] or "")
            display_name = str(row[1] or "")
        except Exception:
            continue
        patients.append((folder_key, display_name,
                         folder_key.lower(), display_name.lower()))
    out = {}
    for study in studies:
        try:
            study_id = str(study.get("ID") or "")
            patient_main = study.get("PatientMainDicomTags", {}) or {}
            patient_id = str(patient_main.get("PatientID") or "").lower()
            patient_name = str(patient_main.get("PatientName") or "")
            patient_first = patient_name.split("^")[0].strip().lower()
        except Exception:
            continue
        if not study_id:
            continue
        for folder_key, display_name, folder_lc, display_lc in patients:
            if patient_id and patient_id in folder_lc:
                out[study_id] = (folder_key, display_name or folder_key)
                break
            if patient_first and patient_first in display_lc:
                out[study_id] = (folder_key, display_name or folder_key)
                break
    return out


def _save_orthanc_config(con, url=None, user=None, password=None):
    """Persist Orthanc settings to every legacy/current key used by the app."""
    current_url, current_user, current_pass, _ = _get_orthanc_config()
    new_url = str(url or current_url or "").strip().rstrip("/")
    new_user = str(user or current_user or "").strip()
    new_pass = str(password if password is not None else current_pass)
    if not new_pass:
        new_pass = current_pass or ORTHANC_PASS
    new_url, new_user, new_pass = _normalize_orthanc_config(
        new_url, new_user, new_pass)
    values = {
        "orthanc_url": new_url,
        "sysparam_orthanc_url": new_url,
        "orthanc/url": new_url,
        "orthanc_user": new_user,
        "sysparam_orthanc_user": new_user,
        "orthanc/user": new_user,
        "orthanc_pass": new_pass,
        "sysparam_orthanc_pass": new_pass,
        "orthanc/pass": new_pass,
    }
    con.execute("""
        CREATE TABLE IF NOT EXISTS settings (
            key TEXT PRIMARY KEY,
            value TEXT
        )
    """)
    for key, value in values.items():
        con.execute(
            "INSERT OR REPLACE INTO settings(key, value) VALUES(?, ?)",
            (key, value))
    return new_url, new_user, new_pass


def _ensure_orthanc_defaults_if_needed():
    """Make first run use the real clinic Orthanc instead of old localhost/admin."""
    try:
        with db_conn() as con:
            key_map = {
                "url": ("sysparam_orthanc_url", "orthanc_url", "orthanc/url"),
                "user": ("sysparam_orthanc_user", "orthanc_user",
                         "orthanc/user"),
                "pass": ("sysparam_orthanc_pass", "orthanc_pass",
                         "orthanc/pass"),
            }
            con.execute("""
                CREATE TABLE IF NOT EXISTS settings (
                    key TEXT PRIMARY KEY,
                    value TEXT
                )
            """)
            all_keys = [key for keys in key_map.values() for key in keys]
            rows = dict(con.execute(
                "SELECT key, value FROM settings "
                f"WHERE key IN ({','.join('?' for _ in all_keys)})",
                all_keys).fetchall())
            selected = {}
            for target, keys in key_map.items():
                fallback = ""
                for key in keys:
                    value = str(rows.get(key) or "").strip()
                    if not value:
                        continue
                    if not fallback:
                        fallback = value
                    if not _is_legacy_orthanc_value(target, value):
                        selected[target] = value
                        break
                else:
                    selected[target] = fallback
            normalized = _normalize_orthanc_config(
                selected.get("url"), selected.get("user"),
                selected.get("pass"))
            expected = {
                "url": normalized[0],
                "user": normalized[1],
                "pass": normalized[2],
            }
            must_save = not rows
            for target, keys in key_map.items():
                for key in keys:
                    value = str(rows.get(key) or "").strip()
                    if target == "url":
                        value = value.rstrip("/")
                    if value != expected[target]:
                        must_save = True
                        break
                if must_save:
                    break
            if must_save:
                _save_orthanc_config(con, *normalized)
                con.commit()
    except Exception:
        pass


@app.before_request
def _bootstrap_orthanc_defaults_once():
    if getattr(app, "_yazklinik_orthanc_defaults_checked", False):
        return
    app._yazklinik_orthanc_defaults_checked = True
    _ensure_orthanc_defaults_if_needed()


