@app.route("/api/orthanc/preflight-status", methods=["GET", "POST"])
@login_required
def api_orthanc_preflight_status():
    base = Path(__file__).resolve().parent
    status_path = base / "orthanc_preflight_status.json"
    script_path = base / "YazKlinik_Orthanc_Preflight.ps1"
    run_now = str(request.values.get("run") or "").lower() in {
        "1", "true", "evet", "yes", "run"}
    run_result = {
        "ran": False,
        "code": None,
        "error": "",
    }
    if run_now and script_path.exists():
        cmd = [
            "powershell",
            "-NoProfile",
            "-ExecutionPolicy",
            "Bypass",
            "-File",
            str(script_path),
        ]
        try:
            proc = subprocess.run(
                cmd,
                cwd=str(base),
                capture_output=True,
                text=True,
                timeout=90,
            )
            run_result["ran"] = True
            run_result["code"] = int(proc.returncode or 0)
            if proc.returncode != 0:
                run_result["error"] = (proc.stderr or proc.stdout or "").strip()[:700]
        except Exception as ex:
            run_result["ran"] = True
            run_result["code"] = -1
            run_result["error"] = f"{type(ex).__name__}: {ex}"
    status = {}
    if status_path.exists():
        try:
            status = json.loads(status_path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            status = {}
    payload = _orthanc_status_payload_cached(deep=False)
    return jsonify({
        "ok": bool(payload.get("online")),
        "orthanc_online": bool(payload.get("online")),
        "orthanc_url": payload.get("url"),
        "worklist_enabled": bool((payload.get("worklists") or {}).get("enabled")),
        "preflight": status,
        "run": run_result,
    })


