@app.route("/api/orthanc/sync", methods=["POST"])
@login_required
def api_orthanc_sync():
    data = request.get_json(silent=True) or {}
    raw_limit = data.get("limit") or request.values.get("limit") or 120
    try:
        limit = int(float(str(raw_limit).replace(",", ".")))
    except Exception:
        limit = 120
    limit = max(1, min(500, limit))
    detail = str(data.get("detail", request.values.get("detail", "1"))).lower()
    detail = detail not in {"0", "false", "hayir", "no"}
    default_instance_cap = 1200 if detail else 0
    default_private_scan_cap = 120 if detail else 0
    raw_instance_cap = (
        data["instance_cap"] if "instance_cap" in data
        else request.values.get("instance_cap", default_instance_cap))
    raw_private_scan_cap = (
        data["private_scan_cap"] if "private_scan_cap" in data
        else request.values.get("private_scan_cap", default_private_scan_cap))
    raw_private_download_cap = (
        data["private_download_cap"] if "private_download_cap" in data
        else request.values.get("private_download_cap", 0))
    try:
        instance_cap = int(float(str(raw_instance_cap).replace(",", ".")))
    except Exception:
        instance_cap = default_instance_cap
    try:
        private_scan_cap = int(float(str(raw_private_scan_cap).replace(",", ".")))
    except Exception:
        private_scan_cap = default_private_scan_cap
    try:
        private_download_cap = int(float(str(raw_private_download_cap).replace(",", ".")))
    except Exception:
        private_download_cap = 0
    try:
        result = _dicom_sync_from_orthanc(
            limit=limit, detail=detail, instance_cap=instance_cap,
            private_scan_cap=private_scan_cap,
            private_download_cap=private_download_cap)
        result.update({
            "synced": result.get("studies_synced", 0),
            "limit": limit,
            "detail": bool(detail),
            "table": "dicom_studies/dicom_series/dicom_instances",
            "message": (
                "Orthanc calismalari indekslendi; goruntu/PDF/video kopyalanmadi."
                if detail else
                "Orthanc study listesi hizli baglandi; ayrintili goruntu taramasi yapilmadi."
            ),
        })
        return jsonify(result)
    except Exception as ex:
        return jsonify({
            "ok": False,
            "error": f"{type(ex).__name__}: {ex}",
            "hint": (
                "Orthanc acik mi, kullanici/sifre dogru mu ve "
                "http://192.168.1.148:8042 erisiliyor mu kontrol edin."
            ),
            "limit": limit,
            "detail": bool(detail),
        }), 502


def _orthanc_modalities_payload():
    """Return configured Orthanc DICOM modalities and their capabilities."""
    modalities = []
    try:
        names = _orthanc_api_json("/modalities", timeout=5) or []
    except Exception as ex:
        return {
            "ok": False,
            "items": [],
            "error": f"{type(ex).__name__}: {ex}",
        }
    for name in names:
        item = {
            "name": str(name),
            "operations": [],
            "configuration": {},
            "error": "",
        }
        q_name = quote(str(name), safe="")
        try:
            ops = _orthanc_api_json(f"/modalities/{q_name}", timeout=5) or []
            if isinstance(ops, list):
                item["operations"] = [str(x) for x in ops]
        except Exception as ex:
            item["error"] = f"{type(ex).__name__}: {ex}"
        try:
            cfg = _orthanc_api_json(
                f"/modalities/{q_name}/configuration", timeout=5) or {}
            if isinstance(cfg, dict):
                item["configuration"] = cfg
        except Exception as ex:
            item["configuration_error"] = f"{type(ex).__name__}: {ex}"
        modalities.append(item)
    return {"ok": True, "items": modalities, "count": len(modalities)}


def _dicom_exchange_local_counts():
    counts = {
        "indexed_studies": 0,
        "indexed_series": 0,
        "indexed_instances": 0,
        "matched_studies": 0,
        "sr_series": 0,
        "sr_measurement_candidates": 0,
        "worklist_sent": 0,
        "last_sync_at": "",
        "last_worklist_at": "",
    }
    try:
        with db_conn() as con:
            _ensure_dicom_ai_tables(con)
            _ensure_dicom_worklist_tables(con)
            counts["indexed_studies"] = int(con.execute(
                "SELECT COUNT(*) FROM dicom_studies").fetchone()[0] or 0)
            counts["indexed_series"] = int(con.execute(
                "SELECT COUNT(*) FROM dicom_series").fetchone()[0] or 0)
            counts["indexed_instances"] = int(con.execute(
                "SELECT COUNT(*) FROM dicom_instances").fetchone()[0] or 0)
            counts["matched_studies"] = int(con.execute(
                "SELECT COUNT(*) FROM dicom_studies "
                "WHERE COALESCE(patient_key,'')<>''").fetchone()[0] or 0)
            counts["sr_series"] = int(con.execute(
                "SELECT COUNT(*) FROM dicom_series "
                "WHERE UPPER(COALESCE(modality,''))='SR'").fetchone()[0] or 0)
            counts["sr_measurement_candidates"] = int(con.execute(
                "SELECT COUNT(*) FROM dicom_measurement_candidates "
                "WHERE source_type IN ('dicom-meta','dicom-sr','pdf')").fetchone()[0] or 0)
            counts["worklist_sent"] = int(con.execute(
                "SELECT COUNT(*) FROM dicom_worklist_exports").fetchone()[0] or 0)
            row = con.execute(
                "SELECT MAX(last_synced_at) FROM dicom_studies").fetchone()
            counts["last_sync_at"] = str(row[0] or "") if row else ""
            row = con.execute(
                "SELECT MAX(updated_at) FROM dicom_worklist_exports").fetchone()
            counts["last_worklist_at"] = str(row[0] or "") if row else ""
    except Exception as ex:
        counts["error"] = f"{type(ex).__name__}: {ex}"
    return counts


def _dicom_exchange_status_payload():
    orthanc = _orthanc_status_payload_cached(deep=False)
    modalities = _orthanc_modalities_payload()
    local_counts = _dicom_exchange_local_counts()
    system = orthanc.get("system") or {}
    orthanc_aet = (
        system.get("DicomAet")
        or system.get("DicomAET")
        or system.get("DicomAETitle")
        or "ORTHANC")
    orthanc_dicom_port = system.get("DicomPort") or 4242
    voluson = None
    for item in modalities.get("items") or []:
        cfg = item.get("configuration") or {}
        name_blob = " ".join([
            str(item.get("name") or ""),
            str(cfg.get("AET") or ""),
            str(cfg.get("Host") or ""),
        ]).upper()
        if "VOLUSON" in name_blob:
            voluson = item
            break
    if not voluson and modalities.get("items"):
        voluson = (modalities.get("items") or [None])[0]
    ops = set(str(x) for x in ((voluson or {}).get("operations") or []))
    cfg = (voluson or {}).get("configuration") or {}
    worklist_ready = bool(
        orthanc.get("online")
        and "orthanc-worklists" in set(orthanc.get("plugins") or []))
    store_ready = bool(orthanc.get("online"))
    report_ready = bool(orthanc.get("online"))
    echo_ready = bool(voluson and ("echo" in ops or cfg.get("AllowEcho")))
    retrieve_ready = bool(voluson and (
        "move" in ops or "get" in ops or cfg.get("AllowMove")
        or cfg.get("AllowGet")))
    flow = [
        {
            "key": "worklist_out",
            "label": "Hasta bilgisi cihaza",
            "from": "YazKlinik",
            "to": "Orthanc Worklist / Voluson C-FIND",
            "service": "REST + DICOM MWL",
            "ok": worklist_ready,
            "detail": "Hasta adi ve protokol Voluson Worklist ekranina duser.",
        },
        {
            "key": "store_in",
            "label": "Goruntu geri gelir",
            "from": "Voluson",
            "to": "Orthanc C-STORE veya mevcut ViewPoint hedefi",
            "service": "DICOM C-STORE",
            "ok": store_ready,
            "detail": "USG bitince resim/video/DICOM PACS'a gelir. ViewPoint STORE ayari mevcut haliyle kalabilir.",
        },
        {
            "key": "report_sr",
            "label": "Olcum raporu geri gelir",
            "from": "Voluson REPORT / MEASUREMENTS",
            "to": "Orthanc SR / YazKlinik",
            "service": "DICOM SR / Comprehensive SR",
            "ok": report_ready,
            "detail": "Voluson olcumleri SR seri olarak gelir; YazKlinik doktor onayli olcum adayi cikarir.",
        },
        {
            "key": "index_match",
            "label": "YazKlinik eslestirir",
            "from": "Orthanc",
            "to": "YazKlinik",
            "service": "REST index + hasta eslestirme",
            "ok": bool(local_counts.get("indexed_studies") or 0),
            "detail": "Gelen study hasta kartina baglanir, kopyalama yapilmaz.",
        },
        {
            "key": "echo",
            "label": "Baglanti testi",
            "from": "Orthanc",
            "to": "Voluson",
            "service": "DICOM C-ECHO",
            "ok": echo_ready,
            "detail": "Cihaz izin verirse ping gibi test edilir; reddetmesi store/worklist'i bozmaz.",
        },
        {
            "key": "retrieve",
            "label": "Eski calisma sorgu",
            "from": "Orthanc",
            "to": "Voluson",
            "service": "C-FIND / C-MOVE / C-GET",
            "ok": retrieve_ready,
            "detail": "Cihaz lisansi izin verirse eski tetkik istenir.",
        },
    ]
    try:
        dicom_port_int = int(str(orthanc_dicom_port or 4242))
    except Exception:
        dicom_port_int = 4242
    try:
        public_mwl_port_int = int(str(_get_voluson_worklist_public_port() or "104"))
    except Exception:
        public_mwl_port_int = 104
    orthanc_host = ORTHANC_DEFAULT_HOST
    try:
        orthanc_host = urlsplit(str(orthanc.get("url") or "")).hostname or orthanc_host
    except Exception:
        pass
    return {
        "ok": bool(orthanc.get("online")),
        "orthanc": orthanc,
        "orthanc_aet": orthanc_aet,
        "orthanc_dicom_port": orthanc_dicom_port,
        "modalities": modalities,
        "voluson": voluson or {},
        "local_counts": local_counts,
        "flow": flow,
        "recommended": {
            "worklist_server_aet": str(orthanc_aet),
            "worklist_server_ip": orthanc_host,
            "worklist_server_port": public_mwl_port_int,
            "orthanc_internal_dicom_port": dicom_port_int,
            "store_target_aet": str(orthanc_aet),
            "store_target_ip": orthanc_host,
            "store_target_port": public_mwl_port_int,
            "report_target_aet": str(orthanc_aet),
            "report_target_ip": orthanc_host,
            "report_target_port": public_mwl_port_int,
            "report_service": "REPORT / SR / MEASUREMENTS / DICOM SR",
            "voluson_local_aet": str(cfg.get("AET") or "VOLUSON"),
        },
    }


