@app.route("/api/hasta/<patient_key>/dicom/eslestir", methods=["POST"])
@login_required
def api_patient_dicom_match(patient_key):
    data = request.get_json(silent=True) or {}
    study_id = str(data.get("study_id") or request.form.get("study_id") or "").strip()
    if not study_id:
        return jsonify({"ok": False, "error": "study_id gerekli"}), 400
    _ensure_dicom_ai_tables()
    try:
        study = _orthanc_api_json(
            f"/studies/{quote(study_id, safe='')}", timeout=10) or {}
    except Exception:
        study = {}
    main = study.get("MainDicomTags") or {}
    patient = study.get("PatientMainDicomTags") or {}
    now = datetime.now().isoformat(timespec="seconds")
    with db_conn() as con:
        _ensure_dicom_ai_tables(con)
        con.execute("""
            INSERT INTO dicom_studies(
                orthanc_study_id, study_instance_uid, patient_name,
                patient_id, study_date, study_time, accession_number,
                institution_name, raw_json, patient_key,
                matched_confidence, match_reason, created_at, updated_at,
                last_synced_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 'manuel eslesme', ?, ?, ?)
            ON CONFLICT(orthanc_study_id) DO UPDATE SET
                patient_key=excluded.patient_key,
                matched_confidence=1,
                match_reason='manuel eslesme',
                updated_at=excluded.updated_at,
                last_synced_at=excluded.last_synced_at
        """, (
            study_id,
            str(main.get("StudyInstanceUID") or ""),
            str(patient.get("PatientName") or "").replace("^", " "),
            str(patient.get("PatientID") or ""),
            str(main.get("StudyDate") or ""),
            str(main.get("StudyTime") or ""),
            str(main.get("AccessionNumber") or ""),
            str(main.get("InstitutionName") or ""),
            json.dumps(study, ensure_ascii=True, default=str),
            patient_key,
            now,
            now,
            now,
        ))
        con.commit()
    return jsonify({"ok": True, "patient_key": patient_key, "study_id": study_id})


@app.route("/api/hasta/<patient_key>/dicom/private-tara", methods=["POST"])
@login_required
def api_patient_dicom_private_scan(patient_key):
    data = request.get_json(silent=True) or {}
    try:
        instance_cap = int(float(str(
            data.get("instance_cap") or request.values.get("instance_cap") or 220
        ).replace(",", ".")))
    except Exception:
        instance_cap = 220
    try:
        download_cap = int(float(str(
            data.get("download_cap") or request.values.get("download_cap") or 80
        ).replace(",", ".")))
    except Exception:
        download_cap = 80
    instance_cap = max(1, min(instance_cap, 1500))
    download_cap = max(0, min(download_cap, instance_cap))

    _ensure_dicom_ai_tables()
    rows = []
    with db_conn() as con:
        _ensure_dicom_ai_tables(con)
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        rows = con.execute("""
            SELECT i.orthanc_instance_id, i.orthanc_series_id,
                   i.raw_json, ds.study_date
            FROM dicom_instances i
            JOIN dicom_series s ON s.orthanc_series_id=i.orthanc_series_id
            JOIN dicom_studies ds ON ds.orthanc_study_id=s.orthanc_study_id
            WHERE ds.patient_key=?
            ORDER BY COALESCE(ds.study_date, '') DESC,
                     COALESCE(i.instance_number, '') ASC
            LIMIT ?
        """, (patient_key, instance_cap)).fetchall()

    if not rows:
        _dicom_sync_from_orthanc(
            limit=160, detail=True, instance_cap=instance_cap,
            private_scan_cap=instance_cap, private_download_cap=0)
        with db_conn() as con:
            _ensure_dicom_ai_tables(con)
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            rows = con.execute("""
                SELECT i.orthanc_instance_id, i.orthanc_series_id,
                       i.raw_json, ds.study_date
                FROM dicom_instances i
                JOIN dicom_series s ON s.orthanc_series_id=i.orthanc_series_id
                JOIN dicom_studies ds ON ds.orthanc_study_id=s.orthanc_study_id
                WHERE ds.patient_key=?
                ORDER BY COALESCE(ds.study_date, '') DESC,
                         COALESCE(i.instance_number, '') ASC
                LIMIT ?
            """, (patient_key, instance_cap)).fetchall()

    scanned = 0
    downloaded = 0
    inserted = 0
    reports = 0
    decoded_reports = 0
    errors = []
    with db_conn() as con:
        _ensure_dicom_ai_tables(con)
        for row in rows:
            iid = str(row.get("orthanc_instance_id") or "").strip()
            if not iid:
                continue
            tags = {}
            try:
                tags = json.loads(row.get("raw_json") or "{}")
            except Exception:
                tags = {}
            do_download = downloaded < download_cap
            try:
                analysis = _dicom_private_scan_instance(
                    iid, tags=tags, download=do_download)
                scanned += 1
                if do_download:
                    downloaded += 1
                if int(analysis.get("decoded_measurement_count") or 0) > 0:
                    decoded_reports += 1
                reports += _dicom_store_private_report(
                    con, patient_key, row.get("orthanc_series_id") or "",
                    iid, analysis)
                inserted += _dicom_insert_measurement_candidates(
                    con, patient_key, analysis.get("candidates") or [],
                    raw_json=_dicom_private_compact_json(analysis))
            except Exception as ex:
                errors.append(f"{iid}: {ex}")
        con.commit()
    return jsonify({
        "ok": True,
        "patient_key": patient_key,
        "scanned": scanned,
        "downloaded": downloaded,
        "reports": reports,
        "decoded_reports": decoded_reports,
        "inserted": inserted,
        "errors": errors[:8],
        "message": (
            f"GE/4DView private tarama tamamlandi: {scanned} instance, "
            f"{downloaded} ham DICOM, {inserted} yeni olcum adayi."
        ),
        "guardrail": _DICOM_AI_GUARDRAIL,
    })


@app.route("/api/hasta/<patient_key>/dicom/ocr-olcum", methods=["POST"])
@login_required
def api_patient_dicom_ocr_measurements(patient_key):
    data = request.get_json(silent=True) or {}
    raw_text = str(data.get("text") or request.form.get("text") or "").strip()
    candidates = []
    candidates.extend(_dicom_pdf_measurement_candidates(patient_key))
    candidates.extend(_dicom_extract_measurements_from_text(
        raw_text, source_type="ocr-manual", source_id=f"manual-{patient_key}"))
    inserted = 0
    with db_conn() as con:
        _ensure_dicom_ai_tables(con)
        inserted += _dicom_insert_measurement_candidates(
            con, patient_key, candidates, raw_json={"mode": "pdf+ocr"})
        con.commit()
    message = (
        f"{inserted} yeni olcum adayi eklendi."
        if inserted else
        "Yeni olcum adayi bulunamadi. Standart DICOM SR yoksa PDF/OCR metni gerekir."
    )
    return jsonify({
        "ok": True,
        "inserted": inserted,
        "candidate_count": len(candidates),
        "message": message,
        "guardrail": _DICOM_AI_GUARDRAIL,
    })


