def _dicom_worklist_parse_date(value=""):
    raw = str(value or "").strip()
    if not raw:
        return datetime.now().strftime("%Y-%m-%d")
    for text in (raw, raw[:10]):
        for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d-%m-%Y", "%Y%m%d"):
            try:
                return datetime.strptime(text, fmt).strftime("%Y-%m-%d")
            except Exception:
                continue
    return datetime.now().strftime("%Y-%m-%d")


def _dicom_worklist_display_date(iso_date):
    try:
        return datetime.strptime(iso_date, "%Y-%m-%d").strftime("%d.%m.%Y")
    except Exception:
        return iso_date


def _dicom_worklist_date_variants(iso_date):
    variants = {iso_date}
    try:
        dt = datetime.strptime(iso_date, "%Y-%m-%d")
        variants.add(dt.strftime("%d.%m.%Y"))
        variants.add(dt.strftime("%Y%m%d"))
    except Exception:
        pass
    return sorted(v for v in variants if v)


def _dicom_worklist_modality(purpose):
    text = _fold_search_text(purpose)
    if "mr" in text or "emar" in text:
        return "MR"
    if "bt" in text or "tomografi" in text or "ct" in text:
        return "CT"
    if "mamograf" in text or "meme" in text:
        return "MG"
    return "US"


def _dicom_worklist_status_badge(status, source):
    st = str(status or "planned").strip().lower()
    if source == "visit":
        return '<span class="badge bg-info text-dark">Bugunku gelis</span>'
    if source == "new_patient":
        return '<span class="badge bg-warning text-dark">Yeni hasta</span>'
    if st == "completed":
        return '<span class="badge bg-secondary">Tamamlandi</span>'
    if st == "confirmed":
        return '<span class="badge bg-success">Onayli</span>'
    if st == "no_show":
        return '<span class="badge bg-warning text-dark">Gelmedi</span>'
    return '<span class="badge bg-primary">Worklist</span>'


def _ensure_dicom_worklist_tables(con=None):
    if con is None:
        with db_conn() as open_con:
            return _ensure_dicom_worklist_tables(open_con)
    con.execute("""
        CREATE TABLE IF NOT EXISTS dicom_worklist_exports (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_key TEXT NOT NULL,
            appointment_id TEXT,
            visit_key TEXT,
            accession_number TEXT NOT NULL,
            study_instance_uid TEXT,
            orthanc_worklist_id TEXT,
            orthanc_path TEXT,
            patient_name TEXT,
            patient_id TEXT,
            scheduled_date TEXT,
            scheduled_time TEXT,
            modality TEXT,
            station_aet TEXT,
            procedure_description TEXT,
            status TEXT DEFAULT 'sent',
            live_verified INTEGER DEFAULT 0,
            matched_study_id TEXT,
            matched_at TEXT,
            last_message TEXT,
            request_json TEXT,
            response_json TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
            created_by TEXT
        )
    """)
    for _column, _ddl in (
        ("live_verified", "ALTER TABLE dicom_worklist_exports ADD COLUMN live_verified INTEGER DEFAULT 0"),
        ("matched_study_id", "ALTER TABLE dicom_worklist_exports ADD COLUMN matched_study_id TEXT"),
        ("matched_at", "ALTER TABLE dicom_worklist_exports ADD COLUMN matched_at TEXT"),
        ("last_message", "ALTER TABLE dicom_worklist_exports ADD COLUMN last_message TEXT"),
    ):
        try:
            con.execute(_ddl)
        except Exception:
            pass
    con.execute("""
        CREATE UNIQUE INDEX IF NOT EXISTS ux_dicom_worklist_accession
        ON dicom_worklist_exports(accession_number)
    """)
    con.execute("""
        CREATE INDEX IF NOT EXISTS idx_dicom_worklist_patient_date
        ON dicom_worklist_exports(patient_key, scheduled_date, scheduled_time)
    """)
    con.commit()


def _dicom_safe_text(value, max_len=64):
    text = fix_mojibake_text(str(value or ""))
    text = text.translate({
        ord("\u00e7"): "c",
        ord("\u011f"): "g",
        ord("\u0131"): "i",
        ord("\u00f6"): "o",
        ord("\u015f"): "s",
        ord("\u00fc"): "u",
        ord("\u00c7"): "C",
        ord("\u011e"): "G",
        ord("\u0130"): "I",
        ord("\u00d6"): "O",
        ord("\u015e"): "S",
        ord("\u00dc"): "U",
    })
    text = unicodedata.normalize("NFKD", text)
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    text = text.upper()
    text = re.sub(r"[^A-Z0-9 ._+\-^]", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text[:max(1, int(max_len or 64))]


def _dicom_patient_name_tag(patient_key, display_name=""):
    name = _patient_display_label(patient_key, display_name or patient_key)
    name = re.sub(r"\([^)]*\)", " ", name)
    name = _dicom_safe_text(name, 64)
    formatted = _person_name_to_family_given(name)
    if formatted:
        return formatted[:64]
    return _dicom_safe_text(patient_key, 64)


def _dicom_worklist_scheduled_values(data):
    data = data or {}
    raw_date = (
        data.get("date") or data.get("scheduled_date")
        or data.get("appointment_date") or datetime.now().strftime("%Y-%m-%d"))
    iso_date = _dicom_worklist_parse_date(raw_date)
    raw_time = str(
        data.get("time") or data.get("scheduled_time")
        or data.get("appointment_time") or datetime.now().strftime("%H:%M")
    ).strip()
    raw_time = raw_time.replace(".", ":")
    digits = re.sub(r"\D", "", raw_time)
    if not digits:
        digits = "090000"
    if len(digits) <= 2:
        digits = digits.ljust(2, "0") + "0000"
    elif len(digits) <= 4:
        digits = digits.ljust(4, "0") + "00"
    else:
        digits = digits[:6].ljust(6, "0")
    return iso_date, digits


def _dicom_worklist_patient_identity(patient_key, display_name="", demo=None, data=None):
    data = dict(data or {})
    demo = dict(demo or {})
    _clean_name, folder_prefix, _folder_date = _patient_key_name_parts(patient_key)
    base_display = _patient_display_label(
        patient_key,
        demo.get("canonical_name") or display_name or patient_key)
    raw_patient_id = (
        data.get("patient_id")
        or data.get("dicom_patient_id")
        or data.get("voluson_patient_id")
        or demo.get("dicom_patient_id")
        or demo.get("voluson_patient_id")
        or folder_prefix
        or re.sub(r"[^A-Za-z0-9_.-]+", "", str(patient_key))
    )
    patient_id = _dicom_safe_text(raw_patient_id, 32)
    raw_patient_name = (
        data.get("patient_name")
        or data.get("dicom_patient_name")
        or data.get("voluson_patient_name")
        or demo.get("dicom_patient_name")
        or demo.get("voluson_patient_name")
        or demo.get("canonical_name")
        or base_display
    )
    raw_patient_name = str(raw_patient_name or "").strip()
    if raw_patient_name and "^" not in raw_patient_name:
        raw_patient_name = _person_name_to_family_given(raw_patient_name) or raw_patient_name
    patient_name = _dicom_safe_text(raw_patient_name, 64)
    if not patient_name:
        patient_name = _dicom_patient_name_tag(patient_key, base_display)
    accession_prefix = _dicom_safe_text(
        data.get("accession_prefix")
        or data.get("dicom_accession_prefix")
        or demo.get("dicom_accession_prefix")
        or patient_id,
        16)
    patient_sex = _dicom_safe_text(
        data.get("patient_sex")
        or data.get("sex")
        or data.get("dicom_patient_sex")
        or demo.get("dicom_patient_sex")
        or demo.get("sex")
        or "F",
        4)
    return {
        "display_name": base_display,
        "patient_id": patient_id,
        "patient_name": patient_name,
        "accession_prefix": accession_prefix or patient_id[:16],
        "patient_sex": patient_sex[:1].upper() if patient_sex else "",
    }


def _dicom_worklist_build_payload(patient_key, data=None):
    data = dict(data or {})
    appointment_id = str(data.get("appointment_id") or "").strip()
    demo = {}
    with db_conn() as con:
        con.row_factory = lambda cur, row: {
            d[0]: row[i] for i, d in enumerate(cur.description)}
        row = con.execute(
            "SELECT display_name FROM patients WHERE folder_key=?",
            (patient_key,)).fetchone()
        display_name = (row or {}).get("display_name") or patient_key
        protocol_no = _ensure_patient_protocol(patient_key, con)
        if appointment_id:
            try:
                appt = con.execute(
                    "SELECT * FROM appointments WHERE id=? AND patient_key=?",
                    (appointment_id, patient_key)).fetchone()
            except Exception:
                appt = None
            if appt:
                for key in ("appointment_date", "appointment_time", "purpose"):
                    if not data.get(key) and appt.get(key):
                        data[key] = appt.get(key)
        con.commit()
    try:
        demo = load_patient_demographics(patient_key) or {}
    except Exception:
        demo = {}

    iso_date, dicom_time = _dicom_worklist_scheduled_values(data)
    dicom_date = datetime.strptime(iso_date, "%Y-%m-%d").strftime("%Y%m%d")
    procedure = str(
        data.get("procedure") or data.get("purpose")
        or data.get("description") or "Obstetrik USG").strip() or "Obstetrik USG"
    modality = str(data.get("modality") or _dicom_worklist_modality(procedure)).upper()
    mwl_cfg = _get_orthanc_mwl_config()
    station_aet = _dicom_safe_text(
        data.get("station_aet")
        or data.get("dicom_station_aet")
        or demo.get("dicom_station_aet")
        or _db_get_setting("dicom_worklist_station_aet", "")
        or _db_get_setting("sysparam_dicom_worklist_station_aet", "")
        or _db_get_setting("voluson_aet", "")
        or _db_get_setting("sysparam_voluson_aet", "")
        or mwl_cfg.get("station_aet")
        or VOLUSON_AET,
        16) or VOLUSON_AET
    identity = _dicom_worklist_patient_identity(
        patient_key, display_name=display_name, demo=demo, data=data)
    patient_id = str(identity.get("patient_id") or "")
    accession = _dicom_safe_text(
        data.get("accession_number")
        or f"YK{identity.get('accession_prefix')}-{dicom_date}",
        16)
    uid_seed = "|".join([
        str(patient_key), str(appointment_id), str(data.get("visit_key") or ""),
        dicom_date, dicom_time, accession])
    study_uid = str(data.get("study_instance_uid") or f"2.25.{uuid.uuid5(uuid.NAMESPACE_URL, uid_seed).int}")
    step_id = _dicom_safe_text(data.get("step_id") or accession, 16)
    patient_name = str(identity.get("patient_name") or "")
    birth_raw = str(data.get("birth_date") or demo.get("birth_date") or "").strip()
    birth_day = _dicom_worklist_parse_date(birth_raw) if birth_raw else ""
    patient_sex = str(identity.get("patient_sex") or "")
    tags = {
        "SpecificCharacterSet": "ISO_IR 192",
        "PatientID": patient_id,
        "PatientName": patient_name,
        "AccessionNumber": accession,
        "StudyInstanceUID": study_uid,
        "RequestedProcedureID": step_id,
        "RequestedProcedureDescription": _dicom_safe_text(procedure, 64),
        "ScheduledProcedureStepSequence": [{
            "Modality": _dicom_safe_text(modality, 16),
            "ScheduledStationAETitle": station_aet,
            "ScheduledProcedureStepStartDate": dicom_date,
            "ScheduledProcedureStepStartTime": dicom_time,
            "ScheduledProcedureStepID": step_id,
            "ScheduledProcedureStepDescription": _dicom_safe_text(procedure, 64),
        }],
    }
    if birth_day:
        tags["PatientBirthDate"] = datetime.strptime(
            birth_day, "%Y-%m-%d").strftime("%Y%m%d")
    if patient_sex:
        tags["PatientSex"] = patient_sex[:1].upper()
    meta = {
        "patient_key": patient_key,
        "display_name": str(identity.get("display_name") or _patient_display_label(patient_key, display_name)),
        "protocol_no": str(protocol_no or ""),
        "patient_id": patient_id,
        "patient_name": patient_name,
        "patient_birth_date": tags.get("PatientBirthDate", ""),
        "patient_sex": tags.get("PatientSex", ""),
        "accession_number": accession,
        "study_instance_uid": study_uid,
        "scheduled_date": iso_date,
        "scheduled_time": f"{dicom_time[:2]}:{dicom_time[2:4]}",
        "dicom_date": dicom_date,
        "dicom_time": dicom_time,
        "modality": modality,
        "station_aet": station_aet,
        "procedure_description": procedure,
        "appointment_id": appointment_id,
        "visit_key": str(data.get("visit_key") or ""),
    }
    return {"Tags": tags}, meta


def _orthanc_worklist_create(payload):
    errors = []
    for path in ("/worklists/create", "/plugins/worklists/create"):
        try:
            result = _orthanc_api_request_json(
                path, method="POST", payload=payload, timeout=12)
            return path, result or {}
        except Exception as ex:
            errors.append(f"{path}: {type(ex).__name__}: {ex}")
    raise RuntimeError("; ".join(errors))


def _orthanc_worklist_live_items(fmt="Simplify"):
    fmt = str(fmt or "Simplify").strip() or "Simplify"
    errors = []
    for path in (f"/worklists/?format={quote(fmt, safe='')}",
                 f"/plugins/worklists?format={quote(fmt, safe='')}"):
        try:
            live = _orthanc_api_request_json(path, timeout=8)
            if isinstance(live, list):
                return live, path, ""
            if isinstance(live, dict) and isinstance(live.get("Worklists"), list):
                return live.get("Worklists") or [], path, ""
            return [], path, ""
        except Exception as ex:
            errors.append(f"{path}: {type(ex).__name__}: {ex}")
    return [], "", "; ".join(errors)


def _dicom_worklist_tag(tags, keyword, code=""):
    tags = tags or {}
    value = tags.get(keyword)
    if value is None and code:
        value = tags.get(code)
    if isinstance(value, dict):
        value = value.get("Value")
    return "" if value is None else str(value)


def _dicom_worklist_verify_live(meta):
    meta = meta or {}
    mwl_cfg = _get_orthanc_mwl_config()
    items, source_path, error = _orthanc_worklist_live_items("Simplify")
    accession = str(meta.get("accession_number") or "")
    patient_id = str(meta.get("patient_id") or "")
    patient_name = str(meta.get("patient_name") or "")
    matched = None
    for item in items:
        tags = item.get("Tags") if isinstance(item, dict) else {}
        item_accession = _dicom_worklist_tag(tags, "AccessionNumber", "0008,0050")
        item_patient_id = _dicom_worklist_tag(tags, "PatientID", "0010,0020")
        item_patient_name = _dicom_worklist_tag(tags, "PatientName", "0010,0010")
        if accession and item_accession == accession:
            matched = item
            break
        if patient_id and patient_name and (
                item_patient_id == patient_id and item_patient_name == patient_name):
            matched = item
            break
    return {
        "verified": bool(matched),
        "source_path": source_path,
        "error": error,
        "live_count": len(items),
        "accession_number": accession,
        "patient_id": patient_id,
        "patient_name": patient_name,
        "worklist_id": str((matched or {}).get("ID") or ""),
        "matched": matched or {},
        "instruction": (
            "Voluson cihazinda Worklist ekranina girip Query/Refresh yapin. "
            f"Server AE {mwl_cfg.get('server_aet') or 'ORTHANC'}, "
            f"port {_get_voluson_worklist_public_port()}, TLS kapali olmali; "
            "104 portu kapaliysa 4242 kullanin ve ilk testte Station/AE filtresini bos birakin."),
    }


def _save_dicom_worklist_export(meta, payload, orthanc_path, response_payload):
    now = datetime.now().isoformat(timespec="seconds")
    orthanc_id = ""
    if isinstance(response_payload, dict):
        orthanc_id = str(
            response_payload.get("ID")
            or response_payload.get("IDWorklist")
            or response_payload.get("worklist_id")
            or response_payload.get("Path")
            or "")
    with db_conn() as con:
        _ensure_dicom_worklist_tables(con)
        con.execute("""
            INSERT INTO dicom_worklist_exports(
                patient_key, appointment_id, visit_key, accession_number,
                study_instance_uid, orthanc_worklist_id, orthanc_path,
                patient_name, patient_id, scheduled_date, scheduled_time,
                modality, station_aet, procedure_description, status,
                request_json, response_json, created_at, updated_at, created_by
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'sent', ?, ?, ?, ?, ?)
            ON CONFLICT(accession_number) DO UPDATE SET
                study_instance_uid=excluded.study_instance_uid,
                orthanc_worklist_id=excluded.orthanc_worklist_id,
                orthanc_path=excluded.orthanc_path,
                patient_name=excluded.patient_name,
                patient_id=excluded.patient_id,
                scheduled_date=excluded.scheduled_date,
                scheduled_time=excluded.scheduled_time,
                modality=excluded.modality,
                station_aet=excluded.station_aet,
                procedure_description=excluded.procedure_description,
                status='sent',
                request_json=excluded.request_json,
                response_json=excluded.response_json,
                updated_at=excluded.updated_at,
                created_by=excluded.created_by
        """, (
            meta.get("patient_key"), meta.get("appointment_id"), meta.get("visit_key"),
            meta.get("accession_number"), meta.get("study_instance_uid"),
            orthanc_id, orthanc_path, meta.get("patient_name"), meta.get("patient_id"),
            meta.get("scheduled_date"), meta.get("scheduled_time"),
            meta.get("modality"), meta.get("station_aet"),
            meta.get("procedure_description"),
            json.dumps(payload, ensure_ascii=True, default=str),
            json.dumps(response_payload, ensure_ascii=True, default=str),
            now, now, session.get("username", "system"),
        ))
        con.commit()
    return orthanc_id


def _dicom_worklist_export_map(selected_date):
    try:
        with db_conn() as con:
            _ensure_dicom_worklist_tables(con)
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            rows = con.execute(
                "SELECT * FROM dicom_worklist_exports "
                "WHERE scheduled_date=? ORDER BY updated_at DESC",
                (selected_date,)).fetchall()
            out = {}
            for row in rows:
                key = (
                    str(row.get("patient_key") or ""),
                    str(row.get("scheduled_date") or ""),
                    str(row.get("scheduled_time") or "")[:5],
                )
                out.setdefault(key, dict(row))
                out.setdefault((key[0], key[1], ""), dict(row))
            return out
    except Exception:
        return {}


def _dicom_worklist_rows(selected_date):
    rows = []
    diagnostics = {
        "appointments": 0,
        "visits": 0,
        "new_patients": 0,
        "tables": [],
    }
    variants = _dicom_worklist_date_variants(selected_date)
    try:
        with db_conn() as con:
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            tables = {
                r["name"] for r in con.execute(
                    "SELECT name FROM sqlite_master WHERE type='table'")
            }
            diagnostics["tables"] = sorted(tables)

            if "appointments" in tables:
                placeholders = ",".join("?" for _ in variants)
                appt_rows = con.execute(
                    "SELECT a.*, p.display_name, 'appointment' AS wl_source "
                    "FROM appointments a "
                    "LEFT JOIN patients p ON p.folder_key = a.patient_key "
                    f"WHERE (a.appointment_date IN ({placeholders}) "
                    "OR substr(COALESCE(a.appointment_date,''),1,10)=?) "
                    "AND COALESCE(a.status,'planned') != 'cancelled' "
                    "ORDER BY COALESCE(a.appointment_time,'99:99'), "
                    "COALESCE(p.display_name,a.patient_key)",
                    (*variants, selected_date)).fetchall()
                diagnostics["appointments"] = len(appt_rows)
                rows.extend(dict(r) for r in appt_rows)

            seen_patients = {
                str(r.get("patient_key") or "") for r in rows
                if r.get("patient_key")
            }

            if "visits" in tables:
                visit_rows = con.execute(
                    "SELECT v.patient_folder_key AS patient_key, "
                    "v.visit_key, v.visit_date, v.file_count, "
                    "v.image_count, v.video_count, v.pdf_count, "
                    "p.display_name, 'visit' AS wl_source "
                    "FROM visits v "
                    "LEFT JOIN patients p "
                    "ON p.folder_key = v.patient_folder_key "
                    "WHERE v.visit_date LIKE ? "
                    "ORDER BY COALESCE(v.visit_date,''), "
                    "COALESCE(p.display_name,v.patient_folder_key)",
                    (f"{selected_date}%",)).fetchall()
                diagnostics["visits"] = len(visit_rows)
                for row in visit_rows:
                    item = dict(row)
                    pkey = str(item.get("patient_key") or "")
                    if pkey in seen_patients:
                        for existing in rows:
                            if str(existing.get("patient_key") or "") == pkey:
                                existing["has_visit_today"] = "1"
                                existing["visit_key"] = (
                                    existing.get("visit_key")
                                    or item.get("visit_key") or "")
                                break
                        continue
                    item.update({
                        "appointment_date": selected_date,
                        "appointment_time": "",
                        "purpose": "USG/DICOM medya - bugunku gelis",
                        "status": "planned",
                        "has_visit_today": "1",
                    })
                    rows.append(item)
                    seen_patients.add(pkey)

            if "patients" in tables:
                new_rows = con.execute(
                    "SELECT folder_key AS patient_key, display_name, "
                    "first_seen_at, 'new_patient' AS wl_source "
                    "FROM patients "
                    "WHERE first_seen_at LIKE ? "
                    "ORDER BY first_seen_at DESC LIMIT 200",
                    (f"{selected_date}%",)).fetchall()
                diagnostics["new_patients"] = len(new_rows)
                for row in new_rows:
                    item = dict(row)
                    pkey = str(item.get("patient_key") or "")
                    if not pkey or pkey in seen_patients:
                        continue
                    item.update({
                        "appointment_date": selected_date,
                        "appointment_time": "",
                        "purpose": "Yeni hasta kaydi",
                        "status": "planned",
                    })
                    rows.append(item)
                    seen_patients.add(pkey)
    except Exception as ex:
        diagnostics["error"] = f"{type(ex).__name__}: {ex}"

    def _sort_key(item):
        source_order = {"appointment": 0, "visit": 1, "new_patient": 2}
        return (
            str(item.get("appointment_time") or "99:99"),
            source_order.get(str(item.get("wl_source") or ""), 9),
            _fold_search_text(item.get("display_name")
                              or item.get("patient_key") or ""),
        )

    rows.sort(key=_sort_key)
    exported = _dicom_worklist_export_map(selected_date)
    for item in rows:
        pkey = str(item.get("patient_key") or "")
        time_key = str(item.get("appointment_time") or "")[:5]
        sent = exported.get((pkey, selected_date, time_key)) or exported.get(
            (pkey, selected_date, ""))
        if sent:
            item["worklist_sent"] = "1"
            item["worklist_accession"] = sent.get("accession_number") or ""
            item["worklist_updated_at"] = sent.get("updated_at") or ""
    return rows[:300], diagnostics


@app.route("/api/dicom/worklist")
@login_required
def api_dicom_worklist():
    selected_date = _dicom_worklist_parse_date(request.args.get("gun"))
    items, diagnostics = _dicom_worklist_rows(selected_date)
    return jsonify({
        "ok": True,
        "date": selected_date,
        "display_date": _dicom_worklist_display_date(selected_date),
        "count": len(items),
        "diagnostics": diagnostics,
        "items": items,
    })


@app.route("/api/hasta/<patient_key>/dicom/worklist-gonder", methods=["POST"])
@login_required
def api_patient_dicom_worklist_send(patient_key):
    data = request.get_json(silent=True) or {}
    dry_run = str(
        data.get("dry_run", request.args.get("dry_run", "0"))
    ).lower() in {"1", "true", "evet", "yes", "dry"}
    payload, meta = _dicom_worklist_build_payload(patient_key, data)
    if dry_run:
        return jsonify({
            "ok": True,
            "dry_run": True,
            "patient_key": patient_key,
            "payload": payload,
            "meta": meta,
            "message": "Voluson/Orthanc Worklist taslagi hazirlandi; dry_run nedeniyle gonderilmedi.",
        })
    try:
        orthanc_path, response_payload = _orthanc_worklist_create(payload)
        orthanc_id = _save_dicom_worklist_export(
            meta, payload, orthanc_path, response_payload)
        verification = _dicom_worklist_verify_live(meta)
        if verification.get("verified"):
            message = (
                "Hasta Orthanc Worklist canli listesinde gorundu. "
                "Voluson cihazinda Worklist > Query/Refresh yapin; hasta listede cikmali.")
        else:
            message = (
                "Hasta Worklist kaydi Orthanc'a gonderildi. Canli listede "
                "anlik dogrulanamadi; Voluson'da tarih filtresini ve Query/Refresh'i kontrol edin.")
        return jsonify({
            "ok": True,
            "patient_key": patient_key,
            "orthanc_path": orthanc_path,
            "orthanc_worklist_id": orthanc_id,
            "payload": payload,
            "meta": meta,
            "response": response_payload,
            "verification": verification,
            "message": message,
        })
    except Exception as ex:
        return jsonify({
            "ok": False,
            "error": f"{type(ex).__name__}: {ex}",
            "payload": payload,
            "meta": meta,
        }), 502


