@app.route("/api/hasta/<patient_key>/dicom/worklist-duzelt", methods=["POST"])
@login_required
def api_patient_dicom_worklist_update_patient(patient_key):
    """Patient-demographic-aware MWL refresh for Voluson/USG."""
    data = request.get_json(silent=True) or {}
    updates = data.get("patient_updates") or data.get("updates") or {}
    if not isinstance(updates, dict):
        updates = {}
    apply_now = str(data.get("apply_to_patient") or "").lower() in {
        "1", "true", "evet", "yes"}
    dry_run = str(data.get("dry_run") or request.args.get("dry_run") or "").lower() in {
        "1", "true", "evet", "yes", "dry"}
    decisions = []
    for field_key, value in updates.items():
        field_key = _patient_data_canonical_key(field_key)
        if field_key not in PATIENT_CANONICAL_FIELDS:
            continue
        if dry_run:
            incoming = _patient_data_normalize(field_key, value)
            try:
                current = _patient_data_normalize(
                    field_key, (load_patient_demographics(patient_key) or {}).get(field_key))
            except Exception:
                current = ""
            decisions.append({
                "ok": bool(incoming),
                "status": "preview" if incoming else "empty",
                "field": field_key,
                "field_label": PATIENT_CANONICAL_FIELDS.get(field_key, field_key),
                "current_value": current,
                "incoming_value": incoming,
                "would_queue": bool(current and incoming and current != incoming),
                "would_apply_empty": bool((not current) and incoming),
            })
            continue
        if apply_now:
            normalized = _patient_data_normalize(field_key, value)
            if normalized:
                _patient_data_apply_value(patient_key, field_key, normalized)
                decisions.append({
                    "field": field_key,
                    "status": "applied",
                    "value": normalized,
                })
        else:
            decisions.append(_patient_data_suggest_value(
                patient_key, field_key, value,
                source="dicom_worklist_duzeltme",
                source_ref="Voluson MWL hasta bilgisi",
                confidence=0.75,
                auto_apply_empty=True))
    payload, meta = _dicom_worklist_build_payload(patient_key, data)
    if dry_run:
        return jsonify({
            "ok": True,
            "dry_run": True,
            "patient_key": patient_key,
            "decisions": decisions,
            "payload": payload,
            "meta": meta,
            "message": "DICOM Worklist duzeltme taslagi hazirlandi.",
        })
    try:
        orthanc_path, response_payload = _orthanc_worklist_create(payload)
        orthanc_id = _save_dicom_worklist_export(
            meta, payload, orthanc_path, response_payload)
        verification = _dicom_worklist_verify_live(meta)
        _log_audit("dicom_worklist_patient_refresh",
                   entity_type="patient", patient_key=patient_key,
                   details=meta.get("accession_number"))
        return jsonify({
            "ok": True,
            "patient_key": patient_key,
            "decisions": decisions,
            "orthanc_path": orthanc_path,
            "orthanc_worklist_id": orthanc_id,
            "payload": payload,
            "meta": meta,
            "response": response_payload,
            "verification": verification,
            "message": (
                "Hasta bilgisi ana kayitla senkron Worklist'e yeniden yazildi. "
                "Voluson cihazinda Worklist > Query/Refresh yapin."),
        })
    except Exception as ex:
        return jsonify({
            "ok": False,
            "error": f"{type(ex).__name__}: {ex}",
            "decisions": decisions,
            "payload": payload,
            "meta": meta,
        }), 502


@app.route("/api/orthanc/worklists")
@login_required
def api_orthanc_worklists():
    selected_date = _dicom_worklist_parse_date(request.args.get("gun"))
    local_rows = []
    try:
        with db_conn() as con:
            _ensure_dicom_worklist_tables(con)
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            local_rows = [dict(r) for r in con.execute(
                "SELECT * FROM dicom_worklist_exports "
                "WHERE scheduled_date=? ORDER BY scheduled_time, updated_at DESC",
                (selected_date,)).fetchall()]
    except Exception:
        local_rows = []
    live = None
    live_error = ""
    live_path = ""
    if str(request.args.get("live", "0")).lower() in {"1", "true", "evet", "yes"}:
        live, live_path, live_error = _orthanc_worklist_live_items(
            request.args.get("format") or "Simplify")
    return jsonify({
        "ok": True,
        "date": selected_date,
        "count": len(local_rows),
        "items": local_rows,
        "orthanc_live": live,
        "orthanc_live_count": len(live or []),
        "orthanc_live_path": live_path,
        "orthanc_live_error": live_error,
    })


@app.route("/api/dicom/worklist/aktif-durum")
@login_required
def api_dicom_worklist_active_status():
    selected_date = _dicom_worklist_parse_date(request.args.get("gun"))
    worklist_items, diagnostics = _dicom_worklist_rows(selected_date)
    local_rows = []
    unmatched = []
    matched_today = 0
    try:
        with db_conn() as con:
            _ensure_dicom_ai_tables(con)
            _ensure_dicom_worklist_tables(con)
            con.row_factory = lambda cur, row: {
                d[0]: row[i] for i, d in enumerate(cur.description)}
            local_rows = [dict(r) for r in con.execute("""
                SELECT * FROM dicom_worklist_exports
                WHERE scheduled_date=?
                ORDER BY scheduled_time, updated_at DESC
            """, (selected_date,)).fetchall()]
            row_count = con.execute("""
                SELECT COUNT(*) AS n FROM dicom_worklist_exports
                WHERE scheduled_date=? AND COALESCE(matched_study_id,'')<>''
            """, (selected_date,)).fetchone()
            matched_today = int((row_count or {}).get("n") or 0)
            unmatched = [dict(r) for r in con.execute("""
                SELECT orthanc_study_id, patient_name, patient_id, study_date,
                       accession_number, matched_confidence, match_reason
                FROM dicom_studies
                WHERE COALESCE(patient_key,'')=''
                ORDER BY COALESCE(study_date,'') DESC, updated_at DESC
                LIMIT 20
            """).fetchall()]
    except Exception as ex:
        diagnostics["status_error"] = f"{type(ex).__name__}: {ex}"
    live, live_path, live_error = _orthanc_worklist_live_items("Simplify")
    orthanc_url, _user, _password, _headers = _get_orthanc_config()
    host = ORTHANC_DEFAULT_HOST
    try:
        host = urlsplit(orthanc_url).hostname or host
    except Exception:
        pass
    mwl_cfg = _get_orthanc_mwl_config()
    return jsonify({
        "ok": True,
        "date": selected_date,
        "planned_count": len(worklist_items),
        "local_sent_count": len(local_rows),
        "live_count": len(live or []),
        "matched_today": matched_today,
        "unmatched_studies": unmatched,
        "diagnostics": diagnostics,
        "voluson_worklist": {
            "server_aet": mwl_cfg.get("server_aet") or "ORTHANC",
            "ip": host,
            "port": _get_voluson_worklist_public_port(),
            "tls": "kapali",
            "note": "Portproxy 104->4242 aktifse 104, degilse genelde 4242 kullanilir.",
        },
        "orthanc": {
            "http": orthanc_url,
            "aet": mwl_cfg.get("server_aet") or "ORTHANC",
            "dicom_internal_port": mwl_cfg.get("dicom_port") or "4242",
            "live_path": live_path,
            "live_error": live_error,
        },
        "local_exports": local_rows[:200],
    })


@app.route("/api/dicom/worklist/bugunu-gonder", methods=["POST"])
@login_required
def api_dicom_worklist_send_day():
    data = request.get_json(silent=True) or {}
    selected_date = _dicom_worklist_parse_date(
        data.get("date") or data.get("gun") or request.args.get("gun"))
    dry_run = str(
        data.get("dry_run", request.args.get("dry_run", "0"))
    ).lower() in {"1", "true", "evet", "yes", "dry"}
    try:
        limit = int(float(str(data.get("limit") or 80).replace(",", ".")))
    except Exception:
        limit = 80
    limit = max(1, min(limit, 300))
    items, diagnostics = _dicom_worklist_rows(selected_date)
    sent = []
    errors = []
    for item in items[:limit]:
        patient_key = str(item.get("patient_key") or "").strip()
        if not patient_key:
            continue
        time_text = str(item.get("appointment_time") or "")[:5]
        purpose = str(item.get("purpose") or "Obstetrik USG")
        payload_data = {
            "date": selected_date,
            "time": "" if time_text == "--:--" else time_text,
            "procedure": purpose,
            "purpose": purpose,
            "modality": _dicom_worklist_modality(purpose),
            "station_aet": _get_orthanc_mwl_config().get("station_aet") or VOLUSON_AET,
            "appointment_id": str(item.get("id") or item.get("appointment_id") or ""),
            "visit_key": str(item.get("visit_key") or ""),
        }
        try:
            payload, meta = _dicom_worklist_build_payload(patient_key, payload_data)
            if dry_run:
                sent.append({"patient_key": patient_key, "meta": meta, "dry_run": True})
                continue
            orthanc_path, response_payload = _orthanc_worklist_create(payload)
            orthanc_id = _save_dicom_worklist_export(
                meta, payload, orthanc_path, response_payload)
            verification = _dicom_worklist_verify_live(meta)
            try:
                with db_conn() as con:
                    _ensure_dicom_worklist_tables(con)
                    con.execute("""
                        UPDATE dicom_worklist_exports
                        SET live_verified=?, last_message=?, updated_at=?
                        WHERE accession_number=?
                    """, (
                        1 if verification.get("verified") else 0,
                        "Canli Worklist dogrulandi." if verification.get("verified")
                        else "Orthanc'a yazildi; canli listede anlik dogrulanamadi.",
                        datetime.now().isoformat(timespec="seconds"),
                        meta.get("accession_number"),
                    ))
                    con.commit()
            except Exception:
                pass
            sent.append({
                "patient_key": patient_key,
                "orthanc_worklist_id": orthanc_id,
                "meta": meta,
                "verified": bool(verification.get("verified")),
            })
        except Exception as ex:
            errors.append({
                "patient_key": patient_key,
                "error": f"{type(ex).__name__}: {ex}",
            })
    return jsonify({
        "ok": not errors,
        "date": selected_date,
        "dry_run": dry_run,
        "sent_count": len(sent),
        "error_count": len(errors),
        "sent": sent,
        "errors": errors,
        "diagnostics": diagnostics,
        "message": (
            "Gunluk Worklist kayitlari hazirlandi. Voluson cihazinda Worklist > Query/Refresh yapin."
            if not dry_run else
            "Gunluk Worklist taslagi hazirlandi; dry_run nedeniyle Orthanc'a yazilmadi."
        ),
    }, 200 if not errors else 207)


