    mwl_cfg = _get_orthanc_mwl_config()
    mwl_server_aet = mwl_cfg.get("server_aet") or "ORTHANC"
    mwl_station_aet = mwl_cfg.get("station_aet") or "VOLUSON"
    mwl_internal_port = str(mwl_cfg.get("dicom_port") or "4242")
    mwl_public_port = _get_voluson_worklist_public_port()
