@app.route("/hasta/<patient_key>/dicom-eslestir/<study_id>")
@login_required
def dicom_link_to_patient(patient_key, study_id):
    """DICOM Ã§alÄ±ÅŸmasÄ±nÄ± YazKlinik hastasÄ± ile eÅŸleÅŸtir."""
    try:
        with db_conn() as con:
            con.execute("""
                CREATE TABLE IF NOT EXISTS dicom_patient_links (
                    patient_key TEXT,
                    study_id TEXT,
                    linked_at TEXT,
                    linked_by TEXT,
                    PRIMARY KEY(patient_key, study_id))
            """)
            con.execute(
                "INSERT OR REPLACE INTO dicom_patient_links"
                "(patient_key, study_id, linked_at, linked_by)"
                " VALUES(?,?,?,?)",
                (patient_key, study_id,
                  datetime.now().isoformat(sep=" ",
                                              timespec="seconds"),
                  session.get("user", "?")))
            con.commit()
        _log_audit("dicom_link", entity_type="patient",
                    patient_key=patient_key,
                    details=study_id[:16])
        flash(f"âœ“ DICOM Ã§alÄ±ÅŸmasÄ± {patient_key} hastasÄ±na "
              f"eÅŸleÅŸtirildi.", "success")
    except Exception as ex:
        flash(f"Hata: {ex}", "danger")
    return redirect(url_for("dicom_dashboard"))


def _pdf_editor_patient_name(patient_key):
    try:
        with db_conn() as con:
            row = con.execute(
                "SELECT display_name FROM patients WHERE folder_key=?",
                (patient_key,)).fetchone()
            if row and row[0]:
                return str(row[0])
    except Exception:
        pass
    return str(patient_key)


def _pdf_editor_patient_summary(patient_key):
    name = _pdf_editor_patient_name(patient_key)
    try:
        demo = load_patient_demographics(patient_key) or {}
    except Exception:
        demo = {}
    try:
        snapshot = _patient_latest_clinical_snapshot(patient_key)
    except Exception:
        snapshot = {}
    lines = [
        f"Hasta: {name}",
        f"Protokol/Klasor: {patient_key}",
    ]
    if demo.get("age"):
        lines.append(f"Yas: {demo.get('age')}")
    if demo.get("weight"):
        lines.append(f"Kilo: {demo.get('weight')} kg")
    if demo.get("height"):
        lines.append(f"Boy: {demo.get('height')} cm")
    if demo.get("phone"):
        lines.append(f"Telefon: {demo.get('phone')}")
    if demo.get("lmp_override"):
        lines.append(f"LMP: {demo.get('lmp_override')}")
    if demo.get("gravida") is not None:
        lines.append(
            "GPAL: "
            f"G{demo.get('gravida')} "
            f"P{demo.get('para') or 0} "
            f"A{demo.get('abortus') or 0} "
            f"L{demo.get('living') or 0}")
    try:
        flags = get_patient_flags(patient_key)
        active = [
            PATIENT_FLAG_LABELS.get(k, k)
            for k, v in flags.items()
            if v.get("value") == "1"
        ]
        if active:
            lines.append("Aktif risk/bayrak: " + ", ".join(active[:8]))
    except Exception:
        pass
    lines.extend(_snapshot_lines_for_diet(snapshot)[:4])
    try:
        labs = list_lab_results(patient_key)[:3]
        if labs:
            lab_bits = []
            for lab in labs:
                values = lab.get("values") or {}
                value_text = ", ".join(
                    f"{k}:{v.get('value')}{v.get('unit', '')}"
                    for k, v in list(values.items())[:4])
                if value_text:
                    lab_bits.append(f"{lab.get('test_date', '')} {value_text}")
            if lab_bits:
                lines.append("Son tahliller: " + " | ".join(lab_bits[:3]))
    except Exception:
        pass
    return "\n".join(lines)


def _pdf_editor_list_pdfs(patient_key, limit=120):
    root = _patient_root_for_nas(patient_key)
    items = []
    seen = set()
    try:
        entries = [
            e for e in _scan_patient_nas_media(
                patient_key, max_candidates=max(limit, 240), timeout=7.5)
            if e.get("kind") == "pdf"
        ]
    except Exception:
        entries = []
    for entry in entries:
        if len(items) >= limit:
            break
        try:
            path = Path(entry.get("path"))
            rel_url = _patient_media_rel_url(patient_key, path)
            if not rel_url:
                continue
            key = _media_path_key(path)
            if key in seen:
                continue
            seen.add(key)
            folder = ""
            try:
                folder = path.parent.resolve().relative_to(root.resolve()).as_posix()
            except Exception:
                folder = path.parent.name
            items.append({
                "rel": rel_url,
                "name": path.name,
                "folder": folder or ".",
                "size_mb": float(entry.get("size") or path.stat().st_size or 0) / (1024 * 1024),
                "mtime": datetime.fromtimestamp(
                    float(entry.get("mtime") or path.stat().st_mtime or 0)
                ).strftime("%d.%m.%Y %H:%M"),
            })
        except Exception:
            continue
    return items


def _pdf_editor_wrap_lines(text, width=92):
    import textwrap
    lines = []
    for paragraph in str(text or "").replace("\r", "").split("\n"):
        paragraph = paragraph.strip()
        if not paragraph:
            lines.append("")
            continue
        wrapped = textwrap.wrap(
            paragraph,
            width=max(40, int(width or 92)),
            replace_whitespace=False,
            drop_whitespace=True,
        )
        lines.extend(wrapped or [paragraph])
    return lines


def _pdf_editor_insert_textbox(page, rect, text, fontsize=10.5,
                               color=(0.08, 0.14, 0.16), align=0,
                               fontname="helv"):
    try:
        return page.insert_textbox(
            rect, str(text or ""), fontsize=fontsize, fontname=fontname,
            color=color, align=align)
    except Exception:
        ascii_text = unicodedata.normalize("NFKD", str(text or "")).encode(
            "ascii", "ignore").decode("ascii")
        return page.insert_textbox(
            rect, ascii_text, fontsize=fontsize, fontname=fontname,
            color=color, align=align)


def _pdf_editor_add_report_pages(doc, patient_key, title, body,
                                 include_summary=True):
    if not HAS_FITZ:
        raise RuntimeError("PyMuPDF yok")
    patient_name = _pdf_editor_patient_name(patient_key)
    clinic = get_clinic_name()
    doctor = get_clinic_doctor_name()
    now_text = datetime.now().strftime("%d.%m.%Y %H:%M")
    body_text = str(body or "").strip()
    if include_summary:
        body_text = (
            "[HASTA OZETI]\n"
            + _pdf_editor_patient_summary(patient_key)
            + "\n\n[RAPOR METNI]\n"
            + (body_text or "Klinik rapor notu girilmedi."))
    lines = _pdf_editor_wrap_lines(body_text, width=92)
    if not lines:
        lines = ["Klinik rapor notu girilmedi."]
    per_page = 42
    chunks = [lines[i:i + per_page] for i in range(0, len(lines), per_page)]
    for page_no, chunk in enumerate(chunks, start=1):
        page = doc.new_page(width=595, height=842)
        page.draw_rect(fitz.Rect(0, 0, 595, 96), color=(0.07, 0.23, 0.21),
                       fill=(0.07, 0.23, 0.21))
        page.draw_rect(fitz.Rect(32, 116, 563, 760),
                       color=(0.82, 0.88, 0.86), width=0.8)
        _pdf_editor_insert_textbox(
            page, fitz.Rect(36, 24, 420, 55),
            title or "YazKlinik Rapor Duzenleme",
            fontsize=18, color=(1, 1, 1))
        _pdf_editor_insert_textbox(
            page, fitz.Rect(36, 58, 420, 82),
            f"{patient_name}  |  {patient_key}",
            fontsize=10.5, color=(0.86, 0.95, 0.92))
        _pdf_editor_insert_textbox(
            page, fitz.Rect(410, 26, 560, 82),
            f"{clinic}\n{doctor}\n{now_text}",
            fontsize=8.5, color=(0.86, 0.95, 0.92), align=2)
        _pdf_editor_insert_textbox(
            page, fitz.Rect(48, 132, 548, 736),
            "\n".join(chunk),
            fontsize=10.5, color=(0.07, 0.12, 0.14))
        _pdf_editor_insert_textbox(
            page, fitz.Rect(44, 772, 552, 806),
            f"YazKlinik v1000 Rapor Editoru - ek sayfa {page_no}/{len(chunks)}",
            fontsize=8.5, color=(0.35, 0.42, 0.45), align=1)


def _pdf_editor_stamp_pages(doc, stamp_text="", footer_text="",
                            add_page_numbers=True):
    now_text = datetime.now().strftime("%d.%m.%Y %H:%M")
    total = doc.page_count
    for index in range(total):
        page = doc[index]
        rect = page.rect
        if stamp_text:
            _pdf_editor_insert_textbox(
                page,
                fitz.Rect(rect.x0 + 34, rect.y0 + 18, rect.x1 - 34, rect.y0 + 42),
                stamp_text,
                fontsize=8.5,
                color=(0.58, 0.20, 0.12),
                align=1)
        footer_parts = []
        if footer_text:
            footer_parts.append(footer_text)
        footer_parts.append(f"YazKlinik v1000 - {now_text}")
        if add_page_numbers:
            footer_parts.append(f"Sayfa {index + 1}/{total}")
        _pdf_editor_insert_textbox(
            page,
            fitz.Rect(rect.x0 + 34, rect.y1 - 38, rect.x1 - 34, rect.y1 - 16),
            " | ".join(footer_parts),
            fontsize=7.5,
            color=(0.35, 0.42, 0.45),
            align=1)


def _pdf_editor_save_upload(patient_key, upload):
    if not upload or not upload.filename:
        return None
    if not upload.filename.lower().endswith(".pdf"):
        raise RuntimeError("Yuklenen dosya PDF olmali.")
    work_dir = _patient_root_for_nas(patient_key) / "_Rapor_Editoru" / "_Yuklenenler"
    filename = _safe_upload_filename(upload.filename, fallback="rapor.pdf")
    if not filename.lower().endswith(".pdf"):
        filename += ".pdf"
    dest = _unique_child_path(
        work_dir,
        f"gelen_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{filename}")
    upload.save(str(dest))
    return dest


def _pdf_editor_build_output(patient_key, form, upload):
    if not HAS_FITZ:
        raise RuntimeError("PDF motoru yuklu degil. PyMuPDF kurulmasi gerekiyor.")
    source_path = None
    uploaded_path = _pdf_editor_save_upload(patient_key, upload)
    source_rel = (form.get("source_pdf") or "").strip()
    if source_rel:
        source_path = _resolve_patient_relative_media_path(patient_key, source_rel)
        if _file_kind_for_path(source_path) != "pdf":
            raise RuntimeError("Secilen kaynak PDF degil.")
    elif uploaded_path:
        source_path = uploaded_path

    doc = fitz.open(str(source_path)) if source_path else fitz.open()
    try:
        title = (form.get("report_title") or "YazKlinik Rapor Duzenleme").strip()
        report_body = (form.get("report_body") or "").strip()
        add_report_page = form.get("add_report_page") == "on"
        if doc.page_count == 0:
            add_report_page = True
        if add_report_page:
            _pdf_editor_add_report_pages(
                doc,
                patient_key,
                title,
                report_body,
                include_summary=form.get("include_patient_summary") == "on")
        if form.get("stamp_all_pages") == "on" or form.get("page_numbers") == "on":
            _pdf_editor_stamp_pages(
                doc,
                stamp_text=(form.get("stamp_text") or "").strip(),
                footer_text=(form.get("footer_text") or "").strip(),
                add_page_numbers=form.get("page_numbers") == "on")
        if doc.page_count == 0:
            raise RuntimeError("Olusturulacak PDF sayfasi yok.")
        work_dir = _patient_root_for_nas(patient_key) / "_Rapor_Editoru"
        out_name = _safe_upload_filename(
            form.get("output_name") or
            f"YazKlinik_Rapor_Editoru_{datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf",
            fallback="YazKlinik_Rapor_Editoru.pdf")
        if not out_name.lower().endswith(".pdf"):
            out_name += ".pdf"
        out_path = _unique_child_path(work_dir, out_name)
        doc.save(str(out_path), garbage=4, deflate=True)
    finally:
        try:
            doc.close()
        except Exception:
            pass
    _log_audit("pdf_report_editor", entity_type="patient",
               patient_key=patient_key, details=out_path.name)
    return out_path


