def _db_file_bytes(path) -> int:
    try:
        p = Path(path)
        if p.exists():
            return int(p.stat().st_size)
    except Exception:
        pass
    return 0


def _fmt_bytes(value) -> str:
    try:
        size = float(value or 0)
    except Exception:
        size = 0.0
    units = ("B", "KB", "MB", "GB", "TB")
    idx = 0
    while size >= 1024 and idx < len(units) - 1:
        size /= 1024.0
        idx += 1
    if idx == 0:
        return f"{int(size)} {units[idx]}"
    return f"{size:.1f} {units[idx]}"


def _sqlite_ident(name: str) -> str:
    return '"' + str(name).replace('"', '""') + '"'


def _sqlite_table_exists(con, table: str) -> bool:
    try:
        return bool(con.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
            (str(table),)).fetchone())
    except Exception:
        return False


def _database_size_snapshot() -> dict:
    db_path = Path(DB_PATH)
    wal_path = Path(str(db_path) + "-wal")
    shm_path = Path(str(db_path) + "-shm")
    info = {
        "db_path": str(db_path),
        "db_bytes": _db_file_bytes(db_path),
        "wal_bytes": _db_file_bytes(wal_path),
        "shm_bytes": _db_file_bytes(shm_path),
        "page_count": 0,
        "freelist_count": 0,
        "page_size": 0,
        "journal_mode": "?",
    }
    try:
        with db_conn() as con:
            info["page_count"] = int(
                con.execute("PRAGMA page_count").fetchone()[0] or 0)
            info["freelist_count"] = int(
                con.execute("PRAGMA freelist_count").fetchone()[0] or 0)
            info["page_size"] = int(
                con.execute("PRAGMA page_size").fetchone()[0] or 0)
            row = con.execute("PRAGMA journal_mode").fetchone()
            if row:
                info["journal_mode"] = str(row[0])
    except Exception:
        pass
    info["total_bytes"] = (info["db_bytes"] + info["wal_bytes"] +
                           info["shm_bytes"])
    info["free_bytes_est"] = info["freelist_count"] * info["page_size"]
    return info


def _database_volatile_table_counts() -> list[tuple[str, int]]:
    tables = [
        "web_audit_log",
        "user_route_usage",
        "patient_media_archive",
        "consent_forms",
        "ready_prescription_templates",
    ]
    rows = []
    try:
        with db_conn() as con:
            for table in tables:
                if not _sqlite_table_exists(con, table):
                    continue
                count = con.execute(
                    f"SELECT COUNT(*) FROM {_sqlite_ident(table)}"
                ).fetchone()[0]
                rows.append((table, int(count or 0)))
    except Exception:
        pass
    return rows


def _database_blob_summary(limit: int = 12) -> list[dict]:
    rows = []
    try:
        with db_conn() as con:
            table_names = [
                str(r[0]) for r in con.execute(
                    "SELECT name FROM sqlite_master "
                    "WHERE type='table' AND name NOT LIKE 'sqlite_%' "
                    "ORDER BY name").fetchall()
            ]
            for table in table_names:
                q_table = _sqlite_ident(table)
                try:
                    columns = con.execute(
                        f"PRAGMA table_info({q_table})").fetchall()
                except Exception:
                    continue
                for col in columns:
                    col_name = str(col[1])
                    col_type = str(col[2] or "").upper()
                    if "BLOB" not in col_type:
                        continue
                    q_col = _sqlite_ident(col_name)
                    try:
                        stat = con.execute(
                            "SELECT COUNT({col}), "
                            "COALESCE(SUM(length({col})),0), "
                            "COALESCE(MAX(length({col})),0) "
                            "FROM {table} WHERE {col} IS NOT NULL".format(
                                col=q_col, table=q_table)).fetchone()
                    except Exception:
                        continue
                    count = int(stat[0] or 0)
                    total = int(stat[1] or 0)
                    max_bytes = int(stat[2] or 0)
                    if count or total:
                        rows.append({
                            "table": table,
                            "column": col_name,
                            "count": count,
                            "total_bytes": total,
                            "max_bytes": max_bytes,
                        })
    except Exception:
        pass
    rows.sort(key=lambda r: int(r.get("total_bytes") or 0), reverse=True)
    return rows[:int(limit or 12)]


def _database_blob_summary_html(rows: list[dict]) -> str:
    if not rows:
        return """
        <div class="alert alert-success mb-0">
          DB icinde BLOB kolon kullanimi bulunmadi. Buyuk dosyalar icin
          kisayol mantigi aktif kalmaya devam eder.
        </div>
        """
    body = ""
    total = 0
    for row in rows:
        total += int(row.get("total_bytes") or 0)
        level = (
            "warning"
            if int(row.get("total_bytes") or 0) > 10 * 1024 * 1024
            else "secondary")
        body += f"""
        <tr>
          <td><code>{sh(row.get("table", ""))}</code></td>
          <td><code>{sh(row.get("column", ""))}</code></td>
          <td>{int(row.get("count") or 0)}</td>
          <td><span class="badge bg-{level}">{_fmt_bytes(row.get("total_bytes"))}</span></td>
          <td>{_fmt_bytes(row.get("max_bytes"))}</td>
        </tr>
        """
    alert = "warning" if total > 25 * 1024 * 1024 else "info"
    return f"""
    <div class="alert alert-{alert}">
      DB icindeki dosya/blob toplam tahmini: <b>{_fmt_bytes(total)}</b>.
      Multimedya arsivi DB'ye dosya gommez; sadece yol, kisayol ve boyut tutar.
    </div>
    <div class="table-responsive">
      <table class="table table-sm align-middle">
        <thead>
          <tr><th>Tablo</th><th>Kolon</th><th>Kayit</th><th>Toplam</th><th>En buyuk</th></tr>
        </thead>
        <tbody>{body}</tbody>
      </table>
    </div>
    """


def _run_database_bloat_maintenance(vacuum: bool = False,
                                    keep_days: int = 180,
                                    route_limit: int = 3000) -> dict:
    keep_days = max(30, min(3650, int(keep_days or 180)))
    route_limit = max(500, min(50000, int(route_limit or 3000)))
    before = _database_size_snapshot()
    cutoff = (datetime.now() - timedelta(days=keep_days)).isoformat(
        sep=" ", timespec="seconds")
    deleted_audit = 0
    deleted_usage_old = 0
    deleted_usage_cap = 0
    backup_path = ""

    if vacuum:
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_target = Path(DB_PATH).parent / "auto_backups" / (
            f"db_bakim_oncesi_{stamp}.sqlite3")
        backup_database(backup_target)
        backup_path = str(backup_target)

    with db_conn() as con:
        if _sqlite_table_exists(con, "web_audit_log"):
            cur = con.execute(
                "DELETE FROM web_audit_log WHERE timestamp < ?",
                (cutoff,))
            deleted_audit = max(int(cur.rowcount or 0), 0)
        if _sqlite_table_exists(con, "user_route_usage"):
            cur = con.execute(
                "DELETE FROM user_route_usage WHERE last_seen < ?",
                (cutoff,))
            deleted_usage_old = max(int(cur.rowcount or 0), 0)
            cur = con.execute(
                "DELETE FROM user_route_usage WHERE id NOT IN ("
                "SELECT id FROM user_route_usage "
                "ORDER BY last_seen DESC LIMIT ?)",
                (route_limit,))
            deleted_usage_cap = max(int(cur.rowcount or 0), 0)
        con.commit()

    checkpoint_rows = []
    try:
        raw = sqlite3.connect(str(DB_PATH), timeout=60, isolation_level=None)
        try:
            raw.execute("PRAGMA busy_timeout=30000")
            checkpoint_rows = raw.execute(
                "PRAGMA wal_checkpoint(TRUNCATE)").fetchall()
            raw.execute("PRAGMA optimize")
            if vacuum:
                raw.execute("VACUUM")
        finally:
            raw.close()
    except Exception as ex:
        if is_sqlite_malformed_error(ex):
            recovery = recover_malformed_database(
                f"database bloat maintenance: {ex}", recreate=True)
            checkpoint_rows = [("recovered", str(recovery.get("backup_dir", "")))]
        else:
            raise

    after = _database_size_snapshot()
    return {
        "keep_days": keep_days,
        "route_limit": route_limit,
        "deleted_audit": deleted_audit,
        "deleted_usage_old": deleted_usage_old,
        "deleted_usage_cap": deleted_usage_cap,
        "checkpoint": checkpoint_rows,
        "vacuum": bool(vacuum),
        "backup_path": backup_path,
        "before": before,
        "after": after,
    }


def _run_manual_database_repair() -> dict:
    """User-triggered DB repair: backup first, then verify/rebuild schema."""
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    db_path = Path(DB_PATH)
    report = {
        "status": "started",
        "db_path": str(db_path),
        "backup_path": "",
        "backup_error": "",
        "recovery_dir": "",
        "detail": "",
        "health_status": "",
    }

    if db_path.exists():
        backup_target = db_path.parent / "auto_backups" / (
            f"db_onarim_oncesi_{stamp}.sqlite3")
        try:
            backup_info = backup_database(backup_target)
            report["backup_path"] = str(
                backup_info.get("path") or backup_target)
        except Exception as ex:
            # Corrupt DB files often cannot be copied with SQLite backup API.
            # Keep going: recover_malformed_database will quarantine sidecars.
            report["backup_error"] = str(ex)

    try:
        info = ensure_database_ready(recreate=True)
    except Exception as ex:
        if not is_sqlite_malformed_error(ex):
            raise
        info = recover_malformed_database(
            f"manual database repair: {ex}", recreate=True)

    report["status"] = str(info.get("status") or "ok")
    report["recovery_dir"] = str(info.get("backup_dir") or "")
    report["detail"] = str(info)

    health = database_health_check(fast=True)
    report["health_status"] = str(health.get("status") or "?")
    return report


