_DB_BLOAT_GUARD_LAST = 0.0


@app.before_request
def _auto_database_bloat_guard():
    """Daily light maintenance: prune volatile logs and trim WAL."""
    global _DB_BLOAT_GUARD_LAST
    try:
        path = request.path or ""
        if path.startswith(("/static/", "/api/", "/favicon", "/brand-logo")):
            return
        now_ts = datetime.now().timestamp()
        if now_ts - float(_DB_BLOAT_GUARD_LAST or 0.0) < 3600:
            return
        marker = _db_get_setting("db_bloat_guard_last", "0")
        try:
            if marker and now_ts - float(marker) < 24 * 3600:
                _DB_BLOAT_GUARD_LAST = now_ts
                return
        except Exception:
            pass
        _DB_BLOAT_GUARD_LAST = now_ts
        _run_database_bloat_maintenance(
            vacuum=False, keep_days=180, route_limit=3000)
        _db_set_setting("db_bloat_guard_last", str(now_ts))
    except Exception as ex:
        print(f"db bloat guard: {ex}")


@app.route("/veritabani-saglik-kontrol", methods=["GET", "POST"])
@login_required
def database_health_page():
    """VeritabanÄ± bÃ¼tÃ¼nlÃ¼k, WAL ve iliÅŸki saÄŸlÄ±ÄŸÄ± kontrolÃ¼."""
    if session.get("role") != "doktor":
        flash("Sadece doktor.", "danger")
        return redirect(url_for("home"))

    maintenance_html = ""
    if request.method == "POST":
        action = request.form.get("action", "prune")
        try:
            if action == "repair":
                result = _run_manual_database_repair()
                backup_line = ""
                if result.get("backup_path"):
                    backup_line = (
                        "<br>Onarim oncesi yedek: "
                        f"<code>{sh(result.get('backup_path'))}</code>")
                if result.get("backup_error"):
                    backup_line += (
                        "<br>Normal yedek alinamadi; bozuk DB karantinasi "
                        f"denendi: <code>{sh(result.get('backup_error'))}</code>")
                recovery_line = ""
                if result.get("recovery_dir"):
                    recovery_line = (
                        "<br>Bozuk DB karantina klasoru: "
                        f"<code>{sh(result.get('recovery_dir'))}</code>")
                maintenance_html = f"""
                <div class="alert alert-success">
                  Veritabani onarim kontrolu tamamlandi.
                  Durum: <b>{sh(result.get('status'))}</b>,
                  saglik: <b>{sh(result.get('health_status'))}</b>.
                  {backup_line}{recovery_line}
                </div>
                """
                flash("Veritabani onarim kontrolu tamamlandi.", "success")
            else:
                try:
                    keep_days = int(
                        request.form.get("keep_days", "180") or 180)
                except Exception:
                    keep_days = 180
                try:
                    route_limit = int(
                        request.form.get("route_limit", "3000") or 3000)
                except Exception:
                    route_limit = 3000
                result = _run_database_bloat_maintenance(
                    vacuum=(action == "vacuum"),
                    keep_days=keep_days,
                    route_limit=route_limit)
                before = result["before"]
                after = result["after"]
                freed = max(0, int(before.get("total_bytes") or 0) -
                            int(after.get("total_bytes") or 0))
                backup_line = ""
                if result.get("backup_path"):
                    backup_line = (
                        "<br>VACUUM oncesi yedek: "
                        f"<code>{sh(result.get('backup_path'))}</code>")
                maintenance_html = f"""
                <div class="alert alert-success">
                  Bakim tamamlandi. Audit silinen: {result['deleted_audit']},
                  kullanim eski silinen: {result['deleted_usage_old']},
                  kullanim limit fazlasi: {result['deleted_usage_cap']}.
                  Kazanc: <b>{_fmt_bytes(freed)}</b>.{backup_line}
                </div>
                """
                flash("Veritabani bakimi tamamlandi.", "success")
        except Exception as ex:
            maintenance_html = f"""
            <div class="alert alert-danger">
              Veritabani islem hatasi: {sh(ex)}
            </div>
            """
            flash(f"Veritabani islem hatasi: {ex}", "danger")

    info = database_health_check(fast=True)
    snapshot = _database_size_snapshot()
    volatile_counts = _database_volatile_table_counts()
    blob_rows = _database_blob_summary()
    status = str(info.get("status", "?"))
    badge = "success" if status == "ok" else (
        "warning" if status == "warning" else "danger")
    rows = ""
    for key, value in info.items():
        rows += (
            "<tr>"
            f"<td><code>{sh(str(key))}</code></td>"
            f"<td>{sh(str(value))}</td>"
            "</tr>")

    content = f"""
 <a href="/sistem-durumu" class="btn btn-secondary mb-3">
 <- Sistem Durumu
 </a>
 <div class="card">
 <div class="card-header d-flex justify-content-between">
 <b>ğŸ’¾ VeritabanÄ± SaÄŸlÄ±k KontrolÃ¼</b>
 <span class="badge bg-{badge}">{sh(status.upper())}</span>
 </div>
 <div class="card-body">
 <p class="text-muted">
 YazKlinik Pro Final, SQLite veritabanÄ±nÄ± WAL,
 busy timeout, foreign key ve quick check ile denetler.
 </p>
 <table class="table table-sm">
 <tbody>{rows}</tbody>
        </table>
      </div>
    </div>
    """
    content = (_database_bloat_panel_html(
        maintenance_html, snapshot, volatile_counts, blob_rows) + content)
    return render(content, title="VeritabanÄ± SaÄŸlÄ±k KontrolÃ¼")


@app.route("/sistem-cache-temizle")
@login_required
def system_cache_clear():
    """TÃ¼m cache'leri temizle."""
    if session.get("role") != "doktor":
        flash("Sadece doktor.", "danger")
        return redirect(url_for("home"))
    try:
        cache_invalidate()
        _AI_CACHE.clear()
        flash("âœ… TÃ¼m cache'ler temizlendi.", "success")
    except Exception as ex:
        flash(f"Hata: {ex}", "danger")
    return redirect(url_for("system_health"))


@app.route("/hasta/<patient_key>/canli-muayene",
            methods=["GET", "POST"])
@login_required
def live_consultation(patient_key):
    """Canli muayene kaydi:
    - F9 veya buton ile kaydi baslat/durdur
    - Whisper ile metne cevir
    - YZ ile yapilandirilmis ozet cikar
    - Tek tikla hasta dosyasina kaydet
    """
    import urllib.request as _urllib_req
    import urllib.error as _urllib_err
    import json as _json
    import base64 as _b64

    summary_data = None
    error_msg = ""

    if request.method == "POST":
        action = request.form.get("action", "summarize")

        if action == "summarize":
            audio_b64 = request.form.get("audio_b64", "")
            native_text = (request.form.get("native_text") or "").strip()
            duration = request.form.get("duration", "0")
            if not audio_b64 and not native_text:
                error_msg = "Ses kaydi bulunamadi."
            else:
                try:
                    if native_text:
                        audio_bytes = b""
                    else:
                        if "," in audio_b64:
                            audio_b64 = audio_b64.split(",", 1)[1]
                        audio_bytes = _b64.b64decode(audio_b64)

                    # 1. WHISPER TRANSKRIPT
                    transcript = ""
                    speaker_segments = []
                    if native_text:
                        transcript = native_text
                    else:
                        try:
                            transcript = _ai_phone_transcribe_audio_bytes(
                                audio_bytes,
                                filename="consult.webm",
                                mime_type="audio/webm",
                                language="tr").strip()
                        except Exception as _ex:
                            error_msg = (
                                "Ses metne cevrilemedi: "
                                f"{sh(str(_ex))}")

                    if transcript and not error_msg:
                        # 2. YZ ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â°LE YAPILANDIR VE ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œZETLEx
                        # Hasta bilgisi al
                        try:
                            demo = load_patient_demographics(
                                patient_key)
                        except Exception:
                            demo = {}

                        ga_line = ""
                        try:
                            from datetime import timedelta
                            lmp_str = demo.get("lmp_override",
                                                "")
                            if lmp_str:
                                parts = lmp_str.split(".")
                                if len(parts) == 3:
                                    lmp_dt = datetime(
                                        int(parts[2]),
                                        int(parts[1]),
                                        int(parts[0]))
                                    ga_w = ((datetime.now()
                                              - lmp_dt).days
                                             // 7)
                                    ga_line = (f", {ga_w} hf "
                                                f"gebe")
                        except Exception:
                            pass

                        age = demo.get("age") or "-"

                        prompt = (
                            "[GOREV]\n"
                            "Asagidaki doktor-hasta gorusmesi transkriptini analiz et. "
                            "Klinik onemi olan tum bilgileri cikar.\n\n"
                            f"[HASTA BILGISI]\n"
                            f"Yas: {age}{ga_line}\n"
                            f"Mevcut ilaclar: {demo.get('medications', '-')}\n"
                            f"Alerji: {demo.get('allergies', '-')}\n\n"
                            "[TRANSKRIPT]\n"
                            f"{transcript}\n\n"
                            "[CIKTI - KESIN JSON FORMATI]\n"
                            "{\n"
                            '  "sikayet": "hastanin ana sikayeti",\n'
                            '  "oyku": "hastalik oykusu",\n'
                            '  "bulgular": ["fizik muayene bulgulari"],\n'
                            '  "tani": "klinik tani/ayirici tani",\n'
                            '  "tedavi": ["verilen ilaclar/islemler"],\n'
                            '  "takip": "kontrol onerisi",\n'
                            '  "uyarilar": ["dikkat edilmesi gerekenler"],\n'
                            '  "ozet": "1-2 cumlelik genel ozet"\n'
                            "}\n"
                            "Sadece JSON dondur. "
                            "Transkriptte olmayan bilgi uydurma. Turkce yaz.")

                        success, ai_response, _ = call_ollama(
                            prompt,
                            temperature=0.2,
                            max_tokens=2048,
                            use_cache=False,
                            timeout=180)

                        if success:
                            # JSON parse et
                            ai_text = ai_response
                            # Markdown code block varsa temizle
                            if "```json" in ai_text:
                                ai_text = ai_text.split(
                                    "```json")[1].split(
                                    "```")[0].strip()
                            elif "```" in ai_text:
                                ai_text = ai_text.split(
                                    "```")[1].split(
                                    "```")[0].strip()

                            try:
                                parsed = _json.loads(ai_text)
                                summary_data = {
                                    "transcript": transcript,
                                    "parsed": parsed,
                                    "duration": int(
                                        float(duration)),
                                    "segments":
                                    speaker_segments,
                                }
                            except _json.JSONDecodeError:
                                # JSON olmadÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±, ham metni gÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶ster
                                summary_data = {
                                    "transcript": transcript,
                                    "raw_ai": ai_response,
                                    "duration": int(
                                        float(duration)),
                                    "segments":
                                    speaker_segments,
                                }
                        else:
                            error_msg = ai_response

                        _log_audit("consultation_analyze",
                                    entity_type="patient",
                                    patient_key=patient_key,
                                    details=(f"dur:{duration}s, "
                                               f"chars:{len(transcript)}"))

                except Exception as ex:
                    error_msg = f"Isleme hatasi: {ex}"

        elif action == "save":
            # ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œzeti hasta dosyasÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±na kaydet
            transcript = request.form.get("transcript", "")
            ozet = request.form.get("ozet", "").strip()
            sikayet = request.form.get("sikayet", "").strip()
            bulgular = request.form.get("bulgular", "").strip()
            tani = request.form.get("tani", "").strip()
            tedavi = request.form.get("tedavi", "").strip()
            takip = request.form.get("takip", "").strip()
            uyarilar = request.form.get("uyarilar", "").strip()
            doctor_extra = request.form.get(
                "doctor_notes", "").strip()
            duration = request.form.get("duration", "0")

            try:
                with db_conn() as con:
                    now = datetime.now().isoformat(
                        sep=" ", timespec="seconds")
                    ts = datetime.now().strftime(
                        "%d.%m.%Y %H:%M")

                    # consultations tablosuna ham kayÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±t
                    ai_summary = _json.dumps({
                        "sikayet": sikayet,
                        "bulgular": bulgular,
                        "tani": tani,
                        "tedavi": tedavi,
                        "takip": takip,
                        "uyarilar": uyarilar,
                        "ozet": ozet,
                    }, ensure_ascii=False)

                    con.execute(
                        "INSERT INTO consultations("
                        "patient_key, started_at, "
                        "duration_seconds, raw_transcript, "
                        "ai_summary, doctor_notes, "
                        "created_by) VALUES(?,?,?,?,?,?,?)",
                        (patient_key, now,
                          int(float(duration)),
                          transcript[:20000],
                          ai_summary, doctor_extra,
                          session.get("user", "?")))

                    # Hasta notuna yapÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±landÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±rÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±lmÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶zet ekle
                    note_parts = [
                        f"[{ts} - {session.get('user', '?')} - CANLI MUAYENE]"]
                    if ozet:
                        note_parts.append(f"OZET: {ozet}")
                    if sikayet:
                        note_parts.append(f"SIKAYET: {sikayet}")
                    if bulgular:
                        note_parts.append(f"BULGULAR: {bulgular}")
                    if tani:
                        note_parts.append(f"TANI: {tani}")
                    if tedavi:
                        note_parts.append(f"TEDAVI: {tedavi}")
                    if takip:
                        note_parts.append(f"TAKIP: {takip}")
                    if uyarilar:
                        note_parts.append(f"UYARILAR: {uyarilar}")
                    if doctor_extra:
                        note_parts.append(f"DOKTOR NOTU: {doctor_extra}")
                    note_parts.append("-" * 40)

                    new_note = "\n".join(note_parts) + "\n\n"

                    row = con.execute(
                        "SELECT notes FROM patient_type "
                        "WHERE patient_key=?",
                        (patient_key,)).fetchone()
                    existing = (row[0] if row and row[0]
                                else "")
                    if row:
                        con.execute(
                            "UPDATE patient_type SET "
                            "notes=?, updated_at=? "
                            "WHERE patient_key=?",
                            (new_note + existing, now,
                              patient_key))
                    else:
                        con.execute(
                            "INSERT INTO patient_type("
                            "patient_key, ptype, is_manual, "
                            "notes, created_at, updated_at) "
                            "VALUES(?,?,?,?,?,?)",
                            (patient_key, "obstetric", 0,
                              new_note, now, now))
                    con.commit()

                _log_audit("consultation_save",
                            entity_type="patient",
                            patient_key=patient_key)
                flash("Muayene ozeti hasta dosyasina kaydedildi.", "success")
                try:
                    cache_invalidate("smart_notifications")
                except Exception:
                    pass
                return redirect(url_for(
                    "patient_detail",
                    patient_key=patient_key))

            except Exception as ex:
                error_msg = f"Kayit hatasi: {ex}"

    # === Render ===

    # Doktor sesi kayÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±tlÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± mÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±?
    doctor_voice_registered = False
