def _format_bytes_web(value):
    try:
        size = float(value or 0)
    except Exception:
        return "-"
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if size < 1024 or unit == "TB":
            return f"{size:.1f} {unit}" if unit != "B" else f"{int(size)} B"
        size /= 1024
    return "-"


_PATH_INFO_UI_CACHE = {}
_PATH_INFO_UI_CACHE_TTL = 20.0


def _is_slow_or_network_path(path_value):
    text = str(path_value or "").strip()
    return text.startswith("\\\\") or text.startswith("//")


def _path_info_for_ui(path_value, file_path=False, quick_count=False):
    path = Path(str(path_value or "")).expanduser()
    target = path.parent if file_path else path
    cache_key = (str(path), bool(file_path), bool(quick_count))
    now = time.time()
    cached = _PATH_INFO_UI_CACHE.get(cache_key)
    if cached and now - cached.get("ts", 0) < _PATH_INFO_UI_CACHE_TTL:
        return dict(cached["info"])
    info = {
        "path": str(path),
        "exists": False,
        "writable": False,
        "kind": "file" if file_path else "folder",
        "size": "",
        "file_count": "",
        "error": "",
    }
    try:
        info["exists"] = path.exists() if file_path else target.exists()
        if file_path and path.exists():
            info["size"] = _format_bytes_web(path.stat().st_size)
        if quick_count and target.exists() and target.is_dir():
            total = 0
            count = 0
            limit = 250 if _is_slow_or_network_path(target) else 600
            try:
                with os.scandir(target) as entries:
                    for entry in entries:
                        count += 1
                        if count > limit:
                            break
                        try:
                            if entry.is_file(follow_symlinks=False):
                                total += entry.stat(follow_symlinks=False).st_size
                        except Exception:
                            pass
            except Exception as ex:
                info["error"] = str(ex)
            suffix = "+" if count > limit else ""
            info["file_count"] = f"{count}{suffix} oge"
            info["size"] = _format_bytes_web(total)
        if target.exists() and target.is_dir():
            sentinel = target / ".yazklinik_write_test"
            try:
                if _is_slow_or_network_path(target):
                    info["writable"] = True
                else:
                    sentinel.write_text("ok", encoding="utf-8")
                    sentinel.unlink(missing_ok=True)
                    info["writable"] = True
            except Exception as ex:
                info["error"] = str(ex)
    except Exception as ex:
        info["error"] = str(ex)
    _PATH_INFO_UI_CACHE[cache_key] = {"ts": now, "info": dict(info)}
    return info


def _same_path_for_move(src, dst):
    try:
        return Path(src).expanduser().resolve() == Path(dst).expanduser().resolve()
    except Exception:
        return str(src or "").strip().casefold() == str(dst or "").strip().casefold()


def _copy_tree_merge_for_paths(src, dst, label, max_files=50000):
    import shutil
    src_path = Path(str(src or "")).expanduser()
    dst_path = Path(str(dst or "")).expanduser()
    result = {"label": label, "copied": 0, "skipped": 0, "errors": []}
    if not src_path.exists():
        result["skipped"] += 1
        result["errors"].append(f"Eski yol yok: {src_path}")
        return result
    if _same_path_for_move(src_path, dst_path):
        result["skipped"] += 1
        return result
    try:
        if src_path.is_file():
            dst_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(str(src_path), str(dst_path))
            result["copied"] += 1
            return result
        dst_path.mkdir(parents=True, exist_ok=True)
        for root_dir, dirs, files in os.walk(src_path):
            rel = Path(root_dir).relative_to(src_path)
            target_dir = dst_path / rel
            target_dir.mkdir(parents=True, exist_ok=True)
            for dirname in dirs:
                try:
                    (target_dir / dirname).mkdir(parents=True, exist_ok=True)
                except Exception as ex:
                    if len(result["errors"]) < 10:
                        result["errors"].append(f"{dirname}: {ex}")
            for name in files:
                if result["copied"] >= max_files:
                    result["errors"].append(
                        f"{max_files} dosya sinirina ulasildi; kalanlar atlandi")
                    return result
                source_file = Path(root_dir) / name
                target_file = target_dir / name
                try:
                    if target_file.exists():
                        try:
                            s1 = source_file.stat()
                            s2 = target_file.stat()
                            if s1.st_size == s2.st_size and s1.st_mtime <= s2.st_mtime:
                                result["skipped"] += 1
                                continue
                        except Exception:
                            pass
                    shutil.copy2(str(source_file), str(target_file))
                    result["copied"] += 1
                except Exception as ex:
                    if len(result["errors"]) < 10:
                        result["errors"].append(f"{source_file}: {ex}")
        return result
    except Exception as ex:
        result["errors"].append(str(ex))
        return result


def _copy_sqlite_snapshot_to_path(target_path):
    target = Path(str(target_path or "")).expanduser()
    result = {"label": "Veritabani", "copied": 0, "skipped": 0, "errors": []}
    try:
        if not DB_PATH or not Path(DB_PATH).exists():
            result["errors"].append("Aktif DB dosyasi bulunamadi")
            return result
        if _same_path_for_move(DB_PATH, target):
            result["skipped"] += 1
            return result
        target.parent.mkdir(parents=True, exist_ok=True)
        src = sqlite3.connect(str(DB_PATH))
        dst = sqlite3.connect(str(target))
        try:
            src.backup(dst)
        finally:
            src.close()
            dst.close()
        result["copied"] += 1
    except Exception as ex:
        result["errors"].append(str(ex))
    return result


def _write_path_alias_settings(key, value):
    aliases = {
        "nas_root": ("path_nas_root", "nas/path"),
        "patient_files_dir": ("path_patient_files_dir", "path_data_root",
                              "system/data_root", "data/root"),
        "multimedia_root": ("path_multimedia_root", "media/archive_root"),
        "backup_dir": ("path_backup_dir",),
        "db_path": ("path_db_path",),
    }
    for alias in aliases.get(key, (f"path_{key}",)):
        try:
            _db_set_setting(alias, value)
        except Exception:
            pass
    if HAS_PYSIDE6 and QSettings is not None:
        try:
            s = QSettings("YazKlinik", "yazklinik")
            if key == "nas_root":
                s.setValue("nas/path", value)
            elif key == "patient_files_dir":
                s.setValue("data/root", value)
            elif key == "multimedia_root":
                s.setValue("media/archive_root", value)
            elif key == "db_path":
                s.setValue("db/custom_path", value)
            s.sync()
        except Exception:
            pass


def _yk_state_root() -> Path:
    raw = (os.environ.get("YAZKLINIK_STATE_ROOT") or "").strip()
    return Path(raw).expanduser() if raw else Path(__file__).resolve().parent / "runtime_state"


