@app.route("/ilk-kurulum", methods=["GET", "POST"])
@login_required
def first_run_wizard():
    """ğŸš€ Ä°lk Kurulum SihirbazÄ± - 5 adÄ±mda sistemi yapÄ±landÄ±r."""
    if session.get("role") != "doktor":
        flash("Sadece doktor.", "danger")
        return redirect(url_for("home"))

    step = int(request.args.get("adim",
                                   request.form.get("adim", "1")))
    step = max(1, min(5, step))

    if request.method == "POST":
        action = request.form.get("action", "next")

        # Her adÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±mÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±n verisini kaydet
        try:
            with db_conn() as con:
                con.execute("""
                    CREATE TABLE IF NOT EXISTS settings (
                        key TEXT PRIMARY KEY, value TEXT)
                """)

                if step == 1:
                    # Klinik bilgileri
                    for k in ["clinic_name", "clinic_phone",
                               "clinic_address", "doctor_name",
                               "doctor_title"]:
                        v = request.form.get(k, "").strip()
                        if v:
                            con.execute(
                                "INSERT OR REPLACE INTO settings"
                                "(key, value) VALUES(?,?)",
                                (f"sysparam_{k}", v))

                elif step == 2:
                    # DB konumu
                    db_p = request.form.get(
                        "db_path", "").strip()
                    if db_p:
                        con.execute(
                            "INSERT OR REPLACE INTO settings"
                            "(key, value) VALUES(?,?)",
                            ("path_db_path", db_p))
                    bk_p = request.form.get(
                        "backup_dir", "").strip()
                    if bk_p:
                        con.execute(
                            "INSERT OR REPLACE INTO settings"
                            "(key, value) VALUES(?,?)",
                            ("path_backup_dir", bk_p))
                    nas_p = request.form.get("nas_root", "").strip()
                    if nas_p:
                        con.execute(
                            "INSERT OR REPLACE INTO settings"
                            "(key, value) VALUES(?,?)",
                            ("path_nas_root", nas_p))
                    media_p = request.form.get("multimedia_root", "").strip()
                    if media_p:
                        con.execute(
                            "INSERT OR REPLACE INTO settings"
                            "(key, value) VALUES(?,?)",
                            ("path_multimedia_root", media_p))
                        con.execute(
                            "INSERT OR REPLACE INTO settings"
                            "(key, value) VALUES(?,?)",
                            ("media/archive_root", media_p))
                    if HAS_PYSIDE6 and QSettings is not None:
                        try:
                            qs = QSettings("YazKlinik", "yazklinik")
                            if nas_p:
                                qs.setValue("nas/path", nas_p)
                            if media_p:
                                qs.setValue("media/archive_root", media_p)
                            qs.sync()
                        except Exception:
                            pass

                elif step == 3:
                    # Ollama
                    for k in ["ollama_url", "ollama_model",
                               "ollama_model_mode", "ollama_timeout"]:
                        v = request.form.get(k, "").strip()
                        if v:
                            if k == "ollama_model":
                                v = _normalize_ollama_model_name(v)
                            if k == "ollama_model_mode":
                                v = "manual" if _is_manual_model_mode(v) else "auto"
                            con.execute(
                                "INSERT OR REPLACE INTO settings"
                                "(key, value) VALUES(?,?)",
                                (f"sysparam_{k}", v))

                elif step == 4:
                    # Whisper + Orthanc
                    v = request.form.get("whisper_url", "").strip()
                    if v:
                        con.execute(
                            "INSERT OR REPLACE INTO settings"
                            "(key, value) VALUES(?,?)",
                            ("sysparam_whisper_url", v))
                    _save_orthanc_config(
                        con,
                        request.form.get("orthanc_url", "").strip(),
                        request.form.get("orthanc_user", "").strip(),
                        request.form.get("orthanc_pass", "").strip() or None)

                elif step == 5:
                    # TamamlandÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â± iÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸areti
                    con.execute(
                        "INSERT OR REPLACE INTO settings"
                        "(key, value) VALUES(?,?)",
                        ("first_run_complete",
                          datetime.now().isoformat(
                              sep=" ", timespec="seconds")))
                    con.commit()
                    flash("ğŸ‰ Kurulum tamamlandÄ±! UygulamayÄ± "
                          "yeniden baÅŸlatÄ±n.", "success")
                    return redirect(url_for("dashboard"))

                con.commit()
        except Exception as ex:
            flash(f"Kayit hatasÄ±: {ex}", "warning")

        if action == "next":
            return redirect(url_for("first_run_wizard",
                                      adim=step + 1))
        elif action == "back":
            return redirect(url_for("first_run_wizard",
                                      adim=step - 1))

    # AdÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±m iÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â§eriÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸i
