@app.route("/hasta/<patient_key>/tetkik-istemi")
@permission_required("view_test_order")
def test_order(patient_key):
    flags = get_patient_flags(patient_key)
    recommendations = recommend_lab_tests(patient_key, None, flags)

    if not recommendations:
        body = ('<div class="alert alert-success">'
                'TÃ¼m rutin tetkikler gÃ¼ncel; ek Ã¶neri yok.</div>')
    else:
        rows = ""
        for r in recommendations:
            badge = {'high': 'danger', 'medium': 'warning',
                      'low': 'info'}.get(r['priority'], 'secondary')
            extra = ""
            if r.get("last_date"):
                extra = (f"<br><small class='text-muted'>"
                         f"Son: {r['last_date']}</small>")
            rows += f"""
            <tr>
              <td><b>{r['test']}</b>{extra}</td>
              <td>{r['reason']}</td>
              <td><span class="badge bg-{badge}">
                {r['priority'].upper()}</span></td>
            </tr>
            """
        body = f"""
 <table class="table table-hover">
 <thead><tr><th>Tetkik</th><th>Sebep</th><th>Ã–ncelik</th></tr></thead>
 <tbody>{rows}</tbody>
        </table>
        <button class="btn btn-warning btn-lg" onclick="ykTestOrderPrint()">
          A4 Yazdir
        </button>
        """

    content = f"""
    <a href="/hasta/{patient_key}" class="btn btn-secondary mb-3">
      &larr; Hasta detay
    </a>
    <h2>Tetkik Listesi - {patient_key}</h2>
 <div id="printArea">
 <div class="text-center mb-3 d-none d-print-block">
 <h3>TETKÄ°K Ä°STEMÄ°</h3>
 <p>{patient_key} - {datetime.now().strftime('%d.%m.%Y')}</p>
      </div>
      {body}
    </div>
    <style>
      @media print {{
        @page {{ size:A4; margin:10mm; }}
        nav, .btn, .alert {{ display:none !important; }}
        .d-print-block {{ display:block !important; }}
      }}
    </style>
    <script>
      function ykTestOrderPrint() {{
        var st = document.getElementById('ykTestOrderPrintStyle');
        if (!st) {{
          st = document.createElement('style');
          st.id = 'ykTestOrderPrintStyle';
          document.head.appendChild(st);
        }}
        st.textContent = '@media print{{@page{{size:A4;margin:10mm;}}}}';
        window.print();
      }}
    </script>
    """
