_YK_STABILITY_JS = """
(function(){
  if (window.__YK_STABILITY_D96__) return;
  window.__YK_STABILITY_D96__ = true;
  var root = document.documentElement;
  root.classList.add('yk-stability-ready');

  function tuneNode(scope) {
    scope = scope || document;
    var nodes = [];
    try {
      if (scope.matches && scope.matches('img, video, iframe')) nodes = [scope];
      nodes = nodes.concat(Array.prototype.slice.call(scope.querySelectorAll ? scope.querySelectorAll('img, video, iframe') : []));
    } catch(e) {
      return;
    }
    nodes.forEach(function(el) {
      if (!el || el.dataset.ykStableTuned) return;
      el.dataset.ykStableTuned = '1';
      var tag = (el.tagName || '').toLowerCase();
      if (tag === 'img') {
        if (!el.getAttribute('loading')) el.setAttribute('loading', 'lazy');
        if (!el.getAttribute('decoding')) el.setAttribute('decoding', 'async');
        if (!el.getAttribute('fetchpriority')) el.setAttribute('fetchpriority', 'low');
        try { el.draggable = false; } catch(e) {}
      } else if (tag === 'video') {
        if (!el.getAttribute('preload') || el.getAttribute('preload') === 'auto') el.setAttribute('preload', 'metadata');
        el.setAttribute('playsinline', '');
      } else if (tag === 'iframe') {
        if (!el.getAttribute('loading')) el.setAttribute('loading', 'lazy');
      }
    });
  }

  function markBusy(el, ms) {
    if (!el || !el.classList) return;
    el.classList.add('yk-click-pending');
    window.setTimeout(function(){ try { el.classList.remove('yk-click-pending'); } catch(e) {} }, ms || 1200);
  }

  document.addEventListener('submit', function(ev) {
    var form = ev.target;
    if (!form || !form.matches || !form.matches('form')) return;
    if ((form.method || '').toLowerCase() !== 'post') return;
    if (form.dataset.ykAllowRepeat === '1') return;
    var now = Date.now();
    var last = parseInt(form.dataset.ykLastSubmit || '0', 10) || 0;
    if (now - last < 1800) {
      ev.preventDefault();
      ev.stopPropagation();
      return false;
    }
    form.dataset.ykLastSubmit = String(now);
    var btn = form.querySelector('button[type="submit"], input[type="submit"]');
    if (btn) markBusy(btn, 1800);
  }, true);

  document.addEventListener('click', function(ev) {
    var target = ev.target && ev.target.closest && ev.target.closest('a[href], button');
    if (!target || target.dataset.ykAllowRepeat === '1') return;
    var now = Date.now();
    var key = (target.getAttribute('href') || target.getAttribute('name') || target.textContent || '').trim();
    if (!key) return;
    var lastKey = target.dataset.ykLastClickKey || '';
    var last = parseInt(target.dataset.ykLastClick || '0', 10) || 0;
    if (lastKey === key && now - last < 650) {
      ev.preventDefault();
      ev.stopPropagation();
      return false;
    }
    target.dataset.ykLastClickKey = key;
    target.dataset.ykLastClick = String(now);
    if (target.tagName && target.tagName.toLowerCase() === 'button') markBusy(target, 800);
  }, true);

  function pauseHiddenMedia() {
    if (!document.hidden) return;
    document.querySelectorAll('video, audio').forEach(function(m) {
      try { m.pause(); } catch(e) {}
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){ tuneNode(document); });
  } else {
    tuneNode(document);
  }
  document.addEventListener('visibilitychange', pauseHiddenMedia);
  window.addEventListener('pagehide', pauseHiddenMedia);
  try {
    var mo = new MutationObserver(function(muts) {
      muts.forEach(function(m) {
        Array.prototype.forEach.call(m.addedNodes || [], function(n) {
          if (n && n.nodeType === 1) tuneNode(n);
        });
      });
    });
    mo.observe(document.documentElement, {childList:true, subtree:true});
  } catch(e) {}
})();
"""

