def _yk_find_pdfs_p(pk, vk=None):
    from pathlib import Path as _P
    out=[]; seen=set()

    def _row_get(row, idx, key=None):
        if row is None:
            return None
        if key:
            try:
                return row[key]
            except Exception:
                pass
        try:
            return row[idx]
        except Exception:
            return None

    def _path_key(path):
        try:
            return str(_P(path).resolve()).lower()
        except Exception:
            return str(path).lower()

    def _add_root(roots, value):
        if not value:
            return
        try:
            root=_P(str(value))
            if root.exists() and root.is_file():
                root=root.parent
            key=_path_key(root)
            if key not in {_path_key(r) for r in roots}:
                roots.append(root)
        except Exception:
            pass

    def _report_roots(pk, vk=None):
        roots=[]
        if vk:
            try:
                with db_conn() as _con:
                    r=_con.execute(
                        "SELECT full_path FROM visits "
                        "WHERE patient_folder_key=? AND visit_key=?",
                        (pk, vk)).fetchone()
                    _add_root(roots, _row_get(r, 0, "full_path"))
            except Exception:
                pass
            try:
                _add_root(roots, get_nas_root() / pk / vk)
            except Exception:
                pass
            try:
                parent_roots=_report_roots(pk, None)
                for parent in parent_roots:
                    _add_root(roots, _P(parent) / vk)
            except Exception:
                pass
            return roots

        try:
            with db_conn() as _con:
                r=_con.execute(
                    "SELECT full_path FROM patients WHERE folder_key=?",
                    (pk,)).fetchone()
                _add_root(roots, _row_get(r, 0, "full_path"))
        except Exception:
            pass
        try:
            _add_root(roots, get_nas_root() / pk)
        except Exception:
            pass
        nas=_yk_os_p.environ.get("YAZKLINIK_NAS_ROOT","")
        if nas:
            _add_root(roots, _P(nas) / pk)
        for k in ("YAZKLINIK_PATIENT_FILES_DIR","YAZKLINIK_MULTIMEDIA_ROOT"):
            v=_yk_os_p.environ.get(k,"")
            if v:
                _add_root(roots, _P(v) / pk)
        return roots

    def _add_pdf(path_value, name=None, db_mt=0):
        if not path_value:
            return
        try:
            p=_P(path_value)
            try:
                rp=p.resolve()
            except Exception:
                rp=p
            if not rp.exists() or not rp.is_file():
                return
            if rp.suffix.lower()!=".pdf":
                return
            key=_path_key(rp)
            if key in seen:
                return
            seen.add(key)
            try:
                st=rp.stat()
                size_kb=int(st.st_size or 0)//1024
                mt=float(st.st_mtime or 0)
            except Exception:
                size_kb=0
                mt=float(db_mt or 0)
            out.append({"name":name or rp.name, "size_kb":size_kb, "abs":str(rp), "mtime":mt})
        except Exception:
            pass

    roots=_report_roots(pk, vk)
    try:
        with db_conn() as _con:
            _ensure_file_archive_schema(_con)
            if vk:
                rows=_con.execute(
                    "SELECT file_name, full_path, mtime, visit_key FROM files "
                    "WHERE patient_folder_key=? AND visit_key=? AND file_kind='pdf' "
                    "AND COALESCE(archived_at, '') = '' "
                    "ORDER BY mtime DESC, file_name", (pk, vk)).fetchall()
            else:
                rows=_con.execute(
                    "SELECT file_name, full_path, mtime, visit_key FROM files "
                    "WHERE patient_folder_key=? AND file_kind='pdf' "
                    "AND COALESCE(archived_at, '') = '' "
                    "ORDER BY mtime DESC, file_name", (pk,)).fetchall()
    except Exception:
        rows=[]

    for row in rows:
        name=_row_get(row, 0, "file_name")
        fp=_row_get(row, 1, "full_path")
        db_mt=_row_get(row, 2, "mtime") or 0
        row_vk=_row_get(row, 3, "visit_key") or vk
        if fp:
            _add_pdf(fp, name=name, db_mt=db_mt)
            continue
        if not name:
            continue
        for root in roots:
            cand=_P(root) / name if vk else _P(root) / str(row_vk or "") / name
            _add_pdf(cand, name=name, db_mt=db_mt)
            if _path_key(cand) in seen:
                break

    for root in roots:
        try:
            d=_P(root)
            if not d.exists() or not d.is_dir():
                continue
            for p in d.rglob("*.pdf"):
                _add_pdf(p)
        except Exception:
            pass
    out.sort(key=lambda x:x.get("mtime",0), reverse=True)
    return out

@app.route("/hasta/<patient_key>/yk-rapor-pdf/<path:pdf_name>")
@app.route("/hasta/<patient_key>/gelis/<visit_key>/yk-rapor-pdf/<path:pdf_name>")
def _yk_rapor_pdf(patient_key,pdf_name,visit_key=None):
    from flask import abort,Response
    for p in _yk_find_pdfs_p(patient_key, visit_key):
        if p["name"]==pdf_name or p["abs"]==pdf_name:
            try:
                with open(p["abs"],"rb") as f: data=f.read()
                return Response(data,mimetype="application/pdf",
                    headers={"Content-Disposition":f'inline; filename="{p["name"]}"',
                            "X-Content-Type-Options":"nosniff"})
            except Exception: abort(500)
    abort(404)

