def _yk_rapor_render(patient_key, visit_key):
    from flask import request as _rq, Response
    from urllib.parse import quote as _q
    from html import escape as _h
    pdfs=_yk_find_pdfs_p(patient_key, visit_key)
    active=_rq.args.get("show","")
    if active and active not in {p["name"] for p in pdfs}:
        active=""
    if not active and pdfs: active=pdfs[0]["name"]
    rows=""
    for p in pdfs:
        cls=" yk-active" if p["name"]==active else ""
        rows+=f'<li class="yk-pdf-item{cls}"><a href="?show={_q(p["name"], safe="")}">PDF - {_h(p["name"])}</a> <small>({p["size_kb"]} KB)</small></li>'
    if not pdfs: rows='<li style="color:#888">PDF bulunamadi</li>'
    base_url = f"/hasta/{patient_key}/gelis/{visit_key}" if visit_key else f"/hasta/{patient_key}"
    rapor_url = f"{base_url}/yk-rapor"
    pdf_serve_base = f"{base_url}/yk-rapor-pdf"
    embed=""
    if active:
        u=f"{pdf_serve_base}/{_q(active, safe='')}"
        print_url = ("/yk-print-media?kind=pdf&src=" + _q(u, safe="")
                     + "&title=" + _q(active, safe=""))
        embed=f'''<div class="yk-pdf-viewer"><div class="yk-pdf-toolbar no-print"><span><b>{_h(active)}</b></span><a href="{print_url}" class="btn btn-primary">A4 Yazdir</a><a href="{rapor_url}" class="btn">Liste</a></div><iframe src="{u}#toolbar=1&view=FitH" id="ykF" name="ykF"></iframe></div>'''
    safe_patient=_h(patient_key)
    html=f'''<!DOCTYPE html><html lang="tr"><head><meta charset="utf-8"><title>Raporlar - {safe_patient}</title><style>
body{{font-family:Segoe UI,sans-serif;padding:18px;max-width:1500px;margin:auto;background:#F5F7FA}}
h1{{font-size:20px;margin:0 0 14px}}
.r{{display:flex;gap:16px;height:calc(100vh - 110px)}}
.l{{flex:0 0 300px;background:#fff;border-radius:12px;padding:12px;box-shadow:0 2px 8px rgba(0,0,0,.06);overflow-y:auto;margin:0;list-style:none}}
.l li{{padding:8px 12px;border-radius:8px;margin-bottom:4px}}
.l li a{{color:#1A1A1A;text-decoration:none;display:block}}
.l li:hover{{background:rgba(0,103,192,.08)}}
.yk-active{{background:rgba(0,103,192,.18);font-weight:600}}
.yk-pdf-viewer{{flex:1;background:#fff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,.06);overflow:hidden;display:flex;flex-direction:column}}
.yk-pdf-toolbar{{display:flex;gap:8px;align-items:center;padding:10px 14px;border-bottom:1px solid #eee;background:#FAFAFA}}
.yk-pdf-toolbar span{{flex:1}}
.btn{{padding:6px 14px;border-radius:8px;border:1px solid #d8dee6;background:#fff;cursor:pointer;font-weight:500;text-decoration:none;color:#1A1A1A}}
.btn-primary{{background:#0067C0;color:#fff;border-color:#0067C0}}
#ykF{{width:100%;flex:1;border:none;background:#525659}}
@media print{{@page{{size:A4;margin:1cm}}body{{background:#fff;padding:0}}.no-print,.l,h1,p{{display:none!important}}.r{{height:auto}}#ykF{{height:100vh}}}}
</style></head><body><h1>Raporlar - {safe_patient}</h1>
<div class="r"><ul class="l">{rows}</ul><div style="flex:1;display:flex">{embed if embed else '<div style="background:#fff;padding:80px;text-align:center;color:#888;border-radius:12px;flex:1">PDF sec</div>'}</div></div>
<p><a href="{base_url}">&laquo; Geri don</a></p></body></html>'''
    return Response(html,mimetype="text/html; charset=utf-8")

@app.after_request
def _yk_inj_rapor_btn(response):
    try:
        if response.direct_passthrough: return response
        ct=(response.content_type or "").split(";")[0].strip().lower()
        if ct!="text/html": return response
        from flask import request as _rq
        import re as _re
        path = _rq.path or ""
        media_fx_routes = (
            path.startswith("/hasta/")
            or path.startswith("/dicom")
            or path.startswith("/yk-rapor")
            or path.startswith("/yk-print-media")
        )
        report_button_route = (
            _re.match(r"^/hasta/([^/]+)/gelis/([^/]+)/?$", path)
            or _re.match(r"^/hasta/([^/]+)/?$", path)
        )
        if not media_fx_routes and not report_button_route:
            return response
        body=response.get_data(as_text=True)
        if "yk-media-fx-css" not in body and "</head>" in body:
            inj = '<link rel="stylesheet" href="/yk-media-fx.css?v=D200-mobile-gallery-nav-v4" id="yk-media-fx-css"><script src="/yk-media-fx.js?v=D200-mobile-gallery-nav-v4" id="yk-media-fx-js" defer></script>'
            body = body.replace("</head>", inj+"</head>", 1)
            response.set_data(body)
            response.headers.pop("Content-Length",None)
        # D200: Raporlar artik hasta/gelis ekranindaki aksiyon bolumunde.
        # Sabit ekranda kalan yuzen balon kullanici akisini bozuyordu.
        return response
    except Exception: pass
    return response
