def _yk_env_truthy(name, default="1"):
    value = os.environ.get(name, default)
    return str(value).strip().lower() not in {"0", "false", "hayir", "hayÄ±r", "no", "off"}


def _yk_https_enabled():
    return _yk_env_truthy("YAZKLINIK_ENABLE_HTTPS", "1")


def _yk_https_port():
    raw = (os.environ.get("YAZKLINIK_HTTPS_PORT") or "").strip()
    if not raw:
        try:
            with db_conn() as con:
                row = con.execute(
                    "SELECT value FROM settings WHERE key=?",
                    ("sysparam_https_port",)).fetchone()
                raw = str(row[0]).strip() if row and row[0] else ""
        except Exception:
            raw = ""
    try:
        return int(raw or "5443")
    except Exception:
        return 5443


def _yk_https_hosts():
    hosts = {"localhost", "127.0.0.1", "::1"}
    extra = os.environ.get("YAZKLINIK_HTTPS_HOSTS", "")
    for part in re.split(r"[,;\s]+", extra):
        token = str(part or "").strip()
        if token:
            hosts.add(token)
    try:
        import ipaddress
        import socket

        hostname = socket.gethostname()
        if hostname:
            hosts.add(hostname)
        fqdn = socket.getfqdn()
        if fqdn:
            hosts.add(fqdn)
        for item in socket.getaddrinfo(hostname, None):
            address = str(item[4][0] or "").strip()
            if not address:
                continue
            try:
                ip = ipaddress.ip_address(address)
            except Exception:
                hosts.add(address)
                continue
            if ip.version == 6 and not ip.is_loopback:
                continue
            if ip.version == 4 and not (
                    ip.is_private
                    or ip.is_loopback
                    or str(ip).startswith("100.")):
                continue
            hosts.add(str(ip))
    except Exception:
        pass
    return sorted(hosts)


def _yk_lan_ipv4_hosts():
    import ipaddress

    lan_ips = []
    seen = set()
    for host in _yk_https_hosts():
        try:
            ip = ipaddress.ip_address(str(host))
        except Exception:
            continue
        if ip.version != 4:
            continue
        text = str(ip)
        if text.startswith("127."):
            continue
        if not (ip.is_private or text.startswith("100.")):
            continue
        if text in seen:
            continue
        seen.add(text)
        lan_ips.append(text)
    return lan_ips


def _yk_required_cert_hosts():
    import ipaddress

    required = {"localhost", "127.0.0.1", "::1"}
    explicit_hosts = set()
    for part in re.split(r"[,;\s]+", os.environ.get("YAZKLINIK_HTTPS_HOSTS", "")):
        token = str(part or "").strip()
        if token:
            explicit_hosts.add(token.lower())
    for host in _yk_https_hosts():
        token = str(host or "").strip()
        if not token:
            continue
        token_key = token.lower()
        try:
            ip = ipaddress.ip_address(token)
        except Exception:
            if re.match(r"^[A-Za-z0-9][A-Za-z0-9._-]*$", token):
                required.add(token_key)
            continue
        if ip.version == 4 and (
                ip.is_private
                or ip.is_loopback
                or str(ip).startswith("100.")
                or token_key in explicit_hosts):
            required.add(str(ip))
        elif ip.version == 6 and ip.is_loopback:
            required.add("::1")
    return required


def _yk_cert_subject_alt_names(cert_path):
    import ipaddress
    import ssl

    decoded = ssl._ssl._test_decode_cert(str(cert_path))
    sans = set()
    for kind, value in (decoded.get("subjectAltName") or []):
        kind_norm = str(kind or "").strip().lower()
        text = str(value or "").strip()
        if not text:
            continue
        if "dns" in kind_norm:
            sans.add(text.lower())
        elif "ip" in kind_norm:
            try:
                sans.add(str(ipaddress.ip_address(text)))
            except Exception:
                sans.add(text)
    return sans


def _yk_https_cert_needs_refresh(cert_path):
    try:
        existing = _yk_cert_subject_alt_names(cert_path)
    except Exception:
        return True
    required = _yk_required_cert_hosts()
    for host in required:
        if host not in existing:
            return True
    return False


def _yk_generate_self_signed_cert(cert_path, key_path):
    from cryptography import x509
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.asymmetric import rsa
    from cryptography.x509.oid import NameOID
    import ipaddress

    key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    subject = issuer = x509.Name([
        x509.NameAttribute(NameOID.COUNTRY_NAME, "TR"),
        x509.NameAttribute(NameOID.ORGANIZATION_NAME, "YazKlinik Local"),
        x509.NameAttribute(NameOID.COMMON_NAME, "YazKlinik HTTPS"),
    ])
    san_items = []
    for host in _yk_https_hosts():
        try:
            san_items.append(x509.IPAddress(ipaddress.ip_address(host)))
        except Exception:
            san_items.append(x509.DNSName(host))
    cert = (
        x509.CertificateBuilder()
        .subject_name(subject)
        .issuer_name(issuer)
        .public_key(key.public_key())
        .serial_number(x509.random_serial_number())
        .not_valid_before(datetime.utcnow() - timedelta(days=1))
        .not_valid_after(datetime.utcnow() + timedelta(days=3650))
        .add_extension(x509.SubjectAlternativeName(san_items), critical=False)
        .sign(key, hashes.SHA256())
    )
    key_path.write_bytes(
        key.private_bytes(
            serialization.Encoding.PEM,
            serialization.PrivateFormat.TraditionalOpenSSL,
            serialization.NoEncryption(),
        )
    )
    cert_path.write_bytes(cert.public_bytes(serialization.Encoding.PEM))


def _yk_https_cert_files(force_regenerate=False):
    cert_dir = Path(os.environ.get("YAZKLINIK_CERT_DIR") or Path(__file__).resolve().parent / "certs")
    cert_dir.mkdir(parents=True, exist_ok=True)
    cert_path = cert_dir / "yazklinik_https.crt"
    key_path = cert_dir / "yazklinik_https.key"
    should_regenerate = bool(force_regenerate)
    if not cert_path.exists() or not key_path.exists():
        should_regenerate = True
    elif _yk_https_cert_needs_refresh(cert_path):
        should_regenerate = True
    if should_regenerate:
        try:
            if cert_path.exists():
                cert_path.unlink()
        except Exception:
            pass
        try:
            if key_path.exists():
                key_path.unlink()
        except Exception:
            pass
        _yk_generate_self_signed_cert(cert_path, key_path)
    return cert_path, key_path


def _yk_start_https_listener(port):
    try:
        from werkzeug.serving import make_server

        cert_path, key_path = _yk_https_cert_files()
        server = make_server(
            "0.0.0.0",
            int(port),
            app,
            threaded=True,
            ssl_context=(str(cert_path), str(key_path)),
        )
        thread = threading.Thread(
            target=server.serve_forever,
            name=f"YazKlinikHTTPS:{port}",
            daemon=True,
        )
        thread.start()
        print(f"  HTTPS listener aktif: https://0.0.0.0:{port}")
        print(f"  Sertifika: {cert_path}")
        return True
    except Exception as ex:
        print(f"  HTTPS baslatilamadi (ilk deneme): {ex}")
        try:
            from werkzeug.serving import make_server

            cert_path, key_path = _yk_https_cert_files(force_regenerate=True)
            server = make_server(
                "0.0.0.0",
                int(port),
                app,
                threaded=True,
                ssl_context=(str(cert_path), str(key_path)),
            )
            thread = threading.Thread(
                target=server.serve_forever,
                name=f"YazKlinikHTTPS:{port}",
                daemon=True,
            )
            thread.start()
            print(f"  HTTPS listener aktif (yeniden sertifika): https://0.0.0.0:{port}")
            print(f"  Sertifika: {cert_path}")
            return True
        except Exception as retry_ex:
            print(f"  HTTPS baslatilamadi: {retry_ex}")
            return False


def _yk_serve_https_forever(port):
    try:
        from werkzeug.serving import make_server

        cert_path, key_path = _yk_https_cert_files()
        server = make_server(
            "0.0.0.0",
            int(port),
            app,
            threaded=True,
            ssl_context=(str(cert_path), str(key_path)),
        )
        print(f"  HTTPS tek port aktif: https://0.0.0.0:{port}")
        print(f"  Sertifika: {cert_path}")
        server.serve_forever()
        return True
    except Exception as ex:
        print(f"  HTTPS tek port baslatilamadi (ilk deneme): {ex}")
        try:
            from werkzeug.serving import make_server

            cert_path, key_path = _yk_https_cert_files(force_regenerate=True)
            server = make_server(
                "0.0.0.0",
                int(port),
                app,
                threaded=True,
                ssl_context=(str(cert_path), str(key_path)),
            )
            print(f"  HTTPS tek port aktif (yeniden sertifika): https://0.0.0.0:{port}")
            print(f"  Sertifika: {cert_path}")
            server.serve_forever()
            return True
        except Exception as retry_ex:
            print(f"  HTTPS tek port baslatilamadi: {retry_ex}")
            return False


def _yk_normalize_host_token(value):
    token = str(value or "").strip().lower()
    if token.startswith("[") and "]" in token:
        token = token[1:token.find("]")]
    if token.startswith("::ffff:"):
        token = token.split(":")[-1]
    if ":" in token and token.count(":") == 1:
        token = token.split(":", 1)[0]
    return token


def _yk_host_is_loopback(value):
    token = _yk_normalize_host_token(value)
    if token in {"localhost", "127.0.0.1", "::1"}:
        return True
    try:
        import ipaddress
        return bool(ipaddress.ip_address(token).is_loopback)
    except Exception:
        return False


def _yk_local_host_tokens():
    hosts = set()
    for item in _yk_https_hosts():
        token = _yk_normalize_host_token(item)
        if token:
            hosts.add(token)
    try:
        import socket
        hostname = socket.gethostname()
        for item in socket.getaddrinfo(hostname, None):
            token = _yk_normalize_host_token(item[4][0])
            if token:
                hosts.add(token)
    except Exception:
        pass
    hosts.update({"localhost", "127.0.0.1", "::1"})
    return hosts


def _yk_current_web_port():
    try:
        env_port = int(os.environ.get("YAZKLINIK_WEB_PORT") or 5443)
        if env_port > 0:
            return env_port
    except Exception:
        pass
    try:
        host_url = urlsplit("http://" + str(request.host or ""))
        if host_url.port:
            return int(host_url.port)
    except Exception:
        pass
    return 5443


def _yk_clean_mic_path(value):
    path = str(value or "").strip()
    if not path or path.startswith("http://") or path.startswith("https://"):
        path = str(request.full_path or request.path or "/")
    if not path.startswith("/"):
        path = "/" + path.lstrip("/")
    if path.endswith("?"):
        path = path[:-1]
    return path or "/"


def _yk_web_mic_context(path=None):
    request_host = _yk_normalize_host_token((request.host or "").split(":", 1)[0])
    if not request_host:
        request_host = "127.0.0.1"
    remote_host = _yk_normalize_host_token(request.remote_addr)
    current_path = _yk_clean_mic_path(path)
    https_port = _yk_https_port()
    web_port = _yk_current_web_port()
    local_scheme = (
        "https"
        if _yk_https_enabled() and int(https_port or 0) == int(web_port or 0)
        else "http"
    )
    scheme = (
        request.headers.get("X-Forwarded-Proto")
        or request.headers.get("X-Scheme")
        or request.scheme
        or "http"
    ).split(",", 1)[0].strip().lower()
    is_loopback = _yk_host_is_loopback(request_host)
    is_secure_request = scheme == "https" or is_loopback
    local_hosts = _yk_local_host_tokens()
    server_native_safe = (
        is_loopback
        or _yk_host_is_loopback(remote_host)
        or (remote_host in local_hosts if remote_host else False)
    )
    return {
        "ok": True,
        "secure": bool(is_secure_request),
        "https_enabled": _yk_https_enabled(),
        "https_port": https_port,
        "web_port": web_port,
        "host": request_host,
        "remote_addr": remote_host,
        "is_loopback": bool(is_loopback),
        "server_native_safe": bool(server_native_safe),
        "browser_mic_ready": bool(is_secure_request),
        "public_base_url": _yk_public_base_url(),
        "https_url": _yk_public_url(current_path),
        "loopback_url": f"{local_scheme}://127.0.0.1:{web_port}{current_path}",
        "localhost_url": f"{local_scheme}://localhost:{web_port}{current_path}",
        "message": (
            "Tarayici mikrofonu hazir."
            if is_secure_request else
            "Web mikrofon icin localhost veya HTTPS gerekir."
        ),
    }


@app.route("/api/https-info")
@login_required
def api_https_info():
    host = (request.host or "").split(":")[0] or "127.0.0.1"
    port = _yk_https_port()
    return jsonify({
        "ok": True,
        "enabled": _yk_https_enabled(),
        "https_port": port,
        "current_host": request.host,
        "public_base_url": _yk_public_base_url(),
        "recommended_url": _yk_public_url("/giris"),
        "legacy_recommended_url": f"https://{host}:{port}/giris",
        "hosts_in_certificate": _yk_https_hosts(),
    })


@app.route("/api/web-mic/context")
@login_required
def api_web_mic_context():
    return jsonify(_yk_web_mic_context(request.args.get("path") or ""))


def _yk_post_boot_tasks():
    """Acilis performansi icin agir/gerekli olmayan kontrol ve watcher'lar."""
    print("  Hizli acilis modu aktif: agir preflight adimlari arka planda baslatilacak.")

    try:
        from yazklinik_runtime_cleanup import run_startup_cleanup
        cleanup = run_startup_cleanup(version=APP_VERSION)
        if cleanup.get("removed_count"):
            print(f"  Eski gecici artiklar temizlendi: {cleanup.get('removed_count')}")
        if cleanup.get("errors"):
            print(f"  Uyari: temizlenemeyen artik sayisi: {len(cleanup.get('errors') or [])}")
    except Exception as _cleanup_ex:
        print(f"  Uyari: acilis temizligi calismadi: {_cleanup_ex}")

    try:
        from yazklinik_updater import is_setup_complete, load_install_config
        if is_setup_complete():
            cfg = load_install_config()
            print(f"  Kurulum: {cfg.get('install_dir')}")
            print(f"  Versiyon: {APP_VERSION}")
            print(f"  Veri: {cfg.get('data_dir')}")
        else:
            print("  ILK KURULUM YAPILMADI!")
            print("  Giris yaptiktan sonra:")
            print("  http://localhost:5000/kurulum-sihirbazi")
    except ImportError:
        print("  yazklinik_updater modulu yok")
    except Exception as _setup_ex:
        print(f"  Setup kontrol uyarisi: {_setup_ex}")

    try:
        _refresh_ai_config()
        print(f"  Ollama: {_AI_CONFIG['url']}")
        print(f"  Model:  {_AI_CONFIG['model']}")
    except Exception as _ai_ex:
        print(f"  Ayar yukleme: {_ai_ex}")

    # NAS watcher bazi aglarda bloklayabildigi icin server ayaga kalktiktan
    # sonra baslatilir.
    try:
        from yazklinik_common import is_integration_enabled, get_integration_config
        if is_integration_enabled("usg_nas"):
            cfg = get_integration_config("usg_nas")
            watch_folder = cfg.get("watch_folder", "")
            if watch_folder:
                try:
                    import yazklinik_nas_watcher
                    ok = yazklinik_nas_watcher.start_nas_watcher(
                        watch_folder=watch_folder,
                        db_conn_func=db_conn,
                        data_root=(cfg.get("data_root") or str(
                            default_patient_data_root(watch_folder))),
                        accepted_prefix=cfg.get("accepted_prefix", "F137230"))
                    if ok:
                        print(f"  NAS USG izleyici: {watch_folder}")
                except Exception as _nas_ex:
                    print(f"  NAS izleyici baslatilamadi: {_nas_ex}")
    except Exception:
        pass


def _yk_start_post_boot_tasks():
    def _runner():
        try:
            delay = _yk_env_float("YAZKLINIK_POST_BOOT_DELAY_SEC", 25.0)
            time.sleep(max(5.0, delay))
        except Exception:
            pass
        _yk_post_boot_tasks()

    t = threading.Thread(target=_runner, name="YKPostBoot", daemon=True)
    t.start()


